window.DB_CONTENT = {"fixtures":{"company":"-- SQLite teaching fixture: explicit NOT NULL on text/composite primary keys.\nPRAGMA foreign_keys = ON;\nCREATE TABLE DEPARTMENT (\n Dname TEXT NOT NULL UNIQUE, Dnumber INTEGER PRIMARY KEY,\n Mgr_ssn TEXT UNIQUE, Mgr_start_date TEXT,\n FOREIGN KEY (Mgr_ssn) REFERENCES EMPLOYEE(Ssn) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE TABLE EMPLOYEE (\n Fname TEXT NOT NULL, Minit TEXT, Lname TEXT NOT NULL,\n Ssn TEXT NOT NULL PRIMARY KEY, Bdate TEXT, Address TEXT, Sex TEXT,\n Salary REAL CHECK (Salary >= 0), Super_ssn TEXT, Dno INTEGER NOT NULL,\n FOREIGN KEY (Super_ssn) REFERENCES EMPLOYEE(Ssn) DEFERRABLE INITIALLY DEFERRED,\n FOREIGN KEY (Dno) REFERENCES DEPARTMENT(Dnumber) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE TABLE DEPT_LOCATIONS (\n Dnumber INTEGER NOT NULL, Dlocation TEXT NOT NULL,\n PRIMARY KEY (Dnumber, Dlocation),\n FOREIGN KEY (Dnumber) REFERENCES DEPARTMENT(Dnumber) ON DELETE CASCADE\n);\nCREATE TABLE PROJECT (\n Pname TEXT NOT NULL UNIQUE, Pnumber INTEGER PRIMARY KEY,\n Plocation TEXT, Dnum INTEGER NOT NULL,\n FOREIGN KEY (Dnum) REFERENCES DEPARTMENT(Dnumber)\n);\nCREATE TABLE WORKS_ON (\n Essn TEXT NOT NULL, Pno INTEGER NOT NULL,\n Hours REAL CHECK (Hours >= 0 AND Hours <= 168),\n PRIMARY KEY (Essn, Pno),\n FOREIGN KEY (Essn) REFERENCES EMPLOYEE(Ssn) ON DELETE CASCADE,\n FOREIGN KEY (Pno) REFERENCES PROJECT(Pnumber) ON DELETE CASCADE\n);\nCREATE TABLE DEPENDENT (\n Essn TEXT NOT NULL, Dependent_name TEXT NOT NULL,\n Sex TEXT, Bdate TEXT, Relationship TEXT,\n PRIMARY KEY (Essn, Dependent_name),\n FOREIGN KEY (Essn) REFERENCES EMPLOYEE(Ssn) ON DELETE CASCADE\n);\n\n-- Familiar COMPANY names; synthetic teaching fixture, not an official answer key.\n-- Added: Mai (unknown salary, no assignment); Innovation (empty department).\nBEGIN;\nINSERT INTO DEPARTMENT VALUES\n ('Research',5,'333445555','1988-05-22'),\n ('Administration',4,'987654321','1995-01-01'),\n ('Headquarters',1,'888665555','1981-06-19'),\n ('Innovation',9,NULL,NULL);\nINSERT INTO EMPLOYEE VALUES\n ('John','B','Smith','123456789','1965-01-09','Houston','M',30000,'333445555',5),\n ('Franklin','T','Wong','333445555','1955-12-08','Houston','M',40000,'888665555',5),\n ('Alicia','J','Zelaya','999887777','1968-01-19','Spring','F',25000,'987654321',4),\n ('Jennifer','S','Wallace','987654321','1941-06-20','Bellaire','F',43000,'888665555',4),\n ('Ramesh','K','Narayan','666884444','1962-09-15','Humble','M',38000,'333445555',5),\n ('Joyce','A','English','453453453','1972-07-31','Houston','F',25000,'333445555',5),\n ('Ahmad','V','Jabbar','987987987','1969-03-29','Houston','M',25000,'987654321',4),\n ('James','E','Borg','888665555','1937-11-10','Houston','M',55000,NULL,1),\n ('Mai',NULL,'Nguyen','111222333','2000-01-01','HCMC','F',NULL,'987654321',4);\nINSERT INTO DEPT_LOCATIONS VALUES (1,'Houston'),(4,'Stafford'),(5,'Bellaire'),(5,'Sugarland'),(5,'Houston');\nINSERT INTO PROJECT VALUES\n ('ProductX',1,'Bellaire',5),('ProductY',2,'Sugarland',5),('ProductZ',3,'Houston',5),\n ('Computerization',10,'Stafford',4),('Reorganization',20,'Houston',1),('Newbenefits',30,'Stafford',4);\nINSERT INTO WORKS_ON VALUES\n ('123456789',1,32.5),('123456789',2,7.5),('333445555',2,10),('333445555',3,10),\n ('333445555',10,10),('333445555',20,10),('999887777',30,30),('999887777',10,10),\n ('987654321',30,20),('987654321',20,15),('666884444',3,40),\n ('453453453',1,20),('453453453',2,20),('987987987',10,35),('987987987',30,5),\n ('888665555',20,NULL);\nINSERT INTO DEPENDENT VALUES\n ('333445555','Alice','F','1986-04-05','Daughter'),('333445555','Theodore','M','1983-10-25','Son'),\n ('333445555','Joy','F','1958-05-03','Spouse'),('987654321','Abner','M','1942-02-28','Spouse'),\n ('123456789','Michael','M','1988-01-04','Son'),('123456789','Alice','F','1988-12-30','Daughter'),\n ('123456789','Elizabeth','F','1967-05-05','Spouse');\nCOMMIT;\n","anime":"PRAGMA foreign_keys = ON;\nCREATE TABLE account (\n account_id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE,\n email TEXT NOT NULL UNIQUE\n);\n-- Overlapping specialization: one account can appear in BOTH child tables.\n-- PK/FK alone does not guarantee TOTAL specialization.\nCREATE TABLE viewer (account_id INTEGER PRIMARY KEY REFERENCES account(account_id));\nCREATE TABLE content_admin (\n account_id INTEGER PRIMARY KEY REFERENCES account(account_id), department TEXT NOT NULL\n);\nCREATE TABLE anime (\n anime_id INTEGER PRIMARY KEY, title TEXT NOT NULL,\n release_year INTEGER CHECK(release_year BETWEEN 1900 AND 2200)\n);\nCREATE TABLE genre (genre_id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);\nCREATE TABLE anime_genre (\n anime_id INTEGER NOT NULL REFERENCES anime(anime_id) ON DELETE CASCADE,\n genre_id INTEGER NOT NULL REFERENCES genre(genre_id), PRIMARY KEY(anime_id,genre_id)\n);\nCREATE TABLE studio (studio_id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);\nCREATE TABLE produced_by (\n anime_id INTEGER NOT NULL REFERENCES anime(anime_id) ON DELETE CASCADE,\n studio_id INTEGER NOT NULL REFERENCES studio(studio_id), PRIMARY KEY(anime_id,studio_id)\n);\nCREATE TABLE episode (\n anime_id INTEGER NOT NULL REFERENCES anime(anime_id) ON DELETE CASCADE,\n episode_no INTEGER NOT NULL CHECK(episode_no>0), title TEXT NOT NULL,\n duration_sec INTEGER NOT NULL CHECK(duration_sec>0), PRIMARY KEY(anime_id,episode_no)\n);\nCREATE TABLE watch_list (\n list_id INTEGER PRIMARY KEY, viewer_id INTEGER NOT NULL REFERENCES viewer(account_id),\n name TEXT NOT NULL, UNIQUE(viewer_id,name)\n);\nCREATE TABLE contains (\n list_id INTEGER NOT NULL REFERENCES watch_list(list_id) ON DELETE CASCADE,\n anime_id INTEGER NOT NULL REFERENCES anime(anime_id) ON DELETE CASCADE,\n added_at TEXT NOT NULL, PRIMARY KEY(list_id,anime_id)\n);\nCREATE TABLE rating (\n viewer_id INTEGER NOT NULL REFERENCES viewer(account_id),\n anime_id INTEGER NOT NULL REFERENCES anime(anime_id),\n score INTEGER NOT NULL CHECK(score BETWEEN 1 AND 10), PRIMARY KEY(viewer_id,anime_id)\n);\n\nBEGIN;\nINSERT INTO account VALUES (1,'an','an@example.test'),(2,'binh','binh@example.test'),(3,'chi','chi@example.test');\nINSERT INTO viewer VALUES(1),(2),(3);\nINSERT INTO content_admin VALUES(3,'Content');\nINSERT INTO anime VALUES(1,'Sky Academy',2024),(2,'Quiet Garden',2025),(3,'Orbit City',2026),(4,'Paper Moon',2023);\nINSERT INTO genre VALUES(1,'Action'),(2,'Slice of life'),(3,'Sci-Fi');\nINSERT INTO anime_genre VALUES(1,1),(1,3),(2,2),(3,1),(3,3),(4,2);\nINSERT INTO studio VALUES(1,'North Studio'),(2,'River Works');\nINSERT INTO produced_by VALUES(1,1),(1,2),(2,2),(3,1),(4,2);\nINSERT INTO episode VALUES(1,1,'Arrival',1440),(1,2,'First test',1440),(2,1,'Seeds',1320),(3,1,'Launch',1500),(4,1,'Letter',1200);\nINSERT INTO watch_list VALUES(1,1,'Weekend'),(2,2,'Favorites');\nINSERT INTO contains VALUES(1,1,'2026-10-01'),(1,2,'2026-10-02'),(2,1,'2026-10-03'),(2,3,'2026-10-04');\nINSERT INTO rating VALUES(1,1,9),(2,1,8),(3,1,10),(1,2,8),(2,3,9);\nCOMMIT;\n"},"pages":[{"id":"c1-00","group":"c1","kind":"source","title":"Chương 1: Khái niệm và Kiến trúc Hệ Cơ Sở Dữ Liệu — *Database System Concepts and Architecture*","markdown":"# Chương 1: Khái niệm và Kiến trúc Hệ Cơ Sở Dữ Liệu — *Database System Concepts and Architecture*\n\n> **Nguồn**: CO2013 Database Systems, HCMUT — Khoa KH&KT Máy tính\n> **Giảng viên phụ trách**: TS. Trần Minh Quang\n> **Giáo trình**: Elmasri & Navathe, *Fundamentals of Database Systems*, 7th Edition (Chương 1, 2 phần đầu)\n> **File PDF gốc**: `Lectures/01_Database System Concepts and Architecture.pdf`\n> **Số slide trong PDF gốc**: **42 slide** (slide 1 = title, slide 41 = Summary, slide 42 = Q & A)\n> **Slide \"Outline\" lặp lại**: slide **2, 3, 22, 31, 34, 38** (6 slide) — đã gộp thành **một** mục lục duy nhất ở §0.4.\n> **Slide có diagram/ảnh**: slide **5, 6, 8, 12, 17, 20, 21, 24, 27, 30, 37, 39** — đã tái tạo bằng Mermaid hoặc ASCII art.\n>\n> **Mục tiêu của tài liệu này**: một sinh viên năm 2 ngành CNTT, **chưa từng học CSDL**, đọc một mạch là đủ hiểu chương 1, **không cần mở slide gốc**, không cần đọc Elmasri.\n\n---\n\n","file":"materials/DB-Chapter1.md","section":0},{"id":"c1-01","group":"c1","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nChương 1 là chương \"vào bài\" — hầu như **không yêu cầu kiến thức CSDL trước đó**. Tuy nhiên bạn nên có vài khái niệm sau (lấy từ môn Lập trình cơ bản và HĐH):\n\n| Khái niệm nền | Giải thích siêu ngắn (đủ để bắt nhịp) |\n|---|---|\n| **File (tập tin)** | Nơi lưu dữ liệu trên máy tính, ví dụ `.txt`, `.csv`, `.dat`, file Excel. Trước khi có DBMS, ứng dụng tự đọc/ghi file này. Mỗi file là 1 dãy byte, có \"đường dẫn\" và \"định dạng\" riêng. |\n| **Struct / Class** (C/C++/Python) | Bạn đã từng khai báo `struct Student { int id; char name[50]; }`. Đây là cách \"khai báo cấu trúc\" trong code; chương 1 sẽ thấy ý tưởng tương tự cho dữ liệu trên đĩa. |\n| **Application Program (chương trình ứng dụng)** | Phần mềm xử lý dữ liệu: nhập liệu, in báo cáo, tính lương, tính điểm. |\n| **Data (dữ liệu)** | Sự kiện có thể ghi lại được, ví dụ MSSV, lương, ngày sinh, mã phòng ban. |\n| **Mảng/Bản ghi (record)** | Một bảng gồm nhiều hàng; mỗi hàng là 1 record, mỗi cột là 1 field. |\n| **User (người dùng)** | Người hoặc hệ thống cần đọc/ghi/sửa/tìm dữ liệu — có thể là nhân viên, quản trị viên, lập trình viên, hoặc một hệ thống khác. |\n\n> 💡 **Hiểu đơn giản:** Chương 1 trả lời 2 câu hỏi gốc:\n> 1. *Vì sao không nên dùng file Excel/text để quản lý dữ liệu công ty?*\n> 2. *Hệ CSDL khác file Excel ở chỗ nào về kiến trúc?*\n>\n> Mọi khái niệm sau đó (DBMS, schema, view, data independence, …) đều mọc ra từ 2 câu hỏi này.\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\nTrích từ đề cương CO2013 (mục L.O.1) — sau chương này bạn cần:\n\n1. **Phân biệt** *File-based Approach* và *Database Approach* qua ≥ 4 tiêu chí.\n2. **Giải thích** được các vấn đề của file-based: *Data Redundancy, Data Inconsistency, Rigid data structure, Physical data dependency, No Concurrency Control*.\n3. **Định nghĩa** chuẩn xác: *Data, Database, Metadata, DBMS, Database System*.\n4. **Nhận biết** các thành phần chính của DBMS qua sơ đồ slide 17.\n5. **Vẽ và giải thích** *Three-Schema Architecture* (External / Conceptual / Internal).\n6. **Phân biệt** *Logical Data Independence* vs *Physical Data Independence* và cho ví dụ mỗi loại.\n7. **Phân biệt** DDL / DML / DCL; *Procedural* vs *Non-Procedural DML*; *4GLs*.\n8. **Phân biệt** *Data Model*, *Database Schema*, *Schema Diagram*, *Database State/Snapshot*.\n9. **Nhìn được bức tranh tổng quan** *Data Management Systems Framework* và các hướng mở rộng DBMS hiện đại.\n\n### 0.3. Lộ trình đọc đề xuất\n\n| TT | Phần | Mức độ | Thời gian | Ghi chú |\n|---:|---|---|---:|---|\n| 1 | §1 File-based vs Database Approach | **CORE** | 45–60 phút | Hay ra trắc nghiệm + tự luận so sánh. |\n| 2 | §2 Three-Schema Architecture & Data Independence | **CORE** | 50–60 phút | **Khó nhất chương** — cần đọc kỹ analogy. |\n| 3 | §3 Database Languages | **CORE** | 20–25 phút | Ngắn, dễ. Nền cho Chương 6 (SQL). |\n| 4 | §4 Data Models, Schema, State | **CORE** | 25–30 phút | Phân biệt 3 khái niệm dễ nhầm. |\n| 5 | §5 Data Management Systems Framework | **NÂNG CAO** | 15 phút | Đọc lướt khi học lần đầu, quay lại sau. |\n\n**Tổng:** ~150 phút đọc lần đầu, ~40 phút ôn lại trước thi.\n\n### 0.4. Outline chương (gộp 6 slide Outline lặp lại)\n\nSlide 2, 3, 22, 31, 34, 38 đều lặp cùng outline (chỉ highlight section sắp vào). Đã gộp:\n\n> **Outline**\n> 1. File-based Approach and Database Approach\n> 2. Three-Schema Architecture and Data Independence\n> 3. Database Languages\n> 4. Data Models, Database Schema, Database State\n> 5. Data Management Systems Framework\n\n---\n\n","file":"materials/DB-Chapter1.md","section":1},{"id":"c1-02","group":"c1","kind":"source","title":"1. File-based Approach và Database Approach","markdown":"## 1. File-based Approach và Database Approach\n\n### 1.1. Tại sao có concept này? (Motivation)\n\nTrước khi có DBMS, cách \"tự nhiên\" để lưu dữ liệu là: mỗi ứng dụng tự tạo file riêng, tự định nghĩa cấu trúc trong code, tự đọc/ghi. Phòng Sales có file khách riêng, phòng Contracts cũng có file khách riêng. Cách này dễ làm khi nhỏ — nhưng khi tổ chức lớn, dữ liệu bị **lặp**, **lệch phiên bản**, **khó sửa cấu trúc**, **khó cho nhiều người dùng cùng lúc**. Database Approach ra đời để **tách dữ liệu khỏi chương trình** và đặt dữ liệu dưới sự quản lý tập trung của DBMS.\n\n> 💡 **Hiểu đơn giản:** File-based Approach giống mỗi phòng ban tự giữ một cuốn sổ Excel riêng. Database Approach giống cả công ty dùng một hệ thống chung, có người quản trị, có luật kiểm tra, có quyền truy cập, có cách chống sửa đụng nhau.\n\n### 1.2. Slide 4 — File-based Approach: định nghĩa\n\n**Nội dung slide gốc** (đầy đủ 2 bullet):\n\n- *Data is stored in one or more separate computer files.*\n  → Dữ liệu được lưu trong một hoặc nhiều file riêng biệt.\n- *Data is then processed by computer programs - applications.*\n  → Dữ liệu được xử lý bởi các chương trình ứng dụng.\n\n**Đặc trưng ngầm chứa trong 2 bullet này** (cực quan trọng): mỗi application **tự định nghĩa cấu trúc file riêng**, định nghĩa đó **bị đóng cứng trong code chương trình** (xem slide 5).\n\n| Thuật ngữ (EN) | Tiếng Việt | Định nghĩa đầy đủ |\n|---|---|---|\n| File-based Approach | Cách tiếp cận dựa trên tập tin | Cách tổ chức trong đó dữ liệu lưu trong các file máy tính riêng biệt; chương trình ứng dụng tự đọc, ghi, xử lý các file này. |\n| Computer file | Tập tin máy tính | Đơn vị lưu trữ trên hệ thống file (text, binary, CSV, Excel, …). |\n| Application program | Chương trình ứng dụng | Phần mềm xử lý dữ liệu cho một nghiệp vụ cụ thể. |\n\n### 1.3. Slide 5 — Diagram File-based: Sales vs Contracts (DreamHome)\n\n> 📊 **Hình 1.1 — File-based Approach (slide 5):**\n> ```mermaid\n> flowchart LR\n>   Sales[Sales user] <--> SalesApp[Sales application programs<br/>• Data entry & reports<br/>• File handling routines<br/>• File definition]\n>   SalesApp <--> SalesFiles[(Sales files)]\n>   Contracts[Contracts user] <--> ContractsApp[Contracts application programs<br/>• Data entry & reports<br/>• File handling routines<br/>• File definition]\n>   ContractsApp <--> ContractsFiles[(Contracts files)]\n> ```\n\n**Sales Files schema** (slide ghi rõ):\n\n| File | Thuộc tính trong file |\n|---|---|\n| `PropertyForRent` | `propertyNo, street, city, postcode, type, rooms, rent, ownerNo` |\n| `PrivateOwner` | `ownerNo, fName, lName, address, telNo` |\n| `Client` | `clientNo, fName, lName, address, telNo, prefType, maxRent` |\n\n**Contracts Files schema**:\n\n| File | Thuộc tính trong file |\n|---|---|\n| `Lease` | `leaseNo, propertyNo, clientNo, rent, paymentMethod, deposit, paid, rentStart, rentFinish, duration` |\n| `PropertyForRent` | `propertyNo, street, city, postcode, rent` |\n| `Client` | `clientNo, fName, lName, address, telNo` |\n\n> 📊 **Đọc diagram này thế nào:**\n> - Hai nhóm user (Sales & Contracts) có **chương trình riêng**, **file riêng**.\n> - Trong mỗi app, \"File definition\" (cấu trúc file) **nằm chung khối với code** — không tách ra catalog.\n> - **Đáng chú ý:** schema `Client` và `PropertyForRent` xuất hiện ở **cả 2 nhóm** với **thuộc tính khác nhau**:\n>   - `Client` ở Sales có thêm `prefType, maxRent`; ở Contracts thì không.\n>   - `PropertyForRent` ở Sales có `type, rooms, ownerNo`; ở Contracts chỉ giữ `propertyNo, street, city, postcode, rent`.\n> - Đây là minh họa trực quan cho **Data Redundancy** + **Data Inconsistency** mà slide 7 sẽ đặt tên chính thức.\n\n### 1.4. Slide 6 — File-based với 4 application\n\n> 📊 **Hình 1.2 — File-based với 4 application (slide 6):**\n> ```mermaid\n> flowchart LR\n>   CO[Customer Orders] --> CF1[Customer File]\n>   CO --> SF1[Stock File]\n>   CO --> OF1[Order File]\n>   CI[Customer Invoicing] --> CF2[Customer File]\n>   CI --> SF2[Stock File]\n>   CI --> OF2[Order File]\n>   PO[Purchase Orders] --> SF3[Stock File]\n>   PO --> SupF[Supplier File]\n>   SC[Stock Control] --> SF4[Stock File]\n>   SC --> OF3[Order File]\n> ```\n\n**Phân tích từng application:**\n\n| Application | File được dùng | Ý nghĩa nghiệp vụ |\n|---|---|---|\n| Customer Orders | Customer File, Stock File, Order File | Nhận đơn hàng — biết khách là ai, hàng còn không, lưu đơn |\n| Customer Invoicing | Customer File, Stock File, Order File | Xuất hóa đơn — cần thông tin khách + hàng + đơn |\n| Purchase Orders | Stock File, Supplier File | Đặt hàng nhập kho |\n| Stock Control | Stock File, Order File | Kiểm soát tồn kho |\n\n> 📊 **Đọc diagram này thế nào:** `Customer File` xuất hiện ở 2 chỗ; `Stock File` xuất hiện ở 4 chỗ; `Order File` xuất hiện ở 3 chỗ. Mỗi app **giữ một bản copy riêng** → 1 customer đổi địa chỉ → phải vào 2 app sửa. Quên 1 chỗ = dữ liệu mâu thuẫn.\n\n### 1.5. Slide 7 — Problems / Limitations\n\n**Nội dung slide gốc:**\n\n- File-based Approach\n  - Problems / Limitations\n    - **Data Redundancy** (dư thừa dữ liệu)\n    - **Data Inconsistency** (không nhất quán dữ liệu)\n    - More details: see [2]\n\n| Thuật ngữ (EN) | Tiếng Việt | Định nghĩa |\n|---|---|---|\n| Data Redundancy | Dư thừa dữ liệu | Cùng một dữ liệu (hoặc tương đương) bị lưu lặp lại ở nhiều nơi. |\n| Data Inconsistency | Không nhất quán dữ liệu | Các bản sao của cùng dữ liệu lệch nhau — không khớp. |\n\n> 💡 **Hiểu đơn giản:** Redundancy giống bạn ghi cùng số điện thoại của bạn vào danh bạ Zalo, danh bạ máy, sổ tay, file Excel. Khi đổi số, bạn quên cập nhật sổ tay → hôm sau tra sổ tay gọi sai. Inconsistency là cái \"gọi sai\" đó.\n\n> 💡 **Ví dụ với COMPANY:** Phòng nhân sự lưu nhân viên `Ssn=123456789` thuộc `Dno=5`. Phòng dự án lại lưu nhân viên đó thuộc `Dno=4`. Khi thống kê nhân viên mỗi phòng → kết quả sai.\n\n### 1.6. Slide 8 — Diagram so sánh File-based vs Shared File\n\n> 📊 **Hình 1.3a — File-based truyền thống (mỗi app file riêng):**\n> ```mermaid\n> flowchart LR\n>   CO1[Customer Orders] --> CF1[Customer File]\n>   CO1 --> SF1[Stock File]\n>   CO1 --> OF1[Order File]\n>   CI1[Customer Invoicing] --> CF2[Customer File]\n>   CI1 --> SF2[Stock File]\n>   CI1 --> OF2[Order File]\n>   PO1[Purchase Orders] --> SF3[Stock File]\n>   PO1 --> SupF1[Supplier File]\n>   SC1[Stock Control] --> SF4[Stock File]\n>   SC1 --> OF3[Order File]\n> ```\n\n> 📊 **Hình 1.3b — Shared File Approach (file dùng chung):**\n> ```mermaid\n> flowchart LR\n>   CO2[Customer Orders] --> CF[Customer File]\n>   CO2 --> SF[Stock File]\n>   CO2 --> OF[Order File]\n>   CI2[Customer Invoicing] --> CF\n>   CI2 --> SF\n>   CI2 --> OF\n>   PO2[Purchase Orders] --> SF\n>   PO2 --> SupF[Supplier File]\n>   SC2[Stock Control] --> SF\n>   SC2 --> OF\n> ```\n\n> 📊 **Đọc 2 diagram này thế nào:** Bên trái: nhiều file cùng tên xuất hiện ở nhiều nhóm app. Bên phải: 4 app cùng trỏ đến **một bộ file dùng chung** (`Customer File`, `Stock File`, `Order File`, `Supplier File`) — mỗi file chỉ còn 1 bản, hết redundancy nội dung.\n\n### 1.7. Slide 9 — Shared File Approach: lợi ích\n\n**Nội dung slide gốc:**\n\n- *Data (files) is shared between different applications.*\n- *Data redundancy problem **is alleviated**.* (giảm nhẹ — không hết hoàn toàn)\n- *Data inconsistency problem across **different versions of the same file** is solved.*\n\nLưu ý: shared file **chưa phải Database Approach hoàn chỉnh** — nó vẫn là file, vẫn phụ thuộc cấu trúc vật lý, thiếu metadata catalog, concurrency control, recovery, security, integrity constraints.\n\n### 1.8. Slide 10 — Shared File Approach: 3 vấn đề còn lại\n\n**Nội dung slide gốc:**\n\n- **Rigid data structure**: *If applications have to share files, the file structure that suits one application might not suit another.*\n- **Physical data dependency**: *If the structure of the data file needs to be changed in some way, this alteration will need to be reflected in all application programs that use that data file.*\n- **No support of concurrency control**: *While a data file is being processed by one application, the file will not be available for other applications or for ad hoc queries.*\n\n| Vấn đề | Giải thích | Ví dụ |\n|---|---|---|\n| **Rigid data structure** | Cấu trúc file phù hợp app A có thể không hợp app B; cuối cùng dùng \"trung dung\" và không ai hài lòng. | HR cần `Bdate`, payroll cần `Salary`, project cần `Hours` — gộp tất cả vào 1 file `EMPLOYEE.txt` thì cồng kềnh. |\n| **Physical data dependency** | Đổi cấu trúc file → tất cả app dùng file đó phải sửa code. | `EMPLOYEE.txt` ban đầu lưu `Ssn, Fname, Lname, Salary`; thêm cột `Dno` vào giữa → app cũ đọc nhầm `Dno` thành `Salary`. |\n| **No concurrency control** | 1 app xử lý file → file bị \"khóa\", app khác không dùng được. | 2 nhân viên HR cùng mở file Excel rồi cùng sửa → người lưu sau ghi đè người lưu trước. |\n\n> 💡 **Hiểu đơn giản:** Shared file giống nhà trọ chia phòng tắm chung — bớt chuyện mỗi đứa xây 1 phòng tắm riêng, nhưng giờ ai vào trước thì khóa cửa, người sau phải đợi. Phòng tắm đã xây rồi, ai muốn lắp thêm vòi sen phải dỡ cả lên.\n\n> 📝 **Tóm lại §1.2–1.8 (File-based và Shared File):**\n> - File-based truyền thống → **Redundancy + Inconsistency**.\n> - Shared File → giảm redundancy, **nhưng vẫn còn** Rigid structure, Physical dependency, No concurrency.\n> - Cội nguồn chung của 2 vấn đề: **definition cấu trúc data nằm trong code app, không tách ra**.\n>\n> **Một câu ghi nhớ:** *Khi data nằm trong file mà cấu trúc data nằm trong code, mỗi lần sửa data sẽ kéo theo sửa code — đó là cội nguồn của mọi bất tiện.*\n\n### 1.9. Slide 11 — Database Approach: vì sao xuất hiện?\n\n**Nội dung slide gốc:**\n\n- **Arose because:**\n  - *Definition of data was embedded in application programs, rather than being stored separately and independently.*\n  - *No control over access and manipulation of data beyond that imposed by application programs.*\n- **Result:** *The Database and Database Management System (DBMS).*\n\nDatabase Approach giải bằng cách:\n1. **Tách định nghĩa dữ liệu ra khỏi code**, lưu vào *system catalog (metadata)*.\n2. **Đặt một lớp middleware giữa app và file gốc** — gọi là *DBMS*.\n3. Mọi truy cập đều phải qua DBMS, không ai chọc thẳng vào file.\n\n### 1.10. Slide 12 — Diagram Database Approach\n\n> 📊 **Hình 1.4 — Database Approach (slide 12):**\n> ```mermaid\n> flowchart LR\n>   Sales[Sales user] <--> SalesApp[Sales application programs<br/>Data entry & reports]\n>   Contracts[Contracts user] <--> ContractsApp[Contracts application programs<br/>Data entry & reports]\n>   subgraph DatabaseSystem[\"Database system\"]\n>     SalesApp --> DBMS[(DBMS)]\n>     ContractsApp --> DBMS\n>     DBMS <--> DB[(Database<br/>PropertyForRent, PrivateOwner,<br/>Client, Lease<br/>+ File definitions)]\n>   end\n> ```\n\n**Schema trong slide 12** (chung cho cả Sales lẫn Contracts):\n\n| Relation | Thuộc tính |\n|---|---|\n| `PropertyForRent` | `propertyNo, street, city, postcode, type, rooms, rent, ownerNo` |\n| `PrivateOwner` | `ownerNo, fName, lName, address, telNo` |\n| `Client` | `clientNo, fName, lName, address, telNo, prefType, maxRent` |\n| `Lease` | `leaseNo, propertyNo, clientNo, rent, paymentMethod, deposit, paid, rentStart, rentFinish` |\n\n> 📊 **Đọc diagram này thế nào:**\n> - Mọi truy vấn từ app phải đi qua **DBMS**, không app nào chạm trực tiếp vào \"Database\".\n> - \"Database\" chứa cả **dữ liệu thật** (`PropertyForRent`, `Client`, …) **lẫn định nghĩa cấu trúc** (file definitions). Đây là điểm khác biệt cốt lõi vs file-based.\n\n**So sánh ngắn:**\n\n| File-based Approach | Database Approach |\n|---|---|\n| Application có file riêng hoặc truy cập file trực tiếp. | Application truy cập dữ liệu **qua DBMS**. |\n| File definition nằm trong code application. | Định nghĩa dữ liệu lưu trong **system catalog**. |\n| Kiểm soát quyền/ràng buộc/đồng thời/phục hồi do từng app tự lo. | DBMS cung cấp cơ chế **tập trung**. |\n| Dễ dư thừa và không nhất quán. | Dữ liệu chia sẻ **có kiểm soát**. |\n\n### 1.11. Slide 13 — Định nghĩa Data và Database\n\n**Nội dung slide gốc:**\n\n- **Data**\n  - *Known facts that can be recorded and that have **implicit meaning**.*\n  - Information? Knowledge?\n  - More: www.whatis.com\n- **Database**: *Shared collection of logically related data and a description of this data, designed to meet the **information needs** of an organization.*\n\nPhân biệt nhanh:\n\n| Khái niệm | Đặc trưng | Ví dụ |\n|---|---|---|\n| **Data** | Sự kiện thô | `38°C`, `Lan`, `123-45` |\n| **Information** | Data có ngữ cảnh | \"Nhiệt độ Sài Gòn hôm nay 38°C\" |\n| **Knowledge** | Information đã đúc kết thành quy luật | \"Sài Gòn tháng 4 thường > 35°C → mặc đồ mỏng\" |\n\n**Phân tích định nghĩa Database:**\n- *\"shared\"* → nhiều user/app cùng dùng được.\n- *\"logically related\"* → không gom lung tung; phải có quan hệ logic.\n- *\"description of this data\"* → cấu trúc dữ liệu cũng nằm trong DB (metadata).\n- *\"information needs of an organization\"* → DB tồn tại vì nhu cầu tổ chức, không phải để demo.\n\n> 💡 **Ví dụ với COMPANY:**\n> - Data: `Ssn = 123456789`, `Dno = 5`, `Salary = 30000`.\n> - Information: Nhân viên có Ssn `123456789` thuộc phòng ban số 5, lương 30000.\n> - Knowledge: Phòng 5 có lương trung bình thấp hơn → cần xem lại chính sách lương.\n\n### 1.12. Slide 14 — System Catalog, Logically Related Data, DBMS\n\n**Nội dung slide gốc:**\n\n- *System catalog (metadata) provides description of data to enable **program-data independence**.*\n- *Logically related data comprises **entities, attributes, and relationships** of an organization's information.*\n- **DataBase Management System (DBMS)**: *a general-purpose software system that facilitates the processes of **defining, constructing, manipulating, and sharing** databases among various users and applications (or a software system that enables users to define, create, maintain, and control access to the database).*\n\n**5 chức năng chính của DBMS:**\n\n| Chức năng | Ý nghĩa |\n|---|---|\n| **Defining** | Định nghĩa schema, kiểu dữ liệu, ràng buộc (qua DDL). |\n| **Constructing** | Tạo và đưa dữ liệu vào lưu trữ. |\n| **Manipulating** | Truy vấn, thêm, xóa, sửa (qua DML). |\n| **Sharing** | Nhiều user/app cùng dùng dữ liệu. |\n| **Control access** | Bảo trì, phân quyền, kiểm soát truy cập. |\n\n**3 thành phần của \"logically related data\"** (chương 2 sẽ dạy chi tiết):\n\n- **Entities** (thực thể) — đối tượng cần lưu, ví dụ `EMPLOYEE`, `DEPARTMENT`, `PROJECT`.\n- **Attributes** (thuộc tính) — đặc điểm của entity, ví dụ `Fname`, `Salary`.\n- **Relationships** (mối liên kết) — quan hệ giữa entity, ví dụ employee *works for* department.\n\n> 💡 **Hiểu đơn giản:** Hình dung DB như **kho chung** của công ty, DBMS là **thủ kho**. Người ta không tự ý vào kho lấy hàng — phải qua thủ kho. Anh ta biết hàng nào ở đâu (catalog), kiểm tra giấy tờ (security), tránh 2 người lấy cùng món (concurrency), và nếu sập đèn anh ta nhớ cách phục hồi (recovery).\n\n> 💡 **Ví dụ DBMS thật:** MySQL, PostgreSQL, Oracle Database, SQL Server, SQLite. File Excel **không phải DBMS** — Excel không có catalog, ràng buộc, transaction, concurrency, recovery theo nghĩa đầy đủ.\n\n### 1.13. Slide 15 — DDL, DML, Controlled Access, Database System\n\n**Nội dung slide gốc:**\n\n- **Data Definition Language (DDL)**\n  - *Permits specification of data types, structures and any data constraints to be stored in the database.*\n  - *All specifications are stored in the database.* (chính là system catalog)\n- **Data manipulation language (DML)**\n  - *Query language: retrieve (query), update (insert, delete, modify).*\n- **Controlled access** to database may include:\n  - **a security system** — phân quyền\n  - **an integrity system** — đảm bảo dữ liệu hợp lệ\n  - **a concurrency control system** — kiểm soát truy cập đồng thời\n  - **a recovery control system** — khôi phục khi crash\n  - **a user-accessible catalog** — cho user tra cứu metadata\n- **Database System = the Database + DBMS software.**\n\n```sql\n-- Ví dụ minh họa DDL (không có trong slide 15 — mở rộng để học):\nCREATE TABLE DEPARTMENT (\n    Dnumber INT PRIMARY KEY,\n    Dname VARCHAR(15) UNIQUE NOT NULL,\n    Mgr_ssn CHAR(9),\n    Mgr_start_date DATE\n);\n```\n\n```sql\n-- Ví dụ minh họa DML:\nSELECT Dnumber, Dname\nFROM DEPARTMENT\nWHERE Dname = 'Research';\n```\n\n> 💡 **Hiểu đơn giản (controlled access):** DBMS giống thư viện có thủ thư. Không chỉ giữ sách, thủ thư còn kiểm tra ai được mượn (security), sách có hợp lệ không (integrity), 2 người không mượn cùng 1 bản sao (concurrency), và nếu cháy mất sổ thì khôi phục được (recovery).\n\n### 1.14. Slide 16 — Roles in the Database Environment\n\n**Nội dung slide gốc** (4 vai trò):\n\n- **Database Administrator (DBA)** *— responsible for:*\n  - authorizing access to DB\n  - coordinating & monitoring its use\n  - acquiring software and hardware resources\n  - security breach, poor response time\n- **Database Designers** *— responsible for:*\n  - identifying the data to be stored in DB\n  - choosing appropriate structures to represent and store this data\n- **Application Programmers**\n- **End Users**\n- *More details: see [1,2]-chapter 1*\n\n| Role (EN) | Tiếng Việt | Trách nhiệm | Ví dụ trên COMPANY |\n|---|---|---|---|\n| **DBA** | Quản trị viên CSDL | Cấp quyền, giám sát, mua phần cứng/phần mềm, xử lý security breach + hiệu năng kém | Cấp quyền cho HR đọc bảng `EMPLOYEE` nhưng không xem `Salary` |\n| **Database Designer** | Thiết kế viên CSDL | Xác định data nào lưu, chọn cấu trúc lưu trữ phù hợp | Quyết định `EMPLOYEE` có khóa chính `Ssn`, có FK `Dno` |\n| **Application Programmer** | Lập trình viên ứng dụng | Viết app dùng DBMS | Viết API `GET /employees`, `POST /projects` |\n| **End User** | Người dùng cuối | Tương tác qua giao diện app | Nhân viên HR nhập hồ sơ, nhân viên xem hồ sơ cá nhân |\n\n> 💡 **Hiểu đơn giản (analogy \"xây nhà\"):** DBA = chủ tịch ban quản lý chung cư (cấp thẻ ra vào, giám sát bảo vệ, mua thang máy mới). Designer = kiến trúc sư vẽ bản thiết kế. App Programmer = thợ thi công nội thất từng căn. End User = cư dân.\n\n### 1.15. Slide 17 — DBMS Components\n\n> 📊 **Hình 1.5 — Các thành phần bên trong DBMS (slide 17):**\n> ```mermaid\n> flowchart TB\n>   Programmers[Programmers<br/>Application programs] --> DML[DML preprocessor]\n>   Users[Users<br/>Queries] --> QP[Query processor]\n>   DBA[DBA<br/>Database schema] --> DDL[DDL compiler]\n>   subgraph DBMSBox[\"DBMS\"]\n>     DML --> POC[Program object code]\n>     POC --> DM[Database manager]\n>     QP --> DM\n>     DDL --> Dict[Dictionary manager]\n>     DM <--> Dict\n>   end\n>   DM <--> FM[File manager]\n>   FM <--> Access[Access methods]\n>   Access <--> Buffers[System buffers]\n>   Buffers <--> Storage[(Database and<br/>system catalog)]\n> ```\n\n**Giải thích từng thành phần:**\n\n| Thành phần | Vai trò |\n|---|---|\n| **DML preprocessor** | Xử lý các lệnh DML nhúng trong app, chuyển để DBMS hiểu. |\n| **Query processor** | Phân tích, tối ưu, thực thi query do user gửi. |\n| **DDL compiler** | Biên dịch lệnh định nghĩa schema, cập nhật metadata. |\n| **Program object code** | Mã đối tượng của app sau khi xử lý. |\n| **Database manager** | Điều phối truy cập DB, kiểm tra quyền/ràng buộc cấp quản lý. |\n| **Dictionary manager** | Quản lý dictionary/catalog chứa metadata. |\n| **File manager** | Quản lý file vật lý trên bộ nhớ phụ. |\n| **Access methods** | Phương pháp truy cập dữ liệu (scan, index access). |\n| **System buffers** | Vùng đệm RAM trao đổi block giữa disk và DBMS. |\n| **Database and system catalog** | Nơi chứa dữ liệu thật + metadata. |\n\n> 📊 **Đọc diagram này thế nào:** 3 nguồn input (Programmer, User, DBA) đi qua 3 cửa nhận tương ứng (DML preprocessor, Query processor, DDL compiler). Tất cả nói chuyện với **Database manager** + **Dictionary manager**. Bên dưới là tầng OS thật (File manager, Access methods, System buffers) đọc/ghi xuống đĩa. **Không có mũi tên nào từ app/query trực tiếp xuống đĩa** — đây chính là cơ chế kiểm soát truy cập.\n\n### 1.16. Slide 18 — 4 Đặc trưng của Database Approach\n\n**Nội dung slide gốc** (slide cực hay ra trắc nghiệm):\n\n- **Self-describing nature** of a database system\n- **Insulation between programs and data, and data abstraction**\n  - *Program-data independence + Program-operation independence = Data abstraction*\n  - *A data model is a type of data abstraction*\n- **Support of multiple views** of the data\n- **Sharing of data** and multi-user transaction processing\n- *Other advantages: see [1]-1.6*\n\n| Đặc trưng | Ý nghĩa | Ví dụ |\n|---|---|---|\n| **1. Self-describing** | DB chứa cả data lẫn metadata mô tả data đó. | Mở DB lên là biết `EMPLOYEE` có cột nào, kiểu gì — không cần xem code app. |\n| **2. Insulation + Data Abstraction** | Program-data independence + Program-operation independence. App không biết chi tiết lưu trữ. | App viết SQL không cần biết block disk. |\n| **3. Multiple views** | Cùng 1 DB, mỗi nhóm user thấy 1 view khác. | HR thấy lương; Project Manager thấy giờ làm dự án; Employee chỉ thấy thông tin của mình. |\n| **4. Sharing & multi-user transaction** | Nhiều user dùng cùng lúc, được kiểm soát bằng transaction. | Hai nhân viên HR cùng cập nhật → DBMS dùng locking & ACID để không phá nhau. |\n\n> 💡 **Hiểu đơn giản (đặc trưng 1, \"self-describing\"):** Như ổ cứng có \"header\" mô tả format. Đem ổ cứng sang máy khác vẫn đọc được vì format nằm trong chính ổ. Ngược lại, file `.bin` của một game cũ — không có code game thì không ai đọc được.\n\n> 💡 **Hiểu đơn giản (đặc trưng 4, \"transaction\"):** Transaction giống chuyển khoản ngân hàng — trừ tiền A và cộng tiền B phải xảy ra cùng nhau; lỗi giữa chừng → hủy cả 2.\n\n### 1.17. Slide 19 — Lịch sử các thế hệ DBMS\n\n**Nội dung slide gốc:**\n\n- **History of database systems**\n  - First generation: **Hierarchical and Network**\n  - Second generation: **Relational**\n  - Third generation: **Object-Relational, Object-Oriented**\n- *Brief history of database applications: see [1]-section 1.7*\n\n| Thế hệ | Mô hình | Đặc điểm | Ví dụ |\n|---|---|---|---|\n| **First** (1960s–70s) | Hierarchical, Network | Dạng cây/đồ thị; truy cập bằng con trỏ | IBM IMS (1968) |\n| **Second** (từ 1970, Codd) | Relational | Dạng bảng; chủ đạo hiện nay | Oracle, MySQL, PostgreSQL, SQL Server |\n| **Third** (1990s+) | Object-Relational, Object-Oriented | Hỗ trợ kiểu phức tạp (đa phương tiện, không gian) | PostgreSQL (extensions), Db4o |\n\n### 1.18. Slide 20 — Network Model Schema (Elmasri Figure 2.8)\n\n> 📊 **Hình 1.6 — Network Model Schema (slide 20):**\n> ```mermaid\n> flowchart TD\n>   STUDENT[STUDENT]\n>   COURSE[COURSE]\n>   SECTION[SECTION]\n>   PREREQ[PREREQUISITE]\n>   GRADE[GRADE_REPORT]\n>   STUDENT -- STUDENT_GRADES --> GRADE\n>   COURSE -- COURSE_OFFERINGS --> SECTION\n>   SECTION -- SECTION_GRADES --> GRADE\n>   COURSE -- HAS_A --> PREREQ\n>   PREREQ -- IS_A --> COURSE\n> ```\n\n> 📊 **Đọc diagram này thế nào:**\n> - 5 record type: STUDENT, COURSE, SECTION, GRADE_REPORT, PREREQUISITE.\n> - 5 \"set\" (mũi tên có tên): `STUDENT_GRADES`, `COURSE_OFFERINGS`, `SECTION_GRADES`, `IS_A`, `HAS_A`.\n> - **Đặc điểm Network**: liên kết = con trỏ thực sự — duyệt DB bằng \"đi theo mũi tên\". Khác Relational dùng JOIN trên giá trị trùng.\n\n> 💡 **Hiểu đơn giản:** Network model giống bản đồ đường đi: muốn tìm gì phải đi từ node nào sang node nào. Relational model giống bảng Excel có cột chung; ta dùng cột chung để JOIN.\n\n### 1.19. Slide 21 — Relational Model Schema + Instance (Elmasri Figure 1.2)\n\nSlide 21 hiển thị **dữ liệu thật** của 4 bảng — minh họa \"cùng một database University, lần này theo Relational Model\".\n\n**Bảng COURSE:**\n\n| Course_name | Course_number | Credit_hours | Department |\n|---|---|---:|---|\n| Intro to Computer Science | CS1310 | 4 | CS |\n| Data Structures | CS3320 | 4 | CS |\n| Discrete Mathematics | MATH2410 | 3 | MATH |\n| Database | CS3380 | 3 | CS |\n\n**Bảng SECTION:**\n\n| Section_identifier | Course_number | Semester | Year | Instructor |\n|---:|---|---|---:|---|\n| 85 | MATH2410 | Fall | 04 | King |\n| 92 | CS1310 | Fall | 04 | Anderson |\n| 102 | CS3320 | Spring | 05 | Knuth |\n| 112 | MATH2410 | Fall | 05 | Chang |\n| 119 | CS1310 | Fall | 05 | Anderson |\n| 135 | CS3380 | Fall | 05 | Stone |\n\n**Bảng GRADE_REPORT:**\n\n| Student_number | Section_identifier | Grade |\n|---:|---:|---|\n| 17 | 112 | B |\n| 17 | 119 | C |\n| 8 | 85 | A |\n| 8 | 92 | A |\n| 8 | 102 | B |\n| 8 | 135 | A |\n\n**Bảng PREREQUISITE:**\n\n| Course_number | Prerequisite_number |\n|---|---|\n| CS3380 | CS3320 |\n| CS3380 | MATH2410 |\n| CS3320 | CS1310 |\n\n> 📊 **Ý nghĩa slide 21:** So với Network (slide 20) cần con trỏ vật lý, Relational chỉ cần các giá trị (Course_number, Section_identifier) \"trỏ\" nhau qua **giá trị trùng** giữa các bảng. Đây là nền của khái niệm **Foreign Key** sẽ học ở chương 4.\n\n> 📝 **Tóm lại §1 (toàn section):**\n> - File-based \"đẻ ra\" Database vì 2 lý do: data definition nhúng trong code, không kiểm soát được truy cập.\n> - DBMS = phần mềm trung gian, đứng giữa app và data; cung cấp DDL/DML, security, integrity, concurrency, recovery, catalog.\n> - 4 đặc trưng nhận diện Database Approach: *Self-describing, Insulation/Abstraction, Multiple views, Sharing & multi-user.*\n> - 4 vai trò: DBA, Designer, Application Programmer, End User.\n> - 3 thế hệ DBMS: Hierarchical/Network → Relational → Object-Relational/OO.\n>\n> **Một câu ghi nhớ:** *Database Approach = tách dữ liệu ra khỏi chương trình, đặt một lớp DBMS ở giữa để chương trình không còn phải biết file nằm đâu hay format ra sao.*\n\n> ❓ **Tự kiểm tra §1:**\n> 1. Phân biệt Data Redundancy và Data Inconsistency. Cái nào là *nguyên nhân*, cái nào là *hậu quả*?\n> 2. Shared File Approach giải quyết được vấn đề gì? Còn để lại vấn đề gì?\n> 3. Trong slide 5, bảng `Client` xuất hiện ở Sales và Contracts với 2 schema khác nhau. Đây là minh họa cho khái niệm nào?\n> 4. Liệt kê 4 đặc trưng của Database Approach. Đặc trưng nào là tiền đề trực tiếp cho data independence?\n> 5. Phân biệt vai trò DBA và Database Designer. Ai làm gì khi công ty đổi từ Oracle sang PostgreSQL?\n> 6. So sánh ngắn Network model (slide 20) và Relational model (slide 21).\n> *(Đáp án ở §12 cuối chương.)*\n\n---\n\n","file":"materials/DB-Chapter1.md","section":2},{"id":"c1-03","group":"c1","kind":"source","title":"2. Three-Schema Architecture và Data Independence","markdown":"## 2. Three-Schema Architecture và Data Independence\n\n### 2.1. Tại sao có concept này? (Motivation)\n\nỞ §1.8, \"Physical data dependency\" là vấn đề chí mạng của shared file: muốn đổi cấu trúc → phải sửa hàng trăm app. Trong công ty lớn 10 năm tuổi, điều đó **không khả thi**. Cần một kiến trúc cho phép **đổi tầng này mà không ảnh hưởng tầng khác** — đó là **Three-Schema Architecture** (do ANSI/SPARC đề xuất 1975), và \"lợi thế cốt lõi\" của nó là **Data Independence**.\n\n> 💡 **Hiểu đơn giản:** Three-level architecture giống nhà hàng:\n> - Khách nhìn **menu** (external view).\n> - Bếp trưởng có **công thức chuẩn** (conceptual schema).\n> - Kho/bếp có **cách sắp nguyên liệu thật** (internal schema).\n> - Khách không cần biết kho xếp thịt ở ngăn nào; nếu kho đổi cách sắp, menu không cần đổi.\n\n### 2.2. Slide 23 — Mục tiêu của Three-Schema Architecture\n\n**Nội dung slide gốc** (5 mục tiêu):\n\n1. *All users should be able to access **same data**.*\n2. *Users should not need to know **physical** database storage details.*\n3. *DBA should be able to change **database storage structures** without affecting the users' views.*\n4. *Internal structure of database should be unaffected by changes to **physical aspects of storage**.*\n5. *DBA should be able to change **conceptual structure** of database without affecting all users.*\n\n5 mục tiêu này = định nghĩa của data independence — mỗi mục tiêu là 1 trường hợp cụ thể của \"đổi 1 tầng, không ảnh hưởng tầng khác\".\n\n### 2.3. Slide 24 — Diagram Kiến trúc 3 mức\n\n> 📊 **Hình 2.1 — Three-level architecture and data independence (slide 24):**\n> ```mermaid\n> flowchart TB\n>   U1[User 1] --> V1[View 1]\n>   U2[User 2] --> V2[View 2]\n>   Un[User n] --> Vn[View n]\n>   V1 --- ExtLevel[External level]\n>   V2 --- ExtLevel\n>   Vn --- ExtLevel\n>   ExtLevel --> ConLevel[Conceptual level<br/>Conceptual schema]\n>   ConLevel --> IntLevel[Internal level<br/>Internal schema]\n>   IntLevel --> Phys[(Physical data<br/>organization<br/>Database)]\n> ```\n\n| Level | Tiếng Việt | Ai quan tâm? | Trả lời câu hỏi gì? |\n|---|---|---|---|\n| **External level** | Mức ngoài / mức khung nhìn | End users, application programmers | User này cần nhìn phần dữ liệu nào? |\n| **Conceptual level** | Mức khái niệm / logic toàn cục | Database designers, DBA, developers | Toàn tổ chức lưu data gì và quan hệ ra sao? |\n| **Internal level** | Mức trong / mức vật lý | DBA, DBMS engineers | Data lưu trên máy thế nào? File, index, block, pointer ra sao? |\n\n> 📊 **Đọc diagram này thế nào:** 3 schema là **mô tả** về data, không phải data thật. Data thật ở \"Physical data organization\" dưới cùng.\n\n### 2.4. Slide 25–26 — External / Conceptual / Internal Level\n\n**Slide 25:**\n\n- **External Level**\n  - *Users' view of the database.*\n  - *Describes that part of database that is **relevant to a particular user**.*\n- **Conceptual Level**\n  - *Community view of the database.*\n  - *Describes what data is stored in database and **relationships among the data**.*\n\n**Slide 26:**\n\n- **Internal Level**\n  - *Physical representation of the database on the computer.*\n  - *Describes **how** the data is stored in the database.*\n\n**Lưu ý:** Internal level vẫn là **schema** (mô tả), không phải bit thật trên đĩa. Tầng \"bit thật\" là *Physical data organization* — nằm ngoài 3 schema.\n\n**Ví dụ trên COMPANY:**\n\n| Level | Ví dụ |\n|---|---|\n| External level | HR view: `EMPLOYEE(Ssn, Fname, Lname, Bdate, Address, Dno)`. Payroll view: `EMPLOYEE(Ssn, Fname, Lname, Salary)`. Project Manager view: `WORKS_ON(Essn, Pno, Hours)`. |\n| Conceptual level | Schema logic đầy đủ: EMPLOYEE, DEPARTMENT, PROJECT, WORKS_ON, DEPENDENT + các quan hệ. |\n| Internal level | File `EMPLOYEE.dat` lưu heap; B+ tree index trên `Ssn`; block size 4KB; cluster theo `Dno`. |\n\n### 2.5. Slide 27 — Ví dụ cụ thể 3 mức (STAFF)\n\n> 📊 **Hình 2.2 — STAFF qua 3 tầng (slide 27):**\n> ```\n> External view 1                       External view 2\n> ┌────┬──────┬──────┬─────┬───────┐    ┌────────┬──────┬─────────┐\n> │sNo │fName │lName │ age │salary │    │staffNo │lName │branchNo │\n> └────┴──────┴──────┴─────┴───────┘    └────────┴──────┴─────────┘\n>          │                                       │\n>          ▼                                       ▼\n> Conceptual level\n> ┌────────┬───────┬───────┬─────┬────────┬─────────┐\n> │staffNo │ fName │ lName │ DOB │ salary │branchNo │\n> └────────┴───────┴───────┴─────┴────────┴─────────┘\n>          │\n>          ▼\n> Internal level (định nghĩa kiểu C):\n> ```\n> ```c\n> struct STAFF {\n>     int  staffNo;\n>     int  branchNo;\n>     char fName[15];\n>     char lName[15];\n>     struct date dateOfBirth;\n>     float salary;\n>     struct STAFF *next;        /* pointer to next Staff record */\n> };\n> index staffNo; index branchNo; /* define indexes for staff */\n> ```\n\n**Phân tích quan trọng:**\n- **External view 1** thấy `age` — **không có** ở Conceptual; được **suy ra (derived)** từ `DOB` qua external/conceptual mapping. *Lý do lưu DOB chứ không lưu age:* age đổi mỗi sinh nhật, lưu DOB rồi tính `age = today - DOB`.\n- **External view 2** chỉ thấy 3 cột tối giản — bỏ luôn `salary`.\n- **Conceptual** lưu canonical: `staffNo, fName, lName, DOB, salary, branchNo`.\n- **Internal** dùng C struct + 2 index trên `staffNo` và `branchNo`; có pointer `*next` (linked list).\n\n> 💡 **Ví dụ với COMPANY:** Payroll view có `Salary`; Project Manager view không có `Salary`. Cả hai cùng lấy từ conceptual schema `EMPLOYEE`, qua 2 external mapping khác nhau.\n\n### 2.6. Slide 28 — Data Independence + Logical Data Independence\n\n**Nội dung slide gốc:**\n\n- **Data Independence** is the *capacity to change the schema at one level of a database system **without having to change the schema at the next higher level**.*\n- **Logical Data Independence**\n  - *Refers to **immunity of external schemas** to changes in conceptual schema.*\n  - *Conceptual schema changes (e.g. addition/removal of entities) should not require changes to external schema or rewrites of application programs.*\n\n| Thuật ngữ (EN) | Tiếng Việt | Định nghĩa |\n|---|---|---|\n| Data Independence | Độc lập dữ liệu | Khả năng đổi schema ở 1 mức mà không phải đổi schema ở mức cao hơn kế tiếp. |\n| Logical Data Independence | Độc lập dữ liệu logic | External schema miễn nhiễm với thay đổi của conceptual schema. |\n\n> 💡 **Ví dụ Logical DI:** Thêm bảng `TRAINING_COURSE` vào conceptual schema COMPANY để lưu khóa đào tạo. HR view cũ chỉ xem `EMPLOYEE` → không cần đổi.\n\n### 2.7. Slide 29 — Physical Data Independence\n\n**Nội dung slide gốc:**\n\n- **Physical Data Independence**\n  - *Refers to **immunity of conceptual schema** to changes in the internal schema.*\n  - *Internal schema changes (e.g. using different file organizations, storage structures/devices) should not require changes to conceptual or external schemas.*\n\n| Thuật ngữ | Định nghĩa |\n|---|---|\n| Physical Data Independence | Conceptual schema miễn nhiễm với đổi của internal schema (đổi file organization, thêm index, đổi storage device). |\n\n> 💡 **Ví dụ Physical DI:** DBA thêm B+ tree index trên `EMPLOYEE(Ssn)` để tìm nhân viên nhanh hơn. Form tra cứu HR không cần đổi.\n\n### 2.8. Slide 30 — Mappings và 2 loại Data Independence\n\n> 📊 **Hình 2.3 — Mappings và Data Independence (slide 30):**\n> ```mermaid\n> flowchart TB\n>   E1[External<br/>schema] --- M1\n>   E2[External<br/>schema] --- M1\n>   E3[External<br/>schema] --- M1\n>   M1[External / conceptual mapping<br/><i>Logical data independence</i>] --- C[Conceptual<br/>schema]\n>   C --- M2[Conceptual / internal mapping<br/><i>Physical data independence</i>]\n>   M2 --- I[Internal<br/>schema]\n> ```\n\n> 📊 **Đọc diagram này thế nào:** 2 mapping nối 3 schema:\n> - **External / conceptual mapping** → **Logical Data Independence**.\n> - **Conceptual / internal mapping** → **Physical Data Independence**.\n> - Mỗi lần 1 schema đổi, **chỉ mapping liên quan cần update**, không phải sửa các schema khác.\n\n**So sánh Logical vs Physical DI:**\n\n| Tiêu chí | Logical DI | Physical DI |\n|---|---|---|\n| Thay đổi ở mức nào? | Conceptual schema | Internal schema |\n| Mức được bảo vệ | External schema + application | Conceptual + external schema |\n| Ví dụ thay đổi | Thêm entity, thêm thuộc tính, đổi quan hệ logic | Đổi file organization, thêm index, đổi disk |\n| Khó hay dễ? | **Khó hơn** | Dễ hơn |\n| Lý do | External gắn chặt với code app | Internal được mapping ẩn đi tốt |\n\n> 💡 **Hiểu đơn giản (cải tạo nhà):**\n> - **Physical DI** = thay sàn gỗ tầng trệt. Tầng 2 không cần xây lại.\n> - **Logical DI** = sửa lại bố cục tầng 2. Cách bố trí phòng tầng 3, 4 (view của từng cư dân) vẫn giữ nguyên.\n\n> 📝 **Tóm lại §2 (Three-Schema và Data Independence):**\n> - 3 schema: External, Conceptual, Internal.\n> - 2 mapping: external/conceptual và conceptual/internal.\n> - Mỗi mapping cho 1 loại data independence: **Logical** (conceptual đổi, external khỏe) và **Physical** (internal đổi, conceptual khỏe).\n> - Logical DI khó hơn Physical DI.\n>\n> **Một câu ghi nhớ:** *3-Schema = 3 cách nhìn cùng 1 DB; 2 Mapping = 2 lớp kính cách âm giữ cho việc đổi tầng dưới không vọng lên tầng trên.*\n\n> ❓ **Tự kiểm tra §2:**\n> 7. Trong ví dụ STAFF (slide 27), `age` có ở External view 1 nhưng không ở Conceptual. Vì sao? Đây có vi phạm 3-schema không?\n> 8. Công ty đổi từ Oracle sang PostgreSQL. Việc này gây thay đổi ở mức nào? Loại data independence nào \"đỡ đòn\"?\n> 9. *\"Logical data independence dễ đạt hơn Physical data independence.\"* Đúng hay sai? Giải thích.\n> 10. DBA thêm index trên `EMPLOYEE(Ssn)` — đây là loại data independence nào?\n\n---\n\n","file":"materials/DB-Chapter1.md","section":3},{"id":"c1-04","group":"c1","kind":"source","title":"3. Database Languages","markdown":"## 3. Database Languages\n\n### 3.1. Tại sao có concept này? (Motivation)\n\nDBMS đứng giữa app và data; app phải nói chuyện với DBMS bằng **ngôn ngữ chuẩn** — không thể gọi function private. Sinh ra họ \"Database Languages\" chia theo chức năng: định nghĩa cấu trúc, thao tác dữ liệu, kiểm soát quyền — đó là **DDL, DML, DCL**.\n\n> 💡 **Hiểu đơn giản:** DBMS giống cơ quan hành chính — muốn xây nhà cần hồ sơ thiết kế (DDL), muốn xin thông tin cần biểu mẫu truy vấn (DML), muốn cấp quyền cần văn bản phân quyền (DCL).\n\n### 3.2. Slide 32 — DDL, DML, DCL\n\n**Nội dung slide gốc:**\n\n- **DDL (Data Definition Language)** *— allows the DBA or user to describe and name **entities, attributes, and relationships** required for the application plus any associated **integrity and security constraints**.*\n- **DML (Data Manipulation Language)** *— provides basic data manipulation operations on data held in the database.*\n- **DCL (Data Control Language)** *— defines activities that are not in the categories of those for the DDL and DML, such as **granting privileges to users**, and defining when proposed changes to a databases should be **irrevocably made**.*\n\n| Language | Tiếng Việt | Dùng để làm gì? | Ví dụ SQL |\n|---|---|---|---|\n| **DDL** | Ngôn ngữ định nghĩa dữ liệu | Mô tả & đặt tên entity/attribute/relationship + integrity/security constraints | `CREATE TABLE`, `ALTER TABLE`, `DROP TABLE` |\n| **DML** | Ngôn ngữ thao tác dữ liệu | Truy vấn, thêm, xóa, sửa data | `SELECT`, `INSERT`, `UPDATE`, `DELETE` |\n| **DCL** | Ngôn ngữ điều khiển dữ liệu | Cấp/thu quyền, commit/rollback transaction | `GRANT`, `REVOKE`, `COMMIT`, `ROLLBACK` |\n\n```sql\n-- DDL: tạo bảng\nCREATE TABLE EMPLOYEE (\n    Ssn CHAR(9) PRIMARY KEY,\n    Fname VARCHAR(15),\n    Lname VARCHAR(15),\n    Salary DECIMAL(10, 2),\n    Dno INT\n);\n\n-- DML: truy vấn dữ liệu\nSELECT Fname, Lname, Salary\nFROM EMPLOYEE\nWHERE Dno = 5;\n\n-- DCL: cấp quyền đọc bảng EMPLOYEE cho user hr_user\nGRANT SELECT ON EMPLOYEE TO hr_user;\n```\n\n*Lưu ý:* Đoạn SQL trên là **ví dụ minh họa** (không phải code xuất hiện trực tiếp trong slide chương 1). Chương 6 sẽ học SQL chi tiết.\n\n> 💡 **Hiểu đơn giản (xây nhà):**\n> - **DDL** = bản vẽ kỹ thuật + công nhân thi công khung nhà — quyết định nhà có mấy tầng.\n> - **DML** = thợ trang trí nội thất — kê bàn, thay rèm, dán tường.\n> - **DCL** = bảo vệ + chìa khóa cửa — ai vào tầng nào, ai có thẩm quyền \"khóa sổ kế toán hôm nay\" (commit) hay hủy sổ vừa làm (rollback).\n\n### 3.3. Slide 33 — Procedural DML, Non-Procedural DML, 4GLs\n\n**Nội dung slide gốc:**\n\n- **Procedural DML** *— allows user to tell system **exactly how** to manipulate data (e.g., Network and hierarchical DMLs).*\n- **Non-Procedural DML (declarative language)** *— allows user to state **what** data is needed rather than **how** it is to be retrieved (e.g., SQL, QBE).*\n- **Fourth Generation Languages (4GLs)**\n  - Non-procedural languages: SQL, QBE, etc.\n  - Application generators, report generators, etc. (see [2])\n\n| Loại | Người dùng nói gì? | Ví dụ |\n|---|---|---|\n| **Procedural DML** | Nói **cách làm** từng bước | \"Đi từ record A theo pointer sang B\" trong Network/Hierarchical DB |\n| **Non-Procedural DML** (declarative) | Nói **muốn gì**, hệ thống tự lo cách | `SELECT * FROM EMPLOYEE WHERE Dno = 5;` |\n\n**Vì sao SQL là non-procedural?** Khi viết:\n```sql\nSELECT Fname, Lname FROM EMPLOYEE WHERE Dno = 5;\n```\nBạn chỉ nói: \"Tôi muốn họ tên nhân viên thuộc phòng 5\". Bạn **không** nói DBMS phải scan bảng hay dùng index, đọc block nào trước, JOIN ra sao. DBMS có **query optimizer** tự chọn kế hoạch tối ưu.\n\n**4GLs** gồm:\n- SQL, QBE.\n- Application generators.\n- Report generators.\n\nMục tiêu 4GL: giảm code thủ công, cho user mô tả nhu cầu ở mức cao.\n\n> 💡 **Hiểu đơn giản:** Procedural = \"đi 200m rẽ trái, qua đèn xanh đèn đỏ, …\" / Non-procedural = \"tới 268 Lý Thường Kiệt giúp anh\" (Grab tự đi).\n\n> 📝 **Tóm lại §3 (Database Languages):**\n> - 3 nhóm theo chức năng: **DDL** (định nghĩa), **DML** (thao tác), **DCL** (kiểm soát).\n> - DML chia 2 phong cách: **procedural** (HOW) và **non-procedural** (WHAT). SQL là declarative.\n>\n> **Một câu ghi nhớ:** *DDL dựng nhà, DML kê đồ, DCL phát chìa khóa — và SQL là declarative DML cộng thêm DDL+DCL gói chung.*\n\n> ❓ **Tự kiểm tra §3:**\n> 11. SQL chứa cả DDL, DML lẫn DCL. Kể 1 câu lệnh SQL mỗi loại.\n> 12. `CREATE TABLE` thuộc DDL, DML hay DCL? Vì sao?\n> 13. `SELECT Fname FROM EMPLOYEE WHERE Dno = 5` là procedural hay non-procedural?\n> 14. Vì sao non-procedural DML thắng thế procedural DML trên thực tế?\n\n---\n\n","file":"materials/DB-Chapter1.md","section":4},{"id":"c1-05","group":"c1","kind":"source","title":"4. Data Models, Database Schema và Database State","markdown":"## 4. Data Models, Database Schema và Database State\n\n### 4.1. Tại sao có concept này? (Motivation)\n\n§2 nói \"schema\" rất nhiều. Nhưng schema **khác** instance/state thế nào? Schema được **mô tả bằng** \"data model\" nào? Đây là 3 khái niệm hay bị nhầm — thi rất hay hỏi.\n\n### 4.2. Slide 35 — Data Model\n\n**Nội dung slide gốc:**\n\n- **Data Model**: *An integrated collection of concepts for describing **data, relationships between data, and constraints** on the data in an organization.*\n- **Categories of data models include:**\n  - **Object-based (Conceptual)**: ERD, Object-Oriented, …\n  - **Record-based (Representational)**: Relational, Network, Hierarchical\n  - **Physical**: used to describe data at the internal level\n- *Object-based and record-based models describe data at the conceptual & external levels.*\n\n| Category | Ví dụ | Dùng khi nào? | Ví dụ trên COMPANY |\n|---|---|---|---|\n| **Object-based** (Conceptual) | ERD, Object-Oriented | Phân tích yêu cầu, thiết kế ý niệm, nói chuyện với user | ERD: `EMPLOYEE` works for `DEPARTMENT`, `DEPARTMENT` controls `PROJECT` |\n| **Record-based** (Representational) | Relational, Network, Hierarchical | Chuyển thiết kế sang DBMS có thể cài đặt logic | Relational: bảng `EMPLOYEE`, `DEPARTMENT`, `PROJECT`, `WORKS_ON` |\n| **Physical** | File org, index, storage struct | Tối ưu lưu trữ, truy cập, hiệu năng | Heap file vs ordered file, B+ tree index trên `Ssn` |\n\n> 💡 **Hiểu đơn giản:** Data model = **kiểu bản vẽ kỹ thuật**. Cùng 1 ngôi nhà, kiến trúc sư có thể vẽ \"phối cảnh 3D\" (object-based), \"mặt bằng từng tầng\" (record-based), hay \"bản vẽ điện-nước\" (physical).\n\n### 4.3. Slide 36 — Database Schema, Schema Diagram, Database State\n\n**Nội dung slide gốc:**\n\n- **Database Schema**: *the description of a database, which is specified during database design and is **not expected to change frequently**.*\n- **Schema Diagram**: *a displayed schema.*\n- **Database State (Snapshot)**: *the data in the database at a **particular moment in time**.*\n\n**Schema vs State:**\n\n| Tiêu chí | Schema | State / Snapshot / Instance |\n|---|---|---|\n| Bản chất | Cấu trúc / thiết kế | Dữ liệu cụ thể hiện tại |\n| Thay đổi? | **Ít** thay đổi | **Liên tục** (insert/update/delete) |\n| Ví dụ trên COMPANY | `EMPLOYEE(Fname, Lname, Ssn, Salary, Dno)` | Dòng `('John', 'Smith', '123456789', 30000, 5)` |\n| Ví dụ đời thường | Mẫu phiếu đăng ký | Các phiếu đã điền của từng người |\n\n**So sánh 3 khái niệm dễ nhầm:**\n\n| Khái niệm | Nội dung | Ví dụ | Tần suất đổi |\n|---|---|---|---|\n| **Data Model** | Tập khái niệm dùng để mô tả schema | Relational, ER, Network | Vài chục năm |\n| **Schema** | Mô tả cụ thể của 1 DB, viết theo data model | \"STUDENT(Name, Student_number, Class, Major)\" | Vài tháng/năm |\n| **State (Instance)** | Dữ liệu thật ở 1 thời điểm | {(\"Lan\", 17, \"K22\", \"CS\"), …} | Liên tục |\n\n> 💡 **Hiểu đơn giản:**\n> - Data model = **quyển từ điển**.\n> - Schema = **bài văn viết bằng từ điển đó**.\n> - State = **bản nháp ghi tay đang được sửa từng giây**.\n> - Hoặc: Schema = **khuôn bánh**; state = **các bánh đổ ra từ khuôn ở 1 thời điểm**.\n\n### 4.4. Slide 37 — Schema Diagram (Elmasri Figure 2.1)\n\n> 📊 **Hình 4.1 — Schema diagram của University DB (slide 37):**\n> ```mermaid\n> erDiagram\n>     STUDENT {\n>         string Name\n>         string Student_number\n>         string Class\n>         string Major\n>     }\n>     COURSE {\n>         string Course_name\n>         string Course_number\n>         int Credit_hours\n>         string Department\n>     }\n>     PREREQUISITE {\n>         string Course_number\n>         string Prerequisite_number\n>     }\n>     SECTION {\n>         string Section_identifier\n>         string Course_number\n>         string Semester\n>         string Year\n>         string Instructor\n>     }\n>     GRADE_REPORT {\n>         string Student_number\n>         string Section_identifier\n>         string Grade\n>     }\n> ```\n\n> 📊 **Đọc diagram này thế nào:**\n> - 5 bảng (relation).\n> - **Schema diagram chỉ vẽ tên bảng + tên cột**, KHÔNG vẽ dữ liệu.\n> - Bạn không thấy \"Anderson\" hay \"Fall 04\" như slide 21 — vì 21 vẽ **state**, còn 37 vẽ **schema**.\n> - Schema diagram cũng **không hiển thị ràng buộc động** (kiểu \"Grade phải thuộc {A, B, C, D, F}\").\n\n**So sánh slide 21 và slide 37:**\n\n| Slide | Vai trò |\n|---|---|\n| Slide 21 | Hiển thị relational model schema **kèm dữ liệu mẫu** (state) |\n| Slide 37 | Hiển thị schema diagram: **tên relation + attributes**, không có dữ liệu |\n\n> 📝 **Tóm lại §4 (Data Models, Schema, State):**\n> - **Data Model** = khung khái niệm.\n> - **Schema** = bản thiết kế DB cụ thể, ít đổi.\n> - **State (Snapshot)** = dữ liệu thật, đổi liên tục.\n>\n> **Một câu ghi nhớ:** *Data model là quyển từ điển; schema là bài văn viết bằng từ điển đó; state là bản nháp đang được sửa từng giây.*\n\n> ❓ **Tự kiểm tra §4:**\n> 15. Phân biệt Data Model và Database Schema.\n> 16. Vì sao Database Schema thường ít đổi còn State đổi liên tục?\n> 17. Với COMPANY, `EMPLOYEE(Fname, Lname, Ssn, Salary)` là schema hay state? Một dòng nhân viên cụ thể là gì?\n> 18. Phân biệt Schema và State qua 1 ví dụ thực tế (trường đại học).\n\n---\n\n","file":"materials/DB-Chapter1.md","section":5},{"id":"c1-06","group":"c1","kind":"source","title":"5. Data Management Systems Framework (NÂNG CAO)","markdown":"## 5. Data Management Systems Framework (NÂNG CAO)\n\n### 5.1. Tại sao có concept này? (Motivation)\n\nSection 5 cho ta biết DBMS truyền thống nằm trong một hệ sinh thái lớn hơn. Slide 39 đặt câu hỏi *\"Where are we?\"* để giúp SV thấy **CSDL nằm ở đâu** trong tổng thể hệ thống thông tin của 1 tổ chức.\n\n### 5.2. Slide 39 — Where are we?\n\n**Bảng framework slide gốc:**\n\n| Layer lớn | Sub-layer | Components |\n|---|---|---|\n| **Application Layer** | (single) | Visualization, Collaborative Computing, Mobile Computing, Knowledge-based Systems |\n| **Data Management Layer** | Layer 3: information extraction & sharing | Data Warehousing, Data Mining, Internet DBs, Collaborative, P2P & Grid Data Management |\n| | Layer 2: interoperability & migration | Heterogeneous DB Systems, Client/Server DBs, Multimedia DB Systems, Migrating Legacy DBs |\n| | Layer 1: DB technologies | DB Systems, Distributed DB Systems |\n| **Supporting Layer** | (single) | Networking, Mass Storage, Agents, Grid Computing Infrastructure, Parallel & Distributed Processing, Distributed Object Management |\n\n> 📊 **Đọc bảng này thế nào:**\n> - 3 tầng: **app gần user** (trên) → **hạ tầng** (dưới).\n> - **Data Management Layer** chia 3 sub-layer:\n>   - **Layer 1 — DB technologies**: chính là CO2013 dạy. Là chương 1–8.\n>   - **Layer 2 — interoperability**: nói chuyện giữa nhiều DBMS (Oracle ↔ PostgreSQL), migrate legacy.\n>   - **Layer 3 — extraction & sharing**: data warehouse, data mining (môn nâng cao).\n\n**Ví dụ ánh xạ vào ứng dụng thật:**\n- Mobile banking app → **Application Layer**.\n- DB giao dịch ngân hàng → **Data Management Layer 1**.\n- Data warehouse lưu lịch sử giao dịch để phân tích → **Layer 3**.\n- Network/storage/cloud → **Supporting Layer**.\n\n### 5.3. Slide 40 — Extending Database Capabilities\n\n**Nội dung slide gốc:**\n\n- **Extending database capabilities for new applications**\n  - Example applications: **storage and retrieval of images, videos**, **data mining** (large amounts of data), **spatial databases**, **time series applications**, …\n  - More complex data structures than relational representation\n  - New data types except for the basic numeric and character string types\n  - New operations and query languages for new data types\n  - New storage and retrieval methods\n  - New security mechanisms\n  - …\n\n| Hướng mở rộng | Ý nghĩa | Ví dụ |\n|---|---|---|\n| Storage of images/videos | Lưu media + metadata | Instagram lưu ảnh + tag |\n| Data mining | Phân tích lượng lớn data tìm pattern | Phát hiện gian lận thẻ tín dụng |\n| Spatial databases | Quản lý dữ liệu không gian | Google Maps, GIS |\n| Time series | Quản lý theo thời gian | Chứng khoán, IoT, log hệ thống |\n| New data types | JSON, XML, geometry, vector embedding | PostgreSQL JSONB; pgvector |\n| New query languages | Spatial query, graph query, similarity search | `ST_Distance()`, Cypher, FAISS |\n\n> 💡 **Hiểu đơn giản:** Section 5 nói \"DBMS quan hệ truyền thống\" mà bạn sắp học chỉ là **móng nhà**. Trên móng này người ta xây thêm: data warehouse, mining, spatial, multimedia, big data, NoSQL — và mỗi cái đẻ ra một họ DBMS riêng.\n\n### 5.4. Slide 41 — Summary\n\n**Nội dung slide gốc:**\n\n- File-based Approach and Database Approach\n- Three-Schema Architecture and Data Independence\n- Database Languages\n- Data Models Database Schema and Database State\n- Data Management Systems Framework\n- **Next week: ER Model**\n\n→ Slide 41 báo trước **chương 2 sẽ học ER Model** — mô hình ý niệm đầu tiên để thiết kế database. Đây là nội dung sẽ áp dụng trong BTL1 (`BTL1_DB_Lab/`).\n\n### 5.5. Slide 42 — Q & A\n\nSlide cuối chương — dành cho hỏi đáp. Không có nội dung mới.\n\n> 📝 **Tóm lại §5 (Framework):**\n> - 3 tầng: Application — Data Management — Supporting.\n> - Data Management chia 3 sub-layer (DB cơ bản → interoperability → extraction).\n> - Ứng dụng mới (image, video, spatial, time series) đòi hỏi mở rộng kiểu dữ liệu, query, storage, security.\n>\n> **Một câu ghi nhớ:** *Môn CO2013 đang dạy bạn Layer 1 (DB technologies cơ bản); cả \"đế chế\" data ngoài kia mọc lên từ tầng đó.*\n\n> ❓ **Tự kiểm tra §5:**\n> 19. Trong khung \"Where are we?\", \"Data Mining\" thuộc layer nào? Cần gì ở layer dưới?\n> 20. Kể 3 loại ứng dụng mới khiến DBMS cần mở rộng khả năng.\n> 21. Trong slide 39, `DB Systems` và `Distributed DB Systems` nằm ở layer nào?\n\n---\n\n","file":"materials/DB-Chapter1.md","section":6},{"id":"c1-07","group":"c1","kind":"source","title":"6. Bảng Tổng Hợp Thuật Ngữ Chương 1","markdown":"## 6. Bảng Tổng Hợp Thuật Ngữ Chương 1\n\n| STT | Thuật ngữ (EN) | Thuật ngữ (VI) | Định nghĩa ngắn | Slide # | Ví dụ trên COMPANY |\n|---:|---|---|---|---:|---|\n| 1 | File-based Approach | Cách tiếp cận dựa trên tập tin | Lưu data trong file riêng, app tự xử lý | 4–10 | Mỗi phòng có file `EMPLOYEE.txt` riêng |\n| 2 | Data Redundancy | Dư thừa dữ liệu | Cùng data lưu lặp nhiều nơi | 7 | Thông tin nhân viên lặp ở HR và Payroll |\n| 3 | Data Inconsistency | Không nhất quán dữ liệu | Các bản sao lệch nhau | 7 | File HR: `Dno=5`; file Project: `Dno=4` |\n| 4 | Shared File Approach | File dùng chung | Nhiều app dùng chung file để giảm lặp | 8–10 | Nhiều module cùng đọc `EMPLOYEE.dat` |\n| 5 | Rigid data structure | Cấu trúc cứng nhắc | File chung khó hợp mọi app | 10 | HR cần `Bdate`, payroll cần `Salary` |\n| 6 | Physical data dependency | Phụ thuộc vật lý | App phụ thuộc cách file lưu | 10 | Đổi cột trong `EMPLOYEE.txt` → app đọc sai |\n| 7 | Concurrency Control | Kiểm soát đồng thời | Phối hợp nhiều user/app cùng truy cập | 10, 15, 18 | 2 HR cùng sửa 1 nhân viên không ghi đè lỗi |\n| 8 | Database Approach | Tiếp cận CSDL | DBMS quản lý chung thay vì app đọc file | 11–19 | App truy cập `EMPLOYEE` qua DBMS |\n| 9 | Data | Dữ liệu | Sự kiện đã biết, ghi lại được, có ý nghĩa ngầm | 13 | `Ssn=123456789`, `Salary=30000` |\n| 10 | Database | Cơ sở dữ liệu | Shared collection of logically related data + description | 13 | COMPANY database |\n| 11 | Metadata | Siêu dữ liệu | Dữ liệu mô tả dữ liệu | 14 | `Ssn` là `CHAR(9)`, là PK |\n| 12 | System catalog | Danh mục hệ thống | Nơi DBMS lưu metadata/schema | 14, 17 | Catalog lưu `EMPLOYEE` có cột nào |\n| 13 | DBMS | Hệ quản trị CSDL | Software cho define, construct, manipulate, share, control DB | 14 | PostgreSQL/MySQL/Oracle quản lý COMPANY |\n| 14 | Database System | Hệ CSDL | Database + DBMS software | 15 | COMPANY data + PostgreSQL |\n| 15 | DDL | Ngôn ngữ định nghĩa | Define schema/constraints | 15, 32 | `CREATE TABLE EMPLOYEE` |\n| 16 | DML | Ngôn ngữ thao tác | Query/insert/delete/update | 15, 32–33 | `SELECT * FROM EMPLOYEE` |\n| 17 | DCL | Ngôn ngữ điều khiển | Grant/revoke quyền, commit/rollback | 32 | `GRANT SELECT ON EMPLOYEE TO HR` |\n| 18 | Procedural DML | DML thủ tục | Nói rõ HOW thao tác | 33 | Network/Hierarchical DML |\n| 19 | Non-Procedural DML | DML phi thủ tục | Nói WHAT cần | 33 | SQL, QBE |\n| 20 | 4GLs | Ngôn ngữ thế hệ 4 | SQL, QBE, generators | 33 | Report generator tạo báo cáo nhân viên |\n| 21 | DBA | Quản trị viên CSDL | Cấp quyền, theo dõi, mua tài nguyên, bảo mật | 16 | Cấp quyền cho HR đọc `EMPLOYEE` |\n| 22 | Database Designer | Thiết kế viên | Chọn data nào lưu + cấu trúc lưu | 16 | Quyết định khóa chính `Ssn` |\n| 23 | Application Programmer | Lập trình viên | Viết app dùng DBMS | 16 | Backend dev viết API |\n| 24 | End User | Người dùng cuối | Tương tác qua app | 16 | Nhân viên HR nhập hồ sơ |\n| 25 | Self-describing | Tự mô tả | DB chứa cả data lẫn metadata | 18 | Mở DB là biết schema |\n| 26 | Data Abstraction | Trừu tượng hóa | Program-data + program-operation independence | 18 | App viết SQL không cần biết block disk |\n| 27 | Data Model | Mô hình dữ liệu | Tập khái niệm mô tả data, relationship, constraint | 18, 35 | ER model, Relational model |\n| 28 | Object-based / Conceptual model | Mô hình đối tượng | ERD, OO — mức conceptual & external | 35 | ERD COMPANY |\n| 29 | Record-based / Representational | Mô hình bản ghi | Relational, Network, Hierarchical | 35 | Relational COMPANY |\n| 30 | Physical Data Model | Mô hình vật lý | Mức internal | 35 | B+ tree index, heap file |\n| 31 | View | Khung nhìn | Phần DB user thấy ở external | 18, 25 | HR view có `Salary`; Project view không |\n| 32 | External Schema | Lược đồ ngoài | Mô tả phần DB cho 1 user cụ thể | 24, 25 | HR view: `EMPLOYEE(Ssn, Fname, Salary)` |\n| 33 | Conceptual Schema | Lược đồ khái niệm | Mô tả cấu trúc DB cấp tổ chức | 24, 25 | Schema đầy đủ COMPANY |\n| 34 | Internal Schema | Lược đồ trong | Mô tả cấu trúc lưu trữ vật lý | 24, 26 | File `EMPLOYEE.dat` heap, B+ tree on `Ssn` |\n| 35 | Three-Schema Architecture | Kiến trúc 3 lược đồ | Kiến trúc ANSI/SPARC chia DB thành 3 mức | 24 | — |\n| 36 | Data Independence | Độc lập dữ liệu | Đổi schema 1 mức không phải đổi mức cao hơn | 28 | Thêm index không sửa app |\n| 37 | Logical Data Independence | Độc lập logic | External miễn nhiễm với đổi của Conceptual | 28, 30 | Thêm bảng `TRAINING_COURSE`; HR view không đổi |\n| 38 | Physical Data Independence | Độc lập vật lý | Conceptual miễn nhiễm với đổi của Internal | 29, 30 | Thêm index `Ssn`; schema logic không đổi |\n| 39 | External / Conceptual Mapping | Ánh xạ ngoài/khái niệm | Lớp dịch giữa external và conceptual; tạo Logical DI | 30 | Tính `age = today - DOB` |\n| 40 | Conceptual / Internal Mapping | Ánh xạ khái niệm/trong | Lớp dịch giữa conceptual và internal; tạo Physical DI | 30 | Map `EMPLOYEE` row → block trên đĩa |\n| 41 | Database Schema | Lược đồ CSDL | Mô tả DB, ít khi đổi | 36 | `EMPLOYEE(Fname, Lname, Ssn, Salary)` |\n| 42 | Schema Diagram | Sơ đồ lược đồ | Schema được vẽ ra | 36, 37 | Hình các bảng COMPANY |\n| 43 | Database State / Snapshot / Instance | Trạng thái / Thể hiện | Dữ liệu thật ở 1 thời điểm | 36 | `('John','Smith','123456789',30000,5)` |\n| 44 | Hierarchical Model | Mô hình phân cấp | DB thế hệ 1, dạng cây | 19 | IBM IMS (1968) |\n| 45 | Network Model | Mô hình mạng | DB thế hệ 1, đồ thị có hướng | 19, 20 | CODASYL DBMS |\n| 46 | Relational Model | Mô hình quan hệ | DB thế hệ 2, dạng bảng (chủ đạo) | 19, 21 | Oracle, MySQL, PostgreSQL |\n| 47 | Object-Relational Model | Mô hình OO-Relational | DB thế hệ 3, OO + Relational | 19 | PostgreSQL extensions |\n| 48 | Object-Oriented Model | Mô hình OO | DB thế hệ 3 thuần OO | 19 | Db4o |\n| 49 | Integrity System | Hệ thống toàn vẹn | Đảm bảo data hợp lệ | 15 | `CHECK(Salary > 0)` |\n| 50 | Recovery Control | Kiểm soát phục hồi | Khôi phục DB khi crash | 15 | WAL, redo log |\n\n---\n\n","file":"materials/DB-Chapter1.md","section":7},{"id":"c1-08","group":"c1","kind":"source","title":"7. Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## 7. Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\nĐề thi CO2013 (50% trắc nghiệm + tự luận, 90 phút) hay ra:\n\n1. **So sánh File-based vs Database Approach** — kể được ≥ 3 vấn đề của file-based, ≥ 3 đặc trưng của database.\n2. **5 vấn đề của file-based / shared file** — Redundancy, Inconsistency, Rigid structure, Physical dependency, No Concurrency.\n3. **Định nghĩa Database** — *shared collection of logically related data + description + designed to meet information needs*.\n4. **5 chức năng DBMS** — defining, constructing, manipulating, sharing, control access.\n5. **Database System = Database + DBMS software**.\n6. **Metadata / System catalog** giúp program-data independence.\n7. **Controlled access** — security, integrity, concurrency, recovery, user-accessible catalog.\n8. **4 vai trò** — DBA, Designer, Programmer, End User.\n9. **4 đặc trưng Database Approach** (slide 18) — *Self-describing, Insulation/Abstraction, Multiple views, Sharing & multi-user*.\n10. **Three-Schema Architecture** — vẽ + gọi tên 3 schema + 2 mapping.\n11. **Logical vs Physical Data Independence** — phân biệt + ví dụ.\n12. **DDL / DML / DCL** — kể câu lệnh SQL mỗi loại.\n13. **Procedural vs Non-Procedural DML** — SQL thuộc loại nào, vì sao.\n14. **3 loại Data Model** — Object-based / Record-based / Physical, phân loại được ví dụ.\n15. **Schema vs State** — phân biệt qua ví dụ.\n16. **3 thế hệ DBMS** — kể tên + đại diện.\n\n---\n\n","file":"materials/DB-Chapter1.md","section":8},{"id":"c1-09","group":"c1","kind":"source","title":"8. Bảng Tra Nhanh (Quick Reference)","markdown":"## 8. Bảng Tra Nhanh (Quick Reference)\n\n| Khái niệm | 1-dòng định nghĩa | Ký hiệu/Ví dụ ngắn | Slide |\n|---|---|---|---:|\n| Data | Sự kiện thô có ý nghĩa ngầm | `Salary=30000` | 13 |\n| Database | Shared logically related data + metadata, phục vụ tổ chức | COMPANY DB | 13 |\n| DBMS | Phần mềm define/construct/manipulate/share DB | PostgreSQL | 14 |\n| DBSystem | Database + DBMS | COMPANY + PostgreSQL | 15 |\n| Metadata | Data về data | `Ssn` là `CHAR(9)` | 14 |\n| DDL | Định nghĩa schema | `CREATE TABLE` | 15, 32 |\n| DML | Truy vấn/cập nhật | `SELECT`, `INSERT` | 15, 32 |\n| DCL | Quyền + transaction | `GRANT`, `COMMIT` | 32 |\n| Procedural DML | Nói HOW | Network DML | 33 |\n| Non-Procedural DML | Nói WHAT | SQL | 33 |\n| External level | View của user | HR view | 24, 25 |\n| Conceptual level | Schema toàn tổ chức | EMPLOYEE/DEPARTMENT/PROJECT | 24, 25 |\n| Internal level | Cách lưu vật lý | Heap file + B+ tree | 24, 26 |\n| Logical DI | External miễn nhiễm với đổi Conceptual | Thêm bảng `TRAINING` | 28 |\n| Physical DI | Conceptual miễn nhiễm với đổi Internal | Thêm index | 29 |\n| Schema | Mô tả DB, ít đổi | `EMPLOYEE(Ssn,Fname,...)` | 36 |\n| State | Data tại 1 thời điểm, đổi liên tục | dòng cụ thể | 36 |\n| Data Model | Khung khái niệm để mô tả | ER, Relational | 35 |\n| Self-describing | DB chứa cả data + metadata | open DB ⇒ biết schema | 18 |\n| Data Abstraction | program-data + program-operation independence | SQL không cần biết disk | 18 |\n| Multiple views | Mỗi user 1 view | HR vs Payroll | 18 |\n| Concurrency Control | Nhiều user cùng lúc không phá nhau | Locking | 10, 15, 18 |\n\n---\n\n","file":"materials/DB-Chapter1.md","section":9},{"id":"c1-10","group":"c1","kind":"source","title":"9. Sai lầm thường gặp (Common Mistakes)","markdown":"## 9. Sai lầm thường gặp (Common Mistakes)\n\n| # | Sai lầm | Tại sao sai | Cách đúng |\n|---|---|---|---|\n| 1 | Nghĩ \"Database\" = \"DBMS\" | Database là **dữ liệu**; DBMS là **phần mềm quản lý** dữ liệu. | Nhớ: *Database System = Database + DBMS software*. |\n| 2 | Nói \"Schema\" và \"State\" giống nhau | Schema là cấu trúc, ít đổi. State là dữ liệu, đổi liên tục. | Mỗi lần INSERT → state đổi, schema không đổi. |\n| 3 | Nói \"Network model = relational model có mũi tên\" | Network dùng **con trỏ thật** giữa record. Relational dùng **giá trị trùng** giữa bảng. | Xem slide 20 vs 21: cùng database, cách biểu diễn khác. |\n| 4 | Nhầm Logical DI với Physical DI | Logical = đổi conceptual không ảnh hưởng external. Physical = đổi internal không ảnh hưởng conceptual. | Xem mức nào ĐỔI, mức nào ĐƯỢC BẢO VỆ. |\n| 5 | Nghĩ \"thêm index = thay đổi conceptual schema\" | Index nằm ở **internal level**, không phải conceptual. | Đây là Physical DI — schema logic không đổi. |\n| 6 | Nói \"SQL chỉ là DML\" | SQL có cả DDL (`CREATE`), DML (`SELECT`), DCL (`GRANT`). | SQL gói chung 3 nhóm. |\n| 7 | Cho rằng Procedural DML mạnh hơn Non-Procedural | Non-procedural tận dụng query optimizer, code ngắn, ít bug. | Đó là lý do SQL thắng. |\n| 8 | Vẽ 3-schema mà không có mappings | Mappings là **lớp dịch** giữa các schema; tạo data independence. | Phải có external/conceptual mapping + conceptual/internal mapping. |\n| 9 | Nghĩ \"Q&A slide\" và \"Summary slide\" không cần đếm | Mọi slide đều cần đếm; chương 1 có 42 slide. | Slide 41 = Summary, slide 42 = Q&A. |\n| 10 | Coi \"physical data organization\" = \"internal schema\" | Internal schema là **mô tả** về cách lưu. Physical data organization là **bit thật trên đĩa**. | Internal vẫn là schema; nằm trên physical. |\n\n---\n\n","file":"materials/DB-Chapter1.md","section":10},{"id":"c1-11","group":"c1","kind":"source","title":"10. Bài tập tự luyện có lời giải","markdown":"## 10. Bài tập tự luyện có lời giải\n\n> **Bài 1 (mức độ: dễ — trắc nghiệm):**\n> Đặc trưng nào sau đây **KHÔNG** thuộc về Database Approach (theo slide 18)?\n> A. Self-describing nature\n> B. Insulation between programs and data\n> C. Tight coupling between application code and physical storage\n> D. Multiple views of the data\n>\n> <details><summary>Lời giải</summary>\n>\n> **C.** Đặc trưng đúng của Database Approach là *Insulation* (B) — tức **không** tight coupling. Tight coupling là đặc trưng của file-based approach.\n> </details>\n\n> **Bài 2 (dễ — tự luận ngắn):**\n> Phân biệt Data Redundancy và Data Inconsistency. Cái nào là nguyên nhân, cái nào là hậu quả?\n>\n> <details><summary>Lời giải</summary>\n>\n> **Data Redundancy** *(dư thừa)*: dữ liệu lưu lặp ở nhiều nơi. **Là nguyên nhân**.\n> **Data Inconsistency** *(không nhất quán)*: các bản sao lệch nhau. **Là hậu quả** — khi update bản này quên bản kia.\n> Không thể có Inconsistency mà không có Redundancy trước.\n> </details>\n\n> **Bài 3 (trung bình — tình huống):**\n> Một công ty đang dùng database COMPANY trên Oracle. DBA quyết định:\n> (a) Thêm B+ tree index trên `EMPLOYEE(Ssn)`.\n> (b) Thêm bảng mới `TRAINING_COURSE` để lưu khóa đào tạo.\n> (c) Đổi storage device từ HDD sang SSD.\n> Hỏi: mỗi thay đổi cần loại data independence nào để **app đang chạy không phải sửa code**?\n>\n> <details><summary>Lời giải</summary>\n>\n> - (a) **Physical DI** — index ở internal level; conceptual schema không đổi.\n> - (b) **Logical DI** — thêm entity ở conceptual level; external schema cũ (chỉ xem `EMPLOYEE`) không cần đổi.\n> - (c) **Physical DI** — đổi storage device thuộc internal; conceptual schema không đổi.\n>\n> Tóm lại: Physical DI bảo vệ trước (a) và (c); Logical DI bảo vệ trước (b).\n> </details>\n\n> **Bài 4 (trung bình — vẽ + giải thích):**\n> Vẽ Three-Schema Architecture (3 schema + 2 mapping) và đặt tên loại data independence cho mỗi mapping. Sau đó cho 1 ví dụ thay đổi tương ứng từng mapping.\n>\n> <details><summary>Lời giải</summary>\n>\n> ```\n> External schema 1   External schema 2   External schema 3\n>        \\                  |                  /\n>         \\________________ | ________________/\n>                            |\n>          External / Conceptual mapping ← Logical Data Independence\n>                            |\n>                  Conceptual schema\n>                            |\n>          Conceptual / Internal mapping ← Physical Data Independence\n>                            |\n>                    Internal schema\n>                            |\n>                  Physical data organization\n> ```\n>\n> Ví dụ:\n> - Đổi `External / Conceptual mapping`: thêm bảng `TRAINING_COURSE` → mapping cho HR view (chỉ xem `EMPLOYEE`) phải biết bỏ qua bảng mới.\n> - Đổi `Conceptual / Internal mapping`: thêm B+ tree index trên `EMPLOYEE(Ssn)` → mapping cho phép DBMS dùng index khi xử lý câu `SELECT ... WHERE Ssn = ?`.\n> </details>\n\n> **Bài 5 (khó — phân tích):**\n> Một SV nói: *\"Em chỉ cần học DDL là đủ vì DDL tạo bảng — quan trọng nhất.\"* Bạn phản biện thế nào? Liệt kê 3 lý do DML và DCL cũng quan trọng.\n>\n> <details><summary>Lời giải</summary>\n>\n> 1. **Không có DML** thì DBMS chỉ là \"kho chữ\" trống — không truy vấn được, không cập nhật được. SV không thể trả lời câu hỏi nghiệp vụ kiểu \"có bao nhiêu nhân viên phòng Research?\".\n> 2. **Không có DCL** thì mọi user có quyền như DBA — không có security, không có transaction. Hai HR cùng cập nhật → ghi đè nhau (vì không có `COMMIT`/`ROLLBACK`).\n> 3. **Trên thực tế**, DDL chỉ chạy 1 lần lúc thiết kế; DML chạy hàng triệu lần mỗi ngày trong production; DCL chạy mỗi lần phân quyền + mỗi giao dịch. → Tỷ lệ thời gian dev viết code: DML ≫ DCL ≫ DDL.\n> </details>\n\n---\n\n","file":"materials/DB-Chapter1.md","section":11},{"id":"c1-12","group":"c1","kind":"source","title":"11. Câu Hỏi Ôn Tập (từ slide gốc)","markdown":"## 11. Câu Hỏi Ôn Tập (từ slide gốc)\n\nPDF chương 1 không có section \"Review questions\" riêng (chỉ có slide Q&A 42). Tổng hợp từ Summary (slide 41) và đề cương CO2013 (mục 1.8 *Self-study requirements: 8 hours*):\n\n1. So sánh File-based Approach và Database Approach (≥ 4 tiêu chí).\n2. Liệt kê và giải thích 4 characteristics của Database Approach (slide 18).\n3. Vẽ và giải thích Three-Schema Architecture (slide 24, 30).\n4. Phân biệt Logical Data Independence và Physical Data Independence; cho ví dụ mỗi loại.\n5. So sánh DDL, DML, DCL — mỗi loại 2 câu lệnh SQL ví dụ.\n6. Phân biệt Schema và State qua ví dụ DB trường đại học.\n7. Liệt kê và giải thích các vai trò trong môi trường CSDL (slide 16).\n8. Kể tên 3 thế hệ DBMS và đặc điểm chính của mỗi thế hệ.\n9. Phân biệt Data Model, Database Schema, và Database State.\n10. Trong framework slide 39, DB Systems thuộc layer nào?\n\n---\n\n","file":"materials/DB-Chapter1.md","section":12},{"id":"c1-13","group":"c1","kind":"source","title":"12. Đáp án Tự kiểm tra","markdown":"## 12. Đáp án Tự kiểm tra\n\n### §1 (câu 1–6)\n\n**1. Redundancy vs Inconsistency:** Redundancy là **nguyên nhân** (dữ liệu lặp). Inconsistency là **hậu quả** (các bản copy lệch nhau). Không thể có inconsistency mà không có redundancy trước.\n\n**2. Shared File:** Giải quyết được redundancy nội dung và inconsistency cross-version. Vẫn còn 3 vấn đề: Rigid data structure, Physical data dependency, No concurrency control.\n\n**3. Slide 5:** Đây là minh họa cho **Data Redundancy** + **Data Inconsistency**. `Client` lưu ở 2 nơi với 2 schema khác nhau → khi đổi `telNo`, nếu chỉ sửa 1 file → 2 bản lệch.\n\n**4. 4 đặc trưng + tiền đề DI:** Self-describing, Insulation+Abstraction, Multiple views, Sharing+multi-user. **\"Insulation + Data Abstraction\"** là tiền đề trực tiếp cho data independence: chương trình \"cách ly\" với data → đổi cấu trúc data không bắt sửa code.\n\n**5. DBA vs Designer (Oracle → PostgreSQL):** Designer review schema (kiểm tra type Oracle-specific như `NUMBER(10,2)` → PostgreSQL `NUMERIC(10,2)`). DBA migrate data, set up cluster, training, đổi connection string.\n\n**6. Network vs Relational:** Network dùng **set + mũi tên có hướng** giữa record types — duyệt bằng \"đi theo mũi tên\" (procedural). Relational dùng **bảng có giá trị trùng** giữa các bảng — truy vấn declarative bằng JOIN. Relational thắng vì đơn giản, không cần con trỏ vật lý, dễ dùng SQL.\n\n### §2 (câu 7–10)\n\n**7. Age không có ở Conceptual:** Vì lưu age sẽ phải update mỗi sinh nhật. Lưu DOB rồi tính `age = today - DOB`. External view 1 thấy age nhờ external/conceptual mapping suy ra. **KHÔNG vi phạm 3-schema** — đây là minh họa đẹp cho derived attribute ở external level.\n\n**8. Oracle → PostgreSQL:** Đổi DBMS engine ảnh hưởng **chủ yếu Internal level**. Conceptual schema **không nhất thiết đổi** — đây là cái mà **Physical DI** đỡ đòn. Tuy nhiên một số tính năng Oracle-only (PL/SQL packages) có thể buộc đổi cả conceptual.\n\n**9. SAI.** Logical DI **khó hơn** Physical DI. Lý do: external schema gắn chặt với code app (SELECT viết theo cột nào của bảng nào). Khi conceptual đổi (xóa bảng, đổi tên cột) → external mapping rất khó \"tự bù đắp\" nếu không có view phức tạp. Physical DI chỉ cần DBMS update conceptual/internal mapping.\n\n**10. Index `EMPLOYEE(Ssn)` = Physical DI** — index ở internal level, conceptual + external không đổi.\n\n### §3 (câu 11–14)\n\n**11. SQL ví dụ 3 loại:**\n- DDL: `CREATE TABLE Employee (Ssn INT PRIMARY KEY, Name VARCHAR(50));`\n- DML: `SELECT * FROM Employee WHERE Salary > 30000;`\n- DCL: `GRANT SELECT ON Employee TO Lan;` hoặc `COMMIT;`\n\n**12. CREATE TABLE = DDL** vì định nghĩa cấu trúc dữ liệu/schema.\n\n**13. SELECT ... WHERE Dno = 5 = Non-Procedural** — chỉ nói WHAT cần, không nói HOW lấy.\n\n**14. Non-Procedural thắng vì:** (a) user/dev không cần biết cấu trúc lưu trữ; (b) DBMS có **query optimizer** tự chọn cách thực thi tối ưu (index nào, JOIN order nào); (c) code ngắn hơn, ít bug; (d) đổi index/cấu trúc không phải sửa query.\n\n### §4 (câu 15–18)\n\n**15. Data Model vs Schema:** Data Model là **bộ khái niệm** (Relational, ER, Network). Schema là **mô tả cụ thể** của 1 DB viết theo data model đó.\n\n**16. Schema ít đổi vs State đổi liên tục:** Schema là bản thiết kế, đổi khi nghiệp vụ đổi (vài tháng/năm). State là dữ liệu — mỗi INSERT/UPDATE/DELETE thì state đổi (mỗi giây).\n\n**17. COMPANY:** `EMPLOYEE(Fname,Lname,Ssn,Salary)` là **schema**. Dòng `('John','Smith','123456789',30000)` là **state/instance**.\n\n**18. Ví dụ trường ĐH:**\n- Schema STUDENT: `(Name, Student_number, Class, Major)` — cố định cả học kỳ.\n- State 8h sáng: 5000 SV. State 8h30 (sau khi 1 SV mới đăng ký): 5001 SV. Schema không đổi, state đã đổi.\n\n### §5 (câu 19–21)\n\n**19. Data Mining = Layer 3** (information extraction & sharing). Cần **Layer 1** (DB technologies cơ bản — chính là CO2013) + **Layer 2** (interoperability — vì mining tổng hợp từ nhiều DB nguồn).\n\n**20. 3 ứng dụng mới:** lưu trữ ảnh-video, data mining, spatial databases, time series applications (chọn 3).\n\n**21. DB Systems + Distributed DB Systems = Data Management Layer 1: DB technologies**.\n\n---\n\n","file":"materials/DB-Chapter1.md","section":13},{"id":"c1-14","group":"c1","kind":"source","title":"13. Mối Quan Hệ Với Các Chương Khác — Liên kết Lab/BTL","markdown":"## 13. Mối Quan Hệ Với Các Chương Khác — Liên kết Lab/BTL\n\n### Chương trước / sau\n\n| Chương | Liên hệ với chương 1 |\n|---|---|\n| **Chương 0 — Introduction** | Tổng quan vai trò DB. Chương 1 đi sâu hơn vào **kiến trúc** + **vì sao** DB ra đời. |\n| **Chương 2 — ER Model** | Slide 41 báo trước. Chương 2 dạy cách **xây Conceptual schema** bằng Entity-Relationship Model. Chương 1 nói \"có conceptual schema\", chương 2 dạy \"vẽ nó ra\". |\n| **Chương 3 — EER Model** | Mở rộng ER với specialization, generalization, category — vẫn ở conceptual level. |\n| **Chương 4 — Relational Mapping** | Dịch ER schema → relational schema = từ Object-based (slide 35) → Record-based. |\n| **Chương 5 — Relational Algebra** | Procedural query language ở relational model (đối lập với SQL declarative). |\n| **Chương 6 — SQL** | DDL (`CREATE`), DML (`SELECT`), DCL (`GRANT`) mà chương 1 chỉ giới thiệu — chương 6 dạy chi tiết. |\n| **Chương 7 — FD & Normalization** | Giải quyết bài toán *Data Redundancy* mà chương 1 nêu — bằng cách hình thức (FD, BCNF). |\n| **Chương 8 — Storage & Indexing** | Đi sâu vào **Internal level** — file organization, B+ tree, hash. Là tầng dưới cùng trong 3-schema. |\n\n### Liên kết với Lab và BTL\n\n| Hoạt động | Phần nào của chương 1 dùng tới |\n|---|---|\n| **Lab 1, Lab 2** (`Labs/`) | SQL = DDL + DML + DCL (slide 15, 32). Chương 1 đặt tên khái niệm; chương 6 dạy chi tiết SQL. |\n| **BTL1** (`BTL1_DB_Lab/`) | Thiết kế DB từ ER → Relational. Hiểu **vì sao** dùng database approach (slide 11) thay vì file Excel. Hiểu **roles** (slide 16) để chia việc trong nhóm. |\n| **BTL2** (`BTL2_DB_Lab/`) | Cài đặt SQL trên DBMS thật. Hiểu **DBMS components** (slide 17) để biết câu SQL đi qua đâu. |\n| **Tutorial** (in-class) | Câu hỏi ôn tập slide 42 (Q&A) — thường lặp lại các câu trong §11 trên. |\n\n### Concept của chương 1 sẽ \"thấy lại\" ở đâu\n\n| Concept chương 1 | Tái hiện ở |\n|---|---|\n| Schema vs State | Chương 4 (relation schema vs instance), chương 7 (functional dependency holds trên schema, không trên state) |\n| Three-Schema | Chương 6 (`CREATE VIEW` = external schema), chương 8 (`CREATE INDEX` = internal schema) |\n| Data Independence | Chương 6 (view + ALTER TABLE), chương 8 (đổi storage không sửa query) |\n| DBA / Designer / Programmer / End User | Chương 6 (DCL, security), trong nhóm BTL: ai làm role nào |\n| Data Redundancy | Chương 7 — lý do gốc của Normalization |\n| Network model con trỏ | Chương 8 — file organization có pointer giữa block |\n\n---\n\n","file":"materials/DB-Chapter1.md","section":14},{"id":"c1-15","group":"c1","kind":"source","title":"14. Phụ lục — Mapping 42 slide → Section trong tài liệu này","markdown":"## 14. Phụ lục — Mapping 42 slide → Section trong tài liệu này\n\n| Slide | Nội dung | Section trong file này |\n|---:|---|---|\n| 1 | Chapter title | Header tài liệu |\n| 2 | Outline | §0.4 (gộp) |\n| 3 | Outline | §0.4 (gộp) |\n| 4 | File-based Approach definition | §1.2 |\n| 5 | File-based diagram + Sales/Contracts | §1.3 |\n| 6 | File-based 4 application | §1.4 |\n| 7 | Problems/Limitations | §1.5 |\n| 8 | Shared file diagram | §1.6 |\n| 9 | Shared File benefits | §1.7 |\n| 10 | Shared File remaining problems | §1.8 |\n| 11 | Database Approach motivation | §1.9 |\n| 12 | Database Approach diagram | §1.10 |\n| 13 | Data + Database definition | §1.11 |\n| 14 | Metadata, logically related, DBMS | §1.12 |\n| 15 | DDL/DML/Controlled access/DBSystem | §1.13 |\n| 16 | Roles in DB Environment | §1.14 |\n| 17 | DBMS components diagram | §1.15 |\n| 18 | Characteristics of Database Approach | §1.16 |\n| 19 | History of database systems | §1.17 |\n| 20 | Network Model Schema | §1.18 |\n| 21 | Relational Model instance tables | §1.19 |\n| 22 | Outline | §0.4 (gộp) |\n| 23 | Three-Schema objectives | §2.2 |\n| 24 | Three-level architecture | §2.3 |\n| 25 | External + Conceptual level | §2.4 |\n| 26 | Internal level | §2.4 |\n| 27 | STAFF 3-level example | §2.5 |\n| 28 | Data Independence + Logical DI | §2.6 |\n| 29 | Physical Data Independence | §2.7 |\n| 30 | Mappings + 2 DI types | §2.8 |\n| 31 | Outline | §0.4 (gộp) |\n| 32 | DDL/DML/DCL | §3.2 |\n| 33 | Procedural/Non-Procedural/4GLs | §3.3 |\n| 34 | Outline | §0.4 (gộp) |\n| 35 | Data Model categories | §4.2 |\n| 36 | Schema/Schema diagram/State | §4.3 |\n| 37 | Student-course schema diagram | §4.4 |\n| 38 | Outline | §0.4 (gộp) |\n| 39 | Data Management Systems Framework | §5.2 |\n| 40 | Extending DB capabilities | §5.3 |\n| 41 | Summary | §5.4 |\n| 42 | Q & A | §5.5 |\n\n---\n\n","file":"materials/DB-Chapter1.md","section":15},{"id":"c1-16","group":"c1","kind":"source","title":"15. Bảng so sánh nguồn (Prompt 3 — audit table)","markdown":"## 15. Bảng so sánh nguồn (Prompt 3 — audit table)\n\n| Section / Nội dung | A (Claude pass1) | B (CO2013) | Nguồn được chọn | Ghi chú |\n|---|---|---|---|---|\n| 0.1 Prerequisite | ✅ có | ✅ có (table) | A+B | Ghép cấu trúc table B + insight A |\n| 0.3 Lộ trình đọc | ✅ có | ✅ có | A+B | Lấy A có time + ghi chú \"khó nhất\" rõ |\n| §1.x slide-by-slide | gộp theo concept | ✅ chi tiết per slide | **B** | B làm khung |\n| Hình 1.1–1.4 (slide 5,6,8,12) | ASCII đẹp | Mermaid | **B Mermaid** + tham khảo bảng A |\n| Hình 1.5 (slide 17 components) | ASCII chi tiết | Mermaid đơn | **A ASCII** đầy đủ hơn |\n| Hình 2.2 (STAFF slide 27) | ASCII + C code | Bảng + C code | **A** ASCII trực quan hơn |\n| Hình 2.3 (mappings slide 30) | Mermaid | Mermaid (khác structure) | **A** Mermaid (lồng thông tin LDI/PDI) |\n| Slide 21 (4 instance tables) | ✅ đủ | ✅ đủ | A=B | Giống nhau |\n| Slide 37 (schema diagram) | ASCII | Mermaid `erDiagram` | **B Mermaid** đẹp hơn |\n| Analogy đời thường | nhiều (Grab, kho, nhà hàng, xây nhà) | có (nhưng ít hơn) | **A** | Mermaid B + analogy A |\n| Bảng tổng hợp thuật ngữ | 43 hàng, không có cột COMPANY | 34 hàng, có cột COMPANY | A+B | Union → 50 hàng có COMPANY |\n| Đáp án tự kiểm tra | 14 câu chi tiết, có giải thích sâu | 15 câu ngắn | **A** chi tiết + B union các câu mới |\n| Phụ lục 42-slide map | không có | ✅ có | **B** |\n| TH2 Bảng tra nhanh | không có | không có | **tự sinh** |\n| TH3 Sai lầm thường gặp | không có | không có | **tự sinh** (10 sai lầm) |\n| TH4 Bài tập có lời giải | không có | không có | **tự sinh** (5 bài) |\n| TH5 Liên kết Lab/BTL | có (ngắn) | có (chung) | A+B union → bảng chi tiết |\n\n---\n\n","file":"materials/DB-Chapter1.md","section":16},{"id":"c1-17","group":"c1","kind":"source","title":"16. Checklist tổng hợp cuối cùng","markdown":"## 16. Checklist tổng hợp cuối cùng\n\n### ✅ Checklist nội dung (so với 2 nguồn)\n\n| Hạng mục | A | B | Bản tổng hợp | Yêu cầu |\n|---|---:|---:|---:|---|\n| Số section đánh số lớn | 5 | 5 | 5 | ≥ max | ✅ |\n| Số diagram được mô tả | 10 | 13 | 13 | ≥ max | ✅ |\n| Số ví dụ COMPANY | 6 | 12 | 14 | ≥ max | ✅ |\n| Số analogy đời thường | 9 | 7 | 9 | ≥ max | ✅ |\n| Số đoạn SQL code | 4 | 5 | 6 | ≥ max | ✅ |\n| Số công thức RA / FD | 0 | 0 | 0 | (chương 1 không có) | ✅ |\n| Số thuật ngữ glossary | 43 | 34 | **50** | ≥ max | ✅ vượt |\n| Số câu hỏi tự kiểm tra | 14 | 15 | 21 | ≥ max | ✅ |\n| Mapping 42 slide → section | 0 | 42 | 42 | bắt buộc có | ✅ |\n\n### ✅ Checklist riêng cho TỰ HỌC\n\n| Hạng mục | Đạt? |\n|---|---|\n| Có **0.1 Prerequisite** | ✅ |\n| Có **0.2 Learning Outcomes** | ✅ |\n| Có **0.3 Lộ trình đọc** | ✅ |\n| Có **Bảng tra nhanh** cuối chương (§8) | ✅ |\n| Có **Sai lầm thường gặp** (§9) | ✅ |\n| Có **≥ 3 bài tập tự luyện có lời giải** (§10 — 5 bài) | ✅ |\n| Có **liên kết Lab/BTL** (§13) | ✅ |\n| Mọi concept trừu tượng có analogy | ✅ |\n| Mọi thuật ngữ lần đầu có VN trong ngoặc | ✅ |\n| Có **Đáp án Tự kiểm tra** (§12) | ✅ |\n| Ví dụ dùng schema thật của slide (DreamHome, University) hoặc COMPANY (chuẩn môn) | ✅ |\n| Phụ lục mapping 42 slide → section (§14) | ✅ |\n| **Tự đánh giá: SV mất gốc đọc sẽ hiểu được?** | ✅ |\n\n---\n\n> **File này là bản TỔNG HỢP CUỐI CÙNG** cho Chương 1, ghép từ 2 nguồn:\n> 1. `_drafts/DB-Chapter1-claude-pass1.md` (bản A — Claude, sau Prompt 1)\n> 2. `_drafts/CO2013_Chuong1_Database_System_Concepts_and_Architecture.md` (bản B — nguồn ngoài)\n>\n> Sau khi finalize, có thể xóa 2 file `_drafts/` nếu không cần giữ làm reference.\n","file":"materials/DB-Chapter1.md","section":17},{"id":"guide-1","group":"c1","kind":"guide","title":"Nền tảng & kiến trúc","markdown":"# 01 · Từ file rời đến một hệ cơ sở dữ liệu\n\n> Đọc cùng **DB-Chapter1.md**. Mục tiêu của buổi học: giải thích được vì sao cần DBMS, phân biệt schema với state và chỉ ra đúng tầng bị thay đổi khi sửa hệ thống.\n\n![Ba tầng kiến trúc và hai loại độc lập dữ liệu](../docs/assets/architecture.svg)\n\n## Một vấn đề cụ thể trước khi học thuật ngữ\n\nPhòng đào tạo có `students.csv`, thư viện có `borrowers.csv`. Cả hai đều lưu tên và email của cùng sinh viên. Khi sinh viên đổi email, một phòng cập nhật và phòng kia quên. Đây là **inconsistency**. Việc lưu cùng một sự kiện nhiều lần tạo **redundancy**, nhưng dư thừa không tự động có nghĩa là sai: sao lưu và bản sao phục vụ đọc vẫn có ích nếu có cơ chế đồng bộ.\n\nNếu hai người cùng đọc số chỗ trống bằng 1 rồi cùng ghi bằng 0, hệ thống có thể bán hai suất cuối. Đây là vấn đề **concurrency**; chỉ gom các CSV vào một thư mục chung không giải quyết được. DBMS cung cấp cơ chế quản lý truy cập, ràng buộc, giao dịch và phục hồi. Ứng dụng vẫn phải chọn transaction và isolation phù hợp.\n\n| Khái niệm | Câu hỏi nó trả lời | Ví dụ |\n|---|---|---|\n| Database | Dữ liệu liên quan nào đang được lưu? | Sinh viên, môn, đăng ký |\n| DBMS | Phần mềm nào quản lý chúng? | SQLite, PostgreSQL |\n| Schema | Những cấu trúc và quy tắc nào được khai báo? | `Student(id, name)` |\n| State / instance | Hiện tại có những hàng nào? | `(1, 'An'), (2, 'Bình')` |\n| Metadata | Dữ liệu được mô tả thế nào? | Tên cột, kiểu, khóa, index |\n\n## Ba tầng: đừng nhầm với frontend, backend và database\n\n**External schema** mô tả góc nhìn của một nhóm người dùng, chẳng hạn giảng viên chỉ xem sinh viên trong lớp mình. **Conceptual schema** mô tả toàn bộ cấu trúc logic của CSDL. **Internal schema** mô tả cách tổ chức lưu trữ và đường truy cập. Đây là ba mức mô tả dữ liệu, không phải ba máy chủ.\n\nThêm index để truy vấn nhanh hơn là thay đổi tầng internal. Nếu ứng dụng vẫn chạy cùng SQL và thấy cùng dữ liệu, đó là **physical data independence**. Tách bảng nhưng duy trì view tương thích cho ứng dụng cũ minh họa **logical data independence**; thực hiện điều này thường khó hơn.\n\n```sql\n-- SQLite; chạy trên COMPANY bằng python tools/lab.py --query \"...\"\nSELECT name, type FROM sqlite_master\nWHERE type IN ('table', 'index') ORDER BY type, name;\n```\n\nTruy vấn trên đọc catalog, không đọc danh sách nhân viên. `CREATE TABLE` là DDL, `INSERT/UPDATE/DELETE/SELECT` thuộc nhóm thao tác dữ liệu theo cách phân loại dùng ở đây; `GRANT/REVOKE` là DCL, `COMMIT/ROLLBACK` là TCL. Một số giáo trình đặt SELECT vào DQL: khác biệt nhãn gọi không làm thay đổi hành vi câu lệnh.\n\n## Lần theo một yêu cầu từ người dùng đến đĩa\n\nNgười dùng muốn xem nhân viên phòng Research. Ứng dụng gửi SQL; parser kiểm tra cú pháp, hệ thống kiểm tra tên/kiểu/quyền; optimizer chọn một kế hoạch tương đương; execution engine thao tác qua buffer và storage manager. Đây là cách giải thích khái quát, không phải thứ tự bắt buộc của mọi bước trong mọi DBMS.\n\n```sql\nSELECT e.Fname, e.Lname\nFROM EMPLOYEE AS e JOIN DEPARTMENT AS d ON d.Dnumber=e.Dno\nWHERE d.Dname='Research' ORDER BY e.Fname;\n```\n\nKết quả gồm Franklin, John, Joyce, Ramesh. `ORDER BY` làm thứ tự có thể đối chiếu; nếu bỏ nó, đừng dựa vào thứ tự hiển thị tình cờ.\n\n## Bài tập tự giải trước khi mở đáp án\n\n1. Thêm `CREATE INDEX ix_employee_dno ON EMPLOYEE(Dno)` có thay đổi conceptual schema không?\n2. Thêm cột `Email` và buộc mọi chương trình phải sửa có chứng minh logical independence không?\n3. Hai hệ thống cùng lưu email có nhất thiết là thiết kế sai không?\n4. Chỉ ra schema và state trong một bảng điểm.\n\n<details><summary>Lời giải và cách lập luận</summary>\n\n1. Theo mô hình ba mức, index thuộc thiết kế vật lý/đường truy cập; có thể đạt physical independence.\n2. Không. Tình huống này cho thấy ứng dụng đang bị ảnh hưởng bởi thay đổi logic.\n3. Không. Có thể là replication chủ đích; cần xác định nguồn chuẩn và cơ chế nhất quán.\n4. Schema là các cột, miền giá trị, khóa và ràng buộc; state là các bản ghi điểm tại một thời điểm.\n\n</details>\n\n## Điểm tự kiểm tra\n\nBạn nên giải thích được bằng ví dụ riêng: redundancy ≠ inconsistency, schema ≠ state, logical ≠ physical independence. Sau đó mở bài gốc để học các vai trò DBA, data model và framework quản lý dữ liệu đầy đủ.\n","file":"lessons/01-foundations.md"},{"id":"c2-00","group":"c2","kind":"source","title":"Chương 2: Mô hình Thực thể–Mối liên kết — Entity-Relationship (ER) Model","markdown":"# Chương 2: Mô hình Thực thể–Mối liên kết — Entity-Relationship (ER) Model\n\n> **Nguồn:** CO2013 Database Systems, HCMUT — Giảng viên: TS. Trần Minh Quang\n> **Giáo trình tham khảo:** Elmasri & Navathe, *Fundamentals of Database Systems*, 7th Edition (chương 7).\n> **Số slide trong PDF gốc:** 91. Slide Contents lặp lại (slide 2, 3, 4, 11, 17, 20, 54, 69, 79, 88) đã được gộp thành 1 mục lục duy nhất.\n> **Mục tiêu:** Sinh viên năm 2 chưa từng học CSDL — đọc bản này một mạch là hiểu được toàn bộ chương ER, vẽ được ERD, sẵn sàng làm Lab 1 và phần ER của BTL1, KHÔNG cần mở slide gốc hay sách Elmasri.\n\n---\n\n","file":"materials/DB-Chapter2.md","section":0},{"id":"c2-01","group":"c2","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nChương ER đứng trên vai chương 0 và 1. Hãy nhớ lại nhanh các concept sau:\n\n| Concept | Nhớ trong 1 câu | Vì sao cần cho chương 2? |\n|---|---|---|\n| **Database (CSDL)** | Tập dữ liệu liên quan logic, dùng chung — không phải file Excel rời. | ERD quyết định *dữ liệu nào* cần lưu. |\n| **DBMS** | Phần mềm trung gian giữa user và dữ liệu (PostgreSQL, MySQL…). | ERD chưa phụ thuộc DBMS — đó là điểm mạnh. |\n| **Schema vs Instance** | Schema = bản thiết kế; Instance = dữ liệu cụ thể. | ERD chính là một *conceptual schema*. |\n| **3-level architecture** | External / Conceptual / Internal. | Chương này chỉ làm việc ở tầng **Conceptual**. |\n| **Set theory & logic** (toán rời rạc) | Tập, phần tử ∈ tập, tích Descartes. | *Entity set* và *relationship set* về bản chất là tập. |\n| **Lập trình cơ bản** (C/C++/Python) | Quen `struct` / `class`. | Entity ≈ \"struct trừu tượng\" trước khi biết lưu thế nào. |\n\n> 💡 **Hiểu đơn giản:** Chương 1 cho biết \"CSDL là gì, kiến trúc tổng thể\"; chương 2 này cho biết **bước đầu tiên khi tự thiết kế** một CSDL: vẽ \"bản phối cảnh\" — tức ER diagram — trước khi gõ một dòng SQL nào.\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\nSau khi đọc xong, bạn có thể:\n\n1. Phân biệt **Database design** vs **Application design**.\n2. Đọc thuộc 4 pha thiết kế CSDL: **Requirements → Conceptual → Logical → Physical**, biết ER nằm ở pha nào.\n3. Đọc một đoạn requirements (Anh/Việt) và **identify** entities, attributes, relationships, constraints.\n4. Phân biệt 4 loại attribute: **simple / composite / multi-valued / derived** (+ complex).\n5. Phân biệt **entity / entity type / entity set**, biết cách xác định **key**.\n6. Vẽ được ERD đúng quy ước Elmasri-Navathe (chữ nhật, oval, hình thoi, gạch chân khóa, đường đôi).\n7. Phân biệt **strong vs weak entity**, biết khi nào dùng **identifying relationship** + **partial key**.\n8. Hiểu **degree** của relationship (binary / ternary / n-ary), **recursive relationship** với role names.\n9. Đặt được **cardinality ratio** (1:1, 1:N, M:N) và **participation constraint** (total/partial).\n10. Sử dụng **(min, max) notation** thay cho cardinality ratio truyền thống.\n11. Đọc được **UML class diagram** và biết tương ứng với ER thế nào.\n12. Nhận diện và sửa **Fan Trap** + **Chasm Trap** — hai cái bẫy thiết kế kinh điển.\n\n### 0.3. Lộ trình đọc đề xuất\n\n| Section | Mức | Phút | Ưu tiên |\n|---|---|---:|---|\n| 1. Database Design Process | CORE | 15 | Phải đọc — biết ER ở pha nào |\n| 2. Sample DB COMPANY | CORE | 15 | Schema chạy XUYÊN SUỐT cả môn |\n| 3. ER Model — What & Why | CORE | 10 | Định nghĩa & motivation |\n| 4. ER Model Concepts | **CORE NẶNG NHẤT** | 60 | ~50% chương — đọc thật kỹ |\n| 5. ER Diagram & Naming + Case studies | CORE | 25 | Vẽ thực hành |\n| 6. Alternative Notations | CORE | 20 | (min,max) chắc ra thi |\n| 7. Problems with ER Models | CORE | 20 | Fan/Chasm trap — phân biệt cao |\n| TH2-TH4 (Bảng tra nhanh, Sai lầm, Bài tập) | EXAM | 30 | Trước thi cuối kỳ |\n\nTổng: ≈ 195 phút (≈ 3h15'). Lần đầu đọc, đừng cố nhớ mọi notation — đọc hết section 4 thật kỹ trước, các section 5–7 sẽ tự nhiên trực quan.\n\n---\n\n","file":"materials/DB-Chapter2.md","section":1},{"id":"c2-02","group":"c2","kind":"source","title":"1. Overview of Database Design Process — Tổng quan quy trình thiết kế CSDL","markdown":"## 1. Overview of Database Design Process — Tổng quan quy trình thiết kế CSDL\n\n### 1.1. Tại sao có quy trình này? (Motivation)\n\nKhi một công ty nói \"tôi muốn quản lý nhân viên, phòng ban, dự án\", nếu lập trình viên nhảy thẳng vào `CREATE TABLE` thì 90% trường hợp phải đập đi xây lại: thiếu bảng, sai khóa, sai cardinality. → Cần một **quy trình** chia thiết kế thành các pha rõ ràng, mỗi pha có *deliverable* và mức độ phụ thuộc DBMS khác nhau. **ER model** là công cụ chính của pha \"Conceptual Design\".\n\n### 1.2. Hai luồng song song\n\n- **Database design** — thiết kế *conceptual schema* (slide 5).\n- **Applications design** — thiết kế *programs and interfaces* truy cập database; coi là một phần của software engineering (slide 5).\n\nHai luồng gặp nhau khi triển khai. Trong môn này ta học luồng *database design*.\n\n### 1.3. Diagram quy trình tổng thể\n\n> 📊 **Hình 1.1 — Database Design Process (slide 6–10):**\n\n```\n                     ┌───────────┐\n                     │ Miniworld │\n                     └─────┬─────┘\n                           ▼\n              ┌────────────────────────────┐\n              │ REQUIREMENTS – COLLECTION  │\n              │       & ANALYSIS           │\n              └──┬───────────────────┬─────┘\n                 │ Functional req.   │ Data requirements\n                 ▼                   ▼\n       ┌──────────────────┐ ┌─────────────────┐\n       │ FUNCTIONAL       │ │ CONCEPTUAL      │ ◄── ER MODEL ở đây!\n       │ ANALYSIS         │ │ DESIGN          │\n       └────────┬─────────┘ └────────┬────────┘\n                │                    │ Conceptual schema\n                │                    ▼\n                │           ┌──────────────────┐\n                │           │ LOGICAL DESIGN   │  DBMS-independent ↑\n                │           │ (DATA MODEL      │ ─────────────────\n                │           │  MAPPING)        │  DBMS-specific ↓\n                │           └────────┬─────────┘\n                │                    │ Database schema\n                ▼                    ▼\n       ┌──────────────────┐ ┌──────────────────┐\n       │ APPLICATION      │◄│ PHYSICAL DESIGN  │\n       │ PROGRAM DESIGN   │ └────────┬─────────┘\n       └────────┬─────────┘          │ Internal schema\n                ▼                    ▼\n       ┌──────────────────┐\n       │ TRANSACTION      │\n       │ IMPLEMENTATION   │\n       └────────┬─────────┘\n                ▼\n         Application program\n```\n\n> 📊 **Đọc diagram:** Cột phải = thiết kế CSDL; cột trái = thiết kế chương trình. Đường ngang đứt nét chia 2 vùng: trên — *DBMS-independent* (không phụ thuộc Oracle/MySQL/Postgres), dưới — *DBMS-specific* (đã chọn DBMS rồi). **ER model phục vụ pha Conceptual Design**: input là Data requirements, output là **Conceptual schema** (chính là ER diagram).\n\n### 1.4. Bốn pha — đặc điểm và ví dụ\n\n| Pha | Slide | Đầu vào | Đầu ra | Đặc điểm |\n|---|---:|---|---|---|\n| **1. Requirements collection & analysis** | 7 | Phỏng vấn user | Data req. + Functional req. | Ngôn ngữ tự nhiên |\n| **2. Conceptual design** | 8 | Data requirements | Conceptual schema (ERD) | Mô tả entity types, relationships, constraints — **DBMS-independent** |\n| **3. Logical design (Data Model Mapping)** | 9 | Conceptual schema | Database schema (relational) | Thường được auto/semi-auto bởi tool |\n| **4. Physical design** | 10 | Database schema | Internal schema | Storage structure, indexes, access path |\n\n> 💡 **Ví dụ 1.1 — Cùng một câu yêu cầu chạy qua 4 pha:**\n> Câu: *\"The company is organized into departments.\"*\n> - **Pha 1 (Requirements):** ghi nhận: công ty có \"phòng ban\" — chưa nói gì về DBMS hay bảng.\n> - **Pha 2 (Conceptual):** tạo entity type `DEPARTMENT` với `Dname`, `Dnumber`, `Locations`; tạo relationship `MANAGES` giữa EMPLOYEE và DEPARTMENT.\n> - **Pha 3 (Logical):** map sang quan hệ `DEPARTMENT(Dname, Dnumber, Mgr_ssn, Mgr_start_date)` — đã chọn relational model.\n> - **Pha 4 (Physical):** tạo `B-tree index trên Dnumber` (vì hay query theo số phòng); chọn file organization phù hợp.\n>\n> **Kết quả:** một câu yêu cầu trừu tượng đi tận đến index cụ thể, qua 4 pha riêng biệt.\n\n> 💡 **Hiểu đơn giản:** Quy trình giống xây nhà:\n> - Pha 1 = nói chuyện với chủ nhà xem cần phòng gì.\n> - Pha 2 = vẽ phối cảnh & layout (ERD = bản phối cảnh).\n> - Pha 3 = vẽ bản vẽ kỹ thuật (relational schema).\n> - Pha 4 = chọn vật liệu xây thật (file organization, index).\n>\n> Đập đi vẽ lại pha 2 thì rẻ; đập đi xây lại pha 4 thì rất đắt → **đầu tư công vào pha conceptual**.\n\n> 📝 **Tóm lại section 1:**\n> - Database design ≠ application design (2 luồng song song).\n> - 4 pha: **Requirements → Conceptual → Logical → Physical**.\n> - **ER thuộc pha Conceptual** — DBMS-independent.\n> - **Một câu ghi nhớ:** *\"ER là bản vẽ phối cảnh — vẽ trước khi đào móng.\"*\n\n> ❓ **Tự kiểm tra section 1:**\n> 1. Pha nào phụ thuộc DBMS cụ thể? Pha nào không?\n> 2. Phân biệt \"Data requirements\" và \"Functional requirements\".\n> 3. Nếu đổi từ MySQL sang PostgreSQL, ERD có phải vẽ lại không? Vì sao?\n\n---\n\n","file":"materials/DB-Chapter2.md","section":2},{"id":"c2-03","group":"c2","kind":"source","title":"2. A Sample Database Application — CSDL mẫu COMPANY","markdown":"## 2. A Sample Database Application — CSDL mẫu COMPANY\n\n### 2.1. Tại sao có section này?\n\nSlide 12 nói thẳng: thiết kế database cho COMPANY (nhân viên, phòng ban, dự án) → Requirements collection. Đây không phải ví dụ ngẫu nhiên — schema **COMPANY** chạy **xuyên suốt** từ chương 2 → 7 (ER, EER, mapping sang relational, RA, SQL, FD). Học một lần, dùng cả môn.\n\n### 2.2. Yêu cầu CSDL COMPANY\n\nSau khi phỏng vấn user, ta thu được Data requirements gồm 4 nhóm: **Entities, Attributes, Relationships, Constraints** (slide 12).\n\n**Tóm tắt requirements (slide 13–14):**\n\n- COMPANY tổ chức thành **DEPARTMENTs**. Mỗi department có: **tên duy nhất, số duy nhất**, một employee *manages* department, **start date** của manager, có thể có nhiều **locations**.\n- Mỗi department *controls* các **PROJECTs**. Mỗi project có: tên duy nhất, số duy nhất, một single location.\n- Lưu **EMPLOYEE**: name, SSN, address, salary, sex, birth date. Mỗi employee thuộc *một* department (assigned), có thể *làm trên nhiều* projects (không nhất thiết do cùng department kiểm soát). Lưu **số giờ/tuần** mỗi employee làm trên mỗi project. Lưu **direct supervisor** của mỗi employee.\n- Lưu **DEPENDENTs** của mỗi employee: first name, sex, birth date, relationship.\n\n### 2.3. Phân tích requirements\n\n| Loại | Rút từ | Trên COMPANY |\n|---|---|---|\n| **Entity type** | Danh từ in hoa | EMPLOYEE, DEPARTMENT, PROJECT, DEPENDENT |\n| **Attribute** | Tính chất mô tả | Name, Ssn, Salary, Locations, Hours |\n| **Relationship type** | Động từ liên hệ | WORKS_FOR, MANAGES, CONTROLS, WORKS_ON, SUPERVISION, DEPENDENTS_OF |\n| **Constraint** | Từ \"unique\", \"must\", \"may\", \"several\" | Dnumber duy nhất; mỗi employee thuộc đúng 1 phòng |\n\n### 2.4. ERD COMPANY hoàn chỉnh (figure huyền thoại — slide 15, 22, 34, 48, 53, 59)\n\nĐây là figure xuất hiện ~6 lần trong chương — chính là Figure 7.2 trong Elmasri 7e. Tái tạo bằng Mermaid + bảng.\n\n**Entity types:**\n\n| Entity | Loại | Attributes |\n|---|---|---|\n| **EMPLOYEE** | Strong | Ssn (key), Name (composite: Fname, Minit, Lname), Bdate, Address, Salary, Sex |\n| **DEPARTMENT** | Strong | Name (key), Number (key — 2 candidate keys), Locations (multivalued), Number_of_employees (derived) |\n| **PROJECT** | Strong | Name (key), Number (key), Location |\n| **DEPENDENT** | **Weak** | Name (partial key), Sex, Birth_date, Relationship |\n\n**Relationship types:**\n\n| Relationship | Giữa | Cardinality | Participation | Attribute |\n|---|---|---|---|---|\n| **WORKS_FOR** | EMPLOYEE — DEPARTMENT | N : 1 | Total cả hai | — |\n| **MANAGES** | EMPLOYEE — DEPARTMENT | 1 : 1 | EMPLOYEE partial, DEPARTMENT total | Start_date |\n| **CONTROLS** | DEPARTMENT — PROJECT | 1 : N | DEPARTMENT partial, PROJECT total | — |\n| **WORKS_ON** | EMPLOYEE — PROJECT | M : N | Total cả hai | Hours |\n| **SUPERVISION** | EMPLOYEE — EMPLOYEE (recursive) | 1 : N | Cả hai partial | role: Supervisor / Supervisee |\n| **DEPENDENTS_OF** | EMPLOYEE — DEPENDENT | 1 : N | DEPENDENT total (identifying) | — |\n\n```mermaid\nerDiagram\n  EMPLOYEE ||--o{ DEPENDENT : \"DEPENDENTS_OF (identifying, 1:N)\"\n  EMPLOYEE }o--|| DEPARTMENT : \"WORKS_FOR (N:1, total)\"\n  EMPLOYEE ||--o| DEPARTMENT : \"MANAGES (1:1, Start_date)\"\n  DEPARTMENT ||--o{ PROJECT : \"CONTROLS (1:N)\"\n  EMPLOYEE }o--o{ PROJECT : \"WORKS_ON (M:N, Hours)\"\n  EMPLOYEE ||--o{ EMPLOYEE : \"SUPERVISION (1:N, recursive)\"\n\n  EMPLOYEE {\n    string Ssn PK\n    string Fname\n    string Minit\n    string Lname\n    date Bdate\n    string Address\n    decimal Salary\n    string Sex\n  }\n  DEPARTMENT {\n    string Name UK\n    int Number PK\n    string Locations \"multivalued\"\n    int Number_of_employees \"derived\"\n  }\n  PROJECT {\n    string Name UK\n    int Number PK\n    string Location\n  }\n  DEPENDENT {\n    string Name \"partial key\"\n    string Sex\n    date Birth_date\n    string Relationship\n  }\n```\n\n> 📊 **Đọc diagram này thế nào:**\n> - 4 ô chữ nhật = 4 entity types. **DEPENDENT có viền đôi** (weak entity).\n> - Oval gắn vào ô chữ nhật = attribute. **Oval gạch chân** = key (Ssn, Number).\n> - **Oval nét đôi** = multivalued (Locations). **Oval nét đứt** = derived (Number_of_employees).\n> - **Oval nối oval** = composite (Name → {Fname, Minit, Lname}).\n> - 6 hình thoi = 6 relationship types. **DEPENDENTS_OF có viền đôi** (identifying).\n> - Số `N`, `1`, `M` cạnh hình thoi = cardinality ratio.\n> - **Đường đôi** = total participation; **đường đơn** = partial.\n> - **SUPERVISION** nối EMPLOYEE với chính nó (recursive); 2 vai: `Supervisor` + `Supervisee`.\n\n### 2.5. Case study Group A & Group B (slide 16)\n\n- **GROUP A:** course registration của HCMUT.\n- **GROUP B:** Library của một University.\n\nHai case này sẽ được dùng lại ở slide 35 (identify entity types), slide 60 (vẽ ERD).\n\n> 📝 **Tóm lại section 2:**\n> - Schema **COMPANY** = ví dụ chạy xuyên suốt môn. Phải thuộc 4 entity + 6 relationship.\n> - Mọi ví dụ minh họa từ chương này trở đi nên dùng schema COMPANY thay vì bịa.\n> - **Một câu ghi nhớ:** *\"COMPANY có 4 entity và 6 relationship — thuộc trước, học sau.\"*\n\n> ❓ **Tự kiểm tra section 2:**\n> 1. DEPENDENT là strong hay weak entity? Vì sao?\n> 2. Cardinality của MANAGES là gì? Participation 2 phía thế nào?\n> 3. Tại sao `Hours` nằm trên relationship `WORKS_ON` mà không gắn vào EMPLOYEE hay PROJECT?\n\n---\n\n","file":"materials/DB-Chapter2.md","section":3},{"id":"c2-04","group":"c2","kind":"source","title":"3. What is ER Model? And Why?","markdown":"## 3. What is ER Model? And Why?\n\n### 3.1. Tại sao có ER Model?\n\nBạn đã có Data requirements bằng tiếng Anh tự nhiên. Vấn đề: tiếng Anh **mơ hồ**. Câu \"an employee works on several projects\" — *several* là 2? 3? 100? *Mọi* nhân viên hay chỉ một số? Cần một **ngôn ngữ có cấu trúc** vừa đủ chính xác cho máy đọc, vừa trực quan cho stakeholder. Đó là ER model.\n\n### 3.2. Định nghĩa (slide 18)\n\n| Thuật ngữ | Tiếng Việt | Định nghĩa |\n|---|---|---|\n| **Entity-Relationship (ER) model** | Mô hình thực thể-mối liên kết | High-level conceptual data model phổ biến — *logical organisation* of data trong database system |\n| **ER Diagram (ERD)** | Sơ đồ ER | Diagrammatic notation đi kèm ER model — tập ký hiệu hình học (ô vuông, oval, hình thoi…) |\n| **Conceptual Design** | Thiết kế ý niệm | Quá trình *Data requirements → Conceptual Schema (ERD)* |\n\n### 3.3. Tại sao dùng ER? — 5 lý do (slide 19)\n\n1. User requirements được *specified formally & unambiguously* (đặc tả hình thức và không nhập nhằng).\n2. *Easily understood* bởi ordinary users (non-technical).\n3. *An effective bridge* giữa user requirements và logical database design / implementation.\n4. *Independent of any particular DBMS* (không phụ thuộc DBMS cụ thể).\n5. *Does not involve any physical or implemental details* (không dính chi tiết vật lý).\n\n### 3.4. Ví dụ minh họa & Analogy\n\n> 💡 **Ví dụ 3.1:** Câu \"Nhân viên làm việc cho phòng ban\".\n> - Tiếng Anh: *\"An employee works for a department.\"*\n> - ER: `EMPLOYEE ──(N)── WORKS_FOR ──(1)── DEPARTMENT`, đường đôi cả 2 phía.\n> - **Đọc lại từ ER:** \"Mỗi employee bắt buộc thuộc đúng 1 department; mỗi department bắt buộc có ≥ 1 employee.\" — đã hết mơ hồ.\n\n> 💡 **Hiểu đơn giản:** ER model giống **bản phối cảnh kiến trúc** trong xây nhà — đủ trực quan để chủ nhà ngắm và sửa, đủ chính xác để kỹ sư biến thành bản vẽ kỹ thuật. Hoặc giống **bản đồ metro**: không cần biết đường ray xây thế nào, chỉ cần biết ga nào nối ga nào.\n\n> 📝 **Tóm lại section 3:**\n> - ER = high-level conceptual data model.\n> - ERD = diagrammatic notation.\n> - Conceptual Design = \"dịch\" requirements text → ERD.\n> - 5 ưu điểm: formal, dễ hiểu, cầu nối, độc lập DBMS, không vướng physical detail.\n> - **Một câu ghi nhớ:** *\"ER chính xác cho máy, trực quan cho người.\"*\n\n> ❓ **Tự kiểm tra section 3:**\n> 1. ER thuộc pha thiết kế nào?\n> 2. ER có phụ thuộc Oracle/MySQL/PostgreSQL không? Tại sao đây là ưu điểm?\n> 3. \"ER model\" và \"ER diagram\" khác nhau thế nào?\n\n---\n\n","file":"materials/DB-Chapter2.md","section":4},{"id":"c2-05","group":"c2","kind":"source","title":"4. ER Model Concepts","markdown":"## 4. ER Model Concepts\n\n> Đây là **section dài nhất, quan trọng nhất** của chương. ER model mô tả dữ liệu bằng 3 trụ cột: **Entities, Attributes, Relationships** (slide 21). Ghim 3 từ này vào đầu — mọi thứ sau đều xoay quanh chúng.\n\n### 4.1. Entity (thực thể) — slide 23\n\n#### 4.1.1. Tại sao có concept này?\n\nKhi mô tả thế giới, ta luôn nói về *các thứ*: con người, cái xe, đơn hàng. Mỗi *thứ* có thể tồn tại độc lập, ta muốn nhớ thông tin của nó. **Entity** là cách CSDL gọi tên một \"thứ\" như vậy. Không có concept entity, ta chỉ có những trường dữ liệu rời — không cách nào ràng buộc \"Salary này thuộc người nào\".\n\n#### 4.1.2. Định nghĩa\n\n- **Entity** = thing in real world with **independent existence**.\n- Có thể là:\n  - **Physical existence**: a person, a car, a house, an employee.\n  - **Conceptual existence**: a company, a job, a university course.\n- Examples in COMPANY: EMPLOYEE *John Smith*, *Research* DEPARTMENT, *ProductX* PROJECT.\n\n> 💡 **Hiểu đơn giản:** Entity ≈ một danh từ riêng có thể \"cầm nắm\" về mặt khái niệm. \"John Smith\" là entity; \"55 tuổi\" thì không — \"55 tuổi\" chỉ là *thuộc tính*. Cách phân biệt nhanh: **nếu không thể tồn tại độc lập, đó không phải entity.**\n\n### 4.2. Attribute (thuộc tính) — slide 24\n\n#### 4.2.1. Định nghĩa\n\n- **Attributes** = properties described an entity.\n- Một specific entity sẽ **có một giá trị** cho mỗi attribute.\n- Mỗi attribute có **a value set / data type** đi kèm.\n\n#### 4.2.2. Hình minh họa (slide 25)\n\n> 📊 **Hình 4.1 — Two entities and their attributes:**\n\n```\n   EMPLOYEE e1                         COMPANY c1\n   ─────────────                       ──────────────\n   Name        = John Smith            Name         = Sunco Oil\n   Address     = 2311 Kirby            Headquarters = Houston\n                 Houston, TX 77001     President    = John Smith\n   Age         = 55\n   Home_phone  = 713-749-2630\n```\n\n> 📊 **Đọc diagram:** mỗi entity là 1 chấm; các đường tỏa ra là attribute với giá trị cụ thể. Đây là *instance*, không phải *type*. Sunco Oil's President (= John Smith) cũng là 1 entity khác — gợi ý sớm cho relationship.\n\n### 4.3. Types of Attributes — 4 (+1) loại (slide 26)\n\n| Loại | Định nghĩa | Ví dụ slide | Ký hiệu ERD |\n|---|---|---|---|\n| **Simple** | Một giá trị atomic duy nhất | SSN, Sex | Oval thường |\n| **Composite** | Gồm nhiều thành phần | Name (Fname, Middle, Lname) | Oval nối với oval con |\n| **Multi-valued** | Có nhiều giá trị | Colors of a Car {Color}, Phones {Phone} | Oval nét **đôi** |\n| **Derived** | Suy ra từ attribute khác | Number of students in a class | Oval nét **đứt** |\n| **Complex** | Tổ hợp composite + multi-valued | {Phone(CountryCode, Number)} | Kết hợp |\n\n> 💡 **Hiểu đơn giản:**\n> - **Simple** = 1 ô Excel.\n> - **Composite** = 1 ô bị tách thành ô con (Họ – Đệm – Tên).\n> - **Multi-valued** = 1 ô chứa list ({bóng đá, đọc sách, code}).\n> - **Derived** = công thức Excel `=COUNT(...)` — không lưu, tính khi cần.\n> - **Complex** = phối hợp 2 cái trên.\n\n> 💡 **Ví dụ bổ sung trên COMPANY:** EMPLOYEE có Name (composite), Salary (simple), Phone (multivalued nếu cho phép nhiều số), Age (derived từ Bdate). Một entity có đủ 4 loại.\n\n### 4.4. Entity Type vs Entity Set — slide 27\n\n- **Entity Type** = collection / set of entities cùng attributes.\n- Tập tất cả entity của 1 type tại 1 thời điểm = **Entity Set** (hay *Extension*).\n\n> 📊 **Hình 4.2 — Entity Type vs Entity Set (slide 27):**\n\n```\nEntity Type:    EMPLOYEE                          COMPANY\nAttributes:     Name, Age, Salary                 Name, Headquarters, President\n\nEntity Set:\n                ┌─────────────────────────┐      ┌──────────────────────────┐\n                │ e1 ● (John Smith,55,80k)│      │ c1 ● (Sunco Oil, Houston,│\n                │ e2 ● (Fred Brown,40,30K)│      │       John Smith)        │\n                │ e3 ● (Judy Clark,25,20K)│      │ c2 ● (Fast Computer,     │\n                │ ...                     │      │       Dallas, Bob King)  │\n                └─────────────────────────┘      └──────────────────────────┘\n```\n\n> 💡 **Tương tự OOP:** Entity Type ≈ class definition; Entity ≈ object instance; Entity Set ≈ list-of-objects hiện tại.\n\n### 4.5. Keys — Khóa (slide 28)\n\n#### 4.5.1. Tại sao cần key?\n\nTrong entity set có thể có hàng nghìn entity — làm sao chỉ đích xác **một** entity? Phải có (một hoặc nhiều) attribute mà giá trị **không trùng** giữa hai entity. Đó là *key*. Không có key → không thể nói \"sửa tuổi của *nhân viên này*\" mà không nhầm.\n\n#### 4.5.2. Định nghĩa\n\n- **Key / uniqueness constraint**: attributes có values **distinct** cho mỗi entity. Tính chất phải đúng cho **mọi** entity set của type (mọi instance — không chỉ tại 1 thời điểm).\n- Một entity type có thể có **more than one key**. Ex: STUDENT có **Citizen ID** *và* **Student ID**.\n\n> 💡 **Hiểu đơn giản — Primary Key:** giống **Số CCCD/CMND** — định danh duy nhất một công dân; ngay cả khi đổi tên, đổi địa chỉ, số CCCD vẫn cố định và duy nhất.\n\n#### 4.5.3. Notation cho Entity Type, Attribute, Key (slide 29)\n\n| Khái niệm | Ký hiệu trên ERD |\n|---|---|\n| **Entity type** | Hình chữ nhật |\n| **Simple attribute** | Oval |\n| **Composite attribute** | Oval nối oval con |\n| **Multi-valued attribute** | Oval **viền đôi** |\n| **Derived attribute** | Oval **viền đứt** |\n| **Key attribute** | Oval với **tên gạch chân** |\n\n#### 4.5.4. Ví dụ entity type CAR (slide 30)\n\n> 📊 **Hình 4.3 — Entity Type CAR with two keys:**\n\n```\n                  ┌─────────────────────────┐\n                  │ Registration            │  ← composite key\n                  │   ┌─────────┬─────────┐ │     (gạch chân nguyên cụm)\n                  │   │  State  │ Number  │ │\n                  │   └─────────┴─────────┘ │\n                  └─────────────────────────┘\n                              │\n   (Year)──────────────  ┌────────┐  ─────────────(Model)\n                         │  CAR   │\n   (Color) ═══════════   └────────┘   ──────────────(Make)\n   ↑ multi-valued                     (Vehicle_id) ← simple key (gạch chân)\n```\n\nCAR(**Registration**(Number, State), **Vehicle_id**, Make, Model, Year, {Color})\n\n| Instance | Registration | Vehicle_id | Make | Model | Year | Color |\n|---|---|---|---|---|---:|---|\n| CAR₁ | (ABC 123, TEXAS) | TK629 | Ford | Mustang, convertible | 2004 | {red, black} |\n| CAR₂ | (ABC 123, NEW YORK) | WP9872 | Nissan | Maxima, 4-door | 2005 | {blue} |\n| CAR₃ | (VSY 720, TEXAS) | TD729 | Chrysler | LeBaron, 4-door | 2002 | {white, blue} |\n\n> 📊 **Đọc diagram:** CAR có **2 keys**. Hai dòng đầu cùng `Number = \"ABC 123\"` nhưng khác State (Texas vs New York) — không vi phạm uniqueness, vì key là *cặp* (Number, State). `Color` viền đôi → multi-valued (1 xe có thể có nhiều màu).\n\n### 4.6. Identify Entity Types & Attributes (case COMPANY) — slide 31–35\n\nĐây là phần *thực hành*. Đọc lại requirements ở slide 31, 32 (giống slide 13, 14 nhưng được highlight bằng màu):\n\n- **Đỏ in hoa** (DEPARTMENTs, EMPLOYEE, PROJECTs, DEPENDENTs) → ứng viên Entity type.\n- **Gạch chân xanh** (\"unique name\", \"unique number\", \"Social Security number\") → ứng viên Key.\n- **Đậm xanh** (start date, address, salary, …) → ứng viên Attribute.\n\n#### Initial Conceptual Design (slide 33) — Bản nháp ban đầu\n\nBản nháp có 4 entity vẽ riêng, **chưa có relationship**, nhưng có một số attribute \"đáng ngờ\" được khoanh đỏ — đó là attribute thực ra là *reference đến entity khác*:\n\n| Entity nháp | Attribute thường | Attribute \"đáng ngờ\" (sẽ thành relationship) |\n|---|---|---|\n| EMPLOYEE | Name, Ssn, Sex, Salary, Birth_date, Address | **Department** (FK → DEPARTMENT), **Works_on/Project/Hours** (M:N → PROJECT), **Supervisor** (recursive) |\n| DEPARTMENT | Name, Number, Locations | **Manager**, **Manager_start_date** (→ EMPLOYEE) |\n| PROJECT | Name, Number, Location | **Controlling_department** (→ DEPARTMENT) |\n| DEPENDENT | Dependent_name, Sex, Birth_date, Relationship | **Employee** (→ EMPLOYEE) |\n\n> 📊 **Đọc diagram:** đây là *giai đoạn 1* — liệt kê tất cả attributes ngây thơ theo lời user. *Giai đoạn 2* (Final ERD slide 34) là khi nhận ra attributes khoanh đỏ thực ra là **mối liên kết** với entity khác, và refactor chúng thành relationship type. Đây là motivation tự nhiên cho phần Relationship sắp tới.\n\n> 📝 **Tóm lại 4.1–4.6:**\n> - **Entity** = \"thứ\" có sự tồn tại độc lập.\n> - **Attribute** = thuộc tính, có 4+1 loại.\n> - **Entity Type** = lớp; **Entity Set** = tập instance hiện tại.\n> - **Key** = uniqueness constraint, có thể có nhiều keys/entity type.\n> - **Quá trình \"identify\"** = liệt kê ngây thơ → refactor reference thành relationship.\n> - **Một câu ghi nhớ:** *\"Danh từ → Entity, Tính từ → Attribute, Động từ → Relationship.\"*\n\n> ❓ **Tự kiểm tra:**\n> 1. Phân biệt entity vs entity type vs entity set qua John Smith / EMPLOYEE / {e1, e2, …}.\n> 2. Multi-valued attribute và Composite attribute khác nhau chỗ nào? Cho 1 ví dụ mỗi loại trên COMPANY.\n> 3. Một entity type có thể có 0 key được không? Vì sao?\n\n### 4.7. Relationships and Relationship Types — slide 36\n\n#### 4.7.1. Tại sao có concept này?\n\nSau khi có entity + attribute, vấn đề tiếp theo: làm sao biểu diễn \"John Smith *làm việc cho* phòng Research\"? Nếu chỉ có entity, ta không có cách \"nối\" John Smith và Research — trừ khi nhồi `DepartmentName=\"Research\"` vào EMPLOYEE (bản nháp slide 33). Cách đó sai vì \"Research\" không phải dữ liệu *của* nhân viên Lan, nó là *liên kết* tới một entity khác. → Cần concept tách biệt: **Relationship**.\n\n#### 4.7.2. Định nghĩa\n\n- **Relationship type R among n entity types E₁, …, Eₙ**: defines a set of associations (relationship set R) among entities.\n- **Relationship instances rᵢ**: each rᵢ associates *n* individual entities (e₁, …, eₙ).\n- **Examples:**\n  - WORKS_FOR between EMPLOYEEs and DEPARTMENTs (relationship type).\n  - EMPLOYEE *John Smith* **works on** PROJECT *ProductX* (relationship instance).\n\n> 💡 **Tương tự với Entity:** *Relationship type* (WORKS_FOR) chứa *relationship instances* (John Smith works on ProductX) — chỉ khác là instance là một \"cặp/bộ liên kết\" thay vì 1 thực thể.\n\n#### 4.7.3. Hình minh họa binary relationship (slide 37)\n\n> 📊 **Hình 4.4 — Example WORKS_FOR (binary):**\n\n```\n   EMPLOYEE          WORKS_FOR        DEPARTMENT\n   ─────────         ─────────        ──────────\n     e1 ●─────r1───────────────────●  d1\n     e2 ●─────r2───────────────────●  d1\n     e3 ●─────r3───────────────────●  d2\n     e4 ●─────r4───────────────────●  d2\n     e5 ●─────r5───────────────────●  d2\n     e6 ●─────r6───────────────────●  d3\n     e7 ●─────r7───────────────────●  d3\n                                            A binary relationship\n```\n\n> 📊 **Đọc diagram:** 3 oval lớn = 3 set: EMPLOYEE bên trái, WORKS_FOR ở giữa, DEPARTMENT bên phải. Mỗi `rᵢ` = \"cặp liên kết\" gồm 1 employee + 1 department. Binary vì mỗi instance gồm 2 entity.\n\n#### 4.7.4. Degree of relationship type (slide 38)\n\n- **Degree** = số entity types tham gia: **Binary** (2), **Ternary** (3), **n-ary** (n).\n- Có thể có **nhiều hơn một relationship type** giữa cùng tập entity types: vd `EMPLOYEE—Works-for—DEPARTMENT` *và* `EMPLOYEE—Manages—DEPARTMENT`.\n\n#### 4.7.5. Hình minh họa ternary (slide 39)\n\n> 📊 **Hình 4.5 — Ternary SUPPLY:**\n\n```\n   SUPPLIER         SUPPLY            PROJECT\n                                      ────────\n     s1 ●        r1 ━━━━━━━━━━━●       j1\n                 r2 ━━━━━━━━━━━●       j2\n     s2 ●        r3 ━━━━━━━━━━━●       j3\n                 r4 ━━━━━━━━━━━\n                 r5 ━━━━━━━━━━━\n   PART          r6 ━━━━━━━━━━━\n   ────          r7 ━━━━━━━━━━━\n     p1 ●\n     p2 ●\n     p3 ●  ← Mỗi rᵢ nối 3 entity: 1 supplier + 1 part + 1 project\n```\n\n#### 4.7.6. Recursive relationship + Role names (slide 40, 41)\n\n- **Recursive** = same entity type tham gia *more than once* ở **các vai khác nhau**.\n- Bắt buộc chỉ định **role**.\n- Ex: SUPERVISION — EMPLOYEE (vai *supervisor/boss*) + (another) EMPLOYEE (vai *subordinate/worker*).\n\n> 📊 **Hình 4.6 — Recursive SUPERVISION (slide 41):**\n\n```\n   EMPLOYEE                       SUPERVISION\n   ────────\n     e1 ─── vai 2 ───┐            r1\n                     ├────────────●\n     e1 ─── vai 1 ───┘\n     e2 ─── vai 2 ───┐            r2\n                     ├────────────●\n     e3 ─── vai 1 ───┘\n     e4 ─── vai 1 ───┐            r3\n                     ├────────────●\n     e1 ─── vai 2 ───┘\n\n     1: supervisor (vai sếp)        2: supervisee (vai nhân viên dưới)\n```\n\n> 📊 **Đọc diagram:** cùng entity `e1` xuất hiện 2 lần — một lần ở vai supervisor, một lần ở vai supervisee. Tình huống recursive: \"John Smith vừa là sếp của Mary, vừa là nhân viên của Bob\".\n\n> 💡 **Hiểu đơn giản:** recursive relationship giống mối quan hệ \"*bố–con*\" trong gia phả — cùng entity type Person, nhưng mỗi cặp có 2 vai khác nhau.\n\n### 4.8. Constraints on Binary Relationship Type (slide 42, 45)\n\n#### 4.8.1. Tại sao cần?\n\nER vẽ ra \"có liên kết WORKS_FOR\" là chưa đủ. User cần biết: 1 nhân viên thuộc *bao nhiêu* phòng? Có *bắt buộc* thuộc phòng nào không? Không trả lời 2 câu này, schema vẫn mơ hồ.\n\n#### 4.8.2. Hai loại constraint\n\n**Structural constraints** = cách *express semantics of relationship*. Gồm:\n1. **Cardinality ratio** (tỉ số lượng).\n2. **Participation constraint** (ràng buộc tham gia).\n\n#### 4.8.3. Cardinality ratio (slide 42)\n\nSpecifies **maximum number** of relationship instances that an entity can participate in.\n\n| Loại | Ý nghĩa |\n|---|---|\n| **one-to-one (1:1)** | A liên kết tối đa 1 B, B tối đa 1 A |\n| **one-to-many (1:N)** / **many-to-one (N:1)** | A liên kết nhiều B; mỗi B chỉ 1 A (hoặc ngược lại) |\n| **many-to-many (M:N)** | A liên kết nhiều B; B liên kết nhiều A |\n\n#### 4.8.4. Hình 1:1 — MANAGES (slide 43)\n\n> 📊 **Hình 4.7 — One-to-one MANAGES:**\n\n```\n   EMPLOYEE          MANAGES         DEPARTMENT\n     e1 ●\n     e2 ●           r1 ●─────────────●  d1\n     e3 ●─────●\n     e4 ●           r2 ●─────────────●  d2\n     e5 ●─────●     r3 ●─────────────●  d3\n     e6 ●─────●\n     e7 ●\n```\n\n> 📊 **Đọc:** chỉ một số ít EMPLOYEE (e3, e5, e6) tham gia (ai làm sếp); mỗi DEPARTMENT có **đúng 1** manager → 1:1.\n\n#### 4.8.5. Hình M:N — WORKS_ON (slide 44)\n\n> 📊 **Hình 4.8 — Many-to-many WORKS_ON:**\n\n```\n   EMPLOYEE        WORKS_ON         PROJECT\n     e1 ●─────r1──────────────●  p1\n                              ●  p2\n     e2 ●─────r2──────────────●  p3\n                              ●  p4\n     e3 ●─────r3──────────────●\n              r4..r7\n```\n\n> 📊 **Đọc:** e2 liên kết với nhiều project (p1, p3); p3 lại nhận nhiều employee (e2, e3) → M:N.\n\n#### 4.8.6. Participation constraint (slide 45)\n\n| Loại | Ý nghĩa | Ký hiệu |\n|---|---|---|\n| **Mandatory / Total** | Every instance **must** participate | Đường **đôi** |\n| **Optional / Partial** | Not every instance must participate | Đường **đơn** |\n\n#### 4.8.7. Notation tích hợp (slide 46)\n\n> 📊 **Hình 4.9 — WORKS_FOR notation tổng hợp:**\n\n```\n                Cardinality ratio\n                                       Participation constraint\n   ┌──────────┐  N    ╔══════════╗  1   ┌────────────┐\n   │ EMPLOYEE │═══════║  Works-for ║─────│ DEPARTMENT │\n   └──────────┘       ╚══════════╝       └────────────┘\n   ═══ : đường ĐÔI = total           ─── : đường ĐƠN = partial\n\n   Diễn nghĩa:\n   • Cardinality:   An EMPLOYEE works for ONE DEPARTMENT.\n                    A DEPARTMENT has MANY EMPLOYEEs.\n   • Participation: An EMPLOYEE MUST work for a DEPARTMENT (đường đôi).\n                    A DEPARTMENT MAY have NO EMPLOYEE (đường đơn).\n```\n\n> 💡 **Hiểu đơn giản:** Cardinality nói **được/tối đa bao nhiêu**; Participation nói **có bắt buộc tham gia không**.\n\n### 4.9. Attributes of Relationship Types (slide 47)\n\n- Relationship type **có thể có attribute** (ex: `HoursPerWeek` của WORKS_ON).\n- Quy tắc migrate attribute relationship sang entity:\n\n| Cardinality | Migrate về đâu? | Vì sao |\n|---|---|---|\n| **1:1** | Một trong hai bên (đều OK) | Mỗi bên gắn tối đa 1 bên kia |\n| **1:N** | **Chỉ phía N** | Mỗi entity phía N gắn với 1 entity phía 1 |\n| **M:N** | **KHÔNG migrate được** | Attribute phụ thuộc *từng cặp* |\n\n> 💡 **Hiểu đơn giản:** Hours là số giờ employee X làm cho project Y — gắn vào ai? Không thể gắn EMPLOYEE (cùng employee có nhiều project, mỗi project khác giờ); cũng không gắn PROJECT. **M:N thì attribute phải nằm trên relationship.** Ngược lại, `Start_date` của MANAGES (1:1) có thể migrate vào EMPLOYEE hoặc DEPARTMENT.\n\n### 4.10. Weak Entity Types (slide 49)\n\n#### 4.10.1. Tại sao có weak entity?\n\nCó những \"thứ\" tồn tại *nhờ* một thứ khác — vd: con của nhân viên, line item của hóa đơn. Tự thân chúng không có key. Nếu cố ép key duy nhất toàn cục, sẽ phải bịa ID không có nghĩa thực tế. → ER cho phép loại entity đặc biệt: weak entity, được định danh **kết hợp** với entity \"chủ\".\n\n#### 4.10.2. Định nghĩa\n\n- **Weak Entity Types**:\n  - **Do not have key attributes of their own**.\n  - Identified by being related to specific entities from another entity type.\n- **Identifying relationship**: relates a weak entity type to its **owner**.\n- **Always has total participation** từ phía weak.\n- Entities identified by **combination of**:\n  - **A partial key** (or *discriminator*) of weak entity type.\n  - The particular owner entity.\n\n#### 4.10.3. Notation cho weak entity (slide 50)\n\n| Khái niệm | Ký hiệu |\n|---|---|\n| **Weak entity type** | Hình chữ nhật **viền đôi** |\n| **Identifying relationship** | Hình thoi **viền đôi** |\n| **Partial key** | Oval với **gạch chân nét đứt** |\n\n> 📊 **Hình 4.10 — Weak Entity DEPENDENT:**\n\n```\n       (Name) ← gạch chân ĐỨT (partial key)         (SSN) ← gạch chân (PK)\n          │                                            │\n   ╔══════════════╗  N  ╔═════╗   1   ┌──────────┐\n   ║  DEPENDENT   ║═════║ Of  ║───────│ EMPLOYEE │  ← Owner / Identifying entity type\n   ║              ║     ╚═════╝       └──────────┘\n   ╚══════════════╝\n   ↑ viền ĐÔI (weak)         ↑ identifying relationship\n                              (hình thoi viền đôi)\n```\n\n> 📊 **Đọc:** DEPENDENT viền đôi (weak); Name partial key (gạch nét đứt). Khóa thực sự định danh dependent là cặp `(SSN của EMPLOYEE chủ, Name)`. Hai con cùng tên \"An\" của 2 employee khác nhau là 2 dependent khác nhau.\n\n> 💡 **Hiểu đơn giản:** Weak entity giống **đăng ký tạm trú** — không có số sổ duy nhất toàn quốc; chỉ định danh được khi gắn với **chủ hộ** + **tên/số phòng** trong nhà chủ hộ. Hoặc giống **người phụ thuộc trong hồ sơ bảo hiểm**: tên con chưa đủ — phải kèm nhân viên chủ hồ sơ.\n\n> 📝 **Tóm lại section 4 (toàn bộ):**\n> - **3 trụ cột**: Entity, Attribute, Relationship.\n> - 4 loại attribute: simple / composite / multi-valued / derived (+ complex).\n> - Entity Type vs Entity Set (≈ class vs set-of-objects).\n> - Key = uniqueness; có thể nhiều keys/entity type.\n> - Relationship: **degree** (binary / ternary / n-ary), có thể **recursive** với role; có thể có **attribute** (Hours, Start_date).\n> - 2 structural constraints: **cardinality ratio** + **participation**.\n> - **Weak entity** = không key riêng, định danh nhờ identifying relationship + partial key + owner.\n> - Migrate attribute relationship: 1:1 đi đâu cũng được; 1:N chỉ phía N; M:N KHÔNG migrate.\n> - **Một câu ghi nhớ:** *\"Entity sống độc lập, weak entity sống ký sinh; cardinality nói có bao nhiêu, participation nói có bắt buộc không.\"*\n\n> ❓ **Tự kiểm tra section 4:**\n> 1. M:N relationship có Hours là attribute. Tại sao không thể migrate Hours sang EMPLOYEE?\n> 2. SUPERVISION có degree mấy? Có recursive không? Vì sao phải có role names?\n> 3. Tại sao DEPENDENT là weak entity? Identifying relationship của nó là gì?\n> 4. CONTROLS giữa DEPARTMENT và PROJECT là 1:N — phía nào là \"1\", phía nào là \"N\"?\n\n---\n\n","file":"materials/DB-Chapter2.md","section":5},{"id":"c2-06","group":"c2","kind":"source","title":"5. ER Diagram and Naming Conventions","markdown":"## 5. ER Diagram and Naming Conventions\n\n### 5.1. Tại sao có quy ước? (slide 55)\n\nERD có thể vẽ đúng nhưng đặt tên dở khiến nó thành câu đố ngược. \"T1 ──R1── T2\" thì máy hiểu nhưng người đọc sẽ chửi. → Cần quy ước thống nhất + hướng đọc trái-phải / trên-dưới để diagram tự kể chuyện.\n\n### 5.2. Naming Conventions (slide 55)\n\n- Choose names that **convey meanings**.\n- **Nouns** → entity type names. (Danh từ → entity.)\n- **Verbs** → relationship type names. (Động từ → relationship.)\n- Choose binary relationship names sao cho ER diagram đọc được **left-to-right và top-to-bottom**.\n\n> 💡 **Ví dụ áp dụng:**\n> - \"EMPLOYEE *Works-for* DEPARTMENT\" — đọc trái-phải hợp lý.\n> - \"DEPARTMENT *Controls* PROJECT\" — đọc trái-phải / trên-dưới hợp lý.\n> - Đặt sai: \"EMPLOYEE *Department* DEPARTMENT\" — vô nghĩa, \"Department\" không phải động từ.\n\n> 💡 **Quy trình làm bài ERD — 5 bước \"đánh dấu\":**\n> Khi đọc 1 đoạn requirements (Hospital, OSU, Library, …), thực hành:\n> 1. **Gạch danh từ** → ứng viên Entity type.\n> 2. **Gạch động từ** → ứng viên Relationship type.\n> 3. **Gạch tính chất / tính từ** → ứng viên Attribute.\n> 4. **Gạch các từ khoá ràng buộc**: *unique*, *one*, *several*, *may*, *must*, *exactly* → constraint.\n> 5. **Đối chiếu lại từng câu** đề với ERD đã vẽ — câu nào không trả lời được thì còn thiếu.\n\n### 5.3. Cheat-sheet ký hiệu ERD (slide 56)\n\n**Bảng ký hiệu để học thuộc lòng:**\n\n| Symbol | Meaning |\n|---|---|\n| `▭` Hình chữ nhật đơn | **ENTITY** (strong) |\n| `▭▭` Hình chữ nhật **viền đôi** | **WEAK ENTITY** |\n| `◇` Hình thoi đơn | **RELATIONSHIP** |\n| `◇◇` Hình thoi **viền đôi** | **IDENTIFYING RELATIONSHIP** |\n| Oval đơn nối entity bằng đường nét liền | **ATTRIBUTE** |\n| Oval với tên **gạch chân** | **KEY ATTRIBUTE** |\n| Oval **viền đôi** | **MULTIVALUED ATTRIBUTE** |\n| Oval cha nối nhiều oval con | **COMPOSITE ATTRIBUTE** |\n| Oval **viền đứt** | **DERIVED ATTRIBUTE** |\n| Đường **đôi** (`══`) | **TOTAL PARTICIPATION** |\n| Đường **đơn** (`──`) | **PARTIAL PARTICIPATION** |\n| Số `1`, `N`, `M` cạnh đường nối | **CARDINALITY RATIO** |\n\n> 📊 **Cheat-sheet ASCII:**\n\n```\n   ▭         ENTITY                 ◇         RELATIONSHIP\n   ▭▭        WEAK ENTITY            ◇◇        IDENTIFYING RELATIONSHIP\n   ─◯        ATTRIBUTE              ─◯─◯─    COMPOSITE ATTRIBUTE\n   ─Ⓞ       KEY (gạch chân tên)     ─◌◌─     MULTIVALUED ATTRIBUTE\n                                     ─⤬⤬─    DERIVED ATTRIBUTE (nét đứt)\n   E1 ─◇─ E2          ← partial cả hai\n   E1 ═◇─ E2          ← E1 total, E2 partial\n   E1 ═◇═ E2          ← total cả hai\n   E1 ─1─ ◇ ─N─ E2    ← cardinality 1:N\n```\n\n### 5.4. Vẽ ERD COMPANY (slide 57–59)\n\nSlide 57, 58, 59 lặp lại requirements COMPANY rồi in **Final ERD** đầy đủ — chính là figure huyền thoại đã mô tả ở section 2.4. Đối chiếu requirement ↔ ERD:\n\n| Requirement (slide 57, 58) | Phần tử ERD (slide 59) |\n|---|---|\n| \"DEPARTMENT có unique name, unique number\" | DEPARTMENT có 2 keys: Name, Number (gạch chân) |\n| \"department has start date\" (của manager) | Start_date là attribute của relationship MANAGES |\n| \"department may have several locations\" | Locations là multivalued attribute của DEPARTMENT |\n| \"department controls a number of projects\" | CONTROLS giữa DEPARTMENT (1) — PROJECT (N) |\n| \"PROJECT có unique name, unique number\" | PROJECT có 2 keys: Name, Number |\n| \"EMPLOYEE có SSN\" | Ssn là key của EMPLOYEE |\n| \"employee assigned to one department\" | WORKS_FOR: EMPLOYEE (N) — DEPARTMENT (1) |\n| \"may work on several projects\" | WORKS_ON: EMPLOYEE (M) — PROJECT (N), attribute Hours |\n| \"direct supervisor of each employee\" | SUPERVISION recursive trên EMPLOYEE, role Supervisor / Supervisee |\n| \"DEPENDENTs với first name, sex, birth date, relationship\" | DEPENDENT là weak entity, Name (partial key), Sex, Birth_date, Relationship |\n\n### 5.5. Case study — Hospital (slide 61)\n\n**Đề bài (rút gọn):**\n- Hospital có nhiều physicians, mỗi physician có **physician_number duy nhất** + **≥ 1 specialty**.\n- Patients được **admit** vào hospital bởi physicians; patient có **patient_id duy nhất**, name, address.\n- Patient được admitted phải có **đúng 1** admitting physician. Sau khi admit, phải được **treat bởi ≥ 1** physician.\n- Một physician **có thể treat 0..N** patients. Mỗi treatment có **date và time**.\n\n> 💡 **Ví dụ 5.1 — Giải case Hospital step-by-step:**\n> **Ý tưởng:** đọc text 3 lần — lần 1 tìm danh từ (entity), lần 2 tìm động từ (relationship), lần 3 tìm \"unique/must/may\" (constraint).\n>\n> **Bước 1 — Entities & Attributes:**\n> - PHYSICIAN: physician_number (key), specialty (multivalued — vì \"≥ 1 specialty\")\n> - PATIENT: patient_id (key), name, address\n>\n> **Bước 2 — Relationships:**\n> - **ADMITS** (PHYSICIAN — PATIENT): \"patient phải có đúng 1 admitting physician\" → cardinality 1:N (1 physician — N patient). PATIENT total (\"must have\"). PHYSICIAN partial.\n> - **TREATS** (PHYSICIAN — PATIENT): \"patient must be treated by ≥ 1 physician; physician may treat 0..N\" → M:N. PATIENT total, PHYSICIAN partial. Attribute: `treatment_date_time`.\n>\n> **Bước 3 — ERD:**\n> ```mermaid\n> erDiagram\n>   PHYSICIAN ||--o{ PATIENT : \"ADMITS (1:N, PATIENT total)\"\n>   PHYSICIAN }o--|{ PATIENT : \"TREATS (M:N, PATIENT total, attr date_time)\"\n>   PHYSICIAN { string physician_number PK; string specialty \"multivalued\" }\n>   PATIENT { string patient_id PK; string name; string address }\n> ```\n> **Tại sao đúng:** mỗi câu trong đề được map sang đúng 1 phần tử ERD; không bịa thêm phần tử nào.\n\n### 5.6. Case study — OSU University (slide 62–66)\n\n**Tóm tắt requirements (slide 62–65):** OSU University có MAJOR (chuyên ngành), STUDENT (ID 7 chữ số, 2 đầu = năm vào), TEACHER (ID 5 chữ số, 2 đầu = department), COURSE (course_id, prerequisites, credits, no_of_classes derived, no_of_students derived), CLASS (class_id, days, periods, room — có thể online). Mỗi major có 1 teacher leader. 3 phases registration: phase 1 (chỉ chọn course không giới hạn), phase 2 (cấp class cụ thể, có thể đổi class), phase 3 (giống phase 2 nhưng không remove được class). Last-year students có graduation project, mỗi project có nhóm students + 1 teacher giám sát. Student học 11–25 credits/semester.\n\n**Đáp án ERD (slide 66) — diễn giải:**\n\n| Entity | Attributes chính | Loại |\n|---|---|---|\n| **USER** | ID (key), Name, DateOfBirth, HashKey | Strong (parent qua specialization → STUDENT/TEACHER) |\n| **STUDENT** | Program, CurrentCredit (derived) | Subclass |\n| **TEACHER** | AcademicQualifications | Subclass |\n| **MAJOR** | MajorID (key), MajorName | Strong |\n| **COURSE** | CourseID (key), CourseName, Credit, Program, No.Classes (derived), No.Students (derived) | Strong |\n| **CLASS** | ClassID (key), Semester, Day, RoomNumber, IsOnline, No.Periods | Strong |\n\n**Một số relationship đáng chú ý:**\n- **IS_PREREQUISITES** recursive trên COURSE.\n- **CAN_TAKE** giữa MAJOR — COURSE (M:N, attribute isMandatory).\n- **REGISTERS / CANCELS / LEAVES / JOINS P2 / JOINS P3 / STUDIES** giữa USER — COURSE/CLASS — phản ánh 3 phases.\n- **DIVIDES** giữa COURSE — CLASS (1:N).\n- Specialization disjoint `d` từ USER → {STUDENT, TEACHER} (kiến thức chương 3 EER).\n\n> 📊 **Ý nghĩa case này:** ERD thực tế dễ có 5–7 entity và 10+ relationship. Đáng chú ý: nhiều relationship cùng nối USER với COURSE/CLASS vì hệ thống phân biệt 3 phases — đây là kỹ thuật \"version\" hóa relationship theo thời gian.\n\n### 5.7. Higher-Degree Relationship — Quan hệ bậc cao (slide 67)\n\n> 📊 **Hình 5.1 — 3 cách mô hình \"supplier supplies part for project\":**\n\n**(a) Ternary relationship — đề xuất gốc:**\n```\n   (Sname)         (Quantity)        (Proj_name)\n      │                │                  │\n   ┌──────┐    ╔═══════════╗    ┌─────────┐\n   │SUPPLIER├───╣  SUPPLY   ╠───┤ PROJECT │\n   └──────┘    ╚═════╤═════╝    └─────────┘\n                     │\n                ┌────┴───┐\n                │  PART  │\n                └────────┘\n                  (Part_no)\n```\n\n**(b) 3 binary relationships (M:N × 3) — phân rã sai semantics:**\n```\n   SUPPLIER ──M──SUPPLIES──N── PROJECT\n       │                          │\n       M                          M\n       │                          │\n   CAN_SUPPLY                    USES\n       │                          │\n       N         ┌──────┐         N\n       └─────────│ PART │─────────┘\n                 └──────┘\n```\n**Vấn đề:** (b) **không tương đương** (a). (b) chỉ ghi rời \"supplier có thể cung cấp part X\" + \"project dùng part X\" + \"supplier hợp tác với project Y\" — KHÔNG ghi được sự kiện \"supplier S cung cấp part P CHO project J\" như là một bộ ba nhất quán.\n\n**(c) Reify SUPPLY thành weak entity + 3 quan hệ định danh:**\n```\n   SUPPLIER ─1─◇SS◇─N─ ╔═════════╗ ─N─◇SPJ◇─1─ PROJECT\n                       ║ SUPPLY  ║   (Quantity là attr)\n                       ╚═════════╝\n                            ║ N\n                          ◇SP◇\n                            ║ 1\n                          ┌────┐\n                          │PART│\n                          └────┘\n```\nSUPPLY trở thành weak entity gồm Quantity, được định danh bởi 3 owner (Supplier, Part, Project).\n\n### 5.8. Constraints on ternary relationship (slide 68)\n\nViệc đặt cardinality cho ternary phức tạp hơn binary: với mỗi *cặp* 2 entity ta xét entity thứ 3 tham gia tối đa bao nhiêu lần.\n\n> 💡 **Quy tắc nhanh:** Với ternary R giữa A, B, C: nếu cặp `(A=a, B=b)` cố định mà chỉ có **đúng 1** C tham gia → cardinality của C là 1; nếu nhiều → là N. Tương tự cho 2 cặp còn lại. Cách viết phổ biến: gắn số 1/N lên cạnh từng entity nối hình thoi.\n\n> 📝 **Tóm lại section 5:**\n> - **Cheat-sheet 11 ký hiệu** (slide 56) phải thuộc lòng.\n> - Naming: noun = entity, verb = relationship; đọc trái-phải / trên-dưới.\n> - Vẽ ERD = lặp: identify → entity → attribute → relationship → cardinality + participation → kiểm tra weak/identifying.\n> - Higher-degree relationship: ternary có thể giữ nguyên, phân rã sai, hoặc reify thành weak entity.\n> - **Một câu ghi nhớ:** *\"Cheat-sheet 11 ký hiệu là chìa khóa — vẽ chuẩn nửa việc, đặt tên đúng nửa còn lại.\"*\n\n> ❓ **Tự kiểm tra section 5:**\n> 1. Tại sao 3 binary không tương đương 1 ternary trong slide 67?\n> 2. Phân biệt hình thoi đơn vs hình thoi viền đôi.\n> 3. Trong case Hospital, TREATS có cardinality và participation gì? Tại sao có attribute date_time?\n\n---\n\n","file":"materials/DB-Chapter2.md","section":6},{"id":"c2-07","group":"c2","kind":"source","title":"6. Alternative Diagrammatic Notations","markdown":"## 6. Alternative Diagrammatic Notations\n\n### 6.1. Tại sao có notation khác?\n\nNotation Elmasri–Navathe (oval, hình thoi, đường đôi) là **chuẩn academic** nhưng không phải duy nhất. Industry thường dùng UML class diagram, Crow's Foot, Chen, IDEF1X… Sinh viên cần đọc được ít nhất 2 notation để không \"khóa\" vào một sách.\n\n### 6.2. (Min, max) notation — slide 70, 71\n\n#### 6.2.1. Định nghĩa\n\n- Specify structural constraints on relationships.\n- **Replaces** cardinality ratio (1:1, 1:N, M:N) **VÀ** single/double line cho participation.\n- Associate cặp `(min, max)` với mỗi participation của entity type E in relationship R, với `0 ≤ min ≤ max` và `max ≥ 1`.\n\n#### 6.2.2. Ý nghĩa của (min, max)\n\n| min | max | Ý nghĩa | Tương đương cũ |\n|---|---|---|---|\n| 0 | 1 | Partial, max 1 | partial + 1 |\n| 1 | 1 | Total, đúng 1 | total + 1 |\n| 0 | N | Partial, có thể nhiều | partial + N |\n| 1 | N | Total, có thể nhiều | total + N |\n| 4 | N | **Tối thiểu 4**, có thể nhiều | (cũ không vẽ được min ≥ 4) |\n\n#### 6.2.3. Ví dụ (slide 71)\n\n> 📊 **Hình 6.1 — (min, max) notation:**\n\n```\n   ┌──────────┐  (1,1)   ┌───────────┐  (4,N)   ┌────────────┐\n   │ EMPLOYEE │──────────│ Works-for │──────────│ DEPARTMENT │\n   └──────────┘          └───────────┘          └────────────┘\n\n   ┌──────────┐  (0,1)   ┌──────────┐  (1,1)   ┌────────────┐\n   │ EMPLOYEE │──────────│  Manages │──────────│ DEPARTMENT │\n   └──────────┘          └──────────┘          └────────────┘\n```\n\n> 📊 **Đọc:**\n> - **WORKS_FOR**: EMPLOYEE `(1,1)` = mỗi nhân viên đúng 1 lần (= total + max 1, tức N:1 phía nhân viên). DEPARTMENT `(4,N)` = mỗi phòng có ≥ **4** nhân viên.\n> - **MANAGES**: EMPLOYEE `(0,1)` = 0 hoặc 1 phòng (partial, max 1). DEPARTMENT `(1,1)` = đúng 1 manager.\n> - **Lợi thế** (min,max) so với cách cũ: diễn đạt được \"min ≥ 4\" mà cardinality 1:N không nói được; gói cả participation vào.\n\n#### 6.2.4. ERD COMPANY với (min,max) + role names — slide 72\n\n| Relationship | Phía A | (min,max) | Phía B | (min,max) | Role A | Role B |\n|---|---|---|---|---|---|---|\n| WORKS_FOR | EMPLOYEE | (1,1) | DEPARTMENT | (4,N) | Employee | Department |\n| MANAGES | EMPLOYEE | (0,1) | DEPARTMENT | (1,1) | Manager | Department Managed |\n| CONTROLS | DEPARTMENT | (0,N) | PROJECT | (1,1) | Controlling Dept | Controlled Project |\n| WORKS_ON | EMPLOYEE | (1,N) | PROJECT | (1,N) | Worker | Project |\n| SUPERVISION | EMPLOYEE | (0,N) | EMPLOYEE | (0,1) | Supervisor | Supervisee |\n| DEPENDENTS_OF | DEPENDENT | (1,1) | EMPLOYEE | (0,N) | Dependent | — |\n\n### 6.3. UML methodology + class diagrams — slide 73, 75–77\n\n#### 6.3.1. UML là gì?\n\n- **UML** (Unified Modeling Language) — used extensively in software design.\n- Many diagram types: use case, sequence, class, activity, …\n- **UML class diagrams** thay thế ER trong nhiều industry tool.\n- **Entity** in ER ↔ **object/class** in UML.\n\n#### 6.3.2. Cấu trúc class (slide 75)\n\n- Class chia **3 sections**:\n  - **Top**: class name.\n  - **Middle**: attributes.\n  - **Bottom**: operations áp dụng được lên individual objects.\n- **Associations** = relationship types.\n- **Relationship instances** = links.\n\n#### 6.3.3. Binary association + link attribute (slide 76)\n\n- **Binary association**: line connecting classes; may have name.\n- **Link attribute**: trong **box** nối với association line bằng **dashed line** (vd `Hours` của WORKS_ON).\n\n#### 6.3.4. Multiplicity + types (slide 77)\n\n- **Multiplicities**: `min..max`, `*` = no maximum.\n- **Types**: **association** + **aggregation**.\n- Distinguish **unidirectional** vs **bidirectional**.\n- Model weak entities bằng **qualified association**.\n\n### 6.4. UML class diagram cho COMPANY (slide 74)\n\n> 📊 **Hình 6.2 — UML class COMPANY (mô tả ASCII):**\n\n```\n   ┌─────────────────────┐  4..*    WORKS_FOR  1..1  ┌────────────────┐\n   │ EMPLOYEE            │──────────────────────────│ DEPARTMENT     │\n   │─────────────────────│                          │────────────────│\n   │ Name: Name_dom      │  1..1            0..1     │ Name           │\n   │   Fname             │─────── MANAGES ──────────│ Number         │\n   │   Minit             │     (Start_date)         │────────────────│\n   │   Lname             │                          │ add_employee   │\n   │ Ssn                 │                          │ number_of_emps │\n   │ Bdate: Date         │                          │ change_manager │\n   │ Sex: {M,F}          │  1..*            ◇       │ ...            │\n   │ Address             │     WORKS_ON             └──────┬─────────┘\n   │ Salary              │     (Hours)      1..1            │ 1..*\n   │─────────────────────│                                  │ CONTROLS\n   │ age                 │  *  ┌──────────┐                 │\n   │ change_department   │─────│ supervisee│                ▼\n   │ change_projects     │     │ supervisor│           ┌──────────┐\n   │ ...                 │     └──────────┘           │ PROJECT  │\n   └────────┬────────────┘                            │──────────│\n            │ 0..1                                    │ Name     │\n            │  ◇ aggregation                          │ Number   │\n            ▼                                         │──────────│\n   ┌──────────────┐                                   │ add_emp  │\n   │ DEPENDENT    │   1..*  ┌──────────┐  1..*        │ ...      │\n   │──────────────│─────────│ LOCATION │              └──────────┘\n   │ Sex: {M,F}   │         │──────────│\n   │ Birth_date   │         │ Name     │\n   │ Relationship │         └──────────┘\n   └──────────────┘   ◇ aggregation từ DEPARTMENT\n```\n\n> 📊 **Đọc diagram:**\n> - Mỗi class chia 3 ngăn (slide 75).\n> - Đường nối (association) thay cho hình thoi của ER.\n> - Số 2 đầu đường = multiplicity, dùng `min..max` (`*` = không giới hạn). Vd `4..*` = ≥ 4.\n> - Composite attribute `Name: Name_dom` — type tag + sub-attribute thụt vào.\n> - Multivalued attribute biểu diễn bằng `0..*` hoặc `1..*` ở đầu đường.\n> - Derived attribute `age` viết italic ở giữa attributes.\n> - Operation `add_employee`, `change_manager` là phương thức (UML mạnh hơn ER ở chỗ ghi được hành vi).\n> - **Aggregation** `◇` = whole–part: DEPARTMENT chứa LOCATION; EMPLOYEE chứa DEPENDENT.\n\n### 6.5. Bảng so sánh các notation (slide 78)\n\nSlide 78 tổng hợp các cách vẽ entity / attribute / relationship / specialization / cardinality theo nhiều notation (Chen, Crow's foot, IDEF1X, OMT/UML, Bachman):\n\n| Construct | Elmasri (chuẩn) | Alternative |\n|---|---|---|\n| Entity / class | Hình chữ nhật | Oval `(E)` |\n| Attribute | Oval gắn `─◯` | Oval rỗng / Bullet trong class |\n| Relationship | Hình thoi `◇R` | Hình tròn `Ⓡ` / Tên trên đường |\n| Specialization (chương 3) | Tam giác với `d`/`o` | Mũi tên / tam giác đặc / box lồng |\n| (min,max) | Bên Elmasri | Crow's foot ký hiệu chân quạ |\n| Cardinality | `1 ◇ N` | Mũi tên kép, `─*─` |\n\n→ Đừng nhớ tất cả — chỉ cần biết **(min,max)** và **UML class diagram** là đủ phần industry.\n\n> 📝 **Tóm lại section 6:**\n> - **(min,max)**: cặp số ở mỗi nhánh, gói cả cardinality + participation.\n> - **UML class**: 3 ngăn (name/attr/op), association = relationship, multiplicity `min..max`, aggregation cho whole–part.\n> - **Một câu ghi nhớ:** *\"(min,max) gọn hơn 1:N vì gói cả participation; UML mạnh hơn ER vì có thêm operation.\"*\n\n> ❓ **Tự kiểm tra section 6:**\n> 1. (min,max) `(0,1)` tương ứng với participation gì + cardinality phía nào trong notation cũ?\n> 2. UML link attribute (vd Hours) vẽ thế nào? Khác attribute thông thường ra sao?\n> 3. `*` trong UML multiplicity nghĩa gì?\n\n---\n\n","file":"materials/DB-Chapter2.md","section":7},{"id":"c2-08","group":"c2","kind":"source","title":"7. Problems with ER Models","markdown":"## 7. Problems with ER Models\n\n### 7.1. Tại sao bàn về hạn chế? (slide 80)\n\nER tốt nhưng không vạn năng. Có 2 lớp vấn đề:\n1. ER **không** biểu diễn được mọi loại ràng buộc (semantic constraint).\n2. ER **dễ bị vẽ sai** dẫn tới ý nghĩa lệch (connection traps: fan/chasm).\n\nBiết trước hai cái bẫy này giúp bạn vẽ ERD vững và đặt \"trigger\" / \"application logic\" cho ràng buộc còn lại.\n\n### 7.2. Semantic constraints (slide 81)\n\n- **Constraints không thể biểu diễn trực tiếp** trong ER diagram.\n- Phải được enforced bởi: **trigger mechanism**, **application programs**, hoặc cách khác (CHECK constraint, stored procedure).\n- **Examples:**\n  - Age của employee phải > 18.\n  - Salary của department manager phải > salary của các employee khác trong cùng phòng.\n  - Khi tăng salary, mức tăng không quá 20% lương hiện tại.\n\n| Constraint | Vì sao ERD khó biểu diễn? | Cách enforce |\n|---|---|---|\n| Age > 18 | Cần tính từ birthdate và ngày hiện tại | SQL `CHECK (age > 18)` / trigger |\n| Manager salary cao nhất phòng | So sánh nhiều tuple | Trigger / assertion |\n| Tăng ≤ 20% | Dynamic constraint phụ thuộc giá trị cũ vs mới | Trigger BEFORE UPDATE |\n\n> 💡 **Hiểu đơn giản:** ER chỉ vẽ được \"Salary là attribute kiểu số\". Còn ràng buộc \"lương sếp > lương lính\" liên quan *so sánh giá trị giữa nhiều entity instance* — vượt khả năng của hình vẽ static. Phải dùng SQL `CHECK` / `TRIGGER` / logic ở tầng application (vd Spring Boot validator).\n\n### 7.3. Connection traps (slide 82, 83)\n\n- Often do *misinterpretation* of relationship.\n- 2 loại chính: **fan traps** + **chasm traps**.\n\n| Trap | Nội dung | Thường do |\n|---|---|---|\n| **Fan Trap** | Pathway giữa các entity instance **mơ hồ** | ≥ 2 quan hệ 1:N tỏa quạt từ cùng 1 entity |\n| **Chasm Trap** | Model gợi ý có quan hệ nhưng pathway **không tồn tại** cho một số instance | Optional (partial) participation |\n\n### 7.4. Fan Trap — slide 84, 85\n\n> 📊 **Hình 7.1 — Fan Trap:**\n\n```\n   ┌──────┐  N  ╔═══╗  1  ┌──────────┐  1  ╔═════════╗  N  ┌──────┐\n   │ Staff│═════║Has║─────│ Division │─────║Operates ║═════│Branch│\n   └──────┘     ╚═══╝     └──────────┘     ╚═════════╝     └──────┘\n\n   Staff entities    Has    Division   Operates   Branch entities\n     SG37 ●────r1───●                                B003 ●\n                          D1                  r4 ●─B003\n     SA9  ●────r2───●     │\n                          ─┼──r1───●          r5 ●─B007\n     SL21 ●────r3───●                                B007 ●\n                          D2                  r6 ●─B005\n                                                  B005 ●\n```\n\n**Vấn đề:** *\"At which branch office does staff number SG37 work?\"*\n- SG37 → r1 → Division D1 (qua HAS).\n- D1 → r4 → Branch B003 (qua OPERATES) **HOẶC** D1 → r5 → Branch B007.\n- → **Không xác định được** SG37 thuộc B003 hay B007. Đây là **Fan Trap**.\n\n**Cách fix (slide 85):**\n\n```\n   ┌──────────┐  1  ╔═════════╗  N  ┌──────┐  1  ╔═══╗  N  ┌──────┐\n   │ Division │─────║Operates ║═════│Branch│═════║Has║─────│Staff │\n   └──────────┘     ╚═════════╝     └──────┘     ╚═══╝     └──────┘\n```\n\nĐặt **Branch ở giữa** thay cho Division. Bây giờ: Staff SG37 → Has → Branch B003 → Operates → Division D1. Đường đi **duy nhất** → trả lời được \"SG37 works at B003\".\n\n> 💡 **Hiểu đơn giản (Fan Trap):** giống \"Lan ở Sài Gòn (city), Sài Gòn có quận 1, 3, 7 — vậy Lan ở quận nào?\" — không suy ra được. Sửa: vẽ trực tiếp \"Lan ở quận 1\", còn quận 1 ∈ Sài Gòn là chuyện khác.\n\n### 7.5. Chasm Trap — slide 86, 87\n\n> 📊 **Hình 7.2 — Chasm Trap:**\n\n```\n   ┌──────┐ 1 ╔═══╗ N ┌─────┐  1  ┌────────┐  N  ┌────────────────┐\n   │Branch│═══║Has║───│Staff│─────│Oversees│─────│PropertyForRent │\n   └──────┘   ╚═══╝   └─────┘     └────────┘     └────────────────┘\n                                  (single line: optional)\n\n   Branch     Has     Staff     Oversees   PropertyForRent\n   B003 ●────r1───●  SG37 ●────r4──────────●  PG36\n   B007 ●────r2───●  SA9  ●  (no oversees!) ●  PA14   ← orphan!\n   B005 ●────r3───●  SL21 ●────r5──────────●  PL94\n```\n\n**Vấn đề:** *\"At which branch office is property PA14 available?\"*\n- Từ PA14 đi ngược: Oversees → tìm Staff → Has → Branch.\n- Nhưng PA14 *không có* Oversees (vì Oversees có participation **partial** — không phải property nào cũng được oversee).\n- → Không trả lời được. Đây là **Chasm Trap**.\n\n**Cách fix (slide 87):**\n\n```\n   ┌──────┐ 1 ╔═══╗ N ┌─────┐ 1 ┌────────╗ N ┌────────────────┐\n   │Branch│═══║Has║───│Staff│───│Oversees│───│PropertyForRent │\n   └──┬───┘   ╚═══╝   └─────┘   └────────┘   └─────┬──────────┘\n      ║                                              ║\n      ║ 1                                          N ║\n      ╚═══════════════ Offers ═════════════════════╝\n                       (relationship trực tiếp Branch—Property)\n```\n\nThêm relationship trực tiếp **Offers** giữa Branch và PropertyForRent. Bây giờ PA14 có *đường trực tiếp* tới B007 → trả lời \"PA14 ở branch B007\".\n\n> 💡 **Hiểu đơn giản (Chasm Trap):** giống \"sách X gắn với thủ thư Y, nhưng có sách chưa được giao thủ thư nào → không biết sách đó thuộc chi nhánh nào\". Sửa: gán sách vào chi nhánh **trực tiếp** thay vì qua thủ thư.\n\n> 📝 **Tóm lại section 7:**\n> - **Semantic constraints**: ER không vẽ được; phải dùng trigger / application / CHECK.\n> - **Fan Trap**: ≥ 2 quan hệ 1:N tỏa quạt → đường đi mơ hồ. Fix: đặt entity \"ngã ba\" ở giữa.\n> - **Chasm Trap**: pathway có vẻ tồn tại nhưng do partial participation, một số instance \"lạc\" → fix bằng quan hệ trực tiếp.\n> - **Một câu ghi nhớ:** *\"Fan trap mơ hồ ở giữa, Chasm trap đứt đoạn ở rìa — cả hai đều fix bằng cách thay đổi vị trí relationship.\"*\n\n> ❓ **Tự kiểm tra section 7:**\n> 1. Semantic constraint khác structural constraint chỗ nào? Cho 1 ví dụ mỗi loại.\n> 2. Fan Trap thường xuất hiện trong hình hình học nào?\n> 3. Trong Chasm Trap, tại sao thêm 1 relationship trực tiếp lại \"cứu\" được?\n\n---\n\n","file":"materials/DB-Chapter2.md","section":8},{"id":"c2-09","group":"c2","kind":"source","title":"TH2 — Bảng tra nhanh trước khi thi","markdown":"## TH2 — Bảng tra nhanh trước khi thi\n\n| Concept | 1 dòng định nghĩa | Ký hiệu/cú pháp | Ví dụ COMPANY | Slide |\n|---|---|---|---|---:|\n| Entity | \"Thứ\" có sự tồn tại độc lập | (chữ nhật) | John Smith | 23 |\n| Entity Type | Tập entities cùng attributes | `▭ EMPLOYEE` | EMPLOYEE | 27 |\n| Entity Set | Tập instance hiện tại | — | {e1, e2, …} | 27 |\n| Simple attr | 1 giá trị atomic | Oval | Ssn | 26 |\n| Composite attr | Nhiều thành phần | Oval cha–con | Name(Fname,Minit,Lname) | 26 |\n| Multi-valued attr | Nhiều giá trị | Oval **đôi** | Locations | 26 |\n| Derived attr | Suy từ attr khác | Oval **đứt** | Number_of_employees | 26 |\n| Key | Uniqueness constraint | Tên **gạch chân** | Ssn | 28 |\n| Relationship type | Khuôn liên kết giữa entity types | Hình thoi `◇` | WORKS_FOR | 36 |\n| Relationship instance | Liên kết cụ thể | rᵢ | (John Smith, ProductX) | 36 |\n| Degree | Số entity types tham gia | binary/ternary/n-ary | SUPERVISION = 2 | 38 |\n| Recursive | Cùng entity type, vai khác | Role names | SUPERVISION (sup/subord) | 40 |\n| Cardinality 1:1 | Mỗi bên tối đa 1 | `1 ◇ 1` | MANAGES | 42–43 |\n| Cardinality 1:N | 1 phía 1 — N phía nhiều | `1 ◇ N` | CONTROLS | 42 |\n| Cardinality M:N | Nhiều hai bên | `M ◇ N` | WORKS_ON | 42, 44 |\n| Total participation | Bắt buộc | Đường **đôi** | EMPLOYEE in WORKS_FOR | 45 |\n| Partial participation | Không bắt buộc | Đường **đơn** | EMPLOYEE in MANAGES | 45 |\n| Relationship attr | Gắn vào hình thoi | Oval nối hình thoi | Hours của WORKS_ON | 47 |\n| Weak entity | Không có key riêng | Chữ nhật **đôi** | DEPENDENT | 49 |\n| Identifying rel. | Nối weak với owner | Hình thoi **đôi** | DEPENDENTS_OF | 49 |\n| Partial key | Phân biệt weak trong owner | Gạch chân **đứt** | Name của DEPENDENT | 50 |\n| (min,max) | Cặp số thay cardinality + participation | `(min,max)` | (4,N) trên DEPARTMENT | 70 |\n| UML class | 3 ngăn (name/attr/op) | Class box | EMPLOYEE class | 74 |\n| Aggregation | Whole–part trong UML | `◇` | DEPARTMENT—LOCATION | 74 |\n| Multiplicity | Số bội UML | `min..max`, `*` | `4..*`, `0..1` | 77 |\n| Semantic constraint | Không biểu diễn trên ERD | (text) | \"lương sếp > lương lính\" | 81 |\n| Fan trap | Pathway mơ hồ | (lỗi thiết kế) | Staff–Division–Branch | 84 |\n| Chasm trap | Pathway đứt đoạn | (lỗi thiết kế) | Branch–Staff–Property | 86 |\n\n---\n\n","file":"materials/DB-Chapter2.md","section":9},{"id":"c2-10","group":"c2","kind":"source","title":"TH3 — Sai lầm thường gặp khi học ER","markdown":"## TH3 — Sai lầm thường gặp khi học ER\n\n| Sai lầm | Tại sao sai | Cách đúng |\n|---|---|---|\n| Quên gạch chân **khóa chính** trong ERD | Khóa là ràng buộc bắt buộc, không gạch chân = không có key | Luôn gạch chân Ssn, Number, … |\n| Vẽ multivalued attribute thành **2 oval rời** | Sai semantics: 2 oval rời = 2 attribute khác nhau | 1 oval **viền đôi** duy nhất (`{Locations}`) |\n| Đặt cardinality 1:N **ngược chiều** | Phía 1 và phía N bị hoán đổi → hiểu sai nghiệp vụ | Đọc lại \"1 X có nhiều Y\" → X là phía 1 |\n| Nhồi `Hours` (M:N attr) vào EMPLOYEE | Cùng employee có nhiều project, mỗi project khác giờ → mất dữ liệu | `Hours` phải nằm trên relationship WORKS_ON |\n| Quên đường đôi cho **weak entity** trong ERD | Vẽ thành chữ nhật đơn → mất dấu weak | Chữ nhật **viền đôi** + identifying relationship cũng viền đôi |\n| Quên **role names** cho recursive (SUPERVISION) | Không phân biệt được 2 vai → vô nghĩa | Ghi rõ Supervisor / Supervisee ở 2 nhánh |\n| Coi *\"unique number\"* không phải key | Bỏ qua key candidate thứ 2 | Mỗi `unique` thường là 1 candidate key |\n| Đặt entity cho cả \"Salary\" | Salary là *attribute* của EMPLOYEE, không phải entity | Đếm: nó có \"tồn tại độc lập\" không? Salary thì không |\n| Vẽ ternary thành 3 binary | Mất semantics bộ ba (slide 67 case b) | Giữ ternary hoặc reify thành weak entity |\n| Bỏ qua `Locations` của DEPARTMENT | Phớt lờ \"may have several locations\" → mất dữ liệu | Multivalued attribute |\n| Quên derived attr | Xem `age` là attribute thường → trùng lặp với Bdate | Oval nét đứt |\n| Để Fan trap trong ERD đa-cấp | Đường đi giữa các instance mơ hồ | Đặt entity \"ngã ba\" vào đúng vị trí |\n\n---\n\n","file":"materials/DB-Chapter2.md","section":10},{"id":"c2-11","group":"c2","kind":"source","title":"TH4 — Bài tập tự luyện có lời giải","markdown":"## TH4 — Bài tập tự luyện có lời giải\n\n### Bài 1 (mức độ: dễ — Trắc nghiệm)\n\n**Đề:** Trong ERD, ký hiệu nào sau đây biểu thị một **derived attribute**?\n- A. Oval với tên gạch chân\n- B. Oval viền đôi\n- C. Oval viền đứt\n- D. Oval nối với nhiều oval con\n\n<details><summary>Xem lời giải</summary>\n\n**Đáp án: C — Oval viền đứt** (dashed oval).\n- A là key attribute.\n- B là multi-valued.\n- D là composite.\n- C là derived (vd Number_of_employees).\n</details>\n\n### Bài 2 (mức độ: trung bình — Trắc nghiệm)\n\n**Đề:** Cho relationship `WORKS_ON` giữa EMPLOYEE và PROJECT với cardinality M:N. Attribute `Hours` của relationship này có thể migrate về:\n- A. EMPLOYEE\n- B. PROJECT\n- C. Cả EMPLOYEE và PROJECT\n- D. Không thể migrate, phải để trên relationship\n\n<details><summary>Xem lời giải</summary>\n\n**Đáp án: D — Không thể migrate.**\nVì `Hours` phụ thuộc *từng cặp* (employee, project): cùng 1 employee làm trên nhiều project với số giờ khác nhau, và 1 project có nhiều employee với giờ khác nhau. Migrate sang EMPLOYEE → mất thông tin per-project; migrate sang PROJECT → mất thông tin per-employee. Quy tắc: **M:N attr phải nằm trên relationship**.\n</details>\n\n### Bài 3 (mức độ: trung bình — Tự luận)\n\n**Đề:** Cho mô tả: *\"Một thư viện có nhiều BRANCH (id duy nhất, address). Mỗi BRANCH có nhiều BOOK (id duy nhất, title, year). Mỗi BOOK có thể có nhiều AUTHOR (chỉ ghi name). Mỗi BOOK có nhiều COPY, mỗi copy có copy_number (chỉ duy nhất trong cùng book).\"*\nVẽ ERD và chỉ rõ entity nào là weak.\n\n<details><summary>Xem lời giải</summary>\n\n**Entity types & attributes:**\n- BRANCH: **id** (key), address (strong)\n- BOOK: **id** (key), title, year (strong)\n- AUTHOR: **name** (key — giả định name unique) (strong)\n- COPY: copy_number (**partial key**) — **WEAK**, vì copy_number chỉ duy nhất trong cùng 1 book.\n\n**Relationships:**\n- HOLDS (BRANCH 1 — BOOK N): mỗi book thuộc 1 branch.\n- WRITTEN_BY (BOOK M — AUTHOR N): book có nhiều author, author viết nhiều book.\n- HAS_COPY (BOOK 1 — COPY N) — **identifying relationship** (vì COPY weak).\n\n**ERD (Mermaid):**\n```mermaid\nerDiagram\n  BRANCH ||--o{ BOOK : HOLDS\n  BOOK }o--o{ AUTHOR : WRITTEN_BY\n  BOOK ||--|{ COPY : HAS_COPY\n  BRANCH { string id PK; string address }\n  BOOK { string id PK; string title; int year }\n  AUTHOR { string name PK }\n  COPY { string copy_number \"partial key\" }\n```\n\n**Giải thích:** COPY là weak vì copy_number không duy nhất toàn cục — copy `#1` của Book A và copy `#1` của Book B là 2 copy khác nhau. Định danh đầy đủ = (Book.id, copy_number).\n</details>\n\n### Bài 4 (mức độ: trung bình — Tự luận)\n\n**Đề:** Cho relationship `WORKS_FOR` giữa EMPLOYEE — DEPARTMENT, với (min,max) như sau: EMPLOYEE `(1,1)`, DEPARTMENT `(4,N)`. Diễn giải bằng tiếng Việt.\n\n<details><summary>Xem lời giải</summary>\n\n- Phía EMPLOYEE `(1,1)`: mỗi employee tham gia relationship **đúng 1 lần** — nghĩa là **bắt buộc thuộc 1 department và chỉ 1**.\n- Phía DEPARTMENT `(4,N)`: mỗi department có **tối thiểu 4** và **tối đa N (nhiều)** employees.\n- Tương đương cardinality cũ: N:1 (employee:department); participation: total cả 2 phía. Nhưng (min,max) còn nói thêm \"min ≥ 4\" mà notation cũ KHÔNG vẽ được.\n\n**Ý nghĩa nghiệp vụ:** một phòng phải có ít nhất 4 nhân viên mới được tồn tại trong CSDL — đây là semantic constraint mạnh, hữu ích khi kiểm tra deletion.\n</details>\n\n### Bài 5 (mức độ: khó — Tự luận)\n\n**Đề:** Cho ERD sau (mô tả bằng text):\n- COURSE — has — INSTRUCTOR (1:N), single line từ COURSE, double line từ INSTRUCTOR.\n- INSTRUCTOR — teaches — STUDENT (1:N), single line cả hai.\n\nHỏi: ERD này có **chasm trap** không? Nếu có, đề xuất cách fix.\n\n<details><summary>Xem lời giải</summary>\n\n**Có chasm trap.** Lý do:\n- Truy vấn \"Sinh viên Nam đang học khoá nào?\" cần đi: STUDENT → teaches → INSTRUCTOR → has → COURSE.\n- Từ phía COURSE đến INSTRUCTOR là **1:N + INSTRUCTOR total** (đường đôi) → không vấn đề.\n- Nhưng INSTRUCTOR → STUDENT là **partial cả hai** (đường đơn) → có instructor chưa dạy student nào, *VÀ* có student chưa được instructor nào dạy.\n- → Với student \"Nam\" nếu không có teaches link, **không thể truy ra COURSE** mà bạn ấy đang học.\n\n**Cách fix:** thêm relationship trực tiếp `ENROLLS` giữa STUDENT — COURSE (M:N):\n```\n   COURSE ━━━ has ━━━ INSTRUCTOR ─── teaches ─── STUDENT\n       ┃                                              ┃\n       ┃                  ENROLLS (M:N)               ┃\n       ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛\n```\nBây giờ student → ENROLLS → course là đường trực tiếp, không phụ thuộc instructor. Truy vấn \"khoá Nam đang học\" trả lời được.\n\n**Bonus:** đây là pattern phổ biến — quan hệ \"học\" giữa student và course thường nên là **trực tiếp**, instructor chỉ là attribute / quan hệ phụ.\n</details>\n\n---\n\n","file":"materials/DB-Chapter2.md","section":11},{"id":"c2-12","group":"c2","kind":"source","title":"TH5 — Liên kết Lab / BTL","markdown":"## TH5 — Liên kết Lab / BTL\n\n### Lab 1 (`Labs/Lab 1.docx`)\nLab 1 thường yêu cầu vẽ ERD cho một bài toán cụ thể (giống case Hospital, Library, Course Registration). Kiến thức cần:\n- Section 4 toàn bộ (entity, attribute, key, relationship, weak entity, constraints).\n- Cheat-sheet ký hiệu (slide 56 / TH2).\n- Quy trình 5 bước trong section 5.\n\n### BTL1 (`BTL1_DB_Lab/`)\nBTL1 (Bài Tập Lớn 1) yêu cầu **Conceptual Design + Logical Design**. Pha conceptual = trực tiếp dùng kiến thức chương 2:\n- Vẽ ERD đầy đủ (entity types, attributes, relationship types, cardinality, participation).\n- Phân tích weak entity nếu có (vd: line item của hóa đơn, copy của book).\n- Đặt cardinality + participation chính xác.\n\n→ **Chất lượng ERD quyết định chất lượng schema cuối** ở pha mapping (chương 4).\n\n### BTL2 (`BTL2_DB_Lab/`)\nBTL2 thực hiện trên DBMS thực — schema từ BTL1 được implement. Nếu ERD ở BTL1 sai, sẽ phải refactor schema, đôi khi viết migration script. → Đầu tư thời gian vào ERD của BTL1 là *đầu tư có lãi* cho BTL2.\n\n### Liên hệ với chương sau\n- **Chương 3 (EER):** mở rộng ER với specialization/generalization (case study OSU slide 66 đã có sneak peek `d` từ USER → STUDENT/TEACHER).\n- **Chương 4 (Relational Mapping):** 7 quy tắc map ERD → relational schema. Học chương 2 giỏi → chương 4 nhẹ.\n- **Chương 6 (SQL):** SQL `CREATE TABLE` chính là cài đặt schema từ chương 4, gốc rễ là ERD từ chương 2.\n\n---\n\n","file":"materials/DB-Chapter2.md","section":12},{"id":"c2-13","group":"c2","kind":"source","title":"Bảng Tổng Hợp Thuật Ngữ Chương 2","markdown":"## Bảng Tổng Hợp Thuật Ngữ Chương 2\n\n| STT | Thuật ngữ (EN) | Tiếng Việt | Định nghĩa ngắn | Slide # |\n|---:|---|---|---|---:|\n| 1 | Database Design | Thiết kế CSDL | Thiết kế conceptual schema | 5 |\n| 2 | Application Design | Thiết kế ứng dụng | Thiết kế chương trình/giao diện | 5 |\n| 3 | Miniworld | Thế giới thu nhỏ | Phần đời thực được mô hình hóa | 6 |\n| 4 | Conceptual Design | Thiết kế ý niệm | Tạo conceptual schema bằng ER | 8 |\n| 5 | Logical Design | Thiết kế logic | Map sang data model cài đặt | 9 |\n| 6 | Physical Design | Thiết kế vật lý | Storage, index, file organization | 10 |\n| 7 | ER Model | Mô hình thực thể-mối liên kết | High-level conceptual data model | 18 |\n| 8 | ER Diagram (ERD) | Sơ đồ ER | Diagrammatic notation của ER | 18 |\n| 9 | Entity | Thực thể | Thing có independent existence | 23 |\n| 10 | Entity Type | Kiểu thực thể | Tập entities cùng attributes | 27 |\n| 11 | Entity Set / Extension | Tập / phần ngoại diên | Tập instance tại 1 thời điểm | 27 |\n| 12 | Attribute | Thuộc tính | Property mô tả entity | 24 |\n| 13 | Simple Attribute | Thuộc tính đơn | Single atomic value | 26 |\n| 14 | Composite Attribute | Thuộc tính ghép | Có components | 26 |\n| 15 | Multi-valued Attribute | Thuộc tính đa trị | Có multiple values | 26 |\n| 16 | Derived Attribute | Thuộc tính suy diễn | Tính được từ attr khác | 26 |\n| 17 | Complex Attribute | Thuộc tính phức | Composite + multivalued | 26 |\n| 18 | Value Set / Domain | Miền giá trị | Data type của attribute | 24 |\n| 19 | Key / Uniqueness Constraint | Khóa | Attribute distinct cho mỗi entity | 28 |\n| 20 | Relationship | Liên kết (instance) | Sự kết hợp giữa entity instances | 36 |\n| 21 | Relationship Type | Kiểu liên kết | Tập associations giữa entity types | 36 |\n| 22 | Relationship Set | Tập liên kết | Tập instance của rel. type | 36 |\n| 23 | Degree | Bậc | Số entity types tham gia | 38 |\n| 24 | Recursive Relationship | Liên kết đệ quy | Cùng entity type ≥ 2 lần khác vai | 40 |\n| 25 | Role Name | Tên vai | Vai trò entity đóng trong rel. | 40 |\n| 26 | Cardinality Ratio | Tỉ số lượng | Max instances: 1:1, 1:N, M:N | 42 |\n| 27 | Participation Constraint | Ràng buộc tham gia | Total / partial | 45 |\n| 28 | Total Participation | Tham gia toàn phần | Mọi instance bắt buộc tham gia | 45 |\n| 29 | Partial Participation | Tham gia một phần | Không phải mọi instance | 45 |\n| 30 | Relationship Attribute | Thuộc tính relationship | Attr thuộc liên kết | 47 |\n| 31 | Weak Entity | Thực thể yếu | Không có key riêng | 49 |\n| 32 | Identifying Relationship | Liên kết định danh | Nối weak với owner | 49 |\n| 33 | Partial Key / Discriminator | Khóa bộ phận | Phân biệt weak trong owner | 49 |\n| 34 | Owner / Identifying Entity | Thực thể chủ | Cung cấp định danh cho weak | 49 |\n| 35 | (min, max) Notation | Ký hiệu min-max | Cặp số thay cardinality + participation | 70 |\n| 36 | UML Class Diagram | Sơ đồ lớp UML | Class/attribute/operation/association | 73 |\n| 37 | Aggregation (UML) | Tổ hợp | Quan hệ whole–part | 74 |\n| 38 | Multiplicity | Số bội | `min..max`, `*` trong UML | 77 |\n| 39 | Semantic Constraint | Ràng buộc ngữ nghĩa | Không vẽ được trên ERD | 81 |\n| 40 | Connection Trap | Bẫy liên kết | Sai lầm thiết kế gây mơ hồ pathway | 82 |\n| 41 | Fan Trap | Bẫy quạt | ≥ 2 1:N tỏa từ 1 entity → mơ hồ | 83, 84 |\n| 42 | Chasm Trap | Bẫy hố ngăn | Pathway có vẻ tồn tại nhưng đứt | 83, 86 |\n\n---\n\n","file":"materials/DB-Chapter2.md","section":13},{"id":"c2-14","group":"c2","kind":"source","title":"Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\nDựa trên format thi HCMUT (50% trắc nghiệm + tự luận, 90 phút):\n\n**Trắc nghiệm thường hỏi:**\n- Phân biệt 4 loại attribute (cho 1 ví dụ → hỏi loại).\n- Ký hiệu nào = weak / multivalued / derived / total participation.\n- Cardinality ratio của 1 relationship cho trước.\n- (min,max) notation: ý nghĩa của (0,1), (1,N), (4,N).\n- Degree của 1 relationship.\n\n**Tự luận thường hỏi:**\n- Cho đoạn requirements → vẽ ERD đầy đủ. Phải có: entity với keys gạch chân, đầy đủ attribute (composite, multivalued, derived nếu có), relationship với cardinality + participation, weak entity + identifying nếu có, role names cho recursive.\n- Phát hiện và sửa Fan/Chasm Trap trong 1 ERD.\n- Đổi notation Elmasri ↔ (min,max) ↔ UML class.\n- Giải thích tại sao M:N attr không thể migrate.\n\n---\n\n","file":"materials/DB-Chapter2.md","section":14},{"id":"c2-15","group":"c2","kind":"source","title":"Câu Hỏi Ôn Tập (từ slide gốc)","markdown":"## Câu Hỏi Ôn Tập (từ slide gốc)\n\n1. **(slide 60)** Vẽ ERD cho course registration HCMUT (Group A) và Library University (Group B).\n2. **(slide 61)** Vẽ ERD cho Hospital (physicians, patients, admit, treat) — đã có giải mẫu trong section 5.5.\n3. **(slide 62–65)** Vẽ ERD cho OSU University course registration 3 phases — đối chiếu với slide 66.\n4. **(slide 84)** Trả lời: \"At which branch office does staff number SG37 work?\" và phát hiện Fan trap.\n5. **(slide 86)** Trả lời: \"At which branch office is property PA14 available?\" và phát hiện Chasm trap.\n6. **(slide 90 — Exercise 1)** **University Database**: vẽ ERD cho departments, lecturers (one head per department), course modules, students. Yêu cầu: head of department, module taught by 1 lecturer, student enrols multiple modules.\n7. **(slide 91 — Exercise 2)** **Small LIB Database**: branches (id unique, name unique, address), books (id, title, publisher, year, multiple authors, multiple copies với copy_number, availability + total copies).\n\n---\n\n","file":"materials/DB-Chapter2.md","section":15},{"id":"c2-16","group":"c2","kind":"source","title":"Đáp án Tự kiểm tra","markdown":"## Đáp án Tự kiểm tra\n\n### Section 1\n1. Pha **Logical Design** và **Physical Design** phụ thuộc DBMS cụ thể; pha **Requirements** và **Conceptual Design** không phụ thuộc.\n2. **Data req.**: cần lưu cái gì (entities, attr, constraints). **Functional req.**: cần làm gì với dữ liệu (transactions, queries) — vd \"tính tổng lương phòng\".\n3. **Không cần** vẽ lại — vì ER là conceptual, độc lập DBMS. Chỉ pha Logical/Physical mới cần làm lại theo đặc thù PostgreSQL.\n\n### Section 2\n1. **Weak entity** — DEPENDENT không có key riêng, định danh bằng cặp (Ssn của EMPLOYEE chủ + Name).\n2. MANAGES = **1:1**. EMPLOYEE **partial** (chỉ ai làm sếp); DEPARTMENT **total** (mỗi phòng phải có 1 manager).\n3. Vì `Hours` phụ thuộc *từng cặp* (employee, project) — quy tắc M:N relationship attr không migrate được.\n\n### Section 3\n1. ER thuộc pha **Conceptual Design**.\n2. ER không phụ thuộc DBMS → đổi từ MySQL sang Oracle không cần vẽ lại.\n3. **ER model** = lý thuyết / conceptual data model. **ER diagram** = cách *vẽ* nó bằng ký hiệu hình học.\n\n### Section 4\n1. Vì cùng 1 EMPLOYEE làm nhiều PROJECT với *số giờ khác nhau*. Migrate sang EMPLOYEE → cần lưu nhiều Hours/employee, mâu thuẫn \"1 attr = 1 giá trị\". Migrate sang PROJECT cùng vấn đề. → Hours phải trên relationship.\n2. SUPERVISION có **degree 2** (binary) nhưng cùng entity type EMPLOYEE 2 vai → **recursive**. Phải có role names (Supervisor, Supervisee) để phân biệt vai mỗi entity đóng.\n3. DEPENDENT là weak vì *không key riêng*: 2 con cùng tên \"An\" của 2 nhân viên là 2 dependent khác nhau. Identifying relationship = **DEPENDENTS_OF**, owner = EMPLOYEE.\n4. CONTROLS = 1:N giữa DEPARTMENT (phía 1) và PROJECT (phía N): 1 phòng kiểm soát nhiều project, mỗi project chỉ thuộc 1 phòng.\n\n### Section 5\n1. 3 binary chỉ ghi rời \"supplier liên hệ project\", \"supplier có thể supply part\", \"project dùng part\" — không nắm được *bộ ba* \"supplier S cung cấp part P **cho project J** với quantity Q\". 1 ternary mới nắm được.\n2. Hình thoi đơn = relationship thường. Hình thoi viền đôi = identifying — chỉ dùng nối weak entity với owner.\n3. TREATS = **M:N**. Patient **total** (\"must be treated by ≥ 1\"); Physician **partial** (\"may treat 0..N\"). Có attr `date_time` vì *mỗi treatment instance* có thời điểm riêng — không gắn vào patient (nhiều treatment) hay physician — phải nằm trên M:N.\n\n### Section 6\n1. `(0,1)` = **partial** (min=0) + cardinality phía đó **1** (max=1). Tương đương \"đường đơn\" + \"số 1\" trong notation cũ.\n2. UML link attribute (Hours) đặt trong **box** nối association line bằng **dashed line**. Khác attribute thông thường (đặt trong middle section của class). Lý do: link attr mô tả tính chất *liên kết*, không phải class.\n3. `*` trong UML = \"no maximum limit\" — tương đương `N` trong cardinality cũ.\n\n### Section 7\n1. **Structural** — biểu diễn được trên ERD bằng ký hiệu (vd \"EMPLOYEE—DEPARTMENT N:1 total\"). **Semantic** — không vẽ được, phải dùng trigger/CHECK/code (vd \"lương sếp > lương lính cùng phòng\").\n2. Fan Trap thường xuất hiện trong \"**chuỗi 3 entity** với 1 entity trung tâm có **2 đường 1:N tỏa ra hai bên**\" — hình dạng giống cái quạt nan, entity trung tâm là trục.\n3. Vì pathway gián tiếp (qua Staff) bị đứt cho các Property không có Staff oversee. Relationship trực tiếp Branch—Property (`Offers`) đảm bảo *mọi* Property đều có đường tới Branch của nó, không phụ thuộc Staff.\n\n---\n\n","file":"materials/DB-Chapter2.md","section":16},{"id":"c2-17","group":"c2","kind":"source","title":"Mối Quan Hệ Với Các Chương Khác","markdown":"## Mối Quan Hệ Với Các Chương Khác\n\n- **Chương trước (1 — Database System Concepts and Architecture):**\n  - 3-level architecture: ER thuộc tầng **Conceptual** — chương 2 cụ thể hóa cách *vẽ* schema ở tầng đó.\n  - Concept \"schema vs instance\" áp dụng trực tiếp: ERD = schema; hộp các instance e1, e2 bên trong = instance.\n\n- **Chương sau (3 — EER Model):**\n  - EER **mở rộng** ER với specialization/generalization (sneak peek ở case OSU slide 66 — tam giác `d` từ USER → STUDENT/TEACHER), category, union types. Toàn bộ kiến thức chương 2 **vẫn dùng** + thêm.\n\n- **Chương 4 — Relational Data Model & Mapping:**\n  - Pha **Logical Design** — biến ER thành relational schema. 7 quy tắc map: entity → table, M:N → bảng phụ, weak entity → bảng + FK của owner trong PK, multivalued → bảng riêng… Học chương 2 giỏi → chương 4 nhẹ.\n\n- **Chương 6 — SQL:**\n  - SQL `CREATE TABLE` chính là cài đặt schema từ chương 4, gốc rễ là ERD từ chương 2.\n\n- **Liên hệ Lab/BTL:** Lab 1, BTL1 (Conceptual + Logical Design), BTL2 (DBMS implementation) — đều dựa trên ERD của chương 2 (xem TH5).\n\n---\n\n*Hết Chương 2 — Bản tổng hợp final (CO2013 — HCMUT).*\n","file":"materials/DB-Chapter2.md","section":17},{"id":"guide-2","group":"c2","kind":"guide","title":"ER · Thực thể và quan hệ","markdown":"# 02 · Đọc nghiệp vụ và vẽ ER theo Chen\n\n> Đọc cùng **DB-Chapter2.md**. ER mô tả ngữ nghĩa nghiệp vụ trước khi lựa chọn bảng và khóa ngoại.\n\n![Chen: thực thể, thuộc tính, quan hệ và tham gia toàn phần](../docs/assets/chen.svg)\n\n## Bắt đầu từ miniworld, không bắt đầu từ tên bảng\n\n“Mỗi anime có mã, tên và năm phát hành. Anime thuộc ít nhất một thể loại. Một thể loại có thể chưa có anime. Một anime có nhiều tập; số tập chỉ duy nhất trong cùng anime.”\n\nBước 1: chọn **ANIME**, **GENRE**, **EPISODE** là các loại thực thể. Bước 2: tách thuộc tính khỏi quan hệ. Tên thể loại có thực thể riêng vì thể loại được tái sử dụng. Bước 3: viết câu theo hai chiều. Một anime có nhiều genre; một genre có nhiều anime, nên **Has_genre là M:N**. Bước 4: hỏi điều kiện tối thiểu. ANIME tham gia toàn phần vì mỗi anime có ít nhất một genre; GENRE tham gia bộ phận vì có thể chưa được dùng.\n\n## Cardinality và participation trả lời hai câu khác nhau\n\n| Trục | Câu hỏi | Ví dụ |\n|---|---|---|\n| Cardinality ratio | Tối đa bao nhiêu? | ANIME—GENRE là M:N |\n| Participation | Có bắt buộc xuất hiện ít nhất một lần? | ANIME total, GENRE partial |\n\nTrong Chen, **đường đôi** biểu diễn total participation. Nhãn `1`, `N`, `M` biểu diễn tỷ lệ số lượng tối đa. Không suy total chỉ từ nhãn N; cũng không suy M:N chỉ vì hai phía đều total.\n\nVới min–max đặt sát thực thể, `(1,N)` ở ANIME nghĩa là mỗi anime tham gia từ một đến N instance của quan hệ. Đừng đọc nhầm vị trí này với ký hiệu “one/many” ở đầu bên kia của một cạnh Crow's Foot. Chú giải luôn phải nói rõ hệ ký hiệu đang dùng.\n\n## Thuộc tính: hỏi nó mô tả cái gì\n\n`AnimeID` là khóa, gạch chân; `Title` là thuộc tính đơn. `Address(Street, City)` minh họa thuộc tính phức hợp. `Phone` có nhiều giá trị là oval đôi. `Age` tính từ `BirthDate` là thuộc tính dẫn xuất, oval nét đứt.\n\nNgày thêm anime vào watch list phụ thuộc vào **cặp (watch list, anime)**, nên `AddedAt` thuộc quan hệ **Contains**. Không đặt vào ANIME: cùng anime có thể được hai người thêm vào hai ngày khác nhau. Không đặt vào WATCH_LIST: mỗi danh sách chứa nhiều anime với thời điểm khác nhau.\n\n## Thực thể yếu: thiếu khóa độc lập, không chỉ “có FK”\n\nEPISODE có `EpisodeNo`, nhưng số 1 có thể xuất hiện ở nhiều anime. Khóa đầy đủ sau mapping là `(AnimeID, EpisodeNo)`. Trong Chen, EPISODE dùng hình chữ nhật đôi; identifying relationship dùng hình thoi đôi; partial key `EpisodeNo` gạch chân nét đứt. EPISODE phải tham gia toàn phần vào quan hệ định danh.\n\nNếu thay nghiệp vụ bằng “mỗi tập có EpisodeID duy nhất toàn hệ thống”, có thể mô hình hóa thành thực thể mạnh. Quyết định dựa vào cách định danh, không dựa vào việc giao diện có cho tạo tập khi chưa chọn anime hay không.\n\n## Một lỗi thiết kế rất thực tế\n\nCó DEPARTMENT—EMPLOYEE và DEPARTMENT—PROJECT không tự động suy được nhân viên nào **thực sự làm** dự án nào. Cùng phòng không có nghĩa là cùng dự án: đây là kiểu suy diễn đường nối gây fan trap. Nếu cần dữ liệu phân công, phải có quan hệ WORKS_ON. Đường nối giữa hai entity chỉ có ích khi ngữ nghĩa của toàn đường đi phù hợp câu hỏi.\n\n## Bài tập\n\n1. Watch list và anime liên kết theo tỷ lệ nào? `AddedAt` ở đâu?\n2. Mỗi anime phải có ít nhất một studio: Produced_by là 1:N hay M:N?\n3. Genre chưa có anime có vi phạm total của ANIME không?\n4. Vì sao không gọi mọi bảng chứa FK là thực thể yếu?\n\n<details><summary>Lời giải</summary>\n\n1. M:N; `AddedAt` thuộc Contains, và trở thành cột của bảng liên kết khi mapping.\n2. Điều kiện “ít nhất một” chỉ nói minimum, chưa đủ để kết luận maximum. Nếu nhiều studio cùng sản xuất một anime và mỗi studio sản xuất nhiều anime thì M:N.\n3. Không. Total được xét riêng từng phía; GENRE đang được phép partial.\n4. Thực thể yếu cần owner key để định danh; bảng con có khóa riêng vẫn có thể là thực thể mạnh.\n\n</details>\n\n## Deliverable của buổi học\n\nViết một trang miniworld, liệt kê entity/key, quan hệ/role, maximum và minimum theo từng chiều. Vẽ Chen từ danh sách đó. Chưa cần SQL; chương 4 sẽ chuyển chính xác những quyết định này thành bảng.\n","file":"lessons/02-er.md"},{"id":"c3-00","group":"c3","kind":"source","title":"Chương 3: Mô hình Thực thể-Mối liên kết Mở rộng — *Enhanced Entity-Relationship (EER) Model*","markdown":"# Chương 3: Mô hình Thực thể-Mối liên kết Mở rộng — *Enhanced Entity-Relationship (EER) Model*\n\n> **Nguồn:** CO2013 Database Systems, HCMUT — Khoa KH&KT Máy tính\n> **Giảng viên phụ trách:** TS. Trần Minh Quang\n> **Giáo trình:** Elmasri & Navathe, *Fundamentals of Database Systems*, 7th Edition (Chương 8 — EER Model)\n> **File PDF gốc:** `Lectures/03_EER Model.pdf`\n> **Số slide trong PDF gốc:** **62 slide** (slide 1 = title, slide 59 = Q&A, slides 60–62 = 3 Exercises)\n> **Slide \"Outline\" lặp lại:** slide **2, 3, 5, 11, 19, 38, 49, 58** (8 slide) — đã gộp thành **một** mục lục duy nhất ở §0.4.\n> **Slide có diagram chính:** 8, 13, 14, 16, 24, 29, 30, 36, 41, 43, 47.\n>\n> **Mục tiêu của tài liệu này:** một sinh viên năm 2 ngành CNTT, **đã học xong chương 2 (ER Model)**, đọc một mạch là đủ hiểu EER, vẽ được EER cho miniworld bất kỳ, làm trọn 3 exercises slide gốc, **không cần mở slide gốc** hay đọc Elmasri.\n\n---\n\n","file":"materials/DB-Chapter3.md","section":0},{"id":"c3-01","group":"c3","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nEER là phần **mở rộng** của ER (chương 2). Nếu chưa nắm chương 2, đọc qua các concept sau:\n\n| Concept ER (chương 2) | Giải thích siêu ngắn |\n|---|---|\n| **Entity / Entity Type** | Đối tượng cần lưu (vd `EMPLOYEE`) — vẽ bằng hình chữ nhật. |\n| **Attribute** | Thuộc tính của entity (vd `Ssn`, `Salary`) — vẽ bằng oval. **Khóa chính** = gạch chân. |\n| **Multivalued / Derived Attribute** | Oval 2 vòng (multivalued) / oval nét đứt (derived). |\n| **Relationship** | Liên kết giữa entity (vd `WORKS_FOR`) — vẽ bằng hình thoi. |\n| **Cardinality 1:1, 1:N, M:N** | Một entity bên này tương ứng bao nhiêu entity bên kia. |\n| **Total / Partial Participation** | Đường đôi (total — *bắt buộc tham gia*) vs đường đơn (partial — *có thể không tham gia*). |\n| **Weak Entity** | Entity không tự định danh; phụ thuộc entity khác (vd `DEPENDENT` phụ thuộc `EMPLOYEE`). |\n\nNgoài ra cần biết:\n- **OOP** (Java/C++/Python): `class`, `subclass`, `inheritance`, `is-a`. EER mượn nhiều từ OOP.\n- **Set theory** (Toán rời rạc): `⊆` (subset), `∪` (union), `∩` (intersection), `∅` (empty set). Slide 55–57 dùng nhiều.\n\n> 💡 **Hiểu đơn giản:** ER cho bạn vẽ COMPANY đơn giản. Khi gặp **bài toán phức tạp** — *\"nhân viên có 3 loại Engineer/Secretary/Manager với attribute riêng\"*, *\"owner xe có thể là Person HOẶC Bank HOẶC Company\"* — ER không đủ. Chương 3 thêm 4 vũ khí: **Subclass/Superclass**, **Specialization/Generalization**, **Inheritance**, **Category (Union type)**.\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\nTrích từ đề cương CO2013 (mục L.O.2.1 — *Design a conceptual schema using the entity relationship model and its extended versions*):\n\n1. **Phân biệt** subclass, superclass; hiểu **IS-A relationship**.\n2. **Vẽ EER diagram** với ký hiệu chuẩn: 〔d〕 (disjoint), 〔o〕 (overlapping), đường đôi (total), đường đơn (partial), 〔U〕 (category).\n3. **Áp dụng Specialization** (top-down) và **Generalization** (bottom-up) để tinh chỉnh schema.\n4. **Phân loại 4 kiểu specialization** theo {disjoint/overlapping} × {total/partial}.\n5. **Phân biệt** *predicate-defined*, *attribute-defined*, *user-defined* subclass.\n6. **Vẽ Hierarchy vs Lattice**, hiểu **single inheritance** vs **multiple inheritance**.\n7. **Phân biệt Category (Union type)** vs **Shared Subclass** — đây là điểm hay nhầm và rất hay ra thi.\n8. **Đưa ra design choice** — khi nào nên dùng EER feature, khi nào nên gộp lại.\n9. **Làm được 3 Exercises slide gốc**: non-profit organization, WV Bank accounts, ngân hàng có chi nhánh.\n\n### 0.3. Lộ trình đọc đề xuất\n\n| TT | Phần | Mức độ | Thời gian | Ghi chú |\n|---:|---|---|---:|---|\n| 1 | §1–§2 Intro + Subclass/Superclass | **CORE** | 25–30 phút | Nền — phải nắm vững. |\n| 2 | §3 Specialization & Generalization | **CORE** | 30–40 phút | Top-down vs bottom-up. |\n| 3 | §4 Constraints & Hierarchies | **CORE** | 50–70 phút | **Phần dài nhất** — 4 tổ hợp {d/o}×{total/partial}, hierarchy vs lattice. |\n| 4 | §5 Categories (Union Types) | **CORE** | 30–40 phút | **Hay nhầm với Shared Subclass** — phải đọc kỹ. |\n| 5 | §6 Design Choices & Formal Definitions | NÂNG CAO | 20–30 phút | Set theory; đọc kỹ khi gặp câu lý thuyết. |\n| 6 | Exercises 1, 2, 3 | **CORE** | 60–90 phút | Y format đề thi cuối kỳ. |\n\n**Tổng:** 3–4 giờ đọc lần đầu + 1.5 giờ làm exercises. Đây là **chương dài thứ 2** sau §6 SQL.\n\n### 0.4. Outline chương (gộp 8 slide Outline lặp lại)\n\nSlide 2, 3, 5, 11, 19, 38, 49, 58 đều cùng outline (chỉ highlight section sắp vào). Đã gộp:\n\n> **Outline**\n> 1. **Introduction to Enhanced-ER Model**\n> 2. **Subclasses, Superclasses, and Inheritance**\n> 3. **Specialization and Generalization**\n> 4. **Constraints and Characteristics of Specialization and Generalization Hierarchies**\n> 5. **Categories**\n> 6. **Design Choices, and Formal Definitions**\n\n### 0.5. Concept map của chương\n\n```mermaid\nflowchart TD\n    A[ER Model nền tảng - Chương 2] --> B[EER Model]\n    B --> C[Subclass / Superclass]\n    B --> D[Specialization / Generalization]\n    B --> E[Inheritance: attribute + relationship]\n    B --> F[Category / Union Type]\n    D --> G[Disjoint d vs Overlap o]\n    D --> H[Total ═══ vs Partial ───]\n    D --> I[Hierarchy vs Lattice]\n    I --> J[Single inheritance]\n    I --> K[Multiple inheritance / Shared subclass]\n    F --> L[OR logic - subset of UNION]\n    K --> M[AND logic - subset of INTERSECTION]\n```\n\n> 📊 **Đọc diagram này thế nào:** ER là nền. EER thêm 4 nhánh concept. Constraint d/o và total/partial là luật nghiệp vụ gắn với specialization. Category (OR) và Shared Subclass (AND) là **2 cách dùng nhiều superclass khác nhau**.\n\n---\n\n","file":"materials/DB-Chapter3.md","section":1},{"id":"c3-02","group":"c3","kind":"source","title":"1. Introduction to Enhanced-ER Model","markdown":"## 1. Introduction to Enhanced-ER Model\n\n### 1.1. Tại sao có EER? (Motivation)\n\nHồi học chương 2, bạn vẽ ER cho COMPANY: `EMPLOYEE`, `DEPARTMENT`, `PROJECT`, `WORKS_ON`, `DEPENDENT`. Mọi nhân viên đều có cùng tập attribute. Nhưng đời thật **không đơn giản như vậy**:\n\n- *Engineer* có `Eng_type`; *Secretary* có `Typing_speed`; *Manager* có relationship riêng `MANAGES PROJECT`.\n- *SalariedEmployee* nhận `Salary` cố định; *HourlyEmployee* nhận `Pay_scale`.\n- *Owner* xe có thể là **Person HOẶC Bank HOẶC Company**.\n\nÉp vào ER thuần thì:\n- Hoặc bảng `EMPLOYEE` có **TẤT CẢ** attribute (`Eng_type`, `Typing_speed`, …) → nhiều cell `NULL`.\n- Hoặc tạo 5 entity riêng và **nhân đôi** mọi attribute chung → Data Redundancy.\n\n→ EER ra đời để mô hình hóa \"is-a\" tự nhiên: *Engineer **is a** Employee*, *Manager **is a** Employee*, *Person **is a** Owner*. Tư duy giống OOP.\n\n### 1.2. Slide 4 — EER thêm gì so với ER?\n\n**Nội dung slide gốc:**\n\n- **Enhanced ER** hoặc **Extended ER (EER) model**\n  - *Created to design more accurate database schemas.*\n  - *More complex requirements than traditional applications.*\n- *EER model includes all modeling concepts of the ER model. **In addition**, EER includes:*\n  - **Subclasses** and **superclasses**\n  - **Specialization** and **generalization**\n  - **Category** or **union type**\n  - **Attribute** and **relationship inheritance**\n- **EER diagrams** *— Diagrammatic technique for displaying these concepts in an EER schema.*\n\n| Thuật ngữ (EN) | Tiếng Việt | Định nghĩa đầy đủ |\n|---|---|---|\n| Enhanced ER (EER) model | Mô hình ER mở rộng | ER + subclass/superclass + specialization/generalization + category + attribute/relationship inheritance. |\n| EER diagram | Sơ đồ EER | Kỹ thuật biểu diễn trực quan các concept EER. |\n\n> 💡 **Hiểu đơn giản (Java OOP analogy):**\n> | OOP | EER tương đương |\n> |---|---|\n> | `class Employee` | Entity type / Superclass |\n> | `class Engineer extends Employee` | Subclass với IS-A relationship |\n> | `eng.salary` (kế thừa từ Employee) | Attribute inheritance |\n> | `interface Owner = Person \\| Company \\| Bank` | Category / Union type |\n\n> 💡 **Ví dụ với COMPANY — vì sao cần EER:**\n> Nếu để `Typing_speed`, `Eng_type`, `Tgrade` chung trong `EMPLOYEE` → engineer không có `Typing_speed` → NULL; secretary không có `Eng_type` → NULL. EER tách `EMPLOYEE` thành `SECRETARY/ENGINEER/TECHNICIAN/MANAGER` để mỗi loại chỉ giữ attribute thực sự cần.\n\n> 💡 **Hiểu đơn giản:** EER giống nâng cấp từ sơ đồ gia đình đơn giản → hồ sơ nhân sự có vai trò. ER chỉ nói *\"đây là người A, người B\"*; EER nói thêm *\"A là sinh viên kiêm trợ giảng; B là cựu sinh viên kiêm nhân viên\"*.\n\n> 📝 **Tóm lại §1:**\n> EER = ER + 4 concept mới: Subclass/Superclass, Specialization/Generalization, Category, Attribute/Relationship Inheritance.\n>\n> **Một câu ghi nhớ:** *EER = ER + tư duy \"kế thừa\" của OOP, để biểu diễn \"X is a Y\" tự nhiên.*\n\n> ❓ **Tự kiểm tra §1:**\n> 1. EER có chứa toàn bộ concept của ER không? Liệt kê 4 concept mới.\n> 2. Vì sao không nhét mọi attribute SECRETARY/ENGINEER/MANAGER vào chung EMPLOYEE?\n> 3. Nêu một tình huống COMPANY cần dùng subclass.\n\n---\n\n","file":"materials/DB-Chapter3.md","section":2},{"id":"c3-03","group":"c3","kind":"source","title":"2. Subclasses, Superclasses, and Inheritance","markdown":"## 2. Subclasses, Superclasses, and Inheritance\n\n### 2.1. Tại sao có concept này?\n\nMột entity type lớn thường có **nhóm nhỏ có ý nghĩa riêng**. `EMPLOYEE` lớn; `ENGINEER`, `SECRETARY`, `MANAGER` là nhóm nhỏ. Các nhóm nhỏ không tách rời hoàn toàn — engineer vẫn là employee và vẫn có `Ssn`, `Name`, `Salary`. Cần cách:\n1. **Giữ phần chung** ở một chỗ (tránh lặp).\n2. **Cho phép phần riêng** của từng loại.\n\n### 2.2. Slide 6 — Định nghĩa Subclass / Superclass\n\n**Nội dung slide gốc:**\n\n- **Subtype or subclass** of an entity type\n  - *Subgroupings of entities that are meaningful.*\n  - *Represented explicitly because of their significance to the database application.*\n- **Terms** for relationship between a superclass and any one of its subclasses:\n  - Superclass / subclass\n  - Supertype / subtype\n  - Class / subclass\n- *A class/subclass relationship is often called an **IS-A (IS-AN) relationship**.*\n\n| Thuật ngữ (EN) | Tiếng Việt | Định nghĩa |\n|---|---|---|\n| Subclass / Subtype | Lớp con / Kiểu con | Subset có ý nghĩa của entity type. |\n| Superclass / Supertype | Lớp cha / Kiểu cha | Entity type chứa subclass. |\n| IS-A relationship | Quan hệ \"là một\" | Mối nối subclass → superclass. *Engineer **is a** Employee*. |\n| Local attribute | Thuộc tính riêng | Attribute chỉ thuộc subclass (vd `Typing_speed` của SECRETARY). |\n| Local relationship | Relationship riêng | Relationship chỉ thuộc subclass (vd MANAGER `MANAGES` PROJECT). |\n\n### 2.3. Slide 7 — Ví dụ EMPLOYEE\n\n> *Ex: EMPLOYEE may be further grouped into SECRETARY, ENGINEER, MANAGER, TECHNICIAN, SALARIED_EMPLOYEE, HOURLY_EMPLOYEE, and so on.*\n> - Set of entities in each subgroups is a **subset** of the EMPLOYEE entity set.\n> - Each is called a **subclass of EMPLOYEE**.\n> - **EMPLOYEE is the superclass** for each of these subclasses.\n\n### 2.4. Slide 8 — EER diagram notation\n\n> 📊 **Hình 2.1 — EER diagram cho EMPLOYEE với 3 specialization (slide 8):**\n> ```\n>             (Fname)  (Minit)  (Lname)\n>                 \\       |       /\n>                       (Name)\n>                          |\n>     (Ssn) ─────[ EMPLOYEE ]───── (Birth_date)\n>                /     |     \\\n>          (Address)   |      \\\n>                      |\n>     ┌────────────────┴───────────────┐\n>     │                │               │\n>   〔 d 〕         (chỉ MANAGER)    〔 d 〕\n>   /  |  \\              │            /   \\\n>  ⊃   ⊃   ⊃             ⊃           ⊃     ⊃\n> SEC TECH ENG       MANAGER     SAL_EMP  HOUR_EMP\n>  │   │   │             │           │       │\n> Typing  Tgrade  Eng_type    ◇MANAGES   Salary  Pay_scale\n> _speed                          │                  │\n>                              PROJECT          ◇BELONGS_TO\n>                                                    │\n>                                              TRADE_UNION\n>\n> Slide 8 chứa 3 specializations:\n>   1) {SECRETARY, TECHNICIAN, ENGINEER} — disjoint\n>   2) {MANAGER}                          — đơn lẻ\n>   3) {SALARIED_EMPLOYEE, HOURLY_EMPLOYEE} — disjoint\n> ```\n>\n> 📊 **Đọc diagram này thế nào:**\n> - 〔d〕 = disjoint (mỗi entity chỉ thuộc 1 subclass trong nhóm).\n> - ⊃ = ký hiệu IS-A (subclass nằm trong superclass).\n> - Đường thẳng từ 〔d〕 lên EMPLOYEE = nối specialization tới superclass.\n> - Mỗi subclass có thể có attribute riêng (`Typing_speed`, `Tgrade`, `Eng_type`, `Salary`, `Pay_scale`) và/hoặc relationship riêng (`MANAGES` cho MANAGER, `BELONGS_TO` cho HOURLY_EMPLOYEE).\n\n### 2.5. Slide 9 — 5 quy tắc về subclass member\n\n**Nội dung slide gốc:**\n\n- *A subclass member is the **same** as the entity in the superclass, but in a **distinct specific role**.*\n- *An entity **cannot exist** in the database merely by being a member of a subclass; it **must also be a member of the superclass**.*\n- *A member of a superclass can be **optionally** included as a member of some of its subclasses.*\n- *It is **not necessary** that every entity in a superclass be a member of some subclass.*\n- *Superclass/subclass relationship is **one-to-one (1:1)**.*\n\n| Quy tắc | Diễn giải |\n|---|---|\n| **R1** | Một entity subclass = cùng entity trong superclass, chỉ thêm \"vai trò riêng\". |\n| **R2** | **Bắt buộc** có trong superclass trước. KHÔNG có Engineer mà không phải Employee. |\n| **R3** | **Tùy chọn** thuộc subclass. Một Employee có thể không phải Engineer/Secretary/Manager. |\n| **R4** | Không bắt buộc mọi entity superclass phải thuộc 1 subclass nào (xem completeness §4). |\n| **R5** | Quan hệ superclass/subclass là **1:1** — một bản ghi Employee tương ứng tối đa 1 bản ghi Engineer (cùng Ssn). |\n\n> 💡 **Hiểu đơn giản (analogy \"thẻ sinh viên\"):** Bạn là **sinh viên** (superclass). Khi tham gia CLB Tin học, bạn cũng là **thành viên CLB** (subclass). Bạn **vẫn là** sinh viên trước (R2). Có sinh viên không tham gia CLB nào (R3, R4). Một thẻ SV chỉ tương ứng tối đa 1 hồ sơ thành viên CLB (R5).\n\n### 2.6. Slide 10 — Inheritance (Kế thừa)\n\n**Nội dung slide gốc:**\n\n- *Subclass entity **inherits all attributes and relationships** of superclass.*\n- *A subclass, with its own specific (or local) attributes and relationships together with all the attributes and relationships it inherits from the superclass, can be considered an **entity type in its own right**.*\n\n| Thuật ngữ | Định nghĩa |\n|---|---|\n| **Attribute Inheritance** | Subclass tự động \"thấy\" mọi attribute của superclass. Engineer có `Ssn`, `Fname`, `Salary` (từ Employee) + `Eng_type` (riêng). |\n| **Relationship Inheritance** | Subclass cũng kế thừa relationship của superclass. Employee `WORKS_FOR` Department → Engineer cũng `WORKS_FOR` Department. |\n\n> 💡 **Hiểu đơn giản (Java analogy):**\n> ```java\n> class Employee { String ssn; String fname; double salary; }\n> class Engineer extends Employee { String engType; }\n> Engineer eng = new Engineer();\n> eng.ssn       // inherited\n> eng.salary    // inherited\n> eng.engType   // local\n> ```\n\n> 💡 **Hiểu đơn giản (analogy \"xe\"):** Subclass/superclass giống \"xe\" và \"xe máy/ô tô/xe tải\". Xe nào cũng có biển số, hãng, màu (chung); xe tải có tải trọng, ô tô có số chỗ (riêng). Không bắt xe máy phải có \"tải trọng xe tải\", cũng không lặp \"biển số\" ở mọi loại.\n\n> 📝 **Tóm lại §2:**\n> - Subclass = subset có ý nghĩa của entity type. Quan hệ với superclass: **IS-A**, **1:1**.\n> - Member subclass phải tồn tại trước trong superclass; thuộc subclass là tùy chọn.\n> - Subclass **kế thừa** tất cả attribute + relationship của superclass.\n>\n> **Một câu ghi nhớ:** *Subclass = \"tôi LÀ một entity của superclass, nhưng có thêm vai trò/đặc trưng riêng\".*\n\n> ❓ **Tự kiểm tra §2:**\n> 4. Vì sao một entity không thể tồn tại trong DB chỉ với tư cách subclass mà không phải superclass?\n> 5. Tỉ số cardinality giữa superclass và subclass là gì? Vì sao?\n> 6. `Typing_speed` nên đặt ở `EMPLOYEE` hay `SECRETARY`? Vì sao?\n> 7. Trong slide 8, `MANAGES` là relationship của MANAGER hay EMPLOYEE? Lý do?\n\n---\n\n","file":"materials/DB-Chapter3.md","section":3},{"id":"c3-04","group":"c3","kind":"source","title":"3. Specialization and Generalization","markdown":"## 3. Specialization and Generalization\n\n### 3.1. Tại sao có 2 concept này?\n\nHai chiều **ngược nhau** của cùng một quá trình thiết kế:\n- **Specialization** = top-down. Từ superclass `EMPLOYEE`, chia thành subclass.\n- **Generalization** = bottom-up. Từ 2 entity riêng `CAR`/`TRUCK`, gộp thành superclass `VEHICLE`.\n\nKết quả vẽ **giống hệt nhau**; chỉ khác **hướng tư duy**.\n\n### 3.2. Slide 12 — Specialization\n\n**Nội dung slide gốc:**\n\n- **Specialization**\n  - *Process of defining **a set of subclasses** of an entity type, called superclass.*\n  - *Defined on the basis of some **distinguishing characteristic** of the entities in the superclass.*\n  - *May have several specializations of the same entity type based on **different distinguishing characteristics**.*\n- **Subclass can have its own:**\n  - **Specific attributes** (local attributes)\n  - **Specific relationship types**\n\nEMPLOYEE có thể có **NHIỀU specialization** đồng thời:\n- Theo Job_type → `{SECRETARY, TECHNICIAN, ENGINEER, MANAGER}`\n- Theo Pay_method → `{SALARIED, HOURLY}`\n\n### 3.3. Slide 13 — Ví dụ Specialization\n\n> 📊 **Hình 3.1 — Specialization với defining attribute Job_type (slide 13):**\n> ```\n>             (Fname)(Minit)(Lname)\n>                  \\    |    /\n>                   (Name)\n>                     |\n>     (Ssn) ────[ EMPLOYEE ]────(Birth_date)\n>                /    |    \\\n>           (Address) |    (Job_type)\n>                     │\n>                  Job_type ← defining attribute\n>                     │\n>                  〔 d 〕  ← disjoint\n>                  /  |  \\\n>          'Secretary' 'Technician' 'Engineer'  ← predicate conditions\n>             ⊃     ⊃      ⊃\n>         ┌────┐ ┌─────┐ ┌──────┐\n>         │SEC │ │TECH │ │ ENG  │\n>         └────┘ └─────┘ └──────┘\n>           │       │       │\n>      (Typing_  (Tgrade) (Eng_type)\n>       speed)\n> ```\n\n### 3.4. Slide 14 — Instances of Specialization\n\n> 📊 **Hình 3.2 — Instances of specialization (slide 14):**\n> ```\n>     EMPLOYEE                SECRETARY\n>     ┌──────────┐            ┌──────────┐\n>     │ e₁ ●─────┼────────────┤ ● e₁     │\n>     │ e₂ ●─────┼──┐         │ ● e₄     │\n>     │ e₃ ●     │  │         │ ● e₅     │\n>     │ e₄ ●─────┼──┼─────────┤   ⋮      │\n>     │ e₅ ●─────┼──┘         └──────────┘\n>     │ e₆ ●     │            ENGINEER\n>     │ e₇ ●─────┼────┐       ┌──────────┐\n>     │ e₈ ●─────┼─┐  │       │ ● e₂     │\n>     │  ⋮       │ │  └───────┤ ● e₇     │\n>     └──────────┘ │          └──────────┘\n>                  │          TECHNICIAN\n>                  │          ┌──────────┐\n>                  └──────────┤ ● e₃     │\n>                             │ ● e₈     │\n>                             └──────────┘\n>\n> Quan hệ tập con:\n>   SECRETARY  ⊆ EMPLOYEE\n>   ENGINEER   ⊆ EMPLOYEE\n>   TECHNICIAN ⊆ EMPLOYEE\n>\n> e₆ thuộc EMPLOYEE nhưng KHÔNG thuộc subclass nào → partial.\n> ```\n\n### 3.5. Slide 15 — Generalization\n\n**Nội dung slide gốc:**\n\n- *Reverse process of Specialization.*\n- **Generalize** several entity types which have some common features into a single **superclass**.\n  - Original entity types are **special subclasses**.\n- **Generalization** *— Process of defining a generalized entity type from the given entity types.*\n\n### 3.6. Slide 16 — Ví dụ CAR + TRUCK → VEHICLE\n\n> 📊 **Hình 3.3 — Generalization (slide 16):**\n> ```\n> (a) Trước:                     (b) Sau khi generalize:\n>\n>  CAR              TRUCK             (Vehicle_id)(Price)(License_plate_no)\n>  Vehicle_id (k)   Vehicle_id (k)               \\    |    /\n>  License_plate_no License_plate_no            ┌─────────┐\n>  Price            Price                       │ VEHICLE │\n>  Max_speed        No_of_axles                 └────┬────┘\n>  No_of_passengers Tonnage                          │\n>                                                  〔 d 〕\n>                                                  /     \\\n>                                                 ⊃       ⊃\n>                                            ┌─────┐  ┌──────┐\n>                                            │ CAR │  │TRUCK │\n>                                            └─────┘  └──────┘\n>                                          /       \\    /     \\\n>                                  Max_speed No_of_p No_of_  Tonnage\n>                                            assengers axles\n> ```\n\n> 💡 **Hiểu đơn giản (top-down vs bottom-up):**\n> - **Specialization** = đi từ \"động vật\" → chia \"chó\", \"mèo\", \"cá\".\n> - **Generalization** = thấy \"iPhone\", \"Galaxy\", \"Pixel\" → nhận ra \"đều là điện thoại\" → đặt tên chung `PHONE`.\n\n### 3.7. Slide 17 — Notation phân biệt\n\n- *Diagrammatic notation **sometimes** used to distinguish between generalization and specialization* — arrow pointing to generalized superclass = generalization; arrows to specialized subclasses = specialization.\n- *We **do not use** this notation because it is often **subjective** as to which process is more appropriate.*\n- *We advocate **not drawing any arrows** in these situations.*\n\n→ **Quy tắc CO2013:** không vẽ mũi tên hướng. Kết quả EER giống nhau.\n\n### 3.8. Slide 18 — Data Modeling\n\n- *A superclass or subclass represents a **set of entities**.*\n- *Shown in **rectangles** in EER diagrams (as are entity types).*\n- *Sometimes, all entity sets are simply called **classes**, whether they are entity types, superclasses, or subclasses.*\n\n→ Trong EER, **class** = bất kỳ rectangle nào (entity type / superclass / subclass / category).\n\n> 📝 **Tóm lại §3:**\n> - **Specialization** = top-down. **Generalization** = bottom-up. Kết quả vẽ giống nhau.\n> - Subclass có thể có **specific attribute + specific relationship**.\n> - Một entity type có thể có nhiều specialization đồng thời theo các đặc trưng khác nhau.\n>\n> **Một câu ghi nhớ:** *Specialization là \"chẻ to ra nhỏ\"; Generalization là \"gom nhỏ lại thành to\". Cùng kết quả EER.*\n\n> ❓ **Tự kiểm tra §3:**\n> 8. Specialization và Generalization khác nhau ở hướng tư duy thế nào?\n> 9. Trong slide 8, EMPLOYEE có **3 specialization** đồng thời. Vô lý không? Vì sao?\n> 10. Vẽ EER thể hiện generalization từ 2 entity `STUDENT` (Major_dept) và `EMPLOYEE` (Salary) thành `PERSON` (Ssn, Name).\n\n---\n\n","file":"materials/DB-Chapter3.md","section":4},{"id":"c3-05","group":"c3","kind":"source","title":"4. Constraints and Characteristics of Specialization/Generalization Hierarchies","markdown":"## 4. Constraints and Characteristics of Specialization/Generalization Hierarchies\n\n### 4.1. Tại sao cần constraint?\n\nMột specialization có nhiều **biến thể**:\n- *Một entity có thể thuộc nhiều subclass cùng lúc không?* → disjoint vs overlapping.\n- *Mọi entity superclass có bắt buộc thuộc subclass nào không?* → total vs partial.\n- *Membership được xác định bằng giá trị attribute, hay user tự gán?* → predicate-defined / attribute-defined / user-defined.\n\nMỗi tổ hợp → schema khác nhau, semantics khác nhau.\n\n### 4.2. Slides 21-25 — 3 cách xác định subclass membership\n\n**Slide 21 — Determine subclass:**\n\n- **Predicate-defined** (or **condition-defined**) subclasses\n- **Attribute-defined** specialization\n- **User-defined**\n\n**Slide 22 — Predicate-defined subclass:**\n\n- *If we can determine **exactly those entities** that will become members of each subclass by a **condition**, the subclasses are called **predicate-defined**.*\n- *Condition is a constraint that determines subclass members.*\n- *Display a predicate-defined subclass by writing the **predicate condition** next to the line attaching the subclass to its superclass.*\n\n**Slide 23 — Attribute-defined specialization:**\n\n- *If **all subclasses** in a specialization have membership condition on the **same attribute** of the superclass, specialization is called an **attribute-defined specialization**.*\n- *Attribute is called the **defining attribute** of the specialization.*\n- *Ex: `JobType` is the defining attribute of the specialization {SECRETARY, TECHNICIAN, ENGINEER} of EMPLOYEE.*\n\n**Slide 25 — User-defined subclass:**\n\n- *If **no condition** determines membership, the subclass is called **user-defined**.*\n- *Membership in a subclass is determined by the database users by **applying an operation** to add an entity to the subclass.*\n- *Membership is **specified individually** for each entity by the user.*\n\n| Loại | Cách xác định | Ví dụ COMPANY | Khi nào dùng? |\n|---|---|---|---|\n| **Predicate-defined** | Condition trên attribute superclass | `Salary > 50000` → SENIOR | Luật rõ ràng từ attribute. |\n| **Attribute-defined** (case đặc biệt) | TẤT CẢ subclass dùng condition trên CÙNG 1 attribute | `Job_type` chia 3 subclass | Một attribute phân loại toàn bộ nhóm. |\n| **User-defined** | User tự gán thủ công | TRADE_UNION_MEMBER | Membership theo quy trình bên ngoài, không suy ra được. |\n\n→ **Phân biệt nhanh:**\n- *Predicate-defined* = từng subclass có condition riêng (có thể trên attribute khác nhau).\n- *Attribute-defined* = case đặc biệt — TẤT CẢ subclass cùng dùng 1 *defining attribute*.\n\n> 💡 **Ví dụ bổ sung:** Trong thư viện, `BORROWER` có subclass `VIP_MEMBER`. Nếu rule là `total_borrowed_books >= 100` → predicate-defined. Nếu thủ thư tự xét duyệt → user-defined.\n\n### 4.3. Slide 24 — EER notation cho attribute-defined\n\n> 📊 **Hình 4.1 — Attribute-defined specialization on Job_type (slide 24):**\n> ```\n>            ┌───────────────┐\n>            │   EMPLOYEE    │\n>            └───────┬───────┘\n>                    │\n>                  Job_type   ← Defining attribute (ghi cạnh đường nối)\n>                    │\n>                  〔 d 〕\n>                  /  |  \\\n>         'Secretary' 'Technician' 'Engineer'  ← Predicate condition\n>             ⊃     ⊃      ⊃\n>          ┌────────┐ ┌──────────┐ ┌────────┐\n>          │SECRETARY│ │TECHNICIAN│ │ENGINEER│  ← Predicate-defined subclass\n>          └────────┘ └──────────┘ └────────┘\n> ```\n\n### 4.4. Slides 26-28 — Disjointness và Completeness Constraints\n\n**Slide 26:**\n\n- *Two basic conditions apply to a specialization/generalization:* **disjointness** *and* **completeness** *constraints.*\n- **Disjointness constraint** — May be **disjointed** or **overlap**.\n- **Completeness (or totalness) constraint** — May be **total** or **partial**.\n- *Disjointness and completeness constraints are **independent**.*\n\n→ 2 ràng buộc **độc lập** → **4 tổ hợp** {d, o} × {total, partial}.\n\n**Slide 27 — Disjointness:**\n\n| Constraint | Ký hiệu | Ý nghĩa |\n|---|---|---|\n| **Disjoint** | 〔 d 〕 | Mỗi entity superclass thuộc **TỐI ĐA 1** subclass. |\n| **Overlapping** | 〔 o 〕 | Một entity có thể thuộc **NHIỀU** subclass cùng lúc. |\n\n**Slide 28 — Completeness:**\n\n| Constraint | Ký hiệu | Ý nghĩa |\n|---|---|---|\n| **Total** | ═══ (đường đôi) | Mọi entity superclass **PHẢI** thuộc ≥ 1 subclass. |\n| **Partial** | ─── (đường đơn) | Có entity superclass **KHÔNG** thuộc subclass nào. |\n\nCách nhớ nhanh:\n- `d` = **d**istinct/**d**isjoint = tách rời.\n- `o` = **o**verlap = chồng lắp.\n\n### 4.5. Slide 29 — Ví dụ Disjoint Partial\n\n> 📊 **Hình 4.2 — Disjoint Partial Specialization (slide 29):**\n> ```\n>            ┌───────────────┐\n>            │   EMPLOYEE    │\n>            └───────┬───────┘\n>                  Job_type\n>                    │ ─── (PARTIAL)\n>                  〔 d 〕   ← DISJOINT\n>                  /  |  \\\n>          ┌────────┐ ┌──────────┐ ┌────────┐\n>          │SECRETARY│ │TECHNICIAN│ │ENGINEER│\n>          └────────┘ └──────────┘ └────────┘\n> ```\n>\n> **Đọc:** Mỗi nhân viên thuộc **TỐI ĐA 1** trong 3 subclass (disjoint), và **CÓ THỂ KHÔNG** thuộc subclass nào (partial — vd `MANAGER` thuộc EMPLOYEE nhưng không thuộc 3 subclass này).\n\n### 4.6. Slide 30 — Ví dụ Overlapping Total\n\n> 📊 **Hình 4.3 — Overlapping Total Specialization PART (slide 30):**\n> ```\n>           (Part_no)   (Description)\n>                \\         /\n>             ┌────────┐\n>             │  PART  │\n>             └────┬───┘\n>                  │ ═══ (TOTAL)\n>                〔 o 〕   ← OVERLAPPING\n>                /     \\\n>               ⊃       ⊃\n>     ┌─────────────┐  ┌────────────┐\n>     │MANUFACTURED │  │  PURCHASED │\n>     │    PART     │  │    PART    │\n>     └─────────────┘  └────────────┘\n>      / | \\             /     \\\n> Drawing Manufacture  Supplier_  List_price\n> _no    _date         name\n> Batch_no\n> ```\n>\n> **Đọc:** Mỗi `PART` **PHẢI** là MANUFACTURED hoặc PURCHASED hoặc CẢ HAI (total). Một part có thể đồng thời được sản xuất nội bộ và mua từ nhà cung cấp khác (overlapping).\n\n### 4.7. Slide 31 — 4 loại Specialization\n\n**Nội dung slide gốc:**\n\n- *Hence, we have **four types** of specialization/generalization:*\n  - **Disjoint, total**\n  - **Disjoint, partial**\n  - **Overlapping, total**\n  - **Overlapping, partial**\n- *Note: **Generalization is usually total** because the superclass is derived from the subclasses.*\n\n| Loại | Ký hiệu | Tối đa 1 subclass? | Bắt buộc thuộc ≥ 1? | Ví dụ |\n|---|---|:---:|:---:|---|\n| **Disjoint, Total** | ═══ + 〔 d 〕 | Có | Có | Mỗi tài khoản ngân hàng phải là **đúng 1**: Savings/Checking/Loan. |\n| **Disjoint, Partial** | ─── + 〔 d 〕 | Có | Không | Employee có thể là Sec/Eng/Tech hoặc không thuộc nhóm nào. |\n| **Overlapping, Total** | ═══ + 〔 o 〕 | Không | Có | PART phải là manufactured/purchased, có thể cả hai. |\n| **Overlapping, Partial** | ─── + 〔 o 〕 | Không | Không | Person có thể là student/employee/alumnus hoặc tạm thời không thuộc nhóm. |\n\n> 💡 **Hiểu đơn giản (analogy \"lớp học thêm\"):**\n> - **Disjoint Total**: bắt buộc mỗi SV chọn đúng 1 chuyên ngành (CS / IT / IS).\n> - **Disjoint Partial**: được chọn tối đa 1 lớp năng khiếu (Bóng đá / Bơi / Cầu lông), hoặc không chọn.\n> - **Overlapping Total**: bắt buộc tham gia ≥ 1 CLB, có thể tham gia nhiều.\n> - **Overlapping Partial**: tham gia CLB nào cũng được, hoặc không.\n\n### 4.8. Slide 32 — Case Study: Identify Superclass-Subclass\n\n| Group | Hệ thống | Hints | Gợi ý thiết kế EER |\n|---|---|---|---|\n| **A** | Course registration of Bach Khoa University | Students (Grad-Student, undergrad-student), Modules (for grad-student, for undergrad-students) | `STUDENT` = superclass; `GRAD_STUDENT`, `UNDERGRAD_STUDENT` = subclass (disjoint, total). `MODULE` cũng có thể specialize thành `GRAD_MODULE`, `UNDERGRAD_MODULE`. |\n| **B** | Library of a University | Materials (Book, Journal, ...), Borrowers (Guest, Member) | `MATERIAL` = superclass; `BOOK`, `JOURNAL` = subclass. `BORROWER` = superclass; `GUEST`, `MEMBER` = subclass. |\n\n### 4.9. Slides 33-34 — Hierarchies vs Lattices\n\n**Slide 33:**\n\n- *A subclass may itself have further subclasses specified on it, forming a **hierarchy** or a **lattice**.*\n- **Specialization hierarchy:**\n  - *Every subclass participates as a subclass in **only one** class/subclass relationship.*\n  - *Results in a **tree** structure or strict hierarchy.*\n  - **Single inheritance**.\n- **Specialization lattice:**\n  - *Subclass can be a subclass in **more than one** class/subclass relationship.*\n  - **Multiple inheritance**.\n\n**Slide 34:**\n\n- *In a lattice or hierarchy, a subclass inherits attributes not only of its **direct superclass**, but also of **all its predecessor superclasses**.*\n- *A subclass with **more than one superclass** is called a **shared subclass**.*\n- *In case of multiple inheritance, if attribute (or relationship) originating in the same superclass inherited more than once via different paths in lattice — included **only once** in shared subclass.*\n\n| Khái niệm | Đặc điểm | Cấu trúc | Inheritance |\n|---|---|---|---|\n| **Hierarchy** | Mỗi subclass có **1** superclass | **Cây** (tree) | Single |\n| **Lattice** | Subclass có thể có **≥ 2** superclass | **Đồ thị có hướng** (DAG) | Multiple |\n| **Shared Subclass** | Subclass với ≥ 2 superclass | Nút chung của nhiều nhánh | Multiple |\n\n> 💡 **Hiểu đơn giản (Java analogy):**\n> ```\n> Hierarchy = Java thuần (chỉ extends 1 class):\n>   Employee → Manager → CEO\n>\n> Lattice = Java có interface (multiple inheritance):\n>   class Manager extends Employee implements Engineer, Salaried\n> ```\n\n### 4.10. Slides 35-36 — Ví dụ UNIVERSITY Lattice\n\n**Slide 35 — Mô tả miniworld:**\n\n> *Database keeps track of three types of persons: **employees, alumni, and students**. A person can belong to one, two, or all three of these types. Each person has a name, SSN, sex, address, and birth date.*\n>\n> *Every employee has a salary, and there are **three types of employees: faculty, staff, and student assistants**. Each employee belongs to exactly one of these types. For each alumnus, a record of the degree(s) earned at the university is kept (degree name, year granted, major department). Each student has a major department. Each faculty has a rank, whereas each staff member has a staff position.*\n>\n> *Student assistants are classified further as either **research assistants or teaching assistants**, with the percent of time recorded. Research assistants have a research project; teaching assistants have a current course.*\n>\n> *Students are further classified as either **graduate or undergraduate** (with degree program M.S./Ph.D./M.B.A. for graduate, class freshman/sophomore for undergraduate).*\n\n**Slide 36 — EER Lattice diagram:**\n\n> 📊 **Hình 4.4 — Specialization/Generalization Lattice cho UNIVERSITY (slide 36):**\n> ```\n>            (Name)(Sex)(Address)(Ssn)(Birth_date)\n>                       \\   |   /\n>                       ┌────────┐\n>                       │ PERSON │\n>                       └───┬────┘\n>                           │ ═══ (TOTAL)\n>                          〔 o 〕  (OVERLAPPING)\n>                          /│ \\\n>                         ⊃ ⊃  ⊃\n>           (Salary)            (Major_dept)\n>              │   (Degrees:Year,Degree,Major) │\n>          ┌─────────┐  ┌────────┐  ┌────────┐\n>          │EMPLOYEE │  │ALUMNUS │  │STUDENT │\n>          └────┬────┘  └────────┘  └────┬───┘\n>               │ ═══                    │ ═══\n>             〔 d 〕                  〔 d 〕\n>             /│\\                       /  \\\n>            ⊃ ⊃ ⊃                    ⊃    ⊃\n>      ┌─────┐ ┌──────┐ ┌───────────┐  ┌──────────┐ ┌───────────┐\n>      │STAFF│ │FACUL.│ │ STUDENT_  │  │GRADUATE_ │ │UNDERGRAD_ │\n>      │     │ │      │ │ ASSISTANT │  │STUDENT   │ │STUDENT    │\n>      └─────┘ └──────┘ └─────┬─────┘  └──────────┘ └───────────┘\n>     (Position)(Rank) (Percent_time)  (Degree_program)  (Class)\n>                            │ ═══\n>                          〔 d 〕\n>                         /     \\\n>                        ⊃       ⊃\n>             ┌────────────────┐  ┌────────────────┐\n>             │RESEARCH_       │  │TEACHING_       │\n>             │ASSISTANT       │  │ASSISTANT       │\n>             └────────────────┘  └────────────────┘\n>                  (Project)            (Course)\n>\n> ⚠ STUDENT_ASSISTANT là SHARED SUBCLASS của EMPLOYEE và STUDENT\n>   (kế thừa Salary từ EMPLOYEE và Major_dept từ STUDENT).\n> ```\n>\n> 📊 **Đọc lattice này thế nào:**\n> - PERSON → EMPLOYEE/ALUMNUS/STUDENT: 〔o〕 + ═══ — overlapping total (1 person có thể đồng thời là cả 3).\n> - EMPLOYEE → STAFF/FACULTY/STUDENT_ASSISTANT: 〔d〕 + ═══ — disjoint total.\n> - STUDENT → GRADUATE/UNDERGRADUATE: 〔d〕 + ═══.\n> - **STUDENT_ASSISTANT** có **2 superclass**: EMPLOYEE (kế thừa `Salary`) + STUDENT (kế thừa `Major_dept`) → **shared subclass** (multiple inheritance).\n> - STUDENT_ASSISTANT chia tiếp thành RESEARCH_ASSISTANT / TEACHING_ASSISTANT.\n\n### 4.11. Slide 37 — Top-down vs Bottom-up\n\n- **Specialization process:**\n  - *Start with entity type then define subclasses by **successive specialization**.*\n  - **Top-down** conceptual refinement process.\n- **Bottom-up** conceptual synthesis:\n  - *Involves **generalization** rather than specialization.*\n\n> 💡 **Hiểu đơn giản:** Disjoint/overlap như quy định CLB ở trường — mỗi SV chỉ vào 1 ban (disjoint) vs vừa vào ban học thuật vừa ban truyền thông (overlap). Total/partial như \"ai cũng phải tham gia ≥ 1 CLB\" vs \"tùy chọn\".\n\n> 📝 **Tóm lại §4:**\n> - 3 cách xác định subclass: **predicate-defined**, **attribute-defined**, **user-defined**.\n> - 2 ràng buộc độc lập: **disjointness** {d, o} × **completeness** {═══, ───} → **4 tổ hợp**.\n> - **Hierarchy** (cây, single inheritance) vs **Lattice** (DAG, multiple inheritance).\n> - **Shared Subclass** = subclass với ≥ 2 superclass (kế thừa từ tất cả).\n> - **Generalization thường total** vì superclass được suy từ subclass.\n>\n> **Một câu ghi nhớ:** *`d/o` trả lời \"được vào bao nhiêu nhóm\"; `total/partial` trả lời \"có bắt buộc vào nhóm không\".*\n\n> ❓ **Tự kiểm tra §4:**\n> 11. Phân biệt 〔d〕 và 〔o〕. Cho ví dụ thực tế cho mỗi loại.\n> 12. Đường đôi vs đơn ý nghĩa khác nhau thế nào?\n> 13. Khi nào dùng predicate-defined? user-defined?\n> 14. STUDENT_ASSISTANT slide 36 là gì — hierarchy hay lattice? Vì sao?\n> 15. *\"Generalization thường total\"* — đúng hay sai? Giải thích.\n\n---\n\n","file":"materials/DB-Chapter3.md","section":5},{"id":"c3-06","group":"c3","kind":"source","title":"5. Categories (Union Types)","markdown":"## 5. Categories (Union Types)\n\n### 5.1. Tại sao có Category?\n\nĐến giờ:\n- **1 superclass** → nhiều subclass (đơn cha).\n- **Nhiều superclass** → 1 shared subclass — nhưng entity của shared subclass phải tồn tại trong **TẤT CẢ** superclass (giao — `AND`).\n\nCó bài toán đời thật mà subclass là **HỢP** (`OR`) các superclass:\n- *Owner xe* = **Person** HOẶC **Bank** HOẶC **Company** — mỗi instance chỉ thuộc **MỘT** superclass.\n\n→ Cần **Category (Union type)**.\n\n### 5.2. Slide 39 — Định nghĩa Category\n\n**Nội dung slide gốc:**\n\n- **Category** or **Union type**\n  - *Represents a single superclass/subclass relationship with **more than one superclass**.*\n  - *Subclass represents a collection of objects that is a **subset of the UNION** of distinct entity types.*\n  - *Attribute inheritance works **more selectively**.*\n  - *Category can be **total** or **partial**.*\n- *Some modeling methodologies do not have union types.*\n\n| Thuật ngữ | Định nghĩa |\n|---|---|\n| **Category / Union Type** | Subclass có nhiều superclass (kiểu OR). Member chỉ tồn tại trong **đúng 1** superclass tại 1 thời điểm. |\n| **Defining superclass** | Các class nguồn tạo nên union cho category. |\n\n### 5.3. Slide 40 — Ví dụ OWNER\n\n**Nội dung slide gốc:**\n\n- *Example: Database for vehicle registration, vehicle owner can be a **person**, a **bank** (holding a lien on a vehicle) or a **company**.*\n  - *Category (subclass) **OWNER** is a subset of the **union** of the three superclasses **COMPANY, BANK, and PERSON**.*\n  - *A category member must exist in **only one** of its superclasses.*\n- *Note: The difference from **shared subclass**, which is a subset of the **intersection** of its superclasses (shared subclass member must exist **in all** of its superclasses).*\n\n→ **Slide phân biệt đỉnh cao** giữa Category và Shared Subclass:\n\n| Khía cạnh | Category | Shared Subclass |\n|---|---|---|\n| Tập hợp | **Union (OR)** của các superclass | **Intersection (AND)** của các superclass |\n| Member tồn tại ở | **ĐÚNG 1** superclass | **TẤT CẢ** superclass |\n\n### 5.4. Slide 41 — EER Diagram cho 2 Categories\n\n> 📊 **Hình 5.1 — 2 Categories: OWNER và REGISTERED_VEHICLE (slide 41):**\n> ```\n> (BName)(BAddress)            (CName)(CAddress)\n>     \\   /         (SSN)(Name)(Address)   \\   /\n>    ┌─────┐         \\    │    /        ┌────────┐\n>    │BANK │       ┌──────┐ ↓            │COMPANY │\n>    └──┬──┘       │PERSON│              └──┬───┘\n>       │          └──┬───┘                 │\n>       │   (DriverLicenseNo)               │\n>        \\         │                       /\n>          \\       │                     /\n>            \\   〔 U 〕               /\n>             \\  /  │  \\              /\n>              ⊃   ⊃   ⊃    ← IS-A from Union\n>             ┌────────┐\n>             │ OWNER  │       ← Category 1\n>             └───┬────┘\n>                 │ M\n>              ┌──────┐ (LienOrRegular, PurchaseDate)\n>              │ OWNS │\n>              └──┬───┘\n>                 │ N\n>          ┌──────────────────┐\n>          │REGISTERED_VEHICLE│  ← Category 2 (LicensePlateNo)\n>          └────────┬─────────┘\n>                   │\n>                 〔 U 〕\n>                  /  \\\n>            (CYear) (TYear)\n>              ⊃     ⊃\n>           ┌─────┐ ┌──────┐\n>           │ CAR │ │TRUCK │\n>           └─────┘ └──────┘\n>          /|  \\    /|   \\\n>     CMake CModel CStyle TMake TModel Tonnage\n>             VehicleId  VehicleId\n> ```\n>\n> 📊 **Đọc diagram này thế nào:**\n> - **OWNER** = union của 3 superclass `BANK`, `PERSON`, `COMPANY`.\n> - **REGISTERED_VEHICLE** = union của `CAR` và `TRUCK`.\n> - 〔 U 〕 = ký hiệu Union notation.\n> - Đường đôi từ category lên 〔 U 〕 = total category; đường đơn = partial.\n> - `OWNS` là M:N relationship giữa 2 category.\n\n### 5.5. Slide 42 — Total / Partial Category\n\n- *A category can be **total** or **partial**:*\n  - **Total**: *Hold the union of **all** entities in its superclasses. Represented by a **double line** connecting the category and the circle.*\n  - **Partial**: *Can hold a **subset** of the union. Represented by a **single line**.*\n- *The superclasses of a category may have **different key attributes** or the **same key attribute**.*\n  - Different keys: OWNER (PERSON.Ssn, BANK.BName, COMPANY.CName).\n  - Same key: REGISTERED_VEHICLE (CAR.VehicleId, TRUCK.VehicleId).\n\n### 5.6. Slides 43-46 — Category vs Shared Subclass (so sánh chi tiết)\n\n| Tiêu chí | Category | Shared Subclass |\n|---|---|---|\n| **Bản chất relationship** | Subclass trong **MỘT** relationship duy nhất | Subclass trong **NHIỀU** relationship phân biệt |\n| **Số superclass / relationship** | 1 relationship có nhiều superclass | Mỗi relationship 1 superclass |\n| **Logic membership** | **OR** | **AND** |\n| **Điều kiện tồn tại** | Member ở **CHỈ 1** superclass | Member ở **TẤT CẢ** superclass |\n| **Tập hợp** | Subset của **UNION** | Subset của **INTERSECTION** |\n| **Kế thừa** | Kế thừa **chỉ 1** superclass mà entity đang là | Kế thừa **TẤT CẢ** superclass |\n| **Ví dụ** | OWNER = COMPANY ∪ BANK ∪ PERSON | ENGINEERING_MANAGER = ENGINEER ∩ MANAGER ∩ SALARIED |\n\n```\nCategory OWNER:                  Shared Subclass STUDENT_ASSISTANT:\n\n  [BANK] [PERSON] [COMPANY]         [EMPLOYEE]      [STUDENT]\n       \\    |    /                      \\              /\n       〔 U 〕                            \\            /\n          │                          [STUDENT_ASSISTANT]\n       [OWNER]\n  OWNER = OR (BANK or PERSON or COMPANY)   STUDENT_ASSISTANT = AND (Employee and Student)\n```\n\n### 5.7. Slides 47-48 — Specialization vs Union Type\n\n> 📊 **2 cách mô hình hóa cùng kịch bản (slide 47):**\n> ```\n> Cách 1 — Specialization từ VEHICLE:\n>           (Vehicle_id)(Price)(License_plate_no)\n>                          │\n>                     ┌─────────┐\n>                     │ VEHICLE │\n>                     └────┬────┘\n>                          │ ═══\n>                        〔 d 〕\n>                       /     \\\n>                  ┌─────┐  ┌──────┐\n>                  │ CAR │  │TRUCK │\n>                  └─────┘  └──────┘\n>\n> Cách 2 — Category REGISTERED_VEHICLE từ CAR ∪ TRUCK:\n>        ┌──────┐     ┌──────┐\n>        │ CAR  │     │TRUCK │\n>        └──┬───┘     └──┬───┘\n>            \\          /\n>             〔 U 〕\n>               │\n>      ┌──────────────────┐\n>      │REGISTERED_VEHICLE│  (LicensePlateNo)\n>      └──────────────────┘\n> ```\n\n**Slide 48 — Phân biệt:**\n\n| Category REGISTERED_VEHICLE | Superclass VEHICLE |\n|---|---|\n| Có thể chỉ chứa **một số** car/truck (xe chưa đăng ký không có). | **Mọi** car/truck đều là VEHICLE. |\n| Implies **chỉ** car/truck là member, không loại khác. | Specialization có thể partial → VEHICLE còn chứa **motorcycle** và loại khác. |\n\n> 💡 **Hiểu đơn giản:**\n> - **Generalization (CAR/TRUCK → VEHICLE)** = \"tôi đặt cha cho 2 đứa con — và có thể có thêm con khác\".\n> - **Category (CAR ∪ TRUCK → REGISTERED_VEHICLE)** = \"tôi tạo subclass nhận dữ liệu từ 2 nguồn — chỉ 2 nguồn này\".\n\n> 💡 **Hiểu đơn giản (analogy \"danh sách ký nhận\"):** Category giống danh sách \"người được phép ký nhận bưu phẩm\" — chủ nhà / người thân / lễ tân. Mỗi người trong danh sách chỉ thuộc **1 vai trò**. Shared subclass giống \"sinh viên thực tập\" — phải đồng thời là sinh viên + nhân viên thực tập.\n\n> 📝 **Tóm lại §5:**\n> - **Category = Union type** = subclass với **NHIỀU superclass** (OR).\n> - Member chỉ thuộc **MỘT** superclass tại một thời điểm.\n> - Khác **Shared Subclass**: Shared = AND, Category = OR.\n> - Total (═══) hoặc Partial (───).\n> - Superclass có thể có **key khác nhau**.\n>\n> **Một câu ghi nhớ:** *Category là \"OR đa cha\"; Shared Subclass là \"AND đa cha\".*\n\n> ❓ **Tự kiểm tra §5:**\n> 16. Phân biệt Category và Shared Subclass bằng 2 ví dụ thực tế.\n> 17. Member của OWNER có thể đồng thời là PERSON và COMPANY không?\n> 18. ENGINEERING_MANAGER (shared) có bắt buộc là ENGINEER + MANAGER + SALARIED?\n> 19. So sánh slide 47 trên (CAR/TRUCK → VEHICLE) và 47 dưới (→ REGISTERED_VEHICLE). Khi nào dùng cách nào?\n\n---\n\n","file":"materials/DB-Chapter3.md","section":6},{"id":"c3-07","group":"c3","kind":"source","title":"6. Design Choices and Formal Definitions","markdown":"## 6. Design Choices and Formal Definitions\n\n### 6.1. Slides 50-52 — Design Choices\n\n**Slide 50:**\n\n- *Many specializations and subclasses can be defined to make the conceptual model accurate.*\n- *If subclass has **few specific attributes** and **no specific relationships** → can be **merged** into the superclass.*\n\n**Slide 51:**\n\n- *If **all the subclasses** of a specialization have few specific attributes and no specific relationships → can be merged.*\n- *Replace with **one or more type attributes** that specify the subclass(es) that each entity belongs to.*\n\n**Slide 52:**\n\n- *Union types and categories should generally **be avoided**.*\n- *Choice of disjoint/overlapping and total/partial constraints → driven by **rules in miniworld** being modeled.*\n\n**Checklist quyết định subclass hay type attribute:**\n\n| Câu hỏi | Có → | Gợi ý |\n|---|---|---|\n| Subclass có local attribute quan trọng? | Có | Tạo subclass. |\n| Subclass có local relationship? | Có | Tạo subclass. |\n| Subclass chỉ là nhãn phân loại đơn giản? | Có | Dùng type attribute. |\n| Các subclass overlap? | Có | Type attribute đơn trị không đủ; cần EER specialization overlap. |\n| Cần OR từ nhiều superclass? | Có | Cân nhắc category nhưng slide khuyên tránh nếu có cách đơn giản hơn. |\n| Luật miniworld quy định rõ d/o và total/partial? | Có | Ghi rõ trong EER. |\n\n→ Tức là thay vì:\n```\nEMPLOYEE → {SECRETARY, TECHNICIAN, ENGINEER}  (mỗi cái không có gì đặc biệt)\n```\ngộp thành:\n```\nEMPLOYEE(Ssn, Name, Job_type ∈ {'Secretary', 'Technician', 'Engineer'})\n```\n\n> 💡 **Hiểu đơn giản (analogy \"tủ đồ\"):** Design choice giống quyết định có cần ngăn riêng trong tủ không. Hai cái khăn — không cần ngăn \"khăn thể thao\" riêng. Nhưng nếu khăn thể thao có cách giặt riêng + nơi để riêng + cần quản lý riêng → tách ngăn.\n\n### 6.2. Slides 53-57 — Formal Definitions\n\n**Slide 53 — Class C:**\n\n- *Set or collection of entities.*\n- *Includes any of the EER schema constructs of group entities.*\n- *Can be entity type, subclass, superclass, or category.*\n\n**Slide 54 — Subclass S:**\n\n- *Inherits all the attributes and relationship of a class C.*\n- *Set of entities must always be a subset of the set of entities of the other class C: **S ⊆ C***.\n- *C is called the **superclass of S**.*\n\n**Slide 55 — Specialization Z:**\n\n> *Z = {S₁, S₂, …, Sₙ}* is a set of subclasses with same superclass G.\n> - *G/Sᵢ is a superclass/subclass relationship, i = 1..n.*\n> - *G is called a **generalization** of {S₁, S₂, …, Sₙ}.*\n> - **Z is total if**: *S₁ ∪ S₂ ∪ … ∪ Sₙ = G.* Otherwise, **partial**.\n> - **Z is disjoint if**: *Sᵢ ∩ Sⱼ = ∅ for i ≠ j.* Otherwise, **overlapping**.\n\n**Slide 56 — Predicate-defined:**\n\n- *Subclass S of C is **predicate defined** if predicate (condition) p on attributes of C is used to specify membership in S; that is, **S = C[p]**, where C[p] is the set of entities in C that satisfy condition p.*\n- *A subclass not defined by a predicate is called **user-defined**.*\n\nVí dụ:\n```\nENGINEER = EMPLOYEE[Job_type = 'Engineer']\n```\n\n**Slide 57 — Category T:**\n\n> *Class T that is a subset of the union of n defining superclasses D₁, D₂, …, Dₙ, n > 1*:\n>\n> **T ⊆ (D₁ ∪ D₂ ∪ … ∪ Dₙ)**\n>\n> *Can have a predicate pᵢ on the attributes of Dᵢ to specify entities of Dᵢ that are members of T.*\n>\n> *If a predicate is specified on every Dᵢ:* **T = (D₁[p₁] ∪ D₂[p₂] ∪ … ∪ Dₙ[pₙ])**.\n>\n> **Relationship type**: *Any class can participate in a relationship.*\n\nVí dụ:\n```\nOWNER ⊆ (PERSON ∪ BANK ∪ COMPANY)\n```\n\n> 📝 **Tóm lại §6:**\n> - **Design choice**: subclass ít content → gộp vào superclass với type attribute.\n> - **Tránh dùng Category** khi có thể.\n> - Constraint d/o và total/partial **dựa theo nghiệp vụ thật**.\n> - **Formal definitions** dùng set theory: `S ⊆ C`; `Z` total ⇔ `⋃Sᵢ = G`, disjoint ⇔ `Sᵢ∩Sⱼ = ∅`; `T ⊆ ⋃Dᵢ`.\n>\n> **Một câu ghi nhớ:** *Càng đơn giản càng tốt — dùng EER feature khi bài toán thật sự cần. Constraint phải bắt nguồn từ nghiệp vụ.*\n\n> ❓ **Tự kiểm tra §6:**\n> 20. Khi nào nên gộp subclass vào superclass?\n> 21. Phát biểu *\"Z = {S₁, …, Sₙ} disjoint ⇔ Sᵢ ∩ Sⱼ = ∅ ∀ i ≠ j\"* — giải thích bằng tiếng Việt.\n> 22. Viết công thức set theory cho category OWNER với 3 superclass PERSON, BANK, COMPANY.\n\n---\n\n","file":"materials/DB-Chapter3.md","section":7},{"id":"c3-08","group":"c3","kind":"source","title":"7. Bảng Tổng Hợp Thuật Ngữ Chương 3","markdown":"## 7. Bảng Tổng Hợp Thuật Ngữ Chương 3\n\n| STT | Thuật ngữ (EN) | Tiếng Việt | Định nghĩa ngắn | Slide | Ví dụ trên COMPANY/UNIVERSITY |\n|---:|---|---|---|---:|---|\n| 1 | Enhanced ER (EER) model | Mô hình ER mở rộng | ER + subclass/superclass + spec/gen + category + inheritance | 4 | EMPLOYEE specialize thành ENGINEER, MANAGER |\n| 2 | EER diagram | Sơ đồ EER | Diagram biểu diễn EER | 4 | Slide 8 |\n| 3 | Subclass / Subtype | Lớp con | Subset có ý nghĩa của entity type | 6, 54 | ENGINEER ⊂ EMPLOYEE |\n| 4 | Superclass / Supertype | Lớp cha | Entity type chứa subclass | 6 | EMPLOYEE chứa ENGINEER |\n| 5 | IS-A relationship | Quan hệ \"là một\" | Class/subclass relationship | 6 | SECRETARY IS-A EMPLOYEE |\n| 6 | Inheritance | Kế thừa | Subclass nhận attribute/relationship của superclass | 10 | ENGINEER có Ssn, Salary từ EMPLOYEE |\n| 7 | Local attribute | Thuộc tính riêng | Attribute chỉ thuộc subclass | 12 | Eng_type của ENGINEER |\n| 8 | Local relationship | Relationship riêng | Relationship chỉ thuộc subclass | 12 | MANAGER—MANAGES—PROJECT |\n| 9 | Specialization | Đặc biệt hóa | Top-down: chia superclass thành subclass | 12 | EMPLOYEE → {SEC, TECH, ENG} |\n| 10 | Generalization | Tổng quát hóa | Bottom-up: gộp entity giống nhau thành superclass | 15 | CAR + TRUCK → VEHICLE |\n| 11 | Distinguishing characteristic | Đặc điểm phân biệt | Tiêu chí chia subclass | 12 | Job_type |\n| 12 | Defining attribute | Thuộc tính định danh | Attribute trên superclass dùng để xác định subclass | 23 | Job_type |\n| 13 | Predicate-defined subclass | Subclass theo điều kiện | Membership = condition trên attribute | 22, 56 | EMPLOYEE[Salary > 50000] = SENIOR |\n| 14 | Attribute-defined specialization | Spec theo thuộc tính | Tất cả subclass dùng condition trên cùng 1 attribute | 23 | {SEC, TECH, ENG} chia bởi Job_type |\n| 15 | User-defined subclass | Subclass do user | Membership do user gán thủ công | 25 | TRADE_UNION_MEMBER |\n| 16 | Disjointness Constraint | Ràng buộc rời nhau | 〔d〕 — entity tối đa 1 subclass | 26, 27 | EMPLOYEE chia Job_type |\n| 17 | Overlapping (notation o) | Chồng lấp | 〔o〕 — entity có thể nhiều subclass | 27 | PART → MANUFACTURED + PURCHASED |\n| 18 | Completeness / Totalness | Ràng buộc đầy đủ | Total ═══ vs Partial ─── | 26, 28 | Đường đôi vs đơn |\n| 19 | Total Specialization | Đặc biệt hóa toàn phần | Mọi entity superclass thuộc ≥ 1 subclass | 28 | PART = MFG ∪ PCH |\n| 20 | Partial Specialization | Đặc biệt hóa từng phần | Có entity không thuộc subclass nào | 28, 29 | EMP không là SEC/TECH/ENG |\n| 21 | Specialization Hierarchy | Phân cấp | Mỗi subclass có 1 superclass → cây | 33 | Single inheritance |\n| 22 | Specialization Lattice | Mạng | Subclass có ≥ 2 superclass → DAG | 33 | UNIVERSITY lattice slide 36 |\n| 23 | Single Inheritance | Đơn kế thừa | 1 superclass | 33 | Java extends |\n| 24 | Multiple Inheritance | Đa kế thừa | ≥ 2 superclass | 33, 34 | STUDENT_ASSISTANT |\n| 25 | Shared Subclass | Lớp con chia sẻ | Subclass với ≥ 2 superclass (intersection — AND) | 34, 43-46 | STUDENT_ASSISTANT |\n| 26 | Top-down (specialization) | Top-down | Bắt đầu từ superclass, chia subclass | 37 | EMPLOYEE → 3 subclass |\n| 27 | Bottom-up (generalization) | Bottom-up | Bắt đầu từ subclass, gộp superclass | 37 | CAR + TRUCK → VEHICLE |\n| 28 | Category / Union Type | Phạm trù / Kiểu hợp | Subclass với nhiều superclass theo OR | 39, 57 | OWNER ⊆ PERSON ∪ BANK ∪ COMPANY |\n| 29 | Total Category | Phạm trù toàn phần | T = D₁ ∪ … ∪ Dₙ (đường đôi) | 42 | — |\n| 30 | Partial Category | Phạm trù từng phần | T ⊆ D₁ ∪ … ∪ Dₙ (đường đơn) | 42 | REGISTERED_VEHICLE |\n| 31 | Class | Lớp | Tổng quát: entity type / subclass / superclass / category | 53 | Mọi rectangle |\n| 32 | Type Attribute | Thuộc tính loại | Attribute thay subclass khi gộp lại | 51 | Pay_method thay 2 subclass |\n\n---\n\n","file":"materials/DB-Chapter3.md","section":8},{"id":"c3-09","group":"c3","kind":"source","title":"8. Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## 8. Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\n1. **Phân biệt Subclass vs Superclass; IS-A; cardinality 1:1**.\n2. **5 quy tắc R1-R5 về subclass member** (slide 9) — đặc biệt R2 *(must be in superclass)* và R5 *(1:1)*.\n3. **Specialization vs Generalization** — top-down vs bottom-up, kết quả vẽ giống.\n4. **3 cách xác định subclass**: predicate-defined / attribute-defined / user-defined.\n5. **4 tổ hợp constraint**: {d, o} × {total, partial}. **Hay ra trắc nghiệm**.\n6. **Ký hiệu EER**: 〔d〕, 〔o〕, ═══, ───, 〔U〕, ⊃.\n7. **Hierarchy vs Lattice** — single vs multiple inheritance.\n8. **Shared Subclass** = ≥ 2 superclass (intersection — AND).\n9. **Category (Union Type)** = ≥ 2 superclass (union — OR).\n10. **Phân biệt Category vs Shared Subclass** — đỉnh điểm hay nhầm:\n    - Category: `T ⊆ (D₁ ∪ … ∪ Dₙ)`, member ở **CHỈ 1** superclass.\n    - Shared: `S ⊆ (D₁ ∩ … ∩ Dₙ)`, member ở **TẤT CẢ** superclass.\n11. **Vẽ EER cho miniworld** (Exercises 1-3) — bài tập practical.\n12. **Design choice**: gộp subclass thành type attribute (slide 50-51).\n13. **Generalization thường total** (slide 31).\n14. **Formal definitions**: `S ⊆ C`, `S₁∪…∪Sₙ = G`, `Sᵢ∩Sⱼ = ∅`, `T ⊆ D₁∪…∪Dₙ`.\n\n---\n\n","file":"materials/DB-Chapter3.md","section":9},{"id":"c3-10","group":"c3","kind":"source","title":"9. Bảng Tra Nhanh (Quick Reference)","markdown":"## 9. Bảng Tra Nhanh (Quick Reference)\n\n| Khái niệm | Ký hiệu | 1-dòng định nghĩa | Slide |\n|---|---|---|---:|\n| Subclass | ⊃ (IS-A) | Subset có ý nghĩa của entity type | 6 |\n| Superclass | (rectangle) | Entity type chứa subclass | 6 |\n| Specialization | top-down | Chia superclass thành subclass | 12 |\n| Generalization | bottom-up | Gộp entity giống nhau thành superclass | 15 |\n| Disjoint | 〔d〕 | Tối đa 1 subclass | 27 |\n| Overlapping | 〔o〕 | Nhiều subclass cùng lúc | 27 |\n| Total | ═══ | Mọi entity superclass thuộc ≥ 1 subclass | 28 |\n| Partial | ─── | Có entity không thuộc subclass nào | 28 |\n| Predicate-defined | condition next to line | Membership = predicate trên attribute | 22 |\n| Attribute-defined | defining attribute name | All subclass dùng cùng attribute | 23 |\n| User-defined | (no condition) | User gán thủ công | 25 |\n| Hierarchy | Tree | Mỗi subclass có 1 superclass | 33 |\n| Lattice | DAG | Subclass có thể ≥ 2 superclass | 33 |\n| Shared Subclass | (multi-line lên) | AND — subset của intersection | 34 |\n| Category | 〔U〕 | OR — subset của union | 39 |\n| Type attribute | (column on superclass) | Thay subclass khi nội dung nghèo | 51 |\n\n---\n\n","file":"materials/DB-Chapter3.md","section":10},{"id":"c3-11","group":"c3","kind":"source","title":"10. Sai lầm thường gặp (Common Mistakes)","markdown":"## 10. Sai lầm thường gặp (Common Mistakes)\n\n| # | Sai lầm | Tại sao sai | Cách đúng |\n|---|---|---|---|\n| 1 | Vẽ EER nhưng không phân biệt 〔d〕 vs 〔o〕 | Slide 27 yêu cầu rõ. Thiếu = ambiguous, không qua audit. | Luôn ghi `d` hoặc `o` trong vòng tròn. |\n| 2 | Đường đơn vs đường đôi vẽ giống nhau | Slide 28 dùng đường đôi cho total, đơn cho partial. Vẽ giống = mất thông tin. | Vẽ rõ ═══ cho total, ─── cho partial. |\n| 3 | Nhầm Shared Subclass với Category | Shared = AND (intersection); Category = OR (union). | Hỏi: \"member có ở TẤT CẢ superclass không?\" Có→Shared. Chỉ 1→Category. |\n| 4 | Vẽ entity ở nhiều subclass cho disjoint | Disjoint cấm điều này. | Disjoint = tối đa 1 subclass; muốn nhiều → dùng overlap. |\n| 5 | Tạo subclass khi không có local attribute/relationship | Slide 50 nói nên gộp vào superclass với type attribute. | Hỏi: \"subclass này có gì RIÊNG không?\" Không → bỏ subclass, dùng type attribute. |\n| 6 | Cho rằng generalization có thể partial | Slide 31: \"Generalization is **usually total** because superclass is derived from subclasses.\" | Generalization mặc định total. Specialization có thể partial. |\n| 7 | Dùng category bừa bãi | Slide 52: \"Union types and categories should generally **be avoided**.\" | Chỉ dùng category khi không có cách khác (vd. superclass có key khác nhau). |\n| 8 | Quên rằng subclass kế thừa cả relationship | Slide 10: kế thừa **attribute VÀ relationship**. | ENGINEER tự động `WORKS_FOR` Department vì kế thừa từ EMPLOYEE. |\n| 9 | Vẽ key attribute ở subclass | Subclass dùng chung key của superclass (vì 1:1, cùng entity). | Key chỉ vẽ ở superclass; subclass không vẽ lại. |\n| 10 | Lẫn defining attribute với key attribute | Defining attribute (Job_type) dùng để **chia** subclass; key attribute (Ssn) dùng để **định danh**. | Defining attribute không cần là key. |\n\n---\n\n","file":"materials/DB-Chapter3.md","section":11},{"id":"c3-12","group":"c3","kind":"source","title":"11. Câu Hỏi Ôn Tập (Exercises từ slide gốc)","markdown":"## 11. Câu Hỏi Ôn Tập (Exercises từ slide gốc)\n\n### Exercise 1 (slide 60) — Non-profit Organization\n\n**Đề bài:**\n> *A non-profit organization depends on a number of different types of persons. The organization is interested in: SSN, Name, Address, City, State, Telephone for **all of these persons**. Three types: **employees, volunteers and donors**.*\n>\n> *Employees have only `Date_Hired`; volunteers have only `Skill`. Donors have a relationship `Donates` with an Item. A donor must have donated **one or more Items**, an Item can only be donated by **one donor**. Item attributes: identity, description.*\n>\n> *There are persons **other than** employees/volunteers/donors → person **does not have to belong** to one of these groups. A person may also belong to **one or more** of these groups.*\n\n**Phân tích:**\n- \"Person does not have to belong\" → **Partial**.\n- \"May also belong to one or more\" → **Overlapping**.\n- → 〔o〕 + ─── (đường đơn).\n- DONOR — `Donates` (1:N) — ITEM (item chỉ thuộc 1 donor).\n- DONOR phải donate ≥ 1 item → total participation phía DONOR.\n\n**Lời giải EER:**\n```\n            (Ssn) (Name) (Address) (City) (State) (Telephone)\n                       \\   |   /\n                       ┌────────┐\n                       │ PERSON │\n                       └────┬───┘\n                            │ ───  (PARTIAL)\n                          〔 o 〕  (OVERLAPPING)\n                          / | \\\n                         ⊃  ⊃  ⊃\n              ┌────────┐ ┌─────────┐ ┌───────┐\n              │EMPLOYEE│ │VOLUNTEER│ │ DONOR │\n              └───┬────┘ └────┬────┘ └───┬───┘\n              (Date_Hired)  (Skill)     │ N (total)\n                                        ◇ Donates\n                                        │ 1\n                                     ┌──────┐\n                                     │ ITEM │\n                                     └──────┘\n                                  (Item_id) (Description)\n```\n\n### Exercise 2 (slide 61) — WV Bank Accounts\n\n**Đề bài:**\n> *WV Bank has **three different types** of bank accounts. Each customer may have any number of accounts. **All accounts have a unique account number**.*\n>\n> *Savings: balance, interest_rate, date_opened. Checking (no interest): balance, date_opened. Loans: date_taken, balance_due, interest_rate. Loan accounts assigned to a Loan Officer.*\n\n**Phân tích:**\n- 3 loại account, mỗi account thuộc đúng 1 loại → **disjoint**.\n- 3 loại tổng quát → **total**.\n- → 〔d〕 + ═══.\n- ACCOUNT — N:1 — CUSTOMER (customer có nhiều account, account chỉ 1 customer).\n- LOAN — N:1 — LOAN_OFFICER.\n\n**Lời giải EER:**\n```\n   ┌──────────┐                ┌──────────┐\n   │ CUSTOMER │ 1───── HAS ────N│ ACCOUNT │\n   └──────────┘                 └────┬────┘\n                              (Account_no key)\n                                     │ ═══ (TOTAL)\n                                  〔 d 〕 (DISJOINT)\n                                   /  |  \\\n                                  ⊃   ⊃   ⊃\n                  ┌──────────┐ ┌──────────┐ ┌──────────┐\n                  │ SAVINGS  │ │CHECKING  │ │   LOAN   │\n                  │ ACCOUNT  │ │ ACCOUNT  │ │ ACCOUNT  │\n                  └────┬─────┘ └────┬─────┘ └────┬─────┘\n              (Balance)     (Balance)     (Loan_date)\n              (Interest_rate)(Date_opened) (Balance_due)\n              (Date_opened)              (Interest_rate)\n                                              │ N\n                                              ◇ Assigned_to\n                                              │ 1\n                                       ┌──────────────┐\n                                       │ LOAN_OFFICER │\n                                       └──────────────┘\n```\n\n### Exercise 3 (slide 62) — Ngân hàng Việt (đề tiếng Việt)\n\n**Đề bài:**\n> *Một ngân hàng có các chi nhánh (mã chi nhánh, tên, địa chỉ, ĐT). Nhân viên (mã NV, họ tên, địa chỉ, ĐT, email, ngày bắt đầu, **loại nhân viên**: giao dịch viên, giám sát viên, tư vấn viên, bảo vệ…). Tại 1 thời điểm, nhân viên chỉ làm việc tại 1 chi nhánh.*\n>\n> *Khách hàng có thể là **cá nhân hoặc doanh nghiệp**. Cá nhân: CMND, họ tên, email, ĐT, địa chỉ. Doanh nghiệp: mã DN, tên DN, tên người đại diện, ĐT, địa chỉ.*\n>\n> *Mỗi khách hàng có thể mở nhiều tài khoản tiết kiệm; 1 tài khoản chỉ thuộc 1 khách. Tài khoản: mã TK, ngày mở, mở tại chi nhánh nào, ngày đáo hạn, gốc, hiện tại, kỳ hạn, lãi suất, phương thức trả lãi.*\n>\n> *Giao dịch: ngày giờ, chi nhánh, **loại giao dịch** (rút/gửi/...), số tiền. Mỗi giao dịch được phụ trách bởi **1 giao dịch viên + 1 giám sát viên**.*\n\n**Phân tích:**\n- EMPLOYEE → specialize theo *loại nhân viên* — disjoint, total, attribute-defined.\n- CUSTOMER → 2 subclass {INDIVIDUAL, BUSINESS} — disjoint, total. **Key khác nhau** (CMND vs Mã DN) → có thể vẫn dùng specialization vì chỉ 2 subclass.\n\n**Lời giải EER:**\n```\n[BRANCH] (Branch_id, Name, Address, Phone)\n   │ 1\n   │ Works_at\n   │ N\n[EMPLOYEE] (Emp_id, Full_name, Address, Phone, Email, Start_date, Emp_type)\n   │ ═══\n 〔 d 〕 (disjoint, total — attribute-defined trên Emp_type)\n  / | | \\\n ⊃ ⊃ ⊃ ⊃\n[TELLER][SUPERVISOR][CONSULTANT][GUARD]\n\n[CUSTOMER] (Cust_id)\n   │ ═══\n 〔 d 〕 (disjoint, total)\n  /   \\\n[INDIVIDUAL_CUSTOMER]      [BUSINESS_CUSTOMER]\n (Citizen_id, Full_name,    (Business_id, Business_name,\n  Email, Phone, Address)     Representative, Phone, Address)\n\n[CUSTOMER] 1 ─── Owns ─── N [SAVINGS_ACCOUNT]\n                          (Acct_id, Open_date, Maturity_date,\n                           Initial_principal, Current_balance,\n                           Term, Interest_rate, Payment_method)\n                              │ N\n                              ◇ Opened_at\n                              │ 1\n                          [BRANCH]\n\n[TRANSACTION] (Trans_id, DateTime, Trans_type, Amount)\n     │ N\n     ├── Occurs_at ───── 1 [BRANCH]\n     ├── On_account ──── 1 [SAVINGS_ACCOUNT]\n     ├── Performed_by ── 1 [TELLER]       ← subclass của EMPLOYEE\n     └── Approved_by ─── 1 [SUPERVISOR]   ← subclass của EMPLOYEE\n```\n\n**Lưu ý:** TRANSACTION có **2 relationship riêng** tới 2 subclass khác nhau của EMPLOYEE — đây là minh họa cho việc relationship có thể gắn vào subclass cụ thể (slide 12 đã nói).\n\n---\n\n","file":"materials/DB-Chapter3.md","section":12},{"id":"c3-13","group":"c3","kind":"source","title":"12. Đáp án Tự kiểm tra","markdown":"## 12. Đáp án Tự kiểm tra\n\n### §1 (câu 1-3)\n\n**1.** EER chứa **toàn bộ** ER (slide 4). 4 concept mới: (a) Subclasses & superclasses, (b) Specialization & generalization, (c) Category / union type, (d) Attribute & relationship inheritance.\n\n**2.** Vì các loại nhân viên có **attribute riêng** (Eng_type, Typing_speed, …) và **relationship riêng** (MANAGER có MANAGES). Ép tất cả vào 1 entity gây nhiều NULL.\n\n**3.** Ví dụ: MANAGER là subclass của EMPLOYEE vì có relationship riêng `MANAGES` với PROJECT. Hoặc HOURLY_EMPLOYEE có `Pay_scale`.\n\n### §2 (câu 4-7)\n\n**4.** Vì subclass = subset có ý nghĩa của superclass — định nghĩa formal `S ⊆ C` (slide 54). Một entity subclass chính là entity superclass với \"vai trò khác\". Không có trong superclass thì không thể \"subset của ai\".\n\n**5.** Cardinality 1:1 (slide 9). Một bản ghi superclass tương ứng tối đa 1 bản ghi subclass cùng key. Trong COMPANY: Ssn của EMPLOYEE = Ssn của ENGINEER.\n\n**6.** `Typing_speed` đặt ở `SECRETARY` — chỉ secretary mới cần. Đặt ở EMPLOYEE → mọi engineer/manager/technician đều có cell NULL.\n\n**7.** `MANAGES` là relationship riêng của MANAGER — chỉ MANAGER mới quản lý PROJECT. Nhưng nhờ inheritance, MANAGER cũng có `WORKS_FOR` Department (kế thừa từ EMPLOYEE).\n\n### §3 (câu 8-10)\n\n**8.** Specialization = top-down (chia superclass). Generalization = bottom-up (gom entity giống nhau lên). Hướng tư duy ngược, kết quả vẽ giống.\n\n**9.** Không vô lý. Một entity type có thể được \"chẻ\" theo **nhiều tiêu chí khác nhau** đồng thời. Slide 8: EMPLOYEE chẻ theo Job_type (3 subclass), theo MANAGER hay không (1 subclass), theo Pay_method (2 subclass). Một nhân viên có thể là SALARIED ENGINEER (thuộc 2 specialization khác nhau).\n\n**10.** EER:\n```\n   (Ssn) (Name)\n       \\  /\n   ┌────────┐\n   │ PERSON │\n   └────┬───┘\n       〔o〕  (overlapping)\n       /  \\\n      ⊃    ⊃\n   ┌──────┐ ┌────────┐\n   │STUDENT│ │EMPLOYEE│\n   └───┬──┘ └────┬───┘\n  (Major_dept)  (Salary)\n```\n\n### §4 (câu 11-15)\n\n**11.** 〔d〕 = disjoint (entity tối đa 1 subclass); 〔o〕 = overlapping (có thể nhiều).\n- 〔d〕: Job_type categorization của EMPLOYEE.\n- 〔o〕: PART vừa MANUFACTURED vừa PURCHASED.\n\n**12.** Đường đôi ═══ = total (mọi entity superclass thuộc ≥ 1 subclass). Đường đơn ─── = partial (có entity không thuộc).\n\n**13.** Predicate-defined: rule rõ ràng từ attribute (vd `Salary > 50000`). User-defined: không có rule, DBA/user tự gán (vd \"thành viên CLB\" — tham gia tự nguyện).\n\n**14.** STUDENT_ASSISTANT (slide 36) là **lattice + shared subclass** vì có 2 superclass (EMPLOYEE và STUDENT). Multiple inheritance: kế thừa Salary từ EMPLOYEE + Major_dept từ STUDENT.\n\n**15.** **Đúng** (slide 31). Generalization tạo superclass *từ* subclass — superclass = ⋃ subclass → mặc nhiên total. Nếu sau này có entity mới → đưa vào subclass mới chứ không thể \"ngoài superclass\".\n\n### §5 (câu 16-19)\n\n**16.**\n- **Category (OR)**: OWNER xe = PERSON ∪ BANK ∪ COMPANY. Chủ xe là 1 trong 3.\n- **Shared Subclass (AND)**: ENGINEERING_MANAGER = ENGINEER ∩ MANAGER ∩ SALARIED. Đồng thời cả 3.\n\n**17.** **KHÔNG**. Slide 40: *\"A category member must exist in **only one** of its superclasses\"*. OWNER là PERSON HOẶC BANK HOẶC COMPANY. Một entity OWNER cụ thể (vd \"Anh Tùng\") chỉ có thể là PERSON.\n\n**18.** **CÓ — phải là cả 3**. Slide 45: *Shared subclass member must exist in **all** of its superclasses*. ENGINEERING_MANAGER ⊆ ENGINEER ∩ MANAGER ∩ SALARIED → bắt buộc đồng thời cả 3.\n\n**19.** Slide 48 phân biệt:\n- **Specialization (CAR/TRUCK ⊂ VEHICLE)**: dùng khi *mọi* car/truck đều phải là VEHICLE; có thể có thêm motorcycle.\n- **Category (REGISTERED_VEHICLE ⊆ CAR ∪ TRUCK)**: dùng khi REGISTERED_VEHICLE *chỉ chứa* car/truck đã đăng ký, không loại khác. Một số car/truck chưa đăng ký → không thuộc.\n\n### §6 (câu 20-22)\n\n**20.** Slide 50-51: gộp khi (a) subclass có ít/không có specific attribute và (b) **không có** specific relationship. Khi đó thay bằng *type attribute* trên superclass (vd `Job_type ∈ {'Secretary', 'Engineer', ...}`).\n\n**21.** \"Specialization Z disjoint ⇔ giao của 2 subclass khác nhau bất kỳ là tập rỗng\" — không có entity nào thuộc đồng thời ≥ 2 subclass trong specialization. EMPLOYEE → {SEC, ENG, TECH} disjoint ⇔ không có nhân viên nào vừa SEC vừa ENG.\n\n**22.** Theo slide 57:\n$$\\text{OWNER} \\subseteq (\\text{PERSON} \\cup \\text{BANK} \\cup \\text{COMPANY})$$\nNếu mỗi superclass có predicate riêng:\n$$\\text{OWNER} = \\text{PERSON}[p_1] \\cup \\text{BANK}[p_2] \\cup \\text{COMPANY}[p_3]$$\n\n---\n\n","file":"materials/DB-Chapter3.md","section":13},{"id":"c3-14","group":"c3","kind":"source","title":"13. Mối Quan Hệ Với Các Chương Khác — Liên kết Lab/BTL","markdown":"## 13. Mối Quan Hệ Với Các Chương Khác — Liên kết Lab/BTL\n\n### Chương trước / sau\n\n| Chương | Liên hệ với chương 3 |\n|---|---|\n| **Chương 2 — ER Model** | Nền cho EER. EER = ER + 4 concept mới. Mọi notation ER giữ nguyên. |\n| **Chương 4 — Relational Mapping** | Dạy 8 quy tắc map ER → Relational. **Step 8** chuyên xử lý EER (specialization, generalization, category) thành relational table. **Hay ra thi tự luận**. |\n| **Chương 6 — SQL** | `CREATE TABLE` với `PRIMARY KEY` + `FOREIGN KEY` để cài đặt EER. Constraint có thể implement bằng `CHECK` (predicate-defined) hoặc `TRIGGER` (user-defined). |\n| **Chương 7 — FD & Normalization** | Sau khi map EER → relational, kiểm tra chuẩn hóa. Specialization tốt thường đã đảm bảo 3NF. |\n\n### Liên kết với Lab và BTL\n\n| Hoạt động | Phần nào của chương 3 dùng tới |\n|---|---|\n| **Lab 1, Lab 2** | Sau khi vẽ EER + map sang relational, dùng SQL `CREATE TABLE`. |\n| **BTL1** (`BTL1_DB_Lab/`) | **Yêu cầu chính**: vẽ EER cho 1 hệ thống thực — sẽ dùng cả 4 EER feature. **Exercises 1-3** ở slide 60-62 là **mini-version** của BTL. |\n| **BTL2** (`BTL2_DB_Lab/`) | Cài đặt EER schema thật trên DBMS. Tương ứng với Step 8 trong chương 4. |\n\n### Concept của chương 3 sẽ \"thấy lại\" ở đâu\n\n| Concept chương 3 | Tái hiện ở |\n|---|---|\n| Specialization | Chương 4 — Step 8a/8b/8c/8d (4 cách map specialization sang relational) |\n| Category | Chương 4 — Step 8e (cách map category với surrogate key) |\n| Inheritance | OOP / ORM frameworks (Hibernate, Django ORM) |\n| Disjoint vs Overlapping | SQL `CHECK` constraint (disjoint) hoặc tách bảng (overlapping) |\n| Predicate-defined | SQL `CHECK (Job_type = 'Engineer')` |\n\n---\n\n","file":"materials/DB-Chapter3.md","section":14},{"id":"c3-15","group":"c3","kind":"source","title":"14. Phụ lục — Mapping 62 slide → Section trong tài liệu này","markdown":"## 14. Phụ lục — Mapping 62 slide → Section trong tài liệu này\n\n| Slide | Nội dung | Section |\n|---:|---|---|\n| 1 | Chapter title | Header |\n| 2, 3, 5, 11, 19, 38, 49, 58 | Outline (8 slide) | §0.4 (gộp) |\n| 4 | Introduction to EER | §1.2 |\n| 6 | Subclass/Superclass definitions | §2.2 |\n| 7 | EMPLOYEE example | §2.3 |\n| 8 | EER diagram notation (3 specialization) | §2.4 |\n| 9 | 5 quy tắc subclass member | §2.5 |\n| 10 | Inheritance | §2.6 |\n| 12 | Specialization | §3.2 |\n| 13 | Example specialization (EMPLOYEE→SEC/TECH/ENG) | §3.3 |\n| 14 | Instances of specialization | §3.4 |\n| 15 | Generalization | §3.5 |\n| 16 | Example generalization (CAR/TRUCK→VEHICLE) | §3.6 |\n| 17 | Notation distinguish (no arrow) | §3.7 |\n| 18 | Data modeling | §3.8 |\n| 20 | Constraints overview | §4.1 |\n| 21 | 3 ways determine subclass | §4.2 |\n| 22 | Predicate-defined | §4.2 |\n| 23 | Attribute-defined | §4.2 |\n| 24 | EER notation attribute-defined | §4.3 |\n| 25 | User-defined | §4.2 |\n| 26 | Disjointness + Completeness overview | §4.4 |\n| 27 | Disjointness Constraint | §4.4 |\n| 28 | Completeness Constraint | §4.4 |\n| 29 | Disjoint Partial example | §4.5 |\n| 30 | Overlapping Total example (PART) | §4.6 |\n| 31 | 4 types specialization | §4.7 |\n| 32 | Case study (Group A/B) | §4.8 |\n| 33 | Hierarchy vs Lattice | §4.9 |\n| 34 | Multiple inheritance, Shared subclass | §4.9 |\n| 35 | UNIVERSITY miniworld description | §4.10 |\n| 36 | UNIVERSITY lattice | §4.10 |\n| 37 | Top-down vs Bottom-up | §4.11 |\n| 39 | Categories / Union type definition | §5.2 |\n| 40 | OWNER example | §5.3 |\n| 41 | OWNER + REGISTERED_VEHICLE diagram | §5.4 |\n| 42 | Total/Partial Category | §5.5 |\n| 43, 44, 45, 46 | Category vs Shared Subclass | §5.6 |\n| 47 | Specialization vs Union type diagram | §5.7 |\n| 48 | Specialization vs Union type comparison | §5.7 |\n| 50, 51, 52 | Design Choices | §6.1 |\n| 53 | Class C | §6.2 |\n| 54 | Subclass S | §6.2 |\n| 55 | Specialization Z | §6.2 |\n| 56 | Predicate-defined formal | §6.2 |\n| 57 | Category T | §6.2 |\n| 59 | Q & A | (slide kết) |\n| 60 | Exercise 1 | §11 |\n| 61 | Exercise 2 | §11 |\n| 62 | Exercise 3 | §11 |\n\n---\n\n","file":"materials/DB-Chapter3.md","section":15},{"id":"c3-16","group":"c3","kind":"source","title":"15. Bảng so sánh nguồn (Prompt 3 audit table)","markdown":"## 15. Bảng so sánh nguồn (Prompt 3 audit table)\n\n| Section / Nội dung | A (Claude pass1) | B (CO2013) | Nguồn được chọn |\n|---|---|---|---|\n| 0.1-0.3 Trước khi bắt đầu | ✅ | ✅ | A+B union |\n| 0.5 Concept map Mermaid | ❌ | ✅ | **B** |\n| §1-§6 slide-by-slide structure | concept-based | ✅ slide-by-slide | **B** làm khung |\n| 5 quy tắc R1-R5 (slide 9) | bảng riêng | text-only | **A** |\n| Diagram slide 8 EER notation | ASCII đẹp 3 specialization | ASCII | **A** |\n| Diagram slide 36 UNIVERSITY lattice | chi tiết hơn (có constraint per nhánh) | có | **A** |\n| 4 tổ hợp constraint + analogy lớp học thêm | có | có | A+B union |\n| Bảng Category vs Shared Subclass | 3 chiều chi tiết | 7 hàng | **A∪B union** → 7 hàng đầy đủ |\n| 3 Exercises lời giải | hint phân tích | **lời giải đầy đủ + ASCII diagram** | **B** |\n| Glossary | 28 hàng không cột COMPANY | 28 hàng có cột | A+B union → 32 hàng có cột |\n| TH2 Bảng tra nhanh | ❌ | ❌ | **tự sinh** |\n| TH3 Sai lầm thường gặp | ❌ | ❌ | **tự sinh** (10 sai lầm) |\n| Phụ lục mapping 62 slide | ❌ | có (slide-by-slide riêng) | **B** rút gọn thành bảng |\n\n---\n\n","file":"materials/DB-Chapter3.md","section":16},{"id":"c3-17","group":"c3","kind":"source","title":"16. Checklist tổng hợp cuối cùng","markdown":"## 16. Checklist tổng hợp cuối cùng\n\n### ✅ Checklist nội dung\n\n| Hạng mục | A | B | Bản tổng hợp | Yêu cầu |\n|---|---:|---:|---:|---|\n| Số section đánh số | 6 | 6 | 6 | ≥ max | ✅ |\n| Số diagram được mô tả | 11 | 11 | 11 | ≥ max | ✅ |\n| Số ví dụ EMPLOYEE/UNIVERSITY/VEHICLE/PART | 12+ | 12+ | 14+ | ≥ max | ✅ |\n| Số analogy đời thường | 7 | 5 | 7 | ≥ max | ✅ |\n| Số đoạn code (Java OOP, set theory) | 4 | 3 | 4 | ≥ max | ✅ |\n| Số công thức set theory | 4 | 4 | 4 | ≥ max | ✅ |\n| Số thuật ngữ glossary | 28 | 28 | **32** | ≥ max | ✅ vượt |\n| Số câu hỏi tự kiểm tra | 20 | 18 | 22 | ≥ max | ✅ |\n| Mapping 62 slide → section | 0 | 62 | 62 | bắt buộc | ✅ |\n\n### ✅ Checklist riêng cho TỰ HỌC\n\n| Hạng mục | Đạt? |\n|---|---|\n| Có **0.1 Prerequisite** (bảng concept ER) | ✅ |\n| Có **0.2 Learning Outcomes** (9 outcome) | ✅ |\n| Có **0.3 Lộ trình đọc** | ✅ |\n| Có **0.5 Concept map Mermaid** | ✅ |\n| Có **Bảng tra nhanh** cuối chương (§9) | ✅ |\n| Có **Sai lầm thường gặp** (§10 — 10 sai lầm) | ✅ |\n| Có **3 Exercises có lời giải đầy đủ + EER diagram** (§11) | ✅ |\n| Có **liên kết Lab/BTL** (§13) | ✅ |\n| Mọi concept khó có analogy (Java OOP, thẻ SV, lớp học thêm, danh sách ký nhận, tủ đồ, ...) | ✅ |\n| Mọi thuật ngữ lần đầu có VN | ✅ |\n| Có **Đáp án Tự kiểm tra** (§12 — 22 đáp án) | ✅ |\n| Phụ lục mapping 62 slide → section (§14) | ✅ |\n| **Tự đánh giá: SV mất gốc đọc sẽ hiểu được?** | ✅ |\n\n---\n\n> **File này là bản TỔNG HỢP CUỐI CÙNG** cho Chương 3, ghép từ 2 nguồn:\n> 1. `_drafts/DB-Chapter3-claude-pass1.md` (bản A — Claude, sau Prompt 1)\n> 2. `_drafts/CO2013_Chuong3_EER_Model_full_notes.md` (bản B — nguồn ngoài, slide-by-slide)\n>\n> Sau finalize, có thể xóa 2 file `_drafts/` (đã merge xong).\n","file":"materials/DB-Chapter3.md","section":17},{"id":"guide-3","group":"c3","kind":"guide","title":"EER · Kế thừa và phân loại","markdown":"# 03 · EER: hiểu lớp con bằng tập hợp\n\n> Đọc cùng **DB-Chapter3.md**. Hai trục disjoint/overlapping và total/partial độc lập với nhau.\n\n![Bốn trường hợp chuyên biệt hóa](../docs/assets/specialization.svg)\n\n## Một người dùng có thể vừa xem vừa quản trị\n\nXét ACCOUNT là superclass; VIEWER và CONTENT_ADMIN là subclass. Một đối tượng VIEWER **vẫn là cùng account**, kế thừa định danh và thuộc tính chung. Subclass không phải một tài khoản thứ hai liên kết 1:1 ngẫu nhiên với tài khoản thứ nhất.\n\nNếu tài khoản Chi vừa xem anime vừa quản trị nội dung, hai subclass **overlapping**. Nếu mọi account bắt buộc phải là viewer hoặc admin (hoặc cả hai), specialization **total**. “Hoặc” trong yêu cầu này không có nghĩa là “chỉ một”.\n\n| Trường hợp | Điều kiện tập hợp | Ví dụ |\n|---|---|---|\n| Disjoint + total | `V ∩ A = ∅`, `V ∪ A = ACCOUNT` | Mỗi tài khoản đúng một vai trò |\n| Overlapping + total | `V ∪ A = ACCOUNT` | Mọi tài khoản có ít nhất một vai trò |\n| Disjoint + partial | `V ∩ A = ∅`, union có thể thiếu | Có tài khoản chưa nhận vai trò |\n| Overlapping + partial | Có thể giao, có thể thiếu | Vai trò tùy chọn, có thể kiêm nhiệm |\n\nTotal không yêu cầu từng subclass đều có phần tử. Nếu hôm nay tất cả account là viewer và admin đang rỗng, total vẫn đúng.\n\n## Generalization và specialization\n\n**Specialization** đi từ ACCOUNT xuống các vai trò có thuộc tính/quan hệ riêng. **Generalization** đi từ những loại có điểm chung lên superclass. Hai hướng là cách tiếp cận thiết kế; kết quả có thể giống nhau.\n\nKhông phải cứ có cột `role` là phải vẽ EER. Nếu chỉ cần nhãn phân loại và mọi loại có cùng thuộc tính, một attribute có thể đủ. Nếu admin có `Department`, quyền riêng và quy tắc riêng, subclass giúp diễn đạt rõ hơn.\n\n## Shared subclass khác category\n\nSHARED_SUBCLASS ⊆ CLASS_A ∩ CLASS_B: một teaching assistant phải đồng thời là student và employee; có thể kế thừa từ cả hai. CATEGORY ⊆ PERSON ∪ COMPANY: một owner là person hoặc company, không cần đồng thời là cả hai. Dấu **giao** và **hợp** là điểm phân biệt nên viết trước khi vẽ.\n\nVới category, các superclass có thể dùng khóa khác miền: `CitizenID` và `TaxID`. Khi mapping thường thêm surrogate `OwnerID`, nhưng vẫn cần ràng buộc xác định owner đang đại diện loại nào và entity gốc nào. Chỉ tạo một số ID mới không tự bảo đảm ngữ nghĩa category.\n\n## Mapping thử để thấy điều gì chưa được bảo đảm\n\n```sql\nCREATE TABLE account(account_id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE);\nCREATE TABLE viewer(account_id INTEGER PRIMARY KEY REFERENCES account(account_id));\nCREATE TABLE content_admin(\n account_id INTEGER PRIMARY KEY REFERENCES account(account_id), department TEXT NOT NULL\n);\n```\n\nPK/FK của hai bảng con bảo đảm mỗi hàng con thuộc một account. Chúng cho phép cùng ID xuất hiện ở cả hai bảng, phù hợp overlapping. Nhưng chúng cũng cho phép account không xuất hiện trong bảng con nào, nên **chưa bảo đảm total**.\n\nTrong capstone, quy tắc này được kiểm tra bằng query vi phạm và transaction trong tầng nghiệp vụ. SQLite không có deferred constraint trigger cho ràng buộc nhiều bảng này; không nên thêm trigger chạy ngay sau INSERT ACCOUNT rồi kết luận đã giải quyết, vì lúc đó các hàng subclass có thể chưa được tạo.\n\n## Bài tập có lời giải\n\n1. Hệ thống có Guest chưa được gán viewer/admin. Total hay partial?\n2. Có người vừa là student vừa employee. Có bắt buộc mọi employee là student không?\n3. Đưa shared subclass xuống hai bảng có FK có tự bảo đảm entity mang cùng định danh không?\n\n<details><summary>Lời giải</summary>\n\n1. Nếu Guest cũng là ACCOUNT mà không thuộc subclass nào trong specialization đang xét thì partial, hoặc phải bổ sung Guest vào một specialization total có đủ lớp.\n2. Không. Overlap chỉ cho phép giao khác rỗng, không tạo bao hàm giữa hai lớp.\n3. Phải thiết kế thống nhất định danh và ràng buộc. Hai FK tùy ý trỏ đến hai người khác nhau không chứng minh đó là cùng entity.\n\n</details>\n","file":"lessons/03-eer.md"},{"id":"c4-00","group":"c4","kind":"source","title":"Chương 4: Mô hình Quan hệ và Ánh xạ ER/EER → Quan hệ — *Relational Data Model and ER/EER-to-Relational Mapping*","markdown":"# Chương 4: Mô hình Quan hệ và Ánh xạ ER/EER → Quan hệ — *Relational Data Model and ER/EER-to-Relational Mapping*\n\n> **Nguồn:** CO2013 Database Systems, HCMUT — Khoa KH&KT Máy tính\n> **Giảng viên phụ trách:** TS. Trần Minh Quang\n> **Giáo trình:** Elmasri & Navathe, *Fundamentals of Database Systems*, 7th Edition (Chapters 3, 9)\n> **File PDF gốc:** `Lectures/04_Relational Data Model and Relational Mapping.pdf`\n> **Số slide trong PDF gốc:** **90 slide** (slide 1 = title, slide 90 = Q&A)\n> **Slide \"Outline\" lặp lại:** slide **2, 3, 29, 36, 53, 59, 66, 76, 89** (9 slide) — đã gộp ở §0.4.\n> **Slide có diagram chính:** 8, 12, 17-18, 21, 23, 31, 34-35, 41, 45, 47-50, 52, 55-58, 62, 67-69, 71-74, 79-80, 82-83, 85-86, 88.\n>\n> **Mục tiêu của tài liệu này:** một sinh viên đã học chương 2 (ER) và chương 3 (EER), đọc một mạch là đủ làm được mapping ER/EER → Relational cho miniworld bất kỳ, **đủ kiến thức cho BTL1** (chương 4 là **chương quan trọng nhất** cho BTL1).\n\n---\n\n","file":"materials/DB-Chapter4.md","section":0},{"id":"c4-01","group":"c4","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nĐây là chương \"kết nối\" — cần kiến thức từ 2 chương trước:\n\n| Concept đã học | Chương | Sẽ dùng để |\n|---|---|---|\n| **Entity, Attribute, Relationship** | 2 (ER) | Step 1–7 mapping |\n| **Cardinality 1:1, 1:N, M:N** | 2 (ER) | Quyết định mapping approach |\n| **Total / Partial Participation** | 2 (ER) | Quyết định FK ở bên nào |\n| **Weak Entity, Partial Key** | 2 (ER) | Step 2 mapping |\n| **Multivalued / Composite / Derived Attribute** | 2 (ER) | Step 6 mapping |\n| **N-ary Relationship** | 2 (ER) | Step 7 mapping |\n| **Subclass / Superclass / Specialization** | 3 (EER) | Step 8 mapping |\n| **Category / Union Type** | 3 (EER) | Step 9 mapping |\n| **Shared Subclass** | 3 (EER) | Mapping shared subclass |\n\n> 💡 **Hiểu đơn giản:** Chương 2 dạy bạn **vẽ ER** (mức conceptual), chương 3 mở rộng thành **EER**. Chương 4 trả lời câu hỏi: *\"Tôi đã có EER diagram đẹp. Làm sao chuyển nó sang **bảng SQL** để cài đặt thật?\"* Đây là **bước nối** giữa thiết kế ý niệm và DB chạy thật.\n\n> 💡 **Hiểu đơn giản (analogy):** ERD giống bản vẽ kiến trúc của một ngôi nhà. Relational schema giống bản vẽ kỹ thuật để thợ xây thật sự thi công. Chương này dạy cách chuyển từ \"bản vẽ ý tưởng\" sang \"bản vẽ bảng/cột/khóa\" để DBMS hiểu được.\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\nTrích từ đề cương (mục L.O.1.2 + L.O.2.2):\n\n1. **Định nghĩa** Relational Data Model: relation, schema, tuple, attribute, domain, degree, cardinality.\n2. **Phân biệt** schema (lược đồ) và instance/state (trạng thái dữ liệu).\n3. **Phân biệt** 4 loại Integrity Constraints: domain, key, entity integrity, referential integrity (+ semantic).\n4. **Hiểu** Superkey, Key, Candidate Key, Primary Key, Secondary Key, Foreign Key.\n5. **Hiểu** update operations (INSERT/DELETE/MODIFY) và 4 actions khi vi phạm (REJECT/CASCADE/SET NULL/custom).\n6. **Áp dụng 9 quy tắc mapping ER/EER → Relational** — kỹ năng cốt lõi.\n7. **Phân biệt 4 options 8A/8B/8C/8D** cho mapping specialization, biết khi nào dùng option nào.\n8. **Áp dụng surrogate key** khi mapping Union Type (category) có superclass key khác nhau.\n\n### 0.3. Lộ trình đọc đề xuất\n\n| TT | Phần | Mức độ | Thời gian | Ghi chú |\n|---:|---|---|---:|---|\n| 1 | §1.1–§1.3 Relational Data Model — Basic concepts + Constraints | **CORE** | 50–60 phút | Nền cho SQL, RA, FD. |\n| 2 | §1.4 Update Operations | **CORE** | 10–15 phút | Hiểu CASCADE/SET NULL/REJECT. |\n| 3 | §2 Main Phases | **CORE** | 10–15 phút | Định vị mapping trong workflow. |\n| 4 | §3.1–§3.8 ER mapping (Step 1–7) | **CORE** | 90–120 phút | Kỹ năng then chốt cho BTL1. |\n| 5 | §3.9 Bảng tương ứng ER ↔ Relational | **CORE** | 5 phút | Trang vàng để học thuộc. |\n| 6 | §3.10 Step 8 — 4 options 8A/8B/8C/8D | **CORE** | 40–50 phút | Hay ra thi tự luận. |\n| 7 | §3.11 Step 9 — Union Types + Surrogate | **CORE** | 20 phút | Concept khó, đặc trưng EER. |\n| 8 | §4 COMPANY full mapping result | **CORE** | 15 phút | Học thuộc PK + FK list. |\n| 9 | Exercises ôn tập | **CORE** | 60–90 phút | Y format thi cuối kỳ. |\n\n**Tổng:** ~5–6 giờ đọc lần đầu + 2 giờ làm bài tập. **Đây là chương dài thứ 2** sau SQL, và **quan trọng nhất cho BTL1**.\n\n### 0.4. Outline chương (gộp 9 slide Outline lặp)\n\nSlide 2, 3, 29, 36, 53, 59, 66, 76, 89 đều cùng outline (slide 53/59/66 còn highlight sub-step). Đã gộp:\n\n> **Outline**\n> 1. **Relational Data Model**\n> 2. **Main Phases of Database Design**\n> 3. **ER-/EER-to-Relational Mapping**\n>    - Step 1: Mapping of Regular Entity Types\n>    - Step 2: Mapping of Weak Entity Types\n>    - Step 3: Mapping of Binary 1:1 Relationship Types\n>    - Step 4: Mapping of Binary 1:N Relationship Types\n>    - Step 5: Mapping of Binary M:N Relationship Types\n>    - Step 6: Mapping of Multivalued attributes\n>    - Step 7: Mapping of N-ary Relationship Types\n>    - Step 8: Options for Mapping Specialization/Generalization (8A, 8B, 8C, 8D)\n>    - Step 9: Mapping of Union Types (Categories)\n\n---\n\n","file":"materials/DB-Chapter4.md","section":1},{"id":"c4-02","group":"c4","kind":"source","title":"1. Relational Data Model","markdown":"## 1. Relational Data Model\n\n### 1.1. Tại sao có concept này? (Motivation)\n\nChương 1 đã giới thiệu sơ Relational Model là một trong các \"data model\" (slide 35 chương 1). Chương 2-3 dạy bạn **vẽ ER/EER**, là *conceptual model*. Để **cài đặt** trên DBMS thật (Oracle, PostgreSQL, MySQL), bạn cần một mô hình *implementational* — đó là **Relational Model** mà E.F. Codd đề xuất năm 1970.\n\n> 💡 **Hiểu đơn giản:** Relational Model = **biểu diễn data dưới dạng BẢNG 2 chiều** (rows + columns). Đây là cách \"trung gian\" giữa ER (đẹp về mặt khái niệm) và file vật lý (chạy được nhưng khó hiểu). DBMS sẽ làm cầu nối từ \"bảng\" xuống file.\n\n### 1.2. Slide 4 — Section overview\n\n**Nội dung slide gốc:**\n\n- Basic Concepts: relational data model, relation schema, domain, tuple, cardinality & degree, database schema, etc.\n- Relational Integrity Constraints\n  - key, primary key & foreign key\n  - entity integrity constraint\n  - referential integrity\n- Update Operations on Relations\n\n### 1.3. Slide 5 — Lịch sử\n\n**Nội dung slide gốc:**\n\n- *The relational model of data is based on the concept of a **relation**.*\n- *A relation is a **mathematical concept** based on the ideas of **sets**.*\n- *The model was first proposed by **Dr. E.F. Codd of IBM in 1970** in: \"A Relational Model for Large Shared Data Banks,\" Communications of the ACM, June 1970.*\n\n→ **Codd's paper (1970)** là một trong những bài báo có ảnh hưởng nhất ngành CS — khiến RDBMS thắng thế Network/Hierarchical model thập niên 70-80.\n\n### 1.4. Slide 6 — Relational Data Model & Relation Schema\n\n**Nội dung slide gốc:**\n\n- **Relational data model**: *Represents a database in the form of **relations** — 2-dimensional table with rows and columns of data.*\n- **Relation schema**: *R(A₁, A₂, …, Aₙ) is made up of a relation name R and a list of **attributes** A₁, A₂, …, Aₙ. Each attribute Aᵢ is the name of a role played by some **domain D** in the relation schema R.*\n\n| Thuật ngữ (EN) | Tiếng Việt | Định nghĩa |\n|---|---|---|\n| **Relation** | Quan hệ | Bảng 2 chiều — đơn vị cơ bản. |\n| **Relation Schema** | Lược đồ quan hệ | Mô tả relation: tên + danh sách attribute. |\n| **Attribute** | Thuộc tính | Cột của bảng. |\n| **Domain D** | Miền giá trị | Tập các giá trị nguyên tử (atomic) hợp lệ + ràng buộc. |\n\n**Ví dụ COMPANY:**\n```text\nEMPLOYEE(Fname, Minit, Lname, Ssn, Bdate, Address, Sex, Salary, Super_ssn, Dno)\n```\n- `EMPLOYEE` = relation name. `Fname, …, Dno` = attributes.\n- `dom(Salary)` = số thực không âm. `dom(Sex)` = `{'M', 'F'}`.\n\n> 💡 **Hiểu đơn giản (Schema vs Instance):** Schema = bản thiết kế nhà; instance = căn nhà cụ thể hôm nay có bàn ghế, người ở.\n\n### 1.5. Slide 7 — Degree & Domain\n\n**Nội dung slide gốc:**\n\n- **Degree of a relation**: *The number of attributes n of its relation schema.*\n- **Domain D**: *D is called the domain of Aᵢ and is denoted by **dom(Aᵢ)**. It is a set of atomic values and a set of integrity constraints.*\n- *Example: STUDENT(Name, SSN, HomePhone, Address, OfficePhone, Age, GPA)*\n  - *Degree = ??*\n  - *dom(GPA) = ??*\n\n**Đáp án:**\n- `Degree(STUDENT) = 7` (7 attribute).\n- `dom(GPA) = {x ∈ ℝ | 0.0 ≤ x ≤ 4.0}` (thang Mỹ) hoặc `{x | 0 ≤ x ≤ 10}` (thang VN).\n\n### 1.6. Slide 8 — Tuple, Cardinality, Database Schema (COMPANY)\n\n**Nội dung slide gốc:**\n\n- **Tuple**: row/record in table.\n- **Cardinality**: number of tuples in a table.\n- **Database schema** S = {R₁, R₂, …, Rₘ}.\n\n**Schema diagram for COMPANY relational database (PK gạch chân):**\n\n| Relation | Attributes |\n|---|---|\n| `EMPLOYEE` | Fname, Minit, Lname, **Ssn**, Bdate, Address, Sex, Salary, Super_ssn, Dno |\n| `DEPARTMENT` | Dname, **Dnumber**, Mgr_ssn, Mgr_start_date |\n| `DEPT_LOCATIONS` | **Dnumber**, **Dlocation** |\n| `PROJECT` | Pname, **Pnumber**, Plocation, Dnum |\n| `WORKS_ON` | **Essn**, **Pno**, Hours |\n| `DEPENDENT` | **Essn**, **Dependent_name**, Sex, Bdate, Relationship |\n\n→ **Schema chuẩn của môn**, dùng làm ví dụ xuyên suốt.\n\n### 1.7. Slide 9 — Relation r (Instance)\n\n**Nội dung slide gốc:**\n\n- *A **relation r** (or **relation state, relation instance**) of the relation schema R(A₁, A₂, …, Aₙ), also denoted by r(R), is a set of **n-tuples** r = {t₁, t₂, …, tₘ}.*\n- *Each n-tuple t is an ordered list of n values t = ⟨v₁, v₂, …, vₙ⟩, where each value vᵢ, i=1..n, is an element of dom(Aᵢ) or is a special **null** value. The iᵗʰ value in tuple t is referred to as **t[Aᵢ]**.*\n\n### 1.8. Slide 10 — 6 khái niệm cơ bản (review)\n\nSlide chỉ liệt kê 6 khái niệm cốt lõi (cảnh báo \"phải nắm cả 6 trước khi đi tiếp\"):\n\n1. Relational data model\n2. Database schema\n3. Relation schema\n4. Relation\n5. Tuple\n6. Attribute\n\n### 1.9. Slide 11 — Tính chất của Relation as Table\n\n**Nội dung slide gốc:**\n\n- *A relation can be conveniently represented by a table.*\n- *The columns of the tabular relation represent **attributes**.*\n- *Each attribute has a **distinct name**, and is always **referenced by that name, never by its position**.*\n- *Each row of the table represents a **tuple**.*\n- *The **ordering of the tuples is immaterial** and **all tuples must be distinct**.*\n\n→ 4 tính chất quan trọng:\n1. **Cột** = attribute, có tên duy nhất, **không xét theo vị trí**.\n2. **Hàng** = tuple.\n3. **Thứ tự hàng không quan trọng** (set property).\n4. **Mọi tuple phải khác nhau** (set property).\n\n### 1.10. Slide 12 — Ví dụ STUDENT\n\n> 📊 **Hình 1.1 — Bảng STUDENT (slide 12):**\n> ```\n> STUDENT\n> ┌────────────────┬─────────────┬───────────────┬─────────────────────┬───────────────┬─────┬──────┐\n> │ Name           │ Ssn         │ Home_phone    │ Address             │ Office_phone  │ Age │ Gpa  │\n> ├────────────────┼─────────────┼───────────────┼─────────────────────┼───────────────┼─────┼──────┤\n> │ Benjamin Bayer │ 305-61-2435 │ (817)373-1616 │ 2918 Bluebonnet Lane│ NULL          │ 19  │ 3.21 │\n> │ Chung-cha Kim  │ 381-62-1245 │ (817)375-4409 │ 125 Kirby Road      │ NULL          │ 18  │ 2.89 │\n> │ Dick Davidson  │ 422-11-2320 │ NULL          │ 3452 Elgin Road     │ (817)749-1253 │ 25  │ 3.53 │\n> │ Rohan Panchal  │ 489-22-1100 │ (817)376-9821 │ 265 Lark Lane       │ (817)749-6492 │ 28  │ 3.93 │\n> │ Barbara Benson │ 533-69-1238 │ (817)839-8461 │ 7384 Fontana Lane   │ NULL          │ 19  │ 3.25 │\n> └────────────────┴─────────────┴───────────────┴─────────────────────┴───────────────┴─────┴──────┘\n> Cardinality = 5, Degree = 7. Có NULL ở Home_phone và Office_phone.\n> ```\n\n### 1.11. Slide 13 — Formal vs Informal Terminology\n\n| Formal Terms | Informal Terms |\n|---|---|\n| Relation | **Table** |\n| Attribute | **Column Header** |\n| Domain | **All possible Column Values** |\n| Tuple | **Row** |\n| Schema of a Relation | **Table Definition** |\n| State of the Relation | **Populated Table** |\n\n→ Khi học SQL (chương 6), thường dùng \"table/row/column\" — informal. Khi viết tự luận / chứng minh, dùng \"relation/tuple/attribute\" — formal.\n\n### 1.12. Slide 14-15 — Integrity Constraints + NULL\n\n**Slide 14 — 4 loại constraint chính:**\n\n> *Constraints are **conditions** that must hold on **all valid relation instances**.*\n>\n> Main types:\n> - **Domain constraints**\n> - **Key constraints**\n> - **Entity integrity constraints**\n> - **Referential integrity constraints**\n\n**Slide 15 — NULL value:**\n\n- *Represents value for an attribute that is currently **unknown** or **inapplicable** for tuple.*\n- *Deals with **incomplete** or **exceptional** data.*\n- *Represents the **absence of a value** and is **not the same as zero or spaces**, which are values.*\n\n> 💡 **Hiểu đơn giản:** NULL ≠ 0, ≠ '', ≠ false. NULL là \"không có giá trị\". Trong SQL, `NULL = NULL` trả về `UNKNOWN` (không phải `TRUE`) — gây nhiều bug nếu không hiểu rõ.\n\n### 1.13. Slide 16-18 — Key Constraints\n\n**Slide 16 — Superkey và Key:**\n\n- **Superkey** of R: *A set of attributes SK of R such that **no two tuples** in any valid relation instance r(R) will have the same value for SK. That is, for any distinct tuples t₁ and t₂ in r(R), **t₁[SK] ≠ t₂[SK]**.*\n- **Key** of R: *A \"**minimal**\" superkey; that is, a superkey K such that **removal of any attribute from K results in a set of attributes that is not a superkey**.*\n\n**Slide 17 — CAR example:**\n\n> *CAR(State, Reg#, SerialNo, Make, Model, Year)* has two keys:\n> - Key1 = {State, Reg#}\n> - Key2 = {SerialNo}\n>\n> {SerialNo, Make} là superkey nhưng **không phải** key (vì có thể bỏ Make mà vẫn unique).\n>\n> *If a relation has several **candidate keys**, one is chosen arbitrarily to be the **primary key**. The primary key attributes are **underlined**.*\n>\n> **Secondary key**: candidate key không được chọn làm primary.\n\n| Loại key | Định nghĩa | Ví dụ trên CAR |\n|---|---|---|\n| **Superkey** | Tập attribute đảm bảo unique (có thể có thừa) | {SerialNo}, {SerialNo, Make}, {State, Reg#, Year} |\n| **Candidate Key** | Superkey **tối thiểu** (không thừa) | {State, Reg#}, {SerialNo} |\n| **Primary Key (PK)** | Candidate key được chọn — **gạch chân** | {SerialNo} (giả sử) |\n| **Secondary Key** | Candidate key còn lại | {State, Reg#} |\n\n**Slide 18 — CAR với data mẫu:**\n\n| License_number | Engine_serial_number | Make | Model | Year |\n|---|---|---|---|---|\n| Texas ABC-739 | A69352 | Ford | Mustang | 02 |\n| Florida TVP-347 | B43696 | Oldsmobile | Cutlass | 05 |\n| New York MPO-22 | X83554 | Oldsmobile | Delta | 01 |\n| California 432-TFY | C43742 | Mercedes | 190-D | 99 |\n| California RSK-629 | Y82935 | Toyota | Camry | 04 |\n| Texas RSK-629 | U028365 | Jaguar | XJS | 04 |\n\n→ License_number được chọn làm PK (gạch chân). Engine_serial_number cũng là candidate.\n\n> 💡 **Hiểu đơn giản (CCCD analogy):** Superkey giống \"danh sách thông tin định danh\" có thể chứa thông tin **dư thừa** ({CCCD, Tên, SĐT}). Key/Candidate Key = phiên bản **rút gọn tối đa** vẫn unique ({CCCD}). Primary Key = cái bạn **chọn làm chính** dùng cho ID.\n\n### 1.14. Slide 19 — Entity Integrity\n\n**Nội dung slide gốc:**\n\n- **Relational Database Schema**: *A set S of relation schemas that belong to the same database. S = {R₁, R₂, …, Rₙ}.*\n- **Entity Integrity**: *Primary key attributes PK of each relation schema R in S **cannot have null values** in any tuple of r(R) because primary key values are used to identify the individual tuples: **t[PK] ≠ null** for any tuple t in r(R).*\n\n→ **Quy tắc Entity Integrity:** PK **KHÔNG ĐƯỢC** là NULL.\n\n> 💡 **Hiểu đơn giản:** Nếu Ssn (PK của EMPLOYEE) là NULL, làm sao biết tuple đó nói về AI? Không định danh được → vô nghĩa.\n\n### 1.15. Slide 20 — Referential Integrity Constraint\n\n**Nội dung slide gốc:**\n\n- *A constraint involving **two relations**.*\n- *Tuples in the referencing relation R₁ have attributes **FK** (called **foreign key attributes**) that reference the primary key attributes **PK** of the referenced relation R₂. A tuple t₁ in R₁ is said to reference a tuple t₂ in R₂ if **t₁[FK] = t₂[PK]**.*\n- *A referential integrity constraint can be displayed as a **directed arc** from R₁.FK to R₂.*\n\n| Thuật ngữ | Định nghĩa |\n|---|---|\n| **Foreign Key (FK)** | Attribute trong R₁ tham chiếu đến PK của R₂. |\n| **Referencing relation** | Bảng chứa FK (R₁). |\n| **Referenced relation** | Bảng chứa PK được tham chiếu (R₂). |\n\n### 1.16. Slide 21 — Ví dụ DEPARTMENT-EMPLOYEE\n\n> 📊 **Hình 1.2 — DEPARTMENT-EMPLOYEE (slide 21):**\n> ```\n> DEPARTMENT\n> ┌────────────────┬─────────┬───────────┬────────────────┐\n> │ DNAME          │ DNUMBER │ MGRSSN    │ MGRSTARTDATE   │\n> ├────────────────┼─────────┼───────────┼────────────────┤\n> │ Research       │ 5       │ 333445555 │ 1988-05-22     │\n> │ Administration │ 4       │ 987654321 │ 1995-01-01     │\n> │ Headquarters   │ 1       │ 888665555 │ 1981-06-19     │\n> └────────────────┴─────────┴───────────┴────────────────┘\n>          ▲           ▲\n>          │           │\n>          │           └─── DNO ─────┐\n>          └─── reference ───────┐   │\n>                                │   │\n> EMPLOYEE                       │   │\n> ┌─────────┬───────┬─────────┬──┴───┬────────────┬─────┬────────┬───────────┬─────┐\n> │ FNAME   │ MINIT │ LNAME   │ SSN  │ BDATE      │ SEX │ SALARY │ SUPERSSN  │ DNO │\n> ├─────────┼───────┼─────────┼──────┼────────────┼─────┼────────┼───────────┼─────┤\n> │ John    │ B     │ Smith   │ 123… │ 1965-01-09 │ M   │ 30000  │ 333445555 │ 5   │\n> │ Franklin│ T     │ Wong    │ 333… │ 1955-12-08 │ M   │ 40000  │ 888665555 │ 5   │\n> │ ...     │ ...   │ ...     │ ...  │ ...        │ ... │ ...    │ ...       │ ... │\n> │ James   │ E     │ Borg    │ 888… │ 1937-11-10 │ M   │ 55000  │ NULL      │ 1   │\n> └─────────┴───────┴─────────┴──────┴────────────┴─────┴────────┴───────────┴─────┘\n>\n> Mũi tên: EMPLOYEE.DNO ──→ DEPARTMENT.DNUMBER (referential integrity).\n> ```\n\n### 1.17. Slide 22 — FK có thể NULL\n\n**Nội dung slide gốc:**\n\n- *The value in the foreign key column FK of the referencing relation R₁ can be either:*\n  - *(1) a value of an existing primary key value of the corresponding primary key PK in R₂, or*\n  - *(2) a NULL.*\n- *In case (2), the FK in R₁ should not be a part of its own primary key.*\n\n→ 2 trường hợp hợp lệ cho FK: match 1 PK trong bảng được tham chiếu, hoặc NULL (chỉ khi FK không là một phần của PK của chính bảng đó).\n\n> 💡 **Ví dụ:** EMPLOYEE.Super_ssn (FK tới EMPLOYEE.Ssn) = NULL khi nhân viên đó là sếp cao nhất, không có ai supervise.\n\n### 1.18. Slide 23 — Toàn cảnh Referential Integrity COMPANY\n\n**Tổng hợp 8 FK trong COMPANY (slide 23):**\n\n| Referencing Relation . FK | Referenced Relation . PK |\n|---|---|\n| `EMPLOYEE.Super_ssn` | `EMPLOYEE.Ssn` (self-reference) |\n| `EMPLOYEE.Dno` | `DEPARTMENT.Dnumber` |\n| `DEPARTMENT.Mgr_ssn` | `EMPLOYEE.Ssn` |\n| `DEPT_LOCATIONS.Dnumber` | `DEPARTMENT.Dnumber` |\n| `PROJECT.Dnum` | `DEPARTMENT.Dnumber` |\n| `WORKS_ON.Essn` | `EMPLOYEE.Ssn` |\n| `WORKS_ON.Pno` | `PROJECT.Pnumber` |\n| `DEPENDENT.Essn` | `EMPLOYEE.Ssn` |\n\n### 1.19. Slide 24 — Other Types of Constraints\n\n**Nội dung slide gốc:**\n\n- **Semantic Integrity Constraints**:\n  - *Based on application semantics and **cannot be expressed by the model per se**.*\n  - *E.g., \"the max. no. of hours per employee for all projects he/she works on is **56 hrs per week**\".*\n  - *SQL-99 allows **triggers** and **ASSERTIONS**.*\n- **State / static constraints** (so far) — kiểm tra trạng thái hiện tại.\n- **Transition / dynamic constraints**: e.g., *\"the salary of an employee can **only increase**\"*.\n\n| Loại constraint | Ví dụ |\n|---|---|\n| **State constraint** | Sex ∈ {'M', 'F'}; Salary > 0 |\n| **Transition constraint** | New_salary ≥ Old_salary |\n| **Semantic** | Tổng giờ/tuần của 1 employee ≤ 56h |\n\n### 1.20. Slide 25-28 — Update Operations\n\n**Slide 25 — 3 thao tác:**\n\n- **INSERT** a tuple\n- **DELETE** a tuple\n- **MODIFY** a tuple\n\n*Integrity constraints should not be violated by the update operations.*\n\n**Slide 26 — Insertion phải đảm bảo:**\n\n- Giá trị attribute thuộc đúng **domain** (đúng kiểu).\n- Giá trị **prime attribute** (PK) không NULL → Entity Integrity.\n- Giá trị key **không trùng** với tuple đã có.\n- Giá trị **FK** (nếu có) phải tham chiếu đến tuple tồn tại → Referential Integrity.\n\n**Slide 27 — Deletion + Modification:**\n\n- **Deletion**: tuple phải tồn tại; không được vi phạm referential integrity.\n- **Modification**: thay đổi attribute của tuple. Constraint tương tự insert/delete.\n\n**Slide 28 — Actions on integrity violation:**\n\n- **Cancel** the operation that causes the violation (**REJECT** option).\n- **Perform** the operation but **inform** the user.\n- **Trigger additional updates** (**CASCADE** option, **SET NULL** option).\n- **Execute** a user-specified error-correction routine.\n\n| Option | Ý nghĩa | Ví dụ |\n|---|---|---|\n| **REJECT** | Hủy operation | DELETE DEPARTMENT đang có EMPLOYEE → từ chối |\n| **CASCADE** | Lan truyền | DELETE DEPARTMENT → xóa luôn EMPLOYEE |\n| **SET NULL** | Đặt FK về NULL | DELETE DEPARTMENT → set EMPLOYEE.DNO = NULL |\n| **SET DEFAULT** | Đặt về giá trị mặc định | DELETE DEPARTMENT → set EMPLOYEE.DNO = 'Unassigned' |\n\n> 💡 **Hiểu đơn giản:** Khi viết `CREATE TABLE ... FOREIGN KEY (DNO) REFERENCES DEPARTMENT(Dnumber) ON DELETE CASCADE`, bạn đang nói với DBMS: *\"khi 1 department bị xóa, hãy xóa hết employee thuộc nó.\"* (Chương 6 dạy SQL chi tiết.)\n\n> 📝 **Tóm lại §1:**\n> - Relational model = bảng 2 chiều, dựa trên set theory.\n> - Schema (cố định) vs Instance (thay đổi). Relation = set of tuples.\n> - 4 integrity constraints: Domain, Key, Entity Integrity (PK ≠ NULL), Referential Integrity.\n> - Superkey ⊇ Candidate Key ⊇ Primary Key.\n> - Update operations: 4 options khi vi phạm — REJECT, CASCADE, SET NULL, custom.\n>\n> **Một câu ghi nhớ:** *Relation là bảng có quy tắc — set theory: tuple distinct + không thứ tự; key constraint: PK không NULL; FK constraint: bảng trỏ nhau hợp lệ.*\n\n> ❓ **Tự kiểm tra §1:**\n> 1. STUDENT(Name, Ssn, Phone, GPA): `Degree` = ? `dom(GPA)` = ?\n> 2. Phân biệt Superkey, Candidate Key, Primary Key.\n> 3. CAR có 2 candidate key. Nếu chọn {State, Reg#} làm PK, {SerialNo} gọi là gì?\n> 4. Entity integrity yêu cầu gì? Vì sao quan trọng?\n> 5. FK của EMPLOYEE.Super_ssn có thể NULL không? Vì sao?\n> 6. Khi xóa DEPARTMENT đang có EMPLOYEE, 4 options nào có thể xảy ra?\n\n---\n\n","file":"materials/DB-Chapter4.md","section":2},{"id":"c4-03","group":"c4","kind":"source","title":"2. Main Phases of Database Design","markdown":"## 2. Main Phases of Database Design\n\n### 2.1. Tại sao có concept này?\n\nChương 1 đã giới thiệu sơ workflow thiết kế DB (slide 6 chương 1). Chương 4 nhắc lại để **xác định vị trí** của ER/EER-to-Relational Mapping trong toàn bộ workflow.\n\n### 2.2. Slide 30 — 3 Main Phases\n\n**Nội dung slide gốc:**\n\n- **Conceptual database design**\n- **Logical database design**\n- **Physical database design**\n\n| Phase | Output | Công cụ | DBMS-dependent? |\n|---|---|---|---|\n| **Conceptual** | ER / EER schema | Chương 2, 3 | Không |\n| **Logical** | Relational schema | **Chương 4 (mapping)** + Chương 7 (normalization) | Có (relational vs network) |\n| **Physical** | File organization, index, storage | Chương 8 | Có (Oracle vs Postgres khác) |\n\n### 2.3. Slide 31-32 — Overview Diagram\n\n> 📊 **Hình 2.1 — Database Design Process (slide 31, giống chương 2 slide 6):**\n> ```\n>            Miniworld\n>                │\n>                ▼\n>     REQUIREMENTS - COLLECTION & ANALYSIS\n>      │                      │\n>      ▼                      ▼\n> Functional req       Data requirements\n>      │                      │\n>      ▼                      ▼\n> FUNCTIONAL ANALYSIS   CONCEPTUAL DESIGN ← Chương 2, 3\n>      │                      │\n>      │                      ▼\n>      │              Conceptual schema\n>      │                      │\n>      │                      ▼\n>      │              LOGICAL DESIGN     ← CHƯƠNG 4\n>      │              (DATA MODEL MAPPING)\n>      │                      │\n>      ▼                      ▼\n> APPLICATION PROGRAM    Database schema\n>      │                      │\n>      ▼                      ▼\n> TRANSACTION             PHYSICAL DESIGN ← Chương 8\n> IMPLEMENTATION          (file, index)\n>                              │\n>                              ▼\n>                          Internal schema\n> ```\n\n### 2.4. Slide 33 — Logical Database Design\n\n**Nội dung slide gốc:**\n\n- *The process of constructing a model of the data based on a specific data model (e.g. relational), but **independent of a particular DBMS**.*\n- **ER- & EER-to-Relational Mapping** ← chương 4\n- *Normalization* ← chương 7\n\n→ **Logical Design = 2 việc**: (1) Mapping ER/EER → Relational và (2) Normalization. Chương 4 làm (1); chương 7 làm (2).\n\n### 2.5. Slide 34-35 — COMPANY ERD → Relational Result\n\nSlide 34 vẽ COMPANY ER (giống chương 2). Slide 35 cho kết quả mapping = relational schema (đã liệt kê ở §1.6 trên).\n\n> 📝 **Tóm lại §2:**\n> - 3 phases: Conceptual → Logical → Physical.\n> - Chương 4 = **Logical Design (Data Model Mapping)**.\n> - Logical = Mapping (ch. 4) + Normalization (ch. 7).\n>\n> **Một câu ghi nhớ:** *Conceptual = \"vẽ ER/EER\"; Logical = \"dịch ER/EER → bảng quan hệ\"; Physical = \"tối ưu lưu trữ\".*\n\n---\n\n","file":"materials/DB-Chapter4.md","section":3},{"id":"c4-04","group":"c4","kind":"source","title":"3. ER-/EER-to-Relational Mapping","markdown":"## 3. ER-/EER-to-Relational Mapping\n\n### 3.1. Slides 37-38 — 9 Steps Overview\n\n**Nội dung slide gốc:**\n\n- **ER:**\n  - Step 1: Mapping of Regular Entity Types\n  - Step 2: Mapping of Weak Entity Types\n  - Step 3: Mapping of Binary 1:1 Relationship Types\n  - Step 4: Mapping of Binary 1:N Relationship Types\n  - Step 5: Mapping of Binary M:N Relationship Types\n  - Step 6: Mapping of Multivalued attributes\n  - Step 7: Mapping of N-ary Relationship Types\n- **EER:**\n  - Step 8: Options for Mapping Specialization or Generalization (4 options 8A-8D)\n  - Step 9: Mapping of Union Types (Categories)\n\n> 💡 **Hiểu đơn giản:** 9 steps thực hiện **theo thứ tự** — không bỏ qua. Mỗi step nhận EER diagram làm input, sinh ra **một số bảng** hoặc **chỉnh sửa bảng đã sinh** (vd thêm FK). Sau bước 9 → relational schema hoàn chỉnh.\n\n### 3.2. Step 1 — Mapping of Regular (Strong) Entity Types\n\n**Slide 39 — Quy tắc:**\n\n- Entity → Relation\n- Attribute of entity → Attribute of relation\n- Primary key of entity → Primary key of relation\n\n**Lưu ý:**\n- **Composite attribute** → tách thành các simple component attribute.\n- **Multivalued attribute** → KHÔNG xử lý ở Step 1, để Step 6.\n- **Derived attribute** → KHÔNG đưa vào (tính khi cần).\n\n**Slide 40-41 — Ví dụ COMPANY (sau Step 1):**\n\n> 📊 **Hình 3.1 — Sau Step 1 (slide 41):**\n> ```\n> EMPLOYEE\n> ┌──────┬───────┬───────┬─────┬───────┬─────────┬─────┬────────┐\n> │FNAME │MINIT  │LNAME  │ SSN │ BDATE │ ADDRESS │ SEX │ SALARY │\n> └──────┴───────┴───────┴──↑──┴───────┴─────────┴─────┴────────┘\n>                          PK\n> DEPARTMENT\n> ┌────────┬─────────┐\n> │ DNAME  │ DNUMBER │\n> └────────┴────↑────┘\n>              PK\n>\n> PROJECT\n> ┌───────┬─────────┬───────────┐\n> │ PNAME │ PNUMBER │ PLOCATION │\n> └───────┴────↑────┴───────────┘\n>             PK\n> ```\n>\n> **Lưu ý:**\n> - `Name` (composite: Fname, Minit, Lname) đã tách thành 3 simple attribute.\n> - `Locations` (multivalued của DEPARTMENT) **chưa có** — sẽ làm ở Step 6.\n> - `Number_of_employees` (derived) **không đưa vào**.\n> - `Mgr_ssn`, `Mgr_start_date` (DEPARTMENT) **chưa có** — Step 3 (1:1 MANAGES).\n> - `Dno`, `Super_ssn`, `DNum` **chưa có** — Step 4.\n\n### 3.3. Step 2 — Mapping of Weak Entity Types\n\n**Slide 43 — Quy tắc:**\n\n> *For each weak entity type W in the ER schema with owner entity type E, create a relation R and include all simple attributes (or simple components of composite attributes) of W as attributes of R.*\n>\n> *In addition, include as **foreign key attributes** of R the **primary key attribute(s)** of the relation(s) that correspond to the owner entity type(s).*\n>\n> *The primary key of R is the **combination** of the primary key(s) of the owner(s) and the partial key of the weak entity type W, if any.*\n\n**Slide 45 — Ví dụ DEPENDENT:**\n\nDEPENDENT là weak entity, owner = EMPLOYEE qua relationship `DEPENDENTS_OF`. Partial key = `Name` (gạch chân nét đứt).\n\n> 📊 **Hình 3.2 — Sau Step 2 (slide 45):**\n> ```\n> DEPENDENT\n> ┌──────┬─────────────────┬─────┬───────┬──────────────┐\n> │ ESSN │ DEPENDENT_NAME  │ SEX │ BDATE │ RELATIONSHIP │\n> └──↑───┴────────↑────────┴─────┴───────┴──────────────┘\n>    │           │\n>    └─PK──── PK ┘\n>    └─ FK → EMPLOYEE.SSN\n>\n> Primary Key = {ESSN, DEPENDENT_NAME} (composite).\n> Note: ON DELETE CASCADE — khi EMPLOYEE bị xóa, DEPENDENT cũng bị xóa.\n> ```\n\n> 💡 **Hiểu đơn giản:** Weak entity = \"đứa con không có CCCD riêng\". Phải dùng CCCD của bố/mẹ + tên để định danh. → PK = {Owner_PK, Partial_key}.\n\n### 3.4. Step 3 — Mapping of Binary 1:1 Relationship Types\n\n**Slides 47-50 — 3 approaches:**\n\n**Approach 1 — Foreign Key Approach:**\n\n> *Choose one of the relations — E2, say — and include as a foreign key in E2 the primary key of E1. It is **better to choose** an entity type with **total participation (mandatory)** in R in the role of E2.*\n\n```\nER:  E1 ─1─◇R◇─1─ E2\n\n→  E1(K1)\n   E2(K2, K1)   ← FK K1 đặt ở E2 (bên total participation)\n```\n\n**Approach 2 — Merged Relation Approach (chỉ khi cả 2 total):**\n\n> *When **both participations are total**, merge the two entity types and the relationship into a **single relation**.*\n\n```\nER:  E1 ═1═◇R◇═1═ E2  (cả 2 đường đôi)\n\n→  E12(K1, K2, ... attributes of E1, E2, R)\n   PK can be K1 or K2.\n```\n\n**Approach 3 — Cross-reference / Relationship Relation:**\n\n> *Set up a third relation R for the purpose of cross-referencing the primary keys of the two relations E1 and E2.*\n\n```\nER:  E1 ─1─◇R◇─1─ E2\n\n→  E1(K1)\n   E2(K2)\n   R(K1, K2)   PK của R có thể là K1 hoặc K2\n```\n\n**Slide 51-52 — Ví dụ MANAGES (1:1, EMPLOYEE-DEPARTMENT):**\n\nDEPARTMENT phải có quản lý → total participation phía DEPARTMENT.\n→ Dùng Approach 1, đặt FK ở DEPARTMENT:\n\n```\nDEPARTMENT\n┌────────┬─────────┬───────────┬────────────────┐\n│ DNAME  │ DNUMBER │ MGRSSN    │ MGRSTARTDATE   │\n└────────┴─────────┴────↑──────┴────────────────┘\n                        FK → EMPLOYEE.SSN\n```\n\n### 3.5. Step 4 — Mapping of Binary 1:N Relationship Types\n\n**Slide 54 — 2 approaches:**\n\n**Approach 1 — Foreign Key Approach (phổ biến nhất):**\n\n> *Include as foreign key in **E2 (N-side)** the primary key of the relation E1 (1-side).*\n\n```\nER:  E1 ─1─◇R◇─N─ E2\n\n→  E1(K1)\n   E2(K2, K1)   ← FK K1 đặt ở E2 (bên N-side)\n```\n\n**Approach 2 — Relationship Relation Approach (almost optional):**\n\n> *Create a separate relation R whose attributes are the primary keys of E1 and E2. The primary key of R is the foreign key from the entity type at the **N-side**.*\n>\n> *This option can be used if **few tuples** in E2 participate in the relationship to **avoid excessive NULL** values.*\n\n```\nER:  E1 ─1─◇R◇─N─ E2  (E2 partial — almost optional)\n\n→  E1(K1)\n   E2(K2)\n   R(K1, K2)   PK = K2\n```\n\n**Slide 56-57 — Ví dụ COMPANY (3 relationship 1:N):**\n\n| Relationship | Cardinality | Mapping |\n|---|---|---|\n| **WORKS_FOR** | EMPLOYEE (N) — DEPARTMENT (1) | FK `EMPLOYEE.Dno → DEPARTMENT.Dnumber` |\n| **CONTROLS** | DEPARTMENT (1) — PROJECT (N) | FK `PROJECT.Dnum → DEPARTMENT.Dnumber` |\n| **SUPERVISION** | EMPLOYEE Supervisor (1) — EMPLOYEE Supervisee (N) | FK `EMPLOYEE.Super_ssn → EMPLOYEE.Ssn` (recursive) |\n\n**Slide 58 — Ví dụ BORROWER-BOOK:**\n\n> *BORROWER ─1─◇ON_LOAN◇─N─ BOOK*\n>\n> One possible representation:\n> ```\n> BORROWER(BNUMBER, NAME, ADDRESS, ...)\n> BOOK(ISBN, TITLE, ..., BNUMBER)   ← FK\n> ```\n>\n> A better alternative (nếu nhiều book chưa được mượn → tránh NULL):\n> ```\n> BORROWER(BNUMBER, NAME, ADDRESS, ...)\n> BOOK(ISBN, TITLE, ...)\n> ON_LOAN(ISBN, BNUMBER)\n> ```\n\n### 3.6. Step 5 — Mapping of Binary M:N Relationship Types\n\n**Slide 60 — Quy tắc:**\n\n> *An M:N relationship is **always** represented by a **new relation** which consists of the prime attributes of both participating entity types together with **any attributes of the relationship**.*\n>\n> *The combination of the prime attributes will form the **primary key** of the new relation.*\n\n```\nER:  E1 ─M─◇R(attrs)◇─N─ E2\n\n→  E1(K1)\n   E2(K2)\n   R(K1, K2, attrs)   PK = {K1, K2} (composite)\n```\n\n→ **Không có lựa chọn nào khác** — M:N **bắt buộc** tách thành relation riêng.\n\n**Slide 61-62 — Ví dụ WORKS_ON (M:N giữa EMPLOYEE và PROJECT):**\n\n```\nWORKS_ON\n┌──────┬─────┬───────┐\n│ ESSN │ PNO │ HOURS │\n└──↑───┴──↑──┴───────┘\n   │     └── FK → PROJECT.PNUMBER\n   └─────── FK → EMPLOYEE.SSN\nPrimary Key = {ESSN, PNO}.\n```\n\n### 3.6a. Recursive (Involuted) Relationships — Slides 63-65\n\n**Slide 63 — Quy tắc:**\n\n> *Relationship among different instances of the **same entity**. The name(s) of the prime attribute(s) needs to be **changed to reflect the role** each entity plays.*\n\n3 ví dụ:\n\n**Slide 64 — Example 1: PERSON-MARRY (1:1, optional cả 2):**\n\n```\nPERSON(ID, NAME, ADDRESS, ...)\nMARRY(HUSBAND_ID, WIFE_ID, DATE_OF_MARRIAGE)\n       PK = HUSBAND_ID hoặc WIFE_ID\n```\n→ Dùng Approach 3 (cross-reference) vì cả 2 phía optional → tránh NULL.\n\n**Slide 65 — Example 2: EMPLOYEE-SUPERVISE (1:M):**\n\n- *Mandatory hoặc almost mandatory:*\n  ```\n  EMPLOYEE(ID, ENAME, ..., SUPERVISOR_ID)\n                            ↑ FK → EMPLOYEE.ID (self-ref)\n  ```\n- *Optional:*\n  ```\n  EMPLOYEE(ID, ENAME, ...)\n  SUPERVISE(ID, START_DATE, ..., SUPERVISOR_ID)\n            PK = ID\n  ```\n\n**Example 3: PART-COMPRISE (N:M):**\n\n```\nPART(PNUMBER, DESCRIPTION, ...)\nCOMPRISE(MAJOR_PNUMBER, MINOR_PNUMBER, QUANTITY)\n          PK = {MAJOR_PNUMBER, MINOR_PNUMBER}\n          (Vd: 1 xe đạp gồm 2 bánh + 1 khung)\n```\n\n> 💡 **Hiểu đơn giản:** Recursive = entity tham chiếu chính nó. Cần **đổi tên** prime attribute (Ssn → Super_ssn, ID → SUPERVISOR_ID) để phân biệt 2 vai trò.\n\n### 3.7. Step 6 — Mapping of Multivalued Attributes\n\n**Slide 67 — Quy tắc:**\n\n> *For each multivalued attribute A, create a new relation R. This relation R will include an attribute corresponding to A, plus the primary key attribute K — as a foreign key in R — of the relation that represents the entity type or relationship type that has A as an attribute.*\n>\n> *The primary key of R is the **combination of A and K**. If the multivalued attribute is composite, we include its simple components.*\n\n```\nER:  Entity E with multivalued attr A\n\n→  E(K, ...other simple attrs)\n   E_A(K, A)   PK = {K, A}, FK K → E.K\n```\n\n**Slide 68-69 — Ví dụ DEPT_LOCATIONS:**\n\n```\nDEPT_LOCATIONS\n┌─────────┬───────────┐\n│ DNUMBER │ DLOCATION │\n└────↑────┴────↑──────┘\n     │         │\n     └────── PK ─────┘  (composite)\n     └── FK → DEPARTMENT.DNUMBER\n```\n\n### 3.8. Step 7 — Mapping of N-ary Relationship Types\n\n**Slide 70 — Quy tắc:**\n\n> *For each n-ary relationship type R, where n > 2, create a new relationship S to represent R.*\n>\n> *Include as foreign key attributes in S the primary keys of the relations that represent the participating entity types.*\n>\n> *Also include any simple attributes of the n-ary relationship type as attributes of S.*\n\n**Slide 71-74 — Ví dụ ternary SUPPLY (SUPPLIER, PROJECT, PART, attribute Quantity):**\n\n```\nSUPPLIER(SNAME, ...)\nPROJECT(PROJNAME, ...)\nPART(PARTNO, ...)\n\nSUPPLY(SNAME, PROJNAME, PARTNO, QUANTITY)\n       PK mặc định = {SNAME, PROJNAME, PARTNO}\n```\n\n**Note quan trọng (slide 71-74):**\n\n> *If the cardinality constraint on any of the entity types E participating in the relationship is **1**, the PK should **not include** the FK attributes that reference the relation E' corresponding to E.*\n\n| Cardinality | PK của SUPPLY |\n|---|---|\n| N:N:N (cả 3 đều N) | {SNAME, PROJNAME, PARTNO} |\n| 1:N:N (SUPPLIER là 1) | {PROJNAME, PARTNO} (bỏ SNAME) |\n| 1:1:N (SUPPLIER, PROJECT là 1) | {PARTNO} |\n| 1:1:1 | Không xác định được — cần thêm constraint |\n\n### 3.9. Slide 75 — Bảng tương ứng ER ↔ Relational\n\n**🌟 Đây là bảng vàng — học thuộc!**\n\n| ER Model | Relational Model |\n|---|---|\n| Entity type | \"Entity\" relation |\n| 1:1 or 1:N relationship type | Foreign key (or \"relationship\" relation) |\n| M:N relationship type | \"Relationship\" relation & 2 foreign keys |\n| n-ary relationship type | \"Relationship\" relation & n foreign keys |\n| Simple attribute | Attribute |\n| Composite attribute | Set of simple component attributes |\n| Multivalued attribute | Relation and foreign key |\n| Value set | Domain |\n| Key attribute | Primary (or secondary) key |\n\n### 3.10. Step 8 — Mapping Specialization/Generalization (4 Options)\n\n**Slide 77 — 4 options overview:**\n\n> *Convert each specialization with m subclasses {S1, S2, …, Sm} and generalized superclass C, where the attributes of C are {k, a1, …, an} and k is the (primary) key, into relational schemas using one of the four following options:*\n\n#### 3.10.1. Option 8A — Superclass + Subclasses (slide 78)\n\n> *Create a relation L for C with attributes Attrs(L) = {k, a1, …, an} and PK(L) = k. Create a relation Li for each subclass Si with attributes Attrs(Li) = {{k} ∪ {attributes of Si}} and PK(Li) = k.*\n>\n> *This option works for **ANY** specialization (total or partial, disjoint or overlapping).*\n\n→ **Tạo m+1 bảng**: 1 cho superclass + m cho subclass.\n\n**Slide 79 — Ví dụ Option 8A (EMPLOYEE → SECRETARY/TECHNICIAN/ENGINEER):**\n\n```\nEMPLOYEE(SSN, FName, MInit, LName, BirthDate, Address, JobType)\nSECRETARY(SSN, TypingSpeed)        FK SSN → EMPLOYEE.SSN\nTECHNICIAN(SSN, TGrade)            FK SSN → EMPLOYEE.SSN\nENGINEER(SSN, EngType)             FK SSN → EMPLOYEE.SSN\n```\n\n→ ✅ **Ưu:** Linh hoạt, áp dụng được cho mọi loại specialization.\n→ ❌ **Nhược:** Truy vấn cần JOIN nhiều bảng.\n\n#### 3.10.2. Option 8B — Subclass relations only (slide 78)\n\n> *Create a relation Li for each subclass Si with attributes Attr(Li) = {{attributes of Si} ∪ {k, a1, …, an}} and PK(Li) = k.*\n>\n> *This option **only works for a specialization whose subclasses are TOTAL**.*\n>\n> *It is **only recommended if the specialization has the disjointness constraint**. If overlapping, the same entity may be duplicated.*\n\n→ **Bỏ superclass**, tất cả attribute superclass được copy vào mỗi subclass.\n\n**Slide 80 — Ví dụ Option 8B (VEHICLE → CAR/TRUCK, total):**\n\n```\nCAR(VehicleId, LicensePlateNo, Price, MaxSpeed, NoOfPassengers)\nTRUCK(VehicleId, LicensePlateNo, Price, NoOfAxles, Tonnage)\n```\n\n→ Mỗi vehicle nằm trong 1 trong 2 bảng (vì disjoint + total).\n\n#### 3.10.3. Option 8C — Single relation with one type attribute (slide 81)\n\n> *Create a single relation L with attributes Attrs(L) = {k, a1, …, an} ∪ {attributes of S1} ∪ … ∪ {attributes of Sm} ∪ {t} and PK(L) = k.*\n>\n> *The attribute t is called a **type (or discriminating) attribute** that indicates the subclass to which each tuple belongs.*\n>\n> *This option **works only for a specialization whose subclasses are disjoint**.*\n\n→ **Gộp tất cả vào 1 bảng**, thêm 1 cột `type` để phân biệt.\n\n**Slide 82 — Ví dụ Option 8C (EMPLOYEE):**\n\n```\nEMPLOYEE(SSN, FName, MInit, LName, BirthDate, Address, JobType,\n         TypingSpeed, TGrade, EngType)\n```\n\n→ Với mỗi tuple:\n- Nếu `JobType = 'Secretary'` → `TypingSpeed` có giá trị, `TGrade` và `EngType` NULL.\n- Nếu `JobType = 'Technician'` → `TGrade` có giá trị, hai cái kia NULL.\n\n→ ❌ **Nhược:** Nhiều NULL.\n\n#### 3.10.4. Option 8D — Single relation with multiple type attributes (slide 81)\n\n> *Create a single relation schema L with attributes Attrs(L) = {k, a1, …, an} ∪ {attributes of S1} ∪ … ∪ {attributes of Sm} ∪ {t1, t2, …, tm} and PK(L) = k. Each ti is a **Boolean type attribute** indicating whether a tuple belongs to the subclass Si.*\n\n→ **Gộp 1 bảng**, có **m flag boolean** thay vì 1 type attribute.\n\n**Slide 83 — Ví dụ Option 8D (PART → MANUFACTURED/PURCHASED, overlapping):**\n\n```\nPART(PartNo, Description, MFlag, DrawingNo, ManufactureDate, BatchNo,\n     PFlag, SupplierName, ListPrice)\n```\n\n- `MFlag = TRUE` → là MANUFACTURED_PART.\n- `PFlag = TRUE` → là PURCHASED_PART.\n- Cả hai TRUE → vừa được sản xuất nội bộ, vừa mua từ supplier.\n\n#### 3.10.5. 🌟 Bảng so sánh 4 options — Decision Matrix\n\n| Option | Số bảng | Hỗ trợ Disjoint? | Hỗ trợ Overlapping? | Hỗ trợ Total? | Hỗ trợ Partial? | Số NULL | Khi nào dùng |\n|---|---:|:---:|:---:|:---:|:---:|---|---|\n| **8A** | m+1 | ✅ | ✅ | ✅ | ✅ | Ít | **Linh hoạt mặc định** — áp dụng được mọi case |\n| **8B** | m | ✅ | ⚠ Duplicate | ✅ | ❌ | Ít | Total + Disjoint, ít attribute chung |\n| **8C** | 1 | ✅ | ❌ | ✅ | ✅ | Nhiều | Disjoint, đơn giản, ít subclass |\n| **8D** | 1 | ✅ | ✅ | ✅ | ✅ | Rất nhiều | **Overlapping** (8C không xử lý được) |\n\n**Quyết định nhanh:**\n- Cần linh hoạt → **8A** (mặc định an toàn)\n- Total + Disjoint, ít attr chung → **8B**\n- Disjoint, ít subclass → **8C**\n- **Overlapping** → **8D** (hoặc 8A)\n\n#### 3.10.6. Mapping Shared Subclasses (slides 84-86)\n\n**Slide 84:**\n\n> *A shared subclass, such as STUDENT_ASSISTANT, is a subclass of several classes, indicating multiple inheritance. These classes must all have the **same key attribute**; otherwise, the shared subclass would be modeled as a category.*\n\n**Slide 85-86 — Ví dụ UNIVERSITY lattice:**\n\n> 📊 **Mapping kết quả (slide 86):**\n> ```\n> PERSON(Ssn, Name, Birth_date, Sex, Address)\n>\n> EMPLOYEE(Ssn, Salary, Employee_type, Position, Rank, Percent_time,\n>          Ra_flag, Ta_flag, Project, Course)\n>          FK Ssn → PERSON.Ssn\n>\n> ALUMNUS(Ssn)\n>          FK Ssn → PERSON.Ssn\n>\n> ALUMNUS_DEGREES(Ssn, Year, Degree, Major)\n>          FK Ssn → ALUMNUS.Ssn\n>          (Degrees là multivalued composite của ALUMNUS → tách thành bảng riêng)\n>\n> STUDENT(Ssn, Major_dept, Grad_flag, Undergrad_flag, Degree_program,\n>         Class, Student_assist_flag)\n>         FK Ssn → PERSON.Ssn\n> ```\n>\n> **Lưu ý:**\n> - PERSON dùng option 8A (superclass riêng).\n> - EMPLOYEE chia thành STAFF/FACULTY/STUDENT_ASSISTANT — dùng 8C (Employee_type) + 8D (Ra_flag/Ta_flag).\n> - STUDENT có Grad_flag/Undergrad_flag (8D) + Student_assist_flag.\n\n### 3.11. Step 9 — Mapping of Union Types (Categories)\n\n**Slide 87 — Surrogate Key:**\n\n> *For mapping a category whose defining superclass have **different keys**, it is customary to specify a new key attribute, called a **surrogate key**, when creating a relation to correspond to the category.*\n\n→ Khi superclass của category có **key khác nhau** (vd PERSON.Ssn vs BANK.BName vs COMPANY.CName) → tạo **surrogate key** mới.\n\n**Slide 88 — Ví dụ OWNER:**\n\n> 📊 **Mapping (slide 88):**\n> ```\n> PERSON(Ssn, Driver_license_no, Name, Address, Owner_id)\n>                                              ↑ FK → OWNER.Owner_id\n> BANK(Bname, Baddress, Owner_id)\n>                       ↑ FK → OWNER.Owner_id\n> COMPANY(Cname, Caddress, Owner_id)\n>                          ↑ FK → OWNER.Owner_id\n>\n> OWNER(Owner_id)   ← surrogate key (mới sinh)\n>\n> REGISTERED_VEHICLE(Vehicle_id, License_plate_number)\n>\n> CAR(Vehicle_id, Cstyle, Cmake, Cmodel, Cyear)\n>      FK Vehicle_id → REGISTERED_VEHICLE.Vehicle_id\n> TRUCK(Vehicle_id, Tmake, Tmodel, Tonnage, Tyear)\n>      FK Vehicle_id → REGISTERED_VEHICLE.Vehicle_id\n>\n> OWNS(Owner_id, Vehicle_id, Purchase_date, Lien_or_regular)\n>      PK = {Owner_id, Vehicle_id}\n> ```\n>\n> **Đặc điểm:**\n> - OWNER chỉ có **1 cột** = surrogate key.\n> - PERSON/BANK/COMPANY mỗi cái thêm `Owner_id` để tham chiếu lên OWNER.\n> - REGISTERED_VEHICLE có key chung `Vehicle_id` — không cần surrogate.\n\n> 💡 **Hiểu đơn giản:** Surrogate key = \"ID nhân tạo\" do hệ thống sinh, dùng khi không có natural key chung. Trong thực tế, đây cũng là pattern phổ biến — vd Django ORM tự sinh `id` (auto-increment) cho mỗi bảng.\n\n> 📝 **Tóm lại §3:**\n> - **9 steps** áp dụng tuần tự lên ER/EER → relational schema.\n> - **ER (Step 1-7)**: Regular entity → bảng; Weak → bảng + composite PK; 1:1 → 3 approaches; 1:N → FK ở N-side; M:N → bảng riêng; multivalued → bảng riêng; n-ary → bảng + n FK.\n> - **EER (Step 8-9)**: Specialization có **4 options 8A/8B/8C/8D**; Category dùng **surrogate key**.\n> - Recursive: đổi tên attribute để phân biệt 2 vai trò.\n>\n> **Một câu ghi nhớ:** *Mọi entity → bảng. 1:N → FK ở phía N. M:N → bảng riêng. Multivalued → bảng riêng. Specialization → 4 options chọn theo disjoint/overlap × total/partial. Category → surrogate key.*\n\n> ❓ **Tự kiểm tra §3:**\n> 7. Step 1 và Step 2 khác nhau về cách xử lý PK?\n> 8. Trong COMPANY, MANAGES là 1:1. Vì sao FK đặt ở DEPARTMENT mà không ở EMPLOYEE?\n> 9. Vì sao M:N **bắt buộc** tạo bảng riêng?\n> 10. Multivalued attribute Locations của DEPARTMENT mapping thành gì?\n> 11. Trong recursive 1:N SUPERVISION, FK gọi là gì? Vì sao đổi tên?\n> 12. Liệt kê 4 options của Step 8. Khi nào dùng option nào?\n> 13. Cho specialization PART → {MANUFACTURED, PURCHASED} (overlapping). Option nào phù hợp?\n> 14. Khi nào cần surrogate key cho category? Cho ví dụ.\n\n---\n\n","file":"materials/DB-Chapter4.md","section":4},{"id":"c4-05","group":"c4","kind":"source","title":"4. Toàn bộ kết quả mapping COMPANY ER schema","markdown":"## 4. Toàn bộ kết quả mapping COMPANY ER schema\n\nSau khi áp dụng đầy đủ 9 steps lên COMPANY ER (chương 2 + slide 34 chương 4), kết quả là:\n\n### 4.1. Relational Schema đầy đủ\n\n```\nEMPLOYEE(Fname, Minit, Lname, Ssn, Bdate, Address, Sex, Salary, Super_ssn, Dno)\nDEPARTMENT(Dname, Dnumber, Mgr_ssn, Mgr_start_date)\nDEPT_LOCATIONS(Dnumber, Dlocation)\nPROJECT(Pname, Pnumber, Plocation, Dnum)\nWORKS_ON(Essn, Pno, Hours)\nDEPENDENT(Essn, Dependent_name, Sex, Bdate, Relationship)\n```\n\n### 4.2. Primary Keys\n\n| Relation | Primary Key | Lý do |\n|---|---|---|\n| EMPLOYEE | `Ssn` | Step 1 — entity key |\n| DEPARTMENT | `Dnumber` | Step 1 — entity key |\n| DEPT_LOCATIONS | {`Dnumber`, `Dlocation`} | Step 6 — composite (FK + multivalued attr) |\n| PROJECT | `Pnumber` | Step 1 — entity key |\n| WORKS_ON | {`Essn`, `Pno`} | Step 5 — composite của 2 PK |\n| DEPENDENT | {`Essn`, `Dependent_name`} | Step 2 — owner_PK + partial_key |\n\n### 4.3. Foreign Keys\n\n| FK | → Referenced PK | Step |\n|---|---|---|\n| `EMPLOYEE.Super_ssn` | `EMPLOYEE.Ssn` | Step 4 (recursive 1:N SUPERVISION) |\n| `EMPLOYEE.Dno` | `DEPARTMENT.Dnumber` | Step 4 (1:N WORKS_FOR) |\n| `DEPARTMENT.Mgr_ssn` | `EMPLOYEE.Ssn` | Step 3 (1:1 MANAGES) |\n| `DEPT_LOCATIONS.Dnumber` | `DEPARTMENT.Dnumber` | Step 6 |\n| `PROJECT.Dnum` | `DEPARTMENT.Dnumber` | Step 4 (1:N CONTROLS) |\n| `WORKS_ON.Essn` | `EMPLOYEE.Ssn` | Step 5 (M:N) |\n| `WORKS_ON.Pno` | `PROJECT.Pnumber` | Step 5 (M:N) |\n| `DEPENDENT.Essn` | `EMPLOYEE.Ssn` | Step 2 (weak) |\n\n→ Tổng **8 foreign keys** trong COMPANY. **Học thuộc bảng này** — hay ra thi cuối kỳ và thi BTL1.\n\n---\n\n","file":"materials/DB-Chapter4.md","section":5},{"id":"c4-06","group":"c4","kind":"source","title":"5. Bảng Tổng Hợp Thuật Ngữ Chương 4","markdown":"## 5. Bảng Tổng Hợp Thuật Ngữ Chương 4\n\n| STT | Thuật ngữ (EN) | Tiếng Việt | Định nghĩa ngắn | Slide | Ví dụ COMPANY |\n|---:|---|---|---|---:|---|\n| 1 | Relational Data Model | Mô hình quan hệ | Bảng 2 chiều, dựa set theory | 5, 6 | EMPLOYEE, DEPARTMENT là relations |\n| 2 | Relation | Quan hệ | Bảng | 6 | EMPLOYEE |\n| 3 | Relation Schema R(A₁,…,Aₙ) | Lược đồ quan hệ | Tên + danh sách attribute | 6 | `EMPLOYEE(Fname, …, Dno)` |\n| 4 | Attribute | Thuộc tính | Cột | 6 | Salary, Ssn |\n| 5 | Domain D / dom(Aᵢ) | Miền giá trị | Tập giá trị nguyên tử + ràng buộc | 7 | dom(Sex) = {'M', 'F'} |\n| 6 | Degree | Bậc | Số attribute | 7 | Degree(EMPLOYEE) = 10 |\n| 7 | Tuple | Bộ | Hàng | 8, 9 | 1 hàng employee |\n| 8 | Cardinality | Lực lượng | Số tuple | 8 | #EMPLOYEE = 8 |\n| 9 | Database Schema | Lược đồ CSDL | Tập relation schemas | 8, 19 | COMPANY = {EMPLOYEE, DEPT, …} |\n| 10 | Relation r / Instance / State | Thể hiện | Bảng có data tại 1 thời điểm | 9 | Bảng EMPLOYEE hiện tại |\n| 11 | NULL | Giá trị rỗng | Không có giá trị | 15 | EMPLOYEE.Super_ssn = NULL |\n| 12 | Domain Constraint | Ràng buộc miền | Giá trị thuộc đúng domain | 14 | Sex ∈ {'M', 'F'} |\n| 13 | Key Constraint | Ràng buộc khóa | Không có 2 tuple cùng key | 14, 16 | 2 employee không cùng Ssn |\n| 14 | Superkey | Siêu khóa | Tập attr đảm bảo unique | 16 | {Ssn, Fname} |\n| 15 | Key | Khóa | Superkey tối thiểu | 16 | {Ssn} |\n| 16 | Candidate Key | Khóa ứng viên | Mọi key của relation | 17 | EMPLOYEE chỉ có 1 candidate {Ssn} |\n| 17 | Primary Key (PK) | Khóa chính | Candidate key được chọn | 17 | EMPLOYEE.Ssn (gạch chân) |\n| 18 | Secondary Key | Khóa phụ | Candidate không được chọn | 17 | Trường hợp CAR: {State, Reg#} |\n| 19 | Entity Integrity | Toàn vẹn thực thể | PK ≠ NULL | 19 | Ssn không được NULL |\n| 20 | Referential Integrity | Toàn vẹn tham chiếu | FK trỏ đến tuple tồn tại hoặc NULL | 20-22 | EMPLOYEE.Dno → DEPARTMENT.Dnumber |\n| 21 | Foreign Key (FK) | Khóa ngoại | Attr tham chiếu PK bảng khác | 20 | EMPLOYEE.Dno |\n| 22 | Referencing Relation | Quan hệ tham chiếu | Bảng chứa FK | 20 | EMPLOYEE chứa Dno |\n| 23 | Referenced Relation | Quan hệ được tham chiếu | Bảng chứa PK | 20 | DEPARTMENT chứa Dnumber |\n| 24 | Semantic Constraint | Ràng buộc ngữ nghĩa | Constraint không biểu diễn trực tiếp | 24 | Hours ≤ 56 / tuần |\n| 25 | State Constraint | Ràng buộc trạng thái | Kiểm tra trạng thái hiện tại | 24 | Salary > 0 |\n| 26 | Transition Constraint | Ràng buộc chuyển trạng thái | Kiểm tra chuyển | 24 | Salary chỉ tăng |\n| 27 | INSERT/DELETE/MODIFY | Thêm/Xóa/Sửa | 3 thao tác cập nhật | 25 | INSERT INTO EMPLOYEE |\n| 28 | REJECT/CASCADE/SET NULL | 3 actions vi phạm | Hủy / lan / NULL | 28 | ON DELETE CASCADE |\n| 29 | Step 1: Regular Entity | Step entity mạnh | Entity → bảng | 39 | EMPLOYEE → bảng EMPLOYEE |\n| 30 | Step 2: Weak Entity | Step entity yếu | Bảng + PK kết hợp | 43 | DEPENDENT(Essn, Dependent_name) |\n| 31 | Step 3: Binary 1:1 | Step 1:1 | 3 approaches | 47-49 | MANAGES → DEPARTMENT.Mgr_ssn |\n| 32 | Step 4: Binary 1:N | Step 1:N | FK ở N-side | 54 | WORKS_FOR → EMPLOYEE.Dno |\n| 33 | Step 5: Binary M:N | Step M:N | Bảng riêng + 2 FK | 60 | WORKS_ON(Essn, Pno, Hours) |\n| 34 | Step 6: Multivalued attr | Step thuộc tính đa trị | Bảng riêng | 67 | DEPT_LOCATIONS |\n| 35 | Step 7: N-ary | Step n-ary | Bảng + n FK | 70 | SUPPLY(SNAME, PROJNAME, PARTNO) |\n| 36 | Step 8: Specialization | Step chuyên biệt | 4 options | 77 | EMPLOYEE → SEC/TECH/ENG |\n| 37 | Option 8A | — | Superclass + subclasses | 78, 79 | EMPLOYEE + 3 subclass |\n| 38 | Option 8B | — | Subclass only | 78, 80 | CAR + TRUCK (no VEHICLE) |\n| 39 | Option 8C | — | Single + type attr | 81, 82 | EMPLOYEE với JobType |\n| 40 | Option 8D | — | Single + Boolean flags | 81, 83 | PART với MFlag, PFlag |\n| 41 | Step 9: Union Type | Step kiểu hợp | Surrogate key | 87 | OWNER với Owner_id |\n| 42 | Surrogate Key | Khóa thay thế | Key nhân tạo (auto-id) | 87 | OWNER.Owner_id |\n| 43 | Recursive Relationship | Quan hệ đệ quy | Entity tham chiếu chính nó | 63 | EMPLOYEE.Super_ssn |\n| 44 | Type / Discriminating Attribute | Thuộc tính phân loại | Cột chỉ ra subclass | 81 | EMPLOYEE.JobType |\n| 45 | Composite Key | Khóa kết hợp | PK gồm nhiều attribute | 43, 60 | DEPENDENT PK = {Essn, Dependent_name} |\n\n---\n\n","file":"materials/DB-Chapter4.md","section":6},{"id":"c4-07","group":"c4","kind":"source","title":"6. Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## 6. Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\n1. **Định nghĩa khái niệm**: relation, schema, tuple, attribute, domain, degree, cardinality.\n2. **4 loại Integrity Constraints**: Domain, Key, Entity Integrity, Referential Integrity.\n3. **Phân biệt Superkey, Candidate Key, Primary Key, Secondary Key, Foreign Key**.\n4. **Entity Integrity**: PK ≠ NULL.\n5. **Referential Integrity**: FK ∈ PK_referenced ∪ {NULL}.\n6. **4 actions khi vi phạm**: REJECT, CASCADE, SET NULL, custom.\n7. **🌟 Bảng tương ứng ER ↔ Relational** (slide 75) — học thuộc.\n8. **9 Steps mapping** — đặc biệt:\n   - Step 2: PK weak entity = `{owner_PK, partial_key}`.\n   - Step 3 (1:1): 3 approaches, ưu tiên đặt FK ở phía total participation.\n   - Step 4 (1:N): FK ở phía N.\n   - Step 5 (M:N): bảng riêng, PK = `{K1, K2}`.\n   - Step 6: multivalued → bảng riêng.\n   - Step 7 (N-ary): note về cardinality 1.\n   - Step 8: 4 options 8A/8B/8C/8D — chọn theo (disjoint vs overlap) × (total vs partial).\n   - Step 9: surrogate key cho category với superclass khác key.\n9. **Recursive relationship**: đổi tên prime attribute (Ssn → Super_ssn).\n10. **🌟 Toàn bộ COMPANY mapping result** (§4) — 6 bảng + 8 FK.\n\n---\n\n","file":"materials/DB-Chapter4.md","section":7},{"id":"c4-08","group":"c4","kind":"source","title":"7. Bảng Tra Nhanh (Quick Reference)","markdown":"## 7. Bảng Tra Nhanh (Quick Reference)\n\n| Tình huống | Mapping rule | Kết quả |\n|---|---|---|\n| Regular entity với attribute đơn giản | Step 1 | Bảng riêng, PK = key của entity |\n| Composite attribute | Step 1 | Tách thành simple components |\n| Multivalued attribute | Step 6 | Bảng riêng, PK = {entity_PK, attr} |\n| Derived attribute | Step 1 | **KHÔNG** lưu (tính khi cần) |\n| Weak entity | Step 2 | Bảng + composite PK = {owner_PK, partial_key}, FK → owner |\n| Binary 1:1, total một bên | Step 3 (FK approach) | FK ở bên total |\n| Binary 1:1, total cả 2 | Step 3 (Merged) | Gộp 2 entity vào 1 bảng |\n| Binary 1:1, optional cả 2 | Step 3 (Cross-ref) | Bảng R riêng |\n| Binary 1:N | Step 4 | FK ở phía N |\n| Binary 1:N, N-side hiếm tham gia | Step 4 (Rel relation) | Bảng riêng → tránh NULL |\n| Binary M:N | Step 5 | Bảng riêng + composite PK + 2 FK |\n| Recursive 1:1 (MARRY) | Step 5 + đổi tên | MARRY(Husband_id, Wife_id) |\n| Recursive 1:N (SUPERVISE) | Step 4 + đổi tên | EMPLOYEE.Super_ssn |\n| Recursive M:N (COMPRISE) | Step 5 + đổi tên | COMPRISE(Major_pno, Minor_pno) |\n| N-ary (n>2) | Step 7 | Bảng + n FK |\n| Specialization disjoint partial | Step 8 (8A/8C) | 8A: linh hoạt; 8C: gọn |\n| Specialization disjoint total | Step 8 (8A/8B/8C) | 8B: bỏ superclass |\n| Specialization overlapping | Step 8 (8A/8D) | 8D: Boolean flags |\n| Shared subclass (cùng key) | Step 8 + multiple inheritance | Áp dụng 8A/B/C/D |\n| Category với superclass khác key | Step 9 | Surrogate key |\n\n---\n\n","file":"materials/DB-Chapter4.md","section":8},{"id":"c4-09","group":"c4","kind":"source","title":"8. Sai lầm thường gặp (Common Mistakes)","markdown":"## 8. Sai lầm thường gặp (Common Mistakes)\n\n| # | Sai lầm | Tại sao sai | Cách đúng |\n|---|---|---|---|\n| 1 | Đặt FK 1:N ở phía 1 thay vì phía N | Phía 1 sẽ có nhiều giá trị (multivalued) → vi phạm 1NF | FK luôn ở phía **N**. Mỗi tuple bên N tham chiếu 1 tuple bên 1. |\n| 2 | Mapping M:N bằng cách đặt FK ở 1 trong 2 bảng | Vi phạm 1NF (FK phải multivalued) hoặc mất quan hệ | Bắt buộc tạo **bảng quan hệ riêng** với composite PK. |\n| 3 | Quên FK CASCADE cho weak entity | Khi xóa owner, weak entity không tự xóa → orphan tuples | `ON DELETE CASCADE` cho FK của weak entity. |\n| 4 | Multivalued attribute để chung bảng (vd `Phone` là cột) | Vi phạm 1NF — 1 cell có nhiều giá trị | Tách thành **bảng riêng**, PK = {entity_PK, attr}. |\n| 5 | Lẫn FK với PK | FK là tham chiếu, PK là định danh | EMPLOYEE.Ssn là PK; EMPLOYEE.Dno là FK. |\n| 6 | Dùng option 8B cho overlapping specialization | Sẽ duplicate entity ở nhiều bảng | Overlapping → dùng **8D** (flags) hoặc **8A** (multi relations). |\n| 7 | Dùng option 8C cho overlapping specialization | Type attribute đơn trị không biểu diễn được nhiều subclass | Overlapping → **8D** với Boolean flags. |\n| 8 | Quên surrogate key cho category với superclass khác key | Không có natural key chung | Tạo `Owner_id` (auto-id) làm PK của category. |\n| 9 | Composite attribute để chung 1 cột (vd `Name` thay vì `Fname/Minit/Lname`) | DBMS không truy vấn được component | Tách thành **simple component attributes**. |\n| 10 | Lưu derived attribute (vd `Age`) | Phải update mỗi khi thời gian trôi → bất tiện | Lưu `Bdate`, tính `Age = today - Bdate` khi cần. |\n| 11 | Không đổi tên attr trong recursive relationship | 2 vai trò không phân biệt được | Đổi tên: `Ssn` → `Super_ssn` cho FK self-reference. |\n| 12 | PK của bảng N:M là 1 trong 2 FK | Có thể duplicate (cùng employee làm cùng project nhiều giờ) | PK **luôn** là composite `{K1, K2}`. |\n| 13 | FK của weak entity dùng ON DELETE SET NULL | Weak entity không tồn tại nếu owner mất → SET NULL vô nghĩa | Dùng **ON DELETE CASCADE**. |\n| 14 | Step 7 N-ary, dùng PK = {tất cả n FK} bất kể cardinality | Sai khi 1 trong n entity có cardinality 1 | Bỏ FK đó ra khỏi PK (slide 71-74). |\n| 15 | Mapping shared subclass mà superclass có key khác nhau | Không có key chung → không thể tham chiếu | Phải dùng **category + surrogate key**, không phải shared subclass. |\n\n---\n\n","file":"materials/DB-Chapter4.md","section":9},{"id":"c4-10","group":"c4","kind":"source","title":"9. Bài tập tự luyện có lời giải","markdown":"## 9. Bài tập tự luyện có lời giải\n\n### Bài 1 (dễ — Step 1+2)\n\n**Đề:** Cho ER:\n- `STUDENT(Sid, Name, Class)` — entity mạnh\n- `THESIS(Title, Year, Grade)` — weak entity, owner = STUDENT, partial key = Title\n\nVẽ relational schema sau Step 1 + Step 2.\n\n<details><summary>Lời giải</summary>\n\n```\nSTUDENT(Sid, Name, Class)         PK = Sid\n\nTHESIS(Sid, Title, Year, Grade)   PK = {Sid, Title}\n                                  FK Sid → STUDENT.Sid (ON DELETE CASCADE)\n```\n</details>\n\n### Bài 2 (trung bình — Step 4 + Step 6)\n\n**Đề:** Cho ER:\n- `DEPARTMENT(Dno, Dname, Locations[multivalued])` — DEPARTMENT có nhiều địa điểm\n- `EMPLOYEE(Eid, Name)` — entity mạnh\n- 1 EMPLOYEE thuộc 1 DEPARTMENT (relationship `WORKS_FOR`, 1:N)\n\nVẽ relational schema đầy đủ.\n\n<details><summary>Lời giải</summary>\n\n```\nDEPARTMENT(Dno, Dname)            PK = Dno   (Step 1)\n\nDEPT_LOCATIONS(Dno, Location)     PK = {Dno, Location}   (Step 6)\n                                  FK Dno → DEPARTMENT.Dno\n\nEMPLOYEE(Eid, Name, Dno)          PK = Eid   (Step 1 + Step 4)\n                                  FK Dno → DEPARTMENT.Dno\n```\n\n**Giải thích:**\n- DEPARTMENT có Locations multivalued → tách thành DEPT_LOCATIONS (Step 6).\n- WORKS_FOR là 1:N (DEPARTMENT 1 — EMPLOYEE N) → FK Dno đặt ở EMPLOYEE (phía N) (Step 4).\n</details>\n\n### Bài 3 (trung bình — Step 5 với recursive)\n\n**Đề:** Cho ER:\n- `PART(PartNo, Name)` — entity mạnh\n- Recursive M:N relationship `COMPRISE(Quantity)` trên PART (1 part có nhiều part con, 1 part con thuộc nhiều part)\n\nVẽ relational schema.\n\n<details><summary>Lời giải</summary>\n\n```\nPART(PartNo, Name)              PK = PartNo\n\nCOMPRISE(MajorPart, MinorPart, Quantity)\n                                PK = {MajorPart, MinorPart}\n                                FK MajorPart → PART.PartNo\n                                FK MinorPart → PART.PartNo\n```\n\n**Giải thích:**\n- M:N → bảng riêng (Step 5).\n- Recursive → đổi tên `PartNo` thành `MajorPart` và `MinorPart` để phân biệt 2 vai trò (Step 5 + slide 63-65).\n</details>\n\n### Bài 4 (khó — Step 8)\n\n**Đề:** Cho EER:\n- `EMPLOYEE(Ssn, Name, Salary)` — superclass\n- Specialization `{TEACHER, ADMIN}` — disjoint, partial. Có nhân viên không phải teacher cũng không phải admin.\n  - `TEACHER(SubjectArea)`\n  - `ADMIN(OfficeNum)`\n\nVẽ relational schema theo cả **2 options** phù hợp. Giải thích vì sao không dùng các options còn lại.\n\n<details><summary>Lời giải</summary>\n\n**Vì là disjoint + partial:**\n- ✅ **Option 8A** (linh hoạt, hỗ trợ partial)\n- ✅ **Option 8C** (single relation với type attribute, hỗ trợ disjoint + partial)\n- ❌ Option 8B: chỉ dùng cho **total** — không phù hợp.\n- ❌ Option 8D: dùng cho overlapping — overkill cho disjoint.\n\n**Option 8A:**\n```\nEMPLOYEE(Ssn, Name, Salary, JobType)\nTEACHER(Ssn, SubjectArea)         FK Ssn → EMPLOYEE.Ssn\nADMIN(Ssn, OfficeNum)             FK Ssn → EMPLOYEE.Ssn\n```\n\n**Option 8C:**\n```\nEMPLOYEE(Ssn, Name, Salary, JobType, SubjectArea, OfficeNum)\n```\n- `JobType ∈ {'Teacher', 'Admin', NULL}`.\n- Nhân viên không phải teacher/admin → JobType = NULL, SubjectArea & OfficeNum đều NULL.\n- Teacher → SubjectArea có giá trị, OfficeNum NULL.\n- Admin → OfficeNum có giá trị, SubjectArea NULL.\n\n**So sánh:** 8A: 3 bảng, ít NULL, nhiều JOIN khi truy vấn. 8C: 1 bảng, nhiều NULL, truy vấn đơn giản.\n</details>\n\n### Bài 5 (khó — Step 9 với surrogate key)\n\n**Đề:** Cho EER:\n- 3 superclass: `INDIVIDUAL(Cmnd)`, `BUSINESS(Tax_id)`, `FOREIGNER(Passport)` — key khác nhau.\n- Category `CUSTOMER` = INDIVIDUAL ∪ BUSINESS ∪ FOREIGNER.\n- Relationship `BUYS` (M:N) giữa CUSTOMER và `PRODUCT(Pid, Pname)`.\n\nVẽ relational schema.\n\n<details><summary>Lời giải</summary>\n\n```\nINDIVIDUAL(Cmnd, Name, Customer_id)\n                       ↑ FK → CUSTOMER.Customer_id\nBUSINESS(Tax_id, BName, Customer_id)\n                        ↑ FK → CUSTOMER.Customer_id\nFOREIGNER(Passport, Country, Customer_id)\n                            ↑ FK → CUSTOMER.Customer_id\n\nCUSTOMER(Customer_id)   ← surrogate key (auto-id)\n\nPRODUCT(Pid, Pname)\n\nBUYS(Customer_id, Pid, Date, Quantity)\n       PK = {Customer_id, Pid}\n       FK Customer_id → CUSTOMER.Customer_id\n       FK Pid → PRODUCT.Pid\n```\n\n**Giải thích:**\n- 3 superclass có key khác nhau (Cmnd vs Tax_id vs Passport) → cần **surrogate key** `Customer_id` cho CUSTOMER (Step 9 — slide 87).\n- Mỗi superclass thêm cột `Customer_id` để link lên CUSTOMER.\n- BUYS là M:N → bảng riêng với PK composite (Step 5).\n</details>\n\n---\n\n","file":"materials/DB-Chapter4.md","section":10},{"id":"c4-11","group":"c4","kind":"source","title":"10. Câu Hỏi Ôn Tập (từ slide gốc + đề cương)","markdown":"## 10. Câu Hỏi Ôn Tập (từ slide gốc + đề cương)\n\nPDF chương 4 không có exercise riêng. Câu hỏi tự luận điển hình:\n\n1. Phân biệt Schema và Instance qua 1 ví dụ trên COMPANY.\n2. Giải thích Entity Integrity và Referential Integrity. Cho ví dụ vi phạm mỗi loại.\n3. Cho relation `CAR(State, Reg#, SerialNo, Make, Model, Year)`. Liệt kê 3 superkey và 2 candidate key.\n4. Khi xóa 1 row trong DEPARTMENT có FK tham chiếu từ EMPLOYEE, có thể chọn action nào? Giải thích.\n5. **(Quan trọng — y format thi)** Cho ER diagram COMPANY, áp dụng 9 step để vẽ relational schema kết quả.\n6. **(Quan trọng)** Cho specialization {SECRETARY, ENGINEER, TECHNICIAN} disjoint partial của EMPLOYEE. Vẽ relational schema theo cả 4 options 8A, 8B, 8C, 8D. So sánh ưu nhược điểm.\n7. **(Quan trọng)** Cho category OWNER = PERSON ∪ BANK ∪ COMPANY (key khác nhau). Vẽ relational schema, giải thích vì sao cần surrogate key.\n8. Cho recursive 1:N SUPERVISION trên EMPLOYEE. Mapping thành relation thế nào?\n\n---\n\n","file":"materials/DB-Chapter4.md","section":11},{"id":"c4-12","group":"c4","kind":"source","title":"11. Đáp án Tự kiểm tra","markdown":"## 11. Đáp án Tự kiểm tra\n\n### §1 (câu 1-6)\n\n**1.** STUDENT(Name, Ssn, Phone, GPA): `Degree = 4`. `dom(GPA)` tùy thang điểm, vd `{x ∈ ℝ | 0.0 ≤ x ≤ 4.0}` (thang Mỹ) hoặc `{x | 0 ≤ x ≤ 10}` (thang VN).\n\n**2.** **Superkey** = bất kỳ tập attribute đảm bảo unique (có thể có thừa). **Candidate Key** = superkey tối thiểu. **Primary Key** = candidate key được chọn để gạch chân.\n\n**3.** Nếu chọn {State, Reg#} làm PK, {SerialNo} là **Secondary Key**.\n\n**4.** Entity Integrity: `t[PK] ≠ NULL` ∀ tuple t. Quan trọng vì PK dùng để định danh — NULL = \"không biết là ai\" = vô nghĩa.\n\n**5.** **CÓ** thể NULL (slide 22 case 2). Khi nhân viên là sếp cao nhất (CEO), không có ai supervise → Super_ssn = NULL. Hợp lệ vì Super_ssn không phải part of PK.\n\n**6.** 4 options: **REJECT** (hủy), **CASCADE** (xóa luôn EMPLOYEE), **SET NULL** (đặt EMPLOYEE.DNO = NULL), **custom routine**.\n\n### §3 (câu 7-14)\n\n**7.** **Step 1** (regular entity): PK = key của entity (1 attribute hoặc composite). **Step 2** (weak entity): PK = `{owner_PK, partial_key}` — composite, kết hợp với owner.\n\n**8.** Trong COMPANY, mỗi DEPARTMENT **bắt buộc** có 1 manager (total participation phía DEPARTMENT). Slide 47 nói: *\"better to choose total participation\"* → đặt FK ở DEPARTMENT (DEPARTMENT.MgrSsn → EMPLOYEE.Ssn).\n\n**9.** Vì M:N có thể có nhiều quan hệ giữa cùng cặp (E1, E2). Nếu đặt FK trong E1 hoặc E2, FK đó phải multivalued — vi phạm 1NF. → **Bắt buộc** tách thành bảng riêng có PK composite {K1, K2}.\n\n**10.** Multivalued `Locations` của DEPARTMENT → bảng riêng `DEPT_LOCATIONS(Dnumber, Dlocation)` với PK = {Dnumber, Dlocation}, FK Dnumber → DEPARTMENT.Dnumber.\n\n**11.** FK gọi là `Super_ssn` (đổi tên từ `Ssn`). Đổi tên vì cùng tham chiếu đến EMPLOYEE.Ssn nhưng đại diện cho **role khác** (sếp).\n\n**12.** 4 options:\n- **8A** (Multiple — superclass + subclasses): linh hoạt, mọi case.\n- **8B** (Subclass only): total + disjoint; bỏ superclass.\n- **8C** (Single + type attribute): disjoint, có cột type chỉ subclass.\n- **8D** (Single + Boolean flags): overlapping.\n\n**13.** PART → {MANUFACTURED, PURCHASED} **overlapping** → dùng **8D** (Boolean flags MFlag, PFlag) hoặc **8A** (3 bảng riêng). Không dùng 8B (overlap → duplicate); không dùng 8C (overlap không biểu diễn bằng 1 type attr đơn trị).\n\n**14.** Khi superclass của category có **key khác nhau** (vd PERSON.Ssn vs BANK.BName vs COMPANY.CName) — không thể chọn key của bất kỳ superclass nào làm PK của category. → Tạo surrogate key mới (vd `Owner_id`), mỗi superclass thêm column FK Owner_id.\n\n---\n\n","file":"materials/DB-Chapter4.md","section":12},{"id":"c4-13","group":"c4","kind":"source","title":"12. Mối Quan Hệ Với Các Chương Khác — Liên kết Lab/BTL","markdown":"## 12. Mối Quan Hệ Với Các Chương Khác — Liên kết Lab/BTL\n\n| Chương | Liên hệ với chương 4 |\n|---|---|\n| **Chương 1 — Architecture** | Phần \"Logical Design\" trong 3-Schema. |\n| **Chương 2 — ER Model** | **Input** của chương 4. Step 1-7 mapping ER. |\n| **Chương 3 — EER Model** | Step 8-9 mapping EER. |\n| **Chương 5 — Relational Algebra** | Truy vấn trên relational schema được tạo từ chương 4. |\n| **Chương 6 — SQL** | `CREATE TABLE` với PK, FK, constraint = **cài đặt thực tế** relational schema. `ON DELETE CASCADE/SET NULL` = slide 28. |\n| **Chương 7 — FD & Normalization** | Sau khi mapping, kiểm tra schema có đúng 3NF/BCNF không. |\n| **Chương 8 — Storage & Indexing** | Physical Design — sau Logical Design. |\n\n| Hoạt động | Liên hệ |\n|---|---|\n| **BTL1** (`BTL1_DB_Lab/`) | **Đề bài chính**: cho miniworld, vẽ ER/EER → mapping sang relational schema (chương 4) → SQL. **Chương 4 là quan trọng nhất cho BTL1.** |\n| **BTL2** (`BTL2_DB_Lab/`) | Cài đặt thực tế trên DBMS với toàn bộ FK constraint. |\n| **Lab 1, 2** | Tập viết SQL cho schema được mapping theo chương 4. |\n\n---\n\n","file":"materials/DB-Chapter4.md","section":13},{"id":"c4-14","group":"c4","kind":"source","title":"13. Phụ lục — Mapping 90 slide → Section","markdown":"## 13. Phụ lục — Mapping 90 slide → Section\n\n| Slide | Nội dung | Section |\n|---:|---|---|\n| 1 | Chapter title | Header |\n| 2, 3, 29, 36, 89 | Outline (5 slide) | §0.4 |\n| 4 | Section overview Relational Data Model | §1.2 |\n| 5 | Codd 1970 | §1.3 |\n| 6 | Relational data model + Relation schema | §1.4 |\n| 7 | Degree, Domain | §1.5 |\n| 8 | Tuple, Cardinality, Database schema (COMPANY) | §1.6 |\n| 9 | Relation r, n-tuples | §1.7 |\n| 10 | 6 key concepts review | §1.8 |\n| 11 | Relation as table — 4 properties | §1.9 |\n| 12 | STUDENT example | §1.10 |\n| 13 | Formal vs Informal terms | §1.11 |\n| 14 | 4 integrity constraints overview | §1.12 |\n| 15 | NULL value | §1.12 |\n| 16 | Superkey + Key | §1.13 |\n| 17 | CAR — candidate, primary, secondary | §1.13 |\n| 18 | CAR with sample data | §1.13 |\n| 19 | Entity Integrity + Database Schema | §1.14 |\n| 20 | Referential Integrity definition | §1.15 |\n| 21 | DEPARTMENT-EMPLOYEE FK example | §1.16 |\n| 22 | FK can be NULL | §1.17 |\n| 23 | COMPANY full referential integrity | §1.18 |\n| 24 | Semantic / state / transition constraints | §1.19 |\n| 25 | INSERT/DELETE/MODIFY overview | §1.20 |\n| 26 | Insertion details | §1.20 |\n| 27 | Deletion + Modification | §1.20 |\n| 28 | Actions on integrity violation | §1.20 |\n| 30 | 3 main phases | §2.2 |\n| 31 | Database Design Process diagram | §2.3 |\n| 32 | Logical Design highlighted | §2.3 |\n| 33 | Logical = Mapping + Normalization | §2.4 |\n| 34 | COMPANY ERD | §2.5 |\n| 35 | Result mapping COMPANY | §2.5 |\n| 37 | 9 steps overview | §3.1 |\n| 38 | Step 1 highlighted | §3.1 |\n| 39 | Step 1 — Regular Entity definition | §3.2 |\n| 40 | COMPANY ERD with regular entities highlighted | §3.2 |\n| 41 | EMPLOYEE/DEPARTMENT/PROJECT after Step 1 | §3.2 |\n| 42 | Step 2 highlighted | §3.3 |\n| 43 | Step 2 — Weak Entity rule | §3.3 |\n| 44 | DEPENDENT in ER (Owner's PK + Partial key) | §3.3 |\n| 45 | DEPENDENT after Step 2 | §3.3 |\n| 46 | Step 3 highlighted | §3.4 |\n| 47 | Step 3 — Foreign key approach | §3.4 |\n| 48 | Step 3 — Merged relation approach | §3.4 |\n| 49 | Step 3 — Cross-reference approach | §3.4 |\n| 50 | Step 3 — combined diagram | §3.4 |\n| 51 | MANAGES highlighted in COMPANY | §3.4 |\n| 52 | DEPARTMENT after Step 3 (MgrSsn FK) | §3.4 |\n| 53 | Step 4 highlighted | §3.5 |\n| 54 | Step 4 — FK + relationship relation approaches | §3.5 |\n| 55 | Step 4 diagrams | §3.5 |\n| 56 | WORKS_FOR/CONTROLS/SUPERVISION highlighted | §3.5 |\n| 57 | COMPANY after Step 4 | §3.5 |\n| 58 | BORROWER-BOOK example | §3.5 |\n| 59 | Step 5 highlighted | §3.6 |\n| 60 | Step 5 — M:N rule | §3.6 |\n| 61 | WORKS_ON highlighted | §3.6 |\n| 62 | WORKS_ON after Step 5 | §3.6 |\n| 63 | Recursive relationships overview | §3.6a |\n| 64 | Example MARRY | §3.6a |\n| 65 | Examples SUPERVISE + COMPRISE | §3.6a |\n| 66 | Step 6 highlighted | §3.7 |\n| 67 | Step 6 — Multivalued rule | §3.7 |\n| 68 | DEPT_LOCATIONS in ER | §3.7 |\n| 69 | COMPANY full mapping result | §3.7 + §4 |\n| 70 | Step 7 — N-ary rule | §3.8 |\n| 71 | SUPPLY ternary N:N:N | §3.8 |\n| 72 | SUPPLY ternary 1:N:N | §3.8 |\n| 73 | SUPPLY ternary 1:1:N | §3.8 |\n| 74 | SUPPLY ternary 1:1:1 | §3.8 |\n| 75 | ER ↔ Relational correspondence table | §3.9 |\n| 76 | Step 8 highlighted | §3.10 |\n| 77 | Step 8 — 4 options list | §3.10 |\n| 78 | Option 8A + 8B detail | §3.10.1, §3.10.2 |\n| 79 | Example 8A (EMPLOYEE) | §3.10.1 |\n| 80 | Example 8B (VEHICLE→CAR/TRUCK) | §3.10.2 |\n| 81 | Option 8C + 8D detail | §3.10.3, §3.10.4 |\n| 82 | Example 8C (EMPLOYEE single) | §3.10.3 |\n| 83 | Example 8D (PART with flags) | §3.10.4 |\n| 84 | Shared subclass mapping | §3.10.6 |\n| 85 | UNIVERSITY lattice | §3.10.6 |\n| 86 | UNIVERSITY mapping result | §3.10.6 |\n| 87 | Step 9 — Union + Surrogate key | §3.11 |\n| 88 | OWNER mapping example | §3.11 |\n| 90 | Q & A | (slide kết) |\n\n---\n\n","file":"materials/DB-Chapter4.md","section":14},{"id":"c4-15","group":"c4","kind":"source","title":"14. Bảng so sánh nguồn (Prompt 3 audit table)","markdown":"## 14. Bảng so sánh nguồn (Prompt 3 audit table)\n\n| Section / Nội dung | A (Claude pass1) | B (CO2013) | Nguồn được chọn |\n|---|---|---|---|\n| Cấu trúc | Concept-based | Slide-by-slide chi tiết | **B làm khung** + insight A |\n| 4 options 8A/8B/8C/8D + decision matrix | **CÓ** đầy đủ với khi nào dùng | Có cơ bản | **A** decision matrix |\n| Recursive (MARRY/SUPERVISE/COMPRISE) | 3 examples + code mapping | có | **A∪B** |\n| §4 COMPANY full mapping result (PK + FK list) | KHÔNG | **CÓ** | **B** |\n| 14 câu tự kiểm tra + đáp án chi tiết | **A** | có ít hơn | **A** |\n| Analogy đời thường | 5 (CCCD, weak=\"đứa con không CCCD\", surrogate=auto-id, …) | ít hơn | **A** |\n| Bảng glossary cột COMPANY | KHÔNG (45 hàng) | KHÔNG | **mới sinh** với COMPANY |\n| TH2 Bảng tra nhanh | Không | Không | **tự sinh** (20 tình huống) |\n| TH3 Sai lầm thường gặp | Không | Không | **tự sinh** (15 sai lầm) |\n| TH4 Bài tập có lời giải | Không | Không | **tự sinh** (5 bài) |\n| Phụ lục 90 slide map | Không | Không | **tự sinh** |\n\n---\n\n","file":"materials/DB-Chapter4.md","section":15},{"id":"c4-16","group":"c4","kind":"source","title":"15. Checklist tổng hợp cuối cùng","markdown":"## 15. Checklist tổng hợp cuối cùng\n\n### ✅ Checklist nội dung\n\n| Hạng mục | A | B | Bản tổng hợp | Yêu cầu |\n|---|---:|---:|---:|---|\n| Số section đánh số | 3 | 3 | 4 (thêm §4 COMPANY) | ≥ max | ✅ |\n| Số diagram | 20+ | 20+ | 22+ | ≥ max | ✅ |\n| Số ví dụ COMPANY/CAR/STUDENT/UNIVERSITY | 12 | 12 | 14 | ≥ max | ✅ |\n| Số analogy đời thường | 5 | 3 | 5 | ≥ max | ✅ |\n| Số đoạn SQL/code | 1 | 2 | 3 | ≥ max | ✅ |\n| Số quy tắc mapping | 9 | 9 | 9 | ≥ max | ✅ |\n| Số thuật ngữ glossary | 45 | 40+ | **45 + cột COMPANY** | ≥ max | ✅ vượt |\n| Số câu tự kiểm tra | 14 | 12 | 14 | ≥ max | ✅ |\n| Mapping 90 slide → section | 0 | 0 | 90 | bắt buộc có | ✅ |\n\n### ✅ Checklist riêng cho TỰ HỌC\n\n| Hạng mục | Đạt? |\n|---|---|\n| Có **0.1 Prerequisite** (bảng concept ER+EER) | ✅ |\n| Có **0.2 Learning Outcomes** (8 outcome) | ✅ |\n| Có **0.3 Lộ trình đọc** | ✅ |\n| Có **§4 COMPANY full mapping result** (PK + FK list) | ✅ |\n| Có **Bảng tra nhanh §7** (20 tình huống) | ✅ |\n| Có **Sai lầm thường gặp §8** (15 sai lầm) | ✅ |\n| Có **5 Bài tập có lời giải đầy đủ** (§9) | ✅ |\n| Có **liên kết Lab/BTL** (§12) | ✅ |\n| Mọi concept khó có analogy | ✅ |\n| Mọi thuật ngữ lần đầu có VN | ✅ |\n| Có **Đáp án Tự kiểm tra** (§11) | ✅ |\n| Phụ lục mapping 90 slide → section (§13) | ✅ |\n| **Tự đánh giá: SV mất gốc đọc sẽ hiểu được?** | ✅ |\n\n---\n\n> **File này là bản TỔNG HỢP CUỐI CÙNG** cho Chương 4, ghép từ 2 nguồn:\n> 1. `_drafts/DB-Chapter4-claude-pass1.md` (bản A — Claude, sau Prompt 1)\n> 2. `_drafts/ch4_relational_data_model_mapping_notes.md` (bản B — slide-by-slide chi tiết + COMPANY full result)\n>\n> Sau finalize, có thể xóa 2 file `_drafts/` (đã merge xong).\n","file":"materials/DB-Chapter4.md","section":16},{"id":"guide-4","group":"c4","kind":"guide","title":"Relational mapping","markdown":"# 04 · Từ ER/EER đến bảng, khóa và ràng buộc\n\n> Đọc cùng **DB-Chapter4.md**. Một mapping tốt cần chỉ ra cả điều đã bảo đảm bằng DDL và điều còn phải kiểm tra thêm.\n\n![Lược đồ quan hệ anime với khóa và bảng liên kết](../docs/assets/schema.svg)\n\n## Bảy bước ER mapping qua cùng một miniworld\n\n| ER construct | Bảng/cột tạo ra | Khóa/ràng buộc |\n|---|---|---|\n| Strong ANIME | `anime(anime_id,title,release_year)` | PK `anime_id` |\n| Weak EPISODE | `episode(anime_id,episode_no,...)` | PK ghép + owner FK |\n| 1:N viewer—watch list | FK `viewer_id` trong watch_list | NOT NULL nếu mỗi list phải có owner |\n| 1:1 quan hệ | FK ở một phía phù hợp nghiệp vụ | UNIQUE; NOT NULL nếu phía đó total |\n| M:N Has_genre | `anime_genre(anime_id,genre_id)` | PK cặp + 2 FK |\n| M:N Contains | `contains(list_id,anime_id,added_at)` | PK cặp; giữ thuộc tính quan hệ |\n| Multivalued phone | `account_phone(account_id,phone)` | PK cặp + owner FK |\n| N-ary relationship | Một bảng có khóa của các participant | Xác định candidate key từ cardinality/FD |\n\nVới quan hệ ternary, không tự động khẳng định cả ba FK là candidate key tối thiểu. Nếu nghiệp vụ nói với mỗi cặp supplier–part chỉ có một project thì cặp đó xác định project; phải xét các phụ thuộc trước khi chọn PK.\n\n## Vì sao FK thường ở phía N?\n\nMỗi watch list có đúng một owner, nên mỗi hàng list giữ một `viewer_id`. Nếu đặt `list_id` trong viewer, một viewer có nhiều list sẽ cần cột lặp hoặc danh sách trong ô. Khi FK NOT NULL và được enforce, mỗi list chắc chắn trỏ tới một viewer hợp lệ.\n\nNhưng quy tắc “mỗi viewer có ít nhất một list” là chiều ngược lại. FK trong list không bắt viewer phải được tham chiếu. Cần kiểm tra tồn tại hoặc cơ chế nghiệp vụ bổ sung.\n\n## Khóa: unique và minimal là hai bước\n\nVới ENROLLMENT(StudentID, CourseID, Semester, Grade), nếu một sinh viên có thể học lại cùng môn ở kỳ khác thì `(StudentID, CourseID)` không đủ duy nhất. Giả sử mỗi kỳ chỉ có một lần đăng ký, `(StudentID, CourseID, Semester)` là candidate key. Thêm `Grade` vào vẫn là superkey nhưng không còn tối thiểu.\n\nPrimary key là một candidate key được chọn. Các candidate key còn lại thường gọi **alternate keys**. “Secondary key” đôi khi có nghĩa khóa tìm kiếm không duy nhất trong ngữ cảnh index, nên không dùng thuật ngữ đó như đồng nghĩa tuyệt đối với alternate key.\n\n## Total ở phía M:N cần kiểm tra riêng\n\n```sql\n-- SQLite: tìm anime vi phạm yêu cầu ít nhất một genre.\nSELECT a.anime_id, a.title\nFROM anime AS a\nWHERE NOT EXISTS (\n SELECT 1 FROM anime_genre AS ag WHERE ag.anime_id=a.anime_id\n);\n```\n\nTrên fixture anime, kết quả rỗng. Nếu thêm anime mới nhưng chưa thêm anime_genre, query trả hàng vi phạm. Một row-level CHECK thông thường không giải quyết được điều kiện nhiều bảng này; SQLite không cho subquery trong CHECK. Với hệ hỗ trợ thích hợp có thể dùng deferred constraint trigger; với SQLite cần gom thao tác nghiệp vụ vào transaction rồi kiểm tra trước COMMIT.\n\n## ON DELETE không phải “cứ CASCADE là tốt”\n\nXóa watch list có thể cascade xóa Contains vì hàng liên kết không còn nghĩa khi mất list. Xóa genre đang được dùng có thể nên bị chặn để người quản trị quyết định lại phân loại. `SET NULL` chỉ có nghĩa khi cột FK cho phép NULL và nghiệp vụ chấp nhận mất liên kết. Phân biệt `DROP ... CASCADE` (đối tượng schema) với `ON DELETE CASCADE` (hàng dữ liệu).\n\n## Bài tập\n\n1. M:N Produced_by ánh xạ thành bảng gì? Đặt `StudioID` duy nhất trong ANIME có đủ không?\n2. Vì sao PK episode phải có AnimeID khi số tập chỉ duy nhất trong một anime?\n3. Quan hệ 1:1 dùng FK mà không có UNIQUE có còn bảo đảm 1:1 không?\n4. PK/FK đã enforce có chứng minh được mọi semantic constraint đều đúng không?\n\n<details><summary>Lời giải</summary>\n\n1. `produced_by(anime_id,studio_id)`, PK cặp; một cột đơn trong ANIME không biểu diễn được nhiều studio cho một anime.\n2. Hai anime đều có tập 1; khóa phải phân biệt hai owner.\n3. Không. Nhiều hàng có thể cùng tham chiếu một hàng cha.\n4. Không. Ví dụ total phía “1”, total phía M:N và total specialization cần kiểm tra riêng.\n\n</details>\n","file":"lessons/04-mapping.md"},{"id":"c5-00","group":"c5","kind":"source","title":"Chương 5: Đại Số Quan Hệ — Relational Algebra","markdown":"# Chương 5: Đại Số Quan Hệ — Relational Algebra\n\n> **Nguồn:** CO2013 Database Systems, HCMUT — Giảng viên: TS. Trần Minh Quang\n> **Giáo trình:** *Fundamentals of Database Systems*, 7th Edition — R. Elmasri & S. B. Navathe, Addison-Wesley, 2017\n> **File PDF gốc:** `Lectures/05_Relational Algebra.pdf` — **85 slide**\n> **Đã gộp slide Contents lặp:** slide **4, 5, 22, 32, 59, 76, 84** (cùng một mục lục, chỉ khác mục được highlight). Slide 85 là slide Q&A kết chương.\n\n---\n\n","file":"materials/DB-Chapter5.md","section":0},{"id":"c5-01","group":"c5","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nChương này đứng **ngay sau** Chương 4 (Relational Data Model & Mapping). Bạn cần đã quen các khái niệm sau — nhắc lại siêu ngắn để bạn không cần mở lại Chương 4:\n\n| Khái niệm | Nhắc lại 2-3 câu | Vì sao cần cho Chương 5? |\n|---|---|---|\n| **Relation (quan hệ/bảng)** | Bảng có schema cố định + tập tuple. Trong RA, là *set* các tuple — không cho 2 dòng giống hệt nhau. | RA biến đổi *bảng → bảng*. |\n| **Tuple (bộ)** | Một dòng = bộ giá trị thuộc các cột. | σ lọc tuple, ÷ kiểm tra tuple với mọi tuple khác. |\n| **Attribute (thuộc tính)** | Một cột. Có domain (kiểu dữ liệu) đi kèm. | π chiếu cột, type-compatible kiểm tra cột tương ứng. |\n| **Schema vs Instance** | Schema = cấu trúc; Instance = dữ liệu cụ thể tại 1 thời điểm. | Mọi ví dụ chương này chạy trên instance COMPANY. |\n| **Primary Key (PK)** | Định danh duy nhất một tuple. | π trên list chứa PK ⇒ không loại tuple. |\n| **Foreign Key (FK)** | Cột trỏ đến PK bảng khác. | JOIN ngầm dùng FK = PK. |\n| **Set theory (toán rời rạc)** | Hợp `∪`, giao `∩`, hiệu `−`, tích Descartes `×`, tập con `⊆`. | 4 phép trong nhóm \"Set Theory Operations\". |\n| **Boolean expression** | `AND`, `OR`, `NOT` + so sánh `= < > ≤ ≥ ≠`. | Selection condition trong σ và join condition trong ⋈. |\n\n> 💡 **Hiểu đơn giản — Relation là gì:** Hình dung một bảng Excel có header cố định (schema) và các dòng (instance). Khác Excel ở chỗ: trong RA, **không cho 2 dòng giống hệt nhau** (vì là set). SQL thì cho phép trùng (multiset) — đây sẽ là điểm khác biệt quan trọng giữa RA và SQL.\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\nHọc xong Chương 5, bạn có thể:\n\n1. **Đọc–hiểu** một biểu thức Đại số quan hệ (RA) bất kỳ và biết nó trả về tập tuple nào.\n2. **Viết** biểu thức RA cho các truy vấn cơ bản trên schema COMPANY: lọc, chiếu, kết, gom nhóm, tính tổng / trung bình.\n3. **Phân biệt 9 toán tử cốt lõi** + biến thể: σ, π, ρ, ∪, ∩, −, ×, ⋈ (theta / equi / natural), ÷, cộng với 𝓕 (aggregate), OUTER JOIN, OUTER UNION, recursive closure.\n4. **Vẽ** Query tree cho một biểu thức RA và đọc ngược lại.\n5. **So sánh** Relational Algebra (procedural — *cách lấy*) và Relational Calculus (non-procedural — *cái cần lấy*).\n6. **Nối RA ↔ SQL:** mỗi toán tử RA ứng với mệnh đề SQL nào (chuẩn bị Chương 6).\n\n### 0.3. Lộ trình đọc đề xuất\n\n| Section | Mức độ | Thời gian gợi ý | Ghi chú |\n|---|---|---|---|\n| 0. Trước khi bắt đầu | Bắt buộc | 10' | Đọc 1 lần cho ngữ cảnh |\n| 1. Unary (σ, π, ρ) | **CORE** | 30' | Phải nắm chắc — slide 9–21 |\n| 2. Set theory (∪, ∩, −, ×) | **CORE** | 25' | Ôn lại set theory toán rời rạc — slide 22–31 |\n| 3. Binary (JOIN, DIVISION, Query Tree) | **CORE** | 50' | Phần khó nhất — JOIN có 3 biến thể; slide 32–58 |\n| 4. Additional (Aggregate, OUTER JOIN, Recursive) | **CORE** + nâng cao | 30' | Aggregate hay ra thi — slide 59–75 |\n| 5. Relational Calculus | NÂNG CAO | 20' | Hiểu khái niệm, không bắt viết phức tạp — slide 76–85 |\n| Bảng tra nhanh + Sai lầm + Mini bài tập | Bắt buộc trước thi | 30' | Ôn cuối chương |\n\n**Tổng:** ~3 giờ tự học cho người mất gốc; ~1.5 giờ nếu đã ôn xong Chương 4.\n\n### 0.4. Lược đồ COMPANY dùng xuyên suốt\n\n```mermaid\nerDiagram\n    EMPLOYEE ||--o{ EMPLOYEE : \"supervises (Super_ssn)\"\n    DEPARTMENT ||--o{ EMPLOYEE : \"Dno → Dnumber\"\n    EMPLOYEE ||--o| DEPARTMENT : \"manages (Mgr_ssn)\"\n    DEPARTMENT ||--o{ DEPT_LOCATIONS : \"Dnumber\"\n    DEPARTMENT ||--o{ PROJECT : \"Dnum → Dnumber\"\n    EMPLOYEE ||--o{ WORKS_ON : \"Essn → Ssn\"\n    PROJECT ||--o{ WORKS_ON : \"Pno → Pnumber\"\n    EMPLOYEE ||--o{ DEPENDENT : \"Essn → Ssn\"\n\n    EMPLOYEE {\n      string Fname\n      string Minit\n      string Lname\n      string Ssn PK\n      date Bdate\n      string Address\n      string Sex\n      number Salary\n      string Super_ssn FK\n      int Dno FK\n    }\n    DEPARTMENT {\n      string Dname\n      int Dnumber PK\n      string Mgr_ssn FK\n      date Mgr_start_date\n    }\n    DEPT_LOCATIONS {\n      int Dnumber PK\n      string Dlocation PK\n    }\n    PROJECT {\n      string Pname\n      int Pnumber PK\n      string Plocation\n      int Dnum FK\n    }\n    WORKS_ON {\n      string Essn PK\n      int Pno PK\n      number Hours\n    }\n    DEPENDENT {\n      string Essn PK\n      string Dependent_name PK\n      string Sex\n      date Bdate\n      string Relationship\n    }\n```\n\n> 📊 **Đọc diagram này thế nào:** Mỗi box là 1 relation. PK gạch chân, FK đi vào quan hệ tham chiếu. EMPLOYEE.Super_ssn → EMPLOYEE.Ssn là **self-reference** (recursive — sếp của một nhân viên cũng là nhân viên).\n\n#### Instance EMPLOYEE (8 tuple — slide 7)\n\n| Fname | Minit | Lname | Ssn | Bdate | Address | Sex | Salary | Super_ssn | Dno |\n|---|---|---|---|---|---|---|---|---|---|\n| John | B | Smith | 123456789 | 1965-01-09 | 731 Fondren, Houston, TX | M | 30000 | 333445555 | 5 |\n| Franklin | T | Wong | 333445555 | 1955-12-08 | 638 Voss, Houston, TX | M | 40000 | 888665555 | 5 |\n| Alicia | J | Zelaya | 999887777 | 1968-01-19 | 3321 Castle, Spring, TX | F | 25000 | 987654321 | 4 |\n| Jennifer | S | Wallace | 987654321 | 1941-06-20 | 291 Berry, Bellaire, TX | F | 43000 | 888665555 | 4 |\n| Ramesh | K | Narayan | 666884444 | 1962-09-15 | 975 Fire Oak, Humble, TX | M | 38000 | 333445555 | 5 |\n| Joyce | A | English | 453453453 | 1972-07-31 | 5631 Rice, Houston, TX | F | 25000 | 333445555 | 5 |\n| Ahmad | V | Jabbar | 987987987 | 1969-03-29 | 980 Dallas, Houston, TX | M | 25000 | 987654321 | 4 |\n| James | E | Borg | 888665555 | 1937-11-10 | 450 Stone, Houston, TX | M | 55000 | NULL | 1 |\n\n#### Instance DEPARTMENT, DEPT_LOCATIONS, PROJECT, WORKS_ON, DEPENDENT (slide 8)\n\n**DEPARTMENT** (3 tuple):\n\n| Dname | Dnumber | Mgr_ssn | Mgr_start_date |\n|---|---|---|---|\n| Research | 5 | 333445555 | 1988-05-22 |\n| Administration | 4 | 987654321 | 1995-01-01 |\n| Headquarters | 1 | 888665555 | 1981-06-19 |\n\n**DEPT_LOCATIONS** (5 tuple):\n\n| Dnumber | Dlocation |\n|---|---|\n| 1 | Houston |\n| 4 | Stafford |\n| 5 | Bellaire |\n| 5 | Sugarland |\n| 5 | Houston |\n\n**PROJECT** (6 tuple):\n\n| Pname | Pnumber | Plocation | Dnum |\n|---|---|---|---|\n| ProductX | 1 | Bellaire | 5 |\n| ProductY | 2 | Sugarland | 5 |\n| ProductZ | 3 | Houston | 5 |\n| Computerization | 10 | Stafford | 4 |\n| Reorganization | 20 | Houston | 1 |\n| Newbenefits | 30 | Stafford | 4 |\n\n**WORKS_ON** (16 tuple):\n\n| Essn | Pno | Hours |\n|---|---|---|\n| 123456789 | 1 | 32.5 |\n| 123456789 | 2 | 7.5 |\n| 666884444 | 3 | 40.0 |\n| 453453453 | 1 | 20.0 |\n| 453453453 | 2 | 20.0 |\n| 333445555 | 2 | 10.0 |\n| 333445555 | 3 | 10.0 |\n| 333445555 | 10 | 10.0 |\n| 333445555 | 20 | 10.0 |\n| 999887777 | 30 | 30.0 |\n| 999887777 | 10 | 10.0 |\n| 987987987 | 10 | 35.0 |\n| 987987987 | 30 | 5.0 |\n| 987654321 | 30 | 20.0 |\n| 987654321 | 20 | 15.0 |\n| 888665555 | 20 | NULL |\n\n**DEPENDENT** (7 tuple):\n\n| Essn | Dependent_name | Sex | Bdate | Relationship |\n|---|---|---|---|---|\n| 333445555 | Alice | F | 1986-04-05 | Daughter |\n| 333445555 | Theodore | M | 1983-10-25 | Son |\n| 333445555 | Joy | F | 1958-05-03 | Spouse |\n| 987654321 | Abner | M | 1942-02-28 | Spouse |\n| 123456789 | Michael | M | 1988-01-04 | Son |\n| 123456789 | Alice | F | 1988-12-30 | Daughter |\n| 123456789 | Elizabeth | F | 1967-05-05 | Spouse |\n\n---\n\n","file":"materials/DB-Chapter5.md","section":1},{"id":"c5-02","group":"c5","kind":"source","title":"Tổng quan — Relational Algebra là gì? (slide 2–3)","markdown":"## Tổng quan — Relational Algebra là gì? (slide 2–3)\n\n- **Relational Algebra** là tập các phép toán cơ bản trên relational model. Mỗi phép nhận 1–2 relation làm input và trả ra **1 relation mới**.\n- Tính chất quan trọng nhất: **closed (đóng)** — input là relation, output cũng là relation. Nhờ vậy có thể *nest* các phép vào nhau, tạo thành **relational algebra expression**.\n- 4 nhóm toán tử (slide 3):\n  1. **Unary:** SELECT (σ), PROJECT (π), RENAME (ρ)\n  2. **Set theory:** UNION (∪), INTERSECTION (∩), DIFFERENCE (−), CARTESIAN PRODUCT (×)\n  3. **Binary:** JOIN (⋈) + biến thể (theta, equi, natural), DIVISION (÷)\n  4. **Additional:** OUTER JOINS, OUTER UNION, AGGREGATE FUNCTIONS (SUM, COUNT, AVG, MIN, MAX)\n\n> 💡 **Hiểu đơn giản — vì sao \"closed\" quan trọng:** Giống cộng/trừ/nhân/chia số nguyên — input số nguyên, output số nguyên, nên ghép được. Ở đây: input relation, output relation, nên ghép vào nhau thành biểu thức phức như `π_…(σ_…(R) ⋈ S)`.\n\n---\n\n","file":"materials/DB-Chapter5.md","section":2},{"id":"c5-03","group":"c5","kind":"source","title":"1. Unary Relational Operations — Toán tử quan hệ một ngôi","markdown":"## 1. Unary Relational Operations — Toán tử quan hệ một ngôi\n\n### 1.1. SELECT (σ — sigma) — Lọc tuple theo điều kiện\n\n#### Tại sao có SELECT? (Motivation)\n\nBạn có 8 nhân viên, nhưng chỉ cần \"những ai làm phòng 4\". Nếu không có SELECT, bạn phải duyệt tay từng tuple. SELECT làm việc đó *chính thức* trên *quan hệ tổng quát*.\n\n> 💡 **Hiểu đơn giản:** SELECT giống *Filter* trên Excel: bấm vào header cột → chọn điều kiện → ẩn dòng không khớp. Kết quả vẫn có schema giống bảng cũ, chỉ ít hàng hơn.\n\n#### Khái niệm và lý thuyết (slide 9–11)\n\n- σ **denoted by σ (sigma)** — lọc *subset of tuples* dựa trên **selection condition** (điều kiện Boolean).\n- **Dạng tổng quát:** `σ_<selection condition>(R)`\n  - Tuple thỏa điều kiện → giữ lại; không thỏa → loại.\n  - Schema kết quả **giống schema R**.\n- Ví dụ slide 9:\n  - `σ Dno=4 (EMPLOYEE)` — nhân viên phòng 4.\n  - `σ Salary>30000 (EMPLOYEE)` — nhân viên lương > 30 000.\n\n#### Tính chất quan trọng (slide 11)\n\n- **Giao hoán (commutative):** `σ_<c1>(σ_<c2>(R)) = σ_<c2>(σ_<c1>(R))`\n- **Cascade rút gọn được:** `σ_<c1>(σ_<c2>(σ_<c3>(R))) = σ_<c1> AND <c2> AND <c3>(R)` — viết lại thành 1 σ với AND.\n- **|σ_C(R)| ≤ |R|** — số tuple kết quả ≤ tuple gốc.\n\n> 💡 **Tại sao tính giao hoán quan trọng — query optimizer:** DBMS có thể đổi thứ tự điều kiện để lọc sớm điều kiện *mạnh* (loại nhiều tuple) trước, giảm chi phí.\n\n#### Ví dụ minh họa trên relation R giả định (slide 12)\n\n```\nR                   σ_A≤4(R)\n| A | B | C |       | A | B | C |\n|---|---|---|       |---|---|---|\n| 1 | 2 | 3 |       | 1 | 2 | 3 |\n| 4 | 5 | 6 |       | 4 | 5 | 6 |\n| 1 | 2 | 7 |       | 1 | 2 | 7 |\n| 8 | 4 | 5 |\n```\n\nTuple `(8,4,5)` bị loại vì `A=8` không ≤ 4.\n\n#### Ví dụ trên COMPANY\n\n> 💡 **Ví dụ 1.1 — Lọc nhân viên phòng 5 lương > 30 000:**\n> `σ Dno=5 AND Salary>30000 (EMPLOYEE)`\n>\n> **Bước 1:** Lọc Dno=5 → Smith (30 000), Wong (40 000), Narayan (38 000), English (25 000).\n> **Bước 2:** Trong đó lọc Salary > 30 000 → **Wong (40 000), Narayan (38 000)**.\n> **Kết quả:** 2 tuple.\n\n#### Ví dụ phức tạp — slide 17(a)\n\n> 💡 **Slide 17(a):** `σ (Dno=4 AND Salary>25000) OR (Dno=5 AND Salary>30000) (EMPLOYEE)`\n>\n> Kết quả 3 tuple: **Wong** (Dno=5, 40 000), **Wallace** (Dno=4, 43 000), **Narayan** (Dno=5, 38 000).\n\n#### Tương đương SQL\n\n```sql\nSELECT *\nFROM   EMPLOYEE\nWHERE  Dno = 5 AND Salary > 30000;\n```\n\n`WHERE` trong SQL **chính là** σ trong RA — mệnh đề tương ứng đầu tiên giữa hai ngôn ngữ.\n\n> 📝 **Tóm lại 1.1:**\n> - σ_C(R) = filter theo dòng, schema không đổi, |kết quả| ≤ |gốc|.\n> - Giao hoán + kết hợp → cascade gộp thành σ AND.\n>\n> **Một câu ghi nhớ:** \"σ là *filter cắt theo chiều ngang*.\"\n\n> ❓ **Tự kiểm tra 1.1:**\n> 1. Viết RA chọn nhân viên nữ (Sex='F') có lương ≥ 25 000.\n> 2. So sánh `σ A=1 OR A=4 (R)` và `σ A=1 (R) ∪ σ A=4 (R)` — bằng nhau không?\n> 3. Vì sao σ là *filter cắt hàng*, không phải *cắt cột*?\n\n---\n\n### 1.2. PROJECT (π — pi) — Chiếu lấy một số cột\n\n#### Tại sao có PROJECT?\n\nSau khi đã lọc hàng cần, nhiều khi bạn không cần *toàn bộ 10 cột* mà chỉ cần Fname, Lname, Salary để in báo cáo. PROJECT làm việc cắt cột *chính thức + sạch sẽ*.\n\n> 💡 **Hiểu đơn giản:** PROJECT = ẩn cột trong Excel để in cho gọn. Khác Excel ở chỗ: nếu sau khi ẩn cột mà có 2 dòng giống hệt → RA *bắt buộc gộp* (vì kết quả là set).\n\n#### Khái niệm và lý thuyết (slide 13–15)\n\n- π **denoted by π (pi)** — giữ một số *columns (attributes)*, bỏ cột còn lại. Tạo *vertical partitioning* (phân hoạch dọc).\n- **Dạng tổng quát:** `π_<attribute list>(R)`\n  - Kết quả chỉ chứa các attribute trong list, **theo đúng thứ tự** trong list.\n  - **Loại tuple trùng** (duplicate elimination) — vì set không cho trùng.\n- Ví dụ slide 13: `π Lname,Fname,Salary (EMPLOYEE)`.\n\n#### Tính chất (slide 15)\n\n- |π_L(R)| ≤ |R|. **Bằng** nếu L chứa một **key** của R.\n- **Không giao hoán:** `π_L1(π_L2(R)) = π_L1(R)` chỉ khi L2 ⊇ L1.\n\n> 💡 **Tại sao không giao hoán:** Bạn không thể chiếu {Salary} trước rồi {Fname, Lname} sau, vì sau bước 1 đã không còn Fname trong bảng. Phải làm theo thứ tự \"list nhiều cột trước\".\n\n#### Ví dụ minh họa (slide 16)\n\n```\nR                       π_A,B(R)\n| A | B | C |           | A | B |\n|---|---|---|           |---|---|\n| 1 | 2 | 3 |           | 1 | 2 |\n| 4 | 5 | 6 |           | 4 | 5 |\n| 1 | 2 | 7 |           | 8 | 4 |\n| 8 | 4 | 5 |\n```\n\nTuple thứ 1 và 3 đều là (1, 2) sau khi bỏ cột C → loại trùng → 3 tuple thay vì 4.\n\n#### Ví dụ slide 17 trên COMPANY\n\n> 💡 **Slide 17(b):** `π Lname,Fname,Salary (EMPLOYEE)` = **8 tuple**.\n> *Vì sao đủ 8 tuple, không loại trùng?* Vì bộ (Lname, Fname, Salary) duy nhất trong instance này — không có 2 nhân viên cùng họ tên + lương.\n\n> 💡 **Slide 17(c):** `π Sex,Salary (EMPLOYEE)` = **7 tuple**.\n> Sau projection, hai nhân viên (F, 25 000) là Zelaya và English → loại trùng còn 1.\n\n#### Tương đương SQL\n\n```sql\nSELECT DISTINCT Lname, Fname, Salary FROM EMPLOYEE;\n```\n\n> ⚠️ **Khác biệt cốt lõi RA vs SQL:** RA = set (không trùng). SQL = multiset (trùng được, trừ khi `DISTINCT`). Hay ra đề thi.\n\n> 📝 **Tóm lại 1.2:**\n> - π_L(R) = filter theo cột, loại trùng tự động.\n> - |kết quả| ≤ |gốc|; bằng khi L chứa key.\n> - Không giao hoán.\n>\n> **Một câu ghi nhớ:** \"π là *filter cắt theo chiều dọc*, kèm bước loại trùng bắt buộc.\"\n\n> ❓ **Tự kiểm tra 1.2:**\n> 1. `π_Dno (EMPLOYEE)` có bao nhiêu tuple?\n> 2. Vì sao `π_Salary (EMPLOYEE)` có thể có ít tuple hơn |EMPLOYEE|?\n> 3. `π_A,B (π_A,B,C (R)) = π_A,B (R)` đúng hay sai?\n\n---\n\n### 1.3. Relational Algebra Expressions — Hai cách viết (slide 18–19)\n\nCó hai cách viết tương đương cho cùng một query phức:\n\n**Cách 1 — Single nested expression:**\n\n```\nπ Fname,Lname,Salary (σ Dno=5 (EMPLOYEE))\n```\n\n**Cách 2 — Sequence with assignment `←`:**\n\n```\nDEP5_EMPS  ← σ Dno=5 (EMPLOYEE)\nRESULT     ← π Fname,Lname,Salary (DEP5_EMPS)\n```\n\nHai cách hoàn toàn tương đương, *cùng kết quả*. Cách 2 dài hơn nhưng *dễ debug* — bạn nhìn thấy DEP5_EMPS trước khi chiếu xuống RESULT. Trong đề thi tự luận HCMUT, cả 2 đều được chấp nhận.\n\n**Tương đương SQL:**\n\n```sql\nSELECT Fname, Lname, Salary FROM EMPLOYEE WHERE Dno = 5;\n```\n\n---\n\n### 1.4. RENAME (ρ — rho) — Đổi tên relation và/hoặc cột (slide 20–21)\n\n#### Tại sao có RENAME?\n\nBạn cần self-join EMPLOYEE với chính nó (vd \"tìm cặp nhân viên - sếp\"). Cả hai bên đều tên EMPLOYEE và đều có cột Ssn → làm sao phân biệt? Phải đổi tên *một bên*. Đó là việc của ρ.\n\n> 💡 **Hiểu đơn giản:** ρ = `AS` trong SQL. `EMPLOYEE AS E1` đổi tên bảng tạm. ρ tổng quát hơn — đổi cả tên bảng lẫn tên cột.\n\n#### Ba dạng (slide 21)\n\n| Dạng | Ý nghĩa |\n|---|---|\n| `ρ_S(B1,B2,…,Bn)(R)` | Đổi tên relation thành S, **đồng thời** đổi tên các cột thành B1, …, Bn. |\n| `ρ_S(R)` | Chỉ đổi tên relation thành S. |\n| `ρ_(B1,B2,…,Bn)(R)` | Chỉ đổi tên cột thành B1, …, Bn. |\n\n#### Ví dụ với COMPANY\n\n```\nDEPT ← ρ_(Dname, Dnum, Mgr_ssn, Mgr_start_date)(DEPARTMENT)\n```\n\nĐổi `Dnumber` thành `Dnum` → khớp với cột `Dnum` của PROJECT → cho phép NATURAL JOIN sau đó.\n\n**Tương đương SQL:**\n\n```sql\nSELECT Dname, Dnumber AS Dnum, Mgr_ssn, Mgr_start_date FROM DEPARTMENT;\n```\n\n> 📝 **Tóm lại section 1 — Unary:**\n> - σ lọc dòng, π lọc cột, ρ đổi tên.\n> - σ giao hoán; π **không**; ρ chỉ đổi nhãn — không đụng dữ liệu.\n>\n> **Một câu ghi nhớ:** \"*σ cắt hàng — π cắt cột — ρ đổi tên.*\"\n\n> ❓ **Tự kiểm tra section 1:**\n> 1. `σ_Salary>30000(EMPLOYEE)` có giữ schema không? Số tuple thay đổi thế nào?\n> 2. Vì sao `π_Sex,Salary(EMPLOYEE)` có thể ít dòng hơn |EMPLOYEE|?\n> 3. Viết RA + SQL lấy `Fname`, `Lname` của nhân viên phòng 4.\n\n---\n\n","file":"materials/DB-Chapter5.md","section":3},{"id":"c5-04","group":"c5","kind":"source","title":"2. Set Theory Operations — Toán tử từ Lý thuyết Tập hợp","markdown":"## 2. Set Theory Operations — Toán tử từ Lý thuyết Tập hợp\n\n### 2.0. Vì sao có nhóm này?\n\nMột relation **là một tập** các tuple. Vì vậy mọi phép tập hợp toán học (∪, ∩, −, ×) **áp dụng được** lên relation. Đó chính là 4 toán tử của section này.\n\n> 💡 **Liên kết toán rời rạc:** `A ∪ B = {x | x ∈ A hoặc x ∈ B}`. Ở đây mọi `x` là một tuple. Logic giống hệt, chỉ khác đối tượng.\n\n### 2.1. UNION (∪) — Phép hợp (slide 23–24)\n\n- Binary, ký hiệu `∪`. `R ∪ S` = tập tuple thuộc **R hoặc S hoặc cả hai**.\n- **Loại trùng** tự động.\n- Hai relation phải **type-compatible** (xem 2.2).\n\n#### Ví dụ slide 24\n\n```\nRESULT1 (Ssn)         RESULT2 (Ssn)        RESULT = RESULT1 ∪ RESULT2\n123456789             333445555             123456789\n333445555             888665555             333445555\n666884444                                   666884444\n453453453                                   453453453\n                                            888665555\n```\n\n`333445555` xuất hiện ở cả 2 → chỉ giữ 1 lần. Kết quả 5 tuple.\n\n**Tương đương SQL:**\n\n```sql\nSELECT Ssn FROM RESULT1\nUNION\nSELECT Ssn FROM RESULT2;\n```\n\n(SQL `UNION` mặc định loại trùng. `UNION ALL` giữ trùng — KHÁC ngữ nghĩa RA.)\n\n### 2.2. Type Compatibility (slide 25)\n\nYêu cầu chung cho `∪`, `∩`, `−`:\n\n1. **Cùng số cột.**\n2. **Cột thứ i ↔ cột thứ i** có domain tương thích (cùng kiểu hoặc kiểu tương thích).\n3. **Tên cột không bắt buộc trùng** — kết quả lấy tên của relation đầu tiên (theo convention).\n\n**Ví dụ hợp lệ:** `π_Ssn(EMPLOYEE) ∪ π_Mgr_ssn(DEPARTMENT)` — đều là 1 cột chứa SSN.\n**Ví dụ KHÔNG hợp lệ:** `EMPLOYEE ∪ DEPARTMENT` — 10 cột vs 4 cột.\n\n### 2.3. INTERSECTION (∩) — Phép giao (slide 26)\n\n`R ∩ S` = tập tuple thuộc **cả R và S**. Tên cột kết quả lấy theo R. Cần type-compatible.\n\n> 💡 **Hiểu đơn giản:** Giao 2 danh sách (sinh viên đăng ký môn A) ∩ (sinh viên đăng ký môn B) = SV học cả hai.\n\n```sql\nSELECT Ssn FROM RESULT1\nINTERSECT\nSELECT Ssn FROM RESULT2;\n```\n\n### 2.4. SET DIFFERENCE (−) — Phép hiệu / MINUS / EXCEPT (slide 27)\n\n`R − S` = tập tuple **thuộc R nhưng không thuộc S**. Tên cột theo R. Cần type-compatible.\n\n> 💡 **Hiểu đơn giản:** \"Trong A, không có trong B.\" Vd: nhân viên đi làm hôm nay TRỪ nhân viên có lịch họp = nhân viên có thể tiếp khách.\n\n```sql\nSELECT Ssn FROM RESULT1\nEXCEPT          -- Oracle dùng MINUS\nSELECT Ssn FROM RESULT2;\n```\n\n### 2.5. Ví dụ tổng hợp ∪, ∩, − (slide 28 — Figure 6.4)\n\n**STUDENT** (7 tuple) | **INSTRUCTOR** (5 tuple) — type-compatible (đều 2 cột tên, dù khác tên cột Fn/Fname):\n\n| (a) STUDENT |  | INSTRUCTOR |  |\n|---|---|---|---|\n| Susan | Yao | John | Smith |\n| Ramesh | Shah | Ricardo | Browne |\n| Johnny | Kohler | Susan | Yao |\n| Barbara | Jones | Francis | Johnson |\n| Amy | Ford | Ramesh | Shah |\n| Jimmy | Wang |  |  |\n| Ernest | Gilbert |  |  |\n\n| (b) STUDENT ∪ INSTRUCTOR (10 tuple) | (c) STUDENT ∩ INSTRUCTOR (2) | (d) STUDENT − INSTRUCTOR (5) | (e) INSTRUCTOR − STUDENT (3) |\n|---|---|---|---|\n| Susan Yao + Ramesh Shah + Johnny Kohler + Barbara Jones + Amy Ford + Jimmy Wang + Ernest Gilbert + John Smith + Ricardo Browne + Francis Johnson | Susan Yao, Ramesh Shah | Johnny Kohler, Barbara Jones, Amy Ford, Jimmy Wang, Ernest Gilbert | John Smith, Ricardo Browne, Francis Johnson |\n\n> 📊 **Quan sát:** (d) ≠ (e) → DIFFERENCE **không giao hoán**. Tên cột: (b)–(d) dùng (Fn, Ln) theo STUDENT; (e) dùng (Fname, Lname) theo INSTRUCTOR.\n\n### 2.6. Tính chất ∪, ∩, − (slide 29)\n\n- ∪, ∩ **giao hoán** + **kết hợp** (associative) — viết được dạng n-ary: `R ∪ S ∪ T`.\n- − **không giao hoán:** `R − S ≠ S − R`.\n\n### 2.7. CARTESIAN PRODUCT (×) — Tích Descartes (slide 30–31)\n\n#### Tại sao có?\n\nJOIN (sẽ học section 3) chính là *× cộng với σ*. Vì vậy phải hiểu × trước.\n\n> 💡 **Hiểu đơn giản:** Tủ có 4 áo và 2 quần → tích Descartes = mỗi áo ghép mỗi quần = 8 bộ. Không phải bộ nào cũng hợp — JOIN sẽ thêm điều kiện \"hợp màu\".\n\n#### Định nghĩa\n\n`R(A1,…,An) × S(B1,…,Bm)` = relation Q có **n+m cột** `Q(A1,…,An,B1,…,Bm)` và **|R| × |S| tuple**.\n\nHai operand **KHÔNG cần** type-compatible.\n\n#### Ví dụ slide 31\n\n```\nR              T               R × T (8 tuple, 5 cột)\n| A | B | C |  | A | D |       | R.A | B | C | T.A | D |\n|---|---|---|  |---|---|       |-----|---|---|-----|---|\n| 1 | 2 | 3 |  | 1 | 5 |       |  1  | 2 | 3 |  1  | 5 |\n| 4 | 5 | 6 |  | 3 | 7 |       |  1  | 2 | 3 |  3  | 7 |\n| 1 | 2 | 7 |                   |  4  | 5 | 6 |  1  | 5 |\n| 8 | 4 | 5 |                   |  4  | 5 | 6 |  3  | 7 |\n                                |  1  | 2 | 7 |  1  | 5 |\n                                |  1  | 2 | 7 |  3  | 7 |\n                                |  8  | 4 | 5 |  1  | 5 |\n                                |  8  | 4 | 5 |  3  | 7 |\n```\n\nCả R và T đều có cột tên A → phải dùng prefix R.A và T.A.\n\n```sql\nSELECT * FROM R CROSS JOIN T;\n-- hoặc\nSELECT * FROM R, T;\n```\n\n> ⚠️ **Cảnh báo thực tế:** `1M × 1M = 10¹² dòng`. Trong production *luôn* theo sau bằng σ → tự nhiên trở thành JOIN.\n\n> 📝 **Tóm lại section 2 — Set theory:**\n> - ∪/∩/− cần type-compatible; tên cột kết quả lấy theo R đầu tiên.\n> - ∪, ∩ giao hoán + kết hợp; − KHÔNG giao hoán.\n> - × ghép mọi cặp tuple, không cần type-compat, |kết quả| = |R| × |S|.\n>\n> **Một câu ghi nhớ:** \"*∪/∩/− coi relation như set; × ghép thô để dành σ lọc.*\"\n\n> ❓ **Tự kiểm tra section 2:**\n> 1. EMPLOYEE ∪ DEPARTMENT có hợp lệ không? Vì sao?\n> 2. Tìm Essn xuất hiện trong WORKS_ON nhưng không trong DEPENDENT — viết RA.\n> 3. |EMPLOYEE × DEPARTMENT| với instance trên = bao nhiêu?\n\n---\n\n","file":"materials/DB-Chapter5.md","section":4},{"id":"c5-05","group":"c5","kind":"source","title":"3. Binary Relational Operations — Toán tử Hai ngôi","markdown":"## 3. Binary Relational Operations — Toán tử Hai ngôi\n\n### 3.1. JOIN (⋈) — Phép kết (slide 33–42)\n\n#### Tại sao có JOIN?\n\nTrong COMPANY, dữ liệu rải ra nhiều bảng: tên nhân viên ở EMPLOYEE, tên phòng ở DEPARTMENT, ai làm dự án nào ở WORKS_ON. Để trả lời \"tên manager mỗi phòng\" cần **ghép** EMPLOYEE và DEPARTMENT *theo điều kiện liên quan* (Mgr_ssn = Ssn). Đó là JOIN.\n\n> 💡 **Hiểu đơn giản:** JOIN = *VLOOKUP* trong Excel. Có hóa đơn với CustomerID; có bảng khách hàng cũng CustomerID — ghép đúng mã thì biết hóa đơn của ai.\n\n#### Khái niệm (slide 33–34)\n\n- JOIN ký hiệu `⋈`.\n- **Tương đương:** `R ⋈_θ S = σ_θ (R × S)` — tích Descartes rồi lọc.\n- Lý do gộp thành 1 phép riêng: pattern `× rồi σ` quá phổ biến với mọi DB có > 1 relation.\n\n#### Ví dụ slide 34 — Tên manager mỗi phòng\n\n```\nDEPT_MGR ← DEPARTMENT ⋈_Mgr_ssn=Ssn EMPLOYEE\nRESULT   ← π_Dname,Lname,Fname (DEPT_MGR)\n```\n\n#### Kết quả (slide 38)\n\n| Dname | Dnumber | Mgr_ssn | … | Fname | Minit | Lname | Ssn | … |\n|---|---|---|---|---|---|---|---|---|\n| Research | 5 | 333445555 | … | Franklin | T | Wong | 333445555 | … |\n| Administration | 4 | 987654321 | … | Jennifer | S | Wallace | 987654321 | … |\n| Headquarters | 1 | 888665555 | … | James | E | Borg | 888665555 | … |\n\n#### Dạng tổng quát (slide 39)\n\n`R(A1,…,An) ⋈_<join condition> S(B1,…,Bm)`\n\n- `<condition>` có dạng `Ai θ Bj`, với θ ∈ {=, <, >, ≤, ≥, ≠} hoặc Boolean phức.\n\n#### Tính chất (slide 40)\n\n- Schema kết quả = **n + m cột** (giống ×).\n- |R ⋈ S| **<** |R| × |S| nói chung — chỉ giữ tuple liên quan.\n\n### 3.2. Theta-Join (slide 41–42)\n\nTrường hợp tổng quát của JOIN — θ là Boolean expression bất kỳ. Khi θ chỉ dùng `=` thuần → gọi là **EQUIJOIN**.\n\n#### Ví dụ slide 42 — Theta-join với `>`\n\n```\nR              T               R ⋈_R.A > T.A T (4 tuple)\n| A | B | C |  | A | D |       | R.A | B | C | T.A | D |\n|---|---|---|  |---|---|       |-----|---|---|-----|---|\n| 1 | 2 | 3 |  | 1 | 5 |       |  4  | 5 | 6 |  1  | 5 |\n| 4 | 5 | 6 |  | 3 | 7 |       |  4  | 5 | 6 |  3  | 7 |\n| 1 | 2 | 7 |                   |  8  | 4 | 5 |  1  | 5 |\n| 8 | 4 | 5 |                   |  8  | 4 | 5 |  3  | 7 |\n```\n\nR.A=1 không > T.A nào → bị loại. R.A=4 > 1 và 3 → 2 cặp. R.A=8 → 2 cặp.\n\n```sql\nSELECT * FROM R JOIN T ON R.A > T.A;\n```\n\n### 3.3. EQUIJOIN (slide 43–44)\n\nTheta-join với θ là `=` thuần. Trong kết quả luôn có *một hoặc nhiều cặp cột* có giá trị bằng nhau ở mọi tuple.\n\n#### Ví dụ slide 44\n\n```\nR              S               R ⋈_R.A=S.A S (2 tuple)\n| A | B | C |  | A | D |       | R.A | B | C | S.A | D |\n|---|---|---|  |---|---|       |-----|---|---|-----|---|\n| 1 | 2 | 3 |  | 1 | 5 |       |  1  | 2 | 3 |  1  | 5 |\n| 4 | 5 | 6 |  | 3 | 7 |       |  1  | 2 | 7 |  1  | 5 |\n| 1 | 2 | 7 |\n| 8 | 4 | 5 |\n```\n\n**Lưu ý:** kết quả giữ cả `R.A` và `S.A` (dù bằng nhau) → đây là điểm khác NATURAL JOIN.\n\n### 3.4. NATURAL JOIN (* hoặc ⋈) (slide 45–50)\n\n#### Tại sao có?\n\nEQUIJOIN giữ 2 cột bằng nhau là *thừa*. NATURAL JOIN sinh ra để **bỏ cột thừa**, **tự** tìm cột cùng tên ở 2 bảng làm join condition.\n\n> 💡 **Hiểu đơn giản:** Hai bản scan cùng mã sinh viên — NATURAL JOIN nói \"Hai mã giống nhau rồi, giữ một là đủ.\"\n\n#### Định nghĩa (slide 45)\n\n- `Q ← R(A,B,C,D) * S(C,D,E)` → join condition ngầm = `R.C=S.C AND R.D=S.D`.\n- Kết quả `Q(A,B,C,D,E)` — chỉ 1 bản của mỗi cặp cột chung.\n- Yêu cầu: cột phải **cùng tên** ở 2 bảng. Nếu khác tên → ρ trước.\n\n#### Ví dụ slide 46\n\n```\nR              T               R * T (2 tuple, 4 cột — bỏ cột thừa A)\n| A | B | C |  | A | D |       | A | B | C | D |\n|---|---|---|  |---|---|       |---|---|---|---|\n| 1 | 2 | 3 |  | 1 | 5 |       | 1 | 2 | 3 | 5 |\n| 4 | 5 | 6 |  | 3 | 7 |       | 1 | 2 | 7 | 5 |\n| 1 | 2 | 7 |\n| 8 | 4 | 5 |\n```\n\n#### Slide 47–48 — PROJ_DEPT trên COMPANY\n\nPROJECT có cột `Dnum`, DEPARTMENT có `Dnumber` — *khác tên* → cần ρ trước:\n\n```\nDEPT       ← ρ_(Dname, Dnum, Mgr_ssn, Mgr_start_date)(DEPARTMENT)\nPROJ_DEPT  ← PROJECT * DEPT\n```\n\n| Pname | Pnumber | Plocation | Dnum | Dname | Mgr_ssn | Mgr_start_date |\n|---|---|---|---|---|---|---|\n| ProductX | 1 | Bellaire | 5 | Research | 333445555 | 1988-05-22 |\n| ProductY | 2 | Sugarland | 5 | Research | 333445555 | 1988-05-22 |\n| ProductZ | 3 | Houston | 5 | Research | 333445555 | 1988-05-22 |\n| Computerization | 10 | Stafford | 4 | Administration | 987654321 | 1995-01-01 |\n| Reorganization | 20 | Houston | 1 | Headquarters | 888665555 | 1981-06-19 |\n| Newbenefits | 30 | Stafford | 4 | Administration | 987654321 | 1995-01-01 |\n\n#### Slide 49–50 — DEPT_LOCS\n\nDEPARTMENT và DEPT_LOCATIONS đều có cột `Dnumber` → NATURAL JOIN trực tiếp:\n\n```\nDEPT_LOCS ← DEPARTMENT * DEPT_LOCATIONS\n```\n\n| Dname | Dnumber | Mgr_ssn | Mgr_start_date | Dlocation |\n|---|---|---|---|---|\n| Headquarters | 1 | 888665555 | 1981-06-19 | Houston |\n| Administration | 4 | 987654321 | 1995-01-01 | Stafford |\n| Research | 5 | 333445555 | 1988-05-22 | Bellaire |\n| Research | 5 | 333445555 | 1988-05-22 | Sugarland |\n| Research | 5 | 333445555 | 1988-05-22 | Houston |\n\nPhòng Research (Dnumber=5) có 3 location → 3 dòng.\n\n### 3.5. Complete Set (slide 51)\n\n**`{σ, π, ∪, −, ×}` là complete set** — mọi RA expression khác có thể biểu diễn bằng tổ hợp 5 phép này:\n\n- `R ∩ S = (R ∪ S) − ((R − S) ∪ (S − R))`\n- `R ⋈_<θ> S = σ_<θ> (R × S)`\n\n> 💡 **Ý nghĩa thực tiễn:** DBMS implementer chỉ cần code 5 phép cốt lõi. Các phép tiện (∩, ⋈, ÷) là *syntactic sugar* — về biểu đạt không thêm gì.\n\n### 3.6. DIVISION (÷) — Phép chia (slide 52–53)\n\n#### Tại sao có?\n\nCâu hỏi \"*làm trên TẤT CẢ project mà Smith làm*\" có *universal quantifier* — rất khó với σ/π/⋈. DIVISION sinh ra cho pattern này.\n\n> 💡 **Analogy số học:** 12 ÷ 3 = 4 vì 4 × 3 = 12. Trong RA: T = R ÷ S sao cho T × S ⊆ R, T lớn nhất có thể. Ngữ nghĩa: T = \"giá trị xuất hiện trong R *cùng với MỌI giá trị* của S\".\n\n#### Định nghĩa (slide 52)\n\n- `R(Z) ÷ S(X) = T(Y)` với `Z = X ∪ Y` (Y = các cột của R không thuộc S).\n- Tuple t ∈ T iff với *mọi* tuple t_S ∈ S, có tuple t_R ∈ R sao cho t_R[Y]=t và t_R[X]=t_S.\n\n#### Ví dụ slide 53(a) — Nhân viên làm tất cả project mà Smith làm\n\n**SSN_PNOS** = π_Essn,Pno (WORKS_ON) — 16 tuple (xem instance WORKS_ON ở section 0.4).\n\n**SMITH_PNOS** (Pno mà Smith — Ssn 123456789 — làm):\n\n| Pno |\n|---|\n| 1 |\n| 2 |\n\n**SSNS = SSN_PNOS ÷ SMITH_PNOS:**\n\n| Ssn |\n|---|\n| 123456789 |\n| 453453453 |\n\nSmith có (1, 2). English có (453453453, 1) và (453453453, 2). Wong (333445555) chỉ có Pno=2, thiếu 1 → bị loại.\n\n#### Ví dụ slide 53(b) — Tổng quát\n\n```\nR(A,B):  S(A):    T = R ÷ S (Y = {B}):\na1 b1    a1       b1\na2 b1    a2       b4\na3 b1    a3\na4 b1\na1 b2\na3 b2\na2 b3\na3 b3\na4 b3\na1 b4\na2 b4\na3 b4\n```\n\nb=b1 cùng a1, a2, a3, a4 → đủ a1, a2, a3 → giữ. b=b2 chỉ a1, a3 → thiếu a2 → loại. b=b3 thiếu a1 → loại. b=b4 đủ → giữ.\n\n#### Tương đương SQL — pattern double NOT EXISTS\n\n```sql\nSELECT DISTINCT W1.Essn\nFROM   WORKS_ON W1\nWHERE  NOT EXISTS (\n    SELECT 1 FROM WORKS_ON SMITH\n    WHERE  SMITH.Essn = '123456789'\n    AND    NOT EXISTS (\n        SELECT 1 FROM WORKS_ON W2\n        WHERE  W2.Essn = W1.Essn AND W2.Pno = SMITH.Pno\n    )\n);\n```\n\nLogic: \"không có Pno mà Smith làm và W1 *không* làm\" = \"W1 làm trên *mọi* Pno của Smith\".\n\n### 3.7. Bảng tổng hợp 10 phép RA (slide 54–55, Table 6.1)\n\n| Operation | Purpose | Notation |\n|---|---|---|\n| **SELECT** | Lọc tuple thỏa selection condition | `σ_<cond>(R)` |\n| **PROJECT** | Giữ một số cột, loại trùng | `π_<list>(R)` |\n| **THETA JOIN** | Cặp tuple thỏa join condition tổng quát | `R ⋈_<cond> S` |\n| **EQUIJOIN** | Theta join với chỉ phép `=` | `R ⋈_<eq cond> S` |\n| **NATURAL JOIN** | Equijoin trên cột cùng tên + bỏ cột trùng | `R * S` hoặc `R ⋈ S` |\n| **UNION** | Tuple thuộc R hoặc S | `R ∪ S` |\n| **INTERSECTION** | Tuple thuộc cả R và S | `R ∩ S` |\n| **DIFFERENCE** | Tuple thuộc R không thuộc S | `R − S` |\n| **CARTESIAN PRODUCT** | Mọi cặp tuple | `R × S` |\n| **DIVISION** | Pattern \"với mọi\" | `R(Z) ÷ S(Y)` |\n\n### 3.8. Notation for Query Trees (slide 56–58)\n\n#### Khái niệm\n\n**Query tree** = cây biểu diễn 1 RA expression:\n- **Leaf nodes** = input relation.\n- **Internal nodes** = phép RA.\n- **Root** = kết quả cuối.\n\nDữ liệu chảy *từ lá lên gốc*.\n\n> 💡 **Hiểu đơn giản:** Sơ đồ dây chuyền sản xuất: nguyên liệu vào ở lá, qua từng \"máy\" (phép RA), ra sản phẩm ở gốc.\n\n#### Ví dụ slide 58 — Q2\n\n> **Q2:** Với mọi project ở Stafford, liệt kê Pnumber, Dnum, Lname, Address, Bdate của manager phòng.\n\n```\nπ_Pnumber, Dnum, Lname, Address, Bdate(\n    ((σ_Plocation='Stafford'(PROJECT))\n        ⋈_Dnum=Dnumber DEPARTMENT)\n        ⋈_Mgr_ssn=Ssn EMPLOYEE\n)\n```\n\n```text\n                  π_P.Pnumber, P.Dnum, E.Lname, E.Address, E.Bdate\n                                  |\n                            ⋈ (3) D.Mgr_ssn = E.Ssn\n                            /                        \\\n                ⋈ (2) P.Dnum = D.Dnumber          (E) EMPLOYEE\n                /                       \\\n   σ (1) P.Plocation = 'Stafford'    (D) DEPARTMENT\n                |\n           (P) PROJECT\n```\n\n**Bước 1:** lọc PROJECT có Plocation='Stafford' → Computerization, Newbenefits.\n**Bước 2:** join với DEPARTMENT theo Dnum=Dnumber → cả 2 thuộc Administration (Dnumber=4).\n**Bước 3:** join với EMPLOYEE theo Mgr_ssn=Ssn → manager Wallace.\n**Cuối cùng:** π chiếu 5 cột.\n\n**Tương đương SQL:**\n\n```sql\nSELECT P.Pnumber, P.Dnum, E.Lname, E.Address, E.Bdate\nFROM   PROJECT P\nJOIN   DEPARTMENT D ON P.Dnum = D.Dnumber\nJOIN   EMPLOYEE   E ON D.Mgr_ssn = E.Ssn\nWHERE  P.Plocation = 'Stafford';\n```\n\n> 💡 **Vì sao DBMS quan tâm query tree:** Optimizer biến đổi cây để chạy nhanh hơn — *push σ xuống gần lá* (giảm tuple sớm), *đổi thứ tự ⋈* (join bảng nhỏ trước).\n\n> 📝 **Tóm lại section 3 — Binary:**\n> - JOIN = `σ_θ(R × S)` — ghép tuple liên quan.\n> - 3 biến thể: theta (điều kiện bất kỳ), equi (chỉ `=`), natural (cùng tên + bỏ cột trùng).\n> - DIVISION = \"*làm trên TẤT CẢ*\" — pattern double NOT EXISTS trong SQL.\n> - Query tree = data flow từ lá lên gốc.\n>\n> **Một câu ghi nhớ:** \"*JOIN nối dữ liệu liên quan; DIVISION kiểm tra liên hệ với toàn bộ tập yêu cầu.*\"\n\n> ❓ **Tự kiểm tra section 3:**\n> 1. Phân biệt theta-join, equi-join, natural join — cho ví dụ trên COMPANY.\n> 2. Vì sao NATURAL JOIN cần cột cùng tên?\n> 3. Diễn đạt \"tìm tên dự án mà *mọi* nhân viên phòng 5 đều tham gia\" — phép nào?\n\n---\n\n","file":"materials/DB-Chapter5.md","section":5},{"id":"c5-06","group":"c5","kind":"source","title":"4. Additional Relational Operations — Phép Mở rộng","markdown":"## 4. Additional Relational Operations — Phép Mở rộng\n\n### 4.1. Aggregate Functions and Grouping (𝓕) (slide 60–66)\n\n#### Tại sao có?\n\n5 phép cơ bản không tính được \"tổng lương\", \"trung bình giờ làm\", \"đếm nhân viên\" — chúng chỉ *thao tác trên tập tuple*, không *tính giá trị tổng hợp*. Cần phép mới: **Aggregate**.\n\n> 💡 **Hiểu đơn giản:** Aggregate = `=SUM(B2:B100)` trong Excel + GROUP BY trong SQL.\n\n#### Khái niệm (slide 60–61)\n\n- Hàm phổ biến: **SUM, AVERAGE, MAXIMUM, MINIMUM**, và **COUNT** (đếm dòng — không loại trùng).\n- Toán tử aggregate: **𝓕** (script F).\n- **Dạng tổng quát:** `[grouping attrs] 𝓕_<function list>(R)`\n\nVí dụ slide 61:\n\n| Biểu thức | Ý nghĩa |\n|---|---|\n| `𝓕 MAX Salary (EMPLOYEE)` | Lương cao nhất |\n| `𝓕 MIN Salary (EMPLOYEE)` | Lương thấp nhất |\n| `𝓕 SUM Salary (EMPLOYEE)` | Tổng lương |\n| `Dno 𝓕 COUNT Ssn, AVERAGE Salary (EMPLOYEE)` | Group theo Dno, đếm + trung bình |\n\n#### Ví dụ slide 62–64 — Bảng giả định (DNO, Name, Salary)\n\n```\nEMPLOYEE                    Dno 𝓕 COUNT Name, SUM Salary (EMPLOYEE)\n| DNO | Name | Salary |     | DNO | Count_Name | Sum_Salary |\n|-----|------|--------|     |-----|------------|------------|\n|  1  |  A   |  1000  |     |  1  |     3      |    4500    |\n|  1  |  B   |  1500  |     |  2  |     2      |    4500    |\n|  1  |  C   |  2000  |     |  3  |     1      |    3000    |\n|  2  |  D   |  2000  |\n|  2  |  E   |  2500  |\n|  3  |  F   |  3000  |\n```\n\n#### Ví dụ slide 65 — Không grouping (toàn bảng = 1 nhóm)\n\n```\n𝓕 COUNT Name, SUM Salary (EMPLOYEE)        𝓕 MAX Salary (EMPLOYEE)\n| Count_Name | Sum_Salary |                | Max_Salary |\n|------------|------------|                |------------|\n|     6      |   12000    |                |    3000    |\n```\n\n#### Ví dụ slide 66 — Trên COMPANY thực (Figure 6.10)\n\n**(a)** `ρ_R(Dno, No_of_employees, Average_sal) ( Dno 𝓕 COUNT Ssn, AVERAGE Salary (EMPLOYEE) )`:\n\n| Dno | No_of_employees | Average_sal |\n|---|---|---|\n| 5 | 4 | 33250 |\n| 4 | 3 | 31000 |\n| 1 | 1 | 55000 |\n\nPhòng 5: (Smith 30k + Wong 40k + Narayan 38k + English 25k)/4 = 33 250.\nPhòng 4: (Zelaya 25k + Wallace 43k + Jabbar 25k)/3 = 31 000.\n\n**(c)** Không grouping: `𝓕 COUNT Ssn, AVERAGE Salary (EMPLOYEE)`:\n\n| Count_ssn | Average_salary |\n|---|---|\n| 8 | 35125 |\n\n#### Tương đương SQL\n\n```sql\nSELECT Dno, COUNT(Ssn) AS No_of_employees, AVG(Salary) AS Average_sal\nFROM   EMPLOYEE GROUP BY Dno;\n\n-- Không grouping\nSELECT COUNT(Ssn), AVG(Salary) FROM EMPLOYEE;\n```\n\n### 4.2. Recursive Closure (slide 67)\n\n#### Khái niệm\n\n- Áp dụng cho **recursive relationship** (vd EMPLOYEE.Super_ssn → EMPLOYEE.Ssn).\n- Câu hỏi điển hình: \"tất cả supervisees của Borg ở *mọi cấp*\".\n- **RA cơ bản KHÔNG diễn đạt được** — cần looping mechanism.\n- **SQL3 standard** có `WITH RECURSIVE`.\n\n> 💡 **Analogy:** \"*tất cả con cháu* của ông X trong cây gia phả\". RA cơ bản chỉ thấy con trực tiếp; recursive closure thấy hết cấp.\n\n#### SQL3 ví dụ — supervisees của Borg\n\n```sql\nWITH RECURSIVE Subordinates AS (\n    SELECT Ssn, Fname, Lname, Super_ssn\n    FROM   EMPLOYEE WHERE Super_ssn = '888665555'   -- cấp 1\n    UNION ALL\n    SELECT E.Ssn, E.Fname, E.Lname, E.Super_ssn\n    FROM   EMPLOYEE E JOIN Subordinates S ON E.Super_ssn = S.Ssn\n)\nSELECT * FROM Subordinates;\n```\n\n### 4.3. OUTER JOIN — Phép kết ngoài (slide 68–75)\n\n#### Tại sao có?\n\nNATURAL JOIN/EQUIJOIN *vứt* tuple không có cặp khớp. Nếu muốn báo cáo \"tất cả nhân viên + tên phòng họ quản lý (NULL nếu không quản lý)\" → INNER JOIN làm mất 5 nhân viên không phải manager. **OUTER JOIN** giữ lại, padding bằng NULL.\n\n> 💡 **Hiểu đơn giản:** OUTER JOIN = INNER JOIN + \"không bỏ ai\".\n\n#### Ba biến thể (slide 69)\n\n| Loại | Ký hiệu | Ngữ nghĩa |\n|---|---|---|\n| **LEFT OUTER JOIN** | `R ⟕ S` | Giữ mọi tuple bên trái R; nếu không match S → cột S = NULL |\n| **RIGHT OUTER JOIN** | `R ⟖ S` | Giữ mọi tuple bên phải S; nếu không match R → cột R = NULL |\n| **FULL OUTER JOIN** | `R ⟗ S` | Giữ mọi tuple cả R và S; padding NULL khi cần |\n\n#### Ví dụ slide 70–72 — LEFT OUTER JOIN trên COMPANY\n\n> **Bài toán:** \"List tất cả tên nhân viên + tên phòng họ manage (NULL nếu không manage)\".\n\n```\nTEMP    ← EMPLOYEE ⟕_Ssn=Mgr_ssn DEPARTMENT\nRESULT  ← π_Fname, Minit, Lname, Dname (TEMP)\n```\n\n| Fname | Minit | Lname | Dname |\n|---|---|---|---|\n| John | B | Smith | NULL |\n| Franklin | T | Wong | Research |\n| Alicia | J | Zelaya | NULL |\n| Jennifer | S | Wallace | Administration |\n| Ramesh | K | Narayan | NULL |\n| Joyce | A | English | NULL |\n| Ahmad | V | Jabbar | NULL |\n| James | E | Borg | Headquarters |\n\n5 nhân viên không quản lý phòng nào → Dname=NULL nhưng *vẫn xuất hiện*.\n\n#### Ví dụ slide 73–75 — Tổng quát\n\n```\nR              S\n| A | B | C |  | P | Q |\n|---|---|---|  |---|---|\n| 1 | 2 | 3 |  | 1 | 5 |\n| 4 | 5 | 6 |  | 3 | 7 |\n| 1 | 2 | 7 |\n| 8 | 4 | 5 |\n```\n\n**LEFT (slide 73):** R ⟕_R.A=S.P S — giữ mọi R:\n\n| A | B | C | P | Q |\n|---|---|---|---|---|\n| 1 | 2 | 3 | 1 | 5 |\n| 1 | 2 | 7 | 1 | 5 |\n| 4 | 5 | 6 | null | null |\n| 8 | 4 | 5 | null | null |\n\n**RIGHT (slide 74):** R ⟖_R.A=S.P S — giữ mọi S:\n\n| A | B | C | P | Q |\n|---|---|---|---|---|\n| 1 | 2 | 3 | 1 | 5 |\n| 1 | 2 | 7 | 1 | 5 |\n| null | null | null | 3 | 7 |\n\n**FULL (slide 75):** R ⟗_R.A=S.P S — giữ cả 2:\n\n| A | B | C | P | Q |\n|---|---|---|---|---|\n| 1 | 2 | 3 | 1 | 5 |\n| 1 | 2 | 7 | 1 | 5 |\n| 4 | 5 | 6 | null | null |\n| 8 | 4 | 5 | null | null |\n| null | null | null | 3 | 7 |\n\n#### Tương đương SQL\n\n```sql\nSELECT … FROM R LEFT  OUTER JOIN S ON R.A = S.P;\nSELECT … FROM R RIGHT OUTER JOIN S ON R.A = S.P;\nSELECT … FROM R FULL  OUTER JOIN S ON R.A = S.P;\n```\n\n> 📝 **Tóm lại section 4 — Additional:**\n> - 𝓕 = SUM/AVG/COUNT/MIN/MAX (có/không grouping) — bù đắp khả năng RA cơ bản không tính được.\n> - Recursive closure xử lý quan hệ đệ quy — RA cơ bản KHÔNG có; SQL3 dùng `WITH RECURSIVE`.\n> - OUTER JOIN giữ tuple không match, padding NULL — tránh mất thông tin.\n>\n> **Một câu ghi nhớ:** \"*Aggregate đếm/cộng; Recursive đi nhiều tầng; OUTER không bỏ ai.*\"\n\n> ❓ **Tự kiểm tra section 4:**\n> 1. Tính tổng giờ làm (SUM Hours) theo từng project từ WORKS_ON — viết RA + SQL.\n> 2. R ⟕ S có bằng S ⟖ R không?\n> 3. Khi nào dùng FULL OUTER JOIN trong thực tế?\n\n---\n\n","file":"materials/DB-Chapter5.md","section":6},{"id":"c5-07","group":"c5","kind":"source","title":"5. Brief Introduction to Relational Calculus (slide 76–85)","markdown":"## 5. Brief Introduction to Relational Calculus (slide 76–85)\n\n### 5.0. Vì sao có Relational Calculus?\n\n- **RA = procedural** — bạn nói *cách lấy* (sequence of operations).\n- **Calculus = non-procedural** — bạn nói *cái cần lấy* (điều kiện kết quả).\n- **SQL chuẩn dựa trên Tuple Calculus** — hiểu calculus = hiểu nguồn gốc cú pháp `SELECT … WHERE …` (giống `{t | COND(t)}`).\n\n> 💡 **Hiểu đơn giản:**\n> - RA: \"Bước 1 lọc, bước 2 chiếu, bước 3 join…\" — chỉ đầu bếp từng bước.\n> - Calculus: \"Tôi muốn món có thịt bò, không cay, có rau\" — đầu bếp tự quyết cách nấu.\n\n### 5.1. So sánh nhanh (slide 77)\n\n| Tiêu chí | Relational Algebra | Relational Calculus |\n|---|---|---|\n| Tư duy | Procedural | Non-procedural |\n| Hỏi | Làm bằng các bước nào? | Kết quả thỏa điều kiện gì? |\n| Biểu diễn | Chuỗi σ, π, ⋈ | Công thức logic với biến |\n| Gần với | Query plan | Declarative query |\n\n### 5.2. Tuple Relational Calculus (slide 78)\n\n- Biến `t` chạy trên **tuple** (cả 1 dòng) của một relation.\n- **Dạng đơn giản:** `{t | COND(t)}` — tập các giá trị t sao cho COND(t) đúng.\n- `EMPLOYEE(t)` đọc là \"t là tuple thuộc EMPLOYEE\".\n- `t.FNAME` truy cột FNAME của tuple t.\n\n#### Ví dụ slide 78\n\n> Tìm Fname, Lname của nhân viên lương > 50 000:\n> `{t.FNAME, t.LNAME | EMPLOYEE(t) AND t.SALARY > 50000}`\n\n**RA tương đương:** `π_Fname,Lname (σ_Salary>50000 (EMPLOYEE))`\n\n**SQL tương đương:**\n\n```sql\nSELECT Fname, Lname FROM EMPLOYEE WHERE Salary > 50000;\n```\n\n### 5.3. Quantifiers ∀ và ∃ (slide 79)\n\n- **Existential `∃`** — \"tồn tại ít nhất một…\"\n- **Universal `∀`** — \"với mọi…\"\n- Tuple variable t là **bound** nếu xuất hiện trong `(∀t)` hoặc `(∃t)`; ngược lại là **free** (xuất hiện trong output).\n\n### 5.4. Ví dụ tuple calculus (slide 80–81)\n\n#### Example 1 (slide 80) — Nhân viên phòng 'Research'\n\n```\n{t.FNAME, t.LNAME, t.ADDRESS |\n   EMPLOYEE(t) AND\n   (∃ d) (DEPARTMENT(d) AND d.DNAME='Research' AND d.DNUMBER=t.DNO)}\n```\n\n**Diễn giải:**\n- `t` free trên EMPLOYEE.\n- `d` bound (∃ d) trên DEPARTMENT.\n- Điều kiện: tồn tại 1 phòng d có Dname='Research' và Dnumber=t.Dno.\n\n**RA tương đương:** `π_Fname,Lname,Address (σ_Dname='Research' (EMPLOYEE ⋈_Dno=Dnumber DEPARTMENT))`\n\n**SQL tương đương:**\n\n```sql\nSELECT E.Fname, E.Lname, E.Address\nFROM   EMPLOYEE E JOIN DEPARTMENT D ON E.Dno = D.Dnumber\nWHERE  D.Dname = 'Research';\n```\n\n#### Example 2 (slide 81) — Nhân viên làm *tất cả* project phòng 5\n\n```\n{e.LNAME, e.FNAME |\n   EMPLOYEE(e) AND ((∀ x)\n   (NOT(PROJECT(x)) OR NOT(x.DNUM=5)\n    OR ((∃ w)(WORKS_ON(w) AND w.ESSN=e.SSN AND x.PNUMBER=w.PNO))))}\n```\n\n**Diễn giải logic** (P → Q ≡ ¬P ∨ Q):\n- Với *mọi* x: nếu x là project phòng 5 → tồn tại w trong WORKS_ON nối e với x.\n- Đọc thẳng: \"với mọi project x phòng 5, e *đều* làm trên x\" → semantic của DIVISION.\n\n**RA tương đương dùng DIVISION:**\n\n```\nDEPT5_PROJS  ← π_Pnumber (σ_Dnum=5 (PROJECT))\nEMP_PROJS    ← π_Essn,Pno (WORKS_ON)\nRESULT_SSNS  ← EMP_PROJS ÷ DEPT5_PROJS\nRESULT       ← π_Lname,Fname (EMPLOYEE ⋈_Ssn=Essn RESULT_SSNS)\n```\n\n**SQL tương đương — double NOT EXISTS:**\n\n```sql\nSELECT E.Lname, E.Fname\nFROM   EMPLOYEE E\nWHERE  NOT EXISTS (\n    SELECT 1 FROM PROJECT P\n    WHERE  P.Dnum = 5\n    AND    NOT EXISTS (\n        SELECT 1 FROM WORKS_ON W\n        WHERE  W.Essn = E.Ssn AND W.Pno = P.Pnumber\n    )\n);\n```\n\n### 5.5. Domain Relational Calculus (slide 82–83)\n\n- Biến chạy trên **giá trị** từ domain của một cột (không phải tuple).\n- Để tạo relation degree n cần n biến (1 cho mỗi cột).\n- **Dạng tổng quát:** `{x1, x2, …, xn | COND(x1, …, xn, xn+1, …, xn+m)}`\n- **QBE (Query-By-Example)** dựa trên domain calculus — xem Appendix D giáo trình.\n\n#### Example slide 83 — Bdate, Address của 'John B. Smith'\n\n```\n{uv | (∃ q)(∃ r)(∃ s)(∃ t)(∃ w)(∃ x)(∃ y)(∃ z)\n      (EMPLOYEE(qrstuvwxyz) AND q='John' AND r='B' AND s='Smith')}\n```\n\nMỗi attribute EMPLOYEE → 1 biến: q=Fname, r=Minit, s=Lname, t=Ssn, **u=Bdate**, **v=Address**, w=Sex, x=Salary, y=Super_ssn, z=Dno. Free = `uv` (output). Bound qua ∃ = 8 biến còn lại.\n\n**RA tương đương:** `π_Bdate,Address (σ_Fname='John' AND Minit='B' AND Lname='Smith' (EMPLOYEE))`\n\n**SQL tương đương:**\n\n```sql\nSELECT Bdate, Address\nFROM   EMPLOYEE\nWHERE  Fname='John' AND Minit='B' AND Lname='Smith';\n```\n\n### 5.6. Slide 85 — Q&A\n\nSlide kết chương — không có nội dung lý thuyết mới.\n\n> 📝 **Tóm lại section 5 — Calculus:**\n> - RA = \"làm thế nào\"; Calculus = \"kết quả nào thỏa điều kiện\".\n> - Tuple calculus: biến chạy trên tuple. Domain calculus: biến chạy trên giá trị cột.\n> - ∀ = \"với mọi\" → SQL pattern double NOT EXISTS. ∃ = \"tồn tại\" → SQL pattern EXISTS.\n> - 3 ngôn ngữ (RA, Tuple Calculus, Domain Calculus) **biểu đạt tương đương**.\n>\n> **Một câu ghi nhớ:** \"*RA mô tả công thức biến đổi; Calculus mô tả tập kết quả.*\"\n\n> ❓ **Tự kiểm tra section 5:**\n> 1. Calculus procedural hay non-procedural?\n> 2. Tuple vs Domain calculus khác gì ở loại biến?\n> 3. ∀ và ∃ tương ứng SQL pattern nào?\n\n---\n\n","file":"materials/DB-Chapter5.md","section":7},{"id":"c5-08","group":"c5","kind":"source","title":"📌 Bảng Tra Nhanh — Cheatsheet ôn thi","markdown":"## 📌 Bảng Tra Nhanh — Cheatsheet ôn thi\n\n### Toán tử + cú pháp + SQL tương đương\n\n| Toán tử | Ký hiệu | Mục đích | Dạng tổng quát | SQL tương đương | Ví dụ COMPANY |\n|---|---|---|---|---|---|\n| SELECT | σ | Lọc tuple | `σ_<cond>(R)` | `WHERE` | `σ_Dno=5(EMPLOYEE)` |\n| PROJECT | π | Chiếu cột | `π_<list>(R)` | `SELECT DISTINCT` | `π_Lname,Fname(EMPLOYEE)` |\n| RENAME | ρ | Đổi tên | `ρ_S(B1,…)(R)` | `AS` | `ρ_(Dnum)(DEPARTMENT)` |\n| UNION | ∪ | Hợp set | `R ∪ S` | `UNION` | `π_Ssn(EMP) ∪ π_Mgr_ssn(DEPT)` |\n| INTERSECTION | ∩ | Giao set | `R ∩ S` | `INTERSECT` | tuple chung 2 query |\n| DIFFERENCE | − | Hiệu set | `R − S` | `EXCEPT`/`MINUS` | tuple R không có S |\n| CARTESIAN PRODUCT | × | Tích | `R × S` | `CROSS JOIN`, `FROM R, S` | `EMP × DEPT` |\n| THETA JOIN | ⋈_θ | Kết theo Boolean | `R ⋈_θ S` | `JOIN ON …` | `EMP ⋈_Salary>1.5*S.Salary EMP` (self-join >) |\n| EQUIJOIN | ⋈_= | Kết bằng | `R ⋈_R.X=S.Y S` | `INNER JOIN ON =` | `DEPT ⋈_Mgr_ssn=Ssn EMP` |\n| NATURAL JOIN | * | Equi cột cùng tên + bỏ trùng | `R * S` | `NATURAL JOIN` | `DEPT * DEPT_LOCATIONS` |\n| DIVISION | ÷ | \"Với mọi\" | `R(Z) ÷ S(X)` | double `NOT EXISTS` | `SSN_PNOS ÷ SMITH_PNOS` |\n| AGGREGATE | 𝓕 | Tổng hợp | `[grp] 𝓕_<fn>(R)` | `GROUP BY` + agg | `Dno 𝓕_COUNT Ssn(EMP)` |\n| LEFT OUTER JOIN | ⟕ | Giữ trái | `R ⟕ S` | `LEFT OUTER JOIN` | `EMP ⟕_Ssn=Mgr_ssn DEPT` |\n| RIGHT OUTER JOIN | ⟖ | Giữ phải | `R ⟖ S` | `RIGHT OUTER JOIN` | — |\n| FULL OUTER JOIN | ⟗ | Giữ cả 2 | `R ⟗ S` | `FULL OUTER JOIN` | — |\n\n### Tính chất ngắn gọn\n\n| Phép | Giao hoán? | Kết hợp? | Cần type-compat? | |kết quả| so |R| |\n|---|---|---|---|---|\n| σ | ✅ | n/a | n/a | ≤ |R| |\n| π | ❌ | n/a | n/a | ≤ |R| (= nếu list chứa key) |\n| ρ | n/a | n/a | n/a | = |R| |\n| ∪ | ✅ | ✅ | ✅ | ≤ |R|+|S| |\n| ∩ | ✅ | ✅ | ✅ | ≤ min(|R|,|S|) |\n| − | ❌ | n/a | ✅ | ≤ |R| |\n| × | ✅ | ✅ | ❌ | = |R|·|S| |\n| ⋈ | ✅ (INNER) | ✅ | ❌ | ≤ |R|·|S| |\n| ÷ | ❌ | ❌ | n/a | tùy |\n| ⟕/⟖ | ❌ (R ⟕ S = S ⟖ R) | ❌ | ❌ | ≥ |R| (LEFT) |\n\n### Complete Set & quan hệ giữa các phép\n\n- `{σ, π, ∪, −, ×}` complete.\n- `R ∩ S = (R ∪ S) − ((R − S) ∪ (S − R))`\n- `R ⋈_θ S = σ_θ (R × S)`\n\n---\n\n","file":"materials/DB-Chapter5.md","section":8},{"id":"c5-09","group":"c5","kind":"source","title":"⚠️ Sai lầm thường gặp","markdown":"## ⚠️ Sai lầm thường gặp\n\n| # | Sai lầm | Vì sao sai | Cách đúng |\n|---|---|---|---|\n| 1 | Viết `π_Sex,Salary(EMPLOYEE)` rồi đếm 8 tuple | Quên bước loại trùng của π — bộ (F, 25 000) xuất hiện 2 lần (Zelaya & English) → loại còn 1 → 7 tuple | Luôn nhớ: **π loại trùng tự động**. Trong SQL phải dùng `DISTINCT` để khớp |\n| 2 | Cho rằng SQL `SELECT` = π của RA | SQL mặc định KHÔNG loại trùng (multiset). RA loại tự động | Dùng `SELECT DISTINCT` để khớp ngữ nghĩa π |\n| 3 | Viết `EMPLOYEE ∪ DEPARTMENT` | 10 cột vs 4 cột → không type-compatible | ∪/∩/− cần cùng số cột + domain tương thích |\n| 4 | Tin rằng `R − S = S − R` | DIFFERENCE KHÔNG giao hoán | \"Tôi có không phải bạn\" ≠ \"bạn có không phải tôi\" |\n| 5 | Dùng NATURAL JOIN khi 2 bảng có cột cùng tên *vô tình* | NJ tự nối *mọi* cột cùng tên — kết quả sai nếu cột không cùng nghĩa | Dùng EQUIJOIN/THETA-JOIN với điều kiện rõ; hoặc ρ trước |\n| 6 | EQUIJOIN nhưng quên rằng kết quả giữ *cả 2 cột bằng nhau* | EQUIJOIN ≠ NATURAL JOIN | Schema kết quả NJ ít hơn EQ 1 cột mỗi cặp |\n| 7 | Viết DIVISION nhưng quên Y = Z − X | Schema kết quả T(Y) chỉ chứa cột R không thuộc S | Tính Y trước khi viết R(Z) ÷ S(X) |\n| 8 | Dùng INNER JOIN khi muốn \"list tất cả nhân viên + phòng manage (NULL nếu không)\" | INNER JOIN bỏ tuple không match → mất 5 nhân viên không phải manager | Dùng LEFT OUTER JOIN |\n| 9 | Aggregate KHÔNG có grouping nhưng vẫn group theo các cột khác | `𝓕_COUNT Salary(EMP)` = 1 dòng. Muốn theo phòng phải dùng `Dno 𝓕_COUNT Salary(EMP)` | Cú pháp: cột bên trái 𝓕 = grouping; bên phải = function list |\n| 10 | Tin rằng RA *cơ bản* xử lý được recursive closure | RA cơ bản KHÔNG có loop → không lấy supervisees ở mọi cấp | Dùng SQL3 `WITH RECURSIVE` |\n| 11 | Coi tuple calculus và RA là 2 **mức biểu đạt** khác nhau | Cả 2 (cộng domain calculus) **biểu đạt tương đương** — chỉ khác cú pháp/tư duy | Cùng query → 3 cách viết |\n| 12 | Viết `σ A=1 (R) ∪ σ A=4 (R)` thay vì `σ A=1 OR A=4 (R)` | Cả hai *bằng nhau*, nhưng cách 2 ngắn hơn và optimizer dễ tối ưu hơn | Distributive: σ phân phối qua ∪ |\n\n---\n\n","file":"materials/DB-Chapter5.md","section":9},{"id":"c5-10","group":"c5","kind":"source","title":"🎯 Mini bài tập có lời giải","markdown":"## 🎯 Mini bài tập có lời giải\n\n> **Bài 1 (Dễ):** Viết RA và SQL liệt kê tên (Fname, Lname) các nhân viên *nữ phòng 5*.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **RA:** `π_Fname,Lname (σ_Sex='F' AND Dno=5 (EMPLOYEE))`\n>\n> **SQL:**\n> ```sql\n> SELECT DISTINCT Fname, Lname FROM EMPLOYEE WHERE Sex='F' AND Dno=5;\n> ```\n>\n> **Kết quả trên instance:** Joyce English. (Chỉ 1 nhân viên nữ phòng 5.)\n> </details>\n\n> **Bài 2 (Trung bình):** Tìm Ssn của các nhân viên *có ít nhất một dependent kiểu 'Spouse'*.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **RA:** `π_Essn (σ_Relationship='Spouse' (DEPENDENT))`\n>\n> **SQL:**\n> ```sql\n> SELECT DISTINCT Essn FROM DEPENDENT WHERE Relationship='Spouse';\n> ```\n>\n> **Kết quả:** {333445555 (Wong), 987654321 (Wallace), 123456789 (Smith)} — 3 Ssn.\n> </details>\n\n> **Bài 3 (Trung bình):** Cho biết tên (Lname) của *manager mỗi phòng* cùng *tên phòng* họ quản lý — dùng JOIN.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **RA:**\n> ```\n> DEPT_MGR ← DEPARTMENT ⋈_Mgr_ssn=Ssn EMPLOYEE\n> RESULT   ← π_Dname,Lname (DEPT_MGR)\n> ```\n>\n> **SQL:**\n> ```sql\n> SELECT D.Dname, E.Lname\n> FROM DEPARTMENT D JOIN EMPLOYEE E ON D.Mgr_ssn = E.Ssn;\n> ```\n>\n> **Kết quả:** (Research, Wong), (Administration, Wallace), (Headquarters, Borg).\n> </details>\n\n> **Bài 4 (Trung bình–Khó):** Đếm số dependent của mỗi nhân viên — group theo Essn, in (Essn, Count).\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **RA:** `Essn 𝓕_COUNT Dependent_name (DEPENDENT)`\n>\n> **SQL:**\n> ```sql\n> SELECT Essn, COUNT(Dependent_name) AS Num\n> FROM DEPENDENT\n> GROUP BY Essn;\n> ```\n>\n> **Kết quả:**\n> | Essn | Num |\n> |---|---|\n> | 333445555 | 3 |\n> | 987654321 | 1 |\n> | 123456789 | 3 |\n>\n> Lưu ý: nhân viên không có dependent (Wong, Zelaya, Narayan, English, Jabbar, Borg) **không xuất hiện** vì DEPENDENT không có Essn của họ. Nếu muốn họ xuất hiện với 0 → dùng LEFT OUTER JOIN trước.\n> </details>\n\n> **Bài 5 (Khó — pattern \"với mọi\"):** Tìm Ssn của nhân viên đã làm việc trên *tất cả các project* mà phòng 4 quản lý.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **Bước 1 — Set các Pnumber thuộc phòng 4:**\n> `DEPT4_PROJS ← π_Pnumber (σ_Dnum=4 (PROJECT))` = {10, 30}\n>\n> **Bước 2 — Bảng (Essn, Pno) từ WORKS_ON:**\n> `EMP_PROJS ← π_Essn,Pno (WORKS_ON)`\n>\n> **Bước 3 — DIVISION:**\n> `RESULT ← EMP_PROJS ÷ DEPT4_PROJS`\n>\n> **Tính tay:** Cần Essn xuất hiện cùng *cả* Pno=10 và Pno=30.\n> - 333445555: làm 10 (✓), không làm 30 → loại.\n> - 999887777: làm 30 và 10 → ✓.\n> - 987987987: làm 10 và 30 → ✓.\n> - 987654321: làm 30, không làm 10 → loại.\n> - 888665555: làm 20 (Reorganization, phòng 1), không phòng 4 → loại.\n>\n> **Kết quả:** {999887777 (Zelaya), 987987987 (Jabbar)} — 2 Ssn.\n>\n> **SQL — double NOT EXISTS:**\n> ```sql\n> SELECT DISTINCT W1.Essn FROM WORKS_ON W1\n> WHERE NOT EXISTS (\n>     SELECT 1 FROM PROJECT P WHERE P.Dnum = 4\n>     AND NOT EXISTS (\n>         SELECT 1 FROM WORKS_ON W2\n>         WHERE W2.Essn = W1.Essn AND W2.Pno = P.Pnumber\n>     )\n> );\n> ```\n> </details>\n\n> **Bài 6 (Khó — OUTER JOIN + Aggregate):** Liệt kê tên phòng và *tổng số nhân viên* của phòng đó. Phòng không có nhân viên nào → 0.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **RA (dùng LEFT OUTER JOIN để giữ phòng không có nhân viên):**\n> ```\n> TEMP   ← DEPARTMENT ⟕_Dnumber=Dno EMPLOYEE\n> RESULT ← Dname 𝓕_COUNT Ssn (TEMP)\n> ```\n>\n> **SQL:**\n> ```sql\n> SELECT D.Dname, COUNT(E.Ssn) AS NumEmp\n> FROM   DEPARTMENT D\n> LEFT  OUTER JOIN EMPLOYEE E ON D.Dnumber = E.Dno\n> GROUP  BY D.Dname;\n> ```\n>\n> **Lưu ý quan trọng:** dùng `COUNT(E.Ssn)` (đếm cột) chứ KHÔNG `COUNT(*)` — `COUNT(*)` đếm dòng, sẽ đếm cả dòng NULL của phòng không có nhân viên (= 1) thay vì 0.\n>\n> **Kết quả với instance hiện tại:** (Research, 4), (Administration, 3), (Headquarters, 1). Cả 3 phòng đều có nhân viên — chưa thấy hiệu ứng OUTER. Nếu thêm phòng \"Marketing\" không có nhân viên thì sẽ là (Marketing, 0) thay vì biến mất.\n> </details>\n\n> **Bài 7 (Tuple Calculus):** Dịch RA `π_Lname,Salary (σ_Dno=5 AND Salary≥35000 (EMPLOYEE))` sang tuple calculus.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> ```\n> {t.LNAME, t.SALARY | EMPLOYEE(t) AND t.DNO = 5 AND t.SALARY >= 35000}\n> ```\n>\n> **Diễn giải:**\n> - `t` free trên EMPLOYEE.\n> - 2 điều kiện AND nhau.\n> - Output 2 cột: t.LNAME và t.SALARY.\n>\n> **Kết quả trên instance:** (Wong, 40 000), (Narayan, 38 000) — 2 tuple.\n> </details>\n\n---\n\n","file":"materials/DB-Chapter5.md","section":10},{"id":"c5-11","group":"c5","kind":"source","title":"🔗 Liên kết Lab / BTL","markdown":"## 🔗 Liên kết Lab / BTL\n\n- **Lab 1 / Lab 2** (`Labs/Lab 1.docx`, `Lab 2.docx`): Lab về SQL trên schema COMPANY — dùng RA để debug ngữ nghĩa trước khi viết SQL.\n- **Exercises** (`Exercises/6_Exercise_SQL.docx`): bài tập SQL — **mỗi câu** có thể giải bằng RA trước cho chắc semantic.\n- **BTL1** (`BTL1_DB_Lab/`): pipeline ER → Relational mapping → SQL queries. Chương 5 là **cầu nối** giữa Relational Schema (đã có sau Chương 4) và SQL (sẽ viết ở Chương 6).\n- **BTL2** (`BTL2_DB_Lab/`): truy vấn nâng cao trên CSDL thật — pattern OUTER JOIN, GROUP BY, DIVISION (NOT EXISTS NOT EXISTS) xuất hiện thường xuyên.\n- **Phần thi cuối kỳ:** thường có 2–3 câu RA tự luận (vẽ query tree, viết RA, dịch RA ↔ SQL) + trắc nghiệm tính chất các phép.\n\n---\n\n","file":"materials/DB-Chapter5.md","section":11},{"id":"c5-12","group":"c5","kind":"source","title":"📚 Bảng Tổng Hợp Thuật Ngữ Chương 5 (Glossary)","markdown":"## 📚 Bảng Tổng Hợp Thuật Ngữ Chương 5 (Glossary)\n\n| STT | Thuật ngữ (EN) | Tiếng Việt | Định nghĩa ngắn | Slide # |\n|---:|---|---|---|---|\n| 1 | Relational Algebra | Đại số quan hệ | Tập phép biến đổi *bảng → bảng* | 2 |\n| 2 | Closed property | Tính đóng | Input/output đều là relation | 2 |\n| 3 | Relational Algebra Expression | Biểu thức ĐSQH | Chuỗi/nesting các phép RA | 2, 18, 19 |\n| 4 | SELECT (σ) | Phép chọn | Lọc tuple thỏa Boolean | 9–12 |\n| 5 | Selection condition | Điều kiện chọn | Boolean trên attribute | 10 |\n| 6 | PROJECT (π) | Phép chiếu | Giữ một số cột, loại trùng | 13–17 |\n| 7 | Vertical partitioning | Phân hoạch dọc | Cách hình dung π | 13 |\n| 8 | Duplicate elimination | Loại trùng | Bước hậu kỳ bắt buộc của π | 14 |\n| 9 | RENAME (ρ) | Phép đổi tên | Đổi tên relation/attribute | 20–21 |\n| 10 | Assignment (←) | Gán | Đặt tên relation trung gian | 19 |\n| 11 | UNION (∪) | Phép hợp | t ∈ R hoặc S, loại trùng | 23–25 |\n| 12 | INTERSECTION (∩) | Phép giao | t ∈ R và t ∈ S | 26 |\n| 13 | SET DIFFERENCE (−) | Phép hiệu | t ∈ R và t ∉ S | 27 |\n| 14 | Type compatibility | Tương thích kiểu | Cùng số cột + domain tương ứng | 23, 25 |\n| 15 | CARTESIAN PRODUCT (×) | Tích Descartes | Mọi cặp tuple, |R|·|S| dòng | 30–31 |\n| 16 | JOIN (⋈) | Phép kết | σ_θ(R × S) | 33–42 |\n| 17 | Theta-join | Theta join | JOIN với điều kiện bất kỳ | 41 |\n| 18 | EQUIJOIN | Equi-join | JOIN chỉ với `=` | 43–44 |\n| 19 | NATURAL JOIN (*) | Kết tự nhiên | EQUIJOIN cột cùng tên + bỏ trùng | 45–50 |\n| 20 | Complete set | Tập đầy đủ | {σ,π,∪,−,×} đủ biểu diễn mọi RA | 51 |\n| 21 | DIVISION (÷) | Phép chia | \"Với mọi\" | 52–53 |\n| 22 | Query tree | Cây truy vấn | Cây biểu diễn 1 RA expression | 56–58 |\n| 23 | Aggregate function (𝓕) | Hàm tổng hợp | SUM, COUNT, AVG, MIN, MAX | 60–66 |\n| 24 | Grouping attribute | Thuộc tính nhóm | Cột bên trái 𝓕 | 61–66 |\n| 25 | Recursive closure | Bao đóng đệ quy | Query \"ở mọi cấp\" | 67 |\n| 26 | OUTER JOIN | Kết ngoài | INNER JOIN + giữ tuple không match | 68–75 |\n| 27 | LEFT OUTER JOIN (⟕) | Kết ngoài trái | Giữ tất cả tuple bên trái | 69, 72–73 |\n| 28 | RIGHT OUTER JOIN (⟖) | Kết ngoài phải | Giữ tất cả tuple bên phải | 69, 74 |\n| 29 | FULL OUTER JOIN (⟗) | Kết ngoài đầy đủ | Giữ cả 2 bên | 69, 75 |\n| 30 | OUTER UNION | Hợp ngoài | (slide ghi homework) | 68 |\n| 31 | Relational Calculus | Phép tính quan hệ | Non-procedural query language | 77 |\n| 32 | Tuple calculus | Phép tính tuple | Biến chạy trên tuple | 78–81 |\n| 33 | Domain calculus | Phép tính domain | Biến chạy trên giá trị cột | 82–83 |\n| 34 | Universal quantifier (∀) | Lượng từ phổ quát | \"Với mọi\" | 79 |\n| 35 | Existential quantifier (∃) | Lượng từ tồn tại | \"Tồn tại\" | 79 |\n| 36 | Bound / Free variable | Biến ràng buộc / tự do | Quantified vs xuất hiện trong output | 79 |\n| 37 | QBE (Query-By-Example) | — | Giao diện query graphical | 82 |\n\n---\n\n","file":"materials/DB-Chapter5.md","section":12},{"id":"c5-13","group":"c5","kind":"source","title":"📑 Phụ lục A — Slide-by-slide index","markdown":"## 📑 Phụ lục A — Slide-by-slide index\n\n| Slide | Nội dung |\n|---:|---|\n| 1 | Title — Relational Algebra Chapter 5 |\n| 2 | Relational Algebra Overview, closed property |\n| 3 | Danh sách 4 nhóm toán tử |\n| 4, 5 | Contents — section 1 highlight (slide 5) |\n| 6 | COMPANY Database Schema |\n| 7 | Instance EMPLOYEE |\n| 8 | Instance DEPARTMENT, DEPT_LOCATIONS, WORKS_ON, PROJECT, DEPENDENT |\n| 9 | SELECT — định nghĩa + 2 ví dụ Dno=4, Salary>30000 |\n| 10 | SELECT — dạng tổng quát |\n| 11 | SELECT — properties (commutative, cascade) |\n| 12 | SELECT — ví dụ σ A≤4(R) |\n| 13 | PROJECT — định nghĩa + ví dụ π Lname,Fname,Salary |\n| 14 | PROJECT — dạng tổng quát + duplicate elimination |\n| 15 | PROJECT — properties (không giao hoán) |\n| 16 | PROJECT — ví dụ π A,B(R) |\n| 17 | Examples (a) σ + (b) π Lname,Fname,Salary + (c) π Sex,Salary |\n| 18 | Relational Algebra Expressions |\n| 19 | Single expression vs sequence with `←` |\n| 20 | RENAME — định nghĩa |\n| 21 | RENAME — 3 dạng |\n| 22 | Contents — section 2 highlight |\n| 23 | UNION |\n| 24 | UNION — ví dụ RESULT1 ∪ RESULT2 |\n| 25 | Type compatibility chung |\n| 26 | INTERSECTION |\n| 27 | SET DIFFERENCE |\n| 28 | Figure 6.4 — STUDENT/INSTRUCTOR ∪/∩/− |\n| 29 | Properties of UNION/INTERSECT/DIFFERENCE |\n| 30 | CARTESIAN PRODUCT |\n| 31 | CARTESIAN PRODUCT — ví dụ R × T |\n| 32 | Contents — section 3 highlight |\n| 33 | JOIN — overview |\n| 34 | JOIN — ví dụ DEPT_MGR (manager mỗi phòng) |\n| 35 | (Nhắc) COMPANY Schema |\n| 36 | (Nhắc) Instance EMPLOYEE + DEPARTMENT |\n| 37 | (Nhắc) Instance còn lại |\n| 38 | JOIN — kết quả DEPT_MGR |\n| 39 | JOIN — dạng tổng quát |\n| 40 | JOIN — properties |\n| 41 | Theta-join + tương đương σ(R × S) |\n| 42 | Theta-join — ví dụ R ⋈_R.A>T.A T |\n| 43 | EQUIJOIN — định nghĩa |\n| 44 | EQUIJOIN — ví dụ R ⋈_R.A=S.A S |\n| 45 | NATURAL JOIN — định nghĩa |\n| 46 | NATURAL JOIN — ví dụ R * T |\n| 47 | Bối cảnh ρ DEPARTMENT → DEPT |\n| 48 | Figure 6.7(a) — PROJ_DEPT |\n| 49 | Bối cảnh DEPT_LOCS |\n| 50 | Figure 6.7(b) — DEPT_LOCS |\n| 51 | Complete set {σ, π, ∪, −, ×} |\n| 52 | DIVISION — định nghĩa |\n| 53 | DIVISION — ví dụ SSN_PNOS ÷ SMITH_PNOS + R÷S tổng quát |\n| 54–55 | Table 6.1 — Operations of Relational Algebra |\n| 56 | Notation for Query Trees |\n| 57 | (Nhắc) Instance EMPLOYEE/DEPT/PROJECT |\n| 58 | Query tree Q2 (Stafford) |\n| 59 | Contents — section 4 highlight |\n| 60 | Aggregate Functions and Grouping — overview |\n| 61 | Functional operator 𝓕 — examples |\n| 62 | Aggregate — bảng giả định Step 1 |\n| 63 | Aggregate — Step 2 (group by Dno) |\n| 64 | Aggregate — Step 3 (compute count + sum) |\n| 65 | Aggregate không grouping — COUNT, SUM, MAX |\n| 66 | Figure 6.10 — Aggregate trên COMPANY |\n| 67 | Recursive closure |\n| 68 | OUTER JOIN — overview |\n| 69 | LEFT/RIGHT/FULL OUTER JOIN |\n| 70 | (Nhắc) Instance EMPLOYEE/DEPT — bài toán LEFT OUTER |\n| 71 | LEFT OUTER JOIN — biểu thức |\n| 72 | Figure 6.12 — kết quả LEFT OUTER trên COMPANY |\n| 73 | Ví dụ tổng quát LEFT OUTER JOIN |\n| 74 | Ví dụ tổng quát RIGHT OUTER JOIN |\n| 75 | Ví dụ tổng quát FULL OUTER JOIN |\n| 76 | Contents — section 5 highlight |\n| 77 | Relational Calculus — overview, procedural vs nonprocedural |\n| 78 | Tuple Calculus — định nghĩa + ví dụ Salary>50000 |\n| 79 | Quantifiers ∀ và ∃, bound/free |\n| 80 | Tuple Calculus Example 1 — Research |\n| 81 | Tuple Calculus Example 2 — all projects of Dnum=5 |\n| 82 | Domain Calculus — overview + QBE |\n| 83 | Domain Calculus Example — John B. Smith |\n| 84 | Contents — final |\n| 85 | Q&A — kết chương |\n\n---\n\n","file":"materials/DB-Chapter5.md","section":13},{"id":"c5-14","group":"c5","kind":"source","title":"🎯 Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## 🎯 Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\n### Trắc nghiệm (15 điểm hay xuất hiện)\n\n1. **σ vs π**: cắt hàng vs cắt cột.\n2. **Tính giao hoán:** σ ✅ giao hoán; π ❌; − ❌; ⋈ INNER ✅; OUTER JOIN ❌.\n3. **Type compatibility:** ∪/∩/− cần; × và ⋈ KHÔNG cần.\n4. **Số tuple kết quả:** |σ_C(R)| ≤ |R|; |π_L(R)| ≤ |R|; |R × S| = |R|·|S|; |R ⋈ S| ≤ |R|·|S|.\n5. **π loại trùng tự động;** SQL không loại trừ khi DISTINCT.\n6. **Complete set** = {σ, π, ∪, −, ×}.\n7. **⋈ ≡ σ_θ(R × S).**\n8. **DIVISION ↔ pattern \"với mọi\"** ↔ SQL `WHERE NOT EXISTS … NOT EXISTS …`.\n9. **NATURAL JOIN** bỏ cột trùng; **EQUIJOIN** giữ cả 2.\n10. **Aggregate cần phép mới (𝓕)** — RA cơ bản không tính được tổng/đếm.\n11. **OUTER JOIN** giữ tuple không match, padding NULL.\n12. **Recursive closure** không có trong RA cơ bản; cần SQL3 `WITH RECURSIVE`.\n13. **Calculus = non-procedural;** RA = procedural.\n14. **3 ngôn ngữ tương đương biểu đạt:** RA ≡ Tuple Calculus ≡ Domain Calculus.\n15. **Query tree:** lá = relation, nội = phép, gốc = kết quả; optimizer push σ xuống lá.\n\n### Tự luận (3–4 dạng đề chính)\n\n**Dạng A — Cho schema + đề câu hỏi tự nhiên:** \"Tên các nhân viên có ít nhất 1 dependent là Spouse\" → viết RA + SQL.\n\n**Dạng B — Cho biểu thức RA, vẽ query tree** + giải thích thứ tự thực thi.\n\n**Dạng C — Chuyển đổi:** RA ↔ SQL ↔ Tuple Calculus.\n\n**Dạng D — DIVISION:** \"Tìm X làm trên *tất cả* Y\" → viết RA dùng ÷ + SQL double NOT EXISTS.\n\n---\n\n","file":"materials/DB-Chapter5.md","section":14},{"id":"c5-15","group":"c5","kind":"source","title":"✅ Đáp án Tự kiểm tra","markdown":"## ✅ Đáp án Tự kiểm tra\n\n### Section 1.1 (SELECT)\n\n1. `σ_Sex='F' AND Salary≥25000 (EMPLOYEE)` → 3 tuple: Zelaya (25 000), Wallace (43 000), English (25 000).\n2. **Bằng nhau** — distributive σ qua ∪.\n3. σ kiểm tra Boolean trên *từng tuple*, không thay đổi tập cột.\n\n### Section 1.2 (PROJECT)\n\n1. `π_Dno (EMPLOYEE)` = 3 tuple {1, 4, 5} (8 nhân viên thuộc 3 phòng → loại trùng).\n2. Có 2 nhân viên cùng lương → loại trùng (vd 25 000 xuất hiện 3 lần — Zelaya, English, Jabbar).\n3. **Đúng** — vì list2 = {A, B, C} ⊇ list1 = {A, B}.\n\n### Section 1 (tổng kết)\n\n1. `σ_Salary>30000(EMPLOYEE)` giữ schema EMPLOYEE; số tuple từ 8 → ?  Đếm: Wong 40k, Wallace 43k, Narayan 38k, Borg 55k → 4 tuple.\n2. `π_Sex,Salary(EMPLOYEE)`: bộ (Sex, Salary) có thể trùng nên loại còn 7 tuple thay vì 8.\n3. RA: `π_Fname,Lname (σ_Dno=4 (EMPLOYEE))`. SQL: `SELECT DISTINCT Fname, Lname FROM EMPLOYEE WHERE Dno=4;`. → 3 tuple: Zelaya, Wallace, Jabbar.\n\n### Section 2\n\n1. `EMPLOYEE ∪ DEPARTMENT` không hợp lệ — 10 cột vs 4 cột → khác số attribute.\n2. `π_Essn(WORKS_ON) − ρ_(Essn)(π_Essn(DEPENDENT))` (đổi tên cột nếu cần để type-compatible).\n3. |EMP × DEPT| = 8 × 3 = 24.\n\n### Section 3\n\n1. **Theta:** `R ⋈_Salary>40000 EMP`. **Equi:** `EMP ⋈_Dno=Dnumber DEPT` (giữ cả 2). **Natural:** sau khi ρ Dnumber→Dno, `EMP * DEPT` (1 cột Dno).\n2. NJ ngầm match cột cùng tên → đó là cách nó tự xác định join condition.\n3. **DIVISION** — vì có universal quantifier \"*mọi*\".\n\n### Section 4\n\n1. RA: `Pno 𝓕_SUM Hours (WORKS_ON)`. SQL:\n   ```sql\n   SELECT Pno, SUM(Hours) FROM WORKS_ON GROUP BY Pno;\n   ```\n2. **Có** — R ⟕ S = S ⟖ R (đối xứng theo định nghĩa).\n3. Khi cần báo cáo phải giữ *cả 2 bên* — vd \"danh sách sinh viên tất cả + môn họ đăng ký, kể cả SV chưa đăng ký môn nào HOẶC môn chưa có SV nào\".\n\n### Section 5\n\n1. **Non-procedural.**\n2. Tuple cal: biến trên *tuple* (cả dòng); Domain cal: biến trên *giá trị* từng cột.\n3. ∀ ↔ double NOT EXISTS; ∃ ↔ EXISTS / IN.\n\n---\n\n","file":"materials/DB-Chapter5.md","section":15},{"id":"c5-16","group":"c5","kind":"source","title":"🔁 Mối Quan Hệ Với Các Chương Khác","markdown":"## 🔁 Mối Quan Hệ Với Các Chương Khác\n\n- **Chương 4 (Relational Data Model & Mapping) — chương trước:**\n  - Cung cấp khái niệm relation, schema, instance, key, FK — *nguyên liệu* cho RA.\n  - Mapping ER → Relational tạo schema COMPANY mà chương 5 dùng làm ví dụ.\n\n- **Chương 6 (SQL) — chương sau:**\n  - Mỗi phép RA tương ứng 1 mệnh đề SQL: σ ↔ WHERE, π ↔ SELECT (DISTINCT), × ↔ FROM A, B, ⋈ ↔ JOIN ON, ∪ ↔ UNION, ∩ ↔ INTERSECT, − ↔ EXCEPT, 𝓕 ↔ GROUP BY + agg, ⟕/⟖/⟗ ↔ LEFT/RIGHT/FULL OUTER JOIN, ÷ ↔ double NOT EXISTS.\n  - **RA là *foundation* để hiểu *vì sao* SQL viết như thế.**\n\n- **Chương 7 (Functional Dependencies & Normalization):**\n  - Khi hiểu JOIN (đặc biệt natural join và spurious tuples), bạn sẽ hiểu vì sao decomposition phải *lossless* — đây là chìa khóa của normalization.\n\n- **Chương 8 (Storage & Indexing):**\n  - RA là ngôn ngữ optimizer dùng để *biến đổi cây* truy vấn thành kế hoạch thực thi tốt hơn.\n  - Index (B+ tree, hash) giúp σ/⋈ chạy nhanh.\n\n- **Liên hệ Lab/BTL:** xem section \"Liên kết Lab / BTL\" ở trên.\n\n---\n\n","file":"materials/DB-Chapter5.md","section":16},{"id":"c5-17","group":"c5","kind":"source","title":"✅ Checklist Tổng hợp Cuối Cùng","markdown":"## ✅ Checklist Tổng hợp Cuối Cùng\n\n### Nội dung\n\n| Hạng mục | PDF gốc | Bản tổng hợp | Khớp? |\n|---|---:|---:|:---:|\n| Tổng số slide | 85 | 85 (đã gộp 7 slide Contents) | ✅ |\n| ER/EER/Schema diagram | 2 (slide 6, 35) | 1 Mermaid + bảng PK/FK | ✅ |\n| Bảng instance/comparison | 9 | 9 + Table 6.1 hợp nhất | ✅ |\n| Ví dụ + bài tập mẫu | ~24 | 24 + 7 mini-bài tập có lời giải | ✅ |\n| SQL code | 0 (slide gốc) | 25+ đoạn SQL tương đương | ✅ (bổ sung pedagogical) |\n| Công thức RA | ~30 | Tất cả + giải thích | ✅ |\n| Định nghĩa formal | ~15 | 37 thuật ngữ glossary | ✅ |\n| Câu hỏi ôn tập từ slide | 24 (ngầm) | 24 + 7 mini-bài + 15 trắc nghiệm | ✅ |\n\n### Sư phạm\n\n| Hạng mục | Đếm | Yêu cầu | Đạt? |\n|---|---:|---|:---:|\n| Concept có \"Tại sao\" (SP-1) | 11 | = số concept lớn | ✅ |\n| Ví dụ COMPANY | 30+ | ≥ 1 per concept trừu tượng | ✅ |\n| Analogy đời thường (SP-4) | 12+ | ≥ 1 per concept khó | ✅ |\n| Block \"Tóm lại section\" (SP-5) | 11 | = số section đánh số | ✅ |\n| Câu hỏi tự kiểm tra | 30+ | ≥ 2 per section | ✅ |\n| Scaffolding nối section | ✅ | Bắt buộc | ✅ |\n| Thuật ngữ EN + VN | ✅ | Bắt buộc | ✅ |\n\n### Riêng cho TỰ HỌC\n\n| Hạng mục | Đạt? |\n|---|:---:|\n| 0.1 Prerequisite | ✅ |\n| 0.2 Learning Outcomes | ✅ |\n| 0.3 Lộ trình đọc | ✅ |\n| Bảng tra nhanh cuối chương | ✅ |\n| Sai lầm thường gặp | ✅ (12 lỗi) |\n| Mini bài tập tự luyện có lời giải | ✅ (7 bài) |\n| Liên kết Lab/BTL | ✅ |\n| Mọi concept trừu tượng có analogy | ✅ |\n| Slide-by-slide index | ✅ |\n| **SV mất gốc đọc sẽ hiểu được?** | ✅ |\n\n> 🎯 **Trạng thái:** Bản tổng hợp hoàn chỉnh — đáp ứng mục tiêu vàng của hệ thống prompt: SV năm 2 chưa từng học CSDL có thể đọc một mạch và hiểu toàn bộ Chương 5, làm được bài tập từ slide, sẵn sàng cho lab và thi cuối kỳ.\n","file":"materials/DB-Chapter5.md","section":17},{"id":"guide-5","group":"c5","kind":"guide","title":"Đại số quan hệ","markdown":"# 05 · Đại số quan hệ: nhìn từng bảng trung gian\n\n> Đọc cùng **DB-Chapter5.md**. Trước khi rút gọn biểu thức, hãy xác định cột đầu ra, điều kiện lọc và đường nối.\n\n![Selection, projection và join qua bảng dữ liệu](../docs/assets/algebra.svg)\n\n## Dịch một câu tiếng Việt thành kế hoạch tính\n\n“Tên nhân viên phòng Research” cần EMPLOYEE và DEPARTMENT. Chúng nối qua `Dno = Dnumber`, không qua tên cột giống nhau.\n\n$$\\pi_{Fname,Lname}\\left(\\sigma_{Dname='Research'}(EMPLOYEE\\bowtie_{Dno=Dnumber}DEPARTMENT)\\right)$$\n\nBước 1 nối nhân viên với phòng; bước 2 giữ hàng Research; bước 3 chỉ giữ tên. Có thể đẩy selection trên Dname xuống DEPARTMENT trước khi join. Điều này giữ cùng kết quả với inner join trong ví dụ này và có thể giảm dữ liệu trung gian; optimizer thực tế quyết định execution plan.\n\n```sql\nSELECT DISTINCT e.Fname, e.Lname\nFROM EMPLOYEE AS e JOIN DEPARTMENT AS d ON e.Dno=d.Dnumber\nWHERE d.Dname='Research' ORDER BY e.Fname;\n```\n\n`DISTINCT` phản ánh projection theo **set semantics**. SQL mặc định là bag: hai nhân viên khác nhau có cùng tên vẫn có thể tạo hai dòng giống nhau nếu không DISTINCT. Khi cần giữ định danh, project thêm Ssn.\n\n## Bộ dữ liệu nhỏ để không bị ký hiệu che mất ý nghĩa\n\n| R.Student | R.Course |\n|---|---|\n| An | DB |\n| An | AI |\n| Bình | DB |\n\nVới S(Course) = {DB, AI}, `R ÷ S` trả {An}. Không phải “An có số dòng lớn nhất”, mà vì An có quan hệ với **mọi** course trong S.\n\n```sql\n-- Nhân viên làm TẤT CẢ dự án do phòng 5 quản lý.\nSELECT e.Fname\nFROM EMPLOYEE AS e\nWHERE NOT EXISTS (\n SELECT 1 FROM PROJECT AS p\n WHERE p.Dnum=5 AND NOT EXISTS (\n  SELECT 1 FROM WORKS_ON AS w WHERE w.Essn=e.Ssn AND w.Pno=p.Pnumber\n )\n) ORDER BY e.Fname;\n```\n\nFixture không có ai làm đủ cả 3 dự án của phòng 5, nên kết quả rỗng. Nếu chỉ xét các dự án 1 và 2 thì John và Joyce thỏa. Hãy kiểm tra **một phản ví dụ**: Franklin không làm dự án 1 nên bị loại, dù Franklin là trưởng Research.\n\n## “Không có” khác “có một cái không thỏa”\n\n“Không làm dự án nào ở Houston” là lấy tất cả nhân viên **trừ** những người làm ít nhất một dự án ở Houston. Không thể lấy “nhân viên có dự án ngoài Houston”: một người có thể làm cả hai nơi.\n\nTrong relational calculus, mẫu “với mọi” được đổi thành “không tồn tại phản ví dụ”. Đây là nền tảng của double NOT EXISTS. Biểu thức calculus còn phải **safe/range restricted** để không phụ thuộc một miền vô hạn ngoài database.\n\n## Natural join phải biết nó đang nối cột nào\n\nEMPLOYEE có `Dno`, DEPARTMENT có `Dnumber`; natural join không hiểu đây là FK. Nếu không có tên cột chung, natural join trở thành tích Descartes. Nếu có cột chung nhưng sai ngữ nghĩa, nó có thể lọc mất hàng ngoài dự kiến. Trong code ứng dụng, viết `JOIN ... ON` thường giúp review điều kiện rõ hơn.\n\n| Toán tử | Kiểm tra trước khi dùng |\n|---|---|\n| Union / difference / intersection | Hai đầu vào union-compatible |\n| Cartesian product | Có bao nhiêu cặp? `|R| × |S|` |\n| Theta join | Điều kiện nối cụ thể là gì? |\n| Projection | Đã loại trùng theo set semantics chưa? |\n| Division | Tập yêu cầu “mọi” nằm ở quan hệ nào? |\n\n## Bài tập\n\n1. Với R ở trên, projection Course có bao nhiêu dòng trong RA? SQL SELECT thường có bao nhiêu?\n2. Viết “nhân viên chưa được phân công dự án nào”.\n3. Nếu tập dự án yêu cầu rỗng, double NOT EXISTS trả ai?\n\n<details><summary>Lời giải</summary>\n\n1. RA có 2 tuple: DB và AI. SQL không DISTINCT có 3 dòng.\n2. Dùng `NOT EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn)`; fixture trả Mai.\n3. Trả mọi nhân viên trong tập ứng viên EMPLOYEE: không có phản ví dụ trong tập rỗng. Lưu ý division thuần thường lấy tập ứng viên từ projection của quan hệ bị chia; SQL lấy từ EMPLOYEE có thể bao gồm cả người chưa xuất hiện trong WORKS_ON.\n\n</details>\n","file":"lessons/05-algebra.md"},{"id":"c6-00","group":"c6","kind":"source","title":"Chương 6: Ngôn ngữ Truy vấn Có Cấu trúc — Structured Query Language (SQL)","markdown":"# Chương 6: Ngôn ngữ Truy vấn Có Cấu trúc — Structured Query Language (SQL)\n\n> Nguồn: CO2013 Database Systems, HCMUT — Giảng viên: TS. Trần Minh Quang\n> Giáo trình: Elmasri & Navathe, 7th Edition (phần SQL: Chapter 6, 7)\n> File PDF gốc: `Lectures/06_SQL.pdf`\n> Số slide trong PDF gốc: **114 slide**\n> Đã gộp slide Contents lặp lại: **slide 2, 3, 5, 27, 80, 98** đều là slide Contents — gộp chung thành mục lục ở đầu chương.\n> COMPANY schema xuất hiện lặp ở **slide 7, 18, 32, 35, 37, 53** — gộp chung thành 1 mô tả + Mermaid + ASCII.\n> Tên thuộc tính trong slide đôi khi xen kẽ `Super_ssn`/`SuperSSN`, `Mgr_ssn`/`MgrSSN`, `Ssn`/`SSN`. Bản này giữ nguyên tên đúng theo slide khi trích code; khi nói khái niệm, dùng tên chuẩn COMPANY: `Fname, Minit, Lname, Ssn, Bdate, Address, Sex, Salary, Super_ssn, Dno` (EMPLOYEE), `Dname, Dnumber, Mgr_ssn, Mgr_start_date` (DEPARTMENT), v.v.\n\n---\n\n","file":"materials/DB-Chapter6.md","section":0},{"id":"c6-01","group":"c6","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nĐể hiểu chương 6 (SQL), bạn cần nhớ lại các khái niệm sau từ các chương trước. Nếu chưa học, đọc 2-3 câu sau cũng đủ để bám theo chương này.\n\n| Kiến thức nền | Nhắc lại thật ngắn | Liên hệ với SQL |\n|---|---|---|\n| **Relation (quan hệ / bảng)** | Bảng 2 chiều có tên, gồm các tuple (hàng) và attribute (cột). | SQL thao tác chủ yếu trên table. |\n| **Tuple (bộ / hàng)** | Một dòng dữ liệu. | `INSERT`, `DELETE`, `UPDATE`, `SELECT` xử lý tuple. |\n| **Attribute (thuộc tính / cột)** | Một cột của bảng. | `SELECT Salary`, `WHERE Salary > 30000`. |\n| **Domain (miền / kiểu)** | Tập giá trị hợp lệ của thuộc tính. | `INT`, `VARCHAR(15)`, `DATE`, `CHECK`. |\n| **Primary Key (khóa chính)** | Định danh duy nhất tuple. Không cho NULL. | `PRIMARY KEY (Ssn)`. |\n| **Foreign Key (khóa ngoại)** | Cột ở bảng con trỏ tới khóa chính ở bảng cha. | `FOREIGN KEY (Dno) REFERENCES Department(Dnumber)`. |\n| **Entity Integrity** | Khóa chính không được NULL. | DBMS tự kiểm tra khi khai báo `PRIMARY KEY`. |\n| **Referential Integrity** | Khóa ngoại phải trỏ tới tuple đang tồn tại (hoặc NULL nếu được phép). | `ON DELETE`, `ON UPDATE`, `CASCADE`, `SET NULL`. |\n| **Relational Algebra (Chương 5)** | Ngôn ngữ hình thức: σ, π, ⋈, ∪, ∩, −. | `SELECT-FROM-WHERE` là cách SQL hiện thực ý tưởng của RA. |\n| **Cartesian Product** | `R × S` = ghép MỌI dòng R với MỌI dòng S. | SQL gọi đây là `FROM R, S` không có điều kiện join. |\n| **COMPANY database** | 6 bảng: EMPLOYEE, DEPARTMENT, DEPT_LOCATIONS, PROJECT, WORKS_ON, DEPENDENT. | Schema chạy xuyên suốt mọi ví dụ. |\n\n> 💡 **Hiểu đơn giản:** Nếu ER diagram là bản vẽ thiết kế nhà, relational schema là bản vẽ kỹ thuật, thì **SQL là bộ câu lệnh để xây nhà, sửa nhà, lấy đồ trong nhà, phân quyền ai được vào phòng nào**.\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\nSau khi đọc xong chương 6, bạn phải có khả năng:\n\n1. **Giải thích** SQL là gì và vì sao SQL là ngôn ngữ chuẩn cho relational database.\n2. **Phân biệt** 3 nhóm lệnh: DDL (CREATE/ALTER/DROP), DML (SELECT/INSERT/UPDATE/DELETE), DCL (GRANT/REVOKE/COMMIT/ROLLBACK).\n3. **Viết câu lệnh CREATE TABLE** đầy đủ với primary key, foreign key, các loại ràng buộc (NOT NULL, UNIQUE, CHECK, DEFAULT), và 4 referential actions (CASCADE/SET NULL/SET DEFAULT/RESTRICT).\n4. **Dùng ALTER/DROP** với CASCADE/RESTRICT cho schema/table/constraint.\n5. **Viết truy vấn SELECT** từ đơn giản (1 bảng) đến phức tạp: nhiều bảng (JOIN), subquery, GROUP BY/HAVING, ORDER BY, các phép tập hợp (UNION/EXCEPT/INTERSECT).\n6. **Hiểu & sử dụng đúng** các operator: IN, EXISTS, NOT EXISTS, ANY/ALL/SOME, LIKE, IS NULL.\n7. **Dùng aggregate** (COUNT/SUM/AVG/MIN/MAX) và phân biệt khi nào dùng WHERE vs HAVING.\n8. **Viết JOIN syntax mới** (INNER, NATURAL, LEFT/RIGHT/FULL OUTER) và phân biệt với cú pháp join cũ qua WHERE.\n9. **Viết INSERT/UPDATE/DELETE** bao gồm cả INSERT từ SELECT.\n10. **Định nghĩa & sử dụng View** (CREATE VIEW), hiểu WITH CHECK OPTION, biết khi nào view là updatable.\n11. **Phân biệt** ASSERTION với CHECK và biết tại sao cần ASSERTION.\n12. **Cấp & thu hồi quyền** bằng GRANT/REVOKE, hiểu WITH GRANT OPTION và sự lan truyền (cascade) khi REVOKE.\n13. **Ánh xạ** câu lệnh SQL ↔ phép toán Relational Algebra tương ứng.\n\n### 0.3. Lộ trình đọc đề xuất\n\nChương 6 là chương **DÀI NHẤT** và **QUAN TRỌNG NHẤT** của môn — kiến thức trực tiếp cho BTL2, Lab 1+2, và phần lớn đề thi cuối kỳ. Đề xuất chia 4 buổi tự học:\n\n| Buổi | Section | Mức độ | Thời gian |\n|---|---|---|---|\n| **Buổi 1** | 1 (Intro) + 2 (DDL: CREATE/ALTER/DROP, constraints) | CORE | ~3h |\n| **Buổi 2** | 3.1–3.17 (SELECT cơ bản, FROM, WHERE, JOIN qua WHERE, *, DISTINCT, LIKE, NULL, UNION) | CORE | ~4h |\n| **Buổi 3** | 3.18–3.37 (Nested queries, IN/EXISTS/ANY/ALL, JOIN syntax mới, OUTER JOIN, Aggregate, GROUP BY, HAVING, ORDER BY) | CORE | ~4h |\n| **Buổi 4** | 4 (INSERT/UPDATE/DELETE) + 5 (Assertions & Triggers) + 6 (Views) + 7 (DCL) + tự luyện | CORE cho View; NÂNG CAO cho Trigger/DCL | ~3h |\n\n> 💡 **Mẹo học SQL hiệu quả:** Mỗi query trong chương — **gõ tay lại trên DBMS thật** (PostgreSQL/MySQL/SQL Server) với schema COMPANY. Đọc thôi sẽ quên 80% sau 1 tuần; gõ lại 5 lần sẽ nhớ. Lab 1 và 2 chính là phần thực hành này.\n\n### Mục lục gộp từ các slide Contents (slide 2, 3, 5, 27, 80, 98)\n\nCác slide Contents của chương liệt kê 4 phần chính (slide 98 ghi thêm \"Chapter 9 + homework\" cho mục 4):\n\n1. **Introduction of Structured Query Language**\n2. **DDL: create, drop, alter**\n3. **DML: select, insert, update, delete**\n4. **DCL: commit, rollback, grant, revoke** *(Chapter 9 + homework)*\n\n---\n\n","file":"materials/DB-Chapter6.md","section":1},{"id":"c6-02","group":"c6","kind":"source","title":"1. Introduction of Structured Query Language","markdown":"## 1. Introduction of Structured Query Language\n\n### 1.1. Tại sao cần SQL? (Motivation)\n\nỞ chương mô hình quan hệ, ta đã có các bảng như `EMPLOYEE`, `DEPARTMENT`, `PROJECT`. Nhưng chỉ có bảng trên giấy thì chưa đủ — ta cần một ngôn ngữ để nói với DBMS rằng: \"hãy tạo bảng này\", \"hãy lấy nhân viên phòng Research\", \"hãy tăng lương\", \"hãy cấp quyền cho user khác\". Nếu mỗi DBMS tự nghĩ ra một ngôn ngữ riêng, người học và lập trình viên sẽ rất khó chuyển đổi giữa các hệ thống. **SQL ra đời (IBM, 1974, tên gốc SEQUEL) như ngôn ngữ chuẩn để định nghĩa, truy vấn, cập nhật và điều khiển relational database**, được chuẩn hóa qua các phiên bản SQL-86 → SQL-92 → SQL:1999 → ... → SQL:2023.\n\n> 💡 **Hiểu đơn giản:** SQL giống như **tiếng Anh** trong thế giới các DBMS. Bạn nói \"tôi muốn các nhân viên ở phòng Research\", thì Oracle, MySQL, PostgreSQL đều hiểu. Còn Relational Algebra giống **tiếng Latin** — chính xác, đẹp về mặt khoa học, nhưng không ai dùng để nói thường ngày.\n\n### 1.2. SQL là gì? (Slide 4)\n\n> **Structured Query Language (SQL)** là một ngôn ngữ máy tính **chuẩn** dùng cho **quản lý cơ sở dữ liệu quan hệ** (relational database management) và **thao tác dữ liệu** (data manipulation).\n\n**Basic SQL** gồm 3 nhóm:\n\n| Nhóm | Tên đầy đủ | Các câu lệnh | Mục đích |\n|---|---|---|---|\n| **DDL** | Data Definition Language (Ngôn ngữ Định nghĩa Dữ liệu) | CREATE, ALTER, DROP | Định nghĩa **cấu trúc** — tạo/sửa/xóa bảng, ràng buộc, schema |\n| **DML** | Data Manipulation Language (Ngôn ngữ Thao tác Dữ liệu) | SELECT, INSERT, UPDATE, DELETE | **Đọc và sửa** dữ liệu bên trong bảng đã có |\n| **DCL** | Data Control Language (Ngôn ngữ Điều khiển Dữ liệu) | COMMIT, ROLLBACK, GRANT, REVOKE | **Phân quyền & quản lý transaction** |\n\n### 1.3. Bản đồ tư duy SQL\n\n```mermaid\nflowchart TD\n    SQL[SQL - Structured Query Language]\n    SQL --> DDL[DDL - Data Definition]\n    SQL --> DML[DML - Data Manipulation]\n    SQL --> DCL[DCL - Data Control]\n\n    DDL --> CREATE[CREATE]\n    DDL --> ALTER[ALTER]\n    DDL --> DROP[DROP]\n\n    DML --> SELECT[SELECT]\n    DML --> INSERT[INSERT]\n    DML --> UPDATE[UPDATE]\n    DML --> DELETE[DELETE]\n\n    DCL --> COMMIT[COMMIT]\n    DCL --> ROLLBACK[ROLLBACK]\n    DCL --> GRANT[GRANT]\n    DCL --> REVOKE[REVOKE]\n```\n\n> 📊 **Đọc diagram này thế nào:** SQL là gốc. Từ SQL tách thành 3 nhóm. DDL \"xây cấu trúc\", DML \"lấy và sửa dữ liệu\", DCL \"quyền và kiểm soát\". Đề thi thường hỏi phân biệt lệnh nào thuộc nhóm nào.\n\n### 1.4. Ví dụ với COMPANY database\n\n> 💡 **Ví dụ 1.1 — Phân loại câu lệnh SQL**\n> Giả sử có COMPANY database. Phân loại các nhu cầu:\n>\n> | Nhu cầu | Lệnh SQL | Nhóm |\n> |---|---|---|\n> | Tạo bảng `EMPLOYEE` | `CREATE TABLE Employee (...)` | DDL |\n> | Lấy tên nhân viên phòng Research | `SELECT ... FROM ... WHERE ...` | DML |\n> | Tăng lương nhân viên phòng 5 | `UPDATE Employee SET Salary = ...` | DML |\n> | Cấp quyền đọc bảng | `GRANT SELECT ON Employee TO A3` | DCL |\n\n### 1.5. Analogy\n\n> 💡 **Hiểu đơn giản:** SQL là bộ câu lệnh điều hành một thư viện. **DDL = xây kệ + đặt quy tắc kệ**; **DML = tìm/thêm/xóa/sửa sách**; **DCL = cấp thẻ thư viện + phân quyền mượn sách**.\n\n> 📝 **Tóm lại section 1 — Introduction of SQL:**\n> - SQL là **ngôn ngữ chuẩn** cho RDBMS (ra đời từ IBM thập niên 70, chuẩn ISO/ANSI).\n> - SQL gồm **3 nhóm**: DDL (cấu trúc), DML (dữ liệu), DCL (quyền/transaction).\n> - Chương này đi từ tạo cấu trúc → truy vấn/cập nhật dữ liệu → view → phân quyền.\n> **Một câu ghi nhớ:** *SQL là cầu nối giữa mô hình quan hệ trên giấy và database chạy thật trong DBMS.*\n\n> ❓ **Tự kiểm tra section 1:**\n> 1. SQL là gì? Vì sao gọi là \"chuẩn\"?\n> 2. `CREATE TABLE` thuộc DDL, DML hay DCL?\n> 3. Trong COMPANY database, nếu muốn lấy danh sách nhân viên, em dùng nhóm lệnh nào?\n\n---\n\n","file":"materials/DB-Chapter6.md","section":2},{"id":"c6-03","group":"c6","kind":"source","title":"2. DDL — Data Definition Language","markdown":"## 2. DDL — Data Definition Language\n\nSection 1 vừa giới thiệu SQL có 3 nhóm. Câu hỏi tự nhiên tiếp theo là: **trước khi truy vấn được dữ liệu, làm sao tạo ra cấu trúc bảng và ràng buộc cho database?** Đó là DDL.\n\n### 2.1. Tại sao cần DDL? (Motivation)\n\nNếu ta chỉ có dữ liệu rời rạc như file Excel không ràng buộc, người dùng có thể nhập `Salary='abc'`, nhập nhân viên không có Ssn, hoặc gán `Dno=999` dù không có department 999. Dữ liệu lúc này rất dễ sai và chương trình phía sau sẽ bị lỗi. **DDL cho phép ta định nghĩa trước hình dạng và luật của database**: bảng gồm cột nào, kiểu dữ liệu gì, cột nào không được rỗng, khóa chính là gì, khóa ngoại trỏ đi đâu.\n\nVí dụ đời thường: trước khi trường mở cổng đăng ký môn học, trường phải định nghĩa danh mục môn, mã môn, số tín chỉ, môn tiên quyết. Nếu không có \"khung luật\", sinh viên có thể đăng ký mã môn không tồn tại hoặc nhập số tín chỉ âm.\n\n### 2.2. Slide 6 — DDL là gì?\n\n> Data Definition Language (DDL) cho phép đặc tả:\n> - **Kiểu dữ liệu** (data types)\n> - **Cấu trúc** (structures)\n> - **Các ràng buộc** (data constraints)\n>\n> Mọi đặc tả được **lưu trong database** (catalog/data dictionary).\n>\n> DDL gồm:\n> - **CREATE**: tạo mới (database, table, index, user, stored query, ...)\n> - **ALTER**: sửa đổi đối tượng đã có\n> - **DROP**: hủy bỏ đối tượng đã có\n\n> 💡 **Hiểu đơn giản:** Ba lệnh CREATE/ALTER/DROP giống như **xây/sửa/phá** một ngôi nhà.\n\n### 2.3. COMPANY Database — Schema chạy xuyên môn (Slide 7, 18, 32, 35, 37, 53)\n\n#### 2.3.1. Bảng tóm tắt các relation\n\n| Relation | Attributes | Primary Key | Foreign Keys / liên hệ |\n|---|---|---|---|\n| `EMPLOYEE` | Fname, Minit, Lname, Ssn, Bdate, Address, Sex, Salary, Super_ssn, Dno | Ssn | Super_ssn → EMPLOYEE(Ssn); Dno → DEPARTMENT(Dnumber) |\n| `DEPARTMENT` | Dname, Dnumber, Mgr_ssn, Mgr_start_date | Dnumber | Mgr_ssn → EMPLOYEE(Ssn) |\n| `DEPT_LOCATIONS` | Dnumber, Dlocation | (Dnumber, Dlocation) | Dnumber → DEPARTMENT(Dnumber) |\n| `PROJECT` | Pname, Pnumber, Plocation, Dnum | Pnumber | Dnum → DEPARTMENT(Dnumber) |\n| `WORKS_ON` | Essn, Pno, Hours | (Essn, Pno) | Essn → EMPLOYEE(Ssn); Pno → PROJECT(Pnumber) |\n| `DEPENDENT` | Essn, Dependent_name, Sex, Bdate, Relationship | (Essn, Dependent_name) | Essn → EMPLOYEE(Ssn) |\n\n#### 2.3.2. ER-style diagram (Mermaid)\n\n```mermaid\nerDiagram\n    EMPLOYEE {\n        VARCHAR Fname\n        CHAR Minit\n        VARCHAR Lname\n        CHAR Ssn PK\n        DATE Bdate\n        VARCHAR Address\n        CHAR Sex\n        DECIMAL Salary\n        CHAR Super_ssn FK\n        INT Dno FK\n    }\n    DEPARTMENT {\n        VARCHAR Dname UK\n        INT Dnumber PK\n        CHAR Mgr_ssn FK\n        DATE Mgr_start_date\n    }\n    DEPT_LOCATIONS {\n        INT Dnumber PK,FK\n        VARCHAR Dlocation PK\n    }\n    PROJECT {\n        VARCHAR Pname UK\n        INT Pnumber PK\n        VARCHAR Plocation\n        INT Dnum FK\n    }\n    WORKS_ON {\n        CHAR Essn PK,FK\n        INT Pno PK,FK\n        DECIMAL Hours\n    }\n    DEPENDENT {\n        CHAR Essn PK,FK\n        VARCHAR Dependent_name PK\n        CHAR Sex\n        DATE Bdate\n        VARCHAR Relationship\n    }\n    EMPLOYEE ||--o{ EMPLOYEE : supervises\n    DEPARTMENT ||--o{ EMPLOYEE : has_employees\n    EMPLOYEE ||--o{ DEPARTMENT : manages\n    DEPARTMENT ||--o{ DEPT_LOCATIONS : has_locations\n    DEPARTMENT ||--o{ PROJECT : controls\n    EMPLOYEE ||--o{ WORKS_ON : works\n    PROJECT ||--o{ WORKS_ON : has_workers\n    EMPLOYEE ||--o{ DEPENDENT : has_dependents\n```\n\n#### 2.3.3. ASCII fallback (nếu trình đọc không hỗ trợ Mermaid)\n\n```\nEMPLOYEE\n+-------+-------+-------+-----+-------+---------+-----+--------+-----------+-----+\n| Fname | Minit | Lname | Ssn | Bdate | Address | Sex | Salary | Super_ssn | Dno |\n+-------+-------+-------+-----+-------+---------+-----+--------+-----------+-----+\n                          (PK)                                  (FK→Ssn)   (FK→Dnumber)\n\nDEPARTMENT                           DEPT_LOCATIONS\n+-------+---------+---------+------+ +---------+-----------+\n| Dname | Dnumber | Mgr_ssn | Mgr… | | Dnumber | Dlocation |\n+-------+---------+---------+------+ +---------+-----------+\n            (PK)   (FK→Ssn)             (PK=Dnumber+Dlocation; FK→Dnumber)\n\nPROJECT                              WORKS_ON\n+-------+---------+-----------+----+ +------+-----+-------+\n| Pname | Pnumber | Plocation |Dnum| | Essn | Pno | Hours |\n+-------+---------+-----------+----+ +------+-----+-------+\n             (PK)              (FK)    (PK=(Essn,Pno); FK Essn,Pno)\n\nDEPENDENT\n+------+----------------+-----+-------+--------------+\n| Essn | Dependent_name | Sex | Bdate | Relationship |\n+------+----------------+-----+-------+--------------+\n  (PK=(Essn,Dependent_name); FK Essn)\n```\n\n> 📊 **Đọc diagram này thế nào:**\n> - Cột có `PK` (hoặc gạch chân trong slide gốc) là **Primary Key**.\n> - `FK` là **Foreign Key** trỏ tới bảng cha (mũi tên trong slide gốc).\n> - **EMPLOYEE.Super_ssn → EMPLOYEE.Ssn** là **self-reference** — cấp trên cũng là một nhân viên trong cùng bảng → lý do cần ALIAS khi truy vấn supervisor.\n> - DEPT_LOCATIONS có composite PK `(Dnumber, Dlocation)`.\n\n### 2.4. Schema và Catalog (Slide 8)\n\n> **Schema (lược đồ)**: một nhóm các bảng và construct cùng thuộc về **một ứng dụng CSDL**.\n\n```sql\nCREATE SCHEMA Schema_Name\nAUTHORIZATION Authorization_Identifier;\n```\n\n**Ví dụ COMPANY:**\n```sql\nCREATE SCHEMA Company AUTHORIZATION JSmith;\n```\n\n| Dòng | Ý nghĩa |\n|---|---|\n| `CREATE SCHEMA Company` | Tạo schema tên `Company`. |\n| `AUTHORIZATION JSmith` | Đặt `JSmith` làm owner — chỉ owner mới được tạo bảng bên trong hoặc cấp quyền tiếp. |\n\n**Catalog**: một **tập hợp có tên** các schema.\n\n> 💡 **Hiểu đơn giản:** Catalog = \"tủ tài liệu lớn\". Schema = \"ngăn kéo bên trong tủ\". Table = \"tập hồ sơ bên trong ngăn kéo\". Cùng tên bảng có thể tồn tại ở 2 schema khác nhau mà không xung đột.\n\n### 2.5. CREATE TABLE — Cú pháp tổng quát (Slide 9)\n\n```sql\nCREATE TABLE [SchemaName.]TableName\n{(colName dataType [NOT NULL] [UNIQUE] [PRIMARY KEY]\n   [DEFAULT defaultOption]\n   [CHECK searchCondition] [,...]}\n[PRIMARY KEY (listOfColumns),]\n{[UNIQUE (listOfColumns),] [...,]}\n{[FOREIGN KEY (listOfFKColumns)\n  REFERENCES ParentTableName [(listOfCKColumns)]\n  [ON UPDATE referentialAction]\n  [ON DELETE referentialAction]] [,...]}\n{[CHECK (searchCondition)] [,...] })\n```\n\n**Giải thích từng phần:**\n\n| Thành phần | Ý nghĩa |\n|---|---|\n| `[SchemaName.]TableName` | Tên bảng, có thể có prefix schema. |\n| `(colName dataType ...)` | Định nghĩa **mỗi cột**: tên + kiểu + các ràng buộc inline. |\n| `PRIMARY KEY (listOfColumns)` | Khóa chính cấp bảng — bắt buộc dùng khi PK gồm ≥ 2 cột. |\n| `UNIQUE (listOfColumns)` | Khóa thay thế (alternate/secondary key). |\n| `FOREIGN KEY (...) REFERENCES ...` | Khóa ngoại + hành động khi cha bị update/delete. |\n| `CHECK (searchCondition)` | Ràng buộc biểu thức Boolean. |\n\n> ⚠️ **Note ngữ pháp BNF:** `[...]` là **tùy chọn** (có thể bỏ); `{...}` là **lặp** (0 hoặc nhiều lần).\n\n### 2.6. CREATE TABLE — Base table vs Virtual relation (Slide 10)\n\n| Loại | Đặc điểm |\n|---|---|\n| **Base tables (base relations)** | Tạo bằng `CREATE TABLE` → relation và tuple được **thực sự tạo và lưu thành file** bởi DBMS. |\n| **Virtual relations** | Tạo bằng `CREATE VIEW` → không lưu vật lý, tính on-the-fly. (Section 6) |\n\n**Foreign Key có thể gây lỗi (slide nhắc):**\n- **Circular references** (A trỏ B, B trỏ A) → không thể tạo cả 2 cùng lúc.\n- Trỏ tới bảng **chưa tồn tại** → phải tạo bảng cha trước hoặc dùng `ALTER TABLE ADD FOREIGN KEY` sau.\n\n### 2.7. Basic Data Types (Slide 11–12)\n\n| Loại | Cú pháp | Ghi chú |\n|---|---|---|\n| **Numeric — Integer** | `INTEGER`, `INT`, `SMALLINT` | Số nguyên |\n| **Numeric — Floating point** | `FLOAT`, `REAL`, `DOUBLE PRECISION` | Số thực |\n| **Numeric — Decimal** (xuất hiện trong CREATE TABLE thực tế) | `DECIMAL(p,d)` | Số thập phân chính xác — `p` chữ số tổng, `d` chữ số sau dấu thập phân. Ví dụ `DECIMAL(10,2)` cho lương. |\n| **Character-string — Fixed length** | `CHAR(n)`, `CHARACTER(n)` | Cố định n ký tự, đệm khoảng trắng nếu ngắn hơn |\n| **Character-string — Varying length** | `VARCHAR(n)`, `CHAR VARYING(n)`, `CHARACTER VARYING(n)` | Độ dài thay đổi, tối đa n |\n| **Bit-string — Fixed length** | `BIT(n)` | Chuỗi bit cố định |\n| **Bit-string — Varying length** | `BIT VARYING(n)` | Chuỗi bit độ dài thay đổi |\n| **Boolean** | `BOOLEAN` | TRUE / FALSE / **NULL** (3-valued logic!) |\n| **Date** | `DATE` | YEAR, MONTH, DAY — `'YYYY-MM-DD'` |\n| **Time** | `TIME` | HOUR, MINUTE, SECOND — `'HH:MM:SS'` |\n| **Timestamp** | `TIMESTAMP` | DATE + TIME + ≥ 6 chữ số phần thập phân giây. Có thể `WITH TIME ZONE`. |\n| **Interval** | `INTERVAL` | Giá trị **tương đối** dùng tăng/giảm date/time/timestamp. Ví dụ `INTERVAL '7' DAY`. |\n\n#### Bảng chọn kiểu dữ liệu cho COMPANY\n\n| Attribute | Kiểu trên slide | Lý do |\n|---|---|---|\n| Fname, Lname, Dname, Pname | VARCHAR(15) | Tên có độ dài thay đổi |\n| Minit, Sex | CHAR | Đúng 1 ký tự |\n| Ssn, Super_ssn, Mgr_ssn, Essn | CHAR(9) | SSN cố định 9 ký tự, có thể có số 0 đầu → không dùng INT |\n| Bdate, Mgr_start_date | DATE | Ngày tháng |\n| Salary | DECIMAL(10,2) | Tiền cần 2 chữ số thập phân chính xác |\n| Dno, Dnumber, Pnumber, Pno | INT | Mã số nguyên |\n| Hours | DECIMAL(3,1) | Số giờ có thể có phần thập phân như 32.5 |\n\n> 💡 **Hiểu đơn giản — CHAR vs VARCHAR:** `CHAR(10)` luôn lưu đúng 10 ký tự → tốn cố định 10 byte. `VARCHAR(10)` lưu số ký tự thật + 1-2 byte ghi độ dài → tiết kiệm hơn cho dữ liệu biến thiên. Dùng CHAR cho mã có độ dài cố định (CCCD 12 ký tự); dùng VARCHAR cho tên/địa chỉ.\n\n### 2.8. Domains (Slide 13)\n\n**Domain** là một **tên** đặt cho đặc tả thuộc tính. Lợi ích: dễ thay đổi kiểu chung; tăng tính đọc của schema.\n\n```sql\nCREATE DOMAIN DomainName AS DataType\n[CHECK conditions];\n```\n\n**Ví dụ COMPANY:**\n```sql\nCREATE DOMAIN SSN_TYPE AS CHAR(9);\n\nCREATE DOMAIN D_NUM AS INTEGER\nCHECK (D_NUM > 0 AND D_NUM < 21);\n```\n\n| Dòng | Ý nghĩa |\n|---|---|\n| `CREATE DOMAIN SSN_TYPE AS CHAR(9);` | Đặt tên `SSN_TYPE` cho `CHAR(9)`. Dùng được cho mọi cột SSN/Essn/Mgr_ssn/Super_ssn. |\n| `CREATE DOMAIN D_NUM AS INTEGER CHECK (D_NUM>0 AND D_NUM<21);` | Domain `D_NUM` chỉ chấp nhận 1..20. |\n\n> 💡 **Hiểu đơn giản:** Domain giống **`typedef int DeptNumber;` trong C** — thay vì viết `INT` ở 50 chỗ thì đặt tên một lần, dùng lại; muốn đổi kiểu, sửa 1 chỗ duy nhất.\n\n### 2.9. Specifying Constraints (Slide 14)\n\n3 nhóm ràng buộc cơ bản:\n\n1. **Key & Referential Integrity** — PRIMARY KEY, UNIQUE, FOREIGN KEY.\n2. **Attribute Constraints** — NOT NULL, DEFAULT, CHECK trên 1 thuộc tính.\n3. **Constraints on Individual Tuples** — CHECK trên nhiều thuộc tính của cùng 1 dòng.\n\n#### 2.9.1. PRIMARY KEY & UNIQUE (Slide 15)\n\n```sql\n-- Cách 1: inline (1 cột)\nDnumber INT PRIMARY KEY\n\n-- Cách 2: cấp bảng (1 hoặc nhiều cột — bắt buộc cho composite PK)\nPRIMARY KEY (Dnumber, DLocation)\n\n-- UNIQUE: khóa thay thế\nDname VARCHAR(15) UNIQUE;\n```\n\n> 💡 **Phân biệt PRIMARY KEY vs UNIQUE:**\n> - **PRIMARY KEY**: 1 mỗi bảng, **không cho NULL**, có index ngầm.\n> - **UNIQUE**: nhiều mỗi bảng, **cho phép NULL** (thường 1 NULL, tùy DBMS), có unique index ngầm.\n\n> 💡 **Primary Key ↔ Số CCCD/CMND:** Định danh duy nhất một người trong quốc gia. Trong EMPLOYEE, `Ssn` đóng vai tương tự.\n\n#### 2.9.2. FOREIGN KEY (Slide 16)\n\n```sql\nFOREIGN KEY (listOfFKColumns)\nREFERENCES ParentTableName [(listOfCKColumns)]\n[ON UPDATE referentialAction]\n[ON DELETE referentialAction]\n```\n\n**4 Referential Triggered Actions** khi cha bị update/delete:\n\n| Action | Ý nghĩa |\n|---|---|\n| **RESTRICT** (mặc định) | DBMS **từ chối** thao tác trên cha nếu còn con tham chiếu. |\n| **CASCADE** | **Lan truyền**: xóa/sửa cha → xóa/sửa luôn con. |\n| **SET NULL** | Đặt FK ở con thành NULL (cần cột FK cho phép NULL). |\n| **SET DEFAULT** | Đặt FK ở con về giá trị DEFAULT đã khai báo. |\n\n**Ví dụ COMPANY:**\n```sql\nFOREIGN KEY (Dno) REFERENCES Department(Dnumber)\nON DELETE CASCADE\nON UPDATE CASCADE\n```\n\n> 💡 **Foreign Key ↔ Số CCCD ghi trên hợp đồng thuê nhà:** Hợp đồng không lưu toàn bộ hồ sơ người thuê, mà ghi CCCD để trỏ chính xác tới 1 người trong bảng dân cư. Nếu CCCD không tồn tại → hợp đồng vô nghĩa. Tương tự, `Employee.Dno = 5` chỉ hợp lệ nếu `Department.Dnumber = 5` tồn tại.\n\n> ⚠️ **Cẩn thận CASCADE DELETE trong thực tế:** xóa nguyên một phòng KHÔNG nên kéo theo xóa hết nhân viên (vô lý!). CASCADE chỉ phù hợp khi con thực sự **phụ thuộc tồn tại** vào cha (weak entity). Nghiệp vụ thường hợp lý hơn với `SET NULL` hoặc `RESTRICT`.\n\n#### 2.9.3. Attribute Constraints (Slide 17)\n\n```sql\n-- NOT NULL: cấm NULL\n-- DEFAULT <value>: giá trị mặc định khi INSERT không chỉ định\nDno INT NOT NULL DEFAULT 1\n\n-- CHECK: biểu thức Boolean\nDnumber INT NOT NULL CHECK (Dnumber > 0 AND Dnumber < 21);\n```\n\n| Constraint | Ý nghĩa | Ví dụ |\n|---|---|---|\n| **NOT NULL** | Bắt buộc có giá trị | Nhân viên bắt buộc có Ssn |\n| **DEFAULT** | Giá trị mặc nếu không INSERT | `Dno DEFAULT 1` |\n| **CHECK** | Biểu thức Boolean trên cột | `Dnumber > 0 AND Dnumber < 21` |\n\n### 2.10. CREATE TABLE COMPANY — Ví dụ đầy đủ (Slide 19–20)\n\n```sql\nCREATE TABLE EMPLOYEE\n( Fname       VARCHAR(15)    NOT NULL,\n  Minit       CHAR,\n  Lname       VARCHAR(15)    NOT NULL,\n  Ssn         CHAR(9)        NOT NULL,\n  Bdate       DATE,\n  Address     VARCHAR(30),\n  Sex         CHAR,\n  Salary      DECIMAL(10,2),\n  Super_ssn   CHAR(9),\n  Dno         INT            NOT NULL,\n  PRIMARY KEY (Ssn) );\n\nCREATE TABLE DEPARTMENT\n( Dname           VARCHAR(15)    NOT NULL,\n  Dnumber         INT            NOT NULL,\n  Mgr_ssn         CHAR(9)        NOT NULL,\n  Mgr_start_date  DATE,\n  PRIMARY KEY (Dnumber),\n  UNIQUE (Dname),\n  FOREIGN KEY (Mgr_ssn) REFERENCES EMPLOYEE(Ssn) );\n\nCREATE TABLE DEPT_LOCATIONS\n( Dnumber      INT          NOT NULL,\n  Dlocation    VARCHAR(15)  NOT NULL,\n  PRIMARY KEY (Dnumber, Dlocation),\n  FOREIGN KEY (Dnumber) REFERENCES DEPARTMENT(Dnumber) );\n\nCREATE TABLE PROJECT\n( Pname       VARCHAR(15)    NOT NULL,\n  Pnumber     INT            NOT NULL,\n  Plocation   VARCHAR(15),\n  Dnum        INT            NOT NULL,\n  PRIMARY KEY (Pnumber),\n  UNIQUE (Pname),\n  FOREIGN KEY (Dnum) REFERENCES DEPARTMENT(Dnumber) );\n\nCREATE TABLE WORKS_ON\n( Essn    CHAR(9)        NOT NULL,\n  Pno     INT            NOT NULL,\n  Hours   DECIMAL(3,1)   NOT NULL,\n  PRIMARY KEY (Essn, Pno),\n  FOREIGN KEY (Essn) REFERENCES EMPLOYEE(Ssn),\n  FOREIGN KEY (Pno)  REFERENCES PROJECT(Pnumber) );\n\nCREATE TABLE DEPENDENT\n( Essn             CHAR(9)       NOT NULL,\n  Dependent_name   VARCHAR(15)   NOT NULL,\n  Sex              CHAR,\n  Bdate            DATE,\n  Relationship     VARCHAR(8),\n  PRIMARY KEY (Essn, Dependent_name),\n  FOREIGN KEY (Essn) REFERENCES EMPLOYEE(Ssn) );\n```\n\n> 💡 **Quan sát:** EMPLOYEE chưa có FK cho `Super_ssn` và `Dno` ở đoạn code trên — vì DEPARTMENT chưa tồn tại lúc tạo EMPLOYEE và `Super_ssn` self-reference cần bảng tồn tại trước. Thực tế: thêm 2 FK này SAU bằng `ALTER TABLE EMPLOYEE ADD FOREIGN KEY ...`.\n\n> 💡 **Vì sao WORKS_ON là bảng riêng?** Vì biểu diễn quan hệ **M:N** giữa EMPLOYEE và PROJECT. Không thể nhét Pnumber vào EMPLOYEE (1 nhân viên làm nhiều project) hay nhét Ssn vào PROJECT (1 project có nhiều nhân viên) — cần bảng trung gian.\n\n### 2.11. Đặt tên cho Constraint (Slide 21–22)\n\n**Optional** — Dùng keyword `CONSTRAINT`. Tên **duy nhất trong schema**. Dùng để DROP sau hoặc thay thế.\n\n```sql\nCREATE TABLE EMPLOYEE\n( ...,\n  Dno INT NOT NULL DEFAULT 1,\n  CONSTRAINT EMPPK\n    PRIMARY KEY (Ssn),\n  CONSTRAINT EMPSUPERFK\n    FOREIGN KEY (Super_ssn) REFERENCES EMPLOYEE(Ssn)\n      ON DELETE SET NULL    ON UPDATE CASCADE,\n  CONSTRAINT EMPDEPTFK\n    FOREIGN KEY (Dno) REFERENCES DEPARTMENT(Dnumber)\n      ON DELETE SET DEFAULT  ON UPDATE CASCADE );\n\nCREATE TABLE DEPARTMENT\n( ...,\n  Mgr_ssn CHAR(9) NOT NULL DEFAULT '888665555',\n  ... ,\n  CONSTRAINT DEPTPK    PRIMARY KEY (Dnumber),\n  CONSTRAINT DEPTSK    UNIQUE (Dname),\n  CONSTRAINT DEPTMGRFK\n    FOREIGN KEY (Mgr_ssn) REFERENCES EMPLOYEE(Ssn)\n      ON DELETE SET DEFAULT  ON UPDATE CASCADE );\n\nCREATE TABLE DEPT_LOCATIONS\n( ...,\n  PRIMARY KEY (Dnumber, Dlocation),\n  FOREIGN KEY (Dnumber) REFERENCES DEPARTMENT(Dnumber)\n    ON DELETE CASCADE  ON UPDATE CASCADE );\n```\n\n| Tên constraint | Ý nghĩa |\n|---|---|\n| EMPPK | Employee Primary Key |\n| EMPSUPERFK | Employee Super_ssn Foreign Key (tự tham chiếu) |\n| EMPDEPTFK | Employee → Department FK |\n| DEPTPK / DEPTSK / DEPTMGRFK | Department's PK / Secondary Key (UNIQUE) / Manager FK |\n\n> 💡 **Hiểu đơn giản:** Đặt tên constraint giống **đặt tên file** thay vì để DBMS sinh `constraint_8a3f7d2e`. Sau này muốn `ALTER TABLE Employee DROP CONSTRAINT EMPSUPERFK;` — câu lệnh gọn, dễ debug khi DBMS báo lỗi.\n\n### 2.12. Constraints on Individual Tuples (Slide 23)\n\n`CHECK` ở **mức bảng** kiểm tra các thuộc tính của **cùng 1 tuple**:\n\n```sql\nCHECK (Dept_create_date < Mgr_start_date);\n```\n\nÝ nghĩa: ngày tạo phòng phải **trước** ngày trưởng phòng nhậm chức.\n\n> 📌 Cho ràng buộc tổng quát hơn (qua nhiều bảng, nhiều dòng) → dùng `CREATE ASSERTION` (Section 5).\n\n### 2.13. DROP Command (Slide 24–25)\n\n| Chế độ | Hành vi |\n|---|---|\n| **RESTRICT** (mặc định) | Chỉ xóa nếu **không có** object phụ thuộc. An toàn. |\n| **CASCADE** | Xóa luôn cả các object phụ thuộc cùng đối tượng này. Nguy hiểm. |\n\n```sql\nDROP SCHEMA Company CASCADE;\nDROP SCHEMA Company RESTRICT;\n\nDROP TABLE Department CASCADE;\n```\n\n> ⚠️ **CẢNH BÁO:** `DROP SCHEMA Company CASCADE;` xóa **TOÀN BỘ** bảng, view, constraint trong schema. Luôn **backup trước** và xác nhận trước khi gõ trên production.\n\n### 2.14. ALTER Command (Slide 26)\n\n```sql\n-- Thêm cột\nALTER TABLE Employee ADD Job VARCHAR(15);\n\n-- Xóa cột\nALTER TABLE Employee DROP COLUMN Address CASCADE;\n\n-- Đổi giá trị DEFAULT\nALTER TABLE Department\n   ALTER COLUMN Mgr_ssn SET DEFAULT '333445555';\n\n-- Xóa constraint\nALTER TABLE Employee DROP CONSTRAINT Empsuperfk;\n```\n\n> 📝 **Tóm lại section 2 — DDL:**\n> - **CREATE SCHEMA / CREATE TABLE** định nghĩa cấu trúc + kiểu + khóa + ràng buộc.\n> - **Constraints**: PRIMARY KEY, UNIQUE, FOREIGN KEY (4 referential actions), NOT NULL, DEFAULT, CHECK.\n> - **CONSTRAINT \\<name\\>** giúp DROP/ALTER sau này.\n> - **DROP** với CASCADE (lan truyền) hoặc RESTRICT (an toàn).\n> - **ALTER** để ADD/DROP/ALTER COLUMN, ADD/DROP CONSTRAINT.\n> **Một câu ghi nhớ:** *DDL là 3 chữ CAD — Create, Alter, Drop — với keyword CONSTRAINT, CHECK, FOREIGN KEY ON DELETE/UPDATE quyết định ngữ nghĩa.*\n\n> ❓ **Tự kiểm tra section 2:**\n> 1. Vì sao `Ssn CHAR(9)` hợp lý hơn `Ssn INT`?\n> 2. Phân biệt PRIMARY KEY và UNIQUE — số lượng/bảng và cho phép NULL?\n> 3. Nếu `FOREIGN KEY (Dno) REFERENCES Department(Dnumber) ON DELETE SET NULL`, khi xóa 1 dòng trong Department, điều gì xảy ra với cột Dno?\n> 4. Sự khác biệt giữa `DROP TABLE T RESTRICT` và `DROP TABLE T CASCADE` là gì?\n> 5. Trong `WORKS_ON(Essn, Pno, Hours)`, vì sao PK là `(Essn, Pno)`?\n> 6. Vì sao cần đặt tên cho constraint?\n\n---\n\n","file":"materials/DB-Chapter6.md","section":3},{"id":"c6-04","group":"c6","kind":"source","title":"3. DML — SELECT: Truy vấn dữ liệu","markdown":"## 3. DML — SELECT: Truy vấn dữ liệu\n\nSection 2 đã tạo được bảng. Câu hỏi tiếp theo: **làm sao lấy thông tin ra khỏi database?** Đây là phần lớn nhất của chương — SELECT.\n\n### 3.1. Tại sao SELECT là lệnh quan trọng nhất? (Motivation)\n\nDatabase có giá trị vì ta có thể hỏi nó. \"Nhân viên nào thuộc phòng Research?\", \"Project ở Stafford do ai quản lý?\", \"Mức lương trung bình mỗi phòng?\". Nếu không có SELECT, database chỉ là kho cất dữ liệu, không tạo ra thông tin. **SELECT biến dữ liệu thành câu trả lời.**\n\n### 3.2. SELECT là gì? (Slide 28)\n\n> - SELECT command: **truy hồi thông tin** (retrieve information) từ database.\n> - SELECT trong SQL = **SELECT operation** trong Relational Algebra (cùng tên!).\n> - SQL cho phép một relation chứa **2 hoặc nhiều tuple giống hệt nhau**.\n> - SQL relation là **multi-set (bag) of tuples**, **không phải set** — đây là khác biệt CỐT LÕI so với RA.\n> - Có thể ép thành set bằng **PRIMARY KEY**, **UNIQUE**, hoặc **`DISTINCT`** trong query.\n\n| Relational Algebra | SQL |\n|---|---|\n| Relation là **set** | Table/query result là **bag/multiset** |\n| Không có duplicate tuple | Có thể có duplicate tuple |\n| Projection tự loại duplicate | SELECT KHÔNG loại duplicate trừ khi `DISTINCT` |\n\n> 💡 **Hiểu đơn giản:** Set = túi không cho 2 quả bóng giống nhau. Multiset/bag = túi cho phép 10 quả giống nhau. SQL mặc định là multiset → truy vấn lương của 3 người cùng lương 25000, ta nhận 3 dòng \"25000\".\n\n### 3.3. Cú pháp SELECT (Slide 29–31, 50, 72, 78–79)\n\n**Basic form:**\n```sql\nSELECT  <attribute list>\nFROM    <table list>\nWHERE   <condition>\n```\n\n**Complete form:**\n```sql\nSELECT  [DISTINCT | ALL]\n    {* | [columnExpression [AS newName]] [,...] }\nFROM    TableName [alias] [, ...]\n[WHERE     condition]\n[GROUP BY  columnList]\n[HAVING    condition]\n[ORDER BY  columnList]\n```\n\n| Mệnh đề | Mục đích |\n|---|---|\n| **SELECT** | Cột nào xuất hiện trong output |\n| **FROM** | Bảng nào được dùng |\n| **WHERE** | Lọc các **dòng** |\n| **GROUP BY** | Gom dòng cùng giá trị cột thành nhóm |\n| **HAVING** | Lọc các **nhóm** |\n| **ORDER BY** | Sắp xếp output |\n\n> 📊 **Thứ tự thực thi logic** (KHÁC thứ tự viết!):\n>\n> **FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY**\n>\n> Hiểu đúng thứ tự này giúp: (a) không bối rối khi alias đặt ở SELECT không dùng được trong WHERE; (b) hiểu vì sao HAVING dùng aggregate được mà WHERE thì không.\n\n### 3.4. Basic queries Q0–Q2 (Slide 33–36)\n\n#### Query 0 — SELECT cơ bản 1 bảng (Slide 33)\n\n> Lấy ngày sinh và địa chỉ của nhân viên tên 'John B. Smith'.\n\n```sql\nQ0: SELECT  Bdate, Address\n    FROM    Employee\n    WHERE   Fname = 'John' AND Minit = 'B' AND Lname = 'Smith';\n```\n\n| Dòng | Ý nghĩa |\n|---|---|\n| `SELECT Bdate, Address` | Lấy 2 cột (= projection π trong RA) |\n| `FROM Employee` | Nguồn dữ liệu |\n| `WHERE ...` | Lọc tuple (= selection σ trong RA) |\n\n**Tương đương Relational Algebra (SELECT-PROJECT):**\n`π_{Bdate, Address}(σ_{Fname='John' AND Minit='B' AND Lname='Smith'}(EMPLOYEE))`\n\n> ⚠️ Kết quả SQL có thể chứa **dòng trùng** (nếu có 2 người cùng tên & ngày sinh & địa chỉ).\n\n#### Query 1 — JOIN qua WHERE (Slide 34)\n\n> Lấy tên và địa chỉ của tất cả nhân viên thuộc phòng 'Research'.\n\n```sql\nQ1: SELECT  Fname, Lname, Address\n    FROM    Employee, Department\n    WHERE   Dname = 'Research' AND Dnumber = Dno;\n```\n\n| Điều kiện | Loại | Ý nghĩa |\n|---|---|---|\n| `Dname='Research'` | Selection condition | Chọn phòng Research |\n| `Dnumber = Dno` | **Join condition** | Ghép EMPLOYEE với DEPARTMENT |\n\n**Tương đương RA (SELECT-PROJECT-JOIN):**\n`π_{Fname, Lname, Address}(σ_{Dname='Research'}(EMPLOYEE ⋈_{Dno=Dnumber} DEPARTMENT))`\n\n> 💡 **Cách \"đọc\" query nhiều bảng:**\n> 1. Bao nhiêu bảng? → n bảng cần **n-1 join conditions**.\n> 2. Tìm cặp cột PK–FK để đặt join condition.\n> 3. Điều kiện \"cứng\" (không phải PK–FK) là selection.\n\n#### Query 2 — 3 bảng, 2 JOIN (Slide 36)\n\n> Với mỗi project ở 'Stafford', liệt kê số project, số phòng kiểm soát, và họ-địa chỉ-ngày sinh của trưởng phòng đó.\n\n```sql\nQ2: SELECT  Pnumber, Dnum, Lname, Bdate, Address\n    FROM    Project, Department, Employee\n    WHERE   Dnum = Dnumber\n        AND MgrSSN = SSN\n        AND Plocation = 'Stafford';\n```\n\n| Điều kiện | Ý nghĩa |\n|---|---|\n| `Dnum = Dnumber` | Nối PROJECT ↔ DEPARTMENT (project thuộc phòng nào) |\n| `MgrSSN = SSN` | Nối DEPARTMENT ↔ EMPLOYEE (trưởng phòng là ai) |\n| `Plocation = 'Stafford'` | Lọc project ở Stafford |\n\n### 3.5. Ambiguous Attribute Names (Slide 38)\n\nTên cột giống nhau ở 2 bảng → query phải **qualify** (đặc tả rõ) bằng `TableName.AttributeName`:\n\n```sql\nDEPARTMENT.Dnumber  -- cột Dnumber trong DEPARTMENT\nDEPT_LOCATIONS.Dnumber  -- cột Dnumber trong DEPT_LOCATIONS\n```\n\nNếu không qualify, DBMS báo `column reference \"Dnumber\" is ambiguous`.\n\n> 💡 **Hiểu đơn giản:** Trong lớp có 2 bạn tên \"An\". Khi gọi \"An ơi\" không rõ An nào. Phải nói \"An lớp trưởng\" hoặc \"An bàn cuối\".\n\n### 3.6. Aliases — Tuple variables (Slide 39–40)\n\nKhi cần **dùng 1 bảng 2 lần** (vd self-join), phải đặt alias.\n\n> **Query 3:** Với mỗi nhân viên, lấy tên nhân viên và tên cấp trên trực tiếp.\n\n```sql\nQ3a: SELECT  E.Fname, E.Lname, S.Fname, S.Lname\n     FROM    Employee E, Employee S\n     WHERE   E.SuperSSN = S.SSN;\n\nQ3b: SELECT  E.Fname, E.Lname, S.Fname, S.Lname\n     FROM    Employee AS E, Employee AS S\n     WHERE   E.SuperSSN = S.SSN;\n```\n\n- `E` = nhân viên **được giám sát** (supervisee).\n- `S` = nhân viên **giám sát** (supervisor).\n\n**Đổi tên cả cột:**\n```sql\nEmployee AS E(FN, M, LN, SSN, BD, Addr, Sex, Sal, SSSN, DNO)\n```\n\n> 💡 **Hiểu đơn giản — self-join:** EMPLOYEE giống 1 lớp học. Lan vừa là \"học sinh\", vừa có thể là \"lớp trưởng\" của Hùng. Muốn xem \"Hùng và lớp trưởng của Hùng\", phải dùng cùng bảng 2 lần — alias `E` cho học sinh, `S` cho lớp trưởng.\n\n### 3.7. Unspecified WHERE — Bỏ WHERE (Slide 41–42)\n\n**Bỏ WHERE = tương đương `WHERE TRUE` = tất cả tuple.**\n\n> **Query 4:** Lấy SSN của tất cả nhân viên.\n\n```sql\nQ4: SELECT  SSN  FROM  Employee;\n```\n\n**Nhiều bảng + không có join condition = CARTESIAN PRODUCT.**\n\n> **Query 5:** Lấy mọi kết hợp Employee.SSN × Department.Dname.\n\n```sql\nQ5: SELECT  SSN, Dname  FROM  Employee, Department;\n```\n\nNếu EMPLOYEE có 8 dòng, DEPARTMENT có 3 dòng → kết quả **24 dòng** (phần lớn vô nghĩa).\n\n> ⚠️ **CẢNH BÁO:** Rất quan trọng để **không bỏ sót** điều kiện chọn và join trong WHERE; nếu không, các quan hệ **sai và rất lớn** có thể bị tạo ra. Trên DB production hàng triệu dòng, query thiếu join có thể **làm chết DBMS**.\n\n### 3.8. Use of ASTERISK `*` (Slide 43)\n\n`*` = **tất cả các thuộc tính**.\n\n```sql\nQ6: SELECT * FROM Employee WHERE DNO = 5;\n\nQ7: SELECT *\n    FROM   Employee, Department\n    WHERE  Dname = 'Research' AND DNO = Dnumber;\n```\n\n> ⚠️ **Tránh `SELECT *` trong production:** Bảng có thể thêm cột (vd `password_hash`) — `*` sẽ vô tình lộ. Tốt hơn liệt kê rõ cột.\n\n### 3.9. DISTINCT (Slide 44)\n\nLoại tuple trùng.\n\n```sql\nQ8a: SELECT Salary FROM Employee;\n-- Có thể: 30000, 25000, 30000, 25000, 40000\n\nQ8b: SELECT DISTINCT Salary FROM Employee;\n-- 30000, 25000, 40000\n```\n\n### 3.10. Set Operations (Slide 45–46)\n\n| SQL | RA | Ý nghĩa |\n|---|---|---|\n| `UNION` | ∪ | Gộp 2 tập, **bỏ trùng** |\n| `EXCEPT` (Oracle: `MINUS`) | − | Có trong trái, không có trong phải |\n| `INTERSECT` | ∩ | Có trong CẢ HAI |\n\n3 điểm quan trọng:\n1. Kết quả là **SET** → dòng trùng bị loại tự động.\n2. Chỉ áp dụng cho **union-compatible relations** (cùng số cột + kiểu tương thích).\n3. Phiên bản giữ trùng: `UNION ALL`, `EXCEPT ALL`, `INTERSECT ALL`.\n\n> **Query 9:** Liệt kê số project liên quan đến nhân viên 'Smith' với vai trò worker HOẶC manager của phòng kiểm soát project.\n\n```sql\nQ9: (SELECT  DISTINCT Pnumber\n     FROM    Project, Department, Employee\n     WHERE   Dnum = Dnumber AND MgrSSN = SSN\n             AND Lname = 'Smith')\n    UNION\n    (SELECT  DISTINCT Pnumber\n     FROM    Project, Works_on, Employee\n     WHERE   Pnumber = Pno AND ESSN = SSN\n             AND Lname = 'Smith');\n```\n\n| Vế | Ý nghĩa |\n|---|---|\n| Trước UNION | Project mà manager họ Smith kiểm soát |\n| Sau UNION | Project mà nhân viên họ Smith làm việc |\n| UNION | Gộp 2 tập, loại trùng |\n\n> 💡 Đề có chữ **OR** từ 2 nguồn khác nhau → thường dùng `UNION`.\n\n### 3.11. LIKE — Pattern Matching (Slide 47)\n\n| Ký tự | Ý nghĩa |\n|---|---|\n| `%` | Đại diện chuỗi bất kỳ (kể cả rỗng) |\n| `_` | Đại diện đúng 1 ký tự |\n\n```sql\nQ10: SELECT * FROM Employee WHERE Address LIKE '%Houston,TX%';\n\nQ11: SELECT * FROM Employee WHERE SSN LIKE '_______88';\n```\n\nQ11: SSN 9 ký tự kết thúc bằng `88` → 7 dấu `_` + `88`.\n\n> 💡 **Hiểu đơn giản — LIKE:** `%` ≈ `.*` trong regex; `_` ≈ `.` trong regex. Phải dùng dấu `'...'` cho string.\n\n### 3.12. Arithmetic Operators (Slide 48)\n\n`+`, `-`, `*`, `/`.\n\n> **Query 12:** Hiển thị lương sau tăng 10% cho nhân viên làm trên project 'ProductX'.\n\n```sql\nQ12: SELECT  Fname, Lname, 1.1 * Salary AS INC_SAL\n     FROM    Employee, Works_on, Project\n     WHERE   SSN = ESSN AND PNO = Pnumber\n             AND Pname = 'ProductX';\n```\n\n- `1.1 * Salary` — phép nhân tạo cột mới.\n- `AS INC_SAL` — đặt tên cột kết quả.\n\n### 3.13. NULL & 3-valued logic (Slide 49)\n\nKhi NULL tham gia so sánh → kết quả là `UNKNOWN`, không phải TRUE/FALSE.\n\n**Bảng chân trị AND:**\n\n| AND | True | False | Unknown |\n|---|---|---|---|\n| **True** | T | F | **U** |\n| **False** | F | F | F |\n| **Unknown** | **U** | F | **U** |\n\n**Bảng chân trị OR:**\n\n| OR | True | False | Unknown |\n|---|---|---|---|\n| **True** | T | T | T |\n| **False** | T | F | **U** |\n| **Unknown** | T | **U** | **U** |\n\n**Bảng chân trị NOT:**\n\n| Input | NOT |\n|---|---|\n| True | F |\n| False | T |\n| Unknown | **U** |\n\n**Kiểm tra NULL — phải dùng `IS NULL` / `IS NOT NULL`** (KHÔNG dùng `= NULL` — sẽ luôn cho Unknown):\n\n```sql\nSELECT * FROM Employee WHERE SuperSSN IS NULL;\nSELECT * FROM Employee WHERE SuperSSN IS NOT NULL;\n```\n\n> 💡 **Hiểu đơn giản — tại sao `NULL = NULL` ra Unknown?** NULL nghĩa là \"không biết\". Hai cái \"không biết\" có bằng nhau không? **Không biết.** → kết quả `UNKNOWN`.\n\n> ⚠️ **Bẫy NULL thường gặp:** `WHERE Salary != 30000` sẽ KHÔNG trả các nhân viên có `Salary = NULL` (vì `NULL != 30000` → UNKNOWN, không TRUE). Để bao gồm cả NULL: `WHERE Salary != 30000 OR Salary IS NULL`.\n\n> 📝 **Tóm lại section 3.1–3.13 — SELECT cơ bản:**\n> - SELECT-FROM-WHERE là 3 mệnh đề tối thiểu.\n> - `*` lấy hết cột; `DISTINCT` loại trùng; `AS` đặt tên cột mới.\n> - n bảng → n-1 join conditions; quên là Cartesian product.\n> - Tên cột trùng → qualify `TableName.col`.\n> - Cùng bảng dùng 2 lần → đặt **alias**.\n> - **LIKE** với `%` (nhiều ký tự) và `_` (1 ký tự).\n> - **NULL** dùng `IS NULL` / `IS NOT NULL`; logic 3 giá trị.\n> - **UNION/INTERSECT/EXCEPT** là phép tập hợp (loại trùng).\n> **Một câu ghi nhớ:** *Đọc xuôi như tiếng Anh, nhưng DBMS thực thi theo FROM→WHERE→SELECT.*\n\n### 3.14. Nested Queries — Truy vấn lồng (Slide 51)\n\n**Subquery (truy vấn lồng):** một SELECT-FROM-WHERE đầy đủ nằm trong WHERE của query khác.\n\n**IN:** so sánh giá trị v với tập V; TRUE nếu v ∈ V.\n\n> **Query 13:** Lấy tên + địa chỉ của nhân viên phòng 'Research'. (Cách viết bằng subquery)\n\n```sql\nQ13: SELECT  Fname, Lname, Address\n     FROM    Employee\n     WHERE   Dno IN ( SELECT  Dnumber\n                      FROM    Department\n                      WHERE   Dname = 'Research' );\n```\n\n| Phần | Ý nghĩa |\n|---|---|\n| Subquery (inner) | Tìm Dnumber của phòng Research |\n| Outer query | Chọn employee có Dno ∈ tập đó |\n| `IN` | Kiểm tra giá trị thuộc tập subquery |\n\n### 3.15. Correlated Nested Queries (Slide 52)\n\nKhi inner query **tham chiếu** một attribute của relation ở outer → 2 query là **correlated**.\n\n> **Query 14:** Lấy tên nhân viên có dependent cùng first name với chính họ.\n\n```sql\nQ14: SELECT  E.Fname, E.Lname\n     FROM    Employee E\n     WHERE   E.SSN IN ( SELECT  ESSN\n                        FROM    Dependent\n                        WHERE   ESSN = E.SSN\n                                AND E.Fname = Dependent_name );\n```\n\nInner query dùng `E.SSN` và `E.Fname` từ outer → **correlated**.\n\n**Cách thực thi (conceptual):** Với MỖI tuple E trong EMPLOYEE, đánh giá lại inner query.\n\n### 3.16. Mọi nested IN có thể viết lại thành single block JOIN (Slide 54)\n\n```sql\nQ14a: SELECT  E.Fname, E.Lname\n      FROM    Employee E, Dependent D\n      WHERE   E.SSN = D.ESSN\n              AND E.Fname = D.Dependent_name;\n```\n\nTương đương Q14 nhưng dùng JOIN thay subquery → thường nhanh hơn vì DBMS tối ưu join tốt.\n\n### 3.17. Nested Query với tuple (Slide 55)\n\n> **Query 15:** Lấy SSN của nhân viên có cùng cặp `(project, hours)` với John Smith (SSN='123456789') trên 1 project nào đó.\n\n```sql\nQ15: SELECT  DISTINCT ESSN\n     FROM    Works_on\n     WHERE   (PNO, Hours) IN ( SELECT PNO, Hours\n                               FROM   Works_on\n                               WHERE  ESSN = '123456789' );\n```\n\n`(PNO, Hours)` là tuple 2 thành phần — so khớp đồng thời cả 2.\n\n### 3.18. ANY/SOME/ALL với toán tử so sánh (Slide 56)\n\nOperators có thể kết hợp với `ANY` (= `SOME`) hoặc `ALL`: `=, >, >=, <, <=, <>`.\n\n| Cú pháp | Tương đương |\n|---|---|\n| `v > ANY (Q)` | v > min(Q) — lớn hơn ít nhất 1 phần tử |\n| `v > ALL (Q)` | v > max(Q) — lớn hơn mọi phần tử |\n| `v = ANY (Q)` | `v IN (Q)` |\n\n> **Query 16:** Nhân viên có lương lớn hơn lương của TẤT CẢ nhân viên phòng 5.\n\n```sql\nQ16: SELECT  *\n     FROM    Employee\n     WHERE   Salary > ALL ( SELECT  Salary\n                            FROM    Employee\n                            WHERE   DNO = 5 );\n```\n\n### 3.19. EXISTS / NOT EXISTS / UNIQUE (Slide 57–59)\n\n- **`EXISTS(Q)`**: TRUE nếu Q **không rỗng**.\n- **`NOT EXISTS(Q)`**: TRUE nếu Q **rỗng**.\n- **`UNIQUE(Q)`**: TRUE nếu Q không có tuple trùng.\n\nEXISTS thường dùng với **correlated nested query**.\n\n> **Query 14b:** (Viết lại Q14 dùng EXISTS)\n\n```sql\nQ14b: SELECT  Fname, Lname\n      FROM    Employee\n      WHERE   EXISTS ( SELECT  *\n                       FROM    Dependent\n                       WHERE   ESSN = SSN\n                               AND FName = Dependent_name );\n```\n\n> **Query 17:** Nhân viên KHÔNG có dependent nào.\n\n```sql\nQ17: SELECT  Fname, Lname\n     FROM    Employee\n     WHERE   NOT EXISTS ( SELECT  *\n                          FROM    Dependent\n                          WHERE   SSN = ESSN );\n```\n\n> 💡 **Pattern quan trọng — \"tìm cái KHÔNG có\":** dùng `NOT EXISTS`. Tương tự: \"phòng KHÔNG có nhân viên\", \"sinh viên CHƯA đăng ký môn nào\",… đều `NOT EXISTS (SELECT * FROM ... WHERE ...)`.\n\n### 3.20. Enumerated Sets (Slide 60)\n\n`IN` với **tập tường minh**:\n\n```sql\nQ18: SELECT  DISTINCT ESSN\n     FROM    Works_on\n     WHERE   PNO IN (1, 2, 3);\n```\n\nTương đương `WHERE PNO = 1 OR PNO = 2 OR PNO = 3` nhưng gọn hơn.\n\n> 📝 **Tóm lại section 3.14–3.20 — Nested Queries & Operators:**\n> - **Nested query** với `IN`, `ANY`, `ALL`, `EXISTS`.\n> - **Correlated** = inner tham chiếu outer; **Uncorrelated** = không.\n> - **Mọi IN với subquery có thể chuyển thành JOIN** — thường nhanh hơn.\n> - **`NOT EXISTS`** là pattern chuẩn để diễn tả \"for all\" / \"không có\" / \"với mọi\".\n> - `= ANY` ≡ `IN`; `> ALL` ≡ \"lớn hơn max\"; `> ANY` ≡ \"lớn hơn min\".\n\n### 3.21. Joined Relations / JOIN cú pháp mới (Slide 61–62)\n\n**Các loại JOIN:**\n- **EQUIJOIN** (join trên `=`)\n- **NATURAL JOIN** (tự động join trên cột cùng tên)\n- **LEFT/RIGHT/FULL OUTER JOIN**\n\n```sql\nQ1a: SELECT  Fname, Lname, Address\n     FROM    (Employee JOIN Department ON Dno = Dnumber)\n     WHERE   Dname = 'Research';\n```\n\nTương đương Q1 cũ, nhưng tách bạch **join condition (ON)** khỏi **selection (WHERE)** → dễ đọc.\n\n### 3.22. NATURAL JOIN (Slide 63)\n\n- **Không cần** điều kiện join.\n- DBMS **tự** áp EQUIJOIN trên **mỗi cặp cột cùng tên** giữa R và S.\n\n> ⚠️ NATURAL JOIN nguy hiểm nếu 2 bảng có cột cùng tên nhưng không có ý nghĩa join mong muốn.\n\n### 3.23. Inner & Outer Join (Slide 64–65)\n\n| Loại | Đặc điểm |\n|---|---|\n| **INNER JOIN** (mặc định) | Tuple chỉ vào kết quả nếu có matching ở bảng kia. |\n| **LEFT OUTER JOIN** | **Mọi tuple TRÁI** phải có trong kết quả. Không match → pad NULL bên phải. |\n| **RIGHT OUTER JOIN** | **Mọi tuple PHẢI** phải có. Không match → pad NULL bên trái. |\n| **FULL OUTER JOIN** | **Mọi tuple cả 2 bên**. |\n\n> 💡 **Hiểu đơn giản — 4 loại JOIN qua Venn diagram:**\n> - INNER = chỉ phần giao\n> - LEFT OUTER = vòng tròn trái + giao\n> - RIGHT OUTER = vòng tròn phải + giao\n> - FULL OUTER = cả 2 vòng tròn\n\n### 3.24. Joined Relations — Examples (Slide 66–68)\n\n> **Q3 — So sánh INNER vs LEFT OUTER:**\n\n```sql\nQ3a: SELECT  E.Fname, E.Lname, S.Fname, S.Lname\n     FROM    Employee E, Employee S\n     WHERE   E.SuperSSN = S.SSN;\n\nQ3c: SELECT  E.Fname, E.Lname, S.Fname, S.Lname\n     FROM    ( Employee E LEFT OUTER JOIN Employee S\n               ON E.SuperSSN = S.SSN );\n```\n\n| Query | Ai xuất hiện? | Ai bị mất? |\n|---|---|---|\n| Q3a inner | Chỉ employee có supervisor khớp | CEO (không có supervisor) bị loại |\n| Q3c LEFT OUTER | **Tất cả** employee bên trái E | Không mất; supervisor name = NULL nếu không có |\n\n> **Q1 dạng JOIN / NATURAL JOIN (Slide 67):**\n\n```sql\nQ1a: SELECT  Fname, Lname, Address\n     FROM    (Employee JOIN Department ON Dnumber = Dno)\n     WHERE   Dname = 'Research';\n\nQ1b: SELECT  Fname, Lname, Address\n     FROM    (Employee NATURAL JOIN (Department\n                  AS Dept(Dname, Dno, MSSN, MSDate)))\n     WHERE   Dname = 'Research';\n```\n\n> 💡 **Vì sao Q1b phải rename Department?** Để NATURAL JOIN tự nối, hai bảng phải có cột **cùng tên**. EMPLOYEE có `Dno`, DEPARTMENT có `Dnumber` — khác tên. Bằng `Department AS Dept(Dname, Dno, MSSN, MSDate)`, ta đổi `Dnumber → Dno` (và 2 cột manager) để NATURAL JOIN tự khớp trên `Dno`.\n\n> **Q2 dạng joined table (Slide 68):**\n\n```sql\nQ2a: SELECT  Pnumber, Dnum, Lname, Bdate, Address\n     FROM    ((Project JOIN Department ON Dnum = Dnumber)\n              JOIN Employee ON MGRSSN = SSN)\n     WHERE   Plocation = 'Stafford';\n```\n\nJOIN từ trái sang phải: PROJECT ⋈ DEPARTMENT trước, kết quả trung gian ⋈ EMPLOYEE.\n\n### 3.25. AGGREGATE FUNCTIONS (Slide 69–70)\n\n5 hàm: **COUNT, SUM, MAX, MIN, AVG**.\n\n```sql\nQ19: SELECT  MAX(Salary), MIN(Salary), AVG(Salary)\n     FROM    Employee;\n\nQ20: SELECT  COUNT(*) FROM Employee;\n\nQ21: SELECT  COUNT(*)\n     FROM    Employee, Department\n     WHERE   Dno = Dnumber AND Dname = 'Research';\n```\n\n> ⚠️ **Lưu ý NULL với aggregate:** NULL values are **discarded** với aggregate khi áp lên 1 cột. Ví dụ `AVG(Salary)` chỉ tính trên Salary IS NOT NULL.\n\n| Biểu thức | Ý nghĩa |\n|---|---|\n| `COUNT(*)` | Đếm số dòng (kể cả có NULL) |\n| `COUNT(col)` | Đếm số dòng có col IS NOT NULL |\n| `COUNT(DISTINCT col)` | Đếm số giá trị phân biệt (không kể NULL) |\n\n### 3.26. GROUP BY (Slide 71–74)\n\n**Quy tắc:**\n- Mọi cột trong **SELECT** (mà không phải aggregate) PHẢI có trong **GROUP BY**.\n- Aggregate áp **độc lập trên từng nhóm**.\n- Nếu cột group có NULL → tạo nhóm riêng cho NULL.\n\n> **Query 22:** Với mỗi phòng, lấy số phòng, số nhân viên, lương trung bình.\n\n```sql\nQ22: SELECT     Dno, COUNT(*), AVG(Salary)\n     FROM       Employee\n     GROUP BY   Dno;\n```\n\n**Bảng EMPLOYEE mẫu (slide 74):**\n\n| Fname | Lname | SSN | Salary | DNO |\n|---|---|---|---:|---:|\n| John | Smith | 123456789 | 30000 | 5 |\n| Franklin | Wong | 333445555 | 40000 | 5 |\n| Ramesh | Narayan | 666884444 | 38000 | 5 |\n| Joyce | English | 453453453 | 25000 | 5 |\n| Alicia | Zelaya | 999887777 | 25000 | 4 |\n| Jennifer | Wallace | 987654321 | 43000 | 4 |\n| Ahmad | Jabbar | 987987987 | 25000 | 4 |\n| James | Borg | 888665555 | 55000 | 1 |\n\n**Kết quả Q22:**\n\n| Dno | COUNT(*) | AVG(Salary) |\n|---:|---:|---:|\n| 5 | 4 | 33250 |\n| 4 | 3 | 31000 |\n| 1 | 1 | 55000 |\n\n> 💡 **Hiểu đơn giản — GROUP BY:** Có 1 đống thẻ học sinh, mỗi thẻ ghi tên + lớp. GROUP BY Lớp = **xếp thẻ thành các đống theo lớp**. Aggregate = **đếm/tính từng đống**.\n\n> ⚠️ **Lỗi phổ biến:** `SELECT Fname, COUNT(*) FROM Employee GROUP BY Dno;` — **SAI** vì Fname không có trong GROUP BY và cũng không phải aggregate. Phải thêm Fname vào GROUP BY, hoặc dùng `MAX(Fname)`, hoặc bỏ Fname khỏi SELECT.\n\n### 3.27. HAVING (Slide 75–76)\n\nLọc **nhóm** (sau GROUP BY) — giống WHERE nhưng cho group.\n\n> **Query 23:** Với mỗi project có HƠN 2 nhân viên làm, lấy số project, tên, số nhân viên.\n\n```sql\nQ23: SELECT     Pnumber, Pname, COUNT(*)\n     FROM       Project, Works_on\n     WHERE      Pnumber = Pno\n     GROUP BY   Pnumber, Pname\n     HAVING     COUNT(*) > 2;\n```\n\n| Clause | Lọc cái gì | Aggregate? |\n|---|---|---|\n| **WHERE** | Từng **dòng** trước group | KHÔNG dùng aggregate |\n| **HAVING** | Từng **nhóm** sau group | Dùng được aggregate |\n\n### 3.28. ORDER BY (Slide 77)\n\n```sql\nQ24: SELECT     Dname, Lname, Fname, Pname\n     FROM       Department, Employee, Works_on, Project\n     WHERE      Dnumber = Dno AND SSN = ESSN AND Pno = Pnumber\n     ORDER BY   Dname, Lname [DESC|ASC];\n```\n\n- ASC (mặc định) tăng dần; DESC giảm dần.\n- Multi-column: sort theo cột đầu trước; cùng giá trị → sort tiếp theo cột sau.\n\n> 📝 **Tóm lại section 3.21–3.28 — JOIN, Aggregate, GROUP BY, ORDER BY:**\n> - **JOIN syntax mới** tách bạch ON (join) với WHERE (selection).\n> - **Inner** loại không match; **LEFT/RIGHT/FULL OUTER** giữ tuple không match, pad NULL.\n> - **Aggregate** loại NULL (trừ `COUNT(*)`).\n> - **GROUP BY**: cột non-aggregate trong SELECT phải có trong GROUP BY.\n> - **HAVING** lọc nhóm; **WHERE** lọc dòng — đừng nhầm.\n> - **Thứ tự thực thi:** FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY.\n\n> ❓ **Tự kiểm tra section 3:**\n> 1. WHERE khác HAVING như thế nào? Tại sao `WHERE COUNT(*) > 2` báo lỗi mà `HAVING COUNT(*) > 2` thì OK?\n> 2. Vì sao Q3 dùng `Employee E, Employee S` thay vì chỉ `Employee`?\n> 3. Viết SQL: lấy tên nhân viên KHÔNG có supervisor.\n> 4. INNER JOIN khác LEFT OUTER JOIN ở điểm nào? Ví dụ COMPANY khi cho kết quả khác?\n> 5. `SELECT DISTINCT Dno FROM Employee` và `SELECT Dno FROM Employee GROUP BY Dno` cho cùng tập giá trị; vậy có khác gì về ngữ nghĩa?\n> 6. Nếu bạn viết `FROM Employee, Department` mà không có WHERE, output có bao nhiêu dòng nếu EMPLOYEE có 100, DEPARTMENT có 5?\n\n---\n\n","file":"materials/DB-Chapter6.md","section":4},{"id":"c6-05","group":"c6","kind":"source","title":"4. DML — INSERT, DELETE, UPDATE","markdown":"## 4. DML — INSERT, DELETE, UPDATE\n\nSection 3 dạy cách **đọc** dữ liệu. Bây giờ học cách **thêm/sửa/xóa** — 3 lệnh ngắn hơn nhưng nhiều **bẫy** (constraint, cascade).\n\n### 4.1. INSERT (Slide 81)\n\n```sql\nINSERT INTO TableName (Attribute1, Attribute2, ...)\nVALUES (value1, value2, ...);\n```\n\n- Values phải khớp **cùng thứ tự** với attribute.\n- Không liệt kê attribute → values phải khớp thứ tự cột trong CREATE TABLE.\n\n### 4.2. INSERT — Ví dụ (Slide 82)\n\n> **U1:** Insert đầy đủ values cho 1 nhân viên mới.\n\n```sql\nU1: INSERT INTO Employee\n    VALUES ('Richard', 'K', 'Marini', '653298653',\n            '30-DEC-52', '98 Oak Forest, Katy, TX',\n            'M', 37000, '987654321', 4);\n```\n\n> **U2:** Insert chỉ FNAME, LNAME, SSN.\n\n```sql\nU2: INSERT INTO Employee (Fname, Lname, SSN)\n    VALUES ('Richard', 'Marini', '653298653');\n```\n\n→ Các cột bỏ qua nhận DEFAULT/NULL.\n\n> ⚠️ Câu chỉ hợp lệ nếu cột bỏ qua cho phép NULL hoặc có DEFAULT. Nếu Dno NOT NULL không default → lệnh lỗi.\n\n### 4.3. INSERT — Lưu ý ràng buộc (Slide 83)\n\n> Chỉ các ràng buộc đặc tả trong DDL mới được DBMS tự động kiểm tra khi update.\n\n→ Quên `NOT NULL` cho Salary → DBMS chấp nhận tuple Salary=NULL mà không phàn nàn.\n\n### 4.4. INSERT từ query (Slide 84)\n\n> **U3/U3A:** Tạo bảng tạm summary và nạp dữ liệu từ query.\n\n```sql\nU3: CREATE TABLE Depts_info\n    ( Dept_name   VARCHAR(10),\n      No_of_emps  INTEGER,\n      Total_sal   INTEGER );\n\nU3A: INSERT INTO Depts_info (Dept_name, No_of_emps, Total_sal)\n     SELECT     Dname, COUNT(*), SUM(Salary)\n     FROM       Department, Employee\n     WHERE      Dnumber = Dno\n     GROUP BY   Dname;\n```\n\n> ⚠️ **Snapshot, không phải view:** sau INSERT, Depts_info **không tự cập nhật** khi EMPLOYEE/DEPARTMENT đổi. Muốn luôn cập nhật → dùng VIEW (Section 6).\n\n### 4.5. DELETE (Slide 85–86)\n\n```sql\nDELETE FROM TableName\nWHERE Condition;\n```\n\n- Xóa từ **1 bảng tại 1 thời điểm** (trừ khi CASCADE FK kích hoạt).\n- **Bỏ WHERE = xóa TẤT CẢ** tuple → bảng rỗng (cấu trúc còn).\n\n```sql\nU4A: DELETE FROM Employee WHERE Lname = 'Brown';\nU4B: DELETE FROM Employee WHERE SSN = '123456789';\nU4C: DELETE FROM Employee\n     WHERE  Dno IN (SELECT Dnumber FROM Department WHERE Dname = 'Research');\nU4D: DELETE FROM Employee;   -- XÓA TẤT CẢ!\n```\n\n> ⚠️ **Bẫy nghiêm trọng:** `DELETE FROM Employee;` (không WHERE) xóa sạch bảng. Luôn **test SELECT trước**: chạy `SELECT * FROM Employee WHERE ...` trước, khi chắc lọc đúng mới chuyển sang DELETE.\n\n### 4.6. UPDATE (Slide 87–89)\n\n```sql\nUPDATE TableName\nSET    Set-Clause\nWHERE  Condition;\n```\n\n> **U5:** Đổi location và Dnum của project 10 thành 'Bellaire' và 5.\n\n```sql\nU5: UPDATE  Project\n    SET     Plocation = 'Bellaire', Dnum = 5\n    WHERE   Pnumber = 10;\n```\n\n> **U6:** Tăng 10% lương cho nhân viên phòng 'Research'.\n\n```sql\nU6: UPDATE  Employee\n    SET     Salary = Salary * 1.1\n    WHERE   Dno IN ( SELECT  Dnumber\n                     FROM    Department\n                     WHERE   Dname = 'Research' );\n```\n\n`Salary = Salary * 1.1`: dùng giá trị **cũ** để tính giá trị mới (không lặp đệ quy).\n\n> 📝 **Tóm lại section 4 — INSERT/DELETE/UPDATE:**\n> - **INSERT** thêm tuple; có thể INSERT từ SELECT.\n> - **DELETE** thiếu WHERE = xóa toàn bảng (giữ cấu trúc).\n> - **UPDATE** sửa cột; SET nói cột nào, WHERE nói dòng nào.\n> - Cả 3 đều có thể dùng **subquery** trong WHERE.\n> - Mọi câu kiểm tra constraint (PK/FK/CHECK/NOT NULL); vi phạm → DBMS từ chối.\n> **Một câu ghi nhớ:** *Luôn tự hỏi \"WHERE của mình đã đúng chưa?\" trước khi gõ Enter.*\n\n> ❓ **Tự kiểm tra section 4:**\n> 1. Khác nhau giữa `DELETE FROM Employee` và `DROP TABLE Employee`?\n> 2. Viết UPDATE giảm 5% lương các nhân viên đang làm project 'ProductX'.\n> 3. Nếu INSERT 1 tuple EMPLOYEE với Dno=999 (không tồn tại) — chuyện gì xảy ra?\n\n---\n\n","file":"materials/DB-Chapter6.md","section":5},{"id":"c6-06","group":"c6","kind":"source","title":"5. Advanced DDL — Assertions & Triggers","markdown":"## 5. Advanced DDL — Assertions & Triggers\n\n### 5.1. Tại sao cần ASSERTION? (Motivation)\n\nCHECK ở mức tuple (Section 2.12) chỉ kiểm tra giá trị các cột trong **cùng 1 dòng**. Có ràng buộc liên quan **nhiều dòng** hoặc **nhiều bảng** — không thể viết bằng CHECK trên tuple. Ví dụ: \"Lương nhân viên không được lớn hơn lương trưởng phòng của họ.\" → cần **ASSERTION**.\n\n### 5.2. ASSERTION (Slide 90–91)\n\n> ASSERTION biểu diễn các ràng buộc **không vừa các loại cơ bản** của SQL.\n> Cú pháp: `CREATE ASSERTION` + tên + `CHECK` + condition.\n\n```sql\nCREATE ASSERTION Salary_constraint\nCHECK ( NOT EXISTS (SELECT  *\n                    FROM    Employee E, Employee M, Department D\n                    WHERE   E.Salary > M.Salary AND\n                            E.Dno = D.Dnumber AND\n                            D.MGRSSN = M.SSN ));\n```\n\n> ℹ️ Slide gốc viết `D.Number`; ý đúng theo schema là `D.Dnumber`.\n\n**Đọc câu này:** \"KHÔNG TỒN TẠI bộ 3 (E, M, D) sao cho lương E > lương M, E thuộc phòng D, M là trưởng phòng D.\"\n\n> 💡 **Pattern chuẩn của ASSERTION:** `CHECK (NOT EXISTS (subquery tìm ra trường hợp vi phạm))` — \"không được tồn tại trường hợp xấu\".\n\n### 5.3. Trigger (Slide 92)\n\n> Trigger đặc tả **hành động** thực hiện khi **sự kiện** xảy ra và **điều kiện** thỏa.\n> Chi tiết: học ở Lab.\n\n> 💡 **Hiểu đơn giản — Trigger:** Báo cháy tự động. Sự kiện \"phát hiện khói\" (INSERT/UPDATE/DELETE) → kiểm tra điều kiện (\"nhiệt độ > 60°C\") → nếu đúng → thực hiện hành động (\"bật chuông\"). Trigger DB chạy code SQL/PL khi có thao tác trên bảng.\n\n| | **ASSERTION** | **TRIGGER** |\n|---|---|---|\n| Vai trò | Thụ động — cấm vi phạm | Chủ động — phản ứng khi sự kiện xảy ra |\n| Cú pháp | `CREATE ASSERTION ... CHECK (NOT EXISTS ...)` | `CREATE TRIGGER ... ON ... AFTER/BEFORE ... ` |\n\n---\n\n","file":"materials/DB-Chapter6.md","section":6},{"id":"c6-07","group":"c6","kind":"source","title":"6. Views — Quan hệ ảo","markdown":"## 6. Views — Quan hệ ảo\n\n### 6.1. Tại sao có VIEW? (Motivation)\n\nTrong DB lớn, người dùng khác cần thấy **các phần khác** của cùng dữ liệu:\n- Nhân sự: họ tên, lương, ngày vào làm.\n- Khách hàng: chỉ tên + liên lạc (KHÔNG lương!).\n- Phân tích: tổng hợp (số nhân viên/phòng), không cần từng người.\n\nNếu mỗi nhóm có bảng riêng → trùng lặp, khó đồng bộ. **VIEW = bảng ảo** không lưu vật lý, được tính từ bảng gốc.\n\n### 6.2. View — Khái niệm (Slide 93)\n\n> - View là **bảng \"ảo\"** dẫn xuất từ các bảng khác.\n> - Cho **giới hạn update** (vì có thể không lưu vật lý).\n> - Cho **toàn bộ query**.\n> - Tiện lợi để biểu diễn các thao tác phức tạp.\n\n> 💡 **Hiểu đơn giản:** View là **kính lọc**. Base table có toàn bộ dữ liệu; view chỉ cho thấy phần cần thiết theo góc nhìn đã định.\n\n### 6.3. View — Cú pháp (Slide 94)\n\n```sql\nCREATE VIEW <view name> [(newColumnName[,...])]\nAS     <SELECT statement>\n[WITH [CASCADED|LOCAL] CHECK OPTION];\n\nDROP VIEW <view name> [RESTRICT | CASCADE];\n```\n\n- **WITH CHECK OPTION**: cấm dòng \"di chuyển\" khỏi view.\n- **LOCAL/CASCADED**: cho view derived từ view khác (view hierarchy).\n\n### 6.4. View — Ví dụ cơ bản (Slide 95)\n\n```sql\nCREATE VIEW Works_on_new AS\nSELECT  Fname, Lname, Pname, Hours\nFROM    Employee, Project, Works_on\nWHERE   SSN = ESSN AND Pno = Pnumber;\n\n-- Query trên view như trên bảng thường:\nSELECT  Fname, Lname FROM Works_on_new WHERE Pname = 'Seena';\n\nDROP VIEW Works_on_new;\n```\n\nTiện lợi: không cần lặp lại 3-bảng-JOIN mỗi lần.\n\n### 6.5. View với WITH CHECK OPTION (Slide 96)\n\n```sql\nV1: CREATE VIEW EMP_D5\n    AS SELECT  SSN, Fname, Lname, Salary, DNO\n       FROM    EMPLOYEE\n       WHERE   DNO = 5\n    WITH CHECK OPTION;\n```\n\n```sql\nV2: UPDATE  EMP_D5\n    SET     DNO = 4\n    WHERE   SSN = '123456789';\n```\n\n→ **CẤM!** Nếu cho phép, dòng đó sẽ có DNO=4 ≠ 5 → \"biến mất\" khỏi view.\n\n```sql\nV3: INSERT INTO EMP_D5\n    VALUES ('111222333', 'Mary', 'Jane', 1, 40000);\n```\n\n→ **CẤM!** Insert dòng DNO=1 sẽ không thuộc view ngay sau insert.\n\n> 💡 **Hiểu đơn giản — WITH CHECK OPTION:** Coi view như \"ô cửa sổ\" nhìn vào bảng gốc. CHECK OPTION nói: \"Mọi thay đổi qua cửa sổ phải vẫn thấy được qua cửa sổ — không cho tạo/sửa dòng khiến nó biến mất khỏi tầm nhìn.\"\n\n### 6.6. View Update — Khi nào view là updatable? (Slide 97)\n\n**Updatable nếu và chỉ nếu:**\n1. **`DISTINCT` không được dùng**.\n2. Mọi phần tử trong SELECT là **tên cột** (không phải hằng/biểu thức/aggregate) và không cột nào xuất hiện 2 lần.\n3. **FROM chỉ có 1 bảng** (single source).\n4. **WHERE không có nested SELECT** tham chiếu bảng trong FROM.\n5. **Không có GROUP BY hoặc HAVING**.\n6. Mọi dòng thêm qua view không vi phạm constraint của base table.\n\n**Bảng quyết định:**\n\n| Điều kiện view | Updatable? | Lý do |\n|---|---|---|\n| 1 bảng, chỉ cột thường | ✅ | Map trực tiếp về base |\n| Có DISTINCT | ❌ | Không biết update dòng gốc nào |\n| Có aggregate (COUNT, AVG, SUM) | ❌ | Mỗi row view = nhiều row gốc |\n| Có GROUP BY/HAVING | ❌ | Mỗi row view = 1 group |\n| Có join nhiều bảng | Thường ❌ | 1 row view = nhiều base rows |\n\n> 💡 **Vì sao có giới hạn:** Khi view phức tạp (aggregate `SUM(Salary)`), DBMS **không biết** dòng nào của base cần sửa để cập nhật `SUM(Salary)` mới — vì 1 giá trị aggregate đến từ nhiều dòng.\n\n> 📝 **Tóm lại section 5+6 — Assertions, Triggers, Views:**\n> - **ASSERTION** = ràng buộc tổng quát qua nhiều bảng/dòng — pattern `CHECK (NOT EXISTS ...)`.\n> - **TRIGGER** = hành động tự động khi sự kiện — học chi tiết ở Lab.\n> - **VIEW** = bảng ảo; query đầy đủ, update có giới hạn.\n> - **WITH CHECK OPTION** chặn row di chuyển khỏi view.\n> **Một câu ghi nhớ:** *View là cửa sổ ảo nhìn vào dữ liệu thật — dùng để bảo mật, đơn giản hóa query, và tách biệt nghiệp vụ khỏi cấu trúc bảng gốc.*\n\n> ❓ **Tự kiểm tra section 5–6:**\n> 1. View khác base table ở điểm nào?\n> 2. `WITH CHECK OPTION` chặn tình huống gì?\n> 3. View có GROUP BY có updatable không? Tại sao?\n> 4. Phân biệt ASSERTION và TRIGGER.\n\n---\n\n","file":"materials/DB-Chapter6.md","section":7},{"id":"c6-08","group":"c6","kind":"source","title":"7. DCL — Data Control Language (Slide 98–108)","markdown":"## 7. DCL — Data Control Language (Slide 98–108)\n\n> Phần này thuộc **Chapter 9** + homework. Slide chính giới thiệu sơ.\n\n### 7.1. Tại sao cần DCL? (Motivation)\n\nDB công ty có **hàng trăm user**: DBA, lập trình viên, nhân viên, khách hàng. Mỗi loại cần quyền khác nhau:\n- DBA: toàn quyền.\n- Lập trình viên: SELECT mọi bảng, INSERT/UPDATE bảng nghiệp vụ.\n- Nhân viên thường: SELECT trên view giới hạn.\n- Khách hàng: chỉ thấy view sản phẩm.\n\n→ Cần GRANT (cấp) và REVOKE (thu) — đây là DCL.\n\n### 7.2. DCL Overview (Slide 99–100)\n\n**Lệnh:** GRANT, REVOKE.\n\n**Dựa trên 3 đối tượng:**\n- **Users**\n- **Database objects** (table, view, schema)\n- **Privileges**: SELECT, MODIFY (INSERT/UPDATE/DELETE), REFERENCE\n\n**Cú pháp:**\n```sql\nGRANT  <privilege list>\nON     <database objects>\nTO     <user list>;\n\nREVOKE <privilege list>\nON     <database objects>\nFROM   <user list>;\n```\n\n### 7.3. Propagation — GRANT OPTION (Slide 101)\n\nKhi A cấp quyền trên R cho B:\n- **Có WITH GRANT OPTION** → B có thể cấp tiếp quyền đó cho người khác (lan truyền).\n- **Không có** → B chỉ dùng, không cấp tiếp.\n\n> 💡 **Hiểu đơn giản:** WITH GRANT OPTION giống như không chỉ cho bạn mượn chìa khóa, mà còn cho phép **photocopy chìa** đưa người khác.\n\n### 7.4. DCL — Examples chi tiết (Slide 102–108)\n\n**Slide 102** — DBA cấp quyền tạo bảng cho A1:\n\n```sql\nGRANT CREATETAB TO A1;\n-- Hoặc trong SQL2:\nCREATE SCHEMA EXAMPLE AUTHORIZATION A1;\n```\n\n**Slide 103** — A1 cấp INSERT/DELETE cho A2 (không lan truyền):\n\n```sql\nGRANT INSERT, DELETE ON EMPLOYEE, DEPARTMENT TO A2;\n```\n\n**Slide 104 — Figure 23.1 — Schema rút gọn cho DCL example:**\n\n```mermaid\nerDiagram\n    EMPLOYEE {\n        VARCHAR Name\n        CHAR Ssn PK\n        DATE Bdate\n        VARCHAR Address\n        CHAR Sex\n        DECIMAL Salary\n        INT Dno FK\n    }\n    DEPARTMENT {\n        INT Dnumber PK\n        VARCHAR Dname\n        CHAR Mgr_ssn FK\n    }\n    DEPARTMENT ||--o{ EMPLOYEE : has\n    EMPLOYEE ||--o{ DEPARTMENT : manages\n```\n\n**Slide 105** — A1 cấp SELECT cho A3 WITH GRANT OPTION; A3 cấp tiếp cho A4 (không lan truyền):\n\n```sql\nGRANT SELECT ON EMPLOYEE, DEPARTMENT\nTO A3 WITH GRANT OPTION;\n\n-- Sau đó A3 chạy:\nGRANT SELECT ON EMPLOYEE TO A4;\n-- A4 không thể propagate vì không có GRANT OPTION\n```\n\n**Sơ đồ lan truyền:**\n\n```mermaid\nflowchart LR\n    A1[A1 - owner] -->|GRANT SELECT WITH GRANT OPTION| A3[A3]\n    A3 -->|GRANT SELECT only| A4[A4]\n    A4 -. cannot grant further .-> X[Other users]\n```\n\n**Slide 106 — REVOKE cascades:**\n\n```sql\nREVOKE SELECT ON EMPLOYEE FROM A3;\n-- DBMS TỰ ĐỘNG revoke A4 vì A3 đã cấp A4 mà A3 không còn quyền\n```\n\n> 💡 **Hiểu đơn giản — propagation revoke:** Chìa khóa được sao chép. A1 đưa chìa cho A3 kèm photocopy (GRANT OPTION). A3 photo chìa đưa A4. Khi A1 lấy lại chìa từ A3, A4 **cũng tự động mất chìa** — vì cả 2 chìa đều bắt nguồn từ A1.\n\n**Slide 107 — Limited SELECT qua VIEW:**\n\n```sql\nCREATE VIEW A3EMPLOYEE AS\n  SELECT  NAME, BDATE, ADDRESS\n  FROM    EMPLOYEE\n  WHERE   DNO = 5;\n\nGRANT SELECT ON A3EMPLOYEE TO A3\nWITH GRANT OPTION;\n```\n\n→ Combo **View + GRANT** — pattern phổ biến để cấp quyền hạn chế theo cột + dòng.\n\n**Slide 108 — Column-level privilege:**\n\n```sql\nGRANT UPDATE ON EMPLOYEE (SALARY) TO A4;\n```\n\n- **UPDATE/INSERT**: có thể giới hạn cột.\n- **SELECT/DELETE**: KHÔNG đặc tả cột (muốn giới hạn cột → dùng VIEW).\n\n> 📝 **Tóm lại section 7 — DCL:**\n> - **GRANT** cấp, **REVOKE** thu.\n> - **WITH GRANT OPTION** cho phép lan truyền.\n> - **REVOKE lan truyền (cascade)**: thu từ A → tự thu từ mọi người A đã cấp.\n> - **UPDATE/INSERT** giới hạn cột được; **SELECT/DELETE** thì không (dùng VIEW).\n> **Một câu ghi nhớ:** *GRANT cấp – REVOKE thu – WITH GRANT OPTION cho lan truyền – REVOKE cascade thu sạch toàn bộ chuỗi.*\n\n> ❓ **Tự kiểm tra section 7:**\n> 1. WITH GRANT OPTION có ý nghĩa gì?\n> 2. Nếu A1 revoke quyền từ A3, quyền A3 đã cấp A4 bị ảnh hưởng thế nào?\n> 3. Muốn cho A4 chỉ được update cột Salary, câu lệnh là gì?\n\n---\n\n","file":"materials/DB-Chapter6.md","section":8},{"id":"c6-09","group":"c6","kind":"source","title":"Bảng Tra Nhanh Chương 6 (cheat sheet)","markdown":"## Bảng Tra Nhanh Chương 6 (cheat sheet)\n\n| Thuật ngữ | Định nghĩa 1 dòng | Ký hiệu/Cú pháp | Ví dụ COMPANY 1 dòng | Slide # |\n|---|---|---|---|---:|\n| SQL | Ngôn ngữ chuẩn cho RDBMS | — | `SELECT * FROM Employee;` | 4 |\n| DDL | Định nghĩa cấu trúc | CREATE/ALTER/DROP | `CREATE TABLE Employee (...);` | 6 |\n| DML | Thao tác dữ liệu | SELECT/INSERT/UPDATE/DELETE | `SELECT Fname FROM Employee;` | 4 |\n| DCL | Phân quyền | GRANT/REVOKE | `GRANT SELECT ON Employee TO A3;` | 99 |\n| Schema | Nhóm bảng cùng app | `CREATE SCHEMA Name AUTH user` | `CREATE SCHEMA Company AUTH JSmith;` | 8 |\n| Catalog | Tập schema có tên | — | — | 8 |\n| Base table | Bảng vật lý | `CREATE TABLE` | EMPLOYEE | 10 |\n| View | Bảng ảo | `CREATE VIEW` | `Works_on_new` | 93 |\n| Domain | Tên cho đặc tả cột | `CREATE DOMAIN X AS Type` | `CREATE DOMAIN SSN_TYPE AS CHAR(9);` | 13 |\n| Primary Key | Định danh duy nhất | `PRIMARY KEY (col)` | `PRIMARY KEY (Ssn)` | 15 |\n| UNIQUE | Khóa thay thế | `UNIQUE (col)` | `UNIQUE (Dname)` | 15 |\n| Foreign Key | Trỏ tới PK bảng khác | `FOREIGN KEY (col) REFERENCES T(c)` | `FOREIGN KEY (Dno) REFERENCES Department(Dnumber)` | 16 |\n| Referential Action | Hành động khi cha thay đổi | `ON DELETE/UPDATE {RESTRICT\\|CASCADE\\|SET NULL\\|SET DEFAULT}` | `ON DELETE CASCADE` | 16 |\n| NOT NULL | Cấm NULL | `col Type NOT NULL` | `Salary DECIMAL(10,2) NOT NULL` | 17 |\n| DEFAULT | Giá trị mặc | `col Type DEFAULT v` | `Dno INT DEFAULT 1` | 17 |\n| CHECK | Boolean ràng buộc | `CHECK (cond)` | `CHECK (Dnumber > 0)` | 17 |\n| CONSTRAINT name | Đặt tên ràng buộc | `CONSTRAINT n PK/FK/CHECK ...` | `CONSTRAINT EMPPK PK (Ssn)` | 21 |\n| DROP | Xóa object | `DROP {SCHEMA\\|TABLE\\|VIEW} N [CASCADE\\|RESTRICT]` | `DROP TABLE Department CASCADE;` | 24-25 |\n| ALTER | Sửa object | `ALTER TABLE T ADD/DROP/ALTER ...` | `ALTER TABLE Employee ADD Job VARCHAR(15);` | 26 |\n| SELECT cơ bản | Truy vấn | `SELECT cols FROM T WHERE cond` | `SELECT Fname FROM Employee WHERE Dno=5;` | 29 |\n| Multiset/Bag | Cho phép trùng | — | Kết quả SELECT mặc định | 28 |\n| DISTINCT | Loại trùng | `SELECT DISTINCT col` | `SELECT DISTINCT Salary FROM Employee;` | 44 |\n| Alias | Bí danh | `Table AS A` hoặc `Table A` | `Employee AS E, Employee AS S` | 39-40 |\n| Cartesian Product | FROM thiếu join | — | `FROM Employee, Department` không có WHERE | 42 |\n| `*` | Tất cả cột | `SELECT *` | `SELECT * FROM Employee;` | 43 |\n| UNION | Hợp tập, loại trùng | `Q1 UNION Q2` | Q9 | 45-46 |\n| INTERSECT | Giao tập | `Q1 INTERSECT Q2` | — | 45 |\n| EXCEPT | Hiệu tập | `Q1 EXCEPT Q2` | — | 45 |\n| LIKE | Khớp mẫu | `WHERE col LIKE 'p%_'` | `Address LIKE '%Houston,TX%'` | 47 |\n| NULL | Rỗng/không biết | `IS NULL` / `IS NOT NULL` | `WHERE Super_ssn IS NULL` | 49 |\n| 3-valued logic | T/F/Unknown | — | `NULL = NULL → UNKNOWN` | 49 |\n| Nested query | Subquery trong WHERE | `WHERE col IN (SELECT ...)` | Q13 | 51 |\n| Correlated subquery | Inner ref outer | — | Q14 | 52 |\n| IN | Thuộc tập | `WHERE col IN (set)` | `WHERE PNO IN (1,2,3)` | 51, 60 |\n| ANY/SOME | Lớn hơn min | `> ANY (subq)` | Q16 (nếu thay ALL→ANY) | 56 |\n| ALL | Lớn hơn max | `> ALL (subq)` | `Salary > ALL (...)` | 56 |\n| EXISTS | Subquery khác rỗng | `WHERE EXISTS (subq)` | Q14b | 57-58 |\n| NOT EXISTS | Subquery rỗng | `WHERE NOT EXISTS (subq)` | Q17 | 59 |\n| INNER JOIN | Mặc định | `R JOIN S ON ...` | Q1a | 62, 64 |\n| NATURAL JOIN | Tự nối cột cùng tên | `R NATURAL JOIN S` | Q1b | 63 |\n| LEFT OUTER JOIN | Giữ tuple trái | `R LEFT OUTER JOIN S ON ...` | Q3c | 64 |\n| RIGHT OUTER JOIN | Giữ tuple phải | — | — | 65 |\n| FULL OUTER JOIN | Giữ tuple cả 2 | — | — | 65 |\n| COUNT/SUM/MAX/MIN/AVG | Aggregate | `AGG(col)` | `AVG(Salary)` | 69 |\n| GROUP BY | Gom nhóm | `GROUP BY cols` | Q22 | 71-73 |\n| HAVING | Lọc nhóm | `HAVING aggcond` | `HAVING COUNT(*) > 2` | 75-76 |\n| ORDER BY | Sắp xếp | `ORDER BY cols [DESC/ASC]` | Q24 | 77 |\n| INSERT | Thêm tuple | `INSERT INTO T (cols) VALUES (...)` | U1, U2 | 81-82 |\n| INSERT từ SELECT | Thêm từ query | `INSERT INTO T SELECT ...` | U3A | 84 |\n| DELETE | Xóa tuple | `DELETE FROM T WHERE ...` | U4A | 85 |\n| UPDATE | Sửa tuple | `UPDATE T SET col=v WHERE ...` | U5, U6 | 87-88 |\n| ASSERTION | Ràng buộc cấp DB | `CREATE ASSERTION n CHECK (NOT EXISTS ...)` | Salary_constraint | 90-91 |\n| Trigger | Phản ứng tự động | (chi tiết ở Lab) | — | 92 |\n| CREATE VIEW | Tạo view | `CREATE VIEW V AS SELECT ...` | Works_on_new | 94-95 |\n| WITH CHECK OPTION | Cấm row di chuyển khỏi view | `... WITH CHECK OPTION;` | V1 (EMP_D5) | 96 |\n| GRANT | Cấp quyền | `GRANT priv ON obj TO user` | `GRANT SELECT ON Employee TO A2;` | 100 |\n| REVOKE | Thu quyền | `REVOKE priv ON obj FROM user` | `REVOKE SELECT FROM A3;` | 100 |\n| WITH GRANT OPTION | Cho lan truyền | `GRANT ... WITH GRANT OPTION` | Slide 105 | 101, 105 |\n| Column-level priv | Giới hạn cột | `GRANT UPDATE ON T(col) TO u` | `GRANT UPDATE ON EMPLOYEE(SALARY) TO A4;` | 108 |\n\n---\n\n","file":"materials/DB-Chapter6.md","section":9},{"id":"c6-10","group":"c6","kind":"source","title":"Sai lầm thường gặp (Top 10)","markdown":"## Sai lầm thường gặp (Top 10)\n\n| # | Sai lầm | Tại sao sai | Cách đúng |\n|---|---|---|---|\n| 1 | `WHERE Salary = NULL` | NULL không so sánh bằng `=`; kết quả luôn UNKNOWN | `WHERE Salary IS NULL` |\n| 2 | `SELECT Fname, COUNT(*) FROM Employee GROUP BY Dno;` | Fname không có trong GROUP BY và không phải aggregate | Thêm Fname vào GROUP BY, dùng `MAX(Fname)`, hoặc bỏ Fname |\n| 3 | `WHERE COUNT(*) > 2` (lọc nhóm trong WHERE) | WHERE chạy **trước** GROUP BY — chưa có nhóm | Dùng `HAVING COUNT(*) > 2` |\n| 4 | `DELETE FROM Employee;` (quên WHERE) | Xóa **toàn bộ** dữ liệu | Luôn test `SELECT * ... WHERE` trước, sau đó DELETE |\n| 5 | `FROM Employee, Department` không có WHERE | Sinh Cartesian product, kết quả sai và rất to | Thêm điều kiện join `WHERE Dno = Dnumber` |\n| 6 | `SELECT * FROM Employee NATURAL JOIN Department` | EMPLOYEE có `Dno`, DEPARTMENT có `Dnumber` — không cùng tên → kết quả Cartesian | Dùng `JOIN ... ON Dno = Dnumber` hoặc rename cột |\n| 7 | Quên alias khi self-join | DBMS không phân biệt được 2 vai trò | `FROM Employee E, Employee S WHERE E.Super_ssn = S.SSN` |\n| 8 | Dùng `IN (subquery)` nhưng subquery trả NULL → unexpected behavior | NULL trong tập làm `IN` trả về UNKNOWN | Đảm bảo subquery loại NULL hoặc dùng `EXISTS` |\n| 9 | `DROP TABLE T CASCADE` trên production mà không backup | Xóa toàn bộ data + ràng buộc + view phụ thuộc | Luôn backup; dùng RESTRICT để DBMS cảnh báo |\n| 10 | View có `GROUP BY` rồi cố UPDATE | View aggregate không updatable | Sửa thẳng trên base table |\n\n---\n\n","file":"materials/DB-Chapter6.md","section":10},{"id":"c6-11","group":"c6","kind":"source","title":"Câu Hỏi Ôn Tập (từ slide gốc) — Lời giải đầy đủ","markdown":"## Câu Hỏi Ôn Tập (từ slide gốc) — Lời giải đầy đủ\n\n### Exercise 1 (Slide 111) — Viết DDL từ schema mô tả\n\n**EMPLOYEE:** Fname/Lname VARCHAR(15) NOT NULL, Minit CHAR, SSN CHAR(9) NOT NULL PK, Bdate DATE earlier than 1/1/1999, Address VARCHAR(100), Sex CHAR {F/M}, Salary DECIMAL(10,2), SuperSSN CHAR(9) refers EMPLOYEE(SSN), Dno INT NOT NULL default 1 refers DEPARTMENT(Dnumber) ON DELETE SET DEFAULT.\n\n**DEPARTMENT:** Dname VARCHAR(15) NOT NULL UNIQUE, Dnumber INT NOT NULL PK, MgrSSN CHAR(9) NOT NULL default '888665555' refers EMPLOYEE(SSN) ON DELETE SET DEFAULT ON UPDATE CASCADE, MgrStartDate DATE, CreateDate DATE earlier than MgrStartDate.\n\n<details><summary>Xem lời giải</summary>\n\nVì EMPLOYEE và DEPARTMENT tham chiếu vòng (circular FK), an toàn nhất là tạo bảng trước, sau đó dùng ALTER TABLE thêm FK.\n\n```sql\nCREATE TABLE EMPLOYEE\n( Fname     VARCHAR(15) NOT NULL,\n  Minit     CHAR,\n  Lname     VARCHAR(15) NOT NULL,\n  SSN       CHAR(9)     NOT NULL,\n  Bdate     DATE,\n  Address   VARCHAR(100),\n  Sex       CHAR,\n  Salary    DECIMAL(10,2),\n  SuperSSN  CHAR(9),\n  Dno       INT         NOT NULL DEFAULT 1,\n  CONSTRAINT EMP_PK PRIMARY KEY (SSN),\n  CONSTRAINT EMP_BDATE_CHK CHECK (Bdate < DATE '1999-01-01'),\n  CONSTRAINT EMP_SEX_CHK CHECK (Sex IN ('F','M'))\n);\n\nCREATE TABLE DEPARTMENT\n( Dname         VARCHAR(15) NOT NULL,\n  Dnumber       INT         NOT NULL,\n  MgrSSN        CHAR(9)     NOT NULL DEFAULT '888665555',\n  MgrStartDate  DATE,\n  CreateDate    DATE,\n  CONSTRAINT DEPT_PK PRIMARY KEY (Dnumber),\n  CONSTRAINT DEPT_DNAME_UK UNIQUE (Dname),\n  CONSTRAINT DEPT_DATE_CHK CHECK (CreateDate < MgrStartDate)\n);\n\nALTER TABLE EMPLOYEE\nADD CONSTRAINT EMP_SUPER_FK\nFOREIGN KEY (SuperSSN) REFERENCES EMPLOYEE(SSN);\n\nALTER TABLE EMPLOYEE\nADD CONSTRAINT EMP_DEPT_FK\nFOREIGN KEY (Dno) REFERENCES DEPARTMENT(Dnumber)\nON DELETE SET DEFAULT;\n\nALTER TABLE DEPARTMENT\nADD CONSTRAINT DEPT_MGR_FK\nFOREIGN KEY (MgrSSN) REFERENCES EMPLOYEE(SSN)\nON DELETE SET DEFAULT\nON UPDATE CASCADE;\n```\n\n</details>\n\n### Exercise 2 (Slide 112) — 7 câu SELECT\n\n**Câu 1:** Lấy tên các nhân viên thuộc phòng nằm tại Houston.\n\n<details><summary>Xem lời giải</summary>\n\n```sql\nSELECT DISTINCT E.Fname, E.Lname\nFROM   Employee E, Department D, Dept_locations L\nWHERE  E.Dno = D.Dnumber\n  AND  D.Dnumber = L.Dnumber\n  AND  L.Dlocation = 'Houston';\n```\nDISTINCT đề phòng phòng có nhiều location dẫn đến dòng trùng.\n</details>\n\n**Câu 2:** Lương trung bình của tất cả nữ nhân viên.\n\n<details><summary>Xem lời giải</summary>\n\n```sql\nSELECT AVG(Salary) AS Avg_female_salary\nFROM   Employee\nWHERE  Sex = 'F';\n```\n</details>\n\n**Câu 3:** Đếm số con trai của John Smith.\n\n<details><summary>Xem lời giải</summary>\n\n```sql\nSELECT COUNT(*) AS Number_of_sons\nFROM   Employee E, Dependent D\nWHERE  E.Ssn = D.Essn\n  AND  E.Fname = 'John'\n  AND  E.Lname = 'Smith'\n  AND  D.Relationship = 'Son';\n```\n</details>\n\n**Câu 4:** Tên các nhân viên có lương cao nhất công ty.\n\n<details><summary>Xem lời giải</summary>\n\n```sql\nSELECT Fname, Lname\nFROM   Employee\nWHERE  Salary = (SELECT MAX(Salary) FROM Employee);\n```\n(Có thể có nhiều người cùng lương cao nhất → query này trả về tất cả.)\n</details>\n\n**Câu 5:** Số và tên các phòng có số nhân viên nhiều nhất.\n\n<details><summary>Xem lời giải</summary>\n\n```sql\nSELECT D.Dnumber, D.Dname\nFROM   Department D, Employee E\nWHERE  D.Dnumber = E.Dno\nGROUP BY D.Dnumber, D.Dname\nHAVING COUNT(*) >= ALL\n       (SELECT COUNT(*) FROM Employee GROUP BY Dno);\n```\n</details>\n\n**Câu 6:** Với mỗi phòng có lương trung bình > $30,000, lấy tên phòng và số nhân viên.\n\n<details><summary>Xem lời giải</summary>\n\n```sql\nSELECT D.Dname, COUNT(*) AS No_of_employees\nFROM   Department D, Employee E\nWHERE  D.Dnumber = E.Dno\nGROUP BY D.Dnumber, D.Dname\nHAVING AVG(E.Salary) > 30000;\n```\n</details>\n\n**Câu 7:** Với mỗi phòng có hơn 2 nhân viên, lấy số phòng và **số nhân viên có lương > $40,000**.\n\n<details><summary>Xem lời giải</summary>\n\n```sql\nSELECT E.Dno,\n       SUM(CASE WHEN E.Salary > 40000 THEN 1 ELSE 0 END) AS High_salary_count\nFROM   Employee E\nGROUP BY E.Dno\nHAVING COUNT(*) > 2;\n```\nMột số DBMS hỗ trợ `COUNT(CASE WHEN Salary > 40000 THEN 1 END)`; cách `SUM(CASE...)` rõ nghĩa và phổ biến.\n</details>\n\n### Exercise 3 (Slide 113) — Định nghĩa 4 view\n\n<details><summary>Xem lời giải</summary>\n\n**V1.** Department name, manager name, manager salary cho mỗi phòng:\n\n```sql\nCREATE VIEW Dept_Manager_Info AS\nSELECT D.Dname,\n       E.Fname AS Mgr_Fname,\n       E.Lname AS Mgr_Lname,\n       E.Salary AS Mgr_Salary\nFROM   Department D, Employee E\nWHERE  D.Mgr_ssn = E.Ssn;\n```\n\n**V2.** Employee name, supervisor name, employee salary cho nhân viên phòng Research:\n\n```sql\nCREATE VIEW Research_Emp_Supervisor AS\nSELECT E.Fname AS Emp_Fname,\n       E.Lname AS Emp_Lname,\n       S.Fname AS Sup_Fname,\n       S.Lname AS Sup_Lname,\n       E.Salary AS Emp_Salary\nFROM   Employee E, Employee S, Department D\nWHERE  E.Super_ssn = S.Ssn\n  AND  E.Dno = D.Dnumber\n  AND  D.Dname = 'Research';\n```\n\n**V3.** Project name, controlling department name, số nhân viên, tổng giờ/tuần — cho mỗi project:\n\n```sql\nCREATE VIEW Project_Summary AS\nSELECT P.Pname,\n       D.Dname,\n       COUNT(W.Essn) AS No_of_employees,\n       SUM(W.Hours)  AS Total_hours\nFROM   Project P, Department D, Works_on W\nWHERE  P.Dnum = D.Dnumber\n  AND  P.Pnumber = W.Pno\nGROUP BY P.Pnumber, P.Pname, D.Dname;\n```\n\n**V4.** Như V3 nhưng chỉ project có **hơn 2 nhân viên** làm:\n\n```sql\nCREATE VIEW Project_Summary_More_Than_2 AS\nSELECT P.Pname,\n       D.Dname,\n       COUNT(W.Essn) AS No_of_employees,\n       SUM(W.Hours)  AS Total_hours\nFROM   Project P, Department D, Works_on W\nWHERE  P.Dnum = D.Dnumber\n  AND  P.Pnumber = W.Pno\nGROUP BY P.Pnumber, P.Pname, D.Dname\nHAVING COUNT(W.Essn) > 2;\n```\n\n</details>\n\n### Exercise 4 (Slide 114) — View update\n\nView:\n```sql\nCREATE VIEW DEPT_SUMMARY (D, C, Total_s, Average_s)\nAS SELECT Dno, COUNT(*), SUM(Salary), AVG(Salary)\nFROM   EMPLOYEE\nGROUP BY Dno;\n```\n\n<details><summary>Xem lời giải (a–e)</summary>\n\n| Câu | Allowed? | Lý do |\n|---|---|---|\n| (a) `SELECT *` | ✅ | Query trên view aggregate được phép |\n| (b) `SELECT D, C ... WHERE TOTAL_S > 100000` | ✅ | Lọc trên kết quả view được phép |\n| (c) Nested query | ✅ | Query nested trên view được phép |\n| (d) `UPDATE ... SET D=3 WHERE D=4` | ❌ | View có GROUP BY và aggregate → không updatable |\n| (e) `DELETE ... WHERE C > 4` | ❌ | Mỗi row view = 1 group, không phải tuple gốc |\n\n**Query tương ứng trên base relation:**\n\n(a):\n```sql\nSELECT Dno AS D, COUNT(*) AS C,\n       SUM(Salary) AS Total_s, AVG(Salary) AS Average_s\nFROM   EMPLOYEE\nGROUP BY Dno;\n```\n\n(b):\n```sql\nSELECT Dno AS D, COUNT(*) AS C\nFROM   EMPLOYEE\nGROUP BY Dno\nHAVING SUM(Salary) > 100000;\n```\n\n(c):\n```sql\nSELECT Dno AS D, AVG(Salary) AS Average_s\nFROM   EMPLOYEE\nGROUP BY Dno\nHAVING COUNT(*) > (SELECT COUNT(*) FROM EMPLOYEE WHERE Dno = 4);\n```\n\n(d, e): Không có update/delete base tương ứng an toàn vì mỗi row view là 1 group tổng hợp.\n\n</details>\n\n---\n\n","file":"materials/DB-Chapter6.md","section":11},{"id":"c6-12","group":"c6","kind":"source","title":"Bài Tập Tự Luyện (5 bài)","markdown":"## Bài Tập Tự Luyện (5 bài)\n\n> **Bài 1 (dễ):** Liệt kê tên (Fname, Lname) và lương của các nhân viên có lương > 30000, sắp xếp giảm dần theo lương.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> ```sql\n> SELECT Fname, Lname, Salary\n> FROM   Employee\n> WHERE  Salary > 30000\n> ORDER BY Salary DESC;\n> ```\n> </details>\n\n> **Bài 2 (trung bình):** Liệt kê tên các nhân viên cùng tên phòng họ làm. **Bao gồm cả** những nhân viên không có phòng (Dno = NULL).\n>\n> <details><summary>Xem lời giải</summary>\n>\n> Dùng LEFT OUTER JOIN:\n>\n> ```sql\n> SELECT E.Fname, E.Lname, D.Dname\n> FROM   Employee E LEFT OUTER JOIN Department D\n>        ON E.Dno = D.Dnumber;\n> ```\n> Nhân viên có Dno = NULL sẽ có Dname = NULL.\n> </details>\n\n> **Bài 3 (khó — Division pattern):** Tìm tên các nhân viên đã làm việc trên **TẤT CẢ** các project do phòng số 5 kiểm soát.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> Đây là kiểu \"Division\" trong RA. Pattern chuẩn: **NOT EXISTS lồng kép**.\n>\n> \"Nhân viên E làm việc trên TẤT CẢ project của phòng 5\"\n> ⇔ \"KHÔNG TỒN TẠI project P thuộc phòng 5 mà E KHÔNG làm việc trên P.\"\n>\n> ```sql\n> SELECT Fname, Lname\n> FROM   Employee E\n> WHERE  NOT EXISTS (\n>          SELECT *\n>          FROM   Project P\n>          WHERE  P.Dnum = 5\n>            AND  NOT EXISTS (\n>                  SELECT *\n>                  FROM   Works_on W\n>                  WHERE  W.Pno = P.Pnumber\n>                    AND  W.Essn = E.Ssn ));\n> ```\n> </details>\n\n> **Bài 4 (trung bình):** Với mỗi phòng có HƠN 3 nhân viên, lấy tên phòng và lương trung bình.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> ```sql\n> SELECT D.Dname, AVG(E.Salary) AS AvgSal\n> FROM   Department D, Employee E\n> WHERE  D.Dnumber = E.Dno\n> GROUP BY D.Dname\n> HAVING COUNT(*) > 3;\n> ```\n> </details>\n\n> **Bài 5 (dễ):** Tạo view tóm tắt cho mỗi project: tên project, tổng giờ làm, số nhân viên tham gia.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> ```sql\n> CREATE VIEW Project_Brief AS\n> SELECT P.Pname,\n>        SUM(W.Hours)  AS Total_hours,\n>        COUNT(W.Essn) AS Num_employees\n> FROM   Project P, Works_on W\n> WHERE  P.Pnumber = W.Pno\n> GROUP BY P.Pname;\n> ```\n> View này **KHÔNG updatable** vì có aggregate (SUM, COUNT) và GROUP BY.\n> </details>\n\n---\n\n","file":"materials/DB-Chapter6.md","section":12},{"id":"c6-13","group":"c6","kind":"source","title":"Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\n**Trắc nghiệm (~30 phút, 15 câu):**\n1. Phân loại lệnh: CREATE/ALTER/DROP = DDL; SELECT/INSERT/UPDATE/DELETE = DML; GRANT/REVOKE = DCL.\n2. NULL & 3-valued logic: cho biểu thức Boolean với NULL, kết quả T/F/U?\n3. DISTINCT: kết quả có trùng không nếu thêm/bỏ DISTINCT?\n4. GROUP BY + HAVING: cột nào được phép trong SELECT?\n5. CASCADE vs RESTRICT trong DROP / FOREIGN KEY.\n6. INNER JOIN vs OUTER JOIN: tuple nào xuất hiện?\n7. EXISTS / NOT EXISTS với correlated subquery — kết quả đúng?\n8. UNION vs UNION ALL: loại trùng?\n9. View updatable: cho định nghĩa, view có updatable không?\n10. Privilege propagation: cho chuỗi GRANT/REVOKE, ai còn quyền gì?\n\n**Tự luận (~60 phút, 3–5 câu):**\n1. **CREATE TABLE đầy đủ** cho 1 schema với mọi loại constraint (giống Exercise 1).\n2. **5–10 câu SELECT** từ dễ đến khó:\n   - 1–2 câu single-table với WHERE.\n   - 2–3 câu JOIN nhiều bảng.\n   - 1–2 câu GROUP BY + HAVING.\n   - 1 câu nested query (IN/EXISTS/ALL).\n   - 1 câu OUTER JOIN hoặc UNION.\n3. **INSERT/UPDATE/DELETE** kèm subquery — vd tăng lương cho phòng có lương trung bình thấp nhất.\n4. **Định nghĩa VIEW** + viết query trên view.\n5. **GRANT/REVOKE** chuỗi với GRANT OPTION + giải thích lan truyền.\n\n**Mẹo làm bài:**\n- **Đọc kỹ đề** — chú ý từ \"tất cả\" (cần `NOT EXISTS` hoặc `> ALL`), \"có ít nhất 1\" (`EXISTS`/`IN`), \"không có\" (`NOT EXISTS`).\n- **Bám đúng schema COMPANY** — nhớ tên cột chính xác.\n- **Kiểm tra n-1 join conditions** cho n bảng.\n- **Đặt alias** khi self-join.\n- Khi gặp câu \"for all\" → nghĩ ngay đến **NOT EXISTS lồng kép** (Bài 3 tự luyện).\n\n---\n\n","file":"materials/DB-Chapter6.md","section":13},{"id":"c6-14","group":"c6","kind":"source","title":"Liên Kết Lab / BTL (TH5)","markdown":"## Liên Kết Lab / BTL (TH5)\n\n| Tài liệu | Phần liên quan đến chương 6 |\n|---|---|\n| **Labs/Lab 1.docx** | Thực hành CREATE TABLE đầy đủ với schema COMPANY hoặc tương đương; INSERT data mẫu; viết SELECT cơ bản. |\n| **Labs/Lab 2.docx** | SELECT nâng cao (JOIN, GROUP BY, nested query), UPDATE/DELETE có điều kiện phức tạp, ràng buộc FK ON DELETE CASCADE/SET NULL. |\n| **Exercises/6_Exercise_SQL.docx** | Bài tập SQL theo từng dạng — tốt cho luyện tay trước khi thi. |\n| **BTL1_DB_Lab/** | Thiết kế ER → ánh xạ → CREATE TABLE chuẩn (DDL của chương 6). |\n| **BTL2_DB_Lab/** | Xây ứng dụng có truy vấn — chương 6 là **kiến thức cốt lõi** (SELECT phức tạp, view, trigger, GRANT/REVOKE). |\n| **CourseOutline/DCMH.CO2013** | Phần grading: SQL chiếm ~25-30% đề thi cuối kỳ + toàn bộ lab/BTL. |\n\n---\n\n","file":"materials/DB-Chapter6.md","section":14},{"id":"c6-15","group":"c6","kind":"source","title":"Bảng Tổng Hợp Thuật Ngữ Chương 6 (Glossary)","markdown":"## Bảng Tổng Hợp Thuật Ngữ Chương 6 (Glossary)\n\n| # | EN | VI | Định nghĩa ngắn | Slide |\n|---:|---|---|---|---:|\n| 1 | SQL | Ngôn ngữ truy vấn có cấu trúc | Ngôn ngữ chuẩn cho RDBMS | 4 |\n| 2 | DDL | Ngôn ngữ định nghĩa | Create/Alter/Drop | 4, 6 |\n| 3 | DML | Ngôn ngữ thao tác | Select/Insert/Update/Delete | 4 |\n| 4 | DCL | Ngôn ngữ điều khiển | Grant/Revoke/Commit/Rollback | 4, 99 |\n| 5 | Schema | Lược đồ | Nhóm bảng cùng app | 8 |\n| 6 | Catalog | Catalog | Tập schema có tên | 8 |\n| 7 | Base table | Bảng cơ sở | Bảng vật lý | 10 |\n| 8 | View | Khung nhìn (bảng ảo) | Bảng ảo từ SELECT | 10, 93 |\n| 9 | Domain | Miền | Tên cho đặc tả cột | 13 |\n| 10 | Constraint | Ràng buộc | Điều kiện dữ liệu phải thỏa | 14 |\n| 11 | Primary Key | Khóa chính | Định danh duy nhất | 15 |\n| 12 | UNIQUE | Khóa thay thế | Không trùng, cho NULL | 15 |\n| 13 | Foreign Key | Khóa ngoại | Tham chiếu PK bảng khác | 16 |\n| 14 | RESTRICT | Hạn chế | Chặn nếu còn phụ thuộc | 16, 24 |\n| 15 | CASCADE | Lan truyền | Xóa/sửa lan đến phụ thuộc | 16, 24 |\n| 16 | SET NULL | Đặt NULL | FK → NULL | 16 |\n| 17 | SET DEFAULT | Đặt mặc định | FK → DEFAULT | 16 |\n| 18 | NOT NULL | Không rỗng | Bắt buộc có giá trị | 17 |\n| 19 | DEFAULT | Mặc định | Giá trị tự dùng | 17 |\n| 20 | CHECK | Kiểm tra | Boolean condition | 17, 23 |\n| 21 | CONSTRAINT name | Đặt tên ràng buộc | Để DROP/ALTER sau | 21 |\n| 22 | DROP | Xóa | Schema/Table/Constraint | 24 |\n| 23 | ALTER | Sửa | Add/Drop/Change | 26 |\n| 24 | SELECT | Truy vấn | Lấy dữ liệu | 28 |\n| 25 | Multiset/Bag | Đa tập | Cho phép trùng | 28 |\n| 26 | DISTINCT | Loại trùng | Loại duplicate | 44 |\n| 27 | Alias / Tuple variable | Bí danh | Tên tạm cho relation | 39 |\n| 28 | Cartesian Product | Tích Descartes | FROM thiếu join | 42 |\n| 29 | `*` | Tất cả cột | SELECT all | 43 |\n| 30 | UNION | Hợp | Gộp loại trùng | 45 |\n| 31 | INTERSECT | Giao | Có ở cả 2 | 45 |\n| 32 | EXCEPT | Hiệu | Trái không phải | 45 |\n| 33 | LIKE | Khớp mẫu | `%`, `_` | 47 |\n| 34 | NULL | Rỗng/không biết | Giá trị đặc biệt | 49 |\n| 35 | 3-valued logic | Logic 3 giá trị | T/F/Unknown | 49 |\n| 36 | Nested query | Truy vấn lồng | SELECT trong WHERE | 51 |\n| 37 | Correlated subquery | Subquery tương quan | Inner ref outer | 52 |\n| 38 | IN | Trong tập | Thuộc tập | 51, 60 |\n| 39 | ANY / SOME | Có ít nhất 1 | `>` ANY ≡ `> min` | 56 |\n| 40 | ALL | Mọi | `>` ALL ≡ `> max` | 56 |\n| 41 | EXISTS | Tồn tại | Subquery khác rỗng | 57 |\n| 42 | NOT EXISTS | Không tồn tại | Subquery rỗng | 57, 59 |\n| 43 | UNIQUE function | UNIQUE | Subquery không trùng | 57 |\n| 44 | EQUIJOIN | Join bằng | Join trên `=` | 61 |\n| 45 | NATURAL JOIN | Phép nối tự nhiên | Tự nối theo cột cùng tên | 63 |\n| 46 | INNER JOIN | Phép nối trong | Mặc định | 64 |\n| 47 | LEFT OUTER JOIN | Ngoài trái | Giữ tuple trái | 64 |\n| 48 | RIGHT OUTER JOIN | Ngoài phải | Giữ tuple phải | 65 |\n| 49 | FULL OUTER JOIN | Ngoài đầy đủ | Giữ cả 2 | 65 |\n| 50 | Aggregate | Hàm tổng hợp | COUNT/SUM/MAX/MIN/AVG | 69 |\n| 51 | GROUP BY | Gom nhóm | Tuple cùng giá trị → nhóm | 71 |\n| 52 | HAVING | Lọc nhóm | Sau GROUP BY | 75 |\n| 53 | ORDER BY | Sắp xếp | DESC/ASC | 77 |\n| 54 | INSERT | Chèn | Thêm tuple | 81 |\n| 55 | DELETE | Xóa | Xóa tuple | 85 |\n| 56 | UPDATE | Cập nhật | Sửa tuple | 87 |\n| 57 | ASSERTION | Khẳng định | Ràng buộc cấp DB | 90 |\n| 58 | Trigger | Kích hoạt tự động | Action khi event | 92 |\n| 59 | CREATE VIEW | Tạo view | Bảng ảo | 94 |\n| 60 | WITH CHECK OPTION | Tùy chọn kiểm tra | Cấm row migrate | 94, 96 |\n| 61 | GRANT | Cấp quyền | Privilege cho user | 100 |\n| 62 | REVOKE | Thu quyền | Lấy lại privilege | 100 |\n| 63 | GRANT OPTION | Quyền lan truyền | Cho phép cấp tiếp | 101 |\n| 64 | Column-level privilege | Quyền cấp cột | UPDATE/INSERT(col) | 108 |\n\n---\n\n","file":"materials/DB-Chapter6.md","section":15},{"id":"c6-16","group":"c6","kind":"source","title":"Đáp án Tự kiểm tra","markdown":"## Đáp án Tự kiểm tra\n\n**Section 1:**\n1. SQL là ngôn ngữ máy tính **chuẩn** (ISO/ANSI) cho RDBMS — mọi DBMS quan hệ phải hỗ trợ phần lõi SQL chuẩn; \"chuẩn\" có nghĩa Oracle/MySQL/PostgreSQL/SQL Server đều hiểu cùng một câu SQL cơ bản.\n2. `CREATE TABLE` thuộc **DDL** vì định nghĩa cấu trúc.\n3. Lấy danh sách nhân viên = `SELECT` → **DML**.\n\n**Section 2:**\n1. `Ssn CHAR(9)` hợp lý hơn `INT` vì SSN có thể có số 0 đầu, không dùng để tính toán số học, có độ dài cố định 9 ký tự.\n2. PRIMARY KEY: 1 mỗi bảng, **không NULL**, có index ngầm. UNIQUE: nhiều mỗi bảng, **cho NULL** (thường 1 NULL).\n3. Khi xóa 1 dòng Department, cột Dno của các Employee thuộc phòng đó được đặt thành **NULL**.\n4. RESTRICT từ chối nếu còn phụ thuộc (an toàn). CASCADE xóa luôn cả phụ thuộc (nguy hiểm).\n5. Vì 1 employee có thể làm nhiều project, 1 project có nhiều employee → chỉ Essn hoặc chỉ Pno không đủ định danh; cặp (Essn, Pno) định danh 1 dòng \"employee X làm project Y\".\n6. Đặt tên constraint để dễ DROP/ALTER sau, dễ debug khi DBMS báo lỗi.\n\n**Section 3:**\n1. WHERE lọc dòng **trước** GROUP BY (chưa có nhóm, không có aggregate). HAVING lọc nhóm **sau** GROUP BY (đã có nhóm, dùng aggregate được). `WHERE COUNT(*) > 2` sai vì lúc đó chưa group nên không có COUNT.\n2. Vì Employee xuất hiện 2 vai trò (supervisee và supervisor) trong cùng query → cần 2 alias.\n3. `SELECT Fname, Lname FROM Employee WHERE Super_ssn IS NULL;`\n4. INNER JOIN loại tuple không match; LEFT OUTER JOIN giữ tuple trái pad NULL. Ví dụ: nhân viên có Dno=NULL — INNER JOIN với Department loại; LEFT OUTER JOIN giữ với Dname=NULL.\n5. Tập giá trị giống nhau, hiệu năng thường tương đương (optimizer tối ưu). Khác: GROUP BY còn cho phép thêm aggregate trong SELECT.\n6. 100 × 5 = **500 dòng** (Cartesian product).\n\n**Section 4:**\n1. DELETE xóa tuple, **giữ cấu trúc**; DROP TABLE xóa cả cấu trúc + dữ liệu, bảng không còn tồn tại.\n2. `UPDATE Employee SET Salary = Salary * 0.95 WHERE Ssn IN (SELECT Essn FROM Works_on W, Project P WHERE W.Pno = P.Pnumber AND P.Pname = 'ProductX');`\n3. DBMS **từ chối INSERT** vì vi phạm FK (Dno trỏ Dnumber nhưng không có phòng 999) → báo `referential integrity violation`.\n\n**Section 5–6:**\n1. View là bảng ảo, không lưu vật lý, được tính từ base table mỗi khi query. Base table lưu dữ liệu thật.\n2. WITH CHECK OPTION chặn INSERT/UPDATE qua view nếu hành động làm row không còn thỏa điều kiện view và \"biến mất\" khỏi view.\n3. View có GROUP BY không updatable vì mỗi row view = 1 nhóm nhiều tuple gốc, không map trực tiếp về 1 tuple base.\n4. ASSERTION = ràng buộc thụ động (cấm vi phạm); TRIGGER = phản ứng chủ động (làm gì khi sự kiện xảy ra).\n\n**Section 7:**\n1. WITH GRANT OPTION cho phép người nhận cấp tiếp quyền cho user khác.\n2. Quyền A3 đã cấp A4 **cũng tự động bị thu hồi** — DBMS cascade revoke vì A3 không còn quyền nguồn.\n3. `GRANT UPDATE ON EMPLOYEE (SALARY) TO A4;`\n\n---\n\n","file":"materials/DB-Chapter6.md","section":16},{"id":"c6-17","group":"c6","kind":"source","title":"Mối Quan Hệ Với Các Chương Khác","markdown":"## Mối Quan Hệ Với Các Chương Khác\n\n- **Chương 5 — Relational Algebra:** SQL là **hiện thực thực tế** của RA. Mỗi SELECT có 1 (hoặc nhiều) cây RA tương đương. Học kỹ RA → hiểu SQL sâu hơn, đặc biệt khi tối ưu hóa.\n- **Chương 7 — Functional Dependencies & Normalization:** Sau khi học cách viết SQL trên schema đã có, chương 7 dạy cách **thiết kế schema chuẩn** (1NF/2NF/3NF/BCNF) để tránh dư thừa và update anomalies.\n- **Chương 2–4 — ER/EER & Mapping:** DDL trong chương 6 tạo bảng từ kết quả mapping ER/EER. Ví dụ WORKS_ON xuất hiện vì quan hệ M:N giữa EMPLOYEE và PROJECT.\n- **Chương 8 — Storage & Indexing:** `CREATE INDEX` cũng thuộc DDL. Hiệu năng SELECT phụ thuộc nhiều vào index.\n- **Lab/BTL:** Toàn bộ chương 6 là kiến thức nền cho Lab 1, Lab 2, BTL1 (DDL), BTL2 (DML + view + trigger).\n\n---\n\n","file":"materials/DB-Chapter6.md","section":17},{"id":"c6-18","group":"c6","kind":"source","title":"Phụ lục A — Slide-by-slide Coverage Ledger","markdown":"## Phụ lục A — Slide-by-slide Coverage Ledger\n\n| Slide | Nội dung | Mục tương ứng |\n|---:|---|---|\n| 1 | Title — Structured Query Language, Chapter 6 | 1.2 |\n| 2, 3, 5, 27, 80, 98 | Contents (gộp) | Mục lục đầu chương |\n| 4 | Introduction of SQL, DDL/DML/DCL | 1.2 |\n| 6 | DDL definition + CREATE/ALTER/DROP | 2.2 |\n| 7 | COMPANY schema diagram | 2.3 |\n| 8 | Schema and Catalog | 2.4 |\n| 9 | CREATE TABLE syntax | 2.5 |\n| 10 | Base tables, virtual relations, FK errors | 2.6 |\n| 11 | Basic Data Types | 2.7 |\n| 12 | TIMESTAMP, INTERVAL | 2.7 |\n| 13 | Domains | 2.8 |\n| 14 | Specifying Constraints overview | 2.9 |\n| 15 | PRIMARY KEY, UNIQUE | 2.9.1 |\n| 16 | FOREIGN KEY, referential actions | 2.9.2 |\n| 17 | NOT NULL, DEFAULT, CHECK | 2.9.3 |\n| 18 | COMPANY schema diagram (lặp) | 2.3 |\n| 19 | CREATE TABLE Employee/Department/Dept_locations | 2.10 |\n| 20 | CREATE TABLE Project/Works_on/Dependent | 2.10 |\n| 21 | Giving names to constraints | 2.11 |\n| 22 | Named constraints code | 2.11 |\n| 23 | Tuple constraints using CHECK, assertion mention | 2.12 |\n| 24 | DROP schema/table, CASCADE/RESTRICT | 2.13 |\n| 25 | DROP table example | 2.13 |\n| 26 | ALTER command | 2.14 |\n| 28 | SELECT command, multiset/bag | 3.2 |\n| 29 | Basic SELECT-FROM-WHERE | 3.3 |\n| 30 | Complete SELECT form | 3.3 |\n| 31 | Meaning of clauses | 3.3 |\n| 32, 35, 37, 53 | COMPANY schema diagram (lặp) | 2.3 |\n| 33 | Q0 | 3.4 |\n| 34 | Q1 | 3.4 |\n| 36 | Q2 | 3.4 |\n| 38 | Ambiguous Attribute Names | 3.5 |\n| 39 | Aliases Q3a | 3.6 |\n| 40 | Aliases Q3b + renaming | 3.6 |\n| 41 | Missing WHERE Q4 | 3.7 |\n| 42 | Cartesian product Q5 | 3.7 |\n| 43 | ASTERISK Q6/Q7 | 3.8 |\n| 44 | DISTINCT Q8a/Q8b | 3.9 |\n| 45 | Set operations | 3.10 |\n| 46 | UNION Q9 | 3.10 |\n| 47 | LIKE Q10/Q11 | 3.11 |\n| 48 | Arithmetic Q12 | 3.12 |\n| 49 | NULL & 3-valued logic | 3.13 |\n| 50 | Complete SELECT form (lặp) | 3.3 |\n| 51 | Nested query Q13 | 3.14 |\n| 52 | Correlated query Q14 | 3.15 |\n| 54 | Q14a single block | 3.16 |\n| 55 | Nested exercise Q15 | 3.17 |\n| 56 | ANY/ALL Q16 | 3.18 |\n| 57 | EXISTS/NOT EXISTS/UNIQUE | 3.19 |\n| 58 | Q14b EXISTS | 3.19 |\n| 59 | Q17 NOT EXISTS | 3.19 |\n| 60 | Enumerated Sets Q18 | 3.20 |\n| 61 | Joined Relations overview | 3.21 |\n| 62 | Joined table Q1a | 3.21 |\n| 63 | NATURAL JOIN | 3.22 |\n| 64 | Inner join, LEFT OUTER JOIN | 3.23 |\n| 65 | RIGHT/FULL OUTER JOIN | 3.23 |\n| 66 | Q3a vs Q3c | 3.24 |\n| 67 | Q1, Q1a, Q1b (NATURAL JOIN with rename) | 3.24 |\n| 68 | Q2a (multiple JOIN) | 3.24 |\n| 69 | Aggregate functions Q19 | 3.25 |\n| 70 | COUNT Q20/Q21 + NULL note | 3.25 |\n| 71 | GROUP BY rules | 3.26 |\n| 72 | Complete SELECT form (lặp) | 3.3 |\n| 73 | Q22 | 3.26 |\n| 74 | Result of Q22 (table) | 3.26 |\n| 75 | HAVING clause | 3.27 |\n| 76 | Q23 | 3.27 |\n| 77 | ORDER BY Q24 | 3.28 |\n| 78, 79 | Complete SELECT form + recap | 3.3 |\n| 81 | Insert syntax | 4.1 |\n| 82 | U1/U2 insert examples | 4.2 |\n| 83 | Constraints enforced + insert from query | 4.3 |\n| 84 | U3/U3A Depts_info | 4.4 |\n| 85 | Delete syntax | 4.5 |\n| 86 | U4A-U4D delete examples | 4.5 |\n| 87 | Update syntax | 4.6 |\n| 88 | U5 update Project | 4.6 |\n| 89 | U6 update Salary | 4.6 |\n| 90 | Assertions mechanism | 5.2 |\n| 91 | Salary assertion | 5.2 |\n| 92 | Triggers | 5.3 |\n| 93 | Views definition | 6.2 |\n| 94 | View syntax, DROP view | 6.3 |\n| 95 | Works_on_new view | 6.4 |\n| 96 | EMP_D5 WITH CHECK OPTION | 6.5 |\n| 97 | Updatable view conditions | 6.6 |\n| 99 | SQL for Data Control | 7.2 |\n| 100 | GRANT/REVOKE syntax | 7.2 |\n| 101 | GRANT OPTION | 7.3 |\n| 102 | A1 create base relations | 7.4 |\n| 103 | A1 grants insert/delete to A2 | 7.4 |\n| 104 | Figure 23.1 schema | 7.4 |\n| 105 | A1 grants select with grant option | 7.4 |\n| 106 | Revoke cascades | 7.4 |\n| 107 | Limited SELECT via view A3EMPLOYEE | 7.4 |\n| 108 | Column-specific UPDATE | 7.4 |\n| 109 | Summary | (kết thúc) |\n| 110 | Q/A slide | (kết thúc) |\n| 111 | Exercise 1 | Câu Hỏi Ôn Tập |\n| 112 | Exercise 2 (7 sub-questions) | Câu Hỏi Ôn Tập |\n| 113 | Exercise 3 (4 views) | Câu Hỏi Ôn Tập |\n| 114 | Exercise 4 (view update) | Câu Hỏi Ôn Tập |\n\n---\n\n","file":"materials/DB-Chapter6.md","section":18},{"id":"c6-19","group":"c6","kind":"source","title":"CHECKLIST TỔNG HỢP — Tự Audit","markdown":"## CHECKLIST TỔNG HỢP — Tự Audit\n\n### ✅ Checklist nội dung\n| Hạng mục | PDF gốc | Output | Khớp |\n|---|---:|---:|---|\n| Tổng số slide | 114 | 114 (gộp 6 slide Contents) | ✅ |\n| ER/Schema diagram (COMPANY + Figure 23.1) | 6 lặp + 1 rút gọn | 1 Mermaid COMPANY + 1 ASCII fallback + 1 Mermaid Figure 23.1 | ✅ |\n| Bảng (instance/comparison) | 4 (3 truth tables AND/OR/NOT + Q22 result) | 4 | ✅ |\n| Ví dụ + bài tập | Q0–Q24 (24) + U1–U6 (6) + Exercise 1–4 | 24+6+4 với lời giải đầy đủ | ✅ |\n| Đoạn SQL code | 50+ | 50+ | ✅ |\n| Công thức RA tương đương | Q0, Q1 | đã liên hệ | ✅ |\n| Định nghĩa chính thức | ~40+ | 64 entries glossary | ✅ |\n| Câu hỏi ôn tập từ slide | Exercise 1–4 | Đã giải đầy đủ trong \"Câu Hỏi Ôn Tập\" | ✅ |\n\n### ✅ Checklist sư phạm\n| Hạng mục | Đếm | Yêu cầu |\n|---|---:|---|\n| \"Tại sao\" (SP-1) | 7+ | = số section lớn ✅ |\n| Ví dụ COMPANY (SP-3) | 24 query + 6 update + 5 tự luyện = 35 | ≥ 1/concept ✅ |\n| Analogy (SP-4) | 12+ | ≥ 1/concept khó ✅ |\n| \"Tóm lại section\" (SP-5) | 7 | = số section ✅ |\n| Câu hỏi tự kiểm tra | 24+ | ≥ 6 cả chương ✅ |\n| Scaffolding chuyển tiếp | ✅ | bắt buộc ✅ |\n| Thuật ngữ EN → VN lần đầu | ✅ | bắt buộc ✅ |\n\n### ✅ Checklist riêng cho TỰ HỌC (TH1–TH5)\n| Hạng mục | Đạt? |\n|---|---|\n| Có 0.1 Prerequisite | ✅ |\n| Có 0.2 Learning Outcomes (13 mục) | ✅ |\n| Có 0.3 Lộ trình đọc (4 buổi) | ✅ |\n| Có \"Bảng tra nhanh\" cuối chương | ✅ |\n| Có \"Sai lầm thường gặp\" (10 lỗi) | ✅ |\n| Có ≥ 3 bài tập tự luyện có lời giải | ✅ (5 bài) |\n| Có liên kết Lab/BTL | ✅ |\n| Mọi concept trừu tượng có analogy | ✅ |\n| **SV mất gốc đọc xong sẽ hiểu được toàn bộ?** | ✅ |\n\n---\n\n# Kết thúc Chương 6 — Structured Query Language\n\n> Khi nắm vững chương này, bạn có thể tự tin viết SQL cho 95% bài tập của môn (Lab, BTL, đề thi). Bước tiếp theo: **Chương 7 — Functional Dependencies & Normalization** để học cách thiết kế schema **tốt** ngay từ đầu (tránh dư thừa và update anomalies).\n>\n> Nếu chỉ nhớ một điều: *SQL không chỉ là SELECT. SQL gồm định nghĩa cấu trúc (DDL), thao tác dữ liệu (DML), và điều khiển quyền (DCL). Trong đề thi, phần SELECT + JOIN + GROUP BY + nested + view update + constraints là trọng tâm lớn nhất.*\n","file":"materials/DB-Chapter6.md","section":19},{"id":"guide-6","group":"c6","kind":"guide","title":"SQL từ cơ bản đến nâng cao","markdown":"# 06 · SQL: hiểu dữ liệu trước và sau mỗi bước\n\n> Đọc cùng **DB-Chapter6.md**. Lab chuẩn dùng SQLite qua Python; ví dụ SQL Server/PostgreSQL trong bản gốc phải đọc theo đúng dialect.\n\n![Pipeline logic truy vấn và lỗi LEFT JOIN](../docs/assets/sql-pipeline.svg)\n\n## Chạy một truy vấn thật\n\nTừ thư mục gốc project:\n\n```bash\npython tools/lab.py --exercise Q01\npython tools/lab.py --query \"SELECT Fname, Salary FROM EMPLOYEE ORDER BY Fname\"\npython tools/lab.py --file sql/solutions.sql\n```\n\nMỗi lần chạy tạo một database trong RAM từ schema và seed. Bạn có thể sửa dữ liệu trong phiên Python riêng mà không làm hỏng fixture trên đĩa. Xem `labs/02-sql.md` để mở REPL giữ cùng một connection.\n\n## FROM/ON → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY\n\nĐây là thứ tự **logic để lý giải** kết quả, không phải trình tự vật lý bắt buộc của optimizer. `WHERE` lọc hàng trước grouping; `HAVING` lọc nhóm sau grouping.\n\n```sql\nSELECT d.Dname, COUNT(e.Ssn) AS Employees\nFROM DEPARTMENT AS d LEFT JOIN EMPLOYEE AS e ON e.Dno=d.Dnumber\nGROUP BY d.Dnumber, d.Dname\nHAVING COUNT(e.Ssn)>=4\nORDER BY d.Dname;\n```\n\nKết quả: Administration 4, Research 4. `COUNT(e.Ssn)` đếm nhân viên thật; `COUNT(*)` ở LEFT JOIN đếm cả hàng giữ lại cho phòng không có nhân viên.\n\n## LEFT JOIN: điều kiện đặt ở ON và WHERE không tương đương\n\n```sql\n-- Giữ cả phòng không có nhân viên lương > 40000.\nSELECT d.Dname, e.Fname\nFROM DEPARTMENT d LEFT JOIN EMPLOYEE e\n ON e.Dno=d.Dnumber AND e.Salary>40000\nORDER BY d.Dname, e.Fname;\n```\n\nAdministration ghép Jennifer; Headquarters ghép James; Research và Innovation vẫn còn với Fname NULL. Nếu chuyển `e.Salary>40000` xuống WHERE, hai hàng NULL không vượt qua điều kiện và bị loại. Đây là lý do “outer join rồi WHERE” thường mất hàng người viết muốn giữ.\n\n## NULL không phải 0, chuỗi rỗng hay một giá trị thường\n\nMai có Salary NULL: dữ liệu chưa biết. `Salary = NULL` cho UNKNOWN, không phải TRUE. Phải dùng `IS NULL`. WHERE chỉ giữ TRUE; cả FALSE và UNKNOWN đều bị loại. `AVG(Salary)` bỏ qua NULL; `COALESCE(Salary,0)` thay NULL bằng 0 và **thay đổi ý nghĩa phép tính**.\n\n```sql\nSELECT COUNT(*) AS AllEmployees, COUNT(Salary) AS KnownSalaries,\n       ROUND(AVG(Salary),2) AS AverageKnownSalary\nFROM EMPLOYEE;\n```\n\nKết quả là 9, 8, 35125. Không nên điền lương chưa biết bằng 0 chỉ để biểu thức chạy được.\n\n## NOT IN và NULL: thử phản ví dụ tối thiểu\n\n```sql\nSELECT Fname FROM EMPLOYEE WHERE Ssn NOT IN (SELECT Super_ssn FROM EMPLOYEE);\n```\n\nSuper_ssn của James là NULL. Với những người không trùng các supervisor đã biết, điều kiện NOT IN vẫn UNKNOWN do NULL trong tập; không có hàng nào được giữ. Dùng correlated NOT EXISTS để tìm người không quản lý ai:\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e\nWHERE NOT EXISTS(SELECT 1 FROM EMPLOYEE s WHERE s.Super_ssn=e.Ssn)\nORDER BY e.Fname;\n```\n\nKết quả Ahmad, Alicia, John, Joyce, Mai, Ramesh.\n\n## Aggregate, subquery, view và transaction\n\nSubquery tương quan tham chiếu hàng ngoài; viết được nó không có nghĩa engine phải thực thi lại y nguyên cho từng hàng. View thường là query lưu tên, không mặc định là bản sao vật lý. `CREATE VIEW ... WITH CHECK OPTION` không được SQLite hỗ trợ trực tiếp như PostgreSQL; không dán nguyên ví dụ đó vào lab rồi coi lỗi là lỗi của cú pháp SQL nói chung.\n\nTransaction gom các thay đổi thành một đơn vị. Trong Python, `with connection:` commit khi thành công và rollback khi phát sinh exception. Truy vấn dữ liệu bằng **parameter binding**:\n\n```python\nrows = connection.execute(\n    \"SELECT Ssn, Fname FROM EMPLOYEE WHERE Dno = ?\", (5,)\n).fetchall()\n```\n\nDấu `?` dành cho **giá trị**, không cho tên bảng/cột. Nếu cho người dùng chọn cột sắp xếp, cần whitelist tên cột. Xem `labs/05-security.md` để thử chuỗi có dấu nháy mà không ghép SQL.\n\n## Bài tập và đầu ra cần kiểm tra\n\n1. Đếm mọi phòng, kể cả phòng rỗng: Q07.\n2. Tìm lương cao hơn trung bình phòng: Q16.\n3. Tìm nhân viên làm cả dự án 1 và 2: Q18.\n4. Dùng UPDATE trong transaction và cố tình lỗi để quan sát rollback: lab giao dịch.\n\n<details><summary>Gợi ý lập luận</summary>\n\nQ07 phải đi từ DEPARTMENT và LEFT JOIN; COUNT cột PK bên employee. Q16 phải so Salary với subquery có `x.Dno=e.Dno`; Salary NULL tự bị loại. Q18 có thể dùng hai EXISTS hoặc GROUP BY và COUNT DISTINCT trên hai mã yêu cầu. Không dùng điều kiện `Pno=1 AND Pno=2` trên cùng một hàng.\n\n</details>\n","file":"lessons/06-sql.md"},{"id":"c7-00","group":"c7","kind":"source","title":"Chương 7: Phụ Thuộc Hàm và Chuẩn Hóa Quan Hệ — Functional Dependencies & Normalization for Relational DBs","markdown":"# Chương 7: Phụ Thuộc Hàm và Chuẩn Hóa Quan Hệ — Functional Dependencies & Normalization for Relational DBs\n\n> Nguồn: CO2013 Database Systems, HCMUT — Giảng viên: TS. Trần Minh Quang\n> Giáo trình: Elmasri & Navathe, 7th Edition (Chương tương ứng: Chương 15–16)\n> File PDF gốc: `Lectures/07_FD_v2.pdf` — **95 trang**\n> Đã gộp các slide \"Contents\" lặp lại (slide 2, 3, 22, 28, 32, 40, 52, 65, 69, 81, 95) thành **một mục lục** ở phần 0.\n\n---\n\n","file":"materials/DB-Chapter7.md","section":0},{"id":"c7-01","group":"c7","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nTrước khi học chương này, bạn cần \"nhớ lại\" nhanh các khái niệm nền (đã học ở chương 4):\n\n| Kiến thức nền | Nhắc lại siêu ngắn | Liên hệ với chương 7 |\n|---|---|---|\n| **Relation, attribute, tuple** | Bảng có cột (attribute) và dòng (tuple). `t[X]` = giá trị tuple t trên tập attribute X. | FD được phát biểu dùng `t[X]`. |\n| **Relation schema** | `R(A1, A2, ..., An)` — tên bảng + danh sách cột. | FD ràng buộc trên schema, áp dụng cho mọi instance. |\n| **Primary key, Candidate key, Superkey** | Superkey = tập attribute không trùng giữa 2 tuple. Candidate key = superkey *tối thiểu*. Primary key = một candidate key được chọn. | Normal form được định nghĩa qua key. |\n| **Foreign key** | Cột ở bảng A trỏ về PK bảng B. | Thiết kế tốt: JOIN qua PK/FK để tránh spurious tuples. |\n| **JOIN (chương 5, 6)** | Ghép 2 relation theo cột chung. | Phân rã sai → JOIN sinh dữ liệu giả. |\n| **COMPANY schema** | EMPLOYEE, DEPARTMENT, DEPT_LOCATIONS, PROJECT, WORKS_ON, DEPENDENT. | Mọi ví dụ trong chương đều bám COMPANY. |\n| **Set theory** | `⊆` tập con, `∪` hợp, `∩` giao, `−` hiệu. | Closure X⁺ và phân loại U_l/U_r/U_b cần. |\n\n> 💡 **Hiểu đơn giản:** Schema vs Instance giống **bản thiết kế nhà** vs **các căn nhà cụ thể đang ở**. Chương 7 chủ yếu kiểm tra bản thiết kế: nếu thiết kế sai, nhà vẫn xây được nhưng ở lâu sẽ bất tiện, sửa chữa tốn công, dễ hỏng.\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\n1. Giải thích vì sao một schema có thể \"xấu\" dù vẫn lưu được dữ liệu (4 vấn đề: semantics, redundancy, NULL, spurious tuples).\n2. Nhận diện 3 loại update anomaly: modification, insertion, deletion.\n3. Viết được Functional Dependency (FD) dạng `X → Y` và đọc hiểu ý nghĩa formal.\n4. Phân biệt **direct, indirect (transitive), partial** dependency.\n5. Áp dụng **Armstrong's inference rules** (IR1, IR2, IR3) và các luật phái sinh.\n6. Tính **closure** X⁺ của tập attribute (Algorithm 16.1).\n7. Kiểm tra **equivalence** của 2 tập FD (F⁺ = G⁺).\n8. Tìm **minimal cover** (Algorithm 16.2).\n9. Tìm **candidate keys** bằng Algorithm 1 (Elmasri) và Algorithm 2 (Saiedian).\n10. Kiểm tra một quan hệ ở **1NF, 2NF, 3NF, BCNF** và **decompose** lên chuẩn cao hơn.\n11. Hiểu hai tính chất quan trọng của decomposition: **non-additive (lossless) join** và **dependency preservation**.\n12. Áp dụng **NJB test** cho phân rã binary.\n\n### 0.3. Lộ trình đọc đề xuất\n\n| Mức | Section | Mục tiêu | Thời gian |\n|---|---|---|---|\n| **CORE 1** | §1 — Vì sao cần Normalization | Hiểu 4 vấn đề thiết kế tệ | 45–60' |\n| **CORE 2** | §2–§4 — FD, Closure, Armstrong, Minimal Cover | Tính X⁺, tìm key, suy FD | 90–120' |\n| **CORE 3** | §5 — Key finding | Tìm hết candidate keys | 30' |\n| **CORE 4** | §6–§7 — 1NF/2NF/3NF/General NF | Phân rã chuẩn hóa | 90–120' |\n| **CORE 5** | §8 — BCNF + NJB | Lên chuẩn cao nhất | 45' |\n| **EXAM** | §9 + Bài tập tự luyện | Luyện dạng thi | 90–120' |\n\n> Tổng thời gian học chủ động: **~6 giờ**. Đây là chương \"đinh\" của môn — kỳ thi cuối kỳ HCMUT **hầu như luôn có 1 bài tự luận lớn** về normalization từ 2NF → BCNF.\n\n---\n\n","file":"materials/DB-Chapter7.md","section":1},{"id":"c7-02","group":"c7","kind":"source","title":"1. Vì sao cần Normalization? — Bốn vấn đề của thiết kế \"tệ\"","markdown":"## 1. Vì sao cần Normalization? — Bốn vấn đề của thiết kế \"tệ\"\n\n### 1.1. Tại sao có concept này? (Motivation)\n\nỞ chương 4, bạn đã biết cách ánh xạ ER → quan hệ. Nhưng cùng một mini-world có thể vẽ ER khác nhau → schema khác nhau. **Schema nào \"tốt\", schema nào \"tệ\"? Đo bằng cách nào?**\n\nNếu không có normalization, hai designer có thể tạo ra 2 schema cùng đúng nghiệp vụ nhưng:\n- Lặp dữ liệu khủng khiếp (1 phòng có 100 nhân viên → tên phòng viết 100 lần).\n- Sửa dữ liệu hay bị sai (đổi tên trưởng phòng nhưng quên 1/100 hàng → DB **inconsistent**).\n- Không thêm được \"phòng chưa có nhân viên\".\n- Khi JOIN lại sinh dữ liệu **không có thật** (spurious).\n\n→ **Normalization** là **formal framework** dùng **Functional Dependencies (phụ thuộc hàm)** và **Keys** để *đo độ tốt* của schema và *biến schema tệ thành tốt* có hệ thống.\n\n> 💡 **Hiểu đơn giản:** Normalization giống như **sắp xếp tủ quần áo**: nhét tất cả áo, quần, vớ vào cùng một ngăn → tủ \"tệ\" (lục tung mỗi lần lấy đồ). Chia thành ngăn áo, ngăn quần, ngăn vớ → tủ \"tốt\" (lấy nhanh, không ảnh hưởng đồ khác khi thay đổi). Normalization gom các attribute *thực sự thuộc về nhau* thành cùng một quan hệ.\n\n### 1.2. Bối cảnh: Overview of Database Design Process (Slide 4)\n\nNormalization nằm ở **pha Logical Design** trong quy trình thiết kế CSDL — sau Conceptual Design (ER) và trước Physical Design (file, index).\n\n```mermaid\nflowchart TB\n    MW([Miniworld]) --> RCA[REQUIREMENTS - COLLECTION & ANALYSIS]\n    RCA --> DR[Data requirements]\n    RCA --> FR[Functional requirements]\n    FR --> FA[FUNCTIONAL ANALYSIS]\n    FA --> HT[High-level transaction specification]\n    HT --> APD[APPLICATION PROGRAM DESIGN]\n    APD --> TI[TRANSACTION IMPLEMENTATION]\n    TI --> APP[Application program]\n    DR --> CD[CONCEPTUAL DESIGN]\n    CD --> CS[Conceptual schema / ERD]\n    CS --> LD[\"LOGICAL DESIGN<br/>(DATA MODEL MAPPING)<br/>← Chương 7 ở đây\"]\n    LD --> DBS[Database schema]\n    DBS --> PD[PHYSICAL DESIGN]\n    PD --> IS[Internal schema]\n```\n\n> 📊 **Đọc diagram này thế nào:** Phần Database Design (phải) chia 4 lớp. Chương 7 nằm ở **Logical Design** — tinh chỉnh schema sau khi đã ánh xạ từ ER. Vẫn thuộc vùng **DBMS-independent** (lý thuyết quan hệ tổng quát).\n\n### 1.3. Bốn tiêu chí \"informal\" đánh giá schema (Slides 5–7)\n\nMỗi relation schema gồm các attribute. Cần **đo** *vì sao* cách gom attribute này tốt hơn cách kia. Bốn tiêu chí:\n\n1. **Semantics of attributes** — mọi attribute phải \"thuộc cùng một thực thể\" về ngữ nghĩa.\n2. **Reducing redundant values** — giảm dư thừa → tiết kiệm storage + tránh update anomalies.\n3. **Reducing NULL values** — NULL có nhiều diễn giải mơ hồ.\n4. **Disallowing spurious tuples** — schema phải sao cho JOIN qua PK/FK không sinh tuple ảo.\n\n### 1.4. Tiêu chí 1: Semantics — \"Bảng nói về cái gì?\" (Slide 7)\n\n**Better Relations** — mỗi tuple chỉ kể về MỘT thực thể:\n\n*EMPLOYEE*:\n| Fname | Lname | Ssn | Bdate | Address | Dnumber |\n|---|---|---|---|---|---|\n| Smith | John B. | 123456789 | 1965-01-09 | 731 Fondren, Houston, TX | 5 |\n| Wong | Franklin T. | 333445555 | 1955-12-08 | 638 Voss, Houston, TX | 5 |\n| Zelaya | Alicia J. | 999887777 | 1968-07-19 | 3321 Castle, Spring, TX | 4 |\n| Wallace | Jennifer S. | 987654321 | 1941-06-20 | 291 Berry, Bellaire, TX | 4 |\n| Narayan | Ramesh K. | 666884444 | 1962-09-15 | 975 Fire Oak, Humble, TX | 5 |\n| English | Joyce A. | 453453453 | 1972-07-31 | 5631 Rice, Houston, TX | 5 |\n| Jabbar | Ahmad V. | 987987987 | 1969-03-29 | 980 Dallas, Houston, TX | 4 |\n| Borg | James E. | 888665555 | 1937-11-10 | 450 Stone, Houston, TX | 1 |\n\n*DEPARTMENT*:\n| Dname | Dnumber | Dmgr_ssn |\n|---|---|---|\n| Research | 5 | 333445555 |\n| Administration | 4 | 987654321 |\n| Headquarters | 1 | 888665555 |\n\n**Worse Relation** — gom 2 thực thể vào 1 bảng:\n\n*EMP_DEPT*:\n| Ename | Ssn | Bdate | Address | Dnumber | Dname | Dmgr_ssn |\n|---|---|---|---|---|---|---|\n| Smith, John B. | 123456789 | 1965-01-09 | 731 Fondren, Houston, TX | 5 | Research | 333445555 |\n| Wong, Franklin T. | 333445555 | 1955-12-08 | 638 Voss, Houston, TX | 5 | Research | 333445555 |\n| Zelaya, Alicia J. | 999887777 | 1968-07-19 | 3321 Castle, Spring, TX | 4 | Administration | 987654321 |\n| Wallace, Jennifer S. | 987654321 | 1941-06-20 | 291 Berry, Bellaire, TX | 4 | Administration | 987654321 |\n| Narayan, Ramesh K. | 666884444 | 1962-09-15 | 975 FireOak, Humble, TX | 5 | Research | 333445555 |\n| English, Joyce A. | 453453453 | 1972-07-31 | 5631 Rice, Houston, TX | 5 | Research | 333445555 |\n| Jabbar, Ahmad V. | 987987987 | 1969-03-29 | 980 Dallas, Houston, TX | 4 | Administration | 987654321 |\n| Borg, James E. | 888665555 | 1937-11-10 | 450 Stone, Houston, TX | 1 | Headquarters | 888665555 |\n\n> 📊 **Đọc diagram này thế nào:** EMP_DEPT mỗi tuple **gom thông tin của 2 thực thể** (1 nhân viên + 1 phòng) → ngữ nghĩa lẫn lộn. (EMPLOYEE + DEPARTMENT) tách rõ — mỗi tuple chỉ \"kể\" về một thực thể.\n\n### 1.5. Tiêu chí 2: Redundancy + Update Anomalies (Slides 8–12)\n\n**Redundancy:** Trong EMP_DEPT, phòng \"Research\" có 4 nhân viên → cụm `(5, Research, 333445555)` lặp 4 lần. Phòng \"Administration\" 3 nhân viên → cụm lặp 3 lần.\n\n**Hậu quả:** Tốn storage, nhưng quan trọng hơn — sinh **update anomalies**:\n\n#### Modification anomaly (Slide 9)\nĐổi trưởng phòng Research từ SSN `333445555` → SSN `999887777`: phải update Dmgr_ssn ở **4 tuple** (Smith, Wong, Narayan, English). Quên 1 tuple → DB **inconsistent**.\n\n#### Insertion anomaly (Slide 10)\nTạo phòng \"R&D Mới\" *trước khi* có nhân viên: KHÔNG thể thêm dòng EMP_DEPT vì SSN (PK) sẽ rỗng. Với schema tách (EMPLOYEE + DEPARTMENT), chỉ cần INSERT 1 dòng DEPARTMENT.\n\n#### Deletion anomaly (Slide 12)\nBorg là nhân viên duy nhất của phòng \"Headquarters\" (Dnumber=1). Xóa dòng Borg → **mất luôn thông tin** dept 1 tồn tại, tên dept, manager dept. Trong thực tế phòng vẫn còn — Borg chỉ nghỉ!\n\n> 💡 **Hiểu đơn giản:** Update anomalies giống như **danh sách lớp dạng \"tên SV - tên GVCN\"** chứ không tách 2 sổ riêng: đổi GVCN phải sửa 60 dòng; thêm GVCN mới chưa có SV thì không ghi được; lớp giải tán hết SV thì mất luôn tên GVCN. Tách 2 sổ \"danh sách SV\" và \"danh sách GVCN\" thì 3 vấn đề biến mất.\n\n### 1.6. COMPANY schema chuẩn (sẽ dùng xuyên suốt) (Slide 11)\n\nMột database state có thể có của COMPANY:\n\n**EMPLOYEE:**\n| Fname | Minit | Lname | Ssn | Bdate | Address | Sex | Salary | Super_ssn | Dno |\n|---|---|---|---|---|---|---|---|---|---|\n| John | B | Smith | 123456789 | 1965-01-09 | 731 Fondren, Houston, TX | M | 30000 | 333445555 | 5 |\n| Franklin | T | Wong | 333445555 | 1955-12-08 | 638 Voss, Houston, TX | M | 40000 | 888665555 | 5 |\n| Alicia | J | Zelaya | 999887777 | 1968-01-19 | 3321 Castle, Spring, TX | F | 25000 | 987654321 | 4 |\n| Jennifer | S | Wallace | 987654321 | 1941-06-20 | 291 Berry, Bellaire, TX | F | 43000 | 888665555 | 4 |\n| Ramesh | K | Narayan | 666884444 | 1962-09-15 | 975 Fire Oak, Humble, TX | M | 38000 | 333445555 | 5 |\n| Joyce | A | English | 453453453 | 1972-07-31 | 5631 Rice, Houston, TX | F | 25000 | 333445555 | 5 |\n| Ahmad | V | Jabbar | 987987987 | 1969-03-29 | 980 Dallas, Houston, TX | M | 25000 | 987654321 | 4 |\n| James | E | Borg | 888665555 | 1937-11-10 | 450 Stone, Houston, TX | M | 55000 | NULL | 1 |\n\n**DEPARTMENT:**\n| Dname | Dnumber | Mgr_ssn | Mgr_start_date |\n|---|---|---|---|\n| Research | 5 | 333445555 | 1988-05-22 |\n| Administration | 4 | 987654321 | 1995-01-01 |\n| Headquarters | 1 | 888665555 | 1981-06-19 |\n\n### 1.7. Tiêu chí 3: NULL values (Slide 13)\n\nNULL có **nhiều diễn giải**:\n- Thuộc tính **không áp dụng** cho tuple này.\n- Giá trị **chưa biết** (unknown).\n- Giá trị **biết nhưng chưa được ghi** (known but absent).\n\n**Vấn đề:** Lãng phí storage; khó hiểu ngữ nghĩa và JOIN ở mức logical; khó tính aggregate (COUNT/SUM có đếm NULL không?).\n\n**Nguyên tắc thiết kế:** Tránh đặt attribute thường xuyên NULL vào base relation. Nếu không tránh được, đảm bảo NULL chỉ áp dụng cho trường hợp **ngoại lệ**, không phải đa số.\n\n> 💡 **Ví dụ COMPANY:** `Super_ssn = NULL` cho James E. Borg vì ông là president (không có supervisor) — hợp lý vì là ngoại lệ. Nhưng nếu bảng có 80% dòng NULL ở 1 cột, đó là dấu hiệu cột không nên ở bảng đó.\n\n### 1.8. Tiêu chí 4: Spurious Tuples — Tuple ảo do JOIN sai (Slides 14–17)\n\n**Spurious tuples** = các tuple **KHÔNG hợp lệ, KHÔNG tồn tại** trong mini-world. Sinh ra khi JOIN các relation từ thiết kế tệ.\n\n**Nguyên tắc:** Schema phải sao cho JOIN với equality trên **PK hoặc FK** đảm bảo không sinh tuple ảo.\n\n#### 1.8.1. Ví dụ phân rã SAI (Slide 14)\n\nCho schema gốc:\n```\nEMP_PROJ (SSN, PNumber, Hours, EName, PName, PLocation)\n```\n\nPhân rã SAI thành:\n```\nEMP_LOCS  (EName, PLocation)\nEMP_PROJ1 (SSN, PNumber, Hours, PName, PLocation)\n```\n\n**Vấn đề:** Khi `EMP_LOCS ⋈ EMP_PROJ1` trên `PLocation`, gặp lỗi vì PLocation **không phải PK, không phải FK** trong cả 2 → sinh spurious tuples.\n\n#### 1.8.2. EMP_PROJ gốc (Slide 15) — có redundancy\n\n| Ssn | Pnumber | Hours | Ename | Pname | Plocation |\n|---|---|---|---|---|---|\n| 123456789 | 1 | 32.5 | Smith, John B. | ProductX | Bellaire |\n| 123456789 | 2 | 7.5 | Smith, John B. | ProductY | Sugarland |\n| 666884444 | 3 | 40.0 | Narayan, Ramesh K. | ProductZ | Houston |\n| 453453453 | 1 | 20.0 | English, Joyce A. | ProductX | Bellaire |\n| 453453453 | 2 | 20.0 | English, Joyce A. | ProductY | Sugarland |\n| 333445555 | 2 | 10.0 | Wong, Franklin T. | ProductY | Sugarland |\n| 333445555 | 3 | 10.0 | Wong, Franklin T. | ProductZ | Houston |\n| 333445555 | 10 | 10.0 | Wong, Franklin T. | Computerization | Stafford |\n| 333445555 | 20 | 10.0 | Wong, Franklin T. | Reorganization | Houston |\n| 999887777 | 30 | 30.0 | Zelaya, Alicia J. | Newbenefits | Stafford |\n| 999887777 | 10 | 10.0 | Zelaya, Alicia J. | Computerization | Stafford |\n| 987987987 | 10 | 35.0 | Jabbar, Ahmad V. | Computerization | Stafford |\n| 987987987 | 30 | 5.0 | Jabbar, Ahmad V. | Newbenefits | Stafford |\n| 987654321 | 30 | 20.0 | Wallace, Jennifer S. | Newbenefits | Stafford |\n| 987654321 | 20 | 15.0 | Wallace, Jennifer S. | Reorganization | Houston |\n| 888665555 | 20 | NULL | Borg, James E. | Reorganization | Houston |\n\n#### 1.8.3. Kết quả JOIN sai sinh spurious (Slide 17)\n\nKhi `EMP_LOCS ⋈ EMP_PROJ1` trên PLocation:\n\n| Ssn | Pnumber | Hours | Pname | Plocation | Ename | Ghi chú |\n|---|---|---|---|---|---|---|\n| 123456789 | 1 | 32.5 | ProductX | Bellaire | Smith, John B. | hợp lệ |\n| 123456789 | 1 | 32.5 | ProductX | Bellaire | **English, Joyce A.** | ⚠️ SPURIOUS! |\n| 123456789 | 2 | 7.5 | ProductY | Sugarland | Smith, John B. | hợp lệ |\n| 123456789 | 2 | 7.5 | ProductY | Sugarland | **English, Joyce A.** | ⚠️ SPURIOUS! |\n| 666884444 | 3 | 40.0 | ProductZ | Houston | Narayan, Ramesh K. | hợp lệ |\n| 666884444 | 3 | 40.0 | ProductZ | Houston | **Wong, Franklin T.** | ⚠️ SPURIOUS! |\n\n**SQL minh họa lỗi:**\n```sql\nSELECT EP1.Ssn, EP1.Pnumber, EP1.Hours, EP1.Pname, EP1.Plocation, EL.Ename\nFROM EMP_PROJ1 AS EP1\nJOIN EMP_LOCS AS EL\n  ON EP1.Plocation = EL.Plocation;\n```\n\n- `ON EP1.Plocation = EL.Plocation`: điều kiện JOIN sai/không đủ mạnh.\n- PLocation không phải key — nhiều employee và project cùng location.\n- → JOIN nhân chéo tạo nhiều tổ hợp không tồn tại.\n\n> 💡 **Hiểu đơn giản:** Spurious tuples giống như **ghép người và phòng thi chỉ dựa trên \"cùng tòa nhà\"**. Tòa H6 có 10 lớp thi và 500 SV — ghép như vậy sinh rất nhiều kết quả sai: SV bị gán vào lớp thi không đăng ký.\n\n### 1.9. Tổng kết \"Goodness\" + Giải pháp (Slides 18–20)\n\n**Goodness measures:**\n- Redundant information in tuples\n- Update anomalies: modification, deletion, insertion\n- Reducing NULL values\n- Disallowing spurious tuples\n\n**☞ Giải pháp: Normalization** (Slide 19)\n- Formal framework phân tích schema dựa trên **keys** + **FDs**.\n- Một loạt **normal form tests**: 1NF, 2NF, 3NF, BCNF, 4NF, 5NF.\n- Đảm bảo attribute được gom với PK. Attribute không phụ thuộc trực tiếp PK → tách ra quan hệ mới.\n\n**Hai tính chất quan trọng của decomposition (Slide 20):**\n1. **Non-additive (lossless) join** — JOIN không sinh spurious — **BẮT BUỘC, không hi sinh**.\n2. **Preservation of functional dependencies** — FD ban đầu vẫn kiểm tra được — **ít nghiêm ngặt hơn, có thể hi sinh**.\n\n> 📝 **Tóm lại section 1:**\n> - Schema \"tệ\" gây 4 vấn đề: lẫn lộn ngữ nghĩa, redundancy (kéo theo 3 anomalies), nhiều NULL, spurious tuples.\n> - Normalization = formal framework dùng FD + keys → biến tệ thành tốt qua các normal form.\n> - Decomposition phải đảm bảo **non-additive join** (bắt buộc) và **dependency preservation** (nên có).\n> **Một câu ghi nhớ:** *\"Schema tệ = lặp + lỗi cập nhật + NULL + tuple ảo. Normalization = phân rã có lý thuyết để chữa cả 4.\"*\n\n> ❓ **Tự kiểm tra section 1:**\n> 1. Liệt kê 3 loại update anomalies + ví dụ COMPANY.\n> 2. Vì sao non-additive join *quan trọng hơn* dependency preservation?\n> 3. JOIN 2 relation trên cột không phải PK/FK gây hiện tượng gì?\n\n---\n\n","file":"materials/DB-Chapter7.md","section":2},{"id":"c7-03","group":"c7","kind":"source","title":"2. Functional Dependencies (FDs) — Định nghĩa và các loại","markdown":"## 2. Functional Dependencies (FDs) — Định nghĩa và các loại\n\n> Section 1 cho thấy schema tệ gây vấn đề. Bây giờ ta cần *công cụ chính xác* để mô tả \"attribute nào quyết định attribute nào\" — đó là **Functional Dependency**.\n\n### 2.1. Tại sao có concept này? (Motivation)\n\nKhi nhìn EMP_DEPT, ta cảm nhận \"Dnumber quyết định Dname\". Nhưng cảm nhận không đủ — cần *ký hiệu hóa* để máy tính (hay người thiết kế) có thể *suy luận tự động*.\n\n**FD** là ký hiệu đó: `X → Y` đọc là \"X xác định hàm Y\" (X functionally determines Y).\n\n### 2.2. Định nghĩa formal (Slides 23–24)\n\n- FD được dùng để xác định **formal measures** của \"goodness\" của design.\n- FD và keys định nghĩa **normal forms**.\n- FD là **constraint** xuất phát từ **ý nghĩa và quan hệ giữa các attribute**.\n- **Quan trọng:** FD **không thể** suy ra tự động từ một *thể hiện* r — phải được **người hiểu ngữ nghĩa** định nghĩa **tường minh**.\n\n**Định nghĩa:** Tập attribute X **functionally determines** tập attribute Y nếu giá trị của X xác định một giá trị duy nhất cho Y.\n\n$$\\boxed{X \\rightarrow Y}$$\n\n`X → Y` đúng nếu khi 2 tuple bất kỳ có cùng giá trị X, chúng PHẢI có cùng giá trị Y.\n\n**Công thức:** Với mọi 2 tuple t₁, t₂ trong mọi instance r(R):\n$$\\text{If } t_1[X] = t_2[X], \\text{ then } t_1[Y] = t_2[Y]$$\n\n| Ký hiệu | Ý nghĩa |\n|---|---|\n| `R` | Relation schema |\n| `r(R)` | Một instance cụ thể của R |\n| `X, Y` | Tập attribute |\n| `t1[X]` | Giá trị tuple t1 trên các attr thuộc X |\n| `X → Y` | \"Biết X là biết Y duy nhất\" |\n\n#### SQL kiểm tra vi phạm FD\n\nSQL không \"chứng minh\" FD đúng về ngữ nghĩa, chỉ kiểm tra instance hiện tại có vi phạm không:\n\n```sql\n-- Mẫu chung kiểm tra X → Y\nSELECT X, COUNT(DISTINCT Y) AS y_count\nFROM R\nGROUP BY X\nHAVING COUNT(DISTINCT Y) > 1;\n```\n\n- Nếu query rỗng → instance hiện tại không vi phạm.\n- Designer vẫn phải dựa vào **ngữ nghĩa miniworld** để khẳng định FD là luật lâu dài.\n\n> 💡 **Hiểu đơn giản:** FD `X → Y` giống như **luật \"biết số CCCD là biết tên\"**: không bao giờ có 2 người cùng CCCD khác tên. CCCD \"xác định\" tên. `SSN → ENAME` nghĩa là \"biết SSN là chắc chắn biết tên\".\n\n### 2.3. Ví dụ FD trên COMPANY (Slide 25)\n\n**1) SSN → EName** — số an sinh xã hội xác định tên nhân viên:\n```sql\nSELECT Ssn, COUNT(DISTINCT Fname || ' ' || Lname) AS name_count\nFROM EMPLOYEE\nGROUP BY Ssn\nHAVING COUNT(DISTINCT Fname || ' ' || Lname) > 1;\n```\n\n**2) PNumber → {PName, PLocation}** — số project xác định tên + location:\n```sql\nSELECT Pnumber,\n       COUNT(DISTINCT Pname) AS pname_count,\n       COUNT(DISTINCT Plocation) AS ploc_count\nFROM PROJECT\nGROUP BY Pnumber\nHAVING COUNT(DISTINCT Pname) > 1 OR COUNT(DISTINCT Plocation) > 1;\n```\n\n**3) {SSN, PNumber} → Hours** — cặp nhân viên-project xác định số giờ làm/tuần:\n```sql\nSELECT Essn, Pno, COUNT(DISTINCT Hours) AS hours_count\nFROM WORKS_ON\nGROUP BY Essn, Pno\nHAVING COUNT(DISTINCT Hours) > 1;\n```\n\n### 2.4. Quan hệ giữa FD và Key (Slide 26)\n\n**Quan trọng:** Nếu K là **key** của R, thì K **functionally determines** *tất cả* attribute trong R:\n$$K \\rightarrow R$$\n\n**Lý do:** Không có 2 tuple phân biệt cùng K → vế \"if t₁[K]=t₂[K]\" không bao giờ xảy ra → FD `K → bất cứ gì` đều thỏa \"vacuously\".\n\n### 2.5. Direct, Indirect, Partial Dependencies (Slides 28–30)\n\n#### 2.5.1. Direct dependency / Fully functional dependency (Slide 28)\n\n**Tất cả** attribute trong R phải **fully functionally dependent** vào PK.\n\nVí dụ `EMPLOYEE(**SSN**, Name, BDate, Address, DNO)`:\n```\nSSN → {Name, BDate, Address, DNO}\n```\n\n```\nEMPLOYEE\n┌─────┬──────┬───────┬─────────┬─────┐\n│ SSN │ Name │ BDate │ Address │ DNO │\n└──┬──┴──────┴───────┴─────────┴─────┘\n   │     ▲      ▲       ▲       ▲\n   └─────┴──────┴───────┴───────┘\n   SSN xác định tất cả attr (trực tiếp)\n```\n\n#### 2.5.2. Indirect / Transitive dependency (Slide 29)\n\nGiá trị attribute KHÔNG được xác định trực tiếp bởi PK — mà gián tiếp qua attribute khác.\n\nVí dụ `EMP_DEPT(**SSN**, Name, BDate, Address, DNO, DName)`:\n```\nSSN → DNO  và  DNO → DName  ⟹  SSN → DName (transitive)\n```\n\n```\nEMP_DEPT\n┌─────┬──────┬───────┬─────────┬─────┬───────┐\n│ SSN │ Name │ BDate │ Address │ DNO │ DName │\n└──┬──┴──────┴───────┴─────────┴──┬──┴───┬───┘\n   │     ▲      ▲       ▲         │      ▲\n   └─────┴──────┴───────┴─────────┘      │\n                                          │\n                                  DNO → DName (transitive!)\n```\n\nĐây là **dấu hiệu vi phạm 3NF**.\n\n#### 2.5.3. Partial dependency (Slide 30)\n\n- **Composite determinant:** Cần *nhiều hơn 1* attribute để xác định attribute khác. Ví dụ `{SSN, PNumber}` trong EMP_PROJ.\n- **Partial dependency:** Attribute KHÔNG phụ thuộc *toàn bộ* composite determinant — chỉ một *phần*.\n\nVí dụ `EMP_PROJ(**SSN, PNumber**, Hours, EName, PName, PLocation)` với PK = {SSN, PNumber}:\n```\n{SSN, PNumber} → Hours              (full)\nSSN            → EName              (partial — chỉ cần SSN)\nPNumber        → {PName, PLocation} (partial — chỉ cần PNumber)\n```\n\n```\nEMP_PROJ\n┌─────┬─────────┬───────┬───────┬───────┬───────────┐\n│ SSN │ PNumber │ Hours │ EName │ PName │ PLocation │\n└──┬──┴────┬────┴───┬───┴───┬───┴───┬───┴────┬──────┘\n   │       │        ▲       ▲       ▲        ▲\n   └───────┴────────┘       │       │        │\n   FD1: {SSN,PNumber} → Hours\n   │                        │       │        │\n   └─FD2: SSN → EName───────┘       │        │\n                                     │        │\n           FD3: PNumber → PName, PLocation ──┘\n```\n\nPartial dependency là **dấu hiệu vi phạm 2NF**.\n\n> 💡 **Hiểu đơn giản:** Partial dependency giống như **hóa đơn có khóa (Mã KH, Mã SP)**. *Số lượng mua* phụ thuộc cả khách và sản phẩm (full). Nhưng *tên khách* chỉ phụ thuộc mã KH (partial); *tên SP* chỉ phụ thuộc mã SP (partial). Nhét tất vào bảng chi tiết hóa đơn → lặp dữ liệu.\n\n> 📝 **Tóm lại section 2:**\n> - FD `X → Y`: biết X là biết Y (mọi cặp tuple cùng X phải cùng Y).\n> - FD được designer xác định từ **semantics nghiệp vụ**, KHÔNG suy ra từ data.\n> - Key K → tất cả attribute trong R.\n> - 3 loại đặc biệt: **Direct/full** (vi phạm = không có), **Indirect/transitive** (→ vi phạm 3NF), **Partial** (→ vi phạm 2NF).\n> **Một câu ghi nhớ:** *\"FD là ngôn ngữ chính thức của ràng buộc; Direct/Transitive/Partial là 3 'cá tính' của nó với key.\"*\n\n> ❓ **Tự kiểm tra section 2:**\n> 1. Cho EMPLOYEE(SSN, Name, Salary, DNO) PK=SSN. Liệt kê FD và phân loại.\n> 2. FD `Salary → SSN` có hợp lệ trong COMPANY không? Vì sao?\n> 3. Phân biệt **composite determinant** và **partial dependency**.\n\n---\n\n","file":"materials/DB-Chapter7.md","section":3},{"id":"c7-04","group":"c7","kind":"source","title":"3. Inference Rules — Quy tắc suy luận FD","markdown":"## 3. Inference Rules — Quy tắc suy luận FD\n\n### 3.1. Motivation\n\nKhi designer ghi tập FD F = {f1, ..., fn}, từ F có thể *suy ra* nhiều FD khác. Ví dụ: `SSN → DNO` và `DNO → DName` ⟹ `SSN → DName`. Việc suy luận quan trọng vì:\n- Cần biết toàn bộ FD đúng để kiểm tra normal form chính xác.\n- Cần thuật toán tính closure X⁺.\n\n**Armstrong's Inference Rules** (1974) là bộ 3 luật cơ bản — **đầy đủ và đúng đắn** (sound and complete).\n\n### 3.2. Armstrong's Inference Rules (Slide 33)\n\n- **IR1. (Reflexive — phản xạ):** Nếu `Y ⊆ X` thì `X → Y`.\n- **IR2. (Augmentation — thêm bổ sung):** Nếu `X → Y` thì `XZ → YZ`. (Notation: XZ = X ∪ Z)\n- **IR3. (Transitive — bắc cầu):** Nếu `X → Y` và `Y → Z` thì `X → Z`.\n\n> 💡 **Hiểu đơn giản:**\n> - **IR1:** Y ⊆ X thì X \"đã chứa\" Y → tự động xác định Y. Ví dụ: `{SSN, Name} → SSN`.\n> - **IR2:** Nếu `SSN → Name`, thêm Z vào cả 2 vế: `{SSN, Address} → {Name, Address}`. \"Biết SSN+Address thì chắc chắn biết Name+Address\".\n> - **IR3:** Bắc cầu logic A→B→C nên A→C.\n\n### 3.3. Derived Rules (Slide 34)\n\nSuy ra được từ IR1–IR3:\n\n- **Decomposition:** `X → YZ` ⟹ `X → Y` và `X → Z`.\n- **Union:** `X → Y` và `X → Z` ⟹ `X → YZ`.\n- **Pseudotransitivity:** `X → Y` và `WY → Z` ⟹ `WX → Z`.\n\n#### Chứng minh ngắn của 3 luật phái sinh\n\n**Decomposition** (X → YZ ⟹ X → Y):\n1. X → YZ (giả thiết)\n2. YZ → Y (IR1, Y ⊆ YZ)\n3. X → Y (IR3 từ 1,2)\n\n**Union** (X → Y và X → Z ⟹ X → YZ):\n1. X → Y\n2. X → Z\n3. X → XY (IR2 augment X)\n4. XY → YZ (IR2 augment Y vào X→Z)\n5. X → YZ (IR3 từ 3,4)\n\n**Pseudotransitivity** (X → Y, WY → Z ⟹ WX → Z):\n1. X → Y\n2. WX → WY (IR2 augment W)\n3. WY → Z\n4. WX → Z (IR3 từ 2,3)\n\n### 3.4. Closure F⁺ và X⁺ (Slide 35)\n\n- **F⁺** = tập tất cả FD suy ra được từ F.\n- **X⁺** = tập tất cả attribute mà X xác định.\n\n**Ý nghĩa thực tế của X⁺:**\n- Nếu X⁺ chứa tất cả attribute của R → X là **superkey**.\n- Nếu thêm vào đó không subset thực sự nào của X có closure = R → X là **candidate key**.\n\n### 3.5. Algorithm 16.1 — Tính X⁺ (Slide 36)\n\n```\nX⁺ := X;\nrepeat\n    oldX⁺ := X⁺;\n    for each functional dependency Y → Z in F do\n        if X⁺ ⊇ Y then X⁺ := X⁺ ∪ Z;\nuntil (X⁺ = oldX⁺);\n```\n\n**Cách hoạt động:**\n1. Khởi tạo X⁺ = X (IR1).\n2. Lặp: với mỗi `Y → Z` trong F, nếu X⁺ chứa Y thì thêm Z (vì X⁺ → Y → Z).\n3. Dừng khi X⁺ không đổi.\n\n### 3.6. Ví dụ tính X⁺ (Slide 37)\n\nCho **F = { AB → C, A → DE, B → M, M → GH, D → IJ }**:\n\n| X | X⁺ | Cách tính |\n|---|---|---|\n| {A, B} | {A, B, C, D, E, M, G, H, I, J} | AB→C, A→DE, B→M, M→GH, D→IJ — chứa tất cả → superkey |\n| {A} | {A, D, E, I, J} | A→DE, D→IJ |\n| {B} | {B, M, G, H} | B→M, M→GH |\n| {M} | {M, G, H} | M→GH |\n| {D} | {D, I, J} | D→IJ |\n\n### 3.7. Exercise (Slide 38)\n\n> **Bài tập 3.1:** Cho R(A, B, C, D, E) với F:\n> 1. AB → C\n> 2. CD → E\n> 3. DE → B\n>\n> Tìm `{A, B}⁺` và `{A, B, D}⁺`.\n>\n> **Giải {A, B}⁺:**\n> - Start: {A, B}\n> - AB → C: {A, B} ⊇ {A,B} ✓ → {A, B, C}\n> - CD → E: cần D, chưa có → bỏ qua\n> - DE → B: cần D, E, chưa có → bỏ qua\n> - **Kết quả:** `{A, B}⁺ = {A, B, C}`\n>\n> **Giải {A, B, D}⁺:**\n> - Start: {A, B, D}\n> - AB → C: ⊇ {A,B} ✓ → {A, B, C, D}\n> - CD → E: ⊇ {C, D} ✓ → {A, B, C, D, E}\n> - DE → B: ⊇ {D, E} ✓ → B đã có\n> - **Kết quả:** `{A, B, D}⁺ = {A, B, C, D, E} = R` → **superkey**!\n>\n> **Tại sao đúng:** Khi closure = R, X xác định tất cả → superkey. Có thể tối thiểu hoá để tìm candidate key.\n\n> 📝 **Tóm lại section 3:**\n> - Armstrong IR1/IR2/IR3 — sound + complete.\n> - Derived: Decomposition, Union, Pseudotransitivity.\n> - X⁺ tính bằng Algorithm 16.1; X⁺ = R ⟺ X là superkey.\n> **Một câu ghi nhớ:** *\"3 luật Armstrong → tính X⁺ → biết superkey hay không.\"*\n\n> ❓ **Tự kiểm tra section 3:**\n> 1. Phát biểu IR1, IR2, IR3 bằng lời.\n> 2. Cho F = {A→B, B→C, C→A}. Tính {A}⁺, {B}⁺, {C}⁺. Nhận xét?\n> 3. {X}⁺ = R ⟹ X là gì? Để X là candidate key cần thêm gì?\n\n---\n\n","file":"materials/DB-Chapter7.md","section":4},{"id":"c7-05","group":"c7","kind":"source","title":"4. Equivalence và Minimal Cover","markdown":"## 4. Equivalence và Minimal Cover\n\n### 4.1. Motivation\n\nHai designer có thể viết tập FD trông khác nhưng *cùng mô tả* một ràng buộc → cần **equivalence**.\n\nTập FD có thể chứa **luật thừa** → cắt bỏ → **minimal cover** — input chuẩn cho thuật toán normalization.\n\n### 4.2. Equivalence (Slide 41)\n\n- F và G **equivalent** ⟺ `F⁺ = G⁺`.\n- F **covers** G ⟺ `G⁺ ⊆ F⁺` (mọi FD suy từ G cũng suy từ F).\n- F và G equivalent ⟺ F covers G **và** G covers F.\n\n**Thuật toán kiểm tra F covers G:**\n- Với mỗi `X → Y` trong G, tính X⁺ theo F.\n- Nếu X⁺ ⊇ Y với *mọi* FD trong G → F covers G.\n\n**Ví dụ:**\n- F = {A → C, AC → D, E → AD, E → H}\n- G = {A → CD, E → AH}\n\n**F covers G:**\n- `A → CD` trong G: {A}⁺ theo F = {A, C, D} ⊇ {C, D} ✓\n- `E → AH` trong G: {E}⁺ theo F = {E, A, D, H, C} ⊇ {A, H} ✓\n\n**G covers F:**\n- `A → C`: {A}⁺ theo G = {A, C, D} ⊇ {C} ✓\n- `AC → D`: {A, C}⁺ theo G = {A, C, D} ⊇ {D} ✓\n- `E → AD`: {E}⁺ theo G = {E, A, H, C, D} ⊇ {A, D} ✓\n- `E → H`: ⊇ {H} ✓\n\n⟹ F ≡ G.\n\n### 4.3. Minimal Cover (Slides 42–43)\n\n**Tập F là minimal** nếu thỏa **3 điều kiện**:\n1. Mọi FD có **một attribute duy nhất** ở vế phải (single RHS).\n2. Không thể **xóa FD** nào mà vẫn equivalent với F.\n3. Không thể **thay X → A** bằng `Y → A` với `Y ⊊ X` mà vẫn equivalent.\n\n**Tính chất:**\n- Mọi tập FD có *ít nhất một* minimal set tương đương.\n- Có thể **nhiều** minimal set khác nhau equivalent.\n- **Không có thuật toán đơn giản** tổng quát — phải thử.\n- Khi synthesize quan hệ, giả định bắt đầu từ minimal set.\n\n### 4.4. Algorithm 16.2 — Tìm Minimal Cover (Slide 44)\n\n```\n1. Set F := E.\n2. Replace each X → {A1, A2, ..., An} in F\n   by n FDs X → A1, X → A2, ..., X → An.\n   (Tách RHS — đáp ứng đk 1)\n\n3. For each X → A in F\n       for each B in X\n           if { {F − {X → A}} ∪ { (X − {B}) → A } } ≡ F\n               then replace X → A with (X − {B}) → A.\n   (Rút LHS — đáp ứng đk 3)\n\n4. For each remaining X → A in F\n       if {F − {X → A}} ≡ F\n           then remove X → A.\n   (Bỏ FD thừa — đáp ứng đk 2)\n```\n\n### 4.5. Ví dụ Minimal Cover (Slide 45)\n\n> **Ví dụ 4.1:** E = {B → A, D → A, AB → D}. Tìm minimal cover.\n>\n> **Bước 1 — RHS đơn:** Tất cả đã đơn ✓\n>\n> **Bước 2 — Rút LHS** của AB → D:\n> - Thử bỏ A → `B → D`. Có B → A nên từ B suy A, kết hợp AB → D → B → D hợp lệ.\n> - Vậy A thừa trong AB → D. Thay → B → D.\n>\n> Trung gian: E = {B → A, B → D, D → A}.\n>\n> **Bước 3 — Bỏ FD thừa:**\n> - `B → A`: nếu bỏ, từ {B → D, D → A} qua transitive cũng có B → A → *thừa*. Bỏ.\n>\n> **Kết quả:** `E_min = {B → D, D → A}`.\n\n### 4.6. Exercise homework (Slide 46)\n\n> **Bài tập 4.2:** E = {A → B, ABCD → I, IJ → G, IJ → H, ACDJ → GI}. Tìm minimal cover.\n>\n> **Bước 1 — Tách RHS:** A→B, ABCD→I, IJ→G, IJ→H, ACDJ→G, ACDJ→I.\n>\n> **Bước 2 — Rút LHS:**\n> - `ABCD → I`: A → B nên B thừa → `ACD → I`.\n> - `ACDJ → I`: ACD → I đã đủ → ACDJ → I *thừa* (sẽ bỏ ở bước 3).\n> - `ACDJ → G`: ACD → I + IJ → G ⟹ ACDJ → G — thừa.\n>\n> **Bước 3 — Bỏ FD thừa:**\n> - `ACDJ → I` thừa (ACD → I đã có).\n> - `ACDJ → G` thừa.\n>\n> **Kết quả:** `F_min = { A → B, ACD → I, IJ → G, IJ → H }`.\n\n> 📝 **Tóm lại section 4:**\n> - F ≡ G ⟺ F⁺ = G⁺.\n> - Minimal cover = 3 điều kiện: RHS đơn, không FD thừa, không attribute thừa LHS.\n> - Algorithm 16.2: tách RHS → rút LHS → bỏ FD thừa.\n> **Một câu ghi nhớ:** *\"Minimal cover = tập FD gọn không thừa, input chuẩn của normalization.\"*\n\n> ❓ **Tự kiểm tra section 4:**\n> 1. Hai điều kiện cần để F equivalent với G?\n> 2. F = {A → B, B → C, A → C} có minimal không?\n> 3. Vì sao trong minimal cover yêu cầu RHS đơn?\n\n---\n\n","file":"materials/DB-Chapter7.md","section":5},{"id":"c7-06","group":"c7","kind":"source","title":"5. Key-finding Algorithms (Slides 82–87)","markdown":"## 5. Key-finding Algorithms (Slides 82–87)\n\n### 5.1. Key và Superkey — Nhắc lại (Slide 82)\n\n- **Superkey** SK: không có 2 tuple phân biệt nào cùng SK.\n- **Key** K: superkey *minimal* — không bỏ thêm attribute nào mà vẫn là superkey.\n- K → mọi attribute trong R.\n\n### 5.2. Algorithm 1 — Tìm MỘT key (Slides 83–84) — Elmasri & Navathe\n\n```\nInput: Relation R và tập FD F.\nOutput: Một key K của R.\n\n1. Set K := tất cả attribute trong R.\n2. For each attribute A in K {\n       compute (K − A)⁺ with respect to F;\n       if (K − A)⁺ chứa tất cả attribute của R then\n           set K := K − {A}\n   };\n```\n\n**Ý tưởng:** Bắt đầu K = toàn R (chắc chắn superkey). Lần lượt thử bỏ A — nếu K\\{A} vẫn superkey, A \"thừa\" → bỏ.\n\n**Hạn chế:** Chỉ tìm **MỘT** candidate key — phụ thuộc *thứ tự* xét.\n\n### 5.3. Algorithm 2 — Tìm TẤT CẢ candidate keys (Slides 85–87) — Saiedian & Spencer\n\n**Phân loại attribute:**\n- **U** = tất cả attribute của R.\n- **U_l** = attribute chỉ xuất hiện ở **vế trái** (Left only) của FD trong F.\n- **U_r** = attribute chỉ xuất hiện ở **vế phải** (Right only).\n- **U_b** = attribute xuất hiện ở **cả hai vế** (Both).\n\n**Tính chất:**\n- `U_l ∩ U_r = ∅, U_l ∩ U_b = ∅, U_r ∩ U_b = ∅` (rời nhau)\n- `U_l ∪ U_r ∪ U_b = U` (phủ hết)\n- A ∈ U_l ⟹ A **phải có** trong mọi candidate key.\n- A ∈ U_r ⟹ A **KHÔNG bao giờ** trong candidate key.\n\n> 💡 **Trực giác:** Attribute \"left only\" là attr \"không ai xác định nó được\" → key phải chứa. Attribute \"right only\" được xác định bởi attr khác → không cần đưa vào key.\n\n**Pseudocode:**\n```\n1. Determine U_l, U_r, U_b.\n2. If (U_l)⁺ = U under F:\n       U_l forms the only key, STOP.\n   Else: go to step 3.\n3. Consider every subset U_bi of U_b:\n       For each U_bi, if (U_l ∪ U_bi)⁺ = U under F:\n           K_i = (U_l ∪ U_bi) is a candidate key.\n   (*) Nếu K_i là candidate key, không cần check U_bj ⊃ U_bi.\n```\n\n### 5.4. Ví dụ minh họa Algorithm 2\n\n> **Ví dụ 5.1:** R(A, B, C, D, E, F) với F = { A,B,C → E,F; B → E; E → D }.\n>\n> **Bước 1:** Phân loại:\n> - LHS: {A, B, C, E}; RHS: {E, F, D}\n> - U_l = {A, B, C}; U_r = {F, D}; U_b = {E}\n>\n> **Bước 2:** `(U_l)⁺ = {A, B, C}⁺`:\n> - + ABC → EF: {A, B, C, E, F}\n> - + E → D: {A, B, C, D, E, F} = U ✓\n>\n> → `(U_l)⁺ = U` ⟹ **{A, B, C}** là candidate key duy nhất.\n\n### 5.5. So sánh 2 Algorithm\n\n| Tính chất | Algorithm 1 | Algorithm 2 |\n|---|---|---|\n| Tác giả | Elmasri & Navathe | Saiedian & Spencer |\n| Output | 1 candidate key | TẤT CẢ candidate keys |\n| Cách | Loại bỏ từng attr từ R | Phân loại U_l/U_r/U_b |\n| Phức tạp | Tuyến tính | Mũ theo \\|U_b\\| (worst case) |\n| Khi dùng | Cần 1 key nhanh | Cần đầy đủ (general 2NF/3NF) |\n\n> 📝 **Tóm lại section 5:**\n> - Algorithm 1: bóc dần từ R → 1 candidate key.\n> - Algorithm 2: phân loại attribute → tìm hết candidate keys.\n> - U_l⁺ = U ⟹ U_l là key duy nhất, dừng sớm.\n> **Một câu ghi nhớ:** *\"Phân loại left/right/both — tìm key như giải đố.\"*\n\n> ❓ **Tự kiểm tra section 5:**\n> 1. Vì sao attribute \"right only\" không bao giờ là phần của candidate key?\n> 2. Algorithm 1 trả về 1 key — sao biết đó là candidate key chứ không chỉ superkey?\n> 3. R(A, B, C, D) với F = {A→B, B→C, C→D}. Tìm tất cả candidate keys.\n\n---\n\n","file":"materials/DB-Chapter7.md","section":6},{"id":"c7-07","group":"c7","kind":"source","title":"6. Normalization — 1NF, 2NF, 3NF (Slides 46–66)","markdown":"## 6. Normalization — 1NF, 2NF, 3NF (Slides 46–66)\n\n### 6.1. Tại sao có concept này?\n\nBây giờ ta dùng FD + key + closure để định nghĩa các **normal forms** — mức độ \"tốt\" của một quan hệ:\n- **1NF** giải quyết: attribute đa trị / nested.\n- **2NF** giải quyết: partial dependency.\n- **3NF** giải quyết: transitive dependency.\n- **BCNF** giải quyết: bất kỳ FD nào có LHS không phải superkey.\n\n### 6.2. Normalization là gì? (Slide 46)\n\n- **Normalization:** Quá trình **decomposing** quan hệ \"tệ\" bằng cách tách attribute thành các quan hệ nhỏ hơn.\n- **Normal form:** Dùng keys + FDs để **chứng nhận** một schema ở chuẩn nào.\n- Designer **KHÔNG nhất thiết** phải normalize đến cao nhất (3NF, BCNF, 4NF) — đôi khi denormalize có lợi cho hiệu suất đọc.\n\n### 6.3. Prime / Nonprime attribute (Slides 48–49)\n\n- **Prime attribute (thuộc tính nguyên tố):** Thành viên của **ít nhất một** candidate key.\n- **Nonprime attribute:** KHÔNG là thành viên của bất kỳ candidate key nào.\n\n> 💡 **Ví dụ COMPANY:**\n> - EMPLOYEE(**Ssn**, Fname, Salary, Dno): Prime = {Ssn}; Nonprime = {Fname, Salary, Dno}.\n> - WORKS_ON(**Ssn, Pno**, Hours): Prime = {Ssn, Pno}; Nonprime = {Hours}.\n\n### 6.4. 1NF — First Normal Form (Slides 51–57)\n\n#### 6.4.1. Định nghĩa (Slide 51)\n\n**1NF:** Mỗi giao của row × column trong relation chỉ có **một giá trị duy nhất** (atomic). KHÔNG có:\n- Composite attribute (thuộc tính phức hợp).\n- Multivalued attribute (đa trị).\n- Nested relation (quan hệ lồng).\n\n1NF là **một phần của định nghĩa formal** relation trong basic (flat) relational model.\n\n> 💡 **Hiểu đơn giản:** 1NF giống **luật \"mỗi ô spreadsheet chỉ chứa 1 giá trị\"**: không viết \"Bellaire, Sugarland, Houston\" trong cùng một ô Dlocations.\n\n#### 6.4.2. Ví dụ 1NF với multivalued (Slide 52)\n\n**Trước 1NF:**\n| Dname | Dnumber | Dmgr_ssn | Dlocations |\n|---|---|---|---|\n| Research | 5 | 333445555 | {Bellaire, Sugarland, Houston} |\n| Administration | 4 | 987654321 | {Stafford} |\n| Headquarters | 1 | 888665555 | {Houston} |\n\n**Sau 1NF (tách dòng):** PK mới = {Dnumber, Dlocation}\n| Dname | Dnumber | Dmgr_ssn | Dlocation |\n|---|---|---|---|\n| Research | 5 | 333445555 | Bellaire |\n| Research | 5 | 333445555 | Sugarland |\n| Research | 5 | 333445555 | Houston |\n| Administration | 4 | 987654321 | Stafford |\n| Headquarters | 1 | 888665555 | Houston |\n\n**Hoặc thiết kế tốt hơn (chuẩn COMPANY) — tách bảng:**\n- `DEPARTMENT(Dname, Dnumber, Mgr_ssn, Mgr_start_date)`\n- `DEPT_LOCATIONS(Dnumber, Dlocation)` ← bảng riêng cho location\n\n#### 6.4.3. Ví dụ 1NF với nested relation (Slides 53–54)\n\n**Trước 1NF (nested):**\n```\nEMP_PROJ\n[SSN] [ENAME] [PROJS]\n              [PNUMBER] [HOURS]\n```\n\n**Sau 1NF (tách bảng):**\n- `EMP_PROJ1(Ssn, Ename)`\n- `EMP_PROJ2(Ssn, Pnumber, Hours)`\n\n#### 6.4.4. EMP_PROJ flat sau 1NF — chuẩn bị 2NF (Slides 55–57)\n\n```\nEMP_PROJ(SSN, PNumber, Hours, EName, PName, PLocation)\n```\n\nFDs:\n1. `SSN, PNumber → Hours`     (full)\n2. `SSN → EName`               (partial — chỉ cần SSN)\n3. `PNumber → PName, PLocation` (partial)\n\n→ Đã ở 1NF nhưng vẫn có partial dependencies → cần 2NF.\n\n> 📝 **Tóm lại 1NF:**\n> - 1NF cấm: composite, multivalued, nested.\n> - Chữa: tách dòng (multivalued) hoặc tách bảng (nested).\n> - 1NF là *yêu cầu tối thiểu* của relational model.\n\n### 6.5. 2NF — Second Normal Form (Slides 59–61)\n\n#### 6.5.1. Định nghĩa (Slide 59)\n\n**2NF:** Mọi **nonprime attribute** phải **fully functionally dependent** vào primary key.\n\n→ Giải quyết **partial dependency** ở 1NF.\n\n**2NF normalized:** Phân rã và tạo quan hệ mới cho **mỗi partial key** + attribute phụ thuộc nó. Giữ quan hệ với PK gốc + attribute phụ thuộc đầy đủ.\n\n> 💡 **Lưu ý:** Định nghĩa 2NF \"primary-key-based\" chỉ áp dụng cho quan hệ 1 candidate key. Quan hệ nhiều candidate keys dùng định nghĩa general (Section 7).\n\n#### 6.5.2. Ví dụ EMP_PROJ → 2NF (Slide 60)\n\n**Trước:** `EMP_PROJ(SSN, PNumber, Hours, EName, PName, PLocation)` — FD2, FD3 là partial.\n\n**Sau 2NF:**\n\n| Relation | Attributes | Key | FD giữ |\n|---|---|---|---|\n| `EP1` | SSN, PNumber, Hours | {SSN, PNumber} | {SSN, PNumber} → Hours |\n| `EP2` | SSN, EName | SSN | SSN → EName |\n| `EP3` | PNumber, PName, PLocation | PNumber | PNumber → PName, PLocation |\n\nMỗi quan hệ KHÔNG còn partial dependency → **đạt 2NF**.\n\n#### 6.5.3. Vấn đề còn lại sau 2NF (Slide 61)\n\nEMP_DEPT(Ename, Ssn, Bdate, Address, Dnumber, Dname, Dmgr_ssn) đã ở 2NF (PK đơn = Ssn → không có partial). Nhưng vẫn có:\n```\nSsn → Dnumber → (Dname, Dmgr_ssn)   ← transitive!\n```\n\nCụm `(Dname, Dmgr_ssn)` lặp lại với từng nhân viên cùng phòng → cần 3NF.\n\n> 📝 **Tóm lại 2NF:**\n> - 2NF = 1NF + mọi nonprime fully dependent PK.\n> - Vi phạm: PK composite + nonprime chỉ phụ thuộc 1 phần PK.\n> - Chữa: tách (partial key + attr phụ thuộc) thành quan hệ con.\n\n### 6.6. 3NF — Third Normal Form (Slides 63–65)\n\n#### 6.6.1. Định nghĩa (Slide 63)\n\n**3NF:** R ở 3NF nếu:\n1. R ở 2NF, **VÀ**\n2. KHÔNG có nonprime attribute A nào **transitively dependent** trên PK.\n\n**NOTE quan trọng:**\n- Trong `X → Y` và `Y → Z`, với X là PK: vấn đề **CHỈ KHI Y KHÔNG phải candidate key**.\n- Khi Y *là* candidate key, transitive dependency *không có vấn đề*.\n\n**Ví dụ:** EMP(SSN, Emp#, Salary). `SSN → Emp#` và `Emp# → Salary`. Emp# *cũng là candidate key* → OK, không vi phạm 3NF.\n\n#### 6.6.2. 3NF Normalization (Slide 64)\n\nXác định *tất cả* transitive dependencies. Mỗi transitive dependency tạo thành **một quan hệ mới**, với:\n- **Nonprime attribute** tham gia transitive dep,\n- Attribute \"quyết định\" (determinant) làm key quan hệ mới.\n\n#### 6.6.3. Ví dụ EMP_DEPT → 3NF (Slide 65)\n\n**Trước:** `EMP_DEPT(Ename, Ssn, Bdate, Address, Dnumber, Dname, Dmgr_ssn)` với transitive Ssn → Dnumber → (Dname, Dmgr_ssn).\n\n**Sau 3NF:**\n\n| Relation | Attributes | Key | Ý nghĩa |\n|---|---|---|---|\n| `ED1` | Ename, Ssn, Bdate, Address, Dnumber | Ssn | Thông tin employee + FK Dnumber |\n| `ED2` | Dnumber, Dname, Dmgr_ssn | Dnumber | Thông tin department |\n\n`Dname, Dmgr_ssn` không còn lặp ở từng employee → đạt 3NF.\n\n### 6.7. Bảng tổng kết NF dựa trên PK (Slide 66)\n\n| Normal Form | Test | Remedy (Normalization) |\n|---|---|---|\n| **First (1NF)** | Không có multivalued attribute hoặc nested relation. | Tạo quan hệ mới cho mỗi multivalued/nested. |\n| **Second (2NF)** | Với quan hệ có PK gồm nhiều attribute, không có nonkey attribute phụ thuộc một phần PK. | Phân rã, tạo quan hệ mới cho mỗi partial key + attribute phụ thuộc. Giữ quan hệ chứa PK gốc + attr phụ thuộc đầy đủ. |\n| **Third (3NF)** | Không có nonkey attribute xác định bởi nonkey attribute khác (không có transitive dep của nonkey trên PK). | Phân rã, tạo quan hệ chứa nonkey attribute xác định nonkey khác. |\n\n> 📝 **Tóm lại 3NF:**\n> - 3NF = 2NF + không có nonprime transitively dependent PK.\n> - Vi phạm: nonprime A \"đi qua\" nonprime B để phụ thuộc PK.\n> - Chữa: tách (B, attr_phụ_thuộc_B) thành quan hệ con; B làm FK ở quan hệ chính.\n> - **Ngoại lệ:** B *cũng là candidate key* → không vi phạm.\n\n> ❓ **Tự kiểm tra section 6:**\n> 1. LIBRARY_BOOK(ISBN, Title, AuthorID, AuthorName). FD: ISBN → AuthorID, AuthorID → AuthorName. Vi phạm 3NF không?\n> 2. Sau ED1, ED2 — chỉ ra PK + FK của mỗi.\n> 3. Vì sao 3NF cho phép \"transitive qua candidate key\" mà BCNF cấm?\n\n---\n\n","file":"materials/DB-Chapter7.md","section":7},{"id":"c7-08","group":"c7","kind":"source","title":"7. General Normal Form Definitions (Slides 67–73)","markdown":"## 7. General Normal Form Definitions (Slides 67–73)\n\n### 7.1. Motivation\n\nĐịnh nghĩa 2NF, 3NF ở trên chỉ dựa **primary key đơn**. Quan hệ có nhiều **candidate keys** cần định nghĩa tổng quát hơn.\n\n### 7.2. Định nghĩa General (Slides 67–68)\n\n**Prime attribute:** Thành viên của *bất kỳ* candidate key nào. Partial/full/transitive dependency được xét **với mọi candidate key**.\n\n**2NF (general):** R ở 2NF nếu **mọi nonprime attribute A** fully functionally dependent trên **mọi key** của R.\n\n**3NF (general):** R ở 3NF nếu với mọi FD `X → A` đúng trong R, thì **hoặc**:\n- **(a)** X là **superkey** của R, **HOẶC**\n- **(b)** A là **prime attribute** của R.\n\n> 💡 **3NF \"dễ thở hơn\" BCNF:** 3NF cho phép FD có LHS không phải superkey nếu RHS là prime. BCNF nghiêm: LHS phải là superkey.\n\n### 7.3. Ví dụ LOTS (Slides 69–72)\n\n**LOTS(Property_id#, County_name, Lot#, Area, Price, Tax_rate)**\n\n**Candidate keys:** {Property_id#}, {County_name, Lot#}.\n**Prime:** Property_id#, County_name, Lot#. **Nonprime:** Area, Price, Tax_rate.\n\n**FDs:**\n- FD1: `Property_id# → County_name, Lot#, Area, Price, Tax_rate`\n- FD2: `{County_name, Lot#} → Property_id#, Area, Price, Tax_rate`\n- FD3: `County_name → Tax_rate`\n- FD4: `Area → Price`\n\n**Phân tích:**\n- FD3: County_name (prime) → Tax_rate (nonprime). Tax_rate phụ thuộc *một phần* của candidate key {County_name, Lot#} → **vi phạm 2NF general**.\n- FD4: Area (nonprime) → Price (nonprime). → Price *transitively* phụ thuộc trên CK qua nonprime → **vi phạm 3NF**.\n\n#### Phân rã LOTS → 2NF (Slide 70)\n\n```\nLOTS1(Property_id#, County_name, Lot#, Area, Price)\nLOTS2(County_name, Tax_rate)\n```\n\nLOTS1 còn FD4 (Area → Price) → vẫn vi phạm 3NF.\n\n#### Phân rã LOTS1 → 3NF (Slide 72)\n\n```\nLOTS1A(Property_id#, County_name, Lot#, Area)\nLOTS1B(Area, Price)\n```\n\n**Cây phân rã hoàn chỉnh:**\n```\nLOTS                           1NF\n├── LOTS1                      2NF\n│   ├── LOTS1A                 3NF\n│   └── LOTS1B                 3NF\n└── LOTS2                      3NF\n```\n\n> ❓ **Tự kiểm tra section 7:**\n> 1. Trong LOTS, vì sao Tax_rate vi phạm 2NF general nhưng *không* vi phạm 2NF PK-based nếu PK = {Property_id#}?\n> 2. Định nghĩa \"Prime attribute\" — ví dụ trong LOTS.\n> 3. Phát biểu 3NF general bằng lời.\n\n---\n\n","file":"materials/DB-Chapter7.md","section":8},{"id":"c7-09","group":"c7","kind":"source","title":"8. BCNF — Boyce-Codd Normal Form (Slides 75–80)","markdown":"## 8. BCNF — Boyce-Codd Normal Form (Slides 75–80)\n\n### 8.1. Motivation\n\n3NF (general) cho phép FD `X → A` đúng nếu X superkey *hoặc* A prime. BCNF cấm hoàn toàn nhánh (b), chỉ chấp nhận X là superkey. Đây là chuẩn **chặt nhất** dựa trên FD.\n\n### 8.2. Định nghĩa BCNF (Slide 75)\n\n**BCNF:** R ở BCNF nếu khi `X → A` đúng trong R, **X PHẢI là superkey** của R.\n\n> 💡 **So sánh BCNF vs 3NF:**\n> - **3NF:** X superkey **OR** A prime.\n> - **BCNF:** X superkey **ONLY**.\n> ⟹ BCNF ⊊ 3NF (mọi quan hệ BCNF cũng ở 3NF, không ngược lại).\n\n### 8.3. LOTS1A với FD5 → BCNF (Slide 76)\n\nGiả sử thêm `FD5: Area → County_name`.\n\nTrong LOTS1A(Property_id#, County_name, Lot#, Area):\n- FD5 (Area → County_name): Area có là superkey? {Area}⁺ = {Area, County_name} ≠ LOTS1A → KHÔNG → **vi phạm BCNF**.\n- Nhưng County_name *là prime* → 3NF OK.\n\n**BCNF decomposition:**\n```\nLOTS1AX(Property_id#, Area, Lot#)\nLOTS1AY(Area, County_name)\n```\n\n**Lưu ý:** FD2 ({County_name, Lot#} → Property_id#) **bị MẤT** trong phân rã này — hi sinh **dependency preservation** để đạt BCNF.\n\n### 8.4. Ví dụ kinh điển TEACH (Slides 77–78)\n\n**TEACH(Student, Course, Instructor)** với:\n- FD1: `{Student, Course} → Instructor`\n- FD2: `Instructor → Course`\n\n**Instance:**\n| Student | Course | Instructor |\n|---|---|---|\n| Narayan | Database | Mark |\n| Smith | Database | Navathe |\n| Smith | Operating Systems | Ammar |\n| Smith | Theory | Schulman |\n| Wallace | Database | Mark |\n| Wallace | Operating Systems | Ahamad |\n| Wong | Database | Omiecinski |\n| Zelaya | Database | Navathe |\n| Narayan | Operating Systems | Ammar |\n\n**Candidate keys:** {Student, Course}, {Student, Instructor}.\n**Prime:** Student, Course, Instructor (đều thuộc một CK).\n\n**Phân tích BCNF:**\n- FD1: vế trái = CK → OK.\n- FD2: Instructor không superkey ({Instructor}⁺ = {Instructor, Course} ≠ TEACH) → **vi phạm BCNF**. Nhưng Course là prime → 3NF OK.\n\n**Ba khả năng phân rã:**\n1. {Student, Instructor} và {Student, Course}\n2. {Course, Instructor} và {Course, Student}\n3. **{Instructor, Course} và {Instructor, Student}** ← thường chọn\n\n**Cả 3 đều mất FD1.** Lựa chọn 3 là *tốt nhất* vì JOIN lại không sinh spurious (nonadditive).\n\n> 💡 **Tradeoff:** Khi BCNF và dependency preservation xung đột → **ưu tiên lossless/non-additive join**. Designer có thể chọn ở lại 3NF để giữ FD.\n\n### 8.5. Algorithm 16.5 — Phân rã BCNF (Slide 79)\n\n```\n1. Set D := {R};\n2. While ∃ Q ∈ D không ở BCNF:\n   {\n       choose Q in D không BCNF;\n       find FD X → Y in Q vi phạm BCNF;\n       replace Q in D by (Q − Y) và (X ∪ Y);\n   };\n```\n\n### 8.6. NJB Test — Nonadditive Join cho Binary Decomposition (Slide 80)\n\n**NJB Test:** D = {R1, R2} của R có **lossless/nonadditive join property** với respect to F *iff*:\n- `((R1 ∩ R2) → (R1 − R2)) ∈ F⁺`, **HOẶC**\n- `((R1 ∩ R2) → (R2 − R1)) ∈ F⁺`.\n\n**Ý nghĩa:** Phần \"giao\" của 2 quan hệ phải xác định ít nhất một bên — không thì JOIN sinh spurious.\n\n> 💡 **Áp dụng NJB cho LOTS1A → LOTS1AX, LOTS1AY:**\n> - R1 ∩ R2 = {Area}; R1 − R2 = {Property_id#, Lot#}; R2 − R1 = {County_name}.\n> - FD5: Area → County_name = ((R1∩R2) → (R2−R1)) ∈ F⁺ ✓ → **nonadditive**.\n\n> 📝 **Tóm lại section 8:**\n> - BCNF: mọi FD `X → A` phải có X là superkey.\n> - BCNF ⊊ 3NF (chặt hơn).\n> - Phân rã BCNF có thể mất dependency preservation → cân nhắc giữa BCNF và 3NF.\n> - NJB cho binary: giao phải xác định ít nhất một bên.\n> **Một câu ghi nhớ:** *\"BCNF: mọi mũi tên FD phải xuất phát từ một (super)key — không ngoại lệ.\"*\n\n> ❓ **Tự kiểm tra section 8:**\n> 1. Phân biệt BCNF vs 3NF qua ví dụ TEACH.\n> 2. Khi nào designer nên giữ ở 3NF, không lên BCNF?\n> 3. Phát biểu NJB cho binary — vì sao đảm bảo nonadditive?\n\n---\n\n","file":"materials/DB-Chapter7.md","section":9},{"id":"c7-10","group":"c7","kind":"source","title":"9. Bài tập từ slide (Slides 90–95)","markdown":"## 9. Bài tập từ slide (Slides 90–95)\n\n### 9.1. Exercise 1 — R(A,B,C,D,E,F)\n\n**Đề:** F = { ABC → EF, B → E, E → D }. Tìm key. Phân rã 2NF, 3NF, BCNF.\n\n**Giải:**\n\n**Bước 1 — Tìm key:**\n- LHS: {A, B, C, E}; RHS: {E, F, D}\n- U_l = {A, B, C}; U_r = {F, D}; U_b = {E}\n- `(U_l)⁺ = {A,B,C}⁺` = {A,B,C} + EF (ABC→EF) + D (E→D) = R ✓\n- → Candidate key duy nhất: **{A, B, C}**.\n\n**Prime:** A, B, C. **Nonprime:** D, E, F.\n\n**Bước 2 — 2NF:** FD2 (B → E): E nonprime, B là *một phần* của PK {A,B,C} → **vi phạm 2NF**.\n\nPhân rã:\n- R1(B, E, D) với key B\n- R2(A, B, C, F) với key {A, B, C}\n\n**Bước 3 — 3NF:** Trong R1, có B → E → D (transitive) → vi phạm 3NF.\n\nPhân rã tiếp:\n- R1a(B, E)\n- R1b(E, D)\n- R2(A, B, C, F)\n\n**Bước 4 — BCNF:**\n- R1a(B, E): B là key → BCNF ✓\n- R1b(E, D): E là key → BCNF ✓\n- R2(A, B, C, F): {A, B, C} là key → BCNF ✓\n\n→ Đã đạt BCNF.\n\n### 9.2. Exercise 2 — R(A..J)\n\n**Đề:** F = { AB → C, A → DE, B → F, F → GH, D → IJ }. Tìm key. Phân rã 2NF, 3NF.\n\n**Giải:**\n\n**Tìm key:** Attribute không xuất hiện RHS: {A, B}. {A, B}⁺:\n- + AB→C: {A,B,C}; + A→DE: +D,E; + B→F: +F; + F→GH: +G,H; + D→IJ: +I,J\n- = {A, B, C, D, E, F, G, H, I, J} = R ✓\n- → Candidate key duy nhất: **{A, B}**.\n\n**Prime:** A, B. **Nonprime:** còn lại.\n\n**Vi phạm 2NF:** A → DE và B → F (chỉ phụ thuộc một phần PK).\n\n**Phân rã 3NF (cuối cùng):**\n- R1(A, B, C)\n- R2(A, D, E)\n- R3(D, I, J)   ← tách D → IJ\n- R4(B, F)\n- R5(F, G, H)   ← tách F → GH\n\n### 9.3. Exercise 3 — R(A,B,C,D,E,F) — CHÚ Ý\n\n**Đề:** F = { AD → B, AB → E, C → D, B → C, AC → F }. Tìm key. Phân rã 2NF, 3NF.\n\n**Giải:**\n\n**Tìm key:**\n- LHS: {A, B, C, D}; RHS: {B, E, D, C, F}\n- U_l = {A}; U_r = {E, F}; U_b = {B, C, D}\n- {A}⁺ = {A} — không phủ R.\n- Thử thêm subset U_b:\n  - {A,B}⁺: B→C, C→D, AD→B (đã có), AB→E, AC→F → R ✓ → **{A,B} CK**.\n  - {A,C}⁺: C→D, AD→B, AB→E, AC→F → R ✓ → **{A,C} CK**.\n  - {A,D}⁺: AD→B, B→C, AB→E, AC→F → R ✓ → **{A,D} CK**.\n- **Candidate keys:** {A,B}, {A,C}, {A,D}.\n\n**Prime:** A, B, C, D. **Nonprime:** E, F.\n\n**Kiểm tra 2NF (general):**\n- AB → E: AB là CK → OK.\n- AC → F: AC là CK → OK.\n- AD → B: B là prime → OK (không partial của nonprime).\n- B → C: cả 2 đều prime → không phải nonprime phụ thuộc partial.\n- C → D: cả 2 đều prime → OK.\n\n→ **R đã đạt 2NF.**\n\n**Kiểm tra 3NF (general):** Với mọi FD `X → A`, X superkey hoặc A prime?\n- AD → B: AD superkey → OK.\n- AB → E: AB superkey → OK.\n- AC → F: AC superkey → OK.\n- B → C: B không superkey ({B}⁺ = {B,C,D,F nếu có,...} chưa phủ R), nhưng **C là prime** → OK.\n- C → D: C không superkey, **D là prime** → OK.\n\n→ **R đã đạt 3NF.** Không cần tách!\n\n**BCNF?** Với B → C: B không superkey → **vi phạm BCNF**. Tương tự C → D. → Để đạt BCNF cần phân rã thêm (có thể mất dependency).\n\n### 9.4. Exercise 4 — R(A,B,C,D,E,F)\n\n**Đề:** F = { A → B, C → AD, AF → CE }. Tìm key. Phân rã 2NF, 3NF, BCNF.\n\n**Giải:**\n\n**Tìm key:**\n- LHS: {A, C, F}; RHS: {B, A, D, C, E}\n- U_l = {F}; U_r = {B, D, E}; U_b = {A, C}\n- {F}⁺ = {F} — không phủ.\n- {A, F}⁺: A→B, AF→CE, C→AD → R ✓ → **{A,F} CK**.\n- {C, F}⁺: C→AD, A→B, AF→CE → R ✓ → **{C,F} CK**.\n\n**Candidate keys:** {A, F}, {C, F}.\n**Prime:** A, C, F. **Nonprime:** B, D, E.\n\n**Vi phạm 2NF:**\n- A → B: B nonprime phụ thuộc một phần PK {A, F} → vi phạm.\n- C → D: D nonprime phụ thuộc một phần PK {C, F} → vi phạm.\n\n**Phân rã 2NF:**\n- R1(A, B)\n- R2(C, A, D)\n- R3(A, F, C, E)\n\n**3NF:** Trong R3, FD `C → A` (từ C → AD): A là prime → OK.\n\n→ Đã đạt 3NF.\n\n**BCNF:** Trong R3, `C → A`: C không superkey của R3 ({C}⁺ trong R3 = {C, A} ≠ R3) → vi phạm BCNF.\n\nPhân rã BCNF:\n- R1(A, B)\n- R2(C, A, D)\n- R3(C, F, E)   ← {C, F} → E\n\n### 9.5. Exercise 5 — BOOK (Slide 94)\n\n**Đề:** `BOOK(Book_title, Author_name, Book_type, List_price, Author_affil, Publisher)` với:\n1. Book_title → Publisher, Book_type\n2. Book_type → List_price\n3. Author_name → Author_affil\n\n**Yêu cầu:** (a) R đang ở NF nào? (b) Phân rã đến không thể tiếp.\n\n**Giải:**\n\n**Tìm key:**\n- LHS: {Book_title, Book_type, Author_name}; RHS: {Publisher, Book_type, List_price, Author_affil}\n- U_l = {Book_title, Author_name}; U_r = {Publisher, List_price, Author_affil}; U_b = {Book_type}\n- {Book_title, Author_name}⁺ = + Publisher,Book_type + List_price + Author_affil = R ✓\n- → Candidate key duy nhất: **{Book_title, Author_name}**.\n\n**Prime:** Book_title, Author_name. **Nonprime:** còn lại.\n\n**NF hiện tại:**\n- 1NF? Giả định mọi attribute atomic → ✓\n- 2NF? Book_title → Publisher,Book_type là partial (Publisher, Book_type nonprime phụ thuộc một phần PK) → **vi phạm 2NF**.\n- → BOOK đang ở **1NF**.\n\n**Phân rã đầy đủ (3NF/BCNF):**\n- `BOOK_AUTHOR(Book_title, Author_name)`\n- `BOOK_INFO(Book_title, Publisher, Book_type)`\n- `BOOK_TYPE(Book_type, List_price)`\n- `AUTHOR(Author_name, Author_affil)`\n\nMỗi quan hệ đạt 3NF và BCNF.\n\n### 9.6. Exercise 6 — BOOK common-sense (Slide 95)\n\n**Đề:** `BOOK(Book_Name, Author, Edition, Year)`. Candidate keys là gì?\n\n| Book_Name | Author | Edition | Copyright_Year |\n|---|---|---|---|\n| DB_fundamentals | Navathe | 4 | 2004 |\n| DB_fundamentals | Elmasri | 4 | 2004 |\n| DB_fundamentals | Elmasri | 5 | 2007 |\n| DB_fundamentals | Navathe | 5 | 2007 |\n\n**Phân tích:** Cùng book có nhiều author, nhiều edition. Một (Book_Name, Edition) → 1 Year.\n\n**Candidate key hợp lý:** `{Book_Name, Author, Edition}`.\n\n(Year nonprime phụ thuộc {Book_Name, Edition} → partial → vi phạm 2NF. Trong thực tế nên dùng surrogate key/ISBN.)\n\n---\n\n","file":"materials/DB-Chapter7.md","section":10},{"id":"c7-11","group":"c7","kind":"source","title":"Bảng Tra Nhanh — Tổng Hợp Thuật Ngữ Chương 7","markdown":"## Bảng Tra Nhanh — Tổng Hợp Thuật Ngữ Chương 7\n\n| Thuật ngữ | Định nghĩa 1 dòng | Ký hiệu/Cú pháp | Ví dụ COMPANY |\n|---|---|---|---|\n| Functional Dependency (FD) | Biết X chắc chắn biết Y | X → Y | Ssn → Ename |\n| Closure F⁺ | Tất cả FD suy ra từ F | F⁺ | — |\n| Closure X⁺ | Tất cả attr mà X xác định | X⁺ | {Ssn}⁺ = mọi attr EMPLOYEE |\n| Direct (full) dependency | RHS phụ thuộc đầy đủ PK | PK → A | Ssn → Salary |\n| Transitive dependency | A → B → C nên A → C qua trung gian | X → Y → Z | Ssn → Dno → Dname |\n| Partial dependency | RHS chỉ phụ thuộc 1 phần composite PK | (X,Y) but X → Z | {Ssn,Pno}: Ssn → Ename |\n| IR1 Reflexive | Y ⊆ X ⟹ X → Y | — | {Ssn, Ename} → Ssn |\n| IR2 Augmentation | X → Y ⟹ XZ → YZ | — | Ssn→Ename ⟹ Ssn,Dno→Ename,Dno |\n| IR3 Transitive | X→Y, Y→Z ⟹ X→Z | — | Ssn→Dno, Dno→Dname ⟹ Ssn→Dname |\n| Decomposition rule | X→YZ ⟹ X→Y và X→Z | — | — |\n| Union rule | X→Y, X→Z ⟹ X→YZ | — | — |\n| Pseudotransitivity | X→Y, WY→Z ⟹ WX→Z | — | — |\n| Equivalence | F⁺ = G⁺ | F ≡ G | — |\n| Cover | G⁺ ⊆ F⁺ | F covers G | — |\n| Minimal cover | F gọn nhất tương đương | 3 đk: RHS đơn, không thừa FD, không thừa LHS | — |\n| Superkey | Không 2 tuple cùng SK | t₁[SK] ≠ t₂[SK] | {Ssn}, {Ssn,Ename} |\n| Candidate key | Superkey tối thiểu | — | {Ssn} |\n| Prime attribute | Thành viên ít nhất 1 CK | — | Ssn (trong EMPLOYEE) |\n| Nonprime attribute | Không thuộc CK nào | — | Salary, Bdate |\n| 1NF | Mỗi ô 1 giá trị atomic | — | DEPT_LOCATIONS chuẩn |\n| 2NF | 1NF + không partial dep | mọi nonprime full FD vào mọi key | EP1, EP2, EP3 sau phân rã |\n| 3NF | 2NF + không transitive nonkey | ∀ X→A: X superkey HOẶC A prime | ED1, ED2 sau phân rã |\n| BCNF | ∀ FD X→A: X PHẢI superkey | — | LOTS1AX, LOTS1AY |\n| Nonadditive join | JOIN không sinh spurious | NJB test | — |\n| Dependency preservation | FD gốc kiểm tra được trên các quan hệ con | có thể hi sinh ở BCNF | TEACH mất FD1 |\n| Spurious tuple | Tuple sinh từ JOIN sai | — | EMP_LOCS ⋈ EMP_PROJ1 |\n| Update anomaly | Lỗi modification/insertion/deletion | — | EMP_DEPT đổi manager |\n\n---\n\n","file":"materials/DB-Chapter7.md","section":11},{"id":"c7-12","group":"c7","kind":"source","title":"Sai Lầm Thường Gặp khi Học Chương 7","markdown":"## Sai Lầm Thường Gặp khi Học Chương 7\n\n| Sai lầm | Tại sao sai | Cách đúng |\n|---|---|---|\n| \"Quan hệ có PK đơn thì luôn ở 2NF\" — quên xét general 2NF với nhiều CK | 2NF general xét **mọi** candidate key. PK đơn nhưng có CK composite vẫn có thể vi phạm. | Tìm hết CK trước (Algorithm 2), rồi áp định nghĩa general. |\n| \"Mỗi FD vi phạm thì tách ngay 1 quan hệ riêng\" | Có thể tạo dư thừa quan hệ. Nên gom các FD có cùng vế trái. | Áp Algorithm 16.5 hoặc 3NF Synthesis (gom FD cùng LHS). |\n| Nhầm transitive: \"Bất kỳ X→Y→Z đều xấu\" | Khi Y là CK, transitive *không phải* vấn đề (slide 63). | Chỉ tách khi Y *không phải* CK. |\n| Quên thuộc tính chỉ xuất hiện LHS là **bắt buộc** trong mọi CK | Bỏ sót CK hoặc nhầm thành CK sai. | Phân loại U_l ngay đầu — U_l ⊆ mọi CK. |\n| Nhầm `K → R` với \"K là PK\" | K là *superkey* trong cả 2 đều đúng, nhưng K → R không tự động minimal. | Kiểm tra minimal: bỏ 1 attr ra K thì closure có còn = R không? |\n| Tính X⁺ thiếu vòng lặp | Quên rằng các FD vừa thêm có thể kích hoạt FD mới. | Lặp đến khi X⁺ không đổi (Algorithm 16.1). |\n| Nhầm \"BCNF tốt nhất\" → luôn ép lên BCNF | BCNF có thể mất dependency preservation (TEACH). | Cân nhắc giữa 3NF + giữ FD vs BCNF + có thể mất FD. |\n| Áp dụng NJB cho phân rã >2 quan hệ | NJB chỉ cho **binary**. | Với >2 quan hệ dùng \"chase algorithm\" hoặc kiểm tra từng cặp binary. |\n| Quên Decomposition rule khi áp Minimal Cover | RHS không đơn → Algorithm 16.2 không chạy đúng. | Bước 1 luôn là tách RHS thành đơn attribute. |\n| Phân rã 1NF cho multivalued nhưng quên mở rộng PK | PK cũ không còn unique sau khi nhân dòng. | PK mới = PK cũ ∪ multivalued attribute (hoặc tách bảng riêng). |\n\n---\n\n","file":"materials/DB-Chapter7.md","section":12},{"id":"c7-13","group":"c7","kind":"source","title":"Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\nĐây là chương **đinh** của môn — kỳ thi cuối kỳ HCMUT hầu như luôn có:\n\n1. **Tính X⁺ (Closure):** Cho R + F, tính X⁺. Trình bày từng bước áp FD.\n2. **Tìm Candidate Key:** Dùng Algorithm 2 (phân loại U_l/U_r/U_b).\n3. **Minimal Cover:** Tách RHS → rút LHS → bỏ FD thừa.\n4. **Kiểm NF + Phân rã:** Cho R, F. (a) R ở NF nào? (b) Phân rã đến 3NF/BCNF.\n5. **Equivalence của 2 tập FD:** Tính X⁺ cho mỗi FD bên kia.\n6. **NJB test:** Phân rã {R1, R2} của R + F. Lossless?\n7. **Lý thuyết:** 3 anomaly, partial vs transitive, 3NF vs BCNF (TEACH).\n\n**Mẹo làm bài tự luận normalization:**\n1. Tìm **tất cả** candidate key TRƯỚC khi xét NF.\n2. Xác định prime/nonprime.\n3. Duyệt từng FD trong F, áp định nghĩa NF *general*:\n   - 2NF: FD có LHS là *thật sự một phần* CK + RHS có nonprime?\n   - 3NF: FD có LHS *không phải* superkey *và* RHS có nonprime?\n   - BCNF: FD có LHS *không phải* superkey?\n4. Mỗi FD vi phạm → tách (LHS + RHS) thành quan hệ con.\n5. Giữ một quan hệ chứa CK gốc làm \"trục\".\n\n---\n\n","file":"materials/DB-Chapter7.md","section":13},{"id":"c7-14","group":"c7","kind":"source","title":"Bài Tập Tự Luyện (Có Lời Giải)","markdown":"## Bài Tập Tự Luyện (Có Lời Giải)\n\n> **Bài 1 (Dễ — Tính closure):** Cho R(A, B, C, D) với F = {A → B, B → C, C → D}. Tính {A}⁺ và xác định {A} có là CK của R không.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> Áp Algorithm 16.1:\n> - Start: {A}\n> - A → B: thêm B → {A, B}\n> - B → C: thêm C → {A, B, C}\n> - C → D: thêm D → {A, B, C, D} = R ✓\n>\n> **{A}⁺ = R** → {A} là superkey. Vì A là 1 attribute đơn → không thể giảm bớt → {A} là **candidate key**.\n> </details>\n\n> **Bài 2 (Trung bình — Tìm minimal cover):** Cho F = {AB → CD, A → C, B → D, AB → E}. Tìm minimal cover.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **Bước 1 — Tách RHS:**\n> - AB → C, AB → D, A → C, B → D, AB → E.\n>\n> **Bước 2 — Rút LHS:**\n> - `AB → C`: thử bỏ A → `B → C`? Tính {B}⁺ theo tập trừ {AB → C} = {A→C, B→D, AB→E}: {B}⁺ = {B, D}. Không có C → không thay được.\n> - Thử bỏ B → `A → C`? {A}⁺ = {A, C} — đã có A → C trong F! Vậy `AB → C` thừa (suy ra từ A → C augment).\n> - `AB → D`: thử bỏ A → `B → D`? Đã có B → D. Vậy AB → D thừa.\n> - `AB → E`: cần giữ vì không có cách khác sinh E.\n>\n> **Bước 3 — Bỏ FD thừa:**\n> - AB → C: thừa (do A → C).\n> - AB → D: thừa (do B → D).\n>\n> **Kết quả:** `F_min = { A → C, B → D, AB → E }`.\n> </details>\n\n> **Bài 3 (Trung bình — Kiểm tra NF + Phân rã):** Cho `STUDENT_COURSE(StudentID, StudentName, CourseID, CourseName, Grade)` với:\n> - StudentID → StudentName\n> - CourseID → CourseName\n> - {StudentID, CourseID} → Grade\n>\n> Đây là NF nào? Phân rã đến 3NF.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **Tìm CK:** {StudentID, CourseID}⁺ phủ tất cả → CK duy nhất.\n> **Prime:** StudentID, CourseID. **Nonprime:** StudentName, CourseName, Grade.\n>\n> **Kiểm 2NF:**\n> - `StudentID → StudentName`: StudentName nonprime phụ thuộc một phần PK → **vi phạm**.\n> - `CourseID → CourseName`: tương tự vi phạm.\n>\n> → Đang ở **1NF**.\n>\n> **Phân rã 2NF/3NF:**\n> - `STUDENT(StudentID, StudentName)`\n> - `COURSE(CourseID, CourseName)`\n> - `ENROLLMENT(StudentID, CourseID, Grade)`\n>\n> Mỗi quan hệ đạt 3NF (và BCNF).\n> </details>\n\n> **Bài 4 (Khó — BCNF với mất FD):** Cho R(A, B, C) với F = {AB → C, C → B}. Kiểm tra 3NF, BCNF. Nếu vi phạm BCNF, phân rã + nhận xét về dependency preservation.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **Tìm CK:**\n> - {AB}⁺ = {A, B, C} = R ✓ → **{AB} là CK**.\n> - {AC}⁺: C → B nên + B = {A, B, C} = R ✓ → **{AC} là CK**.\n>\n> **Prime:** A, B, C (đều thuộc một CK). **Nonprime:** không có.\n>\n> **3NF:** Mọi RHS đều là prime → **đạt 3NF**.\n>\n> **BCNF:**\n> - AB → C: AB là superkey → OK.\n> - C → B: C có superkey không? {C}⁺ = {C, B} ≠ R → KHÔNG → **vi phạm BCNF**.\n>\n> **Phân rã BCNF (theo Algorithm 16.5):**\n> - Tách C → B: R1(A, C), R2(C, B).\n>\n> **Nhận xét dependency preservation:**\n> - R1: chứa A, C — không có FD trong F nào nằm gọn trong R1.\n> - R2: chứa C, B — chứa C → B ✓.\n> - **FD `AB → C` BỊ MẤT** — không nằm gọn trong R1 hay R2.\n>\n> Đây là ví dụ kinh điển: BCNF đạt được nhưng mất FD. Designer có thể chọn giữ R ở 3NF để bảo toàn AB → C.\n> </details>\n\n> **Bài 5 (Khó — Tổng hợp):** Cho R(A, B, C, D, E) với F = {A → BC, CD → E, B → D, E → A}. (a) Tìm tất cả CK. (b) R ở NF nào? (c) Phân rã đến BCNF nếu cần.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> **(a) Tìm CK:**\n> - LHS: {A, B, C, D, E}; RHS: {B, C, D, E, A}\n> - U_l = ∅; U_r = ∅; U_b = {A, B, C, D, E} (tất cả ở cả 2 vế).\n> - Phải thử subset của U_b.\n> - {A}⁺: A→BC, B→D, CD→E → {A,B,C,D,E} = R ✓ → **{A} CK**.\n> - {B}⁺: B→D — chỉ {B, D}. Không phủ.\n> - {C}⁺: chỉ {C}. Không phủ.\n> - {D}⁺: chỉ {D}.\n> - {E}⁺: E→A, A→BC, B→D → R ✓ → **{E} CK**.\n> - {B, C}⁺: B→D, CD→E, E→A → R ✓ → **{BC} CK**.\n> - Các superset của {A}, {E}, {BC} không cần check.\n>\n> **Candidate keys:** {A}, {E}, {BC}.\n>\n> **(b) Prime:** A, B, C, E. **Nonprime:** D.\n>\n> **2NF (general):** Nonprime D có phụ thuộc một phần của CK nào không?\n> - {BC} là composite CK. B → D — D phụ thuộc một phần {BC} → **vi phạm 2NF general**.\n>\n> → R ở **1NF**.\n>\n> **(c) Phân rã 2NF/3NF/BCNF:**\n> Áp Algorithm 16.5. FD vi phạm BCNF: tất cả FD có LHS không phải superkey trong R sau phân rã.\n> Một cách phân rã hợp lý:\n> - R1(B, D) — chứa B → D\n> - R2(C, D, E) — chứa CD → E\n> - R3(A, B, C) — chứa A → BC\n> - R4(E, A) — chứa E → A (có thể gộp vào R3 nếu giữ A là CK)\n>\n> Kiểm tra BCNF cho mỗi: trong R1 B là key; trong R2 CD là key; v.v. Sinh viên kiểm tra chi tiết.\n> </details>\n\n---\n\n","file":"materials/DB-Chapter7.md","section":14},{"id":"c7-15","group":"c7","kind":"source","title":"Câu Hỏi Ôn Tập (từ slide gốc)","markdown":"## Câu Hỏi Ôn Tập (từ slide gốc)\n\n1. R(A, B, C, D, E) với AB → C, CD → E, DE → B. Tính {A,B}⁺, {A,B,D}⁺. *(Slide 38)*\n2. E = {B → A, D → A, AB → D}. Minimal cover. *(Slide 45)*\n3. Homework: E = {A → B, ABCD → I, IJ → G, IJ → H, ACDJ → GI}. Minimal cover. *(Slide 46)*\n4. R = {A, B, C, D, E, F}, ABC → EF, B → E, E → D. Key + 2NF/3NF/BCNF. *(Slide 90)*\n5. R = {A..J}, 5 FD. Key + 2NF/3NF. *(Slide 91)*\n6. R = {A..F}, 5 FD. Key + 2NF/3NF. *(Slide 92)*\n7. R = {A..F}, 3 FD. Key + 2NF/3NF/BCNF. *(Slide 93)*\n8. BOOK relation. NF hiện tại + phân rã. *(Slide 94)*\n9. BOOK(Book_Name, Author, Edition, Year). Possible candidate keys. *(Slide 95)*\n\n---\n\n","file":"materials/DB-Chapter7.md","section":15},{"id":"c7-16","group":"c7","kind":"source","title":"Đáp án Tự kiểm tra","markdown":"## Đáp án Tự kiểm tra\n\n### Section 1\n1. *Modification:* đổi manager phòng Research từ SSN1 → SSN2 phải update Dmgr_ssn ở 4 tuple Smith/Wong/Narayan/English. *Insertion:* không thể thêm phòng \"R&D\" chưa có nhân viên vì SSN sẽ NULL (PK không cho NULL). *Deletion:* xóa Borg → mất luôn thông tin phòng Headquarters (tên + manager).\n2. Non-additive join đảm bảo dữ liệu khôi phục đúng — nếu mất, JOIN tạo dữ liệu RÁC (spurious). Dependency preservation chỉ ảnh hưởng việc kiểm tra ràng buộc (có thể kiểm qua JOIN dù tốn hơn). Dữ liệu sai là không cứu được.\n3. Sẽ sinh **spurious tuples** — tuple không tồn tại trong mini-world, do JOIN nhân chéo các tuple có cùng giá trị cột chung mà cột đó không phải PK/FK.\n\n### Section 2\n1. Direct: Ssn → Name, Ssn → Salary, Ssn → DNO. Transitive: không (vì PK đơn và chỉ 1 mức). Partial: không (PK đơn).\n2. `Salary → Ssn` không hợp lệ — 2 nhân viên có thể cùng lương nhưng khác SSN. Lương không xác định người.\n3. Composite determinant = *vế trái* gồm nhiều attribute. Partial dependency = tình huống *RHS chỉ phụ thuộc một phần* composite determinant đó.\n\n### Section 3\n1. IR1: Y ⊆ X thì X xác định Y (hiển nhiên). IR2: nếu X xác định Y, thêm Z vào 2 vế FD vẫn đúng. IR3: X→Y, Y→Z thì X→Z.\n2. {A}⁺ = {A, B, C} (qua A→B→C). {B}⁺ = {B, C, A}. {C}⁺ = {C, A, B}. Cả 3 = R → cả 3 là candidate keys (chu trình FD).\n3. X là superkey. Để X là candidate key: không subset thực sự nào của X có closure = R.\n\n### Section 4\n1. F covers G và G covers F.\n2. Không minimal — `A → C` suy ra từ `A → B` + `B → C` (transitive). Bỏ `A → C` vẫn equivalent.\n3. RHS đơn cho phép kiểm tra điều kiện 2 và 3 độc lập trên từng cặp (LHS, RHS_atomic).\n\n### Section 5\n1. Attribute \"right only\" được xác định bởi attr khác → trong closure của bất kỳ tập có thể tạo ra nó, ta thêm được nó → A không cần đứng trong key. Nếu A trong key, bỏ A ra closure vẫn = R → A thừa.\n2. Bước 2 đã loại bỏ tối đa: mọi attribute còn lại \"không bỏ được\" (bỏ thì closure không còn = R) → K minimal → candidate key.\n3. R(A, B, C, D) với A→B→C→D. {A}⁺ = R → {A} là CK duy nhất (vì A → tất cả qua transitive, các attr khác không xác định ngược lại A).\n\n### Section 6\n1. Có vi phạm 3NF. ISBN → AuthorID → AuthorName: AuthorID nonprime, AuthorName nonprime → transitive qua nonprime.\n2. ED1(Ename, **Ssn**, Bdate, Address, Dnumber↑) với Ssn = PK, Dnumber = FK trỏ ED2.Dnumber. ED2(**Dnumber**, Dname, Dmgr_ssn) với Dnumber = PK.\n3. 3NF cho \"A prime\" vì A nằm trong CK → redundancy có giới hạn. BCNF cấm để đảm bảo *không có* lặp do FD ngoài key.\n\n### Section 7\n1. Nếu PK = {Property_id#}, không có composite → không \"một phần PK\" để vi phạm theo PK-based. Nhưng CK thứ hai {County_name, Lot#} composite — Tax_rate chỉ phụ thuộc County_name → vi phạm 2NF general.\n2. Prime trong LOTS: Property_id#, County_name, Lot# (thuộc 1 trong 2 CK).\n3. R ở 3NF nếu với mọi FD đúng trong R, vế trái là superkey *hoặc* vế phải là attribute prime.\n\n### Section 8\n1. TEACH(Student, Course, Instructor) với CK {Student, Course} và {Student, Instructor}. `Instructor → Course`: Instructor không superkey, Course là prime → 3NF OK, BCNF vi phạm.\n2. Khi phân rã BCNF làm mất FD quan trọng (như TEACH mất {Student, Course} → Instructor) và việc kiểm tra FD đó qua JOIN tốn kém. Designer giữ 3NF để dependency preservation.\n3. Với D = {R1, R2}, lossless ⟺ giao R1 ∩ R2 phải xác định *ít nhất một* trong 2 phần riêng (R1 − R2 hoặc R2 − R1). Lý do: giao là \"khóa nối\" — nếu nó xác định 1 bên, JOIN ta khôi phục đúng; nếu không, JOIN sinh spurious.\n\n---\n\n","file":"materials/DB-Chapter7.md","section":16},{"id":"c7-17","group":"c7","kind":"source","title":"Mối Quan Hệ Với Các Chương Khác","markdown":"## Mối Quan Hệ Với Các Chương Khác\n\n- **Chương trước (Chương 6 — SQL):** Bạn học SQL để CRUD dữ liệu. Chương 7 đảm bảo schema bạn CRUD \"tốt\" — tránh anomaly khi UPDATE/INSERT/DELETE.\n- **Chương sau (Chương 8 — Data Storage & Indexing):** Sau khi schema chuẩn hóa, chọn index/file organization phù hợp. Normalization giảm dữ liệu, index tăng tốc query. **Schema tốt trước, index sau.**\n- **Liên hệ chương 4 (Relational Mapping):** Chương 4 cho schema ban đầu từ ER. Chương 7 là \"lớp tinh chỉnh\".\n- **Liên hệ chương 5 (Relational Algebra):** Phép JOIN, PROJECTION dùng để mô tả nonadditive join và phân rã.\n\n### Liên kết Lab / BTL\n\n- **Lab 1 (`Labs/Lab 1.docx`):** Thực hành ER + mapping → cần kiểm tra schema mapping ở 3NF/BCNF.\n- **Lab 2 (`Labs/Lab 2.docx`):** SQL nâng cao — schema chuẩn hóa giúp JOIN đúng (không spurious).\n- **BTL1 (`BTL1_DB_Lab/`):** Yêu cầu vẽ ER/EER + relational schema. Normalization thường được yêu cầu chứng minh schema cuối là 3NF/BCNF.\n- **BTL2 (`BTL2_DB_Lab/`):** Implementation — schema phải ổn định, không anomaly khi nhiều người dùng đồng thời.\n- **Exercises (`Exercises/6_Exercise_SQL.docx`):** SQL exercise dùng schema chuẩn hóa.\n\n---\n\n> ✅ **Đã merge từ 2 nguồn:** Bản A (Claude pass1 — pedagogical depth, exercises chi tiết) + Bản B (ChatGPT-style notes — SQL templates, Mermaid diagram, slide transcript references).\n> ✅ **Đã thêm:** Bảng tra nhanh, Sai lầm thường gặp, 5 bài tập tự luyện có lời giải collapsible, liên kết Lab/BTL.\n> ✅ **Mục tiêu vàng:** Sinh viên năm 2 chưa từng học CSDL đọc bản này một mạch là hiểu được toàn bộ chương 7 — KHÔNG cần mở slide gốc, KHÔNG cần đọc Elmasri.\n","file":"materials/DB-Chapter7.md","section":17},{"id":"guide-7","group":"c7","kind":"guide","title":"FD & Chuẩn hóa","markdown":"# 07 · FD và chuẩn hóa: tính trước, kết luận sau\n\n> Đọc cùng **DB-Chapter7.md**. Công cụ **Bao đóng & khóa** cho phép quan sát từng vòng suy diễn; kết quả máy chỉ hỗ trợ lập luận.\n\n![Bao đóng và chuẩn hóa từng bước](../docs/assets/normalization.svg)\n\n## FD là ràng buộc của mọi state hợp lệ\n\n`A → B` nghĩa là hai tuple có cùng A thì bắt buộc cùng B. Một bảng hiện tại tình cờ không lặp A chưa đủ chứng minh nghiệp vụ có FD đó. Ngược lại, chỉ cần hai hàng cùng A nhưng khác B là một phản ví dụ bác bỏ FD trên state đang xét.\n\nBa luật Armstrong: reflexivity (`Y⊆X ⇒ X→Y`), augmentation (`X→Y ⇒ XZ→YZ`) và transitivity (`X→Y, Y→Z ⇒ X→Z`). **Full dependency** có nghĩa không thể bỏ bớt thuộc tính vế trái mà vẫn xác định vế phải; không đồng nghĩa tuyệt đối với “direct dependency”.\n\n## Ví dụ tính bao đóng có đủ từng vòng\n\nCho `R(A,B,C,D,E)` và `F={A→BC, B→D, CD→E}`.\n\n| Vòng | FD dùng | Tập đang biết |\n|---|---|---|\n| 0 | Khởi tạo A | A |\n| 1 | A→BC | ABC |\n| 2 | B→D | ABCD |\n| 3 | CD→E | ABCDE |\n| 4 | Không thêm gì | Dừng |\n\nA xác định toàn R, nên là superkey. A là một thuộc tính và rỗng không xác định được toàn R, nên A là candidate key. Không có FD nào sinh A, vì vậy mọi key phải chứa A: A là candidate key duy nhất.\n\nChú ý “minimal key” là tối thiểu theo **bao hàm**, không phải chỉ chọn những key có số thuộc tính ít nhất. Có thể đồng thời tồn tại một candidate key một thuộc tính và một candidate key hai thuộc tính.\n\n## Minimal cover phải kiểm tra tương đương\n\nCho `F={A→BC, B→C, A→B, AB→C}`. Tách RHS thành từng thuộc tính. Loại bản sao A→B. `A→C` suy được qua A→B và B→C nên có thể bỏ. AB→C cũng dư vì B→C. Một minimal cover là `{A→B, B→C}`. Trình tự giản lược khác có thể tạo biểu diễn khác; tiêu chí là tương đương, không phải giống từng dòng đáp án.\n\n## Định nghĩa chuẩn để tránh học mẹo sai\n\n| Dạng chuẩn | Điều kiện chính xác dùng khi làm bài FD |\n|---|---|\n| 1NF | Mỗi ô nhận một giá trị thuộc miền đã chọn; không nhóm lặp/nested relation trong mô hình đang xét |\n| 2NF | 1NF; không nonprime attribute phụ thuộc vào proper subset của bất kỳ candidate key nào |\n| 3NF | Mỗi FD không tầm thường `X→a` trong F⁺: X là superkey **hoặc** a là prime |\n| BCNF | Mỗi FD không tầm thường `X→a` trong F⁺: X là superkey |\n\nMột thuộc tính prime nếu thuộc **ít nhất một** candidate key. “Khóa chính chỉ có một cột nên tự động 2NF” không an toàn nếu còn candidate key ghép khác. Mọi key đều phải được xét.\n\n## 3NF nhưng không BCNF: TEACH\n\n`R(Student,Course,Instructor)`, FD `{Student,Course}→Instructor`, `Instructor→Course`. Hai candidate key là `{Student,Course}` và `{Student,Instructor}`; cả ba thuộc tính đều prime. Instructor không là superkey nhưng Course prime, nên FD thứ hai thỏa 3NF và vi phạm BCNF.\n\nPhân rã `R1(Instructor,Course)`, `R2(Student,Instructor)`. Giao là Instructor và Instructor→R1, nên **lossless**. Nhưng ràng buộc mỗi cặp Student–Course chỉ có một Instructor không còn kiểm tra riêng trong từng bảng: có thể mất **dependency preservation**.\n\nKhông viết “mọi decomposition thành BCNF đều lossless”. **Thuật toán phân rã BCNF chuẩn** bảo đảm lossless; việc tùy ý cắt bảng rồi thấy mỗi bảng BCNF không chứng minh phép join khôi phục đúng.\n\n## Ví dụ phân rã thật từ FD ban đầu\n\nVới `R(A,B,C,D,E)` phía trên, chọn B→D để tách `BD` và `ABCE`. Trong ABCE có BC→E (do B→D và CD→E), nên tách `BCE` và `ABC`. Trong ABC, A→BC nên A là key. BD và BCE có B, BC là key tương ứng. Ba bảng đều BCNF và mỗi bước là lossless. Đây là một phương án; khi cần bảo toàn FD, phải kiểm riêng chứ không kết luận từ BCNF.\n\n## Bài tập\n\n1. Với `R(A,B,C)` và `F={A→B,B→A}`, tìm mọi candidate key.\n2. `R1(AB),R2(BC)` có luôn lossless không?\n3. FD tầm thường có làm vi phạm BCNF không?\n\n<details><summary>Lời giải</summary>\n\n1. AC và BC. C không nằm RHS nên bắt buộc có trong key; thêm A hoặc B sẽ xác định thuộc tính còn lại.\n2. Không. Cần `(R1∩R2)→R1` hoặc `→R2` suy được từ F, tức B→A hoặc B→C trong ví dụ.\n3. Không. Định nghĩa xét FD **không tầm thường**. Nếu quên điều kiện này, A→A có thể dẫn đến kết luận sai.\n\n</details>\n","file":"lessons/07-normalization.md"},{"id":"c8-00","group":"c8","kind":"source","title":"Chương 8: Lưu Trữ Dữ Liệu và Cấu Trúc Chỉ Mục cho Tập Tin — Data Storage and Indexing Structures for Files","markdown":"# Chương 8: Lưu Trữ Dữ Liệu và Cấu Trúc Chỉ Mục cho Tập Tin — Data Storage and Indexing Structures for Files\n\n> Nguồn: CO2013 Database Systems, HCMUT — Giảng viên: TS. Trần Minh Quang\n> Giáo trình: Elmasri & Navathe, 7th Edition (Chương 16, 17, 18 — Disk Storage, File Organizations, Indexing)\n> Số trang PDF gốc: **89 trang** (số slide hiển thị tới 96 — các slide đáp án 86, 87, 88, 90, 92, 94 không có trong PDF)\n> Đã gộp slide \"Contents\" lặp lại: slide 3, 4, 11, 18, 21, 31, 44, 49, 72, 78, 84 — tất cả đều là slide mục lục, chỉ khác phần highlight section đang vào → gộp thành **một** mục lục duy nhất ở section 0.3.\n\n---\n\n","file":"materials/DB-Chapter8.md","section":0},{"id":"c8-01","group":"c8","kind":"source","title":"0. Trước khi bắt đầu","markdown":"## 0. Trước khi bắt đầu\n\n### 0.1. Bạn cần biết gì trước? (Prerequisite)\n\nChương 8 là chương **\"chui xuống dưới mui xe\"** của hệ CSDL — từ tầng quan hệ trừu tượng xuống tầng vật lý thật. Các kiến thức cần \"nhớ lại\":\n\n| Đã học từ | Concept | Chương này dùng để làm gì? |\n|---|---|---|\n| Cấu trúc dữ liệu | Binary Search Tree, độ cao log₂(n) | Tổng quát hoá thành B-tree, B+-tree. |\n| Cấu trúc dữ liệu | Hash Table | Chương này gọi là *external hashing* khi áp dụng cho file trên đĩa. |\n| Cấu trúc dữ liệu | Linear vs Binary search | Chi phí O(n) vs O(log₂ n) — đo bằng \"số block accesses\". |\n| Hệ điều hành | Block, Buffer | HĐH đọc/ghi đĩa theo *khối*, không theo byte. |\n| Hệ điều hành | File system | File = chuỗi byte/record trên đĩa. |\n| Chương 4 (Relational) | Primary Key, Foreign Key | Vẫn là trục để lập chỉ mục — Ssn, Dnumber. |\n| Chương 6 (SQL) | `CREATE INDEX`, `SELECT ... WHERE` | Chương 8 trả lời \"DBMS làm gì phía dưới câu SQL đó\". |\n| Chương 7 (FD & Normalization) | Decomposition, BCNF | Chuẩn hoá tốt → ít redundancy → cần index để JOIN nhanh. |\n\n> 💡 **Big picture:** Quy trình thiết kế CSDL chia 2 nhánh — **Application Design** (Functional Analysis → App Program Design → Transaction Implementation) và **Database Design** (Conceptual ER → Logical mapping → **Physical Design**). Chương 1–7 đi từ Conceptual đến Logical. **Chương 8 chính là PHYSICAL DESIGN** — tầng cuối trước khi xuống đĩa thật.\n\n```mermaid\nflowchart TD\n    A[Miniworld] --> B[Requirements - Collection & Analysis]\n    B --> C[Data requirements]\n    B --> D[Functional requirements]\n    C --> E[CONCEPTUAL DESIGN]\n    E --> F[Conceptual schema]\n    F --> G[LOGICAL DESIGN<br/>Data Model Mapping]\n    G --> H[Database schema]\n    H --> I[\"⭐ PHYSICAL DESIGN<br/>(Chương 8)\"]\n    I --> J[Internal schema]\n    D --> K[FUNCTIONAL ANALYSIS]\n    K --> L[High-level transaction spec]\n    L --> M[APPLICATION PROGRAM DESIGN]\n    M --> N[TRANSACTION IMPLEMENTATION]\n    N --> O[Application program]\n    H -.-> M\n    L -.-> I\n```\n\n### 0.2. Sau chương này bạn sẽ làm được gì? (Learning Outcomes)\n\n1. **Mô tả** kiến trúc đĩa cứng: track, sector, cylinder, block, read/write head, seek time, rotational delay, double buffering.\n2. **Tính** record size `R`, blocking factor `bfr`, số khối file `b` cho file fixed-length records (unspanned/spanned).\n3. **So sánh** 3 loại file organization: Heap (unordered), Sorted (ordered), Hashed — biết khi nào dùng cái nào.\n4. **Phân biệt** Primary / Clustering / Secondary Index: số entry, dense vs sparse, có dùng block anchor hay không.\n5. **Tính chi phí truy vấn** (số block accesses) khi không/có index — linear search, binary search, index search, multilevel.\n6. **Hiểu** vì sao single-level index không đủ → cần multilevel → cần B-tree/B+-tree.\n7. **Phân biệt** B-tree vs B+-tree về vị trí data pointer và số level.\n8. **Biết** RAID 0–6 khác nhau ở chỗ nào, khi nào dùng RAID nào; khái niệm SAN vs DAS.\n9. **Làm** các bài tập tính disk capacity, block transfer time, index size, block accesses — dạng rất hay ra thi.\n\n### 0.3. Lộ trình đọc đề xuất\n\n| Section | Nội dung | Mức độ | Thời gian |\n|---|---|---|---|\n| 1.1 | Disk Storage Devices | **CORE** | 20 phút |\n| 1.2 | Files of Records (Records, Blocking) | **CORE** | 20 phút |\n| 1.3 | Operations on Files | Nhẹ | 10 phút |\n| 1.4 | Unordered / Ordered / Hashed Files | **CORE** | 40 phút |\n| 1.5 | RAID & SAN | Nâng cao (hay ra trắc nghiệm) | 25 phút |\n| 2.1 | Single-level Ordered Indexes (Primary / Clustering / Secondary) | **CORE — TRỌNG TÂM THI** | 60 phút |\n| 2.2 | Multilevel Indexes | **CORE** | 25 phút |\n| 2.3 | B-Trees & B+-Trees | **CORE — TRỌNG TÂM THI** | 40 phút |\n| Bài tập | Tính bfr, b, block accesses, multilevel, disk timing | **BẮT BUỘC LUYỆN** | 60 phút |\n\n> **Mục lục gốc từ slide (gộp 11 slide Contents):**\n> 1. **Data Storage**\n>    - 1.1 Disk Storage Devices\n>    - 1.2 Files of Records\n>    - 1.3 Operations on Files\n>    - 1.4 Unordered Files & Ordered Files & Hashed Files\n>    - 1.5 RAID Technology and Storage Area Networks\n> 2. **Indexing Structures for Files**\n>    - 2.1 Types of Single-level Ordered Indexes\n>    - 2.2 Multilevel Indexes\n>    - 2.3 Dynamic Multilevel Indexes Using B-Trees and B+-Trees\n\n---\n\n","file":"materials/DB-Chapter8.md","section":1},{"id":"c8-02","group":"c8","kind":"source","title":"1. Data Storage — Lưu Trữ Dữ Liệu","markdown":"## 1. Data Storage — Lưu Trữ Dữ Liệu\n\n### 1.0. Motivation tổng — Vì sao có cả section 1?\n\nĐến chương 7 bạn đã biết: database COMPANY gồm các quan hệ EMPLOYEE, DEPARTMENT… nhưng *chúng nằm ở đâu* trong máy tính thật?\n\n- **Không thể** giữ toàn bộ DB trong RAM: 100k nhân viên ≈ GB; ngân hàng/Facebook tới TB → PB. RAM tỉ byte không đủ và quá đắt.\n- **Phải** lưu xuống **secondary storage** (HDD/SSD): dung lượng lớn, giá rẻ, **persistent** (không mất khi mất điện).\n- Nhưng đĩa **chậm hơn RAM ~10⁵ lần** → mọi công thức trong chương này đo bằng \"số block đọc đĩa\", không phải CPU cycle.\n\n> 💡 **Analogy xuyên chương:** Database = một **thư viện** khổng lồ.\n> - Sách = records. Kệ = blocks. Phòng/dãy kệ = file. Bảng tin = index.\n> - Bạn không ôm hết sách (RAM giới hạn) — lấy 1 kệ vào bàn (load block vào buffer), đọc xong trả lại.\n\n---\n\n### 1.1. Disk Storage Devices — Thiết Bị Lưu Trữ Đĩa (Slide 5–10)\n\n#### 1.1.1. Khái niệm gốc\n\nĐĩa cứng (magnetic disk) là **secondary storage device** được ưa thích nhờ:\n- **Dung lượng cao** (GB → TB).\n- **Giá rẻ** trên mỗi GB.\n- **Persistent** (giữ data khi mất điện).\n\n**Cách dữ liệu được lưu vật lý:**\n- Data lưu dưới dạng **magnetized areas** (vùng từ hoá) trên **disk surface**.\n- Một **disk pack** = nhiều magnetic disk gắn chung 1 *spindle* (trục) quay.\n- Mỗi mặt đĩa chia thành các vòng tròn đồng tâm gọi là **track**.\n  - **Track capacity** điển hình: 4 – 50 KB.\n\n#### 1.1.2. Anatomy của disk pack (Slide 6)\n\n> 📊 **Hình 1.1 — Anatomy ổ đĩa:**\n> ```\n> (a) Single disk:                  (b) Disk pack:\n>      Track                            Spindle (trục)\n>       │                                  │\n>       ▼                              ════╪════ ← surface 0\n>     ╭─────╮                          ────│──── ← surface 1\n>    ╱       ╲ ← Read/write head       ════╪════ ← surface 2\n>   │    ●    │ <── Arm                ────│──── ← ...\n>    ╲       ╱                              ▲\n>     ╰─────╯                         Actuator movement\n>        ▲                            ← một \"Cylinder\" = tập các\n>    Actuator                            track CÙNG bán kính trên\n>                                        TẤT CẢ các mặt\n> ```\n\n> 📊 **Đọc diagram thế nào:**\n> - **Track**: 1 vòng tròn đồng tâm trên 1 mặt đĩa.\n> - **Read/write head**: đầu đọc/ghi — mỗi mặt đĩa có 1 head riêng.\n> - **Arm**: cánh tay giữ head; tất cả arm di chuyển *đồng bộ* khi actuator dịch ra/vào.\n> - **Spindle**: trục quay chung của tất cả các mặt đĩa.\n> - **Cylinder**: KHÔNG phải vật lý — là tập tất cả track *cùng bán kính* trên các mặt khác nhau. Vì head di chuyển đồng bộ → đọc nguyên cylinder không tốn seek thêm.\n\n#### 1.1.3. Sector và Block (Slide 7–9)\n\nMột track được chia thành các phần nhỏ gọi là **sector** (cung) hoặc **block** (khối).\n\n| Thuật ngữ | Tính chất | Giá trị điển hình |\n|---|---|---|\n| **Sector** | Cung vật lý của track | — |\n| **Block** | Đơn vị transfer giữa đĩa và RAM | B = 512 – 4096 bytes |\n| **Block size B** | Cố định cho mỗi hệ thống | 512 / 1024 / 4096 B |\n\n**Toàn bộ block** được transfer giữa đĩa và main memory — không đọc theo byte, không đọc theo record, mà luôn theo **block nguyên**.\n\n> 💡 **Hiểu đơn giản:** Block giống **hộp pizza 8 miếng**: muốn 1 miếng vẫn phải gọi cả hộp. CSDL cũng vậy — muốn đọc 1 record vẫn phải tải nguyên block chứa nó.\n\n#### 1.1.4. Địa chỉ block vật lý và thời gian truy cập (Slide 10)\n\n**Địa chỉ block vật lý** gồm 3 thành phần:\n1. **Cylinder number** (tập các track cùng bán kính).\n2. **Track number** / **surface number** trong cylinder.\n3. **Block number** trong track.\n\nĐọc/ghi 1 block tốn thời gian vì phải đợi:\n| Đại lượng | Ý nghĩa | Điển hình HDD |\n|---|---|---|\n| **Seek time s** | Dịch arm tới đúng cylinder | ~30 ms |\n| **Rotational delay rd** | Đợi block quay đến dưới head | 4–12 ms (tuỳ rpm) |\n| **Block transfer time btt** | Truyền thật 1 block | 0.1–1.25 ms |\n\n**Double buffering** — dùng 2 buffer xen kẽ để tăng tốc transfer các block kề nhau (đọc block A xong, vừa xử lý A vừa preload block B).\n\n> 💡 **Analogy seek + rotational delay:** Bạn muốn nghe bài 7 trong CD. Phải (1) bấm \"track 7\" → đầu đọc dịch tới (**seek**); (2) đợi CD quay tới 0:00 (**rotational delay**); (3) bắt đầu phát (**transfer**). Nghe liên tiếp track 8 sau track 7 → không seek, không đợi quay → tinh thần *double buffering*.\n\n> 📝 **Tóm lại 1.1 — Disk Storage Devices:**\n> - Đĩa cứng = nhiều disk pack quay chung 1 spindle; mỗi mặt chia thành track; mỗi track chia thành block (B = 512–4096 B).\n> - Cylinder = các track cùng bán kính → đọc cùng cylinder không tốn seek thêm.\n> - Đọc/ghi luôn theo BLOCK NGUYÊN.\n> - Chi phí 1 lần truy cập block = seek + rotational delay + transfer.\n> - **Một câu ghi nhớ:** *Đĩa cứng = ổ pizza quay; muốn ăn miếng nào cũng phải gọi cả hộp về bàn.*\n\n> ❓ **Tự kiểm tra 1.1 (3 câu):**\n> 1. Phân biệt **track**, **sector**, **block**, **cylinder**. Cái nào là vật lý, cái nào là ảo?\n> 2. Vì sao block size B được fix cứng chứ không cho user chọn tự do?\n> 3. File COMPANY 1000 block xếp liên tục cùng 1 cylinder vs rải rác 100 cylinder — cái nào đọc nhanh hơn?\n\n---\n\n### 1.2. Files of Records — Tập Tin của các Bản Ghi (Slide 12–17)\n\n#### 1.2.1. Motivation\n\nQuan hệ EMPLOYEE có 30,000 dòng, mỗi dòng ~150 byte. Câu hỏi tự nhiên:\n- 30,000 dòng đó nhồi vào block thế nào?\n- Mỗi dòng có format gì để biết Fname đến đâu, Salary đến đâu?\n- Nếu một dòng dài hơn 1 block thì sao?\n\n#### 1.2.2. Records (Slide 12–13)\n\n- **Fixed-length records** vs **Variable-length records**.\n- Record chứa các **field** (trường) — mỗi field có *value* thuộc 1 *kiểu* (amount, date, time, age, …).\n- Field bản thân có thể *fixed* (Sex 1 byte, Birth_date 8 byte) hoặc *variable* (Address 10–100 byte).\n- Mix variable-length field → cần **separator character** hoặc **length field** để hệ thống parse được record.\n\n> 📊 **Hình 1.3 — Ba dạng record (Slide 13):**\n> ```\n> (a) Fixed-length, 6 field, 71 byte:\n>     │  Name (30) │Ssn(9)│Sal(4)│Job(4)│Department(20)│Hire_dt│\n>     byte 1       31     40     44     48              68     71\n>\n> (b) Mixed (2 variable + 3 fixed):\n>     │Smith,John │123456789│XXXX│XXXX│Computer       │\n>      Name(var)   Ssn(fix)  Sal  Job  Dept(var)\n>\n> (c) Fully variable, self-describing với 3 separator:\n>     │Name=Smith,John│Ssn=123456789│DEPARTMENT=Computer│X│\n>      `=`: tên field=giá trị;  `▌`: ngăn cách field;  `X`: kết record\n> ```\n\n> 📊 **Đọc thế nào:** Dạng (a) parse cực nhanh nhưng lãng phí (Lê vẫn ăn 30 byte). (b) tiết kiệm chỗ nhưng tốn separator. (c) self-describing như JSON/XML, tốn nhất nhưng không cần biết schema trước.\n\n#### 1.2.3. Blocking và Spanned Records (Slide 14–15)\n\n| Thuật ngữ (EN) | Tiếng Việt | Định nghĩa |\n|---|---|---|\n| **Blocking** | Việc gộp khối | Lưu một số record trong cùng 1 block trên đĩa. |\n| **Blocking factor (bfr)** | Hệ số khối | Số record trên mỗi block. |\n| **Spanned record** | Bản ghi vắt khối | Record vượt 1 block → trải qua nhiều block. |\n| **Unspanned record** | Bản ghi không vắt | Không record nào vắt qua 2 block. |\n\n> 📊 **Hình 1.4 — Unspanned vs Spanned:**\n> ```\n> (a) Unspanned (3 record vừa khít, dư trống):\n>   Block i  : │ Rec 1 │ Rec 2 │ Rec 3 │░░░│\n>   Block i+1: │ Rec 4 │ Rec 5 │ Rec 6 │░░░│\n>\n> (b) Spanned (Rec 4 vắt qua, P là pointer \"phần còn lại\"):\n>   Block i  : │ Rec 1 │ Rec 2 │ Rec 3 │ Rec 4 │ P │\n>                                                 └──┐\n>   Block i+1: │ Rec 4 (rest) │ Rec 5 │ Rec 6 │ Rec 7 │ P │\n> ```\n\n#### 1.2.4. Files of Records (Slide 16–17)\n\n- Một **file** = *chuỗi record* (sequence of records).\n- **File descriptor / file header**: lưu schema (field names, kiểu) + địa chỉ block của file trên đĩa.\n- Record lưu trong các **disk block**. **bfr** = số record trung bình trên 1 block.\n- Cách cấp phát block: **contiguous** (liên tục) | **linked** (mỗi block trỏ block kế) | **indexed** (1 bảng index riêng nắm danh sách block).\n- File fixed-length → thường *unspanned*. File variable-length → thường *spanned* + cần separator + field type.\n\n#### 1.2.5. Công thức kim chỉ nam (dùng RẤT NHIỀU)\n\nVới file fixed-length, **unspanned**, gọi R = record size, B = block size, r = tổng số record:\n\n$$ \\boxed{\\;bfr = \\lfloor B/R \\rfloor \\quad\\text{và}\\quad b = \\lceil r/bfr \\rceil\\;} $$\n\nVới file **spanned**: bfr ≈ B/R, b ≈ r/bfr (không cần làm tròn).\n\n> 💡 **Hiểu đơn giản:** `⌊ ⌋` = làm tròn xuống (floor): `⌊3.7⌋ = 3` — 4 record không đủ chỗ thì chỉ nhét 3. `⌈ ⌉` = làm tròn lên (ceiling): `⌈3.1⌉ = 4` — phải mở thêm block thứ 4 cho 1 record dư.\n\n> 💡 **Ví dụ 1.1 — EMPLOYEE 30k record:**\n> R=116 byte, B=512 byte, r=30,000, unspanned.\n> - bfr = ⌊512/116⌋ = ⌊4.41⌋ = **4** records/block.\n> - b = ⌈30,000/4⌉ = **7500** blocks.\n> - Mỗi block chứa 4×116=464 byte, dư 48 byte trống.\n\n> 📝 **Tóm lại 1.2:** Record = tập field; file = chuỗi record nhồi vào block; `bfr=⌊B/R⌋`, `b=⌈r/bfr⌉`.\n\n> ❓ **Tự kiểm tra 1.2 (3 câu):**\n> 1. B=1024, R=300, r=10,000, unspanned → bfr, b, % lãng phí mỗi block?\n> 2. Khi nào nên dùng spanned, khi nào unspanned?\n> 3. DEPENDENT có 5000 record, R=60, B=512 → file chiếm bao nhiêu block?\n\n---\n\n### 1.3. Operations on Files (Slide 19–20)\n\n| Operation | Mô tả slide | Liên hệ SQL |\n|---|---|---|\n| **OPEN** | Mở file, gắn 1 *pointer* trỏ tới *current file record* | DBMS mở file khi bắt đầu query |\n| **FIND** | Tìm record đầu tiên thỏa điều kiện X, biến thành current | `SELECT … WHERE …` |\n| **FINDNEXT** | Tìm record kế tiếp thỏa X | Vòng lặp duyệt kết quả |\n| **READ** | Đọc current record vào biến chương trình | Truyền data lên app |\n| **INSERT** | Chèn record mới, biến thành current | `INSERT INTO …` |\n| **DELETE** | Xóa current — thường *đánh dấu* (mark) \"không còn valid\" | `DELETE FROM …` |\n| **MODIFY** | Thay đổi giá trị một số field của current | `UPDATE … SET …` |\n| **CLOSE** | Đóng file | Kết thúc query |\n| **REORGANIZE** | Tổ chức lại: xoá hẳn record marked-deleted, đổi sắp xếp | `VACUUM` của PostgreSQL |\n| **READ_ORDERED** | Đọc block theo thứ tự của 1 field cụ thể | `ORDER BY field` |\n\n> 💡 **Vì sao DELETE chỉ đánh dấu (mark)?** Xóa vật lý ở giữa file → phải dịch chuyển toàn bộ record phía sau → cực đắt. Mark-and-delete chỉ set 1 byte cờ \"deleted=true\"; REORGANIZE định kỳ mới dồn lại. Đó là lý do Exercise slide 40 có dòng *\"An additional byte is used as a deletion marker\"* — chính là cờ này: R = 115 byte data + 1 byte marker = 116 byte.\n\n> 📝 **Tóm lại 1.3:** SQL là ngôn ngữ logic; file operations là việc DBMS thật sự làm dưới disk. DELETE thường là *logical* — record vẫn nằm đó cho đến REORGANIZE.\n\n> ❓ **Tự kiểm tra 1.3 (2 câu):**\n> 1. Vì sao DELETE không xóa record ngay mà chỉ đánh dấu?\n> 2. Phân biệt FIND vs FINDNEXT — khi nào dùng cái nào?\n\n---\n\n### 1.4. Unordered, Ordered, Hashed Files (Slide 22–30)\n\n3 chiến lược tổ chức file cơ bản — *ảnh hưởng trực tiếp đến chi phí truy vấn*:\n1. **Unordered (Heap)** — quăng record vào đâu cũng được.\n2. **Ordered (Sorted/Sequential)** — sắp theo 1 field (Ssn tăng dần).\n3. **Hashed** — dùng h(K) quyết định bucket nào.\n\n#### 1.4.1. Unordered Files / Heap (Slide 22)\n\n- Còn gọi **heap** / **pile** file. Insert record mới vào **cuối file** — chỉ đọc block cuối, thêm, ghi lại.\n- **Linear search** qua toàn bộ record để tìm 1 record: trung bình **b/2 blocks** → rất tốn.\n- Insert cực **efficient**. Đọc theo thứ tự 1 field → phải **sort file lại** trước.\n\n> 💡 **Analogy:** Heap = **đống quần áo trên ghế**: vứt thêm rẻ; tìm chiếc xanh phải bới hết.\n\n#### 1.4.2. Ordered Files / Sequential (Slide 23)\n\n- Record giữ **sorted** theo **ordering field** (vd Ssn).\n- Insert **expensive**: phải chèn đúng vị trí. Workaround: giữ 1 **overflow file** (= *transaction file*) *unordered* riêng cho record mới; **định kỳ merge** với file ordered chính.\n- **Binary search** dùng được trên *ordering field value*: trung bình **log₂(b)** block accesses.\n- Đọc record theo thứ tự ordering field → **rất hiệu quả** (đọc tuần tự).\n\n> 📊 **Hình 1.5 — File EMPLOYEE ordered theo NAME (Slide 24):**\n> ```\n>  block 1: Aaron,Ed → Abbott,Diane → ... → Acosta,Marc\n>  block 2: Adams,John → Adams,Robin → ... → Akers,Jan\n>  block 3: Alexander,Ed → ... → Allen,Sam\n>  ...\n>  block n: Wright,Pam → ... → Zimmer,Byron\n> ```\n> → Đảm bảo *cuối block i* < *đầu block i+1*. Binary search \"Allen,Sam\": so block giữa → chia đôi → log₂(n) bước.\n\n#### 1.4.3. Bảng Average Access Times (Slide 25 — Table 17.2)\n\n| Type of Organization | Access / Search Method | Average Blocks to Access a Specific Record |\n|---|---|---|\n| Heap (unordered) | Sequential scan (linear search) | **b/2** |\n| Ordered | Sequential scan | **b/2** |\n| Ordered | **Binary search** | **log₂ b** |\n\n> 💡 **Bẫy:** Ordered + sequential scan vẫn là b/2 — phải DÙNG binary search mới hưởng lợi log₂ b. Cũng vậy: nếu file ordered theo Ssn nhưng tìm theo Salary → vẫn linear search.\n\n#### 1.4.4. Hashed Files — External Hashing (Slide 26)\n\n- **External Hashing**: hashing áp dụng cho disk file.\n- File block chia thành **M bucket** đánh số bucket₀, …, bucket_{M−1}. Thường 1 bucket = 1 (hoặc vài) disk block.\n- Một field được chọn làm **hash key** (vd Ssn). Record có K được lưu trong bucket `i = h(K)`.\n- Search **rất hiệu quả** trên hash key — 1 lần tính h(K) + 1 block access (nếu không collision).\n- **Collision**: record mới hash vào bucket đã đầy → giữ **overflow file** chứa record vượt; có thể **link** các overflow record cùng bucket.\n\n> 📊 **Hình 1.6 — Cấu trúc Hashed File (Slide 27):**\n> ```\n>   Bucket directory                 Disk blocks\n>    ┌─────┐\n>  0 │  ●──┼──→ [block bucket 0]\n>  1 │  ●──┼──→ [block bucket 1]\n>  2 │  ●──┼──→ [block bucket 2]\n>    │ :   │\n>  M-1│ ●──┼──→ [block bucket M-1]\n>    └─────┘\n> ```\n> Để tìm record Ssn=12345: tính h(12345)=k → tra directory[k] → đọc 1 block đó → tìm record trong block.\n\n#### 1.4.5. Ví dụ Open Addressing (Slide 28)\n\n> 💡 **Ví dụ 1.2 — h(K) = K mod 7:**\n> Bảng ban đầu (chỉ số 0..6):\n> ```\n>     0   1   2   3   4   5   6\n>    │   │ 1 │   │ 3 │ 11│   │ 6 │\n> ```\n> **Insert 8:** h(8)=1 → ô 1 có 1 → thử ô 2 (trống) → đặt 8 vào ô 2.\n> **Insert 15:** h(15)=1 → 1→2→3→4→5 (trống) → đặt 15 vào ô 5.\n> **Insert 13:** h(13)=6 → ô 6 có 6 → wrap về 0 (trống) → đặt 13 vào ô 0.\n> Kết quả: `[13, 1, 8, 3, 11, 15, 6]`.\n\n#### 1.4.6. 3 phương pháp Collision Resolution (Slide 29)\n\n1. **Open Addressing**: thử các vị trí kế tiếp đến khi tìm thấy ô trống.\n2. **Chaining**: thêm pointer field; record collision đặt vào overflow location, pointer của bucket gốc trỏ tới.\n3. **Multiple hashing**: dùng h₂ khi h₁ collision; nếu vẫn collision → open addressing hoặc h₃.\n\n> 📊 **Hình 1.7 — Chaining (Slide 30):**\n> ```\n>   Main buckets                      Overflow buckets\n>   ┌─────────────┐\n>  0│ 340 │ 460 │ NULL│ ─── NULL\n>  1│ 321 │ 761 │ 91 │●─┐\n>   └─────────────┘  │   ┌──────────────────┐\n>                    └──→│ 981 │ Rec ptr   ●┼─┐\n>                        │ 182 │ Rec ptr   ●┼─┤\n>                        └──────────────────┘ │\n>   ┌─────────────┐                           │\n>  2│ 22 │ 72 │ 522│ ●──→ ┌──────────────────┐│\n>   └─────────────┘       │ 652 │ Rec ptr ←──┼┘\n>                         └──────────────────┘\n> ```\n\n> 💡 **Hiểu nhanh 3 cách:**\n> - **Open addressing** = nhà bên cạnh (\"ai đến chỗ tôi thì đi qua bên cạnh\").\n> - **Chaining** = nhà phụ (\"nhà tôi đầy thì sang nhà phụ\").\n> - **Multiple hashing** = tìm theo họ → trùng thì tìm theo tên (h₂ thay h₁).\n\n#### 1.4.7. So sánh ba kiểu file\n\n| Tiêu chí | Heap | Ordered | Hashed |\n|---|---|---|---|\n| Insert | Rất nhanh, thêm cuối. | Chậm vì phải giữ thứ tự (workaround: overflow file). | Nhanh nếu bucket chưa đầy. |\n| Search theo key chính xác | Chậm (b/2). | Nhanh (log₂ b) nếu key = ordering field. | Rất nhanh (1 access) nếu không collision. |\n| Search theo **range** | Chậm. | **Rất tốt** nếu range theo ordering field. | **Không tốt** cho range. |\n| Đọc theo thứ tự | Phải sort. | Rất tốt. | Không tự nhiên theo thứ tự. |\n| Vấn đề chính | Tìm chậm. | Insert/delete khó. | Collision/overflow. |\n\n> 📝 **Tóm lại 1.4:** *Heap nhanh ghi chậm đọc; Ordered nhanh đọc chậm ghi; Hashed nhanh nhất cho equality lookup nhưng vô dụng cho range query.*\n\n> ❓ **Tự kiểm tra 1.4 (3 câu):**\n> 1. EMPLOYEE 10,000 record, b=2500. Tìm Ssn='12345': heap linear bao nhiêu? ordered binary bao nhiêu? hashed bao nhiêu (no collision)?\n> 2. Vì sao hashed file *không phù hợp* cho `WHERE Salary BETWEEN 20000 AND 50000`?\n> 3. Phân biệt open addressing và chaining.\n\n---\n\n### 1.5. RAID Technology và Storage Area Networks (Slide 32–39)\n\n#### 1.5.1. Motivation\n\nCPU/RAM nhanh lên 10⁶ lần kể từ 1990, nhưng đĩa chỉ ~10 lần → đĩa thành **bottleneck**. Một đĩa có failure rate ~1%/năm; 100 đĩa → kỳ vọng 1 đĩa hỏng/năm. Cần *parallelism* (tăng tốc) + *redundancy* (chịu lỗi) → **RAID**.\n\n#### 1.5.2. RAID concept (Slide 32–33)\n\n- **RAID** = *Redundant Arrays of Inexpensive Disks* (sau đổi thành *Independent*).\n- **Data striping** (rải dữ liệu) — dùng **parallelism** để cải thiện hiệu năng. Phân phối data *trong suốt* qua nhiều đĩa để xuất hiện như 1 đĩa lớn nhanh.\n\n> 📊 **Hình 1.8 — Data Striping:** File A → A₁, A₂, A₃, A₄ trên Disk 0, 1, 2, 3 (đọc song song → tốc độ x4 lý thuyết).\n\n#### 1.5.3. RAID 0–6 (Slide 34–36)\n\nKhác nhau dựa trên **granularity striping** và **pattern redundancy**:\n\n| Level | Striping | Redundancy | Min disks | Chịu lỗi | Khi dùng |\n|---|---|---|---|---|---|\n| **RAID 0** | Block | KHÔNG | 2 | 0 disk fail | Cache, scratch — tốc độ |\n| **RAID 1** | Mirror | 100% (gương) | 2 | 1 disk fail | Logs, critical apps — dễ rebuild nhất |\n| **RAID 2** | Bit | Hamming codes (detection + correction) | 7+ | 1 disk fail | Hiếm dùng thực tế |\n| **RAID 3** | Byte | Single parity disk (controller biết đĩa hỏng) | 3+ | 1 disk fail | Streaming media — transfer rate cao |\n| **RAID 4** | Block | Single parity disk | 3+ | 1 disk fail | Hiếm (RAID 5 hơn) |\n| **RAID 5** | Block | Parity **rải đều** trên tất cả đĩa | 3+ | 1 disk fail | Server doanh nghiệp — phổ biến |\n| **RAID 6** | Block | P + Q (Reed-Solomon) | 4+ | **2 disk fail** | Backup quan trọng |\n\n> 📊 **RAID 5 vs RAID 4:** Cả 2 đều block-level striping. **RAID 4** có *1 đĩa parity riêng* → parity disk thành bottleneck khi ghi. **RAID 5** *rải parity* lên mọi đĩa → mỗi disk vừa data vừa parity → không bottleneck → ghi nhanh hơn.\n\n> 💡 **Use of RAID (Slide 37):** Phổ biến hiện nay = Level 0 (striping), Level 1 (mirroring), Level 5 (extra drive for parity). Design decision RAID gồm: level, số đĩa, parity scheme, cách nhóm đĩa.\n\n#### 1.5.4. Storage Area Networks (SAN) (Slide 38–39)\n\n- **SAN**: online storage peripherals cấu hình như **node trên mạng tốc độ cao**, gắn/tháo khỏi server *rất linh hoạt*.\n- **Ưu điểm:**\n  - **Flexible many-to-many** giữa server-storage qua fiber channel hub & switch.\n  - **Tới 10 km** giữa server và storage qua fiber optic.\n  - **Better isolation** — thêm thiết bị không gián đoạn.\n- **Nhược:** Khó khi kết hợp lựa chọn từ nhiều vendor; chuẩn quản lý đang phát triển.\n\n> 💡 **Analogy SAN vs DAS:** **DAS** (Direct Attached Storage) = kho hàng nằm sát văn phòng — chỉ văn phòng đó dùng. **SAN** = mạng đường ray riêng nối nhiều văn phòng đến nhiều kho — bất kỳ văn phòng nào cũng chở hàng từ bất kỳ kho nào.\n\n> 📝 **Tóm lại 1.5:** *RAID 0 cho tốc độ, RAID 1 cho gương, RAID 5 cho cân bằng, RAID 6 cho an toàn 2 lớp; SAN cho phép storage là node mạng linh hoạt.*\n\n> ❓ **Tự kiểm tra 1.5 (3 câu):**\n> 1. Phân biệt RAID 4 và RAID 5.\n> 2. Vì sao RAID 0 nhanh nhất khi ghi nhưng không phù hợp cho production-critical?\n> 3. SAN khác DAS ở điểm gì?\n\n---\n\n","file":"materials/DB-Chapter8.md","section":2},{"id":"c8-03","group":"c8","kind":"source","title":"2. Indexing Structures for Files","markdown":"## 2. Indexing Structures for Files\n\n### 2.0. Scaffolding — Vì sao cần Section 2?\n\nỞ 1.4 bạn thấy: ordered file + binary search lấy log₂(b) — với b=10,000 → ~14 access. Tốt, nhưng:\n- **Vấn đề 1**: Binary search cần file *ordered theo đúng field tìm*. Lúc tìm Name, lúc tìm Salary → không thể sort theo 2 thứ cùng lúc.\n- **Vấn đề 2**: Binary search trên *file dữ liệu thật* phải nhảy block, tốn seek.\n\n→ **Giải pháp**: tạo 1 *file phụ* nhỏ chỉ chứa `<field_value, pointer to record>` — gọi là **index file**. Nhỏ hơn → sort nhanh → binary search trên nó nhanh.\n\n### 2.1. Indexes as Access Paths (Slide 45–48)\n\n#### 2.1.1. Khái niệm (Slide 45)\n\n- **Single-level index** = **auxiliary file** giúp tìm record trong data file *hiệu quả hơn*.\n- Index thường định nghĩa trên **1 field** (có thể nhiều) → **indexing field**.\n- Dạng cơ bản: file gồm các entry `<field value, pointer to record>` **ordered theo field value**.\n- Index gọi là **access path** trên field đó.\n\n> 📊 **Hình 2.1 — Index file và data file (Slide 46):**\n> ```\n>   Index file               Data file (indexing field = ID)\n>   ┌──────┬──────┐         ┌─────┬────┬────┬──────┐\n>   │Value │BlkPtr│         │ ID  │Name│DoB │Salary│...\n>   │  1   │  ●───┼────→    │  1,2,3                │ ← block 1\n>   │  4   │  ●───┼─────→   │  4,6,7                │ ← block 2\n>   │  8   │  ●───┼──────→  │  8,9,10               │ ← block 3\n>   │ 12   │  ●───┼───────→ │ 12,13,15              │ ← block 4\n>   └──────┴──────┘\n> ```\n> Index nhỏ hơn nhiều: data có 5+ field; index chỉ 2 → ăn ít block hơn → binary search trên index nhanh hơn.\n\n#### 2.1.2. Tính chất Index (Slide 47)\n\n- Index *chiếm ít block hơn data file* vì entry nhỏ hơn.\n- **Binary search trên index** trả về pointer tới record.\n- Index có thể là:\n  - **Dense index**: 1 index entry cho *MỖI search key value* (mỗi record).\n  - **Sparse / nondense index**: chỉ có entry cho *một số* search value.\n\n> 💡 **Hiểu đơn giản:**\n> - **Dense** = mục lục từ điển: MỖI từ đều có entry → tra \"abandon\" thấy ngay.\n> - **Sparse** = mục lục tiểu thuyết: chỉ có entry mỗi *chương* → tra \"trang 73\" thấy chương 4 (bắt đầu trang 70) → mở chương 4 → lật tiếp.\n\n#### 2.1.3. Ví dụ Dense Index — Slide 48\n\n> 💡 **Ví dụ 2.1 — Dense index trên SSN:**\n> EMPLOYEE(NAME, SSN, ADDRESS, JOB, SAL, …). R=150, B=512, r=30,000. V_SSN=9, P_R=7 (record pointer).\n>\n> **Bước 1 — Data file:** bfr=⌊512/150⌋=**3**; b=⌈30,000/3⌉=**10,000** blocks.\n>\n> **Bước 2 — Dense index entry:** Rᵢ = V_SSN + P_R = 9+7 = **16** byte; bfrᵢ = ⌊512/16⌋ = **32** entries/block.\n>\n> **Bước 3 — Số block index** (dense → 1 entry/record): bᵢ = ⌈30,000/32⌉ = **938** blocks.\n>\n> **Bước 4 — Chi phí search:** ⌈log₂ 938⌉ + 1 = **10 + 1 = 11** block accesses.\n>\n> **Bước 5 — So sánh:**\n> - Linear search: b/2 = **5000**.\n> - Binary search trên data ordered: ⌈log₂ 10,000⌉ = **14**.\n> - Dense index: **11** — cải thiện ~455 lần so với linear.\n>\n> **+1 đến từ đâu?** ⌈log₂ bᵢ⌉ là số block đọc *trong index*. Sau khi tìm thấy pointer, phải đọc thêm 1 *data block* chứa record thật.\n\n---\n\n### 2.2. Types of Single-level Ordered Indexes (Slide 50–71)\n\n**3 loại** (slide 50): **Primary** | **Clustering** | **Secondary**.\n\n#### 2.2.1. Primary Index (Slide 51–53)\n\n- Defined trên **ordered data file** theo **key field**.\n- **Một index entry cho MỖI BLOCK** của data file — entry chứa *first record* của block (gọi **block anchor**). (Có scheme tương tự dùng *last record*.)\n\n> 📊 **Hình 2.2 — Primary Index trên ID:**\n> ```\n>   Primary index            Data file (ordered by ID, key)\n>   ┌──────┬──────┐         ┌─────────────────────────────┐\n>   │  1   │  ●───┼─────→   │ 1, 2, 3                     │ ← anchor=1\n>   │  4   │  ●───┼─────→   │ 4, 6, 7                     │ ← anchor=4\n>   │  8   │  ●───┼─────→   │ 8, 9, 10                    │ ← anchor=8\n>   │ 12   │  ●───┼─────→   │ 12, 13, 15                  │ ← anchor=12\n>   └──────┴──────┘\n> ```\n> Tìm ID=7: binary search index → 7 giữa 4 và 8 → block 2 → đọc block 2 (4, 6, 7) → tìm 7.\n\n**Tính chất (Slide 53):**\n- **Number of index entries** = *số block* của data file.\n- **Dense or Nondense?** → **Nondense** (1 entry/block).\n- **Insert/Update/Delete?** Đắt vì data file phải giữ sorted → có thể dịch chuyển nhiều record.\n\n> 💡 **Vì sao Primary Index Nondense?** 1 entry trỏ tới *block anchor* — record đầu block, không phải tới từng record. Trong 1 block có 3 record (4,6,7) nhưng index chỉ giữ anchor \"4\".\n\n#### 2.2.2. Clustering Index (Slide 54–57)\n\n- Defined trên **ordered data file** theo **non-key field** → **clustering field**.\n- **Một index entry cho MỖI distinct value** của field — trỏ tới **first data block** chứa value đó.\n\n> 📊 **Hình 2.3 — Clustering Index trên Dept_No (non-key):**\n> ```\n>   Clustering index         Data file (ordered by Dept_No)\n>   ┌──────┬──────┐         ┌──────────────────────┐\n>   │ 1    │  ●───┼─→ block với Dept_No=1: │1,1,2│\n>   │ 2    │  ●───┼─→ block đầu chứa 2:    │2,2,2│\n>   │ 3    │  ●───┼─→ ... :                │2,3,3│\n>   │ 4    │  ●───┼─→                      │4,4,5│\n>   │ 5    │  ●───┼─→\n>   └──────┴──────┘\n> ```\n> Dept_No=2 xuất hiện ở nhiều record (trải nhiều block) nhưng chỉ 1 entry \"2\" trong index → trỏ block đầu → đọc tiếp các block kề nhau.\n\n**Cải tiến (Slide 56):** mỗi distinct value *bắt đầu một block mới* — không trộn các value khác nhau cùng block; cuối mỗi nhóm có pointer linked sang nhóm sau.\n\n**Tính chất (Slide 57):**\n- **Number of index entries** = *số distinct value* của indexing field.\n- **Dense or Nondense?** → **Nondense**.\n- **QUAN TRỌNG:** Một file CHỈ có thể có **TỐI ĐA 1 Primary Index HOẶC 1 Clustering Index, KHÔNG ĐƯỢC CẢ HAI** — vì cả hai đòi data file ordered, mà file chỉ ordered được theo *một* field.\n\n#### 2.2.3. Secondary Index (Slide 58–67)\n\n- Cung cấp **secondary means of accessing** một file.\n- Data file **UNORDERED** trên indexing field.\n- Indexing field có thể là **secondary key** (unique) hoặc **nonkey** (duplicate).\n- Index là **ordered file** với 2 trường: (1) indexing field; (2) block pointer hoặc record pointer.\n- Một file có thể có **NHIỀU secondary index** (khác Primary/Clustering — chỉ 1).\n\n##### Secondary Index on KEY field (Slide 59–60)\n\n> 📊 **Hình 2.4 — Secondary Index on key (data UNORDERED):**\n> ```\n>   Secondary index (ordered)    Data file (unordered)\n>   ┌──────┬──────┐              5, 13, 8  ← block 1\n>   │  3   │  ●───┼─→ record     6, 15, 3  ← block 2\n>   │  4   │  ●───┼─→ record     9, 21, 11 ← block 3\n>   │  5   │  ●───┼─→ record     4, 23, 18 ← block 4\n>   │  6   │  ●───┼─→ ...\n>   │  8   │  ●───┼─→\n>   │  ⋮   │  ⋮   │\n>   │ 23   │  ●───┼─→\n>   └──────┴──────┘\n>   → mỗi entry trỏ thẳng tới record (record pointer)\n> ```\n\n**Tính chất (Slide 60):**\n- **Entries** = số record data file.\n- **Dense** (bắt buộc — data unordered, không có anchor để sparse).\n\n##### Secondary Index on NON-KEY field (Slide 61) — 3 option\n\n**Option 1: Duplicate entries** cùng K(i), 1 entry/record → **DENSE**.\n\n> 📊 Index có 13 entry (cho 13 record), sort theo Phòng: 1,1,2,2,2,2,3,4,4,5,5,5,5.\n\n**Option 2: List of pointers** `<P(i,1), …, P(i,k)>` trong entry K(i) → **NONDENSE** nhưng *variable-length entry* → khó quản lý, khó binary search.\n\n**Option 3 (PHỔ BIẾN NHẤT):** 1 entry/distinct value + **extra level of indirection** (block trung gian chứa danh sách pointer) → **NONDENSE**, fixed-length entry.\n\n> 📊 **Hình 2.7 — Option 3:**\n> ```\n>   Index            Mức trung gian          Data file\n>   ┌────┬────┐      (blocks of record ptrs)\n>   │ 1  │ ●──┼─→    ┌──────────────┐\n>   │ 2  │ ●──┼─→    │ ●→record 1   │\n>   │ 3  │ ●──┼─→    │ ●→record 2   │\n>   │ 4  │ ●──┼─→    │   ⋮         │\n>   │ 5  │ ●──┼─→    └──────────────┘\n>   └────┴────┘\n> ```\n> Tìm Phòng=2: index → block trung gian của 2 → trong đó có nhiều pointer → mỗi record Phòng=2.\n\n#### 2.2.4. Summary — Bảng tổng hợp (Slide 70 — Table 18.2)\n\n| Type of Index | Number of (First-level) Index Entries | Dense / Nondense | Block Anchoring on Data File |\n|---|---|---|---|\n| **Primary** | Number of **blocks** in data file | Nondense | **Yes** |\n| **Clustering** | Number of **distinct** index field values | Nondense | Yes/no ᵃ |\n| **Secondary (key)** | Number of **records** in data file | **Dense** | No |\n| **Secondary (nonkey)** | Number of records ᵇ hoặc number of distinct field values ᶜ | Dense or Nondense | No |\n\n> ᵃ Yes nếu mỗi distinct value bắt đầu block mới; no nếu không.\n> ᵇ Option 1. ᶜ Option 2, 3.\n\n**Phân loại theo \"Data file ordered trên indexing field?\" (Slide 68):**\n- File **ordered** → **Primary** (nếu key) | **Clustering** (nếu non-key).\n- File **unordered** → **Secondary** (cả key và non-key).\n\n> 💡 **Mẹo nhớ:** \"**P**rimary và **C**lustering\" → *Nondense* (file ordered → có block anchor để sparse). \"**S**econdary on key\" → *Dense* (data unordered → phải có entry cho mỗi record).\n\n#### 2.2.5. Ví dụ Primary Index — Slide 71\n\n> 💡 **Ví dụ 2.2 — Primary Index trên SSN (file ordered theo key):**\n> EMPLOYEE: R=150, B=512, r=30,000. V_SSN=9, **block pointer P=6 byte** (khác Ví dụ 2.1 dùng record pointer 7!).\n>\n> - **Data:** bfr=3, b=10,000.\n> - **Primary index entry:** Rᵢ = 9+6 = **15** byte; bfrᵢ = ⌊512/15⌋ = **34** entries/block.\n> - **Số entry primary = số BLOCK** = 10,000 → bᵢ = ⌈10,000/34⌉ = **295** blocks.\n> - **Search:** ⌈log₂ 295⌉ + 1 = 9 + 1 = **10** block accesses.\n> - **So với dense (Ví dụ 2.1):** 11. Primary tốn ít block hơn (295 vs 938) vì *1 entry/block* thay vì *1 entry/record* → primary index *sparse* nhanh hơn dense.\n\n> 📝 **Tóm lại 2.2:** *Primary cho key đã sort; Clustering cho non-key đã sort; Secondary cho mọi trường hợp khác — và bao nhiêu Secondary cũng được.*\n\n> ❓ **Tự kiểm tra 2.2 (4 câu):**\n> 1. Tại sao Primary nondense còn Secondary on key dense?\n> 2. Vì sao 1 file *không thể* có cả Primary và Clustering cùng lúc?\n> 3. Để tăng tốc `SELECT * FROM EMPLOYEE WHERE Dno=5` nên tạo loại index nào? Vì sao?\n> 4. EMPLOYEE 30,000 record, file unordered → tạo dense secondary index trên Ssn (V=9, P=7, B=512). Tính bᵢ.\n\n---\n\n### 2.3. Multilevel Indexes (Slide 73–77)\n\n#### 2.3.1. Motivation\n\nVí dụ 2.2: index có 295 block, log₂ 295 ≈ 9 access. Với r=100 triệu → index hàng nghìn block, mỗi access là 1 seek. Cách giảm xuống 2–3 access?\n\n**Insight:** Index *bản thân nó là ordered file* → tạo *index cho file index* → **multilevel index**.\n\n#### 2.3.2. Khái niệm (Slide 73)\n\n- File index gốc = **first-level index**; index trỏ tới index = **second-level**.\n- Lặp lại: third, fourth, …, **top level cho đến khi tất cả entry của top level vừa khít trong MỘT block**.\n- Có thể tạo cho **bất kỳ loại first-level index** (primary, secondary, clustering) miễn first-level có **> 1 block**.\n\n> 📊 **Hình 2.8 — Two-level primary index, kiểu ISAM (Slide 74):**\n> ```\n>   Top level (2nd)   Base level (1st)        Data file\n>   ┌────┬──┐         ┌────┬──┐               ┌──┬──┐\n>   │ 2  │●─┼──────→  │ 2  │●─┼─→             │ 2│ 5│\n>   │35  │●─┼─┐       │ 8  │●─┼─→             │ 8│12│\n>   │55  │●─┼─┼┐      │15  │●─┼─→             │15│21│\n>   │85  │●─┼─┼┼┐     │24  │●─┼─→             │24│29│\n>   └────┴──┘ │││     └────┴──┘               ...\n>             │└→     ┌────┬──┐\n>             │       │35  │●─┼─→             │35│36│\n>             │       │39  │●─┼─→             │39│41│\n>             │       │44  │●─┼─→             │44│46│\n>             │       │51  │●─┼─→             │51│52│\n>             │       └────┴──┘\n>             ...                            (Indexed Sequential Access Method)\n> ```\n>\n> Tìm key=39: (1) top: 39 giữa 35 và 55 → đi base bắt đầu \"35\"; (2) base: 39 giữa 39 và 44 → đi data block bắt đầu \"39\"; (3) data: tìm 39 trong block. → **3 block accesses** (1 top + 1 base + 1 data) — giảm so với single-level.\n\n> 💡 **Hiểu đơn giản:** Multi-level index = **mục lục đa cấp**: cuốn từ điển có (1) cánh gà ABC ngoài bìa (top), (2) mục lục đầu chương (base), (3) trang định nghĩa (data).\n\n#### 2.3.3. Hạn chế multilevel tĩnh (Slide 75)\n\n- Multi-level là một dạng **search tree**.\n- **NHƯỢC ĐIỂM**: Insert/delete index entry là vấn đề nghiêm trọng vì **mỗi level là ordered file** → mỗi insert ở first-level có thể trigger update cascading lên top level.\n\n→ Cần cấu trúc mới: **B-tree / B+-tree** (section 2.4).\n\n#### 2.3.4. Search Tree node (Slide 76–77)\n\nMột node của search tree **order q** chứa q-1 key values K₁ < K₂ < … < K_{q-1} và q tree pointers P₁, P₂, …, P_q. Pᵢ trỏ tới subtree chứa giá trị X thoả `K_{i-1} < X < Kᵢ` (K₀ = −∞, K_q = +∞).\n\n> 📊 **Hình 2.10 — Search tree of order p=3 (Slide 77):**\n> ```\n>                    ┌────┬───┬────┐\n>                    │ ●  │ 5 │ ●  │\n>                    └─┬──┴───┴──┬─┘\n>             ┌────────┘         └────────┐\n>             ▼                           ▼\n>      ┌──┬───┬────┐              ┌──┬───┬──┬───┬──┐\n>      │● │ 3 │NULL│              │● │ 6 │● │ 9 │● │\n>      └─┬┴───┴────┘              └─┬┴───┴─┬┴───┴─┬┘\n>        ▼                          ▼      ▼      ▼\n>     ┌──┬───┐                   ┌──┬──┐ ┌──┬───┐ ┌────┐\n>     │1 │NULL│                   │7 │8 │ │12│NULL│ │NULL│\n>     └──┴───┘                   └──┴──┘ └──┴───┘ └────┘\n> ```\n\n> 📝 **Tóm lại 2.3:** Multilevel index = mục lục đa cấp; search rất nhanh (3–4 access) nhưng insert đau đầu vì phải giữ ordered ở mọi level — đó là động lực cho B-tree/B+-tree.\n\n> ❓ **Tự kiểm tra 2.3 (3 câu):**\n> 1. First-level 295 block, bfrᵢ=34. Two-level có bao nhiêu block ở level 2? Tổng chi phí search?\n> 2. Vì sao multilevel cần giải thuật phức tạp khi insert/delete?\n> 3. Multilevel index có thể tạo trên loại first-level nào? Có điều kiện gì?\n\n---\n\n### 2.4. Dynamic Multilevel Indexes — B-Trees và B+-Trees (Slide 79–83)\n\n#### 2.4.1. Motivation (Slide 79)\n\n- Hầu hết multilevel index dùng **B-tree** hoặc **B+-tree** vì giải quyết vấn đề insert/delete.\n- Tinh thần: **để chỗ trống trong mỗi node (= 1 disk block)** để chứa entry mới sau này.\n- Biến thể của search tree cho phép insert/delete hiệu quả. Mỗi node = 1 disk block. Mỗi node giữ **half-full đến full** → đảm bảo cây không lệch, performance ổn định.\n\n#### 2.4.2. Insert / Delete (Slide 80)\n\n| Tình huống | Hành vi |\n|---|---|\n| Insert vào node chưa full | Rất hiệu quả — chỉ thêm vào đúng vị trí. |\n| Insert vào node full | **Split** thành 2 node. Splitting có thể **propagate** lên các level trên. |\n| Delete, node không trở thành less than half full | Hiệu quả. |\n| Delete làm node less than half full | Phải **merge** với neighbor. |\n\n> 💡 **Analogy split & merge:** Tủ sách quy định \"không trống quá nửa, không vượt giới hạn\". Nhồi quá → mua tủ mới chia đôi (split). Trống quá → gộp tủ kế bên (merge).\n\n#### 2.4.3. B-tree vs B+-tree (Slide 81)\n\n| Tiêu chí | B-tree | B+-tree |\n|---|---|---|\n| **Vị trí data pointer** | Tồn tại ở **MỌI level** | Chỉ ở **leaf-level nodes** |\n| **Số level cho cùng số search value** | Nhiều hơn | **Ít hơn** (fanout lớn hơn) |\n| **Range query** | Khó (phải duyệt cây) | **Dễ** — leaf có **P_next** nối linked list |\n| **Internal node chứa** | Search values + data pointers + tree pointers | **CHỈ** search values + tree pointers |\n| **Leaf node chứa** | Search + data + tree pointers | Search + data pointers + **P_next** |\n\n> 💡 **Vì sao B+-tree ít level hơn B-tree?** Node internal B-tree mang data pointer cho mỗi key → entry to → ít search value/node. Node internal B+-tree không có data pointer → entry nhỏ → nhiều search value/node → fanout lớn → cây thấp hơn.\n\n#### 2.4.4. B-Tree Structures (Slide 82)\n\n> 📊 **Hình 2.11(a) — B-tree node:**\n> ```\n>   ┌──┬───┬───┬──┬───┬───┬─────────┬──┐\n>   │P₁│K₁│Pr₁│P₂│K₂│Pr₂│   ...   │P_q│\n>   └──┴───┴───┴──┴───┴───┴─────────┴──┘\n>     │                                │\n>     ▼ subtree X<K₁                   ▼ subtree X>K_{q-1}\n> ```\n> Mỗi search key Kᵢ đi kèm **data pointer Prᵢ** ngay trong node. → Data có thể tìm thấy ở node giữa đường, không cần xuống leaf.\n\n#### 2.4.5. B+-Tree Nodes (Slide 83)\n\n> 📊 **Hình 2.11 — B+-tree nodes:**\n>\n> **(a) Internal node** với q-1 search values, q tree pointers (KHÔNG có data pointer):\n> ```\n>   ┌──┬───┬──┬───┬──────┬────┬──┐\n>   │P₁│K₁│P₂│K₂│ ...   │K_{q-1}│P_q│\n>   └──┴───┴──┴───┴──────┴────┴──┘\n>      ▼              ▼              ▼\n>    X ≤ K₁     K_{i-1} < X ≤ Kᵢ   K_{q-1} < X\n> ```\n>\n> **(b) Leaf node** với q-1 search values + q-1 data pointers + P_next:\n> ```\n>   ┌────┬────┬────┬────┬────┬─────┬────────┬───────┐\n>   │K₁Pr₁│K₂Pr₂│ ...│KᵢPrᵢ│ ... │K_{q-1}Pr_{q-1}│P_next│\n>   └────┴────┴────┴────┴────┴─────┴────────┴───────┘\n>      │     │           │            │           │\n>      ▼     ▼           ▼            ▼           ▼\n>    Data  Data        Data         Data    → next leaf\n> ```\n\n> 💡 **Hiểu đơn giản:**\n> - **Internal node** = bảng chỉ dẫn ngoài cửa thư viện (\"phòng 1: 0–999; phòng 2: 1000–1999\") — không có sách thật.\n> - **Leaf node** = bảng chỉ dẫn trong phòng (\"kệ 1: số 0–9 → vị trí; kệ 2: số 10–19 → vị trí\") + cuối phòng có biển \"Sang phòng kế\" (P_next).\n>\n> **Lợi ích P_next:** `WHERE Salary BETWEEN A AND B` → tìm leaf chứa A → duyệt linked list cho đến B → cực nhanh.\n\n> 📝 **Tóm lại 2.4:** *B+-tree là multilevel index có \"khoản trống dự phòng\" trong mỗi block + leaf nối chuỗi → vừa nhanh insert vừa nhanh range query — index thực tế nhất, dùng trong PostgreSQL, MySQL InnoDB.*\n\n> ❓ **Tự kiểm tra 2.4 (3 câu):**\n> 1. Vì sao mỗi node B-tree được giữ \"half-full đến full\"?\n> 2. Range query `Salary BETWEEN 30000 AND 50000` chạy trên B-tree vs B+-tree — cái nào nhanh hơn? Vì sao?\n> 3. Trong B+-tree, vì sao internal node KHÔNG có data pointer giúp cây thấp hơn?\n\n---\n\n","file":"materials/DB-Chapter8.md","section":3},{"id":"c8-04","group":"c8","kind":"source","title":"Bảng Tra Nhanh — 1 Trang Ôn Thi","markdown":"## Bảng Tra Nhanh — 1 Trang Ôn Thi\n\n### Công thức \"kim chỉ nam\"\n\n| Đại lượng | Công thức | Ghi chú |\n|---|---|---|\n| Blocking factor | `bfr = ⌊B/R⌋` | floor (làm tròn xuống) |\n| Số block file | `b = ⌈r/bfr⌉` | ceil (làm tròn lên) |\n| Linear search (heap) | trung bình **b/2** | worst case b |\n| Binary search (ordered file) | **⌈log₂ b⌉** | chỉ áp dụng theo ordering field |\n| Hashed search (no collision) | **1 block** | bucket directory thường trong RAM |\n| Index entry size (sparse, block ptr) | `Rᵢ = V + P` | P = block pointer (vd 6 byte) |\n| Index entry size (dense, record ptr) | `Rᵢ = V + P_R` | P_R = record pointer (vd 7 byte) |\n| Index blocking factor | `bfrᵢ = ⌊B/Rᵢ⌋` | |\n| Single-level index search | **⌈log₂ bᵢ⌉ + 1** | +1 để đọc data block |\n| Multilevel two-level | **L + 1** | L = số level (3 nếu top fit 1 block + 1 base + 1 data) |\n| Block access time | `s + rd + btt` | seek + rotational delay + block transfer time |\n| Rotational delay (avg) | `(1 revolution time) / 2` | rpm 2400 → rd=12.5 ms |\n| Transfer rate (useful) | `useful_bytes_per_track / rotation_time` | Appendix B |\n\n### 3 loại Index — bảng tra nhanh\n\n| | Primary | Clustering | Secondary (key) | Secondary (nonkey) |\n|---|---|---|---|---|\n| Data file ordered? | Yes (theo key) | Yes (theo non-key) | No | No |\n| Field is key? | Yes | No | Yes | No |\n| # entries | # blocks | # distinct values | # records | # records hoặc # distinct |\n| Dense / Sparse | **Nondense** | **Nondense** | **Dense** | Dense / Nondense |\n| Block anchor? | Yes | Yes/No | No | No |\n| Max per file | **1** (cùng với Clustering) | **1** (cùng với Primary) | **Nhiều** | **Nhiều** |\n| Ví dụ COMPANY | Index trên `EMPLOYEE(Ssn)` khi file sort theo Ssn | Index trên `EMPLOYEE(Dno)` khi file sort theo Dno | Index trên `EMPLOYEE(Ssn)` khi file unordered | Index trên `EMPLOYEE(Salary)` |\n\n### RAID 0–6 — bảng tra nhanh\n\n| Level | Striping | Redundancy | Disk fail tolerance | Note |\n|---|---|---|---|---|\n| 0 | Block | KHÔNG | 0 | Tốc độ tối đa, mất 1 disk = mất data |\n| 1 | Mirror | 100% | 1 | Logs, critical apps |\n| 2 | Bit | Hamming (3 parity) | 1 | Hiếm dùng |\n| 3 | Byte | Single parity | 1 | Transfer rate cao |\n| 4 | Block | Single parity disk | 1 | Hiếm (parity disk = bottleneck) |\n| 5 | Block | Parity rải đều | 1 | **Phổ biến nhất** cho server |\n| 6 | Block | P + Q (Reed-Solomon) | **2** | Backup quan trọng |\n\n---\n\n","file":"materials/DB-Chapter8.md","section":4},{"id":"c8-05","group":"c8","kind":"source","title":"Sai Lầm Thường Gặp","markdown":"## Sai Lầm Thường Gặp\n\n| # | Sai lầm | Tại sao sai | Cách đúng |\n|---|---|---|---|\n| 1 | Tính `bfr = B/R` không làm tròn | Tạo phân số → vô nghĩa cho số record/block | `bfr = ⌊B/R⌋` (floor) |\n| 2 | Tính `b = r/bfr` không làm tròn | Bỏ sót record dư | `b = ⌈r/bfr⌉` (ceil) |\n| 3 | Tính dense index entry size với block pointer P | Dense trỏ tới *record*, không phải block | Dùng `Rᵢ = V + P_R` (record pointer) |\n| 4 | Tính primary index entry size với record pointer P_R | Primary trỏ block anchor → block pointer | Dùng `Rᵢ = V + P` (block pointer) |\n| 5 | Cho rằng có thể có cả Primary và Clustering trên 1 file | Cả 2 đòi data file ordered, file chỉ ordered 1 field | Chỉ 1 (Primary HOẶC Clustering); nhưng có thể có nhiều Secondary kèm |\n| 6 | Cho rằng Secondary on key là Nondense | Data file unordered → không có anchor để sparse | **Bắt buộc Dense** |\n| 7 | Quên +1 khi tính chi phí search qua index | log₂(bᵢ) là chi phí *trong index* — còn phải đọc data block | `⌈log₂ bᵢ⌉ + 1` |\n| 8 | Cho rằng Hashed file tốt cho range query | h(K) làm 2 key kề nhau hash vào 2 bucket bất kỳ | Hashed *cực tốt cho equality*, *vô dụng cho range* |\n| 9 | Cho rằng B-tree và B+-tree giống nhau | B-tree có data pointer ở mọi level; B+-tree chỉ ở leaf + P_next | B+-tree tốt hơn cho range query và có fanout lớn hơn |\n| 10 | Tính `btt` bằng raw bytes per track | Slide HCMUT theo Appendix B dùng useful capacity | `tr = useful_bytes / rotation_time`, `btt = B / tr` |\n\n---\n\n","file":"materials/DB-Chapter8.md","section":5},{"id":"c8-06","group":"c8","kind":"source","title":"Câu Hỏi Ôn Tập (từ slide gốc — 5 Exercise)","markdown":"## Câu Hỏi Ôn Tập (từ slide gốc — 5 Exercise)\n\n### Exercise 1 (Slide 40–43) — bfr, b, binary search\n\nFile r=30,000 EMPLOYEE fixed-length. Fields: Name(30)+SSN(9)+Department_code(9)+Address(40)+Phone(10)+Birth_date(8)+Sex(1)+Job_code(4)+Salary(4)+deletion marker(1). B=512, P=6, P_R=7.\n\n1. **R = ?**\n   - R = 30+9+9+40+10+8+1+4+4+1 = **116 bytes**.\n\n2. **bfr và b (unspanned)?**\n   - bfr = ⌊512/116⌋ = **4** records/block.\n   - b = ⌈30,000/4⌉ = **7500** blocks.\n\n3. **File ordered by SSN — block accesses (binary search)?**\n   - ⌈log₂ 7500⌉ = **13** block accesses.\n\n### Exercise 2 (Slide 89, 91) — Primary Index trên SSN\n\nSame file. File ordered by SSN, build primary index trên SSN.\n\n4a. **Index blocking factor bfrᵢ?**\n   - Rᵢ = V_SSN + P = 9 + 6 = 15 byte → bfrᵢ = ⌊512/15⌋ = **34** entries/block.\n\n4b. **Số entries và số index blocks?**\n   - # entries = # blocks data = **7500**.\n   - bᵢ = ⌈7500/34⌉ = **221** blocks.\n\n4c. **Block accesses?**\n   - ⌈log₂ 221⌉ + 1 = 8 + 1 = **9** block accesses.\n\n### Exercise 3 (Slide 93) — Two-level Multilevel\n\n5a. **Total blocks of second-level index?**\n   - Second-level = primary trên first-level (221 block, bfrᵢ=34). # entries = 221 → b₂ = ⌈221/34⌉ = **7** blocks.\n\n5b. **Block accesses (two-level)?**\n   - ⌈log₂ 7⌉ + 1 (first) + 1 (data) = 3 + 1 + 1 = **5** block accesses.\n   - *(Nếu top level chỉ 7 block — fit 1 block thì chỉ 1 top + 1 base + 1 data = 3 accesses; đề \"two-level\" thường tính theo cách trên = 5.)*\n\n### Exercise 4 (Slide 95) — Disk parameters\n\nDisk: B=512, gap G=128, 20 blocks/track, 400 tracks/surface, 15 double-sided disks, p=2400 rpm, s=30 msec.\n\n**a) Track total + useful capacity:**\n- Useful = 20 × 512 = **10,240 byte (10 KB)**.\n- Total = 20 × (512+128) = 20 × 640 = **12,800 byte (12.5 KB)**.\n\n**b) Cylinders:** **400** (mỗi surface có 400 tracks).\n\n**c) Cylinder capacity:** 15 × 2 = 30 surfaces → Useful = 30 × 10,240 = **307,200 B (300 KB)**; Total = 30 × 12,800 = **384,000 B (375 KB)**.\n\n**d) Disk pack capacity:** Useful = 400 × 307,200 = **122,880,000 B ≈ 117 MB**; Total = 400 × 384,000 = **153,600,000 B ≈ 146 MB**.\n\n**e) tr, btt, rd, btr:**\n- 2400 rpm = 40 rev/sec → 1 rev = 1000/40 = **25 msec**.\n- tr = 10,240 / 25 = **409.6 byte/msec** (useful).\n- **btt = B / tr = 512 / 409.6 = 1.25 msec** (Appendix B). Tương đương: btt = 25 × (512/10,240) = 1.25 msec.\n- **rd = 25 / 2 = 12.5 msec**.\n- Bulk transfer rate btr ≈ 409.6 byte/msec ≈ 0.4 MB/sec.\n\n**f) Single block locate + transfer:** **s + rd + btt = 30 + 12.5 + 1.25 = 43.75 msec**.\n\n**g) 20 random vs 20 consecutive (double buffering):**\n- Random: 20 × 43.75 = **875 msec**.\n- Consecutive: 30 + 12.5 + 20 × 1.25 = **67.5 msec**.\n- Consecutive nhanh hơn **~13 lần**.\n\n### Exercise 5 (Slide 96) — STUDENT file\n\nr=20,000, fixed-length. Fields: Name(30)+Ssn(9)+Address(40)+PHONE(10)+Birth_date(8)+Sex(1)+Major_dept_code(4)+Minor_dept_code(4)+Class_code(4)+Degree_program(3)+deletion marker(1). Disk như Exercise 4.\n\n**a) R:** 30+9+40+10+8+1+4+4+4+3+1 = **114 bytes**.\n\n**b) bfr & b:** bfr = ⌊512/114⌋ = **4**. b = ⌈20,000/4⌉ = **5000** blocks.\n\n**c) Linear search avg time:**\n- (i) **Contiguous + double buffering** (b/2 = 2500 block): 30 + 12.5 + 2500 × 1.25 = **3167.5 msec**.\n- (ii) **Non-contiguous (random)**: 2500 × 43.75 = **109,375 msec ≈ 109 sec**.\n\n**d) Binary search (file ordered by Ssn):**\n- ⌈log₂ 5000⌉ = **13** block accesses.\n- Time = 13 × 43.75 = **568.75 msec**.\n\n---\n\n","file":"materials/DB-Chapter8.md","section":6},{"id":"c8-07","group":"c8","kind":"source","title":"Mini Bài Tập Tự Luyện (kèm Lời Giải)","markdown":"## Mini Bài Tập Tự Luyện (kèm Lời Giải)\n\n> **Bài tập tự luyện 1 (dễ):** File DEPARTMENT có r=200, R=80 byte, B=512. Tính bfr, b.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> - bfr = ⌊512/80⌋ = 6 records/block.\n> - b = ⌈200/6⌉ = ⌈33.33⌉ = 34 blocks.\n> - Mỗi block chứa 6×80=480 byte data + 32 byte trống.\n> </details>\n\n> **Bài tập tự luyện 2 (trung bình):** File EMPLOYEE r=30,000 unordered (heap). Tạo *secondary index trên Salary* (V_Salary=8 byte, P_R=7 byte, B=512). Salary là non-key (duplicate values), giả sử có 5,000 distinct Salary values. Dùng Option 1 (duplicate entries, dense). Tính bᵢ và chi phí search.\n>\n> <details><summary>Xem lời giải</summary>\n>\n> - Rᵢ = V + P_R = 8 + 7 = 15 byte.\n> - bfrᵢ = ⌊512/15⌋ = 34 entries/block.\n> - Option 1: # entries = # records = 30,000 → bᵢ = ⌈30,000/34⌉ = 883 blocks.\n> - Chi phí search 1 Salary value: ⌈log₂ 883⌉ + 1 = 10 + 1 = 11 block accesses (cho record đầu tiên).\n> - Lưu ý: với non-key, có thể có nhiều record cùng Salary → phải đọc thêm các entry kề trong index và data block tương ứng.\n> </details>\n\n> **Bài tập tự luyện 3 (trung bình):** Same EMPLOYEE 30,000 record. Disk như Exercise 4 (s=30, rd=12.5, btt=1.25). Tính tổng thời gian thực hiện query `SELECT * FROM EMPLOYEE WHERE Ssn='123456789'` trong 3 tình huống:\n> (a) heap, file random;\n> (b) file ordered by Ssn — binary search;\n> (c) ordered + primary index trên Ssn (bᵢ=221).\n>\n> <details><summary>Xem lời giải</summary>\n>\n> - **(a) Heap, random blocks:** b/2 × 43.75 = 3750 × 43.75 ≈ **164,062.5 msec ≈ 164 sec**. *(Quá chậm, không chấp nhận được.)*\n> - **(b) Binary search trên ordered file:** 13 × 43.75 ≈ **568.75 msec**. *(Khá tốt.)*\n> - **(c) Primary index:** (8+1) × 43.75 ≈ **393.75 msec**. *(Nhanh nhất — và còn nhanh hơn nữa nếu index nằm sẵn trong cache RAM.)*\n> </details>\n\n> **Bài tập tự luyện 4 (khó):** Một B+-tree order p được dùng làm index trên Ssn. Block size B=512, tree pointer = 6 byte, search key V=9 byte, data pointer P_r=7 byte. Tính:\n> (a) Order p của internal node (số tree pointer tối đa);\n> (b) Order p_leaf của leaf node (số (K, P_r) pair tối đa, biết leaf còn 1 P_next = 6 byte).\n>\n> <details><summary>Xem lời giải</summary>\n>\n> - **(a) Internal node:** chứa p tree pointer + (p-1) search keys → `p × 6 + (p-1) × 9 ≤ 512` ⇒ `15p − 9 ≤ 512` ⇒ `p ≤ 34.7` ⇒ **p = 34**.\n> - **(b) Leaf node:** chứa p_leaf cặp (K, P_r) + 1 P_next → `p_leaf × (9+7) + 6 ≤ 512` ⇒ `16 × p_leaf ≤ 506` ⇒ `p_leaf ≤ 31.6` ⇒ **p_leaf = 31**.\n> - Vì internal entry nhỏ hơn → fanout 34 > 31, cây sẽ thấp.\n> </details>\n\n> **Bài tập tự luyện 5 (khó — thường ra thi tự luận):** EMPLOYEE 100,000 records, R=200, B=1024, P=8 (block ptr), P_R=10 (record ptr). File ordered theo Ssn. Tạo *primary index* trên Ssn (V_Ssn=9). Sau đó tạo *multilevel index*. Cần bao nhiêu level để top fit 1 block? Tổng block accesses?\n>\n> <details><summary>Xem lời giải</summary>\n>\n> - **Data file:** bfr = ⌊1024/200⌋ = 5; b = ⌈100,000/5⌉ = 20,000 blocks.\n> - **First-level primary:** Rᵢ = 9+8 = 17; bfrᵢ = ⌊1024/17⌋ = 60; entries = 20,000 → b₁ = ⌈20,000/60⌉ = 334 blocks.\n> - **Second-level:** entries = 334 → b₂ = ⌈334/60⌉ = 6 blocks.\n> - **Third-level (top):** entries = 6 → b₃ = ⌈6/60⌉ = 1 block → DỪNG (fit 1 block).\n> - Số level = 3.\n> - **Tổng block accesses:** 1 (top) + 1 (b₂) + 1 (b₁) + 1 (data) = **4 block accesses**.\n> - So với single-level binary search trên primary: ⌈log₂ 334⌉ + 1 = 9 + 1 = 10 → multilevel giảm từ 10 xuống 4.\n> </details>\n\n---\n\n","file":"materials/DB-Chapter8.md","section":7},{"id":"c8-08","group":"c8","kind":"source","title":"Bảng Tổng Hợp Thuật Ngữ Chương 8 (Glossary)","markdown":"## Bảng Tổng Hợp Thuật Ngữ Chương 8 (Glossary)\n\n| # | Thuật ngữ (EN) | Thuật ngữ (VI) | Định nghĩa ngắn | Slide # |\n|---|---|---|---|---|\n| 1 | Disk pack | Khối đĩa | Nhiều đĩa từ chia sẻ chung 1 spindle | 5 |\n| 2 | Track | Rãnh | Vòng tròn đồng tâm trên mặt đĩa | 5 |\n| 3 | Sector | Cung | Cung tròn của 1 track | 7 |\n| 4 | Cylinder | Trụ ảo | Tập tracks cùng bán kính trên các mặt | 10 |\n| 5 | Block | Khối | Đơn vị transfer giữa đĩa và RAM (512–4096 B) | 9 |\n| 6 | Block size (B) | Kích thước khối | Số byte/block, cố định | 9 |\n| 7 | Seek time (s) | Thời gian dịch | Thời gian arm dịch tới đúng cylinder | 10 |\n| 8 | Rotational delay (rd) | Trễ quay | Thời gian đợi block dưới head | 10 |\n| 9 | Block transfer time (btt) | Thời gian truyền khối | Thời gian thật để truyền block | 10 |\n| 10 | Double buffering | Đệm đôi | Dùng 2 buffer xen kẽ để tăng tốc | 10 |\n| 11 | Record | Bản ghi | 1 dòng dữ liệu = tập field | 12 |\n| 12 | Field | Trường | 1 cột trong record | 12 |\n| 13 | Fixed-length record | Bản ghi cố định | Mọi record cùng kích thước | 12 |\n| 14 | Variable-length record | Bản ghi biến đổi | Record khác nhau kích thước | 12 |\n| 15 | Separator character | Ký tự ngăn cách | Để parse field variable | 12 |\n| 16 | Blocking | Gộp khối | Nhồi nhiều record vào 1 block | 14 |\n| 17 | Blocking factor (bfr) | Hệ số khối | Số record/block | 14 |\n| 18 | Spanned record | Bản ghi vắt | Record trải qua nhiều block | 14 |\n| 19 | Unspanned record | Bản ghi không vắt | 1 record không qua 2 block | 14 |\n| 20 | File descriptor / header | Đầu file | Lưu schema và địa chỉ block | 16 |\n| 21 | Heap (pile) file | File chồng | File unordered, insert ở cuối | 22 |\n| 22 | Linear search | Tìm tuyến tính | Quét tuần tự, O(b/2) | 22 |\n| 23 | Sequential file | File tuần tự | File ordered | 23 |\n| 24 | Ordering field | Field sắp xếp | Field dùng để sort file | 23 |\n| 25 | Binary search | Tìm nhị phân | O(log₂ b) trên ordered file | 23 |\n| 26 | Overflow file | File tràn | Heap phụ cho ordered file | 23 |\n| 27 | External hashing | Băm ngoài | Hashing cho disk file | 26 |\n| 28 | Bucket | Thùng | 1 đơn vị lưu trong hashed file | 26 |\n| 29 | Hash function h(K) | Hàm băm | Map key → bucket number | 26 |\n| 30 | Collision | Đụng độ | 2 key hash vào cùng bucket | 26 |\n| 31 | Open addressing | Địa chỉ mở | Resolution: thử vị trí kế | 28 |\n| 32 | Chaining | Xích | Resolution: linked list overflow | 29 |\n| 33 | Multiple hashing | Băm đa | Resolution: dùng h₂ khi h₁ collision | 29 |\n| 34 | RAID | Mảng đĩa dư | Redundant Arrays of Inexpensive/Independent Disks | 32 |\n| 35 | Data striping | Rải dữ liệu | Phân phối data qua nhiều đĩa | 33 |\n| 36 | RAID 0 | — | Striping không parity | 34 |\n| 37 | RAID 1 | — | Mirroring | 34 |\n| 38 | RAID 5 | — | Block striping + distributed parity | 35 |\n| 39 | RAID 6 | — | P+Q (Reed-Solomon), chịu 2 disk fail | 36 |\n| 40 | SAN | Mạng lưu trữ | Storage Area Networks | 38 |\n| 41 | Index | Chỉ mục | File phụ tăng tốc tìm record | 45 |\n| 42 | Indexing field | Field chỉ mục | Field mà index xây trên | 45 |\n| 43 | Access path | Đường truy cập | Index = path tới record | 45 |\n| 44 | Dense index | Chỉ mục dày | 1 entry/record | 47 |\n| 45 | Sparse / Nondense index | Chỉ mục thưa | 1 entry/block hoặc 1 entry/distinct | 47 |\n| 46 | Primary Index | Chỉ mục chính | Trên ordered file + key | 51 |\n| 47 | Block anchor | Mỏ neo khối | Record đầu mỗi block | 51 |\n| 48 | Clustering Index | Chỉ mục gom nhóm | Trên ordered file + non-key | 54 |\n| 49 | Clustering field | Field gom nhóm | Field non-key dùng sort file | 54 |\n| 50 | Secondary Index | Chỉ mục thứ cấp | Trên unordered file | 58 |\n| 51 | Multilevel index | Chỉ mục đa cấp | Index của index | 73 |\n| 52 | First-level / Top-level | Cấp 1 / Đỉnh | Cấp gốc / Cấp top fit 1 block | 73 |\n| 53 | ISAM | — | Indexed Sequential Access Method | 74 |\n| 54 | Search tree | Cây tìm kiếm | Multi-level index dạng cây | 75 |\n| 55 | Order p | Bậc p | Mỗi node có tối đa p tree pointers | 77 |\n| 56 | B-tree | Cây B | Dynamic, data ptr ở mọi level | 79 |\n| 57 | B+-tree | Cây B+ | Data ptr CHỈ ở leaf, leaf linked qua P_next | 81 |\n| 58 | Internal node | Nút nội | Node không phải leaf | 83 |\n| 59 | Leaf node | Nút lá | Node cuối | 83 |\n| 60 | P_next | Con trỏ kế | Pointer sang leaf kế tiếp (B+-tree) | 83 |\n\n---\n\n","file":"materials/DB-Chapter8.md","section":8},{"id":"c8-09","group":"c8","kind":"source","title":"Tổng Kết — Những Điểm Khả Năng Cao Ra Thi","markdown":"## Tổng Kết — Những Điểm Khả Năng Cao Ra Thi\n\n### Trắc nghiệm\n1. **Phân biệt 3 loại index** (Primary / Clustering / Secondary) — bảng 18.2.\n2. **bfr và b** từ R, B, r.\n3. **Block accesses** cho linear (b/2), binary (log₂ b), index (log₂ bᵢ + 1), multilevel (số level).\n4. **RAID levels** — RAID 0/1/5/6 đặc trưng.\n5. **B-tree vs B+-tree** — vị trí data pointer.\n6. **Dense vs Sparse** — định nghĩa, ứng dụng.\n7. **External hashing** — collision resolution.\n\n### Tự luận\n1. Tính chi phí truy vấn (số block accesses) với/không có index.\n2. Xây primary index: tính bfrᵢ, bᵢ, block accesses.\n3. Multilevel index: tính số level, chi phí search.\n4. Vẽ index entry table cho data file cho trước.\n5. So sánh ưu/nhược hashed vs ordered vs heap.\n\n### Bẫy hay gặp (đã liệt kê chi tiết ở \"Sai Lầm Thường Gặp\")\n- Lẫn lộn **block pointer (P=6)** vs **record pointer (P_R=7)** trong tính kích thước index entry.\n- Quên làm tròn: `bfr = ⌊B/R⌋` (xuống), `b = ⌈r/bfr⌉` (lên).\n- Quên **+1** khi tính search qua index (đọc thêm data block).\n- Secondary on key bắt buộc **DENSE**.\n- Primary và Clustering: chỉ 1 trên mỗi file; Secondary thì nhiều bao nhiêu cũng được.\n\n---\n\n","file":"materials/DB-Chapter8.md","section":9},{"id":"c8-10","group":"c8","kind":"source","title":"Đáp án Tự Kiểm Tra","markdown":"## Đáp án Tự Kiểm Tra\n\n### Section 1.1\n1. **Track** (vật lý) = vòng tròn đồng tâm. **Sector** (vật lý) = cung của track. **Block** (logic, thường = 1 sector) = đơn vị transfer. **Cylinder** (logic) = tập track cùng bán kính trên các mặt.\n2. DBMS biết trước kích thước transfer → đơn giản hoá buffer management, đảm bảo I/O atomic. Cho user chọn tự do sẽ phá hỏng mọi assumption.\n3. File trên 1 cylinder duy nhất nhanh hơn nhiều — 1 seek ban đầu rồi đọc tuần tự. File trên 100 cylinder phải seek 100 lần. So sánh Ex4(g): consecutive 67.5ms vs random 875ms.\n\n### Section 1.2\n1. R=300, B=1024, r=10,000: bfr = ⌊1024/300⌋ = 3; b = ⌈10,000/3⌉ = 3334. % lãng phí = 124/1024 ≈ **12.1%**.\n2. **Spanned**: R lớn (gần/vượt B), variable-length, tận dụng tối đa đĩa quan trọng hơn parsing. **Unspanned**: fixed-length, B≫R, tốc độ parse quan trọng.\n3. R=60, B=512: bfr=8, b=⌈5000/8⌉ = **625 blocks**.\n\n### Section 1.3\n1. Xóa vật lý cần dịch chuyển nhiều record → cực đắt. Đánh dấu chỉ cập nhật 1 bit. REORGANIZE định kỳ mới xóa vật lý.\n2. **FIND**: tìm từ đầu file (record đầu thoả). **FINDNEXT**: tiếp từ current. Dùng FIND mở đầu vòng lặp, FINDNEXT trong lặp.\n\n### Section 1.4\n1. b=2500. **Heap linear**: 1250. **Ordered binary**: ⌈log₂ 2500⌉ = 12. **Hashed (no collision)**: 1.\n2. Hashed dùng h(K) → 2 key kề nhau (Salary 25000 và 25001) hash ra 2 bucket *bất kỳ*, không kề nhau → range query phải scan toàn bộ buckets. Hashed *cực tốt cho equality*, *vô dụng cho range*.\n3. **Open addressing**: collision → tìm ô trống *kế tiếp* trong cùng bảng. **Chaining**: collision → đặt vào overflow location riêng, set pointer từ bucket gốc.\n\n### Section 1.5\n1. **RAID 4 vs RAID 5**: cả 2 đều block-level striping. RAID 4 có **1 đĩa parity riêng** (bottleneck khi ghi). RAID 5 **rải parity** lên tất cả → không bottleneck.\n2. RAID 0 chỉ striping, không parity → mất bất kỳ 1 disk = mất toàn bộ data. Production-critical không chấp nhận risk này.\n3. **DAS**: storage gắn trực tiếp 1 server qua SATA/SAS — chỉ server đó dùng. **SAN**: storage là node trên mạng fiber channel, nhiều server cùng truy cập, gắn/tháo linh hoạt, tách xa tới 10 km.\n\n### Section 2.2\n1. **Primary nondense** vì file ordered → có block anchor đại diện cả block. **Secondary on key dense** vì data file unordered → không có anchor có nghĩa; phải có entry cho mỗi record.\n2. Vì cả 2 đòi data file *ordered* trên indexing field, mà file chỉ ordered theo *một* field (không thể đồng thời sort theo Ssn và Dno).\n3. Nếu file đã ordered theo Dno → **Clustering Index trên Dno** (1 entry/distinct Dno, hiệu quả vì record cùng Dno nằm cạnh nhau). Nếu file ordered theo Ssn → **Secondary Index trên Dno** (Option 3 nondense).\n4. Dense secondary on Ssn: Rᵢ = 9+7 = 16. bfrᵢ = 32. bᵢ = ⌈30,000/32⌉ = **938 blocks**.\n\n### Section 2.3\n1. Two-level: level 2 = ⌈295/34⌉ = ⌈8.68⌉ = **9 blocks**. Search ≈ 1 (top) + 1 (base) + 1 (data) = **3 access** nếu top fit 1 block; hoặc ⌈log₂ 9⌉ + 1 + 1 = 4 + 1 + 1 = 6 nếu phải binary search top.\n2. Mỗi level là ordered file → insert vào giữa cần dịch chuyển record. Worse: phải maintain consistency cascading qua các level. Mỗi insert ở first-level có thể trigger update ở second-level nếu block đầy/anchor đổi.\n3. Multilevel có thể tạo trên **bất kỳ loại** first-level (Primary, Clustering, Secondary). **Điều kiện**: first-level phải có > 1 block.\n\n### Section 2.4\n1. Để (a) đảm bảo cây balanced (cao log_q b), (b) fanout đủ lớn → cây thấp, (c) cho phép insert mà không restructure ngay (còn chỗ trống half-full → full).\n2. **B+-tree nhanh hơn rõ rệt**. Leaf nodes của B+-tree có P_next → tạo linked list → tìm 30000 ở leaf → duyệt linked list cho đến 50000 → 1 lần descend cây + scan leaves. B-tree không có P_next → phải duyệt cây nhiều lần cho mỗi key trong range.\n3. Entry trong internal node B+-tree chỉ có (K, tree_pointer) — nhỏ. So với B-tree internal (K, data_pointer, tree_pointer) — to hơn. Cùng block size, B+-tree fit nhiều entry hơn → fanout q lớn hơn → cây thấp hơn.\n\n---\n\n","file":"materials/DB-Chapter8.md","section":10},{"id":"c8-11","group":"c8","kind":"source","title":"Mối Quan Hệ Với Các Chương Khác và Liên Hệ Lab/BTL","markdown":"## Mối Quan Hệ Với Các Chương Khác và Liên Hệ Lab/BTL\n\n### Chương trước (Chương 7 — FD & Normalization)\n- Chương 7 dạy *thiết kế bảng đúng* (3NF, BCNF) để giảm redundancy.\n- Chương 8 trả lời: sau khi đã có bảng đúng, **lưu xuống đĩa và truy vấn nhanh thế nào**.\n- Kết nối: Normalization tốt → ít redundancy → query phức tạp hơn (cần JOIN) → cần index để tránh JOIN chậm.\n\n### Chương sau (Query Processing & Transactions — học sau CO2013)\n- Sau Chương 8, học **Query Optimization** (DBMS lựa chọn index/scan/join algorithm).\n- **Transactions, Concurrency, Recovery** — Chương 8 cung cấp nền: block, double buffering, log file (RAID 1 cho log), B+-tree cho concurrent access.\n\n### Liên hệ Lab / BTL\n\n| Lab/BTL | Dùng kiến thức Chương 8 ở đâu? |\n|---|---|\n| **Lab 1** (thiết kế bảng, insert data) | Hiểu *bfr* để ước lượng dung lượng table. Lúc tạo PRIMARY KEY trong `CREATE TABLE`, DBMS tự tạo Primary Index. |\n| **Lab 2** (viết SQL queries) | `EXPLAIN PLAN` cho thấy DBMS dùng index nào — biết Chương 8 giúp đọc kế hoạch. Tối ưu query bằng cách tạo Secondary Index hợp lý trên field hay query (vd `Salary`, `Dno`). |\n| **BTL1** (`BTL1_DB_Lab/`) — ER → Mapping → SQL | Lúc tạo bảng có thể thêm `CREATE INDEX idx_emp_dno ON EMPLOYEE(Dno);` — đó chính là Secondary Index. Phải biết: nếu Dno đã được ordered (Clustering), thì index khác kiểu. |\n| **BTL2** (`BTL2_DB_Lab/`) — DB lớn hơn, performance | PostgreSQL/MySQL B-tree index thật **chính là** kiến trúc Section 2.4 trong chương này. `CREATE INDEX … USING btree` mặc định = B+-tree. Hashed index có sẵn (`USING hash`) nhưng *không hỗ trợ range query* — đúng như Section 1.4.6. |\n\n### Câu cuối — Ý nghĩa thực tiễn\nSau khi học Chương 8, bạn có thể giải thích vì sao cùng query `SELECT * FROM EMPLOYEE WHERE Ssn=?` chạy mili-giây trên 1 triệu hàng (vì có B+-tree index trên Ssn), nhưng `SELECT * FROM EMPLOYEE WHERE LOWER(Name) LIKE '%john%'` quét cả bảng (LIKE prefix `%…` không dùng được B+-tree).\n\n---\n\n","file":"materials/DB-Chapter8.md","section":11},{"id":"c8-12","group":"c8","kind":"source","title":"Câu hỏi/giả thiết còn mở (cần xác minh khi đi học)","markdown":"## Câu hỏi/giả thiết còn mở (cần xác minh khi đi học)\n\n- **Công thức `btt`**: tài liệu này dùng `btt = B / tr` với `tr` tính theo **useful capacity** (Elmasri Appendix B) → `btt = 1.25 msec` cho disk Exercise 4. Nếu giảng viên HCMUT yêu cầu dùng **raw capacity** (`tr = 512 byte/msec`), thì `btt = 1.0 msec` và mọi đáp án Ex4/Ex5 cần điều chỉnh tương ứng. Hỏi giảng viên hoặc tham khảo lời giải trong slide để xác nhận.\n- **Two-level Exercise 3** (slide 93): đề chỉ ghi \"If we make it into a multilevel index (two levels)\" — lời giải có thể là 3 access (nếu coi top level fit 1 block và đọc tuần tự) hoặc 5 access (binary search top level). Bản tổng hợp này dùng 5 — kiểm tra lại với slide đáp án nếu giảng viên cung cấp.\n","file":"materials/DB-Chapter8.md","section":12},{"id":"guide-8","group":"c8","kind":"guide","title":"Storage & Indexing","markdown":"# 08 · Storage và index: tính đúng đơn vị\n\n> Đọc cùng **DB-Chapter8.md**. Mọi công thức dưới đây là mô hình bài tập; không dùng chúng như benchmark của SSD hoặc DBMS thực tế.\n\n![B+ tree: internal separators và các lá liên kết](../docs/assets/bplus.svg)\n\n## Bài tính xuyên suốt\n\nFile có `r=30.000` record, mỗi record `R=100 B`, block `B=4096 B`. Record unspanned, bỏ qua header và pointer liên kết.\n\n$$bfr=\\lfloor4096/100\\rfloor=40,\\quad b=\\lceil30000/40\\rceil=750.$$\n\nMỗi block thừa 96 byte, nhưng block cuối còn có thể chưa đầy. Nếu spanned và không có overhead thì `ceil(rR/B)=733` block. Thêm header hoặc pointer làm thay đổi dung lượng hữu dụng; không trừ pointer hai lần.\n\n## Không có index thì đọc bao nhiêu block?\n\nHeap linear search tìm một record tồn tại và phân bố đều: kỳ vọng xấp xỉ b/2 = 375 block; worst case 750. Không tìm thấy phải quét hết. Binary search trên **file được sắp theo khóa tìm** mất cỡ ceil(log2 750)=10 block theo mô hình đếm của bài; chi tiết cộng/trừ một lần đọc phụ thuộc cách đặt giả thiết.\n\nBinary search không áp dụng cho heap chỉ vì cột tìm kiếm là primary key. Key là ràng buộc logic; thứ tự vật lý là chuyện khác.\n\n## Tạo sparse primary index\n\nKey 8 byte, block pointer 8 byte, entry 16 byte. Một index block chứa `floor(4096/16)=256` entry. Sparse primary index có một entry cho mỗi data block, nên 750 entry chiếm `ceil(750/256)=3` block. Mức trên của multilevel index có 3 entry, chiếm 1 block.\n\nNếu không cache: đọc root index, một index block ở mức dưới, rồi data block = **3 block accesses**. Nếu root được cache, số physical I/O có thể giảm; không tự động trừ đi khi đề chưa nói.\n\n| Loại index theo giáo trình | File được sắp theo trường đó? | Entry điển hình |\n|---|---|---|\n| Primary | Có, ordering key | Một block anchor mỗi data block |\n| Clustering | Có, ordering nonkey | Một entry mỗi giá trị phân biệt, trỏ tới cluster |\n| Secondary | Không theo trường index | Dense theo record hoặc key + bucket/posting list |\n\n“Primary index” ở bảng này không đồng nghĩa mọi index DBMS tạo cho PRIMARY KEY. SQLite và PostgreSQL có thiết kế lưu trữ riêng; đọc thuật ngữ theo ngữ cảnh.\n\n## B+ tree: lá mới chứa các data entries trong mô hình chuẩn\n\nInternal node giữ separator và child pointers. Tìm bằng cách đi từ root xuống đúng nhánh. Lá được nối để range scan duyệt liên tiếp sau khi tìm lá đầu tiên. B-tree thông thường có thể giữ data pointer cả ở node trong. Quy ước **order** khác nhau giữa giáo trình, nên khi tính sức chứa cần bắt đầu từ kích thước entry/pointer thay vì nhớ một con số p không có định nghĩa.\n\nVới internal fan-out p, key V và pointer P:\n\n$$(p-1)V+pP\\le B.$$\n\nVới leaf có q cặp key–record-pointer và một next-leaf-pointer:\n\n$$q(V+P_r)+P_{next}\\le B.$$\n\nĐây là hai công thức khác nhau. Nếu đề cho occupancy 69% hoặc header, phải đưa vào mô hình rõ ràng.\n\n## Index trong thực tế: đo kế hoạch, không đo niềm tin\n\n```bash\npython tools/index_demo.py\n```\n\nScript sinh 20.000 hàng, chạy `EXPLAIN QUERY PLAN` trước/sau tạo index và xác nhận kết quả truy vấn như nhau. Nó in thời gian tham khảo nhưng không assert “phải nhanh gấp N lần”: cache, dữ liệu nhỏ và phần cứng làm thời gian biến động.\n\nIndex giúp đọc trong các điều kiện phù hợp, nhưng cần không gian và chi phí cập nhật. Cột có ít giá trị không tự động vô dụng: độ chọn lọc của predicate, covering index, phân bố và kế hoạch đều quan trọng.\n\n## RAID và giới hạn mô hình\n\nRAID 0 striping không dự phòng; RAID 1 mirroring; RAID 5 chịu lỗi một đĩa; RAID 6 hai đĩa theo mô hình chuẩn. RAID 10 chịu được nhiều lỗi tùy vị trí các đĩa hỏng. **RAID không thay thế backup**: xóa nhầm hoặc mã độc có thể được phản ánh ngay trên các bản sao.\n\n## Bài tập\n\n1. Tính lại bfr, b khi có pointer liên kết 8 byte/block.\n2. Secondary dense index 30.000 entry, mỗi entry 16 byte, chiếm bao nhiêu block?\n3. Đọc ba mức index và data block, khi chưa cache, tốn bao nhiêu accesses?\n\n<details><summary>Lời giải</summary>\n\n1. `floor((4096−8)/100)=40`; b=750. Không phải mọi overhead đều làm thay đổi floor ở cùng một bộ số.\n2. `ceil(30000/256)=118` block (giả sử entry không spanned, không header).\n3. 4. Phân biệt số mức index với tổng số block đọc.\n\n</details>\n","file":"lessons/08-storage.md"},{"id":"final-00","group":"final","kind":"source","title":"📚 TÓM TẮT LÝ THUYẾT DATABASE SYSTEMS (CO2013) — FULL ĐIỂM CUỐI KỲ HK252","markdown":"## 📚 TÓM TẮT LÝ THUYẾT DATABASE SYSTEMS (CO2013) — FULL ĐIỂM CUỐI KỲ HK252\n\n> **Mục tiêu:** Đọc 1 file duy nhất này là đủ để **đi thi được điểm 10** trắc nghiệm — viết để **dễ coi và dễ hệ thống hoá lại kiến thức một cách tổng quát**, **bao quát hết toàn bộ kiến thức** của môn (toàn bộ 8 lecture chính + nhóm slide \"Security & Advanced topics\" + Tutorial 8 chương + 2 PDF VoTien), đối chiếu với **đề thi 4 năm gần nhất** (HK191, HK192, HK202, HK211, F2024/HK241) và **bộ QUIZ 1–10 trên BK-LMS** (`Final/Important/`) đã có đáp án đúng — nguồn dự đoán sát nhất.\n>\n> **📣 Cấu trúc đề (theo thông báo chính thức của thầy — `Final/Important/Nội dung ôn thi`):** **50 câu trắc nghiệm**, **thi OPEN-BOOK** (được mang tài liệu in: sách, vở, ghi chú). Vì open-book → file này tối ưu để **tra nhanh (Ctrl+F)**: mỗi định nghĩa có dòng `🔑 Keywords (EN)`, mỗi công thức có **Worked example** giải từng bước, mỗi chương có bảng so sánh + bẫy MCQ.\n>\n> | # | Chủ đề | Số câu | Ưu tiên học |\n> |---|---|---|---|\n> | 1 | Database System Overview | 5 | ④ |\n> | 2 | **ERD & EERD** | **10** 🔥🔥 | ① LỚN NHẤT |\n> | 3 | Relational Mapping | 5 | ⑤ |\n> | 4 | Relational Algebra | 4 | ⑦ |\n> | 5 | **SQL** | **9** 🔥🔥 | ② |\n> | 6 | Functional Dependencies & Normalization | 6 🔥 | ③ |\n> | 7 | Data Storage & Indexing | 4 | ⑥ |\n> | 8 | Database Security | 3 | ⑨ |\n> | 9 | Advanced Topics | 4 | ⑧ |\n>\n> **Cách dùng (open-book):**\n> 1. Ghi nhớ **§0 Quick Reference Card** (công thức + notation) và **§0bis Golden Rules** (quy tắc loại đáp án) — đây là 2 mục cứu nguy.\n> 2. Học theo trọng số: **§2 (10) → §5 (9) → §6 (6) → §1 (5) → §3 (5) → §4 (4) → §7 (4) → §9 (4) → §8 (3)**.\n> 3. Mỗi chương: đọc keyword EN (bôi đậm) → làm Worked example → đọc \"🎯 MCQ Traps\".\n> 4. Đêm trước thi: ôn **§10 Câu thần chú** + **§11 \"If you see X → think Y\"**; in sẵn **§0 + §0bis + §11** để tra trong phòng thi.\n\n---\n\n","file":"materials/DB-Final.md","section":0},{"id":"final-01","group":"final","kind":"source","title":"📑 MỤC LỤC","markdown":"## 📑 MỤC LỤC\n\n| § | Chủ đề | Nguồn chính | Số câu |\n|---|---|---|---|\n| 0 | Quick Reference Card (formulas + notation) | — | tổng hợp |\n| 0bis | Golden Rules giải trắc nghiệm (cross-chương) | — | 8 quy tắc |\n| 1 | Database System Overview | Lecture 00 + 01 · QUIZ 1 | 5 |\n| 2 | ERD & EERD | Lecture 02 + 03 · QUIZ 2,3 | 10 🔥🔥 |\n| 3 | Relational Mapping | Lecture 04 · QUIZ 4 | 5 |\n| 4 | Relational Algebra | Lecture 05 · QUIZ 5 | 4 |\n| 5 | SQL | Lecture 06 + Advanced SQL + Exercises · QUIZ 6,7 | 9 🔥🔥 |\n| 6 | Functional Dependencies & Normalization | Lecture 07 + VoTien/Normalization · QUIZ 8,9 | 6 🔥 |\n| 7 | Data Storage & Indexing | Lecture 08 + Indexing + VoTien/Storage · QUIZ 10 | 4 |\n| 8 | Database Security | `6_DatabaseSecurity_v2` · QUIZ 10 | 3 |\n| 9 | Advanced Topics | Data Warehouse, Distributed DB, NoSQL, Neo4j, Cassandra, Data Anonymization | 4 |\n| 10 | Câu thần chú trước khi vào phòng thi | — | 70+ |\n| 11 | \"If you see X → think Y\" + Disputed answer keys | — | speed-recap |\n| 12 | Mẹo làm bài MCQ (open-book) | — | 8 mẹo |\n| 13 | Checklist trước khi vào phòng thi | — | ≥15 mục |\n| 14 | Kết luận + chiến lược 3 ngày | — | — |\n\n---\n\n# §0. QUICK REFERENCE CARD\n\n> In riêng trang này mang vào phòng thi (open-book). Mọi công thức + notation cốt lõi gom 1 chỗ.\n\n","file":"materials/DB-Final.md","section":1},{"id":"final-02","group":"final","kind":"source","title":"0.1. Formula sheet — phải thuộc lòng","markdown":"## 0.1. Formula sheet — phải thuộc lòng\n\n```\n─── STORAGE & INDEXING ───\nbfr  = ⌊B / R⌋                          (unspanned blocking factor)\nb    = ⌈r / bfr⌉                        (số block lưu r record)\nbfr  = ⌊(B − p) / R⌋                    (unspanned + linked, p = pointer)\nb    = ⌈(r × R) / B⌉                    (spanned, continuous)\nb    = ⌈(r × R) / (B − p)⌉              (spanned, non-continuous)\n\n─── SEARCH COST (số block access) ───\nHeap linear search avg          = b/2          worst = b\nOrdered file binary search      = ⌈log₂ b⌉\nHashed file (no collision)      = 1\nIndex access (single level)     = ⌈log₂ bᵢ⌉ + 1   (+1 = data block)\nMultilevel index                = L + 1            (L = số mức index)\n\n─── INDEX ENTRY COUNTS ───\nindex_entry  = field_size + block_pointer\nindex_bfr    = ⌊B / index_entry⌋\nindex_blocks = ⌈#entries / index_bfr⌉\nPrimary index   #entries = #data blocks         (sparse; field KEY + file ordered)\nClustering index #entries = #distinct values    (file ordered theo NON-key)\nSecondary (key) #entries = #records             (dense; field non-ordering)\n\n─── RELATIONAL ALGEBRA CARDINALITY ───\n|σ_c(R)| ≤ |R| ;  |π_L(R)| ≤ |R| (loại trùng) ;  |R × S| = |R|·|S|\ndegree(R × S) = degree(R) + degree(S)\n|RA result (π)| ≤ |SQL result (no DISTINCT)|\n\n─── DECOMPOSITION (NJB / lossless test) ───\n{R1, R2} lossless ⇔  (R1 ∩ R2) → (R1 − R2) ∈ F⁺   HOẶC  (R1 ∩ R2) → (R2 − R1) ∈ F⁺\n```\n\n","file":"materials/DB-Final.md","section":2},{"id":"final-03","group":"final","kind":"source","title":"0.2. NF decision tree (BẮT BUỘC nhớ)","markdown":"## 0.2. NF decision tree (BẮT BUỘC nhớ)\n\n```\n1NF:  Mọi ô có giá trị atomic (không tổ hợp, không đa trị, không nested)\n       ▼\n2NF:  1NF + KHÔNG có partial FD (nonprime phụ thuộc đầy đủ vào MỌI candidate key)\n       Quy tắc nhanh: nếu MỌI CK chỉ 1 thuộc tính → tự động đạt 2NF\n       ▼\n3NF:  2NF + ∀ FD X→A non-trivial:  X là superkey  HOẶC  A là prime (không transitive qua nonprime)\n       ▼\nBCNF: ∀ FD X→A non-trivial:  X PHẢI là superkey  (nghiêm hơn 3NF)\n       BCNF có thể MẤT dependency preservation; luôn lossless join\n```\n\n| Vi phạm từ → | Dấu hiệu |\n|---|---|\n| 1NF → 2NF | Có FD `Y→A`, `Y` là **tập con thực sự** của một CK, `A` nonprime (partial) |\n| 2NF → 3NF | Có FD `X→A`, `X` không superkey, `A` nonprime (transitive) |\n| 3NF → BCNF | Có FD `X→A`, `X` không superkey **nhưng** `A` lại là prime |\n\n> ⚠️ **Báo dạng chuẩn THẤP nhất đạt được.** Vi phạm 2NF → dạng chuẩn cao nhất là **1NF** (kể cả khi cũng vi phạm 3NF).\n\n","file":"materials/DB-Final.md","section":3},{"id":"final-04","group":"final","kind":"source","title":"0.3. ER notation cheatsheet","markdown":"## 0.3. ER notation cheatsheet\n\n```\n▭      Strong entity            ▭▭   Weak entity (double rect)\n◇      Relationship             ◇◇   Identifying relationship (double diamond)\n○      Attribute (oval)         ⊙    Multivalued (double oval)\n◌      Derived (dashed oval)    A̲    Key (gạch chân)\n═══    Total participation      ───  Partial participation\n1,N,M  Cardinality ratio        (m,n) min–max (structural) notation\n〔d〕  Disjoint specialization   〔o〕 Overlapping\n〔U〕  Category (union type)     ──△ IS-A (subclass)\n```\n\n","file":"materials/DB-Final.md","section":4},{"id":"final-05","group":"final","kind":"source","title":"0.4. 3 loại Index — bảng vàng","markdown":"## 0.4. 3 loại Index — bảng vàng\n\n| Loại index | File ordered? | Field key? | # entry | Dense/Sparse | Max/1 file |\n|---|---|---|---|---|---|\n| **Primary** | Yes (theo PK) | Yes (PK) | **= # block** | sparse | **1** |\n| **Clustering** | Yes (theo non-key) | No | **= # distinct values** | sparse | **1** |\n| **Secondary (key)** | No | Yes (CK khác) | **= # record** | **dense** | nhiều |\n| **Secondary (non-key)** | No | No | bucket / dense | dense | nhiều |\n\n> **Quy tắc vàng:** 1 file CHỈ có **1 Primary HOẶC 1 Clustering** (1 thứ tự vật lý), nhưng **nhiều Secondary**.\n\n","file":"materials/DB-Final.md","section":5},{"id":"final-06","group":"final","kind":"source","title":"0.5. SQL logical execution order","markdown":"## 0.5. SQL logical execution order\n\n```\nFROM → ON/JOIN → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT\n```\n\n> WHERE lọc **tuple** (trước aggregate); HAVING lọc **nhóm** (sau aggregate). Cột GROUP BY không thấy alias của SELECT (SELECT chạy sau).\n\n","file":"materials/DB-Final.md","section":6},{"id":"final-07","group":"final","kind":"source","title":"0.6. CAP Theorem (3 chọn 2)","markdown":"## 0.6. CAP Theorem (3 chọn 2)\n\n| Chữ | Tên | Nghĩa |\n|---|---|---|\n| **C** | Consistency | Mọi node thấy cùng phiên bản dữ liệu mới nhất |\n| **A** | Availability | Mọi request đều có response (không treo) |\n| **P** | Partition tolerance | Vẫn chạy khi mạng phân vùng |\n\n> Distributed thực tế **P bắt buộc** → chọn **CP** (MongoDB, HBase) hoặc **AP** (Cassandra, DynamoDB). **CA** chỉ có ở DB centralized.\n\n","file":"materials/DB-Final.md","section":7},{"id":"final-08","group":"final","kind":"source","title":"0.7. ACID vs BASE","markdown":"## 0.7. ACID vs BASE\n\n| | ACID (SQL) | BASE (NoSQL) |\n|---|---|---|\n| A | **Atomicity** | **Basically Available** |\n| C | **Consistency** | (drop / Soft state) |\n| I | **Isolation** | **Soft state** |\n| D | **Durability** | **Eventually consistent** |\n\n> ⚠️ **Bẫy kinh điển:** \"**Accuracy**\" KHÔNG thuộc ACID — `A = Atomicity`.\n\n","file":"materials/DB-Final.md","section":8},{"id":"final-09","group":"final","kind":"source","title":"0.8. Magic numbers / hằng số phải thuộc","markdown":"## 0.8. Magic numbers / hằng số phải thuộc\n\n| Hằng số | Giá trị / nội dung |\n|---|---|\n| Block size B / Pointer p | thường 512B hoặc 4096B / 6B (block ptr), 4B (record ptr) |\n| 3-schema (ANSI/SPARC) | External / Conceptual / Internal |\n| Armstrong axioms | IR1 Reflexivity, IR2 Augmentation, IR3 Transitivity (+ Union, Decomposition, Pseudotransitivity) |\n| 4 dạng chuẩn cơ bản | 1NF / 2NF / 3NF / BCNF (+ 4NF MVD, 5NF PJNF) |\n| 4 mô hình access control | DAC / MAC / RBAC / ABAC |\n| 4 loại NoSQL | Key-Value / Document / Wide-Column / Graph |\n| Cardinality ratio | 1:1, 1:N, M:N · (min,max): (0,1),(1,1),(0,N),(1,N) |\n| Bell-LaPadula | no read-up, no write-down → Confidentiality |\n\n---\n\n# §0bis. GOLDEN RULES GIẢI TRẮC NGHIỆM (áp cho MỌI chương)\n\n> Áp dụng **cơ học** trước khi đọc đáp án. Đây là phần \"cứu nguy\" khi gặp câu lạ.\n\n### 0bis.1 — Dịch đề thành điều kiện kỹ thuật TRƯỚC khi đọc đáp án\n- \"all projects\" ≠ \"at least one project\"; \"controlled by Research\" (`Project.Dnum`) ≠ \"employee belongs to Research\" (`Employee.Dno`).\n- FD: **đừng đoán key bằng mắt — tính closure `X⁺`**.\n- Storage: xác định câu hỏi đang hỏi **record / block / index entry / index block / block access** — đây là các con số khác nhau.\n\n### 0bis.2 — \"does NOT do / không tham gia\" = phép trừ tập hợp (set difference)\nMẫu: *nhân viên không làm project nào*, *khách không đăng ký*. Công thức:\n```\nπ_X(AllObjects)  −  π_X(ObjectsThatDoTheAction)\n```\nHai vế của `−` phải **union-compatible** (cùng số cột, cùng kiểu, cùng ý nghĩa cột).\n\n### 0bis.3 — Natural join `*` chỉ nối cột **trùng tên**\nBẫy kinh điển trong schema COMPANY — các cặp cột liên quan nhưng **khác tên** ⇒ natural join trần là SAI:\n```\nPROJECT.Dnum ≠ DEPARTMENT.Dnumber ;  EMPLOYEE.SSN ≠ WORKS_ON.ESSN ;  WORKS_ON.Pno ≠ PROJECT.Pnumber\n```\nSửa: dùng theta/equi-join có điều kiện `⋈_{Dnum=Dnumber}` hoặc `ρ`-rename cột trước.\n\n### 0bis.4 — Đáp án quá tuyệt đối thường SAI\nNghi ngờ: *\"all SQL systems cannot…\"*, *\"NoSQL always…\"*, *\"SQL never…\"*, *\"tất cả các đáp án còn lại\"*. Trừ định nghĩa cứng, câu tuyệt đối hầu hết là bẫy.\n\n### 0bis.5 — Bẫy \"đúng khái niệm, sai chủ thể\" (right concept, wrong subject)\n\"only managers can change\" đúng là **Integrity**, nhưng nếu đáp án ghi *\"Integrity for passengers\"* thì sai vì sai chủ thể. Luôn hỏi: **tính chất này áp cho actor nào trong đề?**\n\n### 0bis.6 — Bẫy least-privilege (đặc quyền tối thiểu)\nMột câu lệnh đúng cú pháp nhưng cấp **quá nhiều quyền** → sai. Cấp toàn bộ `Employee` cho user chỉ cần phòng 1 = over-privileged. Đáp án security ưu tiên **least privilege**.\n\n### 0bis.7 — Bẫy \"giữ sai số dòng / bỏ mất cột\"\n- \"tất cả nhân viên nhưng giấu lương\" → phải **mask giá trị** (CASE/UNION), KHÔNG `WHERE`-lọc bỏ dòng.\n- View lọc đúng dòng nhưng chỉ `SELECT SSN` là sai khi đề cần full thông tin nhân viên.\n\n### 0bis.8 — Bẫy NULL (3-valued logic)\n`= NULL` và `<> NULL` hầu như luôn sai → dùng `IS NULL` / `IS NOT NULL`. SQL là 3 trị: TRUE / FALSE / **UNKNOWN**. `CHECK (X > 1)` KHÔNG chặn NULL (vì `NULL > 1` = UNKNOWN, không phải FALSE).\n\n---\n\n","file":"materials/DB-Final.md","section":9},{"id":"final-10","group":"final","kind":"source","title":"§1. DATABASE SYSTEM OVERVIEW — Trọng số đề: 5 câu","markdown":"## §1. DATABASE SYSTEM OVERVIEW — Trọng số đề: 5 câu\n\n---\n\n### 1.1 Data, Information, Knowledge\n\n**Data** (dữ liệu): các sự kiện thô, chưa xử lý — ví dụ: `30`, `\"Nguyễn Văn A\"`, `\"HCM\"`.\n\n**Information** (thông tin): dữ liệu đã được xử lý, có ngữ cảnh, mang ý nghĩa — ví dụ: *\"Sinh viên Nguyễn Văn A, 30 tuổi, ở HCM\"*.\n\n**Knowledge** (tri thức): thông tin đã được diễn giải, kết hợp với kinh nghiệm để ra quyết định.\n\n> Chuỗi: **Data → (processing/context) → Information → (interpretation/experience) → Knowledge**\n\n🔑 **Keywords (EN):** **raw facts**, **meaningful information**, **knowledge**, **data processing**\nBẫy: Data chưa xử lý ≠ Information; Information ≠ Knowledge.\n\n---\n\n### 1.2 Database, DBMS và Database System\n\n| Khái niệm | Định nghĩa ngắn | Ví dụ |\n|---|---|---|\n| **Database** | Tập hợp dữ liệu có liên quan, được tổ chức có cấu trúc, phản ánh một side of the real world | Tập hợp hồ sơ sinh viên của HCMUT |\n| **DBMS** | Phần mềm cho phép định nghĩa, xây dựng, thao tác và chia sẻ database | Oracle, MySQL, PostgreSQL, MongoDB |\n| **Database System** | Database + DBMS + Application programs + Users (textbook); một số slide dùng bản hẹp hơn: Database + DBMS software — nếu đề trích nguyên văn slide, cả hai đều được chấp nhận | Toàn bộ hệ thống quản lý sinh viên |\n| **Database Application** | Chương trình tương tác với database qua DBMS | Web app tra cứu điểm |\n\n🔑 **Keywords (EN):** **database**, **DBMS** (Database Management System), **database system**, **define, construct, manipulate, share**\nBẫy: DBMS ≠ Database; Database System bao gồm cả DBMS lẫn Database lẫn ứng dụng.\n\n---\n\n### 1.3 Metadata và System Catalog\n\n**Metadata** = \"data about data\" — mô tả cấu trúc, kiểu dữ liệu, ràng buộc của database.\n\n**System Catalog** (còn gọi **Data Dictionary**): nơi DBMS lưu trữ metadata. Bản thân DBMS dùng catalog để xử lý truy vấn.\n\nVí dụ metadata: tên bảng `STUDENT`, tên cột `StudentID INT PRIMARY KEY`, ràng buộc `NOT NULL`.\n\n🔑 **Keywords (EN):** **metadata**, **system catalog**, **data dictionary**, **self-describing nature of a database system**\nBẫy: Metadata lưu trong system catalog, không phải trong data files thông thường.\n\n---\n\n### 1.4 Schema vs State (Snapshot / Instance)\n\n| | Schema | State / Instance / Snapshot |\n|---|---|---|\n| **Là gì?** | Mô tả cấu trúc database (tên bảng, cột, kiểu, ràng buộc) | Dữ liệu thực tế tại một thời điểm |\n| **Thay đổi?** | Hiếm thay đổi (DDL) | Thay đổi liên tục (DML) |\n| **Còn gọi** | Intension, database schema | Extension, database state, snapshot, instance |\n| **Ví dụ** | `STUDENT(ID, Name, GPA)` | 500 dòng trong bảng STUDENT vào ngày 01/06/2026 |\n\n**Schema Diagram** = a displayed schema — biểu diễn trực quan của schema (ví dụ: sơ đồ ER, bảng cột trong công cụ thiết kế).\n\n🔑 **Keywords (EN):** **schema (intension)**, **database state / instance / snapshot (extension)**, **schema evolution**, **schema diagram**\nBẫy: *Instance* (một occurrence cụ thể) ≠ *Schema*; Schema thay đổi qua **schema evolution** (hiếm), còn state thay đổi mỗi khi có insert/update/delete.\n\n---\n\n### 1.5 File-Processing System — Vấn đề và Khi nào vẫn dùng\n\n**Vấn đề của file-processing approach:**\n- **Data redundancy & inconsistency**: dữ liệu trùng lặp ở nhiều file.\n- **Data isolation**: dữ liệu phân tán, khó truy cập tổng hợp.\n- **Integrity problems**: khó ràng buộc nhất quán.\n- **Atomicity problems**: không đảm bảo giao dịch toàn vẹn.\n- **Concurrent-access anomalies**: nhiều user cùng ghi gây lỗi.\n- **Security problems**: khó kiểm soát truy cập chi tiết.\n\n**Shared File Approach** — bước trung gian giữa file-processing và full database: file/dữ liệu được **chia sẻ** giữa nhiều ứng dụng, giúp giảm redundancy và inconsistency. Tuy nhiên, phát sinh 3 vấn đề mới:\n- **Rigid data structure**: cấu trúc dữ liệu không uyển chuyển, khó thay đổi schema.\n- **Physical data dependency**: ứng dụng phụ thuộc vào cách dữ liệu được lưu trữ vật lý.\n- **No concurrency control support**: không có cơ chế kiểm soát truy cập đồng thời.\n\n**Khi nào file-processing vẫn chấp nhận được?**\n- Ứng dụng đơn giản, dữ liệu ít, chỉ một người dùng.\n- Không cần truy vấn phức tạp hay chia sẻ đồng thời.\n- Overhead của DBMS vượt lợi ích (embedded systems, log files đơn giản).\n\n🔑 **Keywords (EN):** **data redundancy**, **data inconsistency**, **data isolation**, **integrity constraint**, **atomicity**, **concurrent access**, **security**, **shared file approach**, **rigid data structure**, **physical data dependency**\n\n---\n\n### 1.6 Database Approach — Lợi ích so với File Processing\n\n| Lợi ích | Giải thích |\n|---|---|\n| **Self-describing** | Metadata lưu trong catalog, hệ thống tự mô tả |\n| **Insulation between programs and data** | Program-data independence |\n| **Data abstraction** | Ẩn chi tiết lưu trữ, cung cấp conceptual view; bao gồm cả **program-data independence** và **program-operation independence** |\n| **Multiple views** | Mỗi user thấy một view phù hợp |\n| **Sharing & multiuser transaction processing** | Concurrency control, ACID transactions |\n| **Enforcing integrity constraints** | DBMS kiểm tra tự động |\n| **Backup & recovery** | DBMS cung cấp cơ chế phục hồi |\n| **Reduced development time** | Không phải viết lại I/O code |\n| **Up-to-date data sharing** | Trạng thái real-time luôn được cập nhật và chia sẻ đồng thời giữa nhiều user (ví dụ: thông báo chỗ ngồi còn trống) |\n\n🔑 **Keywords (EN):** **program-data independence**, **program-operation independence**, **data abstraction**, **multiple views of data**, **multiuser transaction processing**, **backup and recovery**, **up-to-date with data sharing**\nBẫy: Khi đề mô tả tình huống \"nhiều user chia sẻ trạng thái real-time luôn cập nhật\" → chọn **\"up-to-date with data sharing\"**, KHÔNG phải \"multiple views\".\n\n---\n\n### 1.7 3-Schema Architecture (ANSI/SPARC)\n\n```\n┌─────────────────────────────────────┐\n│   EXTERNAL LEVEL (External Schemas) │  ← Views cho từng user/group\n├─────────────────────────────────────┤\n│   CONCEPTUAL LEVEL (Conceptual      │  ← Cấu trúc logic toàn bộ DB\n│          Schema)                    │     (entities, relationships, constraints)\n├─────────────────────────────────────┤\n│   INTERNAL LEVEL (Internal Schema)  │  ← Cách lưu trữ vật lý\n│                                     │     (indexes, file org, storage)\n└─────────────────────────────────────┘\n```\n\n- **External schema** (= *subschema* = **view level**): mỗi user group thấy một phần/biến thể của DB. \"External level\" và \"View level\" là hai thuật ngữ tương đương.\n- **Conceptual schema**: mô tả TOÀN BỘ cấu trúc logic, ẩn chi tiết lưu trữ.\n- **Internal schema**: mô tả physical storage — file tổ chức thế nào, index nào tồn tại.\n\n**Logical Data Independence**: có thể thay đổi conceptual schema mà không phải sửa external schemas (khó thực hiện hơn).\n\n**Physical Data Independence**: có thể thay đổi internal schema (cách lưu, index) mà không phải sửa conceptual schema (dễ thực hiện hơn, DBMS hiện đại hỗ trợ tốt).\n\n🔑 **Keywords (EN):** **3-schema architecture**, **external / conceptual / internal schema**, **view level**, **logical data independence**, **physical data independence**, **ANSI/SPARC**\nBẫy: Physical independence = thay đổi **internal** không ảnh hưởng **conceptual**. Logical independence = thay đổi **conceptual** không ảnh hưởng **external**. Logical independence **khó đạt** hơn physical. **External level = View level** — hai tên cùng một tầng.\n\n---\n\n### 1.8 DDL, DML, DCL, TCL\n\n| Loại | Tên đầy đủ | Mục đích | Ví dụ lệnh |\n|---|---|---|---|\n| **DDL** | Data Definition Language | Định nghĩa schema, cấu trúc | `CREATE`, `ALTER`, `DROP` |\n| **DML** | Data Manipulation Language | Thao tác dữ liệu | `SELECT`, `INSERT`, `UPDATE`, `DELETE` |\n| **DCL** | Data Control Language | Phân quyền truy cập | `GRANT`, `REVOKE` |\n| **TCL** | Transaction Control Language | Quản lý giao dịch | `COMMIT`, `ROLLBACK`, `SAVEPOINT` |\n\n- **Procedural DML**: người dùng chỉ định **how** (cách lấy) — ví dụ: relational algebra.\n- **Non-procedural DML** (declarative): người dùng chỉ định **what** (cần gì) — ví dụ: SQL `SELECT`.\n- **4GL (Fourth-Generation Language)**: ngôn ngữ non-procedural thế hệ 4 — bao gồm SQL, QBE (Query By Example), application generators, report generators.\n\n🔑 **Keywords (EN):** **DDL**, **DML**, **DCL**, **TCL**, **procedural vs non-procedural (declarative) DML**, **high-level / low-level DML**, **4GL**, **QBE**\nBẫy: **Không phải mọi DML đều non-procedural** — relational algebra là procedural DML. SQL là non-procedural. Đề hay hỏi \"SQL thuộc loại nào?\" → **Non-procedural / declarative DML**.\n\n---\n\n### 1.9 Database Design Process\n\n```\nRequirements Collection & Analysis\n          ↓\n  Conceptual Design  ←── DBMS-INDEPENDENT (dùng ER/EER model)\n          ↓\n    Logical Design   ←── DBMS-INDEPENDENT (mapping → relational schema)\n          ↓             (một số tài liệu coi bước này cũng DBMS-independent)\n   Physical Design   ←── DBMS-DEPENDENT (chọn index, file org, storage params)\n          ↓\n     Implementation\n```\n\n- **Conceptual Design**: tạo **conceptual schema** bằng **high-level data model** (ER diagram). **DBMS-independent**.\n- **Logical Design** (= data model mapping): chuyển sang mô hình DBMS muốn dùng (relational). Thường vẫn DBMS-independent với mức relational.\n- **Physical Design**: xác định cấu trúc lưu trữ, index, partitioning. **DBMS-dependent**.\n\n🔑 **Keywords (EN):** **requirements analysis**, **conceptual design**, **logical design**, **physical design**, **DBMS-independent**, **high-level data model**, **ER model**\nBẫy: Conceptual design là DBMS-independent — chưa cần biết dùng Oracle hay MySQL. Physical design mới phụ thuộc DBMS.\n\n---\n\n### 1.10 Data Models — Phân loại\n\n| Loại | Đặc điểm | Ví dụ | Level ánh xạ |\n|---|---|---|---|\n| **High-level / Conceptual data models** | Gần cách con người nghĩ, dùng trong thiết kế | ER model, EER model, UML | Conceptual + External level |\n| **Representational / Implementation / Record-based data models** | Dùng trong DBMS thực tế; cấu trúc dạng records | Relational, Network, Hierarchical | Conceptual + some physical |\n| **Low-level / Physical data models** | Mô tả dữ liệu lưu trên disk | Record formats, storage structures | Internal level |\n| **Object-based data models** | Tích hợp OOP | Object-oriented, Object-relational | Conceptual + External level |\n| **Self-describing data models** | Schema + data cùng chỗ | XML, JSON, NoSQL (key-value, document) | — |\n\n**Lịch sử 3 thế hệ DBMS:**\n- **1st generation**: Hierarchical model & Network model.\n- **2nd generation**: **Relational model** (SQL-based DBMS).\n- **3rd generation**: Object-relational & Object-oriented DBMS.\n\n🔑 **Keywords (EN):** **conceptual / high-level data model**, **representational / implementation / record-based data model**, **low-level / physical data model**, **ER model**, **relational model**, **object-based**, **self-describing**, **1st / 2nd / 3rd generation DBMS**\nBẫy: \"Relational model thuộc thế hệ mấy?\" → **2nd generation**. Tên đầy đủ đúng của nhóm Relational/Network/Hierarchical là **record-based** (không chỉ \"representational\").\n\n---\n\n### 1.11 Data Model Terminology (ER vs Relational)\n\n| Khái niệm | ER Model | Relational Model |\n|---|---|---|\n| Tập đối tượng | Entity type | Relation (table) |\n| Một đối tượng cụ thể | Entity instance | Tuple (row) |\n| Thuộc tính | Attribute | Attribute (column) |\n| Kiểu thuộc tính | Domain | Domain |\n| Liên kết | Relationship type | Foreign key / join |\n\n🔑 **Keywords (EN):** **entity**, **attribute**, **relationship**, **tuple**, **relation**, **domain**, **entity type vs entity instance**\n\n---\n\n### 1.12 DBA, Database Designer và Các Vai Trò Trong DB Environment\n\n| Vai trò | Trách nhiệm chính |\n|---|---|\n| **DBA** (Database Administrator) | Cài đặt/cấu hình DBMS; cấp quyền; monitor hiệu năng; backup & recovery; security policy |\n| **Database Designer** | Xác định data (entities, attributes, relationships); thiết kế schema conceptual + logical; **phân tích nhu cầu lưu trữ dữ liệu** (storage-requirements analysis) |\n| **Application Programmers** | Viết và bảo trì các chương trình ứng dụng tương tác với database qua DBMS |\n| **End Users** | Người dùng cuối — truy cập và sử dụng database thông qua application hoặc trực tiếp |\n\n- DBA chịu trách nhiệm **toàn bộ hệ thống** sau khi deploy.\n- Database Designer làm việc chủ yếu trong **giai đoạn thiết kế** (trước khi deploy).\n- **Storage-requirements analysis** là nhiệm vụ của Database Designer / requirements analyst, **không phải** DBA.\n\n🔑 **Keywords (EN):** **DBA**, **database designer**, **application programmers**, **end users**, **authorization**, **performance tuning**, **schema design**, **storage requirements analysis**\nBẫy: \"Phân tích nhu cầu lưu trữ dữ liệu\" → **Database Designer**, không phải DBA. Có 4 vai trò chính trong DB environment, không chỉ 2.\n\n---\n\n### 1.13 DBMS Components\n\nCác thành phần chính của một DBMS:\n\n1. **DDL Compiler** — biên dịch DDL statements, cập nhật system catalog.\n2. **Query Compiler / Optimizer** — parse và tối ưu hóa truy vấn.\n3. **Runtime Database Processor** — thực thi truy vấn tối ưu, xử lý DML.\n4. **Transaction Manager** — concurrency control + recovery.\n5. **Storage Manager / Buffer Manager** — quản lý I/O giữa disk và memory.\n6. **System Catalog / Data Dictionary** — lưu metadata.\n\n🔑 **Keywords (EN):** **query compiler**, **query optimizer**, **runtime database processor**, **transaction manager**, **storage manager**, **buffer manager**, **system catalog**\n\n---\n\n### 1.14 Controlled-Access Subsystems (5 loại) và Data Management Framework\n\nDBMS cung cấp controlled access qua các subsystem:\n\n| Subsystem | Chức năng |\n|---|---|\n| **Security subsystem** | Kiểm soát ai được đọc/ghi gì (authentication + authorization) |\n| **Integrity subsystem** | Kiểm tra integrity constraints khi cập nhật |\n| **Concurrency control subsystem** | Đảm bảo nhất quán khi nhiều user truy cập đồng thời |\n| **Recovery subsystem** | Khôi phục database sau sự cố |\n| **Catalog / Data Dictionary subsystem** | Lưu và cung cấp truy cập metadata |\n\n**Data Management Systems Framework — 3 tầng:**\n\n| Tầng | Nội dung |\n|---|---|\n| **Tầng 1 — DB Technologies** | DB Systems, Distributed DB |\n| **Tầng 2 — Interoperability & Migration** | Heterogeneous DB, Client/Server, Multimedia, Legacy systems |\n| **Tầng 3 — Information Extraction & Sharing** | Data Warehousing, Data Mining, Internet DB |\n\n🔑 **Keywords (EN):** **security**, **integrity**, **concurrency control**, **backup and recovery**, **data dictionary / catalog**, **data warehousing**, **data mining**, **heterogeneous DB**, **distributed DB**\nBẫy: Đề hay hỏi \"DBMS provides controlled access through which subsystems?\" — liệt kê đủ 5.\n\n---\n\n### 1.15 Worked Example — Câu hỏi thực từ QUIZ/MCQ\n\n**Câu hỏi (QUIZ 1 style):** Phát biểu nào sau đây MÔ TẢ ĐÚNG về sự khác nhau giữa Schema và State của một database?\n\nA. Schema là dữ liệu thực tế; State là cấu trúc của database.\nB. Schema mô tả cấu trúc database (ít thay đổi); State là dữ liệu thực tế tại một thời điểm (thay đổi thường xuyên).\nC. Schema và State đều thay đổi mỗi khi có INSERT.\nD. State được lưu trong System Catalog.\n\n**Phân tích từng bước:**\n1. Schema = structure description (intension) → hiếm thay đổi, chỉ thay đổi qua DDL.\n2. State/Instance/Snapshot = actual data (extension) → thay đổi mỗi khi có DML.\n3. System Catalog lưu **schema** (metadata), không lưu state.\n4. → Đáp án: **B**.\n\nBẫy: Nhiều bạn nhầm \"instance\" = một bản cài đặt DBMS; ở đây \"instance\" = một database state tại thời điểm cụ thể.\n\n---\n\n### 1.16 Worked Example — 3-Schema và Data Independence\n\n**Câu hỏi (MCQ-01 style):** Thêm một cột vào bảng STUDENT ở conceptual schema mà không làm ảnh hưởng đến các view (external schemas) hiện có — đây là ví dụ về loại independence nào?\n\n**Phân tích:**\n1. Thay đổi xảy ra ở **conceptual level**.\n2. External schemas **không bị ảnh hưởng**.\n3. Conceptual → External = **Logical Data Independence**.\n4. → Đáp án: **Logical Data Independence**.\n\nBẫy: Nếu thay đổi là ở internal schema (thêm index) mà conceptual không đổi → **Physical Data Independence**.\n\n---\n\n### 🎯 MCQ Traps §1\n\n1. 🔥 **\"Database System\" ≠ DBMS** — Database System = Database + DBMS + Applications + Users.\n2. 🔥 **SQL là non-procedural DML** — không phải mọi DML đều non-procedural (relational algebra = procedural).\n3. 🔥 **Physical data independence dễ đạt hơn Logical** — đề thường hỏi cái nào \"harder to achieve\" → Logical.\n4. 🔥 **Conceptual design là DBMS-independent** — Physical design mới phụ thuộc DBMS cụ thể.\n5. 🔥 **Metadata lưu trong System Catalog**, không phải trong data files.\n6. **Schema = intension (structure)** / **State = extension (data)** — \"instance\" = một state cụ thể, không phải bản cài DBMS.\n7. **File-processing approach vẫn OK** khi ứng dụng đơn giản, single-user, không cần chia sẻ hay truy vấn phức tạp — đề hay hỏi \"khi nào file-processing là lựa chọn hợp lý?\"\n8. **External schema = subschema = view level** — cùng một khái niệm, ba tên khác nhau.\n9. **DDL** định nghĩa schema; **DML** thao tác data — `CREATE TABLE` là DDL, `INSERT` là DML.\n10. 🔥 **3-schema architecture mục đích chính**: đạt **data independence** (cả logical lẫn physical), cho phép **multiple views**, ẩn chi tiết lưu trữ khỏi người dùng.\n11. 🔥 **\"Up-to-date with data sharing\"** là benefit riêng biệt — khi đề mô tả nhiều user chia sẻ trạng thái real-time luôn cập nhật (vd: chỗ ngồi còn trống) → chọn benefit này, KHÔNG phải \"multiple views\".\n12. 🔥 **\"Phân tích nhu cầu lưu trữ\" → Database Designer**, không phải DBA — DBA quản lý hệ thống sau deploy, Designer phân tích và thiết kế trước deploy.\n13. **Shared File Approach**: giảm redundancy nhưng PHÁT SINH `rigid data structure` + `physical data dependency` + `no concurrency control` — đề hỏi \"problem cần giải quyết\" → chọn một trong 3 này.\n14. **Relational model = 2nd generation DBMS** — 1st gen: Hierarchical & Network; 3rd gen: Object-relational & OO.\n15. **DB environment có 4 vai trò**: DBA, Database Designer, Application Programmers, End Users — không chỉ 2.\n\n---\n\n### 🪄 Câu thần chú §1\n\n- 🔥 *\"Database System = DB + DBMS + App + Users — không phải chỉ DBMS.\"*\n- 🔥 *\"Schema = bản vẽ, State = ngôi nhà thực tế đang xây.\"*\n- 🔥 *\"3-schema: External (ai thấy gì) → Conceptual (có gì) → Internal (lưu thế nào).\"*\n- 🔥 *\"Physical independence: đổi cách lưu → conceptual không đổi. Logical independence: đổi conceptual → external không đổi. Logical khó hơn.\"*\n- *\"Conceptual design không cần biết DBMS. Physical design mới cần.\"*\n- *\"Metadata = data về data → lưu trong System Catalog (Data Dictionary).\"*\n- 🔥 *\"SQL = non-procedural (what). Relational algebra = procedural (how).\"*\n- *\"File-processing OK khi: đơn giản, single-user, không chia sẻ, không truy vấn phức tạp.\"*\n- *\"DBMS controlled access = Security + Integrity + Concurrency + Recovery + Catalog.\"*\n- 🔥 *\"DBA giữ hệ thống sống; Designer tạo ra schema — hai vai trò khác nhau.\"*\n- *\"Shared File: chia sẻ tốt hơn file riêng, nhưng rigid structure + physical dependency + no concurrency control.\"*\n- *\"Relational = 2nd gen. 1st = Hierarchical/Network. 3rd = Object-relational/OO.\"*\n- 🔥 *\"External level = View level — hai tên, một tầng.\"*\n- 🔥 *\"Real-time shared state → 'up-to-date with data sharing', không phải 'multiple views'.\"*\n- *\"Data abstraction = program-data independence + program-operation independence.\"*\n\n---\n\n","file":"materials/DB-Final.md","section":10},{"id":"final-11","group":"final","kind":"source","title":"§2. ERD & EERD — Trọng số đề: 10 câu 🔥🔥","markdown":"## §2. ERD & EERD — Trọng số đề: 10 câu 🔥🔥\n\n> Nguồn: `Lectures/02_ER Model.pdf` · `Lectures/03_EER Model.pdf` · `Tutorial/DB-Chapter2.md` · `DB-Chapter3.md`\n> Tập trung: Fan/Chasm trap · Weak entity · Cardinality vs Participation (trục độc lập) · Shared subclass vs Category · 4 tổ hợp Specialization · Attribute types · Recursive · Counting rule |Sup|=|Sub1|+|Sub2|\n\n---\n\n### 2.1 Quy trình thiết kế CSDL (Database Design Process) — 5 phases\n\n| Phase | Output | DBMS? |\n|---|---|---|\n| **Requirements collection & analysis** | Data requirements + Functional requirements | — |\n| **Conceptual design** | **Conceptual schema = ERD/EERD** | **DBMS-independent** |\n| **Choice of DBMS** | Chọn DBMS phù hợp | — |\n| **Logical design** (\"data model mapping\") | Database schema (relational tables…) | **DBMS-specific** |\n| **Physical design** | Storage structures, file org, **indexes, access paths** | DBMS-specific |\n\n🔑 **Keywords (EN):** **conceptual database design**, **DBMS-independent**, **high-level data model**, **data model mapping**, **storage structures and access paths** (= physical, NOT conceptual).\n\n> 🔥 **MCQ Trap:** \"Xác định storage structures and access paths\" → **Physical design**, KHÔNG phải Conceptual. Thứ tự chuẩn: Requirements → Conceptual → **Choice of DBMS** → Logical → Physical. \"Choice of DBMS\" phải **sau** Conceptual (vì Conceptual là DBMS-independent) và **trước** Logical. *(QUIZ 2 Q1, Q3 — 100%)*\n\n> 🔥 **MCQ Trap:** **Functional design (phân tích chức năng phần mềm) và DB structural design (thiết kế cấu trúc CSDL) chạy SONG SONG và ĐỘC LẬP nhau** — đáp án \"parallel + independent\", KHÔNG phải \"parallel + related\". *(HK211mock Q12)*\n\n---\n\n### 2.2 Entity / Entity Type / Entity Set\n\n```\nEntity      = đối tượng cụ thể, tồn tại độc lập (John Smith, Research Dept)\nEntity Type = lớp/template (EMPLOYEE, DEPARTMENT)\nEntity Set  = tập tất cả instance của entity type tại một thời điểm\n```\n\n🔑 **Keywords (EN):** **entity**, **entity type**, **entity set**, **independent existence**.\n\nKhi nào nên mô hình là entity (không phải attribute)? → Khi đối tượng: tồn tại độc lập, có nhiều thuộc tính, nhiều instance, tham gia nhiều relationship, được tham chiếu bởi entity khác.\n\n> 🔥 **MCQ Trap:** Danh từ KHÔNG tự động là entity — nếu chỉ là property đơn giản của entity khác thì nên là attribute.\n\n---\n\n### 2.3 Attribute — 5 loại + Complex + Value Set\n\n| Loại | Ký hiệu ERD | Ví dụ | Đặc điểm |\n|---|---|---|---|\n| **Simple / Atomic** | Oval thường | `Ssn`, `Sex` | Không chia nhỏ trong phạm vi bài |\n| **Composite** | Oval cha + oval con | `Name{Fname, Minit, Lname}` | Chia thành component; equivalent với từng atomic riêng |\n| **Multivalued** | Oval **viền đôi** | `[[Phones]]`, `[[Locations]]` | Một entity có nhiều giá trị |\n| **Derived** | Oval **viền đứt** | `(Age)` từ `Bdate`, `(CloseDate)` | Tính được, thường **không lưu** trong DB |\n| **Complex** | Composite + multivalued | `{Phone(Country, Number)}` | Vừa có cấu trúc, vừa nhiều giá trị |\n\n**Value set (= domain)** = tập giá trị hợp lệ của attribute. Không phải chỉ các giá trị đang có trong data.\n\n🔑 **Keywords (EN):** **simple**, **composite**, **multivalued** (double oval), **derived** (dashed oval), **complex**, **value set**, **stored attribute** (attribute lưu thật sự, đối nghĩa với derived).\n\nTừ khóa nhận diện trong đề:\n- Multivalued: *\"one or many …\", \"multiple …\", \"list of …\", \"several …\"*\n- Derived: *\"determined from\", \"computed from\", \"calculated by\", \"based on details\"*\n\n> 🔥 **MCQ Traps:**\n> - **Derived KHÔNG lưu** trong DB. *(QUIZ 2 Q4 — CloseDate = derived)*\n> - **Multivalued ≠ Composite**: oval đôi ≠ oval cha-con.\n> - **Composite ≡ hai atomic riêng biệt** về mặt semantics (equivalence — QUIZ 2 Q9).\n> - \"list of conditions\", \"list of privileges\" → **multivalued**. *(QUIZ 2 Q8)*\n\n---\n\n### 2.4 Key Attribute\n\n```\nKey attribute = attribute (hoặc tập attribute) định danh duy nhất entity trong entity set.\nCandidate keys: có thể nhiều. ERD underline TẤT CẢ candidate keys (không chỉ PK).\n```\n\n| Candidate | OK? | Lý do |\n|---|---|---|\n| SSN | ✅ | Unique nationwide |\n| Full name | ❌ | Nhiều người trùng tên |\n| Phone numbers | ❌ | Multivalued, không stable |\n| Transaction number per branch | ❌ | Chỉ unique cục bộ trong branch |\n\n🔑 **Keywords (EN):** **key attribute**, **candidate key**, **uniqueness constraint**, **unique over the full modeling scope**.\n\n> 🔥 **MCQ Trap:** Underline **TẤT CẢ** candidate keys trong ERD, không chỉ 1. *(H202 Q33)* — Ví dụ DEPARTMENT có cả `Name` và `Number` đều là key. *(QUIZ 2 Q10)*\n\n---\n\n### 2.5 Relationship Type / Instance / Degree / Recursive\n\n```\nRelationship Type    = WORKS_FOR (liên kết giữa EMPLOYEE và DEPARTMENT)\nRelationship Instance = \"John Smith works_for Research Dept\" = 1 record cụ thể\nDegree              = số entity type tham gia\n```\n\n| Degree | Tên | Ví dụ |\n|---|---|---|\n| 1 | **Unary / Recursive** | EMPLOYEE supervises EMPLOYEE |\n| 2 | **Binary** | EMPLOYEE works_for DEPARTMENT |\n| 3 | **Ternary** | Customer submits LoanApplication at Branch |\n| n | n-ary | — |\n\n🔑 **Keywords (EN):** **relationship type**, **relationship instance**, **degree**, **binary**, **ternary**, **recursive (unary) relationship**, **role names**.\n\n> 🔥 **MCQ Traps:**\n> - **Degree = số entity type tham gia**, KHÔNG phải số attribute của relationship. *(H211 Q53)*\n> - **Recursive relationship BẮT BUỘC có role names** (Supervisor / Subordinate). *(H211)*\n> - **Ternary KHÔNG luôn thay được bằng 3 binary** — tách có thể mất thông tin. *(H202 Q40)*\n> - **Cùng 2 entity type có thể có ≥ 2 relationship type** (WORKS_FOR vs MANAGES). *(Slides)*\n> - **≥ 2 relationship type có thể tồn tại giữa CÙNG cặp entity** → không bị cấm.\n\n**Đọc cardinality chuỗi 3 entity:** Với ERD chuỗi nhiều entity (ví dụ: Curriculum — Grade — Subject), đọc cardinality **từng cạnh riêng biệt** (ví dụ: Curriculum 1:N Grade, Grade N:1 Subject → chuỗi N:N:1). Không rút gọn hay ghép tắt.\n\n**Relationship Attribute:** Attribute thuộc về relationship khi **chỉ có nghĩa cho cặp (A, B)**, không thuộc riêng A hay B.\n\n| Relationship | Attribute | Vì sao đặt trên hình thoi |\n|---|---|---|\n| `WORKS_ON(EMP, PROJ)` | `Hours` | Số giờ phụ thuộc cặp emp-proj |\n| `MANAGES(EMP, DEPT)` | `Start_date` | Ngày bắt đầu quản lý thuộc association |\n| `complains_to(Cust, Branch)` | `Content`, `Timestamp` | Nội dung/thời điểm thuộc lần complain *(QUIZ 2 Q7)* |\n| `gains(Cust, CreditType)` | `Timestamp` | Thời điểm khách được cấp credit type *(QUIZ 2 Q8)* |\n\n---\n\n### 2.6 Cardinality Ratio vs Participation Constraint — HAI TRỤC ĐỘC LẬP\n\n> ⚠️ Cardinality và Participation là **hai khái niệm hoàn toàn độc lập** — đừng nhầm.\n\n| Tiêu chí | **Cardinality Ratio** | **Participation Constraint** |\n|---|---|---|\n| Trả lời | Một instance liên hệ với tối đa **bao nhiêu** instance phía kia? | Tham gia relationship có **bắt buộc** không? |\n| Dạng | `1:1`, `1:N`, `M:N` | **Total** (phải) / **Partial** (tuỳ chọn) |\n| Ký hiệu | Số/chữ trên đường | Total = **đường đôi** (═══); Partial = đường đơn |\n| Từ khóa đề | \"one\", \"many\", \"at most one\", \"several\" | \"must\", \"at least one\" (total) / \"may\", \"optional\", \"some have none\" (partial) |\n| Nhãn slide | — | **Mandatory** (= total) / **Optional** (= partial) |\n\n🔑 **Keywords (EN):** **cardinality ratio** (1:1 / 1:N / M:N), **participation constraint**, **total participation** (double line, existence-dependent), **partial participation** (single line), **membership class**, **mandatory** (= total), **optional** (= partial).\n\n> 🔥 **MCQ Trap kinh điển:** \"1:N\" KHÔNG nói tham gia có bắt buộc hay không — chúng độc lập. \"Some excellent branches have no complaint\" → **partial participation** của Branch. *(QUIZ 2 Q7)*\n\n**Relationship attribute migrate khi nào?**\n\n| Cardinality | Migrate attribute sang bên nào? |\n|---|---|\n| **1:1** | Một trong 2 bên đều được |\n| **1:N** | **CHỈ phía N** (mỗi N instance gắn 1 entity phía 1) |\n| **M:N** | **KHÔNG migrate** — attribute phụ thuộc *từng cặp* (Hours BẮT BUỘC trên WORKS_ON) |\n\n---\n\n### 2.7 Min-Max Notation (Structural Constraint)\n\n> **Lưu ý thuật ngữ:** \"Structural constraint\" bao gồm **cả cardinality ratio lẫn participation** — không chỉ riêng min-max. Min-max notation là cách ký hiệu gộp cả hai vào một cặp `(min, max)`.\n\nDạng `(min, max)` — **thay thế hoàn toàn** cả cardinality ratio lẫn participation ký hiệu đường đôi/đơn.\n\n| Notation | Nghĩa | Participation |\n|---|---|---|\n| `(0, 1)` | tuỳ chọn, tối đa 1 | Partial |\n| `(1, 1)` | bắt buộc đúng 1 | Total |\n| `(0, N)` | tuỳ chọn, nhiều | Partial |\n| `(1, N)` | bắt buộc ít nhất 1, nhiều | Total |\n| `(4, N)` | bắt buộc ít nhất 4 | Total |\n\nRàng buộc toán học: `0 ≤ min ≤ max`, `max ≥ 1`.\n\n🔑 **Keywords (EN):** **min-max notation**, **structural constraint**, `(min, max)` constraint.\n\n**Ví dụ chuẩn:** `EMPLOYEE (1,1) — WORKS_FOR — (4,N) DEPARTMENT` → mỗi employee thuộc đúng 1 dept; mỗi dept có ít nhất 4 employees.\n\n---\n\n### 2.8 Weak Entity — Định nghĩa chính xác\n\n**Weak entity** = entity type **KHÔNG có key attribute của riêng nó** (no key attribute of its own), định danh nhờ:\n\n1. **Identifying owner** entity (entity mạnh) + **Identifying relationship** (◇◇, double diamond)\n2. **Partial key** (gạch chân **đứt**) — unique trong phạm vi owner\n3. **Full key = {owner\\_PK, partial\\_key}**\n\n| Thành phần | Ký hiệu ERD |\n|---|---|\n| Weak entity | Rectangle **đôi** |\n| Identifying relationship | Diamond **đôi** (◇◇) |\n| Partial key | Gạch chân **đứt** |\n| Participation phía weak | **LUÔN total** (double line) |\n\n🔑 **Keywords (EN):** **weak entity type**, **no key attribute of its own**, **partial key**, **identifying relationship**, **identifying owner**, **total participation**, **existence-dependent**.\n\n> 🔥 **MCQ Traps:**\n> - Weak entity **LUÔN total** phía weak trong identifying relationship. *(H211 Q3)*\n> - Weak entity có thể có **nhiều owner** (identifying relationship degree > 2). *(H192 Q31)*\n> - **Partial key một mình KHÔNG phải PK** — phải kết hợp với owner\\_PK.\n> - Mapping: FK nên có `ON DELETE CASCADE`.\n\n**Ví dụ COMPANY:** DEPENDENT là weak; owner = EMPLOYEE; identifying = DEPENDENTS\\_OF (◇◇); partial key = `Dependent_name`; PK = `(Essn, Dependent_name)`.\n\n**Ví dụ QUIZ 3 Q7 (Contract):** CONTRACT là weak entity (double rectangle), identified bởi ternary \"has\" relationship với STAR và STUDIO; CONTRACT M:N \"is used for\" MOVIE. *(QUIZ 3 Q7)*\n\n**Ví dụ QUIZ 3 Q11 (Bank Branch):** BANK `(1)—◇◇ has—(N)` BRANCH — BRANCH là weak entity; `Number` và `Name` đều là **partial keys** (dashed underline) trong phạm vi BANK. *(QUIZ 3 Q11)*\n\n---\n\n### 2.9 COMPANY Database — Ví dụ chuẩn phải thuộc\n\n**4 entity chính:**\n\n| Entity | Loại | Key |\n|---|---|---|\n| **EMPLOYEE** | Strong | `Ssn` |\n| **DEPARTMENT** | Strong | `Name` (CK), `Number` (CK) |\n| **PROJECT** | Strong | `Name` (CK), `Number` (CK) |\n| **DEPENDENT** | **Weak** | `(Essn, Dependent_name)` |\n\n**6 relationship chính:**\n\n| Relationship | Giữa | Cardinality | Participation | Attribute |\n|---|---|---|---|---|\n| **WORKS\\_FOR** | EMP — DEPT | N:1 | EMP total, DEPT partial | — |\n| **MANAGES** | EMP — DEPT | 1:1 | EMP partial, DEPT total | `Start_date` |\n| **CONTROLS** | DEPT — PROJ | 1:N | DEPT partial, PROJ **total** | — |\n| **WORKS\\_ON** | EMP — PROJ | M:N | Total cả 2 | `Hours` |\n| **SUPERVISION** | EMP — EMP (recursive) | 1:N | Partial cả 2 | roles: Supervisor/Subordinate |\n| **DEPENDENTS\\_OF** | EMP — DEPENDENT | 1:N (identifying) | DEPENDENT total | — |\n\n> 🔥 `Hours` BẮT BUỘC nằm trên WORKS\\_ON (M:N) — không migrate sang EMP hay PROJECT.\n\n---\n\n### 2.10 Connection Traps — ĐỀ NÀO CŨNG CÓ\n\n| Trap | Bản chất | Dấu hiệu nhận biết | Ví dụ | Cách sửa |\n|---|---|---|---|---|\n| **Fan trap** | Pathway qua entity trung tâm **mơ hồ** | ≥ 2 relationship **1:N** tỏa quạt từ 1 entity (1:N + 1:N từ cùng hub) | BRANCH→1:N→STAFF, BRANCH→1:N→PROPERTY → \"Staff nào phụ trách Property nào?\" = mơ hồ | Thêm relationship trực tiếp `STAFF OVERSEES PROPERTY` |\n| **Chasm trap** | Pathway **bị đứt** do partial participation | Có pathway nhưng ≥ 1 participation = partial ở giữa → tuple không match | BRANCH→1:N→STAFF, STAFF→**0:N**→PROPERTY → Property chưa assign = không tìm được Branch | Thêm relationship `PROPERTY LOCATED_AT BRANCH` hoặc đổi participation |\n\n🔑 **Keywords (EN):** **fan trap** (ambiguous pathway), **chasm trap** (broken pathway, partial/optional participation).\n\n**Ví dụ điển hình — QUIZ 3 Q19 (Chasm trap):**\n```\nBRANCH (Code,Name) ─M─ joins ─N─ PROJECT ─M─ is supported by ─N─ INVESTOR\n```\nCâu hỏi: \"Có tìm được Branch của Investor không?\"\n→ **KHÔNG** — đây là **chasm trap**: một investor có thể chưa tham gia \"is supported by\" → không nối được về Branch.\nĐáp án: **b** (chasm trap, không phải fan trap). *(QUIZ 3 Q19 — xác nhận 100%)*\n\n**Phân biệt Fan vs Chasm:**\n- **Fan** = ambiguity (đường đi không rõ đi theo nhánh nào).\n- **Chasm** = no path (đường đi bị đứt hoàn toàn).\n\n**Phân biệt Fan trap 1:N+1:N vs M:N+1:N:**\n\n> Fan trap định nghĩa **chính xác**: chỉ xảy ra khi cùng 1 entity là **hub của ≥ 2 nhánh 1:N** toả ra. Trường hợp **M:N + 1:N** (ví dụ: DesignStudio —M:N— Model —1:N— Product; hoặc Branch —M:N— Book —1:N— BookCopy) thì **không phải fan trap thuần** — đường đi vẫn có thể mơ hồ nhưng cơ chế khác (thiếu relationship trực tiếp). Cách giải quyết tương tự: thêm quan hệ trực tiếp hoặc restructure ERD. *(HK191 Q4, F2024 Q36)*\n\n---\n\n### 2.11 Đọc miniworld để vẽ ERD — Từ khóa ánh xạ\n\n| Từ trong đề | Quy ra ERD |\n|---|---|\n| Danh từ chính | **Entity** |\n| Tính chất / mô tả | **Attribute** |\n| Động từ / liên hệ | **Relationship** |\n| unique / identifier / code / SSN / number | **Key attribute** |\n| must / at least one | **Total participation** |\n| may / can / optional / some have none | **Partial participation** |\n| one or many / multiple / list of / several | **Multivalued attribute** |\n| computed / determined from / derived from / based on | **Derived attribute** |\n| uniquely in each X / numbered within X | **Partial key** (→ Weak entity) |\n\n---\n\n### 2.12 Semantic Constraints — Không vẽ được trong ERD\n\n**Semantic constraints** = ràng buộc **KHÔNG biểu diễn trực tiếp được trong ERD**; phải enforce bằng **trigger / application program / CHECK constraint / assertion**.\n\nVí dụ: `Age > 18`, `Manager salary > employee salary cùng phòng`, `Salary tăng ≤ 20%`.\n\n**Ràng buộc thời gian (time-based constraint):** Ràng buộc kiểu \"sau N ngày tự đổi trạng thái\" KHÔNG enforce được bằng trigger (trigger chỉ chạy theo DML event, không theo thời gian trôi qua), không enforce được bằng CHECK hay app validation thụ động → cần **tiến trình định thời (scheduled job / cron job)**. *(HK191 Q10)*\n\n🔑 **Keywords (EN):** **semantic constraint**, **trigger**, **application program**, **assertion**, **scheduled job** (time-based constraint).\n\n> 🔥 **MCQ Trap:** \"ERD không biểu diễn được ràng buộc nào?\" → **semantic constraint** — enforce bằng trigger/app code. Ràng buộc thời gian → **scheduled job**, không phải trigger.\n\n---\n\n### 2.13 UML Class Diagram (Alternative Notation)\n\n| ER | UML |\n|---|---|\n| Entity type | **Class** (3 ngăn: tên / attributes / operations) |\n| Entity instance | **Object** |\n| Relationship type | **Association** |\n| Relationship instance | **Link** |\n| Cardinality | **Multiplicity** `min..max` |\n| Không giới hạn max (= N) | **`*`** |\n| Weak entity | **Qualified association** |\n| Link attribute (M:N) | Box đính vào association bằng **đường đứt nét** |\n\n🔑 **Keywords (EN):** **UML class diagram**, **association**, **link**, **multiplicity**, `*` = no maximum.\n\n> 🔥 **MCQ Trap:** `*` = \"no maximum\" = N. Association ↔ relationship **type**; Link ↔ relationship **instance** — đừng đảo.\n\n---\n\n### 2.14 EER — Vì sao ER thuần chưa đủ\n\n```\nEMPLOYEE → SECRETARY / ENGINEER / TECHNICIAN / MANAGER\n```\nNhét hết vào EMPLOYEE → NULL nhiều. Tách hoàn toàn → lặp `Ssn`, `Name`, `Address`.\n\nEER thêm: **Subclass / Superclass + Specialization / Generalization + Inheritance + Shared subclass + Category (Union type)**.\n\n🔑 **Keywords (EN):** **EER (Enhanced Entity-Relationship)**, **subclass**, **superclass**, **IS-A**, **specialization** (top-down), **generalization** (bottom-up), **attribute inheritance**, **relationship inheritance**.\n\n---\n\n### 2.15 Subclass / Superclass / IS-A / Inheritance\n\n```\nENGINEER IS-A EMPLOYEE\nEMPLOYEE = superclass;  ENGINEER / SECRETARY / MANAGER = subclasses\nSubclass S ⊆ Superclass C (formal: S ⊆ C)\n```\n\nQuy tắc (theo Elmasri):\n- **R2:** Mọi subclass instance PHẢI tồn tại ở superclass trước. *(H211 Q43)*\n- **R5:** Superclass / subclass **LUÔN là 1:1**. *(Slides)*\n- Subclass kế thừa **TẤT CẢ attribute VÀ relationship** của superclass.\n- Subclass có thể có thêm **local attributes** (thuộc tính riêng) và **specific relationship types** (relationship riêng).\n- Entity KHÔNG thể chỉ tồn tại trong subclass.\n\n🔑 **Keywords (EN):** **subclass**, **superclass**, **IS-A relationship**, **attribute inheritance**, **relationship inheritance**, `S ⊆ C`, **local attributes**, **specific relationship types**, **class** (tên gọi chung cho entity type / superclass / subclass).\n\n> 🔥 **MCQ Trap:** \"An entity of a subclass is also one of the entities of its superclass.\" → **TRUE** (R2). *(QUIZ 3 Q6 — xác nhận 100%)*\n\n---\n\n### 2.16 Specialization vs Generalization\n\n| | **Specialization** | **Generalization** |\n|---|---|---|\n| Hướng | **Top-down** | **Bottom-up** |\n| Bắt đầu từ | Superclass | Nhiều entity types |\n| Kết quả | Subclasses | Superclass mới |\n| Vẽ trên diagram | **Giống nhau hoàn toàn** | **Giống nhau hoàn toàn** |\n\n**Mũi tên trong ký hiệu EER:** Slides đề cập có ký hiệu mũi tên (mũi tên hướng về superclass = generalization; hướng về subclass = specialization), tuy nhiên môn này **không dùng mũi tên** trong diagram (\"advocate not drawing any arrows\") — phân biệt qua ngữ cảnh mô tả.\n\n**\"Generalization is usually total\":** Vì superclass được suy ra TỪ các subclass (bottom-up) nên thường mọi superclass entity đều thuộc ít nhất 1 subclass → generalization thường **total**.\n\n🔑 **Keywords (EN):** **specialization** (top-down, subgroups), **generalization** (bottom-up, common descriptions), **inverse processes**.\n\n> 🔥 **MCQ Trap:** \"Generalization mặc định total\" (vì superclass được suy từ subclass). *(QUIZ 3 Q17 chính xác: Specialization = hỗ trợ mô tả/associations cụ thể hơn cho subgroup; Generalization = lấy common descriptions của nhiều entity types để tạo superclass mới)*\n\n---\n\n### 2.17 Predicate-defined / Attribute-defined / User-defined\n\n| Loại | Định nghĩa | Hệ quả |\n|---|---|---|\n| **Predicate-defined** (= **condition-defined**) | `S = C[predicate]` — entity thỏa điều kiện p | Có thể disjoint hoặc overlap |\n| **Attribute-defined** | Giá trị 1 attribute quyết định subclass (defining attribute) | **Implies disjoint** |\n| **User-defined** | User/app gán thủ công từng instance vào subclass | Có thể disjoint hoặc overlap |\n\n🔑 **Keywords (EN):** **predicate-defined** (= **condition-defined**), **attribute-defined** (defining attribute, implies disjoint), **user-defined**.\n\n---\n\n### 2.18 Disjoint vs Overlapping × Total vs Partial — 4 Tổ hợp\n\n> ⚠️ Hai trục **hoàn toàn độc lập** → 4 tổ hợp.\n\n| Constraint | Ký hiệu | Ý nghĩa |\n|---|---|---|\n| **Disjoint `d`** | vòng tròn chứa `d` | Superclass entity thuộc **tối đa 1** subclass |\n| **Overlapping `o`** | vòng tròn chứa `o` | Superclass entity có thể thuộc **nhiều** subclass |\n| **Total** | **double line** từ superclass → vòng tròn | **Mọi** superclass entity phải thuộc **≥ 1** subclass |\n| **Partial** | single line từ superclass → vòng tròn | Một số superclass entity có thể **không thuộc** subclass nào |\n\n> ⚠️ **Bẫy hình \"U-shape\":** Trong diagram, vòng tròn chứa chữ **`o`** (overlapping) có thể trông giống hình chữ U. Đây là ký hiệu **overlapping** của specialization (1 entity thuộc nhiều subclass) — **KHÁC HOÀN TOÀN** với ký hiệu **`∪`** của category/union type. Không nhầm hai ký hiệu này. *(QuizDB img9)*\n\n**4 tổ hợp:**\n\n| Tổ hợp | Ký hiệu | Ví dụ |\n|---|---|---|\n| **Disjoint + Total** | ═══ + `d` | PATIENT = Outpatient **hoặc** Inpatient (đúng 1, bắt buộc) *(QUIZ 3 Q4)* |\n| **Disjoint + Partial** | ─── + `d` | DRUG → TreatmentDrug/SpecialDrug/SupportingDrug (max 1, có thể chưa phân loại) *(QUIZ 3 Q5)* |\n| **Overlapping + Total** | ═══ + `o` | BOOK = Hardcopy/Softcopy (phải là ít nhất 1, có thể cả 2) *(QUIZ 3 Q3)* |\n| **Overlapping + Partial** | ─── + `o` | WAREHOUSE = Physical/e-Warehouse (có thể cả 2, có thể 1) *(QUIZ 3 Q2)* |\n\n🔑 **Keywords (EN):** **disjoint** `d` (at most one), **overlapping** `o` (may belong to several), **total** (double line, at least one), **partial** (single line, may belong to none).\n\n**Counting Rule (rất hay ra đề):**\n> **|Sup| = |Sub1| + |Sub2|** ⟺ **Total AND Disjoint** (total ngăn không có entity nào bị loại trừ; disjoint ngăn đếm trùng). *(QUIZ 3 Q13 — xác nhận 100%)*\n\n**Ứng dụng counting rule:**\n- **Total + Disjoint:** Mỗi entity Sup thuộc đúng 1 sub → |Sup| = |Sub1| + |Sub2|.\n- **Total + Overlapping:** Sup = Sub1 ∪ Sub2 nhưng Sub1 ∩ Sub2 có thể ≠ ∅ → |Sup| ≤ |Sub1| + |Sub2|. \"Có sách chỉ có softcopy\" → **TRUE** dưới Total+Overlapping. *(QUIZ 3 Q3 — xác nhận)*\n- **Partial + bất kỳ:** |Sup| > |Sub1| + |Sub2| (có entity không thuộc sub nào).\n\n> 🔥 **MCQ Trap:** \"Phòng học vs Phòng TN không thể vừa là vừa kia\" → **Disjoint(d)**. \"Mọi entity phải vào ít nhất 1 nhóm\" → **Total**. Hai điều kiện **độc lập**.\n\n**Worked Example — Hai specialization độc lập trên cùng superclass:**\n```\nEMPLOYEE có 2 specialization RIÊNG BIỆT:\n  Job-type (d): SECRETARY / TECHNICIAN / ENGINEER / MANAGER\n  Pay-type:     HOURLY_EMPLOYEE / SALARIED_EMPLOYEE\n```\nHai specialization chạy **độc lập** — một SECRETARY có thể đồng thời là HOURLY_EMPLOYEE. Mỗi specialization có ký hiệu d/o và total/partial riêng. *(QuizDB img22)*\n\n---\n\n### 2.19 Multiple Inheritance — Hierarchy vs Lattice — Shared Subclass\n\n```\nHierarchy = cây, mỗi subclass có đúng 1 superclass trực tiếp (single inheritance).\nLattice   = DAG, multiple inheritance.\n           STUDENT_ASSISTANT = subclass của EMPLOYEE ∩ STUDENT (shared subclass)\n```\n\n**Multiple inheritance (lattice):** Subclass kế thừa attribute của **direct superclass VÀ tất cả predecessor superclass**. Nếu attribute cùng gốc 1 superclass kế thừa qua nhiều đường → **chỉ tính 1 lần**.\n\n**Ví dụ chuẩn — QUIZ 3 Q1:**\n```\nPERSON\n  └─ o ─┬─ EMPLOYEE  ─ d ─┬─ STAFF / FACULTY / STUDENT_ASSISTANT\n        ├─ ALUMNUS         └─ RESEARCH_ASSISTANT / TEACHING_ASSISTANT\n        └─ STUDENT ─ d ─┬─ GRADUATE_STUDENT / UNDERGRAD / STUDENT_ASSISTANT\n```\nSuperclasses của RESEARCH\\_ASSISTANT = **Student\\_Assistant, Employee, Student, Person** (tất cả ancestors trên mọi đường kế thừa). *(QUIZ 3 Q1 — 100%)*\n\n🔑 **Keywords (EN):** **hierarchy** (single inheritance), **lattice** (multiple inheritance, DAG), **shared subclass** (AND, intersection, multiple inheritance).\n\n---\n\n### 2.20 Shared Subclass vs Category (Union Type) — DỄ NHẦM NHẤT\n\n> Đây là 1 trong những bẫy điểm cao nhất của §2.\n\n| Tiêu chí | **Shared Subclass (AND)** | **Category / Union type (OR)** |\n|---|---|---|\n| Logic | **AND** / intersection (∩) | **OR** / union (∪) |\n| Subset của | `S ⊆ D1 ∩ D2 ∩ … ∩ Dn` | `T ⊆ D1 ∪ D2 ∪ … ∪ Dn` (`n > 1`) |\n| Member phải thuộc | **TẤT CẢ** superclass | **CHỈ 1** trong các superclass |\n| Kế thừa từ | **Tất cả** superclass | **Chỉ 1** superclass mà nó thực sự thuộc |\n| Key superclass | Nên cùng key | **Có thể khác key** → bắt buộc **surrogate key** |\n| Số relationship | Nhiều IS-A riêng biệt | **Một** relationship với circle `∪` |\n| Ví dụ | `ENG_MGR ⊆ ENGINEER ∩ MANAGER ∩ SALARIED_EMP` | `OWNER ⊆ PERSON ∪ BANK ∪ COMPANY` |\n| Ký hiệu | Nhiều relationship riêng | Circle `∪` (circle-U) |\n\n🔑 **Keywords (EN):** **shared subclass** (AND, multiple inheritance, intersection), **category** / **union type** (OR, union), **surrogate key**, `n > 1` (điều kiện của category).\n\n> ⚠️ **Ký hiệu `o` vs `∪`:** Vòng tròn `o` trong specialization = **overlapping** (khác key); vòng tròn `∪` = **union/category**. Nhìn hình chữ U-shape trong diagram EER → kiểm tra kỹ: nếu là specialization thì là `o` (overlapping), không phải category. *(QuizDB img9)*\n\n**Subsets trong mô hình (QUIZ 3 Q9):**\n- Subclass (Sub1, Sub2) = **subsets** (⊆ superclass).\n- Category/union type (Uni) = **subset** (⊆ union của owners).\n- E1, E2 (owners của category) = **KHÔNG phải subsets** — chúng là owners.\n- **Đáp án: Sub1, Sub2, Uni** là subsets. E1, E2 không phải. *(QUIZ 3 Q9 — 100%)*\n\n**Category total/partial:**\n- **Total category** = **double line** vào **circle ∪** → mọi owner entity tham gia.\n- **Partial category** = **single line** vào **circle ∪** → chỉ một subset của union.\n\n| Ví dụ Category | Key các owner | Hệ quả mapping |\n|---|---|---|\n| `OWNER = PERSON ∪ BANK ∪ COMPANY` | **Khác key** | BẮT BUỘC **surrogate key** |\n| `REGISTERED_VEHICLE = CAR ∪ TRUCK` | **Cùng key** | Dùng key chung |\n\n> 🔥 **MCQ Traps:**\n> - **Shared = AND; Category = OR** — H191 Q6.\n> - Category total = double line vào **CIRCLE** (≠ double line vào subclass box như specialization total).\n> - Đếm relationship: Shared = subclass của *nhiều* IS-A riêng biệt mỗi cái 1 cha; Category = subclass của *một* relationship có *nhiều* cha.\n> - **Category giới hạn member trong đúng các owner type liệt kê** — khác partial specialization (không giới hạn).\n\n---\n\n### 2.21 Union type vs Specialization — Phân biệt ngữ nghĩa\n\n- **Category** `REGISTERED_VEHICLE = CAR ∪ TRUCK` → **CHỈ** car và truck mới có thể là member.\n- **Partial specialization** của `VEHICLE` → **KHÔNG loại trừ** các type khác (ví dụ: motorcycle vẫn là VEHICLE).\n\n**Ví dụ điển hình — QUIZ 3 Q12 (Self-study places):**\n> \"Self-study places are given from library rooms and class rooms. **Some** class rooms CANNOT be provided.\"\n> → SelfStudy ⊆ LibraryRoom ∪ ClassRoom → **Category (union type)**.\n> → \"Some class rooms cannot\" → không phải mọi phòng đều là self-study place → **Partial category**.\n> **Đáp án: Union type, partial category (d)**. *(QUIZ 3 Q12 — 100%)*\n\n**Ví dụ QUIZ 3 Q20 (Studying Room):**\n> Diagram gốc: STUDYING\\_ROOM ─── `d` ─┬─ CLASSROOM / LABORATORY (single line = partial disjoint)\n> Modeling nào có **cùng số entity** trong Studyingroom?\n> → Đáp án **f**: Category/union type Studyingroom = CLASSROOM ∪ LABORATORY, mỗi owner có attr riêng.\n> Lý do: Partial disjoint specialization ≡ partial category về số entity trong supertype. *(QUIZ 3 Q20)*\n\n---\n\n### 2.22 Formal Definitions EER (Elmasri)\n\n| Formal | Định nghĩa |\n|---|---|\n| `S ⊆ C` | Subclass S là subset của superclass C |\n| `S1 ∪ S2 ∪ … ∪ Sn = G` | **Total** specialization |\n| `Si ∩ Sj = ∅` (i ≠ j) | **Disjoint** |\n| `S = C[p]` | **Predicate-defined** subclass |\n| `T ⊆ D1 ∪ … ∪ Dn`, `n > 1` | **Category / union type** |\n| `T = (D1[p1] ∪ D2[p2] ∪ … ∪ Dn[pn])` | Category có predicate đủ |\n\n**Thuật ngữ:** **class** = tên gọi chung bao gồm entity type, superclass, và subclass trong mô hình EER.\n\n> 🔥 `n > 1` là điều kiện bắt buộc của category (≥ 2 owner types).\n\n---\n\n### 2.23 Design Choices trong EER\n\n- Nên tạo subclass nếu có: **thuộc tính riêng (local attributes), relationship riêng (specific relationship types), constraint riêng, nghiệp vụ riêng**.\n- **Không nên** nếu chỉ khác tên loại → dùng **type attribute** (Employee\\_type).\n- Subclass có ít attr riêng + không có relationship riêng → **gộp vào superclass**.\n- **Union type nên TRÁNH** khi có thể.\n- Chọn d/o và total/partial **theo miniworld requirement**, không theo ý thích.\n\n---\n\n### 2.24 Worked Example — Giải chi tiết Q14 BOOK (QUIZ 3 Q3) 🔥\n\n**Đề:** BOOK superclass, `o` (overlapping), double line (total), 2 subclass HARDCOPY và SOFTCOPY.\n\n**Phân tích từng đáp án:**\n- **(a) \"There exists a book that has only softcopies.\"** → Total = mọi book thuộc ≥ 1 subclass; Overlapping = có thể thuộc cả 2. Một book chỉ thuộc SOFTCOPY (không thuộc HARDCOPY) hoàn toàn hợp lệ. → **TRUE ✅**\n- **(d) \"Each book is either hardcopy or softcopy.\"** → \"either … or\" = disjoint, nhưng ký hiệu là `o` (overlapping) → sai, book có thể thuộc cả 2. → **FALSE ❌**\n- **(e) \"There exists a book not classified.\"** → Total (double line) = mọi book phải thuộc ≥ 1 → không thể không được phân loại. → **FALSE ❌**\n- **(f) \"|BOOK| = |HARDCOPY| + |SOFTCOPY|.\"** → Overlapping cho phép một book thuộc cả 2 → bị đếm 2 lần → không bằng nhau. → **FALSE ❌**\n\n**Đáp án: a.** *(QUIZ 3 Q3 — xác nhận 100%)*\n\n**Trap rút ra:** Total+Overlapping → |Sup| ≤ |Sub1|+|Sub2| (không phải bằng). Counting rule chỉ đúng khi **Total AND Disjoint**.\n\n---\n\n### 2.25 Worked Example — Giải chi tiết Q12 SELF-STUDY PLACES (QUIZ 3 Q12) 🔥\n\n**Đề:** \"Self-study places are given from library rooms and class rooms. However, **some** class rooms can **not** be provided for self-study places.\"\n\n**Bước suy luận:**\n1. Self-study place được lấy từ library room HOẶC class room → logic **OR/Union** → **Category (union type)**.\n2. \"Some class rooms cannot\" → không phải mọi library room hay class room đều là self-study place → Category là **partial** (single line vào circle ∪).\n3. Nếu dùng specialization (Self-Study là superclass của Library/Class): sẽ hàm ý Library và Class room là subtype của Self-Study → sai ngữ nghĩa.\n\n**Đáp án: d — Union type, partial category.** *(QUIZ 3 Q12 — 100%)*\n\n**Trap rút ra:** Union type khi objects đến từ **nhiều entity type khác nhau** (library ≠ class), không dùng specialization.\n\n---\n\n### 🎯 MCQ Traps §2\n\n> Học 17 bẫy này = bảo hiểm ~8/10 câu §2 🔥\n\n1. 🔥 **Storage structures / access paths → Physical design, KHÔNG phải Conceptual** (Conceptual = DBMS-independent). *(QUIZ 2 Q1)*\n2. 🔥 **Thứ tự 5 phase:** Requirements → Conceptual → Choice of DBMS → Logical (mapping) → Physical. \"Choice of DBMS\" sau Conceptual, trước Logical. *(QUIZ 2 Q3)*\n3. 🔥 **Derived KHÔNG lưu** trong DB — oval đứt, tính từ stored data. \"Close date determined from account details\" = derived. *(QUIZ 2 Q4)*\n4. 🔥 **\"must / at least one\" = total; \"may / optional / some have none\" = partial** — áp dụng ngay khi đọc miniworld. *(QUIZ 2 Q4, Q5, Q7)*\n5. 🔥 **M:N relationship attribute KHÔNG migrate** — Hours BẮT BUỘC nằm trên WORKS\\_ON.\n6. 🔥 **Cardinality VÀ Participation là 2 trục độc lập** — 1:N không nói gì về tính bắt buộc.\n7. 🔥 **Weak entity: no key of its own + partial key + identifying relationship (◇◇) + LUÔN total phía weak.** Weak có thể có nhiều owner. *(H192 Q31)*\n8. 🔥 **Degree = số entity type tham gia**, KHÔNG phải số attribute của relationship. *(H211 Q53)*\n9. 🔥 **|Sup| = |Sub1| + |Sub2| ⟺ Total AND Disjoint** — không total hoặc không disjoint thì không bằng. *(QUIZ 3 Q13)*\n10. 🔥 **Shared subclass = AND (∩); Category = OR (∪)** — H191 Q6. Subsets: Sub1, Sub2, Uni đều là subsets; E1, E2 (owners của Uni) KHÔNG. *(QUIZ 3 Q9)*\n11. 🔥 **Chasm trap = pathway bị đứt do partial/0:N participation**, KHÔNG phải fan trap. *(QUIZ 3 Q19)*\n12. 🔥 **\"An entity of a subclass is also one of the entities of its superclass\" = TRUE (R2).** *(QUIZ 3 Q6)*\n13. 🔥 **Category giới hạn member đúng các owner type liệt kê**; partial specialization KHÔNG giới hạn (motorcycle vẫn là VEHICLE).\n14. 🔥 **Attribute-defined specialization implies disjoint** (defining attribute chỉ có 1 giá trị → 1 subclass).\n15. 🔥 **Ternary KHÔNG luôn thay bằng 3 binary** — tách có thể mất thông tin (ai submit cái nào tại branch nào). *(H202 Q40)*\n16. 🔥 **Fan trap = 1:N + 1:N từ cùng hub** (hub mơ hồ). Trường hợp M:N + 1:N không phải fan trap thuần — nhưng vẫn cần restructure (thêm direct relationship). *(HK191 Q4, F2024 Q36)*\n17. 🔥 **Functional design ∥ DB structural design = parallel + independent** (KHÔNG phải \"parallel + related\"). *(HK211mock Q12)* Ràng buộc thời gian → **scheduled job**, không phải trigger. *(HK191 Q10)*\n\n---\n\n### 🪄 Câu thần chú §2\n\n1. **Danh từ → Entity, Tính chất → Attribute, Động từ → Relationship, Unique/SSN → Key.**\n2. **Multivalued = oval đôi; Derived = oval đứt; Composite = oval cha-con.**\n3. **Weak entity PK = {owner\\_PK, partial\\_key}** — identifying = ◇◇, participation phía weak = **luôn total**.\n4. **M:N attribute BẮT BUỘC trên relationship** — Hours trên WORKS\\_ON, không migrate.\n5. **Cardinality \"bao nhiêu\", Participation \"có bắt buộc không\" — hai trục độc lập.**\n6. **(min,max) gói cả cardinality + participation** — `(1,N)` = total + many, `(0,1)` = partial + max one.\n7. **Specialization = top-down, Generalization = bottom-up; vẽ trên diagram giống nhau.**\n8. **`d/o` trả lời \"vào bao nhiêu nhóm\"; Total/Partial trả lời \"có bắt buộc vào nhóm không\".**\n9. **|Sup| = |Sub1| + |Sub2| chỉ khi Total AND Disjoint** — một trong hai thiếu là sai.\n10. **Shared = AND (∩ tất cả); Category = OR (∪ chỉ 1)** — điểm nhầm nhất trong §2.\n11. **Subclass/superclass LUÔN 1:1 (R5); subclass entity PHẢI tồn tại ở superclass (R2).**\n12. **Fan trap = pathway mơ hồ (≥2 nhánh 1:N toả từ hub); Chasm trap = pathway đứt (partial participation).**\n13. **Conceptual design = DBMS-independent; Physical design = storage structures + access paths.**\n14. **Subsets trong EER: Sub1, Sub2 (subclasses) và Uni (category) đều là subsets; E1/E2 (owners) không phải.**\n15. **Hình `o` trong specialization = overlapping; hình `∪` = union/category — KHÔNG nhầm dù trông giống nhau.**\n\n---\n\n","file":"materials/DB-Final.md","section":11},{"id":"final-12","group":"final","kind":"source","title":"§3. RELATIONAL MAPPING (ER/EER → Relational) — Trọng số đề: 5 câu","markdown":"## §3. RELATIONAL MAPPING (ER/EER → Relational) — Trọng số đề: 5 câu\n\n> **Nguồn:** Lecture 04 · Tutorial/DB-Chapter4.md · QUIZ 4 BK-LMS (20/20 điểm — near-verbatim predictive) · đề thi các năm\n>\n> **Tập trung:** 7 + 2 steps mapping, specialization 4 options, FK direction, total participation enforcement, relational model terminology, COMPANY schema 6 bảng.\n\n---\n\n### 3.1. Bức tranh tổng quan — Mapping nằm ở đâu?\n\n```\nConceptual design → ER/EER diagram   [DBMS-independent]\n          ↓  STEP 1–9 (Relational Mapping)\nLogical design   → Relational schema  [DBMS-specific, dùng relational model]\n          ↓\nPhysical design  → file, index, storage\n```\n\n🔑 **Keywords (EN):** logical database design · relational data model · conceptual schema · external schema · internal schema\n\n- **Mapping ≠ Normalization** — chỉ dịch ER thành bảng; normalization kiểm tra FD/redundancy sau đó.\n- **Relational model dùng ở đâu?** → Conceptual schema + external schemas (KHÔNG phải internal schema — internal là physical storage). `(QUIZ Q4 = E; MCQ-03 Q8 = A)`\n\n---\n\n### 3.2. Thuật ngữ Relational Model — cốt lõi\n\n🔑 **Keywords (EN):** relation · tuple · attribute · domain · relation schema · relation state/instance · degree · cardinality · atomic value · NULL · `t[A]` notation · intension vs extension · E.F. Codd 1970\n\n| Formal (RM) | Informal | Ví dụ EMPLOYEE |\n|---|---|---|\n| Relation | Table | EMPLOYEE |\n| Tuple | Row | 1 nhân viên cụ thể |\n| Attribute | Column header | `Ssn`, `Salary` |\n| Domain | All column values | tập giá trị hợp lệ của `Salary` |\n| Schema `R(A1…An)` | Table definition | `EMPLOYEE(Ssn, Fname, …)` |\n| State / Instance | Populated table | 8 nhân viên tại thời điểm t |\n| Degree | Số cột (# attribute trong schema) | EMPLOYEE 10 cột → degree = 10 |\n| Cardinality (RM) | Số hàng (# tuple) | 8 tuple → cardinality = 8 |\n\n> ⚠️ **Bẫy:** Cardinality trong RM = số dòng. Cardinality ratio trong ER = 1:1/1:N/M:N. Hai khái niệm hoàn toàn khác nhau.\n\n- **Relation là SET** → không có duplicate tuple, thứ tự tuple không quan trọng, attribute tham chiếu bằng **tên** (không bằng vị trí).\n- **Tuple** `t = <v1, v2, …, vn>`; giá trị thứ i viết là `t[Ai]`. Mỗi `vi ∈ dom(Ai)` **hoặc NULL**.\n- **NULL** = unknown / inapplicable / known but not recorded. ⚠️ NULL ≠ 0 ≠ empty string ≠ space.\n- **Tại sao data trong relational DB gọi là \"simple\"?** → Attribute values are **atomic** and organized in a well-controlled tabular format. `(QUIZ Q16 = A)`\n- **Nguồn gốc:** Relational model do Dr. **E.F. Codd** (IBM) đề xuất năm **1970** trong bài báo *\"A Relational Model for Large Shared Data Banks\"* (CACM).\n\n---\n\n### 3.3. Relation (RM) ≠ Relationship (ER)\n\n🔑 **Keywords (EN):** relation (table) · relationship (ER diamond/association)\n\n| Từ | Nằm ở | Nghĩa |\n|---|---|---|\n| **Relationship** | ER/EER | Mối liên kết giữa entity type (hình thoi ◇) |\n| **Relation** | Relational Model | Bảng |\n\n`WORKS_ON` là một *relationship* trong ER. Sau mapping, `WORKS_ON(Essn, Pno, Hours)` là một *relation* (bảng). Tuy nhiên **relation ≠ relationship**.\n\n---\n\n### 3.4. Superkey / Candidate Key / Primary Key / Secondary Key\n\n🔑 **Keywords (EN):** superkey · candidate key (minimal superkey) · primary key · secondary key (alternate key)\n\n```\nSuperkey       ⊇  Candidate key  ⊇  Primary key\n(minimal superkey = candidate key; primary key = candidate key được chọn)\nSecondary / alternate key = candidate key còn lại (không được chọn làm PK)\n```\n\n**Ví dụ CAR(State, Reg#, SerialNo, Make, Model, Year):**\n- Candidate keys: `{State, Reg#}`, `{SerialNo}`\n- `{SerialNo, Make}` = **superkey** nhưng **KHÔNG phải key** (không minimal — bỏ Make vẫn unique)\n- PK được chọn: `{SerialNo}` (hoặc `{State, Reg#}`); cái còn lại = secondary key\n\n> 🔥 **Bẫy Q40/MCQ:** \"A superkey is the primary key used to distinguish rows\" → **SAI** (D = sai). Đúng: superkey ⊇ PK, nhưng không nhất thiết bằng nhau. `(MCQ-03 Q40 ans=D incorrect)`\n>\n> 🔥 **Bẫy phát biểu (HK191-Q16):** Nếu một phát biểu về key chỉ đòi **tính duy nhất** (`t1[K] ≠ t2[K]`) mà **không đòi minimal** → đó là định nghĩa **SUPERKEY**, không phải primary key. PK = candidate key được chọn = minimal superkey.\n\n---\n\n### 3.5. 4 Integrity Constraints\n\n🔑 **Keywords (EN):** domain constraint · key constraint · entity integrity constraint · referential integrity constraint · NOT NULL · NULL · FK · static constraint · transition constraint · dynamic constraint\n\n| Constraint | Nghĩa | Vi phạm điển hình |\n|---|---|---|\n| **Domain** | Mỗi giá trị ∈ domain hợp lệ | `Salary = 'abc'` hoặc `Salary < 0` |\n| **Key** | PK duy nhất xác định tuple; không trùng | 2 employee cùng `Ssn` |\n| **Entity integrity** | **PK ≠ NULL** (mọi thành phần PK phải NOT NULL) | `Employee.Ssn = NULL` |\n| **Referential integrity** | FK ∈ {PK referenced relation} ∪ {NULL} | `Dno = 99` nhưng không có Department 99 |\n\n> ⚠️ **Participation constraint** = ràng buộc ER, **KHÔNG phải** constraint của Relational Data Model. `(MCQ-03 Q47=A, Q52=B, Q62=D)`\n>\n> 🔥 **Nếu FK là một phần PK** → FK đó KHÔNG được NULL (vì PK ≠ NULL). Ví dụ `WORKS_ON(Essn, Pno, Hours)` — `Essn` vừa là FK vừa là phần PK → NOT NULL bắt buộc.\n\n**Static vs Dynamic (Transition) Constraints:**\n- 4 integrity constraints trên đều là **static constraints** — phải đúng tại **mọi thời điểm** (mọi state hợp lệ).\n- **Transition / dynamic constraint**: ràng buộc áp lên **sự thay đổi trạng thái** — ví dụ *\"salary chỉ được tăng, không giảm\"*. Loại này không thể biểu diễn trực tiếp bằng 4 constraint trên; cần trigger hoặc application logic.\n\n**Update operations vi phạm constraint nào?**\n\n| Operation | Có thể vi phạm |\n|---|---|\n| **INSERT** | Domain · Entity integrity (PK=NULL) · Key (PK trùng) · Referential (FK → không tồn tại) |\n| **DELETE** | **Referential integrity** (xóa cha khi con đang tham chiếu) |\n| **MODIFY** | Tùy cột: PK/FK → như INSERT/DELETE; cột thường → Domain |\n\n> `(MCQ-03 Q41=B, Q54=D, Q55=C, Q58=A, Q65=C)`\n\n---\n\n### 3.6. 7 Steps Mapping ER → Relational\n\n🔑 **Keywords (EN):** strong entity · weak entity · partial key · owner relation · binary 1:1 · binary 1:N · binary M:N · recursive relationship · involuted relationship · multivalued attribute · n-ary relationship · relationship relation · FK (foreign key) · PK (primary key) · ON DELETE CASCADE\n\n| Step | Đối tượng | Quy tắc |\n|---|---|---|\n| **1** | **Strong (Regular) Entity** | Bảng riêng. Simple attr → cột. Composite → tách thành simple components. Derived → **KHÔNG lưu** (bỏ). Multivalued → để Step 6. Key → PK. |\n| **2** | **Weak Entity** | Bảng riêng + FK trỏ owner. **PK = {owner_PK + partial_key}**. Thêm `ON DELETE CASCADE`. |\n| **3** | **Binary 1:1** | 3 cách: **(a) FK approach** — đặt FK ở **phía total participation** (giảm NULL), FK phải có **UNIQUE** (nếu thiếu UNIQUE → quan hệ biến thành N:1); **(b) Merge** — gộp 1 bảng nếu cả 2 total; **(c) Cross-reference relation** — bảng riêng nếu cả 2 partial. |\n| **4** | **Binary 1:N** | **FK ở phía N** trỏ về PK phía 1. Relationship attr đặt vào phía N. KHÔNG tạo bảng mới (option chính). Option phụ: **Relationship-relation approach** — tạo bảng quan hệ riêng với PK = FK phía N; nên dùng khi ít tuple phía N tham gia (tránh nhiều NULL), coi như \"almost optional\". |\n| **5** | **Binary M:N** | **BẮT BUỘC bảng riêng** `R(PK1, PK2, attrs)`. PK = `{PK1, PK2}`. 2 FK. |\n| **6** | **Multivalued Attribute** | Bảng riêng `(entity_PK, attr_value)`. PK = `{entity_PK, attr_value}`. |\n| **7** | **N-ary Relationship** | Bảng riêng + n FK. **Nếu Eᵢ có cardinality 1 → FKᵢ KHÔNG nằm trong PK** (xem 3.9). |\n\n**Recursive relationship (= involuted relationship):**\n- Slide dùng thuật ngữ **involuted** cho recursive relationship (ví dụ: 1:1 MARRY, 1:N EMPLOYEE-SUPERVISE, M:N PART-COMPRISE).\n- 1:N recursive → self-FK (đổi tên role). Ví dụ: `EMPLOYEE(..., Super_ssn)` FK `Super_ssn → EMPLOYEE(Ssn)`.\n- M:N recursive → bảng riêng. Ví dụ: `COMPRISE(Major_part_no, Minor_part_no, Quantity)`, PK = `(Major_part_no, Minor_part_no)`.\n\n> 🔥 **Đối tượng MAY NOT cần bảng riêng**: Binary 1:N relationship (Step 4 dùng FK thôi). `(MCQ-03 Q28=D, Q43=C)`\n\n---\n\n### 3.7. Enforcing Total Participation — khi nào cần CHECK/Assertion?\n\n🔑 **Keywords (EN):** total participation · NOT NULL · CHECK constraint · trigger/assertion · partial participation\n\n| Trường hợp | Cách enforce | Cần CHECK? |\n|---|---|---|\n| **1:N — phía N total** | `FK + NOT NULL` là đủ | ❌ Không cần CHECK thêm |\n| **Weak entity** | owner PK là phần PK → tự động NOT NULL | ❌ Không cần CHECK thêm |\n| **Strong entity / phía 1 / phía M:N total** | FK/PK KHÔNG đảm bảo entity xuất hiện ≥ 1 lần | ✅ **Cần CHECK / assertion / trigger** |\n\n**Ví dụ quan trọng (QUIZ Q11 / MCQ-03 Q27):**\n- `Building(Name, Location) 1—N Room(Number)`, **Building total** → Room có FK `BuildingName NOT NULL` (Room total → auto). Nhưng bạn **vẫn cần** `Check: total participation of Building in Room` vì không có gì ngăn INSERT một Building mà không có Room nào.\n- `Musician M—N Instrument`, cả 2 total → `Plays(MusicianSSN, InstrumentCode)` PK/FK không force → **cần Check total participation của cả hai**. `(QUIZ Q9 = Check: total participation of Musician and Instrument in Plays)`\n- `Customer M—N Service`, Customer total → `Registration(...)` cần `Check: total participation of Customer`. `(QUIZ Q14/Q19)`\n- Ngược lại: `Project(Code, …, DepartmentID NOT NULL)` — Project total trong 1:N với Department → **KHÔNG cần** thêm Check. `(QUIZ Q5 ans=B, no spurious Check)`\n\n---\n\n### 3.8. Ternary Relationship — quy tắc PK khi có cardinality 1\n\n🔑 **Keywords (EN):** ternary (n-ary) relationship · functional dependency in ternary · 1-side FK not in PK\n\nCho ternary relationship A:1, B:N, C:N → `(B, C) → A`:\n```\nR(A_id, B_id, C_id, attrs)\nPK = (B_id, C_id)      -- hai phía N\nA_id là FK, KHÔNG nằm trong PK\n```\n\n**Ví dụ QUIZ Q17 — `Plays(Musician:1, Play:N, Instrument:N, Style)`:**\n```\nPlays(MusicianIdentifier, PlayTitle, InstrumentCode, Style)\nPK = (PlayTitle, InstrumentCode)          -- hai N-side\nFK MusicianIdentifier → Musician.Identifier  NOT NULL\n```\nMultivalued attr `Periods` trên `Plays` → bảng riêng:\n```\nplaysPeriods(PlayTitle, InstrumentCode, APeriod)\nPK = (PlayTitle, InstrumentCode, APeriod)\nFK (PlayTitle, InstrumentCode) → Plays\n```\n\n---\n\n### 3.9. Step 8 — Specialization / Generalization: 4 Options\n\n🔑 **Keywords (EN):** specialization · generalization · superclass · subclass · disjoint · overlapping · total · partial · 8A (superclass+subclasses) · 8B (subclass-only) · 8C (single table + type attr) · 8D (single table + boolean flags)\n\n| Option | Cấu trúc | Disjoint? | Overlap? | Total? | Partial? | Nhược điểm |\n|---|---|---|---|---|---|---|\n| **8A** Superclass + Subclass tables | m+1 bảng | ✅ | ✅ | ✅ | ✅ | JOIN nhiều — nhưng **luôn an toàn** |\n| **8B** Subclass-only (kế thừa tất cả attr) | m bảng | ✅ tốt nhất | ⚠️ duplicate (discouraged) | ✅ **Bắt buộc Total** | ❌ **Không dùng Partial** | Redundancy nếu overlap |\n| **8C** Single table + 1 type attribute | 1 bảng | ✅ | ❌ **Không dùng Overlap** | ✅ | ✅ | Nhiều NULL |\n| **8D** Single table + boolean flags | 1 bảng | ✅ | ✅ **Tốt cho Overlap** | ✅ | ✅ | Nhiều NULL |\n\n> 🔥 **Partial + Disjoint → 3 options: 8A, 8C, 8D** (KHÔNG có 8B vì 8B yêu cầu Total). `(MCQ-03 Q46=C)`\n>\n> 🔥 **Overlap → chỉ 8D hoặc 8A. KHÔNG dùng 8C.**\n>\n> 🔥 **8B nuance:** Option 8B *hoạt động được* với total (cả disjoint lẫn overlap về mặt kỹ thuật), nhưng chỉ *được khuyến dùng* cho **total + disjoint**. Nếu overlap → cùng 1 thực thể xuất hiện trùng lặp ở nhiều bảng con → **discouraged** (không phải cấm tuyệt đối, nhưng tạo redundancy nghiêm trọng).\n>\n> 🔥 **Bẫy 8C với Total specialization:** `BookType ∈ {Hardcopy, Softcopy, Both, Other}` — domain value `Other` nghĩa là \"không thuộc subclass nào\" → vi phạm Total (phải thuộc ít nhất 1 subclass).\n>\n> 🔥 **Bẫy \"find the INCORRECT mapping\" (QUIZ4-Q10):** Với **overlapping** specialization (Book → Hardcopy/Softcopy), áp dụng 8C (single table + type attr `Domain {Hardcopy, Softcopy, Both, Other}`) là **mapping SAI** — thêm giá trị `Both`/`Other` là workaround sai bản chất; 8C chỉ đúng cho disjoint.\n>\n> `(MCQ-03 Q30=E: tất cả A,B,C,D đều đúng cho disjoint specialization Room → Classroom/Laboratory)`\n\n**Integrity constraints của specialization:** Disjointness constraint + Completeness constraint. `(MCQ-03 Q39=D: \"all of the above wrong\" — đúng là Disjointness + Completeness, không phải Participation hay Cardinality)`\n\n---\n\n### 3.10. Step 9 — Category / Union Type → Surrogate Key\n\n🔑 **Keywords (EN):** category · union type · superclass · surrogate key · partial category · total category\n\n- Category `C = T1 ∪ T2 ∪ T3` (OR/union) khi các superclass có PK **khác nhau** → bắt buộc tạo **surrogate key** mới.\n\n**Ví dụ QUIZ Q3 — `LearningMaterial = Book(ISBN) ∪ Article(DOI)`:**\n```\nLearningMaterial(ID, …)           PK = ID  (surrogate)\nBook(ISBN, …, LearningMaterialID) FK LearningMaterialID → LearningMaterial.ID\nArticle(DOI, …, LearningMaterialID) FK LearningMaterialID → LearningMaterial.ID\nIs_used_in(LearningMaterialID, CourseID)  PK = (LearningMaterialID, CourseID)\n```\n> Nếu **partial category** → KHÔNG đặt NOT NULL cho link FK. Total category → FK NOT NULL.\n\n---\n\n### 3.11. Shared Subclass vs Category\n\n| | Shared subclass | Category |\n|---|---|---|\n| Logic | AND / intersection | OR / union |\n| Ví dụ | `STUDENT_ASSISTANT = STUDENT ∩ EMPLOYEE` | `OWNER = PERSON ∪ BANK ∪ COMPANY` |\n| Key condition | Superclass nên **cùng key** | Khác key → **surrogate key** |\n\n---\n\n### 3.12. Bảng vàng ER construct → Relational result\n\n🔑 **Keywords (EN):** entity relation · relationship relation · foreign key · composite attribute flatten · value set → domain\n\n| ER construct | Relational result |\n|---|---|\n| Strong entity | Entity relation; key → PK |\n| Weak entity | Relation, PK = owner_PK + partial_key; owner PK là FK |\n| Composite attribute | **Flatten** — tách thành simple components (KHÔNG bảng riêng) |\n| Derived attribute | Thường **không lưu** |\n| Multivalued attribute | Bảng riêng `(OwnerPK, Value)`, PK = cả hai |\n| 1:1 relationship | Foreign key (ưu tiên phía total participation); FK phải **UNIQUE** |\n| 1:N relationship | FK ở **phía N** |\n| M:N relationship | Relationship relation mới + 2 FK, PK = (PK1, PK2) |\n| N-ary relationship | Relationship relation + n FK; phía cardinality 1 → FK không vào PK |\n| Value set | Domain |\n| Key attribute | Primary (or secondary) key |\n\n---\n\n### 3.13. Referential Actions (ON DELETE / ON UPDATE)\n\n🔑 **Keywords (EN):** REJECT / NO ACTION / RESTRICT · CASCADE · SET NULL · SET DEFAULT · referential action\n\n| Action | Hành vi khi cha bị xóa/update |\n|---|---|\n| **REJECT / NO ACTION / RESTRICT** | Không cho nếu còn child tham chiếu |\n| **CASCADE** | Lan truyền sang child (xóa cha → xóa con) |\n| **SET NULL** | FK child = NULL |\n| **SET DEFAULT** | FK child = DEFAULT value |\n\n> ⚠️ `SET NULL` **không dùng được** nếu FK là NOT NULL hoặc là một phần PK.\n>\n> **QUIZ Q42:** Khi update Card_no ở BORROWER phải cascade sang BOOK_LOANS, nhưng delete BORROWER bị block nếu BOOK_LOANS còn tham chiếu → `FOREIGN KEY (Card_no) REFERENCES BORROWER(Card_no) ON DELETE RESTRICT ON UPDATE CASCADE` đặt trong **BOOK_LOANS** (hoặc tương đương: PRIMARY KEY ON DELETE RESTRICT trên BORROWER). Đáp án = A.\n\n---\n\n### 3.14. COMPANY — Full Mapping (BẮT BUỘC thuộc — 6 bảng + 8 FK)\n\n```\nEMPLOYEE(Fname, Minit, Lname, Ssn, Bdate, Address, Sex, Salary, Super_ssn, Dno)\n  PK = Ssn\n  FK: Super_ssn → EMPLOYEE(Ssn)          -- recursive 1:N (self-ref)\n      Dno       → DEPARTMENT(Dnumber)    -- 1:N\n\nDEPARTMENT(Dname, Dnumber, Mgr_ssn, Mgr_start_date)\n  PK = Dnumber\n  FK: Mgr_ssn → EMPLOYEE(Ssn)           -- 1:1\n\nDEPT_LOCATIONS(Dnumber, Dlocation)       -- Step 6: multivalued\n  PK = {Dnumber, Dlocation}\n  FK: Dnumber → DEPARTMENT(Dnumber)\n\nPROJECT(Pname, Pnumber, Plocation, Dnum)\n  PK = Pnumber\n  FK: Dnum → DEPARTMENT(Dnumber)        -- 1:N\n\nWORKS_ON(Essn, Pno, Hours)              -- Step 5: M:N\n  PK = {Essn, Pno}\n  FK: Essn → EMPLOYEE(Ssn)\n      Pno  → PROJECT(Pnumber)\n\nDEPENDENT(Essn, Dependent_name, Sex, Bdate, Relationship)  -- Step 2: weak entity\n  PK = {Essn, Dependent_name}\n  FK: Essn → EMPLOYEE(Ssn)  ON DELETE CASCADE\n```\n\n> QUIZ Q6: \"If available, each `Dno` value in Employee must appear in `Dnumber` in Department\" → **TRUE** (Referential integrity). Removing Employee has no impact on Department. `(QUIZ Q6 = E)`\n\n---\n\n### 3.15. \"Is this table a relation?\" — Bẫy kinh điển\n\n🔑 **Keywords (EN):** duplicate tuples · non-atomic column · set semantics · 1NF\n\n- Bảng có **duplicate tuples** → **KHÔNG phải relation** (relation là set).\n- Cột chứa **non-atomic value** (tập giá trị, như `Contact = {212921, 018271}`) → **KHÔNG phải relation** (vi phạm 1NF/atomicity).\n- Cột có giá trị lặp lại **nhưng không phải PK** → vẫn là relation (bình thường).\n\n**QUIZ Q20 / MCQ-03 Q33:**\n- `Trainee` có tuple `(NDV,20,2001)` xuất hiện 2 lần → **NOT a relation**.\n- `Customer` có `Contact = {…}` multi-value → **NOT a relation**.\n- `Book` và `iPhone` atomic, distinct tuples → **Relations**.\n\n---\n\n### 3.16. Các trường hợp đặc biệt từ QUIZ BK-LMS\n\n**QUIZ Q1 — 1:1 (Employee–Account), both total + multivalued attr Privileges:**\n```\nEmployeeAccount(SSN, Name, …, Username, Password, …)\n  PK = SSN;  Secondary key (unique, not null): Username\nisgivenPrivileges(EmployeeAccountSSN, APrivilege)\n  PK = (EmployeeAccountSSN, APrivilege)\n  FK EmployeeAccountSSN → EmployeeAccount.SSN\n```\n→ 1:1 both total → **merge** vào 1 bảng; Privileges multivalued → bảng riêng.\n\n**QUIZ Q2 — 1:N (Employee leads Project), Project total + multivalued attr Tasks trên relationship:**\n```\nEmployee(ID, SSN)  PK=ID, SK SSN\nProject(Number, Name, EmployeeID)  PK=Number, FK EmployeeID NOT NULL + UNIQUE\nIs_led_byTasks(ProjectNumber, ATask)  PK=(ProjectNumber, ATask)  FK→Project\n```\n→ 1:N → FK ở phía N (Project); multivalued attr trên relationship → bảng riêng lấy PK từ phía FK; 1:1 FK phía total → UNIQUE.\n\n**QUIZ Q5 — 1:N (Department–Project), composite attr ProjectPeriod(From, To):**\n```\nDepartment(ID, Name)  SK Name\nProject(Code, Name, DepartmentID)  FK DepartmentID NOT NULL\nProjectPeriod(ProjectCode, From, To)  PK=(ProjectCode, From, To)  FK→Project\n```\n→ Composite attr `ProjectPeriod` → flatten From, To; composite + thực ra là multivalued → bảng riêng.\n\n**QUIZ Q13 — Weak entity Drug + Specialization + Multivalued SpecialConditions:**\n```\nDrug(DrugName, CompanyName, DrugType, Function)\n  PK = (DrugName, CompanyName)  [weak: CompanyName là owner PK]\n  Domain DrugType: {'Treatment', 'Special', 'Supporting', 'Other'}\nSpecialConditions(DrugName, CompanyName, Acondition)\n  PK = (DrugName, CompanyName, Acondition); FK → Drug\nIs_used_for(DrugName, CompanyName, DiseaseCode)  [only Treatment drugs]\n```\n→ Specialization disjoint → 8C (single table + type attribute).\n\n**QUIZ4-Q15 — Reverse-direction mapping (schema → ERD):**\n- Dạng đề: *\"Cho lược đồ quan hệ R, ERD nào KHÔNG thể tương ứng?\"*\n- Nguyên tắc: `(OwnerPK, AttrValue)` với PK = cả hai → xuất phát từ **multivalued attribute** trong ER, **không thể** tương ứng ERD có **weak entity** (vì weak entity luôn có thêm partial key riêng và FK rõ ràng). Cần phân biệt schema do multivalued attr sinh ra vs schema do weak entity sinh ra.\n\n---\n\n### 🎯 MCQ Traps §3\n\n1. 🔥 **1:N → FK phía N**, KHÔNG phải phía 1 (đặt FK phía 1 → vi phạm 1NF vì 1 tuple phải chứa nhiều FK).\n2. 🔥 **M:N → BẮT BUỘC bảng riêng** — không bao giờ merge vào entity.\n3. 🔥 **Weak entity PK = {owner_PK + partial_key}** + `ON DELETE CASCADE`; partial key **một mình không unique**.\n4. 🔥 **Multivalued attr KHÔNG để chung 1 cột** (`Phone=\"123,456\"` → vi phạm 1NF).\n5. 🔥 **Option 8B chỉ được khuyến dùng Total + Disjoint**; với overlap 8B tạo redundancy nghiêm trọng (discouraged, không phải cấm tuyệt đối); **8C không xử lý Overlap**; **8D tốt cho Overlap**.\n6. 🔥 **Partial + Disjoint → 3 options (8A, 8C, 8D)**, không có 8B.\n7. 🔥 **Category (superclass khác key) → surrogate key**; Shared subclass cần cùng key.\n8. 🔥 **Total participation phía N** → `FK NOT NULL` là đủ, không cần CHECK thêm. **Total participation phía \"1\" hoặc phía M:N** → phải có CHECK/assertion/trigger.\n9. 🔥 **Ternary A:1, B:N, C:N → PK = (B_id, C_id)**; A_id là FK nhưng không vào PK.\n10. 🔥 **DELETE vi phạm referential integrity**; **INSERT vi phạm entity integrity** (PK null) hoặc key/referential.\n11. 🔥 **Participation constraint KHÔNG phải constraint của Relational Model** (Domain · Key · Entity integrity · Referential integrity là 4 cái đúng).\n12. 🔥 **Superkey ⊇ CK ⊇ PK**; superkey không nhất thiết là key (ví dụ `{SerialNo, Make}` là superkey nhưng không minimal). Phát biểu chỉ đòi uniqueness mà không đòi minimal = định nghĩa superkey, KHÔNG phải PK.\n13. 🔥 **1:1 FK phía total PHẢI có UNIQUE** — thiếu UNIQUE → quan hệ biến thành N:1 (nhiều phía N trỏ về cùng 1 phía 1). `(QUIZ4-Q2)`\n14. 🔥 **8C + overlapping specialization = mapping SAI** — thêm `Both`/`Other` vào domain là workaround sai bản chất; nhận diện dạng \"find the incorrect mapping\". `(QUIZ4-Q10)`\n15. 🔥 **Reverse-direction trap**: schema `(OwnerPK, Value)` PK=cả hai → multivalued attr, **không phải** weak entity. Dạng đề \"ERD nào KHÔNG thể tương ứng\". `(QUIZ4-Q15)`\n16. 🔥 **Static vs Dynamic constraint**: 4 integrity constraints là static; \"salary chỉ được tăng\" là transition/dynamic constraint → không thể enforce bằng 4 constraint trên.\n\n---\n\n### 🪄 Câu thần chú §3\n\n1. **Entity → bảng; Weak → PK = {owner_PK + partial_key} + CASCADE.**\n2. **1:1 → FK phía total (UNIQUE); 1:N → FK phía N; M:N → bảng riêng + 2 FK.**\n3. **Composite → flatten; Derived → bỏ; Multivalued → bảng riêng.**\n4. **N-ary → bảng + n FK; cardinality-1 side → FK không vào PK.**\n5. **Recursive (involuted) 1:N → self-FK đổi tên; Recursive M:N → bảng riêng.**\n6. **Overlap → 8D hoặc 8A. KHÔNG 8C. 8B chỉ Total+Disjoint (discouraged nếu overlap). 8A luôn an toàn.**\n7. **Total phía N/weak → FK NOT NULL đủ. Total phía \"1\"/M:N → cần CHECK.**\n8. **Category khác key → surrogate key mới.**\n9. **Mapping nằm ở Logical Design phase (không phải Conceptual, không phải Physical).**\n10. **Conceptual + External schemas dùng relational model; Internal = physical.**\n11. **DELETE vi phạm Referential; INSERT vi phạm Entity integrity / Key / Referential.**\n12. **Relation = SET: không duplicate tuple, không thứ tự, atomic value, tên không vị trí.**\n13. **Superkey = unique không cần minimal; PK = minimal superkey được chọn; 1:1 FK thiếu UNIQUE → thành N:1.**\n14. **Static constraint = đúng mọi thời điểm (4 loại); Dynamic/transition = ràng buộc thay đổi trạng thái (cần trigger).**\n\n---\n\n","file":"materials/DB-Final.md","section":12},{"id":"final-13","group":"final","kind":"source","title":"§4. RELATIONAL ALGEBRA — Trọng số đề: 4 câu","markdown":"## §4. RELATIONAL ALGEBRA — Trọng số đề: 4 câu\n\n> **Nguồn gốc:** `Lectures/05_Relational Algebra.pdf` + `Tutorial/DB-Chapter5.md`\n> **Tập trung thi:** type-compatibility cho set ops, cardinality của ×, Division ÷, OUTER JOIN, GROUP BY ↔ 𝓕, RA σ vs SQL SELECT, natural join name-trap.\n\n---\n\n### 4.1. Operator Cheat Table\n\n| Toán tử | Ký hiệu | SQL equiv | Tính chất nổi bật |\n|---|---|---|---|\n| **SELECT** | `σ_cond(R)` | `WHERE` | Lọc ROWS; giao hoán; cascade AND; `\\|σ(R)\\| ≤ \\|R\\|` |\n| **PROJECT** | `π_L(R)` | `SELECT DISTINCT` | Chọn COLS; **tự loại duplicate** (relation = set); **không** giao hoán tùy tiện |\n| **RENAME** | `ρ_S(B1,…)(R)` | `AS` | Chỉ đổi nhãn; dùng khi self-join hoặc natural join khác tên |\n| **UNION** | `R ∪ S` | `UNION` | Giao hoán + kết hợp; **đòi union-compatible** |\n| **INTERSECT** | `R ∩ S` | `INTERSECT` | Giao hoán + kết hợp; **đòi union-compatible** |\n| **DIFFERENCE** | `R − S` | `EXCEPT/MINUS` | **KHÔNG** giao hoán; **đòi union-compatible** |\n| **CART. PRODUCT** | `R × S` | `CROSS JOIN` | `\\|R×S\\|=\\|R\\|·\\|S\\|`; degree = n+m; **KHÔNG** cần union-compat |\n| **THETA JOIN** | `R ⋈_θ S` | `JOIN ON θ` | `= σ_θ(R × S)`; θ bất kỳ (≤, ≥, ≠) |\n| **EQUIJOIN** | `R ⋈_{R.A=S.B} S` | `INNER JOIN ON =` | θ chỉ dùng `=`; **giữ cả 2** cột bằng |\n| **NATURAL JOIN** | `R * S` | `NATURAL JOIN` | Tự nối cột **cùng tên**, **bỏ 1 cột trùng** |\n| **DIVISION** | `R(Z) ÷ S(X)` | `double NOT EXISTS` | \"với mọi / for all / every\" |\n| **AGGREGATE** | `[grp] 𝓕_{fn}(R)` | `GROUP BY` + agg | grouping attrs **bên trái** 𝓕; không group → 1 dòng |\n| **LEFT OUTER** | `R ⟕ S` | `LEFT OUTER JOIN` | Giữ mọi tuple R; pad NULL bên phải |\n| **RIGHT OUTER** | `R ⟖ S` | `RIGHT OUTER JOIN` | Giữ mọi tuple S; pad NULL bên trái |\n| **FULL OUTER** | `R ⟗ S` | `FULL OUTER JOIN` | Giữ cả 2; pad NULL cả 2 chiều |\n| **OUTER UNION** | `R ⊌ S` | — | Dùng khi **không** union-compat; cột riêng pad NULL |\n| **ASSIGNMENT** | `R ← expr` | — | Đặt tên kết quả trung gian; vd `DEP5_EMPS ← σ_{DNO=5}(EMPLOYEE)` |\n\n🔑 **Keywords (EN):** RA is \"closed\" (output is always a relation → composable); read RA expressions **inside-out** (leaf → root); complete set `{σ, π, ∪, −, ×}`; σ = filter rows; π = choose columns removes duplicates (set semantics); ∪/∩/− need union-compatibility; − NOT commutative; ∪/∩ commutative; × no union-compat required; join = `σ_θ(R × S)`; natural join = same-named columns keep one copy; division = \"for all/every\"; 𝓕 = aggregate with grouping attrs left; outer join keeps unmatched tuples with NULL; outer union pads NULL when not union-compatible; `query tree` = tree where leaves are relations and internal nodes are RA operators, executed leaf→root; `assignment ←` names intermediate results; `UNIQUE(Q)` returns TRUE iff Q has no duplicate tuples.\n\n---\n\n### 4.2. Tính chất quan trọng & Kích thước\n\n```\nσ giao hoán ✅   π KHÔNG ❌   − KHÔNG ❌   × ✅   ⋈ INNER ✅   OUTER JOIN KHÔNG ❌\n\n∪ / ∩ / −  ĐÒI union-compatible (cùng số cột + kiểu tương thích)\n× / ⋈       KHÔNG đòi union-compatible\n\nCascade:   σ_C1(σ_C2(R)) = σ_{C1 AND C2}(R)          -- commutes\nCascade:   σ_C(R ∪ S)   = σ_C(R) ∪ σ_C(S)\n           σ_C(R × S)   = σ_C(R) × S     (nếu C chỉ thuộc R)\n           π_X(π_Y(R))  = π_X(R)  nếu X ⊆ Y\n\nKích thước:\n  |σ_C(R)|      ≤ |R|\n  |π_L(R)|      ≤ |R|;  = |R| nếu L chứa key của R\n  |R × S|       = |R| · |S|\n  degree(R × S) = degree(R) + degree(S)\n\nComplete set:\n  R ∩ S   = R − (R − S)\n  R ⋈_θ S = σ_θ(R × S)\n\nAssignment (đặt tên trung gian):\n  DEP5_EMPS ← σ_{DNO=5}(EMPLOYEE)\n  RESULT    ← π_{FNAME,LNAME}(DEP5_EMPS)\n  -- Giúp viết biểu thức dài thành chuỗi bước tường minh\n```\n\n> 🔥 **RA closed:** mọi toán tử nhận relation → trả relation → có thể lồng phép tùy ý.\n\n---\n\n### 4.3. SELECT σ vs PROJECT π vs SQL SELECT\n\n| Chiều | RA | SQL |\n|---|---|---|\n| Lọc DÒNG | `σ_cond(R)` | `WHERE cond` |\n| Chọn CỘT + loại trùng | `π_L(R)` | `SELECT DISTINCT L` |\n| Chọn CỘT **giữ trùng** | *(không có — RA là set)* | `SELECT L` (multiset) |\n\n> 🔥 **Bẫy cổ điển:** RA `σ` (SELECT) = lọc **hàng**, KHÔNG phải chọn cột như SQL `SELECT`.\n> 🔥 **`|RA result| ≤ |SQL result|`** — RA π loại duplicate tự động; SQL `SELECT` giữ multiset.\n\n---\n\n### 4.4. JOIN biến thể — bẫy tên cột\n\n| Loại JOIN | Cách hoạt động | Cột bằng nhau |\n|---|---|---|\n| **Theta** `R ⋈_θ S` | `σ_θ(R × S)` với θ bất kỳ | Giữ cả 2 cột |\n| **Equijoin** `R ⋈_{R.A=S.B} S` | θ chỉ là `=` | **Giữ cả 2 cột bằng** |\n| **Natural** `R * S` | Tự nối cột **cùng tên** | **Bỏ 1 cột trùng (giữ 1)** |\n\n> 🔥 **NATURAL JOIN trap:** `EMPLOYEE.SSN ≠ WORKS_ON.ESSN` → natural join **không nối** (khác tên). Phải dùng `EMPLOYEE ⋈_{SSN=ESSN} WORKS_ON`.\n>\n> 🔥 `PROJECT.Dnum ≠ DEPARTMENT.Dnumber` → natural join **sai hoàn toàn** cho bộ Company DB.\n>\n> ✅ Giải pháp: dùng `⋈_{cond}` hoặc `ρ` đổi tên trước rồi dùng natural join.\n\n---\n\n### 4.5. Division ÷ — \"với mọi / for all / every\"\n\n**Cú pháp:** `R(Y, X) ÷ S(X) = T(Y)` — trả về tuple t ∈ Y sao cho **∀s ∈ S: (t, s) ∈ R**.\n\n**Nhận diện:** từ khoá *all, every, tất cả, mọi* trong đề bài.\n\n**Ví dụ:** `STUDENT_COURSE ÷ COURSE` = sinh viên đã học **tất cả** môn trong COURSE.\n\n**Worked step-by-step (HK191-Q20):** `Students(Code,CNo) ÷ Courses(CNo)` với `Courses = {DB, DM, OS}`:\n\n| Code | Môn đã học | Có đủ {DB,DM,OS}? |\n|---|---|---|\n| 1111 | DB, DM, OS | ✅ → vào kết quả |\n| 1112 | DB | ✗ thiếu DM, OS → loại |\n| 1113 | DM, OS, DB | ✅ → vào kết quả |\n| 1114 | DM | ✗ thiếu DB, OS → loại |\n\n**Kết quả: {1111, 1113}**\n\n**Công thức tường minh (không dùng ÷):**\n```\nR ÷ S = π_Y(R) − π_Y( (π_Y(R) × S) − R )\n      = \"mọi ứng viên\" − \"ứng viên bị thiếu ít nhất 1 yêu cầu\"\n```\n\n**SQL equivalent:** `double NOT EXISTS`:\n```sql\nSELECT s.Code FROM Students s\nWHERE NOT EXISTS (\n  SELECT * FROM Courses c\n  WHERE NOT EXISTS (\n    SELECT * FROM Students sc\n    WHERE sc.Code = s.Code AND sc.CNo = c.CNo\n  )\n);\n-- Students(Code,CNo) ÷ Courses(CNo) → {1111, 1113}  (Q32 / Q40)\n```\n\n---\n\n### 4.6. Aggregate 𝓕 — nhận diện \"for each / per\"\n\n**Cú pháp:** `<grouping_cols> 𝓕_{fn_list}(R)` — grouping attrs **bên trái** 𝓕.\n\n| Tín hiệu đề | Toán tử |\n|---|---|\n| *\"for each / in each / mỗi / từng X\"* | Có grouping attr X bên trái 𝓕 |\n| Không có nhóm | `𝓕_{count Ssn}(Employee)` → 1 dòng kết quả |\n\n| Function | Quy tắc NULL |\n|---|---|\n| `COUNT(*)` | Đếm **tất cả** dòng, kể cả NULL |\n| `COUNT(col)` | Chỉ đếm `IS NOT NULL` |\n| `SUM`, `AVG`, `MAX`, `MIN` | **Discard NULL** tự động |\n\n> 🔥 **Sau OUTER JOIN:** dùng `COUNT(col)` không `COUNT(*)` để trả về 0 cho tuple không match (NULL từ outer join).\n\n---\n\n### 4.7. OUTER JOIN & OUTER UNION\n\n- `R ⟕ S` LEFT: giữ **mọi tuple R**, pad NULL phía S nếu không match.\n- `R ⟖ S` RIGHT: giữ mọi tuple S.\n- `R ⟗ S` FULL: giữ cả 2, pad NULL cả 2 phía.\n\n> 🔥 **`R ⟕ S = S ⟖ R`** — LEFT của R = RIGHT của S (đề thường hỏi dạng này).\n\n> 🔥 **INNER = RIGHT OUTER khi nào? (HK191-Q32):** Xét `Employee E ⋈_{E.Superssn=S.Ssn} Employee S`. RIGHT OUTER giữ mọi S (supervisor) và pad NULL cho S nào không có ai báo cáo. Nếu **mọi nhân viên đều là supervisor** (không ai có `Superssn=NULL`) → không có tuple bị pad NULL → INNER JOIN ≡ RIGHT OUTER JOIN. Ngược lại, nếu tồn tại nhân viên `Superssn=NULL` → INNER bỏ dòng đó còn RIGHT OUTER giữ → **khác nhau**.\n\n**OUTER UNION** `R ⊌ S`: dùng khi R và S **không** union-compatible. Cột chung gộp bình thường, cột riêng pad NULL cho phía thiếu.\n\n```\nSTUDENT(Name, Age, GPA) ⊌ INSTRUCTOR(Name, Age, Salary)\n→ kết quả: (Name, Age, GPA, Salary)\n  Student rows:     Salary = NULL\n  Instructor rows:  GPA    = NULL\n```\n\n---\n\n### 4.8. RA vs Relational Calculus\n\n| Tiêu chí | Relational Algebra | Relational Calculus |\n|---|---|---|\n| Bản chất | **Procedural** (HOW) | **Non-procedural** (WHAT) |\n| Dạng | Chuỗi phép toán | Biểu thức điều kiện logic |\n| Ví dụ | `π_Fname(σ_{Dno=5}(Employee))` | `{t.Fname \\| Employee(t) ∧ t.Dno=5}` |\n| Biến | — | Tuple Calc: 1 biến/dòng; Domain Calc: n biến cho degree n |\n\n**3 ngôn ngữ tương đương biểu đạt:** RA ≡ Tuple Calculus ≡ Domain Calculus.\n\n**Bound vs Free variable (Tuple Calculus):** Tuple variable `t` là **bound** nếu nằm trong phạm vi lượng từ `∃(t)` hoặc `∀(t)`; ngược lại là **free**. Trong biểu thức `{t.Fname | Employee(t) ∧ ∃s(Department(s) ∧ s.Mgr=t.Ssn)}`, `t` là free (xác định output), `s` là bound (nằm trong ∃s).\n\n> 🔥 **RA = procedural; Calculus = non-procedural** — câu hỏi phân biệt xuất hiện thường xuyên (Q17, Q19).\n>\n> 🔥 **Recursive closure** (chuỗi supervisor, tổ tiên) **KHÔNG** tính được bằng RA cơ bản → cần `SQL3 WITH RECURSIVE`.\n\n---\n\n### 4.9. Query Tree (Expression Tree)\n\n🔑 **`query tree`** — cấu trúc cây biểu diễn một biểu thức RA:\n- **Leaf node:** quan hệ đầu vào (base relations).\n- **Internal node:** phép toán RA (σ, π, ⋈, …).\n- **Thực thi:** từ leaf lên root (inside-out).\n\n```\n        π_{Fname, Lname}\n               |\n         σ_{Dno=5}\n               |\n           Employee\n```\n*Ví dụ:* `π_{Fname,Lname}(σ_{Dno=5}(Employee))` — đọc từ dưới lên: (1) lấy Employee, (2) lọc Dno=5, (3) project Fname/Lname.\n\n```\n         π_{Fname}\n               |\n           ⋈_{SSN=ESSN}\n          /             \\\n    Employee          WORKS_ON\n```\n\n> Query tree là nền tảng của **query optimization**: DBMS viết lại cây (đẩy σ xuống leaf, kết hợp π) để tối ưu chi phí trước khi thực thi.\n\n---\n\n### 4.10. Recognition Guide — nhận diện → chọn toán tử\n\n| Dấu hiệu đề bài | Toán tử RA |\n|---|---|\n| *\"for each / per / mỗi / từng X\"* | `X 𝓕_{func}(R)` — group by X |\n| *\"do not / no / without / không\"* | Set difference `−` (project cả 2 vế cùng schema trước) |\n| *\"for all / every / tất cả / mọi\"* | Division `÷` hoặc `double NOT EXISTS` |\n| Cần chỉ cột employee nhưng join lộ cột Department | Phải `π` về đúng cột employee sau join |\n\n---\n\n### 4.11. Canonical Worked Patterns\n\n**Pattern 1 — Average salary của female employees theo từng department:**\n```\n_{Dno} 𝓕_{average Salary}( σ_{Sex='F'}(Employee) )\n```\nBước: (1) σ lọc nữ → (2) group by Dno → (3) tính AVG(Salary). ✅ Đáp án Q4.\n\n**Pattern 2 — Employees không làm project nào:**\n```\nπ_{SSN, Fname, Minit, Lname}(Employee)\n  − π_{SSN, Fname, Minit, Lname}(Employee ⋈_{SSN=ESSN} WORKS_ON)\n```\nBước: (1) tất cả emp → (2) emp có trong WORKS_ON → (3) trừ. Hai vế `−` **phải cùng schema**. ✅ Đáp án Q2, Q9.\n\n**Pattern 3 — Số dependents của manager từng department:**\n```\n_{Mgr_ssn} 𝓕_{count Dependent_name}(Department ⋈_{Mgr_ssn=Essn} Dependent)\n```\nGrouping attr = `Mgr_ssn`; function = `count Dependent_name` (tên cụ thể, không dùng `count` trống). ✅ Đáp án Q6.\n\n**Pattern 4 — Tổng giờ làm từng project:**\n```\n_{Pname} 𝓕_{sum Hours}(Project ⋈_{Pnumber=Pno} WORKS_ON)\n```\nGrouping = `Pname`; function = `sum Hours`. ✅ Đáp án Q8.\n\n**Pattern 5 — Emp dept 5 làm >10h trên project ProductX:**\n```\nπ_{SSN, Fname, Lname}(\n  σ_{DNo=5}(Employee)\n  ⋈_{SSN=ESSN} (σ_{Hours>10}(WORKS_ON) ⋈_{Pno=Pnumber} σ_{PName='ProductX'}(Project))\n)\n```\nPhải dùng `⋈_{cond}` (SSN≠ESSN, Pno≠Pnumber) — natural join sai. ✅ Đáp án Q7.\n\n**Pattern 6 — Emp có tổng giờ >1000:**\n```\nπ_{Fname, Lname}(\n  σ_{sum_hours>1000}(\n    (_{Essn} 𝓕_{sum Hours}(WORKS_ON)) ⋈_{Essn=SSN} Employee\n  )\n)\n```\nAggregate **trước** rồi σ lọc trên alias `sum_hours`, sau đó join Employee. ✅ Đáp án Q42.\n\n**Pattern 7 — Natural join với MCQ Q16:**\n```\nR(A,B,C) * S(A,C) → T(A,B,C)  (nối trên A và C đồng thời)\nKết quả giữ các row thỏa A và C khớp cả 2 → 6 rows (C đáp án Q16)\n```\n\n---\n\n### 4.12. SQL ↔ RA So sánh nhanh\n\n| SQL | RA tương đương | Ghi chú |\n|---|---|---|\n| `SELECT A, C FROM R WHERE B=1` | `π_{A,C}(σ_{B=1}(R))` | `\\|SQL\\| ≥ \\|RA\\|` vì SQL giữ duplicates |\n| `SELECT dno, AVG(salary) FROM Employee GROUP BY dno` | `_{dno} 𝓕_{average salary}(Employee)` | Tương đương Q43C ✅ |\n| `SELECT * FROM A, B` (không WHERE) | `A × B` (Cartesian product!) | Bẫy: thiếu join condition |\n| `SELECT DISTINCT A, C FROM R WHERE B=1` | `π_{A,C}(σ_{B=1}(R))` | Hoàn toàn tương đương |\n\n> 🔥 **Q38/Q13:** `π_{A,C}(σ_{B=1}(R))` vs `SELECT A, C FROM R WHERE B=1` → `|RA| ≤ |SQL|` — RA loại duplicate, SQL không. Nếu {A,C} chứa key thì `|RA| = |SQL|`.\n\n---\n\n### 🎯 MCQ Traps §4\n\n1. 🔥 **σ = lọc HÀNG** (không phải chọn cột như SQL SELECT) — bẫy thường ra đề (Q19).\n2. 🔥 **Natural join `*` xét TÊN CỘT**, không xét foreign key: `SSN ≠ ESSN`, `Dnum ≠ Dnumber` → natural join sai (Q1, Q5, Q7, Q10 — xuyên suốt BK-LMS quiz).\n3. 🔥 **π loại trùng tự động (set); SQL SELECT giữ multiset → `|RA| ≤ |SQL|`** (Q13, Q38).\n4. 🔥 **Set ops (∪/∩/−) đòi union-compatible; × và ⋈ KHÔNG** — câu hỏi phân biệt ra nhiều lần (Q33, Q34, Q35, Q37).\n5. 🔥 **`R − S ≠ S − R`** — difference KHÔNG giao hoán.\n6. 🔥 **`∪/∩/−`: tên cột lấy theo toán hạng ĐẦU (R1)**, không phải R2.\n7. 🔥 **Aggregate `𝓕`: grouping attr bên TRÁI 𝓕**; thiếu grouping → 1 dòng toàn cục (Q4, Q6, Q8).\n8. 🔥 **Division ÷ = \"for all/every\"**; SQL equivalent = `double NOT EXISTS`; kết quả HK191-Q20: `{1111, 1113}` (Q15, Q28, Q32, Q40).\n9. 🔥 **`R ⟕ S = S ⟖ R`** — LEFT outer của R = RIGHT outer của S.\n10. 🔥 **`COUNT(*)` đếm dòng (kể NULL); `COUNT(col)` discard NULL** — quan trọng sau OUTER JOIN.\n11. 🔥 **`|R × S| = |R|·|S|`; `degree(R×S) = degree(R) + degree(S)`** — tính cardinality và degree (Q39).\n12. 🔥 **RA = procedural (HOW); Calculus = non-procedural (WHAT)** — tương đương biểu đạt nhưng khác bản chất (Q17).\n13. 🔥 **INNER = RIGHT OUTER iff mọi nhân viên đều là supervisor** (không có Superssn=NULL); nếu tồn tại Superssn=NULL → INNER ≠ RIGHT OUTER (HK191-Q32).\n14. 🔥 **Bound variable** nằm trong ∃/∀; **free variable** xuất hiện ngoài lượng từ (xác định output của biểu thức calculus).\n\n---\n\n### 🪄 Câu thần chú §4\n\n1. **σ cắt HÀNG — π cắt CỘT (loại trùng tự động) — ρ đổi tên**.\n2. **∪/∩/− đòi union-compatible; × và ⋈ KHÔNG cần**.\n3. **Complete set = {σ, π, ∪, −, ×}** — đủ suy ra mọi toán tử còn lại.\n4. **Natural join = cùng TÊN CỘT, bỏ cột trùng; Equijoin = cùng GIÁ TRỊ (=), giữ cả 2 cột**.\n5. **Division = \"với mọi\" = double `NOT EXISTS`**.\n6. **\"for each/per\" → grouping 𝓕; \"do not/without\" → set diff −; \"for all/every\" → ÷**.\n7. **RA closed: output luôn là relation → lồng phép tùy ý**.\n8. **`|RA π| ≤ |SQL SELECT|` — RA là set, SQL là multiset**.\n9. **OUTER JOIN giữ tuple không match + pad NULL; INNER bỏ**.\n10. **`R ⟕ S = S ⟖ R`** (LEFT của R = RIGHT của S).\n11. **Aggregate: fn arg cụ thể (`count Ssn`), không bỏ trống; group attr bên TRÁI 𝓕**.\n12. **Recursive closure cần `SQL3 WITH RECURSIVE` — RA cơ bản không tính được**.\n13. **Query tree: leaf = relation, internal = operator, thực thi leaf→root**.\n14. **Assignment `←` đặt tên trung gian, giúp viết biểu thức dài thành chuỗi bước**.\n\n---\n\n","file":"materials/DB-Final.md","section":13},{"id":"final-14","group":"final","kind":"source","title":"§5. SQL — Trọng số đề: 9 câu 🔥🔥","markdown":"## §5. SQL — Trọng số đề: 9 câu 🔥🔥\n\n### 5.1 Bản chất SQL: Declarative + Bag/Multiset\n\n🔑 **Keywords (EN):** `SQL = declarative`, `bag / multiset`, `DISTINCT`, `set vs. multiset`, `DDL / DML / DCL / TCL`\n\nSQL khác Relational Algebra ở chỗ:\n- **RA relation = set** → không có tuple trùng.\n- **SQL table / result = bag (multiset)** → có thể có dòng trùng.\n- `SELECT Salary FROM Employee;` → có thể trả về nhiều dòng cùng giá trị.\n- `SELECT DISTINCT Salary FROM Employee;` → loại trùng, tương đương `π` trong RA.\n\n| Nhóm | Lệnh | Mô tả |\n|---|---|---|\n| DDL | `CREATE`, `ALTER`, `DROP` | Định nghĩa / sửa / xóa cấu trúc |\n| DML | `SELECT`, `INSERT`, `UPDATE`, `DELETE` | Truy vấn + thao tác dữ liệu |\n| DCL | `GRANT`, `REVOKE` | Phân quyền |\n| TCL | `COMMIT`, `ROLLBACK`, `SAVEPOINT` | Quản lý transaction (một số slide gom vào DCL) |\n\n---\n\n### 5.2 DDL: CREATE TABLE, Data Types, Constraints\n\n🔑 **Keywords (EN):** `CREATE TABLE`, `CHAR(n)`, `VARCHAR(n)`, `DECIMAL(p,s)`, `DATE`, `TIMESTAMP`, `NOT NULL`, `DEFAULT`, `CHECK`, `UNIQUE`, `PRIMARY KEY`, `FOREIGN KEY`, `REFERENCES`, `ON DELETE`, `ON UPDATE`, `CASCADE`, `SET NULL`, `SET DEFAULT`, `NO ACTION`, `RESTRICT`, `INTERVAL`, `BIT(n)`, `BIT VARYING(n)`, `BOOLEAN`, `CHAR VARYING(n)`, `CREATE DOMAIN`, `CONSTRAINT`\n\n```sql\nCREATE TABLE Department (\n    Dname   VARCHAR(15) NOT NULL,\n    Dnumber INT         NOT NULL,\n    Mgr_ssn CHAR(9)     NOT NULL,\n    Mgr_start_date DATE,\n    PRIMARY KEY (Dnumber),\n    UNIQUE (Dname),\n    FOREIGN KEY (Mgr_ssn) REFERENCES Employee(Ssn)\n        ON DELETE SET NULL ON UPDATE CASCADE\n);\n```\n\n**Chọn kiểu dữ liệu đúng:**\n\n| Dữ liệu | Nên dùng | Lý do |\n|---|---|---|\n| SSN / CCCD | `CHAR(9)` | Giữ số 0 đầu, độ dài cố định |\n| Tên / địa chỉ | `VARCHAR(n)` | Độ dài thay đổi (`CHAR VARYING(n)` = `CHARACTER VARYING(n)` = synonym) |\n| Lương / tiền | `DECIMAL(10,2)` | Chính xác, không làm tròn như FLOAT |\n| Ngày | `DATE` | Chỉ ngày |\n| Ngày + giờ | `TIMESTAMP` | DATE + TIME |\n| Khoảng thời gian | `INTERVAL` | Giá trị tương đối để +/− date/time |\n| Cờ nhị phân | `BIT(n)` / `BIT VARYING(n)` | Chuỗi bit cố định / thay đổi |\n| Logic | `BOOLEAN` | TRUE / FALSE / NULL |\n\n**Referential Actions — bẫy quan trọng:**\n\n| Action | Khi parent bị xóa / update |\n|---|---|\n| `RESTRICT` / `NO ACTION` | Không cho nếu còn child |\n| `CASCADE` | Lan truyền sang child |\n| `SET NULL` | FK của child → NULL |\n| `SET DEFAULT` | FK của child → DEFAULT |\n\n> **Bẫy:** `ON DELETE CASCADE` khai báo ở **bảng con** (bảng chứa FK), không phải bảng cha. `DROP TABLE Department CASCADE` ≠ `ON DELETE CASCADE` — DROP CASCADE loại bỏ cả lược đồ phụ thuộc, không phải hành động referential.\n\n**Ví dụ QUIZ 6 Q10 — đọc kỹ FK chain:** với `Employee.Dno → Department ON DELETE CASCADE` và `Project.Dnum → Department ON DELETE CASCADE`, khi `DELETE FROM Department WHERE Dnumber = 4` → Department, tất cả Employee có Dno=4 **và** tất cả Project có Dnum=4 đều bị xóa theo.\n\n**QUIZ 6 Q15 — ALTER TABLE ADD UNIQUE:**\n```sql\nALTER TABLE Employee ADD Experience int UNIQUE;  -- CÓ THỂ LỖI\n```\nNếu bảng đã có dữ liệu, thêm cột với `UNIQUE` mà không có `DEFAULT` → nhiều dòng nhận NULL → **lỗi vi phạm UNIQUE** (trong quy ước SQL Server, nhiều NULL bị coi là vi phạm). Ngược lại, `ADD Experience int DEFAULT 1` hoặc `ADD Experience int NULL` thành công. `CHECK (Experience > 1)` **không** chặn NULL vì `NULL > 1 = UNKNOWN` (không phải FALSE).\n\n**CREATE DOMAIN — tái sử dụng kiểu dữ liệu:**\n```sql\nCREATE DOMAIN SSN_TYPE AS CHAR(9)\n    CHECK (VALUE REGEXP '[0-9]{9}');\n-- Dùng lại: Ssn SSN_TYPE NOT NULL\n```\n`CREATE DOMAIN DomainName AS DataType [CHECK(...)]` định nghĩa domain do người dùng tạo, tái dùng cho nhiều cột.\n\n**Đặt tên ràng buộc để sau này DROP được:**\n```sql\nALTER TABLE Employee\n    ADD CONSTRAINT chk_salary CHECK (Salary > 0);\n-- Để xóa: ALTER TABLE Employee DROP CONSTRAINT chk_salary;\n```\n`CONSTRAINT <name> ...` giúp `ALTER TABLE ... DROP CONSTRAINT <name>` sau này.\n\n**DROP SCHEMA:**\n```sql\nDROP SCHEMA Company CASCADE;   -- xóa cả nội dung bên trong\nDROP SCHEMA Company RESTRICT;  -- chỉ xóa nếu schema rỗng\n```\n\n---\n\n### 5.3 Thứ tự xử lý logic SELECT và WHERE vs HAVING\n\n🔑 **Keywords (EN):** `FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY`, `aggregate filter → HAVING`\n\n```\nFROM → (ON / JOIN) → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT\n```\n\n**Hệ quả:**\n- `WHERE` lọc **tuple trước** khi group; `HAVING` lọc **group sau** khi aggregate.\n- Không được dùng aggregate trực tiếp trong `WHERE`:\n  - `WHERE COUNT(*) > 2` ❌ → `GROUP BY … HAVING COUNT(*) > 2` ✅\n- `WHERE` không thấy alias đặt trong `SELECT`.\n- Cột không aggregate trong `SELECT` **bắt buộc** có trong `GROUP BY`.\n- **Mệnh đề tối thiểu:** chỉ `SELECT` (thường kèm `FROM`) là bắt buộc; `WHERE / GROUP BY / HAVING / ORDER BY` là OPTIONAL. SQL Server cho phép `SELECT 1+1` không cần FROM (HK241-Q1, F2024).\n\n```sql\n-- QUIZ 6 Q8: xóa nhân viên làm < 20 giờ trên tất cả project\nDELETE FROM Employee\nWHERE SSN IN (\n    SELECT ESSN FROM Works_on\n    GROUP BY ESSN\n    HAVING SUM(Hours) < 20\n);\n-- Sai: WHERE SUM(Hours) < 20  -- aggregate không được trong WHERE\n-- Sai: DELETE Employee WHERE ...  -- thiếu FROM\n-- Sai: WHERE SSN = (SELECT ...)  -- subquery trả nhiều dòng → dùng IN không dùng =\n```\n\n**QUIZ 6 Q11 — kiểu cũ vs JOIN:**\n```sql\n-- kiểu cũ (tương đương INNER JOIN):\nSELECT dno, count(Super_SSN), min(Salary), avg(Salary), max(Salary)\nFROM Employee, Works_on, Project\nWHERE SSN = Essn AND Pno = Pnumber AND Pname = 'ProductY'\nGROUP BY dno\nHAVING count(Super_SSN) >= 2;\n-- Đúng tương đương:\nFROM (Employee JOIN Works_on ON SSN=Essn) JOIN Project ON Pno = Pnumber\nWHERE Pname = 'ProductY'\nGROUP BY dno HAVING count(Super_SSN) >= 2;\n```\n\n| Clause | Lọc gì | Dùng aggregate trực tiếp? |\n|---|---|---|\n| `WHERE` | Tuple trước GROUP BY | **KHÔNG** |\n| `HAVING` | Group sau GROUP BY | **CÓ** |\n\n---\n\n### 5.4 JOIN: INNER, OUTER, NATURAL JOIN, Self-Join\n\n🔑 **Keywords (EN):** `INNER JOIN`, `LEFT OUTER JOIN`, `RIGHT OUTER JOIN`, `FULL OUTER JOIN`, `NATURAL JOIN`, `Cartesian product`, `self-join`, `LEFT JOIN … WHERE rightKey IS NULL`, `tuple variable`, `alias`\n\n- **Thiếu join condition** → **Cartesian product** (tích Đề-các): N×M dòng.\n- **Old-style** `FROM A, B WHERE A.k = B.k` ≡ `A JOIN B ON A.k = B.k` (INNER JOIN).\n- **LEFT JOIN** giữ tất cả dòng bên trái, bên phải NULL nếu không match.\n- **`LEFT JOIN … WHERE rightKey IS NULL`** = anti-join = \"A không có B nào tương ứng\".\n\n```sql\n-- Nhân viên không có dependent:\nSELECT E.Fname FROM Employee E\nLEFT JOIN Dependent D ON E.Ssn = D.Essn\nWHERE D.Essn IS NULL;\n```\n\n- **NATURAL JOIN** tự nối cột **cùng tên** — không hiểu FK. Trong COMPANY: `Employee.Ssn ≠ Works_on.Essn` nên `Employee NATURAL JOIN Works_on` **SAI**; đúng là `JOIN Works_on ON Ssn = Essn`.\n- **Self-join** luôn cần alias:\n\n```sql\nSELECT E.Fname AS EmpName, S.Fname AS SupervisorName\nFROM Employee E LEFT JOIN Employee S ON E.Super_ssn = S.Ssn;\n```\n\n- **Tuple variable / alias đổi tên cột:** `FROM Employee AS E(FN, M, LN, SSN, ...)` — `E`, `S` là \"tuple variables\"; dạng này đổi tên cả cột trong phạm vi truy vấn.\n\n**OUTER JOIN COUNT(\\*) trap:**\n```sql\n-- Sai: employee không có dependent vẫn COUNT=1 (dòng padding NULL):\nSELECT E.Ssn, COUNT(*) FROM Employee E\nLEFT JOIN Dependent D ON E.Ssn = D.Essn GROUP BY E.Ssn;\n\n-- Đúng: đếm dependent thực sự:\nSELECT E.Ssn, COUNT(D.Dependent_name) FROM Employee E\nLEFT JOIN Dependent D ON E.Ssn = D.Essn GROUP BY E.Ssn;\n```\n\n---\n\n### 5.5 NULL và 3-valued Logic\n\n🔑 **Keywords (EN):** `NULL`, `IS NULL`, `IS NOT NULL`, `3-valued logic`, `TRUE / FALSE / UNKNOWN`\n\n- **`WHERE Salary = NULL` → SAI** → luôn dùng `IS NULL` / `IS NOT NULL`.\n- Trong `WHERE` chỉ giữ lại dòng có điều kiện = **TRUE**; FALSE và **UNKNOWN** đều bị loại.\n\n```\nTRUE AND UNKNOWN  = UNKNOWN\nFALSE AND UNKNOWN = FALSE\nTRUE OR UNKNOWN   = TRUE\nFALSE OR UNKNOWN  = UNKNOWN\nNOT UNKNOWN       = UNKNOWN\n```\n\n- `CHECK (Experience > 1)` **không chặn NULL** vì `NULL > 1 = UNKNOWN`.\n- `AVG(Salary)` bỏ qua NULL tự động; `SUM(Salary) / COUNT(*)` **sai** khi Salary có NULL.\n\n---\n\n### 5.6 Subquery: IN, EXISTS, Correlated, ANY/ALL\n\n🔑 **Keywords (EN):** `IN`, `NOT IN`, `EXISTS`, `NOT EXISTS`, `correlated subquery`, `ANY`, `SOME`, `ALL`, `> ALL ≡ > MAX`, `> ANY ≡ > MIN`, `= ANY ≡ IN`, `UNIQUE(Q)`\n\n```sql\n-- IN: subquery không correlated\nSELECT Fname FROM Employee\nWHERE Dno IN (SELECT Dnumber FROM Department WHERE Dname='Research');\n\n-- EXISTS: correlated (tham chiếu outer)\nSELECT E.Fname FROM Employee E\nWHERE EXISTS (\n    SELECT * FROM Dependent D\n    WHERE D.Essn = E.Ssn AND D.Dependent_name = E.Fname\n);\n```\n\n- Subquery trả **nhiều dòng** → dùng `IN`, không dùng `=` (sẽ runtime error).\n- `NOT EXISTS` an toàn hơn `NOT IN` khi subquery có thể trả NULL.\n- **`UNIQUE(Q)`** — hàm SQL trả TRUE nếu subquery Q không có tuple trùng (kiểm tra tính duy nhất của kết quả).\n\n| Biểu thức | Trực giác | Tương đương |\n|---|---|---|\n| `x > ALL(Q)` | x lớn hơn mọi phần tử | `x > MAX(Q)` |\n| `x > ANY(Q)` | x lớn hơn ít nhất 1 | `x > MIN(Q)` |\n| `x = ANY(Q)` | x thuộc tập Q | `x IN (Q)` |\n| `x <> ALL(Q)` | x khác tất cả | `x NOT IN (Q)` |\n\n**QUIZ 6 Q4 — salary > max Research:**\n```sql\nSELECT ssn, fname, lname, dnumber, dname\nFROM Employee JOIN Department ON dno = dnumber\nWHERE salary > ALL (\n    SELECT salary FROM Employee JOIN Department ON dno=dnumber\n    WHERE dname='Research'\n);\n-- \"> ALL\" ≡ \"> MAX\". KHÔNG dùng \">= MAX\" (sẽ bao gồm cả đúng bằng max).\n-- KHÔNG dùng \"IN (SELECT MAX...)\" (IN kiểm tra = chứ không phải >).\n```\n\n**QUIZ 6 Q9 — EXISTS vs COUNT = 1:**\n```sql\n-- Đúng: \"có ít nhất 1 project\" dùng EXISTS:\nAND EXISTS (SELECT * FROM Works_on WHERE essn = ssn);\n-- Sai: AND (SELECT count(*) FROM Works_on WHERE essn = ssn) = 1;\n-- → \"= 1\" là \"đúng 1 project\", không phải \"ít nhất 1\".\n```\n\n---\n\n### 5.7 Pattern \"Không có\" và \"Tất cả\" (Double NOT EXISTS)\n\n🔑 **Keywords (EN):** `NOT EXISTS`, `double NOT EXISTS`, `relational division`, `set difference`, `\"for all\" pattern`\n\n**Pattern \"không có\" (anti-join):**\n```sql\n-- Nhân viên không có dependent:\nSELECT E.Fname FROM Employee E\nWHERE NOT EXISTS (SELECT * FROM Dependent D WHERE D.Essn = E.Ssn);\n```\n\n**Pattern \"tất cả\" — double NOT EXISTS (quan trọng nhất §5):**\n```sql\n-- QUIZ 6 Q6: nhân viên làm TẤT CẢ project của Research department\nSELECT *\nFROM Employee\nWHERE NOT EXISTS (\n    SELECT * FROM PROJECT JOIN DEPARTMENT ON dnum=dnumber\n    WHERE dname='Research'\n      AND pnumber NOT IN (SELECT pno FROM Works_on WHERE essn=ssn)\n);\n```\nĐọc: *\"Không tồn tại project Research nào mà nhân viên này CHƯA làm\"* → tức là đã làm **tất cả** project Research.\n\n**Lưu ý quan trọng:** Điều kiện này **không** yêu cầu nhân viên thuộc Research — nó chỉ kiểm tra nhân viên nào đã làm hết các project do Research kiểm soát. Điều kiện là về **project's controlling department**, không phải department của employee.\n\nPhiên bản double NOT EXISTS chuẩn:\n```sql\nSELECT E.Ssn FROM Employee E\nWHERE NOT EXISTS (\n    SELECT * FROM Project P\n    JOIN Department D ON P.Dnum = D.Dnumber\n    WHERE D.Dname = 'Research'\n    AND NOT EXISTS (\n        SELECT * FROM Works_on W\n        WHERE W.Essn = E.Ssn AND W.Pno = P.Pnumber\n    )\n);\n-- Đọc lớp ngoài: \"không có project Research nào …\"\n-- Đọc lớp trong: \"… mà không có dòng Works_on chứng minh E làm project đó\"\n```\n\n---\n\n### 5.8 Set Operations: UNION, INTERSECT, EXCEPT\n\n🔑 **Keywords (EN):** `UNION`, `UNION ALL`, `INTERSECT`, `EXCEPT`, `compatible columns`, `duplicate elimination`\n\n```sql\nUNION / INTERSECT / EXCEPT       -- mặc định loại trùng\nUNION ALL / INTERSECT ALL / EXCEPT ALL   -- giữ trùng (multiset)\n```\n\n- Hai SELECT phải có **cùng số cột** + kiểu tương thích theo vị trí.\n- `SELECT` mặc định **KHÔNG** loại trùng; `UNION` thì **có**.\n- **`UNION ALL` nhanh hơn `UNION`** vì bỏ qua bước khử trùng — ưu tiên khi cần tốc độ và chấp nhận duplicate.\n\n**QUIZ 6 Q5 — UNION đặt bên trong IN:**\n```sql\n-- Đúng: UNION nằm trong subquery của IN:\nSELECT * FROM Employee\nWHERE dno IN (\n    SELECT dnumber FROM Dept_locations WHERE dlocation LIKE 'Houston'\n    UNION\n    SELECT dnum FROM Project WHERE plocation LIKE 'Houston'\n);\n-- Sai: UNION dùng riêng với SELECT * (UNION ALL giữ trùng → trả duplicate employees).\n```\n\n---\n\n### 5.9 Aggregate Functions và GROUP BY\n\n🔑 **Keywords (EN):** `COUNT(*)`, `COUNT(col)`, `SUM`, `AVG`, `MIN`, `MAX`, `GROUP BY`, `HAVING`, `NULL discard`\n\n| Function | Xử lý NULL |\n|---|---|\n| `COUNT(*)` | Đếm **tất cả dòng** kể cả dòng chứa NULL |\n| `COUNT(col)` | **Bỏ** dòng có NULL ở col |\n| `COUNT(DISTINCT col)` | Bỏ NULL + đếm distinct |\n| `SUM / AVG / MIN / MAX(col)` | **Bỏ** NULL tự động |\n\n- Cột không aggregate trong `SELECT` **phải nằm** trong `GROUP BY`.\n- `AVG(Salary)` bỏ NULL — `SUM(Salary)/COUNT(*)` sai khi có NULL.\n\n---\n\n### 5.10 INSERT / UPDATE / DELETE\n\n🔑 **Keywords (EN):** `INSERT INTO`, `INSERT INTO … SELECT`, `UPDATE SET`, `DELETE FROM`, `subquery in UPDATE`, `referential integrity`, `ON DELETE CASCADE`\n\n```sql\n-- INSERT đúng cột:\nINSERT INTO Department VALUES ('Marketing', 10, '123456789', '2000-10-10');\n-- Mgr_ssn phải là SSN hợp lệ trong Employee → nếu '123456789' không tồn tại → lỗi FK.\n\n-- INSERT … SELECT — bulk insert nhiều tuple từ kết quả query:\nINSERT INTO HighEarner(Ssn, Fname, Salary)\nSELECT Ssn, Fname, Salary FROM Employee WHERE Salary > 50000;\n\n-- UPDATE với subquery (QUIZ 6 Q3):\nDECLARE @avg FLOAT;\nSET @avg = (SELECT average(Salary) FROM Employee);  -- AVG của TOÀN CÔNG TY\nUPDATE Employee SET Salary = @avg\nWHERE Dno = (SELECT Dnumber FROM Department WHERE Dname='Research');\n-- Sai nếu tính AVG của Research rồi gán cho Research → đệ quy tham chiếu.\n\n-- UPDATE có thể vi phạm: PK (trùng key), FK (không tồn tại), NOT NULL, CHECK.\n-- DELETE FROM Employee;  -- xóa TOÀN BỘ dữ liệu, bảng cấu trúc vẫn còn.\n-- DROP TABLE Employee;   -- xóa cả cấu trúc.\n```\n\n**DELETE NOT IN — xóa dòng cha không được tham chiếu:**\n```sql\n-- Xóa Department không có nhân viên nào:\nDELETE FROM Department\nWHERE Dnumber NOT IN (SELECT Dno FROM Employee);\n-- Luôn hợp lệ bất kể ON DELETE setting — chỉ xóa dòng không bị tham chiếu (HK211-Q4).\n```\n\n**QUIZ 6 Q1 — UPDATE nào chạy được:**\n- `UPDATE Department SET Dnumber = 1 WHERE Dname = 'Research';` → **Sai**: Dnumber là PK được Employee và Project reference → không thể đổi nếu không có `ON UPDATE CASCADE`.\n- `UPDATE Employee SET Dno = NULL WHERE Super_ssn IS NULL;` → **Sai**: `Dno INT NOT NULL` → không cho NULL.\n- `UPDATE Employee SET Salary = 45000, Dno = 1 WHERE Dno = (SELECT Dnumber FROM Department WHERE Dname='Research');` → **Đúng**.\n\n---\n\n### 5.11 VIEW và WITH CHECK OPTION\n\n🔑 **Keywords (EN):** `CREATE VIEW`, `WITH CHECK OPTION`, `WITH CASCADED CHECK OPTION`, `WITH LOCAL CHECK OPTION`, `updatable view`, `view for security`, `CASE WHEN`, `mask not delete rows`, `view auto-reflect`\n\n```sql\nCREATE VIEW EMP_D5 AS\nSELECT Ssn, Fname, Salary, Dno FROM Employee WHERE Dno = 5\nWITH CHECK OPTION;\n-- WITH CHECK OPTION chặn INSERT/UPDATE làm row rời khỏi điều kiện WHERE Dno=5.\n```\n\n**WITH CASCADED vs LOCAL CHECK OPTION (view phân cấp):**\n- `WITH CASCADED CHECK OPTION` (mặc định): kiểm tra điều kiện WHERE của **tất cả** view trong chuỗi kế thừa.\n- `WITH LOCAL CHECK OPTION`: chỉ kiểm tra điều kiện WHERE của **view hiện tại**; view cha không bị kiểm tra.\n\n**Điều kiện view UPDATABLE (đủ điều kiện):**\n- Không có `DISTINCT`.\n- `SELECT` chỉ chứa tên cột (không expression, không aggregate, không cột trùng).\n- `FROM` chỉ một bảng nguồn (không JOIN nhiều bảng).\n- Không có nested `SELECT` tham chiếu cùng bảng trong `FROM`.\n- Không có `GROUP BY` / `HAVING`.\n\n**View tự động phản ánh base table:** `SELECT` trong view được re-evaluated mỗi lần truy vấn → view luôn thể hiện trạng thái hiện tại của base table (HK202-Q20).\n\n**View thường KHÔNG updatable nếu có:**\n`DISTINCT`, `GROUP BY / HAVING`, `Aggregate`, `JOIN nhiều bảng`, `UNION / INTERSECT / EXCEPT`, cột tính toán, không chứa PK của base table.\n\n**View cho security — mask, không xóa dòng:**\n```sql\n-- Ẩn lương thật của manager (Super_ssn IS NULL = đó là top-level manager):\nCREATE VIEW Alice_View AS\nSELECT Fname, Lname, Ssn,\n       CASE WHEN superssn IS NULL THEN 0 ELSE salary END AS salary,\n       superssn, dno\nFROM Employee;\n-- KHÔNG dùng WHERE superssn IS NULL (sẽ xóa dòng thay vì mask).\n-- KHÔNG dùng <> NULL (syntax sai — phải IS NOT NULL).\n```\n\n---\n\n### 5.12 GRANT / REVOKE và ACID\n\n🔑 **Keywords (EN):** `GRANT`, `REVOKE`, `WITH GRANT OPTION`, `CASCADE revoke`, `GRANT CREATETAB`, `CREATE SCHEMA … AUTHORIZATION`, `SET AUTOCOMMIT OFF`, `COMMIT`, `ROLLBACK`, `ACID`, `Atomicity`, `Consistency`, `Isolation`, `Durability`\n\n```sql\nGRANT SELECT ON Employee TO A3;\nGRANT SELECT ON Employee TO A3 WITH GRANT OPTION;  -- A3 có thể cấp tiếp\nGRANT UPDATE(Salary) ON Employee TO A4;             -- cấp theo cột\nREVOKE SELECT ON Employee FROM A3;                  -- cascade xuống A3-đã-cấp-tiếp\n\n-- Account-level DDL privilege:\nGRANT CREATETAB TO A1;                              -- cho phép A1 tạo bảng\nCREATE SCHEMA Example AUTHORIZATION A1;             -- A1 là chủ schema Example\n```\n\n- `GRANT` không có `WHERE` → dùng **VIEW** cho row-level security.\n- `REVOKE` có thể **cascade** xuống người đã được cấp tiếp.\n\n**TCL — quản lý transaction:**\n```sql\nSET AUTOCOMMIT OFF;   -- tắt auto-commit; mọi thay đổi phải COMMIT tường minh\nCOMMIT;\nROLLBACK;\nSAVEPOINT sp1;\n```\n\n| Chữ | Tên | Nghĩa |\n|---|---|---|\n| A | **Atomicity** | all-or-nothing |\n| C | Consistency | DB hợp lệ → DB hợp lệ |\n| I | Isolation | transaction đồng thời như chạy riêng |\n| D | Durability | commit xong thì bền vững |\n\n> **Bẫy cổ điển:** A = **Atomicity** (KHÔNG phải Accuracy).\n\n---\n\n### 5.13 ASSERTION vs TRIGGER\n\n🔑 **Keywords (EN):** `CREATE ASSERTION`, `CHECK`, `TRIGGER`, `BEFORE`, `AFTER`, `INSTEAD OF`, `FOR EACH ROW`, `FOR EACH STATEMENT`\n\n- `CHECK` cấp bảng: kiểm trong **1 tuple**, không kiểm cross-table.\n- `ASSERTION`: ràng buộc **cross-table** — modern DBMS (SQL Server, MySQL) **hầu như không hỗ trợ** → dùng **TRIGGER thay thế ASSERTION** trong thực tế.\n- `TRIGGER`: tự chạy khi event xảy ra — linh hoạt hơn, là giải pháp thực tế.\n\n```sql\nCREATE ASSERTION Salary_constraint CHECK (\n    NOT EXISTS (\n        SELECT * FROM Employee E, Employee M, Department D\n        WHERE E.Dno=D.Dnumber AND D.Mgr_ssn=M.Ssn AND E.Salary > M.Salary\n    )\n);\n```\n\n---\n\n### 5.14 Stored Procedure, Function, Trigger, Cursor (T-SQL / SQL Server)\n\n🔑 **Keywords (EN):** `CREATE PROC`, `EXEC`, `OUTPUT param`, `CREATE FUNCTION`, `RETURNS`, `scalar function`, `table-valued function (TVF)`, `inline TVF`, `multi-statement TVF`, `dbo.`, `CREATE TRIGGER`, `AFTER`, `INSTEAD OF`, `INSERTED`, `DELETED`, `CURSOR`, `DECLARE CURSOR`, `OPEN`, `FETCH`, `CLOSE`, `DEALLOCATE`\n\n**Bảng so sánh 3 đối tượng quan trọng:**\n\n| Tiêu chí | Procedure | Scalar Function | Table-Valued Function |\n|---|---|---|---|\n| Tạo bằng | `CREATE PROC` | `CREATE FUNCTION … RETURNS type` | `CREATE FUNCTION … RETURNS TABLE` hoặc `RETURNS @t TABLE(...)` |\n| Gọi bằng | `EXEC proc_name` | Trong `SELECT`, `WHERE` → `dbo.f(...)` | Trong `FROM` → `FROM dbo.tvf(...)` |\n| Return | Không bắt buộc | Bắt buộc 1 scalar | Bắt buộc 1 table |\n| Multiple result sets | **Có** | Không | Không |\n| Dùng trong SELECT | **KHÔNG** | **CÓ** | Chỉ trong FROM |\n| Modify data (INSERT/UPDATE) | Có thể | Thường không | Thường không |\n\n**Stored procedure = lựa chọn tốt nhất cho INSERT cần giá trị dẫn xuất:**\n> Khi INSERT cần tính toán tại thời điểm gọi (rental_time = NOW(), unit_price = giá hiện tại, total = price × days), **Stored Procedure** là tốt nhất: tính dẫn xuất tại call-time. Trigger = reactive enforcement sau khi event xảy ra; CHECK = ràng buộc tĩnh trên 1 cột, không dẫn xuất cross-table (HK191-Q8).\n\n**Procedure với OUTPUT param (QUIZ 7 Q2, Q12):**\n```sql\nCREATE PROC getCount @dname VARCHAR(15), @count INT OUT\nAS\nSET @count = (SELECT COUNT(*)\n              FROM Employee\n              WHERE ssn IN (\n                  SELECT essn FROM Works_on\n                  WHERE pno IN (\n                      SELECT pnumber FROM Project JOIN Department ON dnum = dnumber\n                      WHERE dname = @dname)));\n-- Phải dùng SET @count = (...) để gán vào OUT param.\n-- Bare SELECT COUNT(*) KHÔNG gán vào @count.\n\n-- Cách gọi đúng (QUIZ 7 Q12):\nDECLARE @name VARCHAR(15), @cnt INT;\nSET @name = 'Research';\nEXEC getCountEmployee @name, @cnt OUT;\nPRINT @cnt;\n```\n\n**Scalar Function (QUIZ 7 Q11):**\n```sql\nCREATE FUNCTION countProject (@dname VARCHAR(15))\nRETURNS INT AS BEGIN\n    DECLARE @cnt INT;\n    SET @cnt = (SELECT COUNT(*) FROM Project\n                WHERE dnum = (SELECT dnumber FROM Department WHERE dname = @dname));\n    RETURN @cnt;\nEND;\n\n-- Gọi đúng: dbo. prefix trong SELECT/WHERE:\nSELECT dnumber, dname, dbo.countProject(dname) project_number\nFROM Department\nWHERE dbo.countProject(dname) > 1;\n-- Sai: EXEC dbo.countProject('Research') -- EXEC dùng cho procedure, không dùng cho function.\n```\n\n**Multi-statement Table-Valued Function (QUIZ 7 Q8):**\n```sql\n-- Gọi đúng: trong FROM, không dùng EXEC:\nDECLARE @dname VARCHAR(15);\nSET @dname = (SELECT dname FROM Department WHERE dnumber = 5);\nSELECT * FROM getSum(@dname) WHERE AverageHours > 10.0;\n-- Sai: FROM getSum(5) -- không truyền INT trực tiếp nếu param VARCHAR.\n-- Sai: EXEC getSum @dname -- EXEC dành cho procedure.\n```\n\n**Procedure trả nhiều result set vs Function (QUIZ 7 Q7):**\n> Procedure có thể trả **nhiều result set**; Function chỉ trả **1** (scalar hoặc 1 table).\n> TVF không hiệu quả hơn base table mặc định — đây là bẫy MCQ.\n\n---\n\n### 5.15 Trigger: INSERTED / DELETED và AFTER vs INSTEAD OF\n\n🔑 **Keywords (EN):** `INSERTED` (virtual table), `DELETED` (virtual table), `AFTER INSERT`, `AFTER UPDATE`, `AFTER DELETE`, `INSTEAD OF DELETE`, `ROLLBACK` trong trigger\n\n| Event | `INSERTED` | `DELETED` |\n|---|---|---|\n| `INSERT` | Row **mới** vừa thêm | Rỗng |\n| `DELETE` | Rỗng | Row **cũ** vừa xóa |\n| `UPDATE` | Row **mới** (sau khi update) | Row **cũ** (trước khi update) |\n\n```sql\n-- QUIZ 7 Q13 — AFTER DELETE, cập nhật derived column:\nCREATE TRIGGER trigger1 ON Works_on AFTER DELETE\nAS BEGIN\n    UPDATE Project\n    SET number = (SELECT COUNT(*) FROM Works_on WHERE pno = pnumber)\n    WHERE Pnumber IN (SELECT DISTINCT pno FROM deleted);\nEND;\n-- Trigger cập nhật [number] của project BỊ ẢNH HƯỞNG (lọc từ deleted) sau khi xóa Works_on.\n\n-- QUIZ 7 Q6 — AFTER INSERT kích hoạt khi nào:\nCREATE TRIGGER trigger3 ON Project AFTER INSERT AS BEGIN\n    IF NOT EXISTS (SELECT * FROM Dept_locations, inserted\n                   WHERE dnumber = inserted.dnum AND dlocation = inserted.plocation)\n    BEGIN RAISERROR(...); ROLLBACK; RETURN; END;\nEND;\n-- Chỉ kích hoạt bởi INSERT có plocation (không phải SELECT/UPDATE/DELETE).\n-- INSERT không có plocation → inserted.plocation = NULL → điều kiện UNKNOWN → trigger rollback.\n-- insert into project (pname, pnumber, plocation, dnum) values ('Sales', 15, 'Stafford', 5); -- ✅ kích hoạt\n\n-- QUIZ 7 Q3 — INSTEAD OF DELETE:\nCREATE TRIGGER trigger2 ON Employee INSTEAD OF DELETE AS BEGIN\n    IF NOT EXISTS (SELECT * FROM Employee e JOIN deleted d ON e.dno = d.dno)\n        UPDATE Employee SET status = 1 WHERE ssn IN (SELECT ssn FROM deleted);\n    ELSE\n        DELETE FROM Employee WHERE ssn IN (SELECT ssn FROM deleted);\nEND;\n-- Logic: nếu KHÔNG CÒN nhân viên nào khác cùng phòng (deleted là dòng cuối cùng của dept)\n--        → đặt status = 1 thay vì xóa.\n-- Nếu CÒN nhân viên khác cùng phòng → xóa bình thường.\n\n-- QUIZ 7 Q15 — AFTER UPDATE: reject nếu project.plocation không trùng dept location.\n-- Bảo đảm project luôn cùng địa điểm với department kiểm soát nó.\n```\n\n**Trigger vs Procedure — điểm khác biệt cốt lõi (QUIZ 7 Q14):**\n> Trigger **tự động kích hoạt** theo event trên table/updatable view; Procedure **phải được gọi** tường minh (EXEC/CALL). Đây là sự khác biệt chính — không phải số bảng nó động đến.\n\n---\n\n### 5.16 Cursor\n\n🔑 **Keywords (EN):** `CURSOR`, `DECLARE CURSOR`, `OPEN`, `FETCH NEXT`, `CLOSE`, `DEALLOCATE`, `set-based thinking`\n\n```text\nDECLARE cursor_name CURSOR FOR SELECT ...\nOPEN cursor_name\nFETCH NEXT FROM cursor_name INTO @var\n-- xử lý từng dòng\nCLOSE cursor_name\nDEALLOCATE cursor_name\n```\n\n> **Nguyên tắc:** SQL nên xử lý theo **tập (set-based)**. Cursor duyệt từng dòng → chậm hơn query tập hợp. Chỉ dùng khi thật sự cần xử lý từng row riêng.\n\n---\n\n### 5.17 Query Processing Pipeline\n\n🔑 **Keywords (EN):** `query processing pipeline`, `syntax analysis`, `query optimization`, `code generation`, `query execution`, `table scan vs index scan`\n\n```\nSQL string\n  → Syntax Analysis & Conversion (parse, check schema)\n  → Query Optimization (chọn execution plan: table scan hay index scan)\n  → Code Generation & Interpretation\n  → Query Execution (kết quả)\n```\n\nDBMS chọn **index scan** nếu có index phù hợp (trên `Dno` chẳng hạn), hoặc **full table scan** nếu không có. Quyết định này xảy ra ở bước **Query Optimization**.\n\n---\n\n### 🎯 MCQ Traps §5\n\n1. 🔥 `= NULL` **luôn sai** → phải dùng `IS NULL`.\n2. 🔥 Aggregate (`COUNT`, `SUM`…) trong `WHERE` → **lỗi** → chuyển sang `HAVING`.\n3. 🔥 `> ALL(Q)` ≡ `> MAX(Q)` — **không** phải `>= MAX` và **không** phải `IN (MAX)`.\n4. 🔥 Double NOT EXISTS = \"làm tất cả\" — lớp ngoài \"không có project nào\", lớp trong \"chưa làm project đó\".\n5. 🔥 `EXISTS` = \"ít nhất 1\" ≠ `COUNT(*) = 1` = \"đúng 1\".\n6. 🔥 `COUNT(*)` sau `LEFT JOIN` đếm cả dòng NULL padding → **phải dùng** `COUNT(right_col)`.\n7. 🔥 `EXEC` chỉ dành cho **procedure**; function gọi qua `dbo.f()` trong SELECT/WHERE, TVF gọi trong FROM.\n8. 🔥 OUTPUT param trong procedure **phải `SET @out = (...)`** — bare `SELECT COUNT(*)` không gán vào @out.\n9. 🔥 Trigger: `INSERTED` = row **mới**, `DELETED` = row **cũ**; cả hai đều có trong `UPDATE`.\n10. 🔥 `AFTER INSERT` chỉ kích hoạt bởi **INSERT** — SELECT/UPDATE/DELETE không kích hoạt.\n11. 🔥 `ON DELETE CASCADE` khai báo ở **bảng con** (chứa FK) — không phải bảng cha.\n12. 🔥 `ALTER TABLE ADD col UNIQUE` có thể **lỗi** nếu bảng đã có nhiều dòng (nhiều NULL = unique violation).\n13. 🔥 `SECONDARY KEY` **không phải** SQL syntax — secondary/candidate key khai báo bằng `UNIQUE`.\n14. 🔥 `DROP TABLE T CASCADE` ≠ `ON DELETE CASCADE` — DROP CASCADE xóa lược đồ phụ thuộc, không phải dữ liệu.\n15. 🔥 `DELETE FROM T;` (thiếu WHERE) = xóa **toàn bộ dữ liệu**, bảng vẫn còn; `DROP TABLE T` = xóa cả cấu trúc.\n16. 🔥 `SELECT` + `FROM` là tối thiểu; `WHERE/GROUP BY/HAVING/ORDER BY` là OPTIONAL — `SELECT 1+1` hợp lệ không cần FROM (SQL Server).\n17. 🔥 **Alias scope:** trong correlated subquery, đặt tên alias che table-name gốc — dùng sai scope gây lỗi biên dịch (HK241-Q2).\n18. 🔥 **Stored procedure = tốt nhất** cho INSERT cần tính giá trị dẫn xuất tại call-time; Trigger = reactive; CHECK = ràng buộc tĩnh 1 cột.\n19. 🔥 **ASSERTION** hầu như không được hỗ trợ trong modern DBMS → dùng TRIGGER thay thế.\n20. 🔥 `WITH CASCADED CHECK OPTION` kiểm tra toàn bộ chuỗi view; `WITH LOCAL CHECK OPTION` chỉ kiểm tra view hiện tại.\n\n---\n\n### 🪄 Câu thần chú §5\n\n1. SQL = bag (multiset) → `SELECT DISTINCT` mới loại trùng như π RA.\n2. Thứ tự xử lý: **FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY**.\n3. WHERE lọc tuple; HAVING lọc group — không hoán đổi được.\n4. NULL so sánh = UNKNOWN → chỉ `IS NULL` / `IS NOT NULL` mới đúng.\n5. `> ALL` = `> MAX`; `> ANY` = `> MIN`; `= ANY` = `IN`.\n6. \"Tất cả\" = double NOT EXISTS: \"không có cái X nào mà ta chưa làm\".\n7. `EXISTS` = \"ít nhất 1\" ≠ `COUNT = 1` = \"đúng 1\".\n8. `LEFT JOIN + WHERE rightKey IS NULL` = anti-join = \"không có\".\n9. `COUNT(*)` sau LEFT JOIN đếm cả NULL → dùng `COUNT(right_col)` khi cần đếm matched.\n10. Procedure: `EXEC` + có thể nhiều result set; Function: `dbo.f()` hoặc `FROM tvf()` + chỉ 1 result.\n11. OUTPUT param: bắt buộc `SET @out = (...)` trong thân procedure; bare `SELECT` không gán.\n12. Trigger: `INSERTED` = mới, `DELETED` = cũ; UPDATE có cả hai.\n13. Trigger khác procedure ở **activation**: trigger tự động theo event, procedure phải EXEC.\n14. `ON DELETE CASCADE` đặt ở **bảng con**; ACID: **A = Atomicity** (không phải Accuracy).\n15. `DROP TABLE CASCADE` ≠ referential CASCADE; `SECONDARY KEY` không tồn tại → dùng `UNIQUE`.\n16. Query pipeline: **Parse → Optimize → Generate → Execute** — index scan hay table scan quyết định ở Optimize.\n17. `INSERT INTO T SELECT ...` = bulk insert từ query; `UNION ALL` nhanh hơn `UNION` (bỏ bước khử trùng).\n18. View tự động phản ánh base table (re-evaluated mỗi truy vấn); `WITH CASCADED CHECK OPTION` = kiểm tra toàn chuỗi.\n19. ASSERTION = cross-table constraint nhưng modern DBMS không hỗ trợ → dùng TRIGGER.\n20. Stored procedure tốt nhất cho INSERT tính giá trị dẫn xuất tại call-time.\n\n---\n\n","file":"materials/DB-Final.md","section":14},{"id":"final-15","group":"final","kind":"source","title":"§6. FUNCTIONAL DEPENDENCIES & NORMALIZATION — Trọng số đề: 6 câu 🔥","markdown":"## §6. FUNCTIONAL DEPENDENCIES & NORMALIZATION — Trọng số đề: 6 câu 🔥\n\n> **Nguồn chính:** `Lectures/07_FD_v2.pdf` · `Final/VoTien/Normalization.pdf` · `Tutorial/DB-Chapter7.md`  \n> **Tập trung:** tính `X⁺`, tìm tất cả candidate key, xác định NF cao nhất, phân rã BCNF, anomalies, lossless join.\n\n---\n\n### 6.1. Khái niệm nền tảng\n\n🔑 **Keywords (EN):** functional dependency, determinant, trivial / non-trivial FD, F⁺ (closure of FD set), X⁺ (closure of attribute set), superkey, candidate key, primary key, prime attribute, non-prime attribute, NULL interpretations.\n\n**Functional dependency (FD)** `X → Y`: với mỗi giá trị của X, tồn tại **duy nhất** một giá trị của Y. FD phản ánh **ngữ nghĩa thực tế** của dữ liệu — do **database designer** quyết định (QUIZ 8 Q10), không thể chứng minh từ một instance mẫu (mẫu chỉ có thể *bác bỏ* FD).\n\n**NULL — 3 cách diễn giải (Lec07):**\n\n| Diễn giải | Nghĩa |\n|---|---|\n| **(a) attribute does not apply** | Attribute không áp dụng cho entity này |\n| **(b) value unknown** | Giá trị tồn tại nhưng chưa biết |\n| **(c) value known but not yet recorded** | Biết giá trị nhưng chưa nhập vào hệ thống |\n\n> NULL không phải 0, không phải chuỗi rỗng — ba nghĩa trên là lý do chính tại sao thiết kế tốt cần tránh NULL không cần thiết (đây là **informal guideline**, xem §6.12).\n\n**Superkey vs Candidate Key vs Primary Key:**\n\n```\nSuperkey:       K sao cho mọi cặp tuple t1[K] ≠ t2[K] (CHỈ đòi duy nhất, KHÔNG đòi minimal)\nCandidate Key:  Superkey tối giản (minimal superkey)\nPrimary Key:    1 candidate key được DBA chọn làm khóa chính\n```\n\n> 🔥 **Bẫy HK192/HK191-Q16:** Phát biểu \"K sao cho mọi cặp tuple t1[K]≠t2[K]\" = định nghĩa **SUPERKEY**, KHÔNG phải primary key hay candidate key. PK = minimal superkey.\n\n**Phân biệt F⁺ và X⁺ — cực dễ nhầm:**\n\n| Ký hiệu | Chứa gì | Dùng để |\n|---|---|---|\n| **F⁺** | Tất cả **FD** suy ra được từ F | Kiểm equivalence, minimal cover |\n| **X⁺** | Tất cả **attribute** suy ra được từ X dựa trên F | Tìm superkey/CK, kiểm `X→Y` |\n\n```\nF = {A→B, B→C}\nF⁺ chứa: A→B, B→C, A→C, AB→C, …  (các luật)\nA⁺ = {A, B, C}                    (các cột)\n```\n\n**Các loại FD:**\n\n| Loại | Định nghĩa |\n|---|---|\n| **Trivial** | `X → Y` với `Y ⊆ X` |\n| **Non-trivial** | `X → Y` với `Y ⊄ X` |\n| **Full FD** | `X → A` không tồn tại `Y ⊂ X` với `Y → A` |\n| **Partial FD** | `X → A` và ∃ `Y ⊂ X` với `Y → A` (gây vi phạm 2NF) |\n| **Transitive FD** | `X → Y → A`, Y không phải CK (gây vi phạm 3NF nếu A nonprime) |\n\n---\n\n### 6.2. Armstrong Inference Rules — bắt buộc thuộc\n\n🔑 **Keywords (EN):** Armstrong's axioms, reflexivity, augmentation, transitivity, union rule, decomposition rule, pseudotransitivity rule.\n\n```\nGốc (sound & complete):\n  IR1 Reflexive:     Y ⊆ X           ⟹  X → Y\n  IR2 Augmentation:  X → Y           ⟹  XZ → YZ\n  IR3 Transitive:    X → Y, Y → Z    ⟹  X → Z\n\nSuy ra (derived):\n  Decomposition:     X → YZ          ⟹  X → Y  và  X → Z\n  Union:             X → Y, X → Z    ⟹  X → YZ\n  Pseudo-transitive: X → Y, WY → Z   ⟹  WX → Z\n```\n\n> 🔥 **Bẫy VoTien Q5/Q6 (QUIZ 8):** Union rule cho `X → YZ`, KHÔNG suy ra `Y → Z`. Không có **Symmetry rule** — `X → Y` KHÔNG suy ra `Y → X`.\n\n> 🔥 **Bẫy FD derivability (HK211-Q27):** `R(A,B,C,D,E)`, `F={AB→CE, B→D, D→A}`. `B→E` có suy ra được không?  \n> `B⁺ = {B} → B→D → {B,D} → D→A → {A,B,D}` — không có C, không thể kích hoạt AB→CE.  \n> → `B⁺ = {A,B,D}`, E ∉ B⁺ → **B→E KHÔNG suy ra được**. Luôn kiểm bằng closure của LHS, đừng suy diễn bằng \"cảm giác\".\n\n---\n\n### 6.3. Tính X⁺ (Algorithm 16.1) — kỹ năng cốt lõi\n\n🔑 **Keywords (EN):** attribute closure, X⁺ algorithm, superkey test, FD derivability test.\n\n```\nX⁺ := X\nrepeat\n    for each FD Y → Z in F:\n        if Y ⊆ X⁺:  X⁺ := X⁺ ∪ Z\nuntil X⁺ không đổi\n\n→ X⁺ = R  ⟺  X là superkey\n→ X superkey VÀ minimal  ⟺  X là candidate key (CK)\n→ X → Y suy ra được từ F  ⟺  Y ⊆ X⁺\n```\n\n**Ví dụ có bước:** `R(A,B,C,D,E)`, `F = {AB→C, CD→E, DE→B}` (VoTien Q8/Q9):\n\n```\n{A,B}⁺:\n  AB→C: {A,B,C}   Hết → {A,B,C}  ≠ R → không phải superkey\n\n{A,B,D}⁺:\n  AB→C: {A,B,C,D}\n  CD→E: {A,B,C,D,E} = R → superkey ✓\n  Có thể bỏ A? {B,D}⁺: BD→C(không), CD→E(C chưa có) → {B,D} → không đủ\n  → {A,B,D} là candidate key\n```\n\n**Ví dụ closure chuỗi (HK192):** `F = {A→BC, CD→E, B→D, E→A}`\n\n```\n{A}⁺:\n  A→BC: {A,B,C}\n  B→D:  {A,B,C,D}\n  CD→E: {A,B,C,D,E}\n  E→A:  đã có A\n  → {A}⁺ = {A,B,C,D,E} = R → A là superkey (và candidate key nếu minimal)\n```\n\n---\n\n### 6.4. Tìm tất cả Candidate Keys (Phương pháp U_l / U_r / U_b)\n\n🔑 **Keywords (EN):** candidate key, U_left, U_right, U_both, key-finding algorithm, minimal superkey.\n\n```\nPhân loại attribute:\n  U_l = chỉ xuất hiện ở LHS  → BẮT BUỘC trong MỌI CK\n  U_r = chỉ xuất hiện ở RHS  → KHÔNG BAO GIỜ trong CK\n  U_b = cả hai vế             → cần thử\n\nQuy trình:\n  1. Tính U_l⁺. Nếu = R → U_l là CK duy nhất.\n  2. Nếu chưa đủ: thử U_l ∪ (tập con của U_b), tính closure.\n     - closure = R VÀ tối giản → CK\n     - closure = R không tối giản → superkey\n```\n\n**Ví dụ đầy đủ — QUIZ 8 Q1:** `R(A,B,C,D,G,H,I,J)`, `F = {AB→DHI, H→G, C→BJ}`\n\n```\nPhân loại: U_l = {A,C}, U_r = {D,G,I}, U_b = {B,H,J}\n(không có attribute hoàn toàn vắng — A và C đều chỉ ở LHS)\n\n{A,C}⁺:\n  C→BJ: {A,B,C,J}\n  AB→DHI: {A,B,C,D,H,I,J}\n  H→G: {A,B,C,D,G,H,I,J} = R ✓\n  Bỏ A? {C}⁺ = {B,C,J,D,H,G,I} (không có A) → không đủ\n  Bỏ C? {A}⁺ = {A} → không đủ\n→ CK duy nhất = {A,C}   ← Đáp án QUIZ 8 Q1: E\n```\n\n**Ví dụ — QUIZ 8 Q2:** `R(A,B,C,D,G,H)`, `F = {AC→D, G→AB, C→GH}`\n\n```\nU_l = {} (không có), U_r = {D}, U_b = {A,B,C,G,H}\nC⁺: C→GH → {C,G,H}; G→AB → {A,B,C,G,H}; AC→D → {A,B,C,D,G,H} = R ✓\nBỏ được gì từ C? Không thể (C là tập 1 phần tử)\n→ CK = {C}   ← Đáp án QUIZ 8 Q2: A\n```\n\n**Ví dụ — QUIZ 8 Q8:** `R(A,B,C,D,E,G,H)`, `F = {AB→EH, A→CG, C→DE}`\n\n```\n(AB)⁺:\n  A→CG: {A,B,C,G}\n  C→DE: {A,B,C,D,E,G}\n  AB→EH: {A,B,C,D,E,G,H} = R ✓\n  Bỏ B? A⁺ = {A,C,D,E,G} → thiếu B,H\n  → {A,B} là CK   ← Đáp án QUIZ 8 Q8: E\n```\n\n> 🔥 **Trap:** Algo \"bỏ từng attribute\" chỉ tìm **1 key** (phụ thuộc thứ tự). Muốn **tất cả CK** phải dùng phương pháp U_l/U_r/U_b.\n\n---\n\n### 6.5. Minimal Cover (Canonical Cover) — Algorithm 16.2\n\n🔑 **Keywords (EN):** minimal cover, canonical cover, FD set equivalence, F covers G, redundant FD, extraneous attribute.\n\n```\n3 bước:\n  B1. Tách RHS đơn:   AB→CD  ⟹  AB→C và AB→D\n  B2. Rút LHS:        XY→A: bỏ Y nếu (X)⁺ đã chứa A\n  B3. Bỏ FD thừa:     bỏ f nếu (F − {f})⁺ vẫn chứa f\n```\n\n**Ví dụ VoTien Q10:** `F = {AB→CD, A→C, C→D, D→E}`\n\n```\nB1: {AB→C, AB→D, A→C, C→D, D→E}\nB2: AB→C: bỏ B (vì A→C đã có) → A→C (trùng → loại)\n    AB→D: bỏ B (vì A→C, C→D → A→D) → A→D\nB3: A→D dư vì A→C, C→D suy ra → loại\nKết quả: Fmin = {A→C, C→D, D→E}\n```\n\n**F ≡ G** ⟺ F covers G VÀ G covers F (kiểm: ∀ `X→Y ∈ G`, `Y ⊆ X⁺` theo F).\n\n> 🔥 Minimal cover **không duy nhất** — có thể tồn tại nhiều tập minimal tương đương.\n\n---\n\n### 6.6. Prime vs Non-prime Attribute\n\n🔑 **Keywords (EN):** prime attribute, non-prime attribute, candidate key membership.\n\n```\nPrime    = thuộc ít nhất MỘT candidate key\nNon-prime = không thuộc CK nào\n```\n\nVí dụ `TEACH(Student, Course, Instructor)`, CK = `{Student,Course}` và `{Student,Instructor}` → tất cả 3 attribute đều **prime**.\n\n---\n\n### 6.7. Normal Forms — Định nghĩa chính xác\n\n🔑 **Keywords (EN):** 1NF, 2NF, partial dependency, 3NF, transitive dependency, BCNF (Boyce-Codd Normal Form), 4NF, MVD (multivalued dependency), 5NF (PJNF), lossless join, dependency preservation.\n\n| NF | Điều kiện | Vi phạm điển hình |\n|---|---|---|\n| **1NF** | Mọi ô **atomic** (không composite, không multivalued, không nested) | Cell chứa nhiều giá trị |\n| **2NF** | 1NF + mọi nonprime attribute **full FD** vào mọi CK | Tồn tại partial dep (phần của CK → nonprime) |\n| **3NF** | ∀ FD non-trivial `X→A`: X **superkey** HOẶC A **prime** | Transitive dep qua nonprime (X→Y→A, Y không CK, A nonprime) |\n| **BCNF** | ∀ FD non-trivial `X→A`: X **phải là superkey** | FD với LHS không phải superkey (kể cả A prime) |\n| **4NF** | ∀ MVD non-trivial `X ↠ Y`: X **superkey** | Cartesian-product redundancy độc lập |\n| **5NF** | ∀ join dependency non-trivial: implied by candidate keys | Join dep không suy ra từ CK |\n\n**Thứ tự nghiêm ngặt:** 5NF ⊂ 4NF ⊂ BCNF ⊂ 3NF ⊂ 2NF ⊂ 1NF\n\n> 🔥 **Quy tắc báo cáo NF:** Nếu 2NF bị vi phạm → highest NF = **1NF** (không phải \"2NF không thỏa\"). Luôn báo cáo dạng chuẩn **thấp nhất đã thỏa** mà không vi phạm gì cao hơn.\n\n> 🔥 **Trick:** Mọi CK chỉ gồm **1 attribute đơn** ⟹ **tự động 2NF** (không thể có partial dep). Cẩn thận: phải **mọi CK** đều đơn; nếu còn 1 CK composite thì vẫn phải kiểm.\n\n---\n\n### 6.8. Worked Examples — Xác định NF cao nhất\n\n🔑 **Keywords (EN):** highest normal form, NF determination, partial dependency check, transitive dependency check, BCNF violation.\n\n**Ví dụ A — QUIZ 9 Q1 (1NF):** `R(A,B,C,D,G,H)`, `F = {A→C, BC→AD, G→H, B→G}`, Keys = `{AB, BC}`\n\n```\nKiểm 2NF: B là tập con thực sự của CK {AB}.\n  B→G: B ⊂ {AB}, G là nonprime → PARTIAL DEP → vi phạm 2NF\n→ Highest NF = 1NF\nĐáp án: \"1NF because B→G violates 2NF's condition.\"\nTrap: đáp án \"2NF because B→G violates 3NF\" là SAI — phải kiểm 2NF trước!\n```\n\n**Ví dụ B — QUIZ 9 Q2 (1NF):** `R(A,B,C,D,G,H)`, `F = {AB→CD, AD→BC, AC→B, D→GH}`, Keys = `{AB, AC, AD}`\n\n```\nKiểm 2NF: D là tập con thực sự của CK {AD}.\n  D→GH: D ⊂ {AD}, G và H là nonprime → PARTIAL DEP → vi phạm 2NF\n→ Highest NF = 1NF\nĐáp án: \"1NF because D→GH violates 2NF's condition.\"\n```\n\n**Ví dụ C — QUIZ 9 Q3 (1NF):** `R(A,B,C,D,G,H,I,J)`, `F = {AB→DHI, H→G, C→BJ}`, Key = `{AC}`\n\n```\nKiểm 2NF: C ⊂ {AC}, C→BJ: B và J nonprime → PARTIAL DEP → vi phạm 2NF\n→ Highest NF = 1NF\nĐáp án: \"1NF because C→BJ violates 2NF's condition.\"\n```\n\n**Ví dụ D — QUIZ 9 Q4 (BCNF):** `R(A,B,C,D,G,H)`, `F = {AB→CD, AD→BC, AC→BGH}`, Keys = `{AB, AD, AC}`\n\n```\nPrime = {A,B,C,D} (mọi LHS của CK). G, H nonprime.\nKiểm từng FD:\n  AB→CD: AB là CK ✓\n  AD→BC: AD là CK ✓\n  AC→BGH: AC là CK ✓\n→ Mọi LHS là superkey → BCNF ✓\nĐáp án: BCNF ← QUIZ 9 Q4\n```\n\n**Ví dụ E — VoTien Q16 / MCQ Q39 (3NF không BCNF):** `R(A,B,C,D,E,F)`, `F = {AB→EFDC, EF→A}`\n\n```\nCK: {AB} và {EFB} (tính: (EFB)⁺ = EFB→A→ABCDEF = R ✓)\nPrime = {A,B,E,F}\nXét EF→A: EF không phải superkey. Nhưng A là prime → thỏa 3NF, vi phạm BCNF\n→ Highest NF = 3NF\n```\n\n**Ví dụ F — QUIZ 9 Q7 / MCQ Q17 (3NF không BCNF):** `R(A,B,C,D,E)`, `F = {AB→C, CD→E, DE→B}`, Keys = `{ABD, ACD, ADE}`\n\n```\nPrime = {A,B,C,D,E} (tất cả prime)\nXét AB→C: AB không superkey (AB⁺ = {A,B,C} ≠ R), C là prime → 3NF OK, vi phạm BCNF\nXét CD→E: CD không superkey, E prime → 3NF OK, vi phạm BCNF\n→ Highest NF = 3NF   ← QUIZ 9 Q7 đáp án B\n```\n\n**Ví dụ G — VoTien Q21 / MCQ Q44 (3NF không BCNF):** `R(A,B,C,D)`, `F = {A→BCD, BC→AD, D→B}`\n\n```\nCK: {A} và {BC}. D⁺ = {B,D} ≠ R → D không superkey.\nD→B: D không superkey, B là prime (trong CK {BC}) → 3NF OK, vi phạm BCNF\n→ Highest NF = 3NF\n```\n\n**Ví dụ H — BOOK (QUIZ 9 Q6 / MCQ Q16) (1NF):** `BOOK(Book_title, Author_name, Book_type, List_price, Author_affil, Publisher)`  \n`F = {Book_title→{Publisher, Book_type}, Book_type→List_price, Author_name→Author_affil}`\n\n```\nKhông có key được cung cấp tường minh → suy key = {Book_title, Author_name} (composite)\nAuthor_name→Author_affil: Author_name ⊂ key, Author_affil nonprime → PARTIAL DEP → vi phạm 2NF\n→ Highest NF = 1NF   ← QUIZ 9 Q6 đáp án A\n```\n\n**Ví dụ I — HK192 (3NF không BCNF):** `R(A,B,C,D)`, `F = {A→BCD, BC→AD, D→B}`\n\n```\nCK: {A} (A⁺ = ABCD = R ✓; minimal ✓)\n    {BC} (BC⁺ = BC→AD → {A,B,C,D} = R ✓; B⁺={B}, C⁺={C} → minimal ✓)\nPrime = {A, B, C}; Non-prime = {D}\n\nKiểm từng FD:\n  A→BCD: A là CK ✓ (BCNF OK)\n  BC→AD: BC là CK ✓ (BCNF OK)\n  D→B: D không phải superkey (D⁺ = {B,D} ≠ R).\n        B là prime (∈ CK {BC}) → 3NF OK (RHS prime), vi phạm BCNF\n→ Highest NF = 3NF\n```\n\n---\n\n### 6.9. Ví dụ kinh điển TEACH — 3NF nhưng không BCNF\n\n🔑 **Keywords (EN):** TEACH relation, 3NF but not BCNF, dependency preservation loss, lossless decomposition.\n\n```\nTEACH(Student, Course, Instructor)\nFD1: (Student, Course) → Instructor\nFD2: Instructor → Course\n\nCK: {Student, Course} và {Student, Instructor}\nPrime: Student, Course, Instructor (tất cả prime)\n\nFD2: Instructor → Course\n  - Instructor không phải superkey\n  - Course là prime → 3NF ✓ (vì RHS prime)\n  - BCNF ✗ (vì LHS không superkey)\n→ 3NF nhưng không BCNF\n```\n\n**Các cách phân rã nhị phân TEACH (tất cả 3 cách đều mất FD1):**\n\n| Cặp phân rã | Lossless? | Dep. Preserving? |\n|---|---|---|\n| `{Student,Course}` + `{Student,Instructor}` | ✓ (SC∩SI={Student}, Student→…) | Mất FD1 (SC→I không tồn tại ở bảng nào) |\n| `{Instructor,Course}` + `{Instructor,Student}` | ✓ (IC∩IS={Instructor}, I→C ✓) | Mất FD1 |\n| `{Student,Course}` + `{Instructor,Course}` | Phụ thuộc FD | Mất FD1 |\n\n> Cặp **{Instructor,Course} + {Instructor,Student}** là **desirable** — lossless (Instructor→Course ∈ F⁺, kiểm NJB: R1∩R2={Instructor}, R1−R2={Course}, Instructor→Course ✓) và hai bảng con tự nhiên. Tất cả cách phân rã BCNF đều mất FD1.\n\n> 🔥 BCNF có thể **mất dependency preservation**. Khi đó thường giữ **3NF** — tốt hơn về mặt thực tế.  \n> 🔥 **Wording chính thức (Elmasri):** \"Property (1) non-additive join is EXTREMELY important and CANNOT be sacrificed; property (2) dependency preservation may be sacrificed when necessary.\"\n\n---\n\n### 6.10. BCNF Decomposition Algorithm\n\n🔑 **Keywords (EN):** BCNF decomposition, lossless decomposition, dependency preservation, BCNF violation, spurious tuples.\n\n```\nD := {R}\nwhile ∃ Q ∈ D vi phạm BCNF:\n    tìm FD X→A trong Q mà X không phải superkey của Q\n    thay Q bằng:\n        Q1 = Q − {A}      (giữ mọi cột trừ A)\n        Q2 = X ∪ {A}      (X + A)\nreturn D\n```\n\n**Ví dụ đầy đủ — QUIZ 9 Q8 / MCQ Q18:** `R(A,B,C,D,E)`, `F = {A→D, AB→C, D→E}`, Key duy nhất = `{A,B}`\n\n```\nBước 1: A→D: A không superkey (A⁺ = {A,D,E} ≠ R)\n  → R1(A,D) Key={A}, R2(A,B,C) Key={A,B}\n\nBước 2: trong R1(A,D): D→E: D không superkey của R1 (D⁺ = {D,E} ≠ {A,D})\n  → R11(D,E) Key={D}, R12(A,D) Key={A}\n  (R12 = R1 trừ E, R11 = D+E)\n\nKết quả cuối: R1(A,B,C) Key={A,B} + R2(A,D) Key={A} + R3(D,E) Key={D}\n← QUIZ 9 Q8 đáp án D\n```\n\n**Ví dụ BCNF — VoTien Q19 / MCQ Q41-42:** `R(A,B,C,D,E,F)`, `F = {A→B, C→AD, AF→CE}`\n\n```\nCK: {A,F}⁺ = {A,F} → AF→CE → {A,C,E,F} → A→B → {A,B,C,E,F} → C→AD → R = {A,B,C,D,E,F} ✓\n    {C,F}⁺: C→AD → {A,C,D,F} → AF→CE → {A,C,D,E,F} → A→B → R ✓\nKeys = {A,F}, {C,F}\n\nA→B: A không superkey → phân rã R1(A,B), R2(A,C,D,E,F)\nTrong R2(A,C,D,E,F): C→AD, C không superkey của R2\n  → R21(C,A) = R22(C,A), R_temp = R2 − A = (C,D,E,F)\n  Trong R_temp: C→D, C không superkey → R23(C,D), R21(C,E,F)\n\nKết quả BCNF: R1(A,B), R22(C,A), R21(C,E,F), R23(C,D)\n```\n\n---\n\n### 6.11. NJB Test — Lossless (Non-additive) Join (Algorithm 16.5)\n\n🔑 **Keywords (EN):** lossless join, non-additive join, NJB test, binary decomposition, spurious tuples, Algorithm 16.5.\n\n```\nBinary decomposition {R1, R2} lossless ⟺\n  (R1 ∩ R2) → (R1 − R2) ∈ F⁺\n  HOẶC (R1 ∩ R2) → (R2 − R1) ∈ F⁺\n```\n\n**Ví dụ cơ bản:** `R(A,B,C)`, `F = {A→B}`, `R1(A,B)`, `R2(A,C)`\n\n```\nR1 ∩ R2 = {A}\nR1 − R2 = {B}\nA→B ∈ F → LOSSLESS ✓\n```\n\n**Ví dụ ENROLLMENT (Algorithm 16.5 worked):**  \n`ENROLLMENT(Student, Instructor, Course)`, `F = {Instructor→Course}`  \nPhân rã: `R1(Instructor, Course)` + `R2(Student, Instructor)`\n\n```\nR1 ∩ R2 = {Instructor}\nR1 − R2 = {Course}\nKiểm: Instructor → Course ∈ F ✓\n→ LOSSLESS ✓\n```\n\n> 🔥 Lossless join **bắt buộc phải giữ** — không được đánh đổi. Dependency preservation có thể hy sinh nếu cần.\n\n> 🔥 **Spurious tuples** sinh ra khi JOIN trên attribute không phải PK/FK → kết quả JOIN \"phình\" ra các tuple giả. Thiết kế đúng: JOIN luôn qua PK = FK.\n\n---\n\n### 6.12. 3 Anomalies & Mục đích Normalization\n\n🔑 **Keywords (EN):** modification anomaly, insertion anomaly, deletion anomaly, data redundancy, normalization goals, informal design guidelines.\n\n| Anomaly | Nguyên nhân | Ví dụ |\n|---|---|---|\n| **Modification** | 1 fact lưu nhiều dòng → sửa 1 phải sửa hết | Đổi tên phòng → update mọi nhân viên |\n| **Insertion** | Không thể thêm entity nếu thiếu thông tin CK | Thêm phòng mới chưa có nhân viên |\n| **Deletion** | Xóa entity cuối → mất thông tin liên quan | Xóa nhân viên cuối → mất thông tin phòng |\n\n**Phân biệt QUAN TRỌNG — Mục tiêu hình thức vs. Informal guideline:**\n\n| Loại | Nội dung |\n|---|---|\n| **Mục tiêu HÌNH THỨC của một phép phân rã** (normalization algorithm) | ① Attribute preservation · ② Dependency preservation · ③ Non-additive (lossless) join |\n| **Informal design guidelines** (Elmasri Ch.14 — động cơ thiết kế) | Clear semantics · Giảm redundant info · Giảm anomalies · **Giảm NULL** · Tránh spurious tuples |\n\n> 🔥 **F2024-Q24 (MCQ Trap):** Câu \"đâu KHÔNG phải mục đích của normalization?\" → đáp án = **\"Minimize NULL values\"**.  \n> \"Minimize NULL\" là *informal guideline* (lý do thiết kế tốt), KHÔNG phải mục tiêu của thuật toán phân rã chuẩn hoá. Trong khi đó \"lossless join\", \"dependency preservation\", \"attribute preservation\" đều là mục tiêu hình thức.\n\n**KHÔNG phải mục đích:** giảm số phép JOIN — chuẩn hóa thường **TĂNG** JOIN.\n\n> 🔥 VoTien Q26 đáp án C = \"giảm lưu trữ dữ liệu dư thừa\". QUIZ 9 Q9: \"attribute preservation, dependency preservation, lossless (nonadditive) join\" (đáp án C).\n\n> ⚠️ Mâu thuẫn đề cũ: HK202 Q12 có phương án \"tất cả đều đúng\" (bao gồm giảm join) — nếu gặp đúng wording đó, chọn theo đề đó. Mặc định và đề mới: **giảm dư thừa**.\n\n---\n\n### 6.13. 4NF & MVD — Multivalued Dependency + 5NF/PJNF\n\n🔑 **Keywords (EN):** MVD (multivalued dependency), 4NF, trivial MVD, 4NF violation, Cartesian-product redundancy, 5NF, PJNF, join dependency, SPJ relation.\n\n**MVD** `X ↠ Y`: nếu tồn tại `(x, y1, z1)` và `(x, y2, z2)` thì phải tồn tại `(x, y1, z2)` và `(x, y2, z1)` — Y và Z độc lập với nhau trên X.\n\n- Mọi FD đều kéo theo MVD: `X → Y ⟹ X ↠ Y`\n- **Trivial MVD:** `Y ⊆ X` **hoặc** `X ∪ Y = R` (tức phần còn lại Z = R − X − Y = ∅)\n- **Non-trivial MVD:** `Y ⊄ X` **VÀ** `X ∪ Y ≠ R`\n\n**4NF:** ∀ MVD non-trivial `X ↠ Y` → X là superkey.\n\n**Worked STUDENT (4NF):** `STUDENT(StudentID, Major, Club)`\n\n```\nGiả sử 1 SV có 2 Major (CS, Math) và 2 Club (Chess, Drama):\n→ 4 dòng bắt buộc (Cartesian product): (S,CS,Chess),(S,CS,Drama),(S,Math,Chess),(S,Math,Drama)\n\nStudentID ↠ Major: non-trivial (Major ⊄ {StudentID}, {StudentID}∪{Major} ≠ R)\nStudentID ↠ Club:  non-trivial\nStudentID không phải superkey của STUDENT → vi phạm 4NF\n\nFix: STUDENT_MAJOR(StudentID, Major) + STUDENT_CLUB(StudentID, Club)\n→ Lossless: (R1∩R2) = {StudentID}, R1−R2={Major}, StudentID ↠ Major ✓\n```\n\n**5NF / PJNF:**\n\n```\nJoin dependency *(R1, R2, …, Rk): R = R1 ⋈ R2 ⋈ … ⋈ Rk\nNon-trivial: không có Ri nào = R\n5NF: mọi join dependency non-trivial đều implied by candidate keys của R\n```\n\n**Worked SPJ (5NF):** `SPJ(Supplier, Part, Project)`\n\n```\nNgữ nghĩa: (S,P,J) ∈ SPJ ⟺ S cung cấp Part P ∧ S tham gia Project J ∧ J sử dụng Part P\n→ 3-way join dependency *(SP, SJ, PJ)  (non-trivial vì không cái nào = SPJ)\n→ Nếu không có FD nào, SPJ vi phạm 5NF\nFix: tách SP(Supplier,Part) + SJ(Supplier,Project) + PJ(Part,Project)\n→ 3-way lossless join ✓ (nhưng chỉ đúng khi 3 constraints đồng thời thỏa)\n```\n\n---\n\n### 6.14. Bảng so sánh NF & Decision Tree\n\n| | 2NF | 3NF | BCNF |\n|---|---|---|---|\n| **Điều kiện** | Không partial dep (nonprime vào partial CK) | ∀ `X→A` non-trivial: X superkey **HOẶC** A prime | ∀ `X→A` non-trivial: X **phải** superkey |\n| **Cho phép** | Full dep vào CK | Transitive dep nếu A prime | Không có ngoại lệ |\n| **Vi phạm** | Partial dep (LHS ⊂ CK, RHS nonprime) | Transitive dep qua nonprime | LHS không superkey dù RHS prime |\n| **Dep. preservation** | ✓ | Thường ✓ | Có thể mất |\n| **Lossless join** | ✓ | ✓ | ✓ luôn |\n\n**NF Decision Tree:**\n\n```\n1. Ô atomic?          No → 1NF vi phạm (báo không thỏa 1NF)\n                      Yes ↓\n2. Partial dep?        Yes → highest = 1NF\n                       No ↓\n3. Transitive dep      Yes (RHS nonprime) → highest = 2NF\n   qua nonprime?       No ↓\n4. ∃ FD X→A với        Yes → highest = 3NF\n   X không superkey    No ↓\n   nhưng A prime?      BCNF (nếu không có 4NF check)\n```\n\n---\n\n### 6.15. Redundancy trong CAR_SALE — Ví dụ thực tế (QUIZ 9 Q5)\n\n`CAR_SALE(Car_id, Option_type, Option_listprice, Sale_date, Option_discountedprice)`  \n`Key = {Car_id, Option_type}`, `FD: Car_id→Sale_date; Option_type→Option_listprice; {Car_id,Option_type}→Option_discountedprice`\n\n```\nOption_type→Option_listprice: Option_type ⊂ key → PARTIAL DEP\n→ Option_listprice lặp lại nhiều lần khi nhiều xe có cùng Option_type\n→ Redundancy = Option_listprice\n← Đáp án QUIZ 9 Q5: D\n```\n\n**Phân rã BCNF đúng (MCQ Q64):**  \n`R1(Car_id, Sale_date)` + `R2(Option_type, Option_listprice)` + `R3(Car_id, Option_type, Option_discountedprice)`\n\n---\n\n### 6.16. Derived FD — Kiểm tra suy ra được\n\n**QUIZ 8 Q6 / VoTien Q30:** `R(A,B,C,D,E)`, `F = {AB→CE, B→D, D→A}`. FD nào KHÔNG suy ra từ F?\n\n```\nAD→CE?\n  AD⁺ = {A,D}\n  D→A: đã có, B→D: B không có → không thêm được gì\n  AD⁺ = {A,D} → CE ⊄ {A,D} → AD→CE KHÔNG suy ra được ✓\n← Đáp án: AD→CE (VoTien Q30 đáp án D, QUIZ 8 Q6 đáp án C)\n\nKiểm nhanh B→E: B→D→A→(AB)→CE, B→E ✓ (suy ra được)\n```\n\n---\n\n### 🎯 MCQ Traps §6\n\n1. 🔥 **F⁺ ≠ X⁺** — F⁺ chứa FD, X⁺ chứa attribute. Nhầm 2 ký hiệu này = sai toàn bộ bài.\n2. 🔥 **Union rule = `X→YZ`** (KHÔNG phải `Y→Z`). Không có symmetry rule.\n3. 🔥 **X⁺ = R ⟹ superkey, chưa chắc CK** — phải kiểm tối giản.\n4. 🔥 **NF cao nhất = dạng chuẩn thấp nhất đã thỏa**: vi phạm 2NF → báo 1NF, không phải \"2NF không thỏa\".\n5. 🔥 **3NF: LHS superkey HOẶC RHS prime. BCNF: LHS superkey (only)** — BCNF nghiêm hơn, không có ngoại lệ RHS.\n6. 🔥 **BCNF có thể mất dependency preservation** (TEACH là ví dụ kinh điển). Lossless join LUÔN bắt buộc.\n7. 🔥 **B→G vi phạm 2NF** khi B là tập con thực sự của composite CK và G là nonprime — không phải 3NF.\n8. 🔥 **Mọi CK đều đơn (1 attribute) ⟹ tự động 2NF** — nhưng phải MỌI CK, không chỉ primary key.\n9. 🔥 **Normalization = giảm dư thừa + giảm anomaly**. KHÔNG giảm số JOIN (thường TĂNG JOIN).\n10. 🔥 **Minimal cover không duy nhất** — bài có thể có nhiều đáp án đúng khác nhau về canonical form.\n11. 🔥 **FD do semantics quyết định** (database designer) — không suy từ 1 instance. Instance chỉ bác bỏ FD.\n12. 🔥 **U_r KHÔNG BAO GIỜ trong CK; U_l BẮT BUỘC trong mọi CK** — nhầm là mất toàn bộ bài tìm key.\n13. 🔥 **3NF cho phép transitive dep nếu đích đến là prime attribute** (ví dụ TEACH, QUIZ 9 Q7).\n14. 🔥 **F2024-Q24 — \"Minimize NULL values\" KHÔNG phải mục tiêu hình thức của normalization** — đây là *informal design guideline* (Elmasri Ch.14). Mục tiêu hình thức là: attribute preservation + dependency preservation + lossless join. → Khi hỏi \"cái nào KHÔNG phải mục đích normalization\" mà có option \"Minimize NULL\", chọn nó.\n15. 🔥 **Superkey ≠ Candidate Key ≠ Primary Key** — \"K sao cho t1[K]≠t2[K]\" là định nghĩa SUPERKEY (chỉ đòi duy nhất, không đòi minimal). CK = minimal superkey. PK = 1 CK được chọn.\n16. 🔥 **FD derivability trap:** Muốn kiểm `X→Y` có suy ra từ F không → tính `X⁺` theo F, kiểm `Y ⊆ X⁺`. Đừng suy bằng chuỗi \"cảm giác\" — ví dụ B→E với F={AB→CE,B→D,D→A}: B⁺={A,B,D} → E∉B⁺ → B→E không suy ra được.\n17. 🔥 **TEACH — tất cả cách phân rã BCNF đều mất FD1** (Student,Course→Instructor). Cặp ưu tiên là {Instructor,Course}+{Instructor,Student} (lossless, Instructor→Course làm key join). Giữ 3NF nếu dep preservation là ưu tiên.\n\n---\n\n### 🪄 Câu thần chú §6\n\n1. **`X → Y`: biết X chắc chắn biết Y — do database designer quyết định, không suy từ mẫu.**\n2. **`F⁺` = closure của TẬP FD (chứa luật); `X⁺` = closure của TẬP THUỘC TÍNH (chứa cột). Đừng nhầm.**\n3. **`X⁺ = R ⟺ superkey; tối giản ⟺ CK`. Superkey chỉ đòi duy nhất — không đòi minimal.**\n4. **U_l bắt buộc trong mọi CK; U_r không bao giờ trong CK; U_b thì thử.**\n5. **Minimal cover 3 bước: tách RHS đơn → rút LHS → bỏ FD thừa. Kết quả không duy nhất.**\n6. **1NF: atomic. 2NF: không partial (nonprime full-dep vào mọi CK). 3NF: không transitive qua nonprime. BCNF: mọi LHS là superkey.**\n7. **3NF: X superkey HOẶC A prime. BCNF: X superkey chấm hết — không có ngoại lệ nào.**\n8. **BCNF ⊊ 3NF. TEACH (Instructor→Course): 3NF ✓, BCNF ✗ — ví dụ kinh điển.**\n9. **Vi phạm 2NF → highest NF = 1NF. Luôn báo dạng chuẩn THẤP nhất đã thỏa.**\n10. **NJB lossless (Alg 16.5): `(R1∩R2) → (R1−R2)` hoặc `(R1∩R2) → (R2−R1)` thuộc F⁺.**\n11. **BCNF luôn lossless join nhưng có thể MẤT dependency preservation. Lossless KHÔNG thể bỏ.**\n12. **Mục tiêu HÌNH THỨC của normalization = attribute preservation + dependency preservation + lossless join. \"Minimize NULL\" là informal guideline — KHÔNG phải mục tiêu hình thức (F2024-Q24).**\n13. **Spurious tuple = join trên attribute không phải PK/FK → dữ liệu giả phình ra.**\n14. **4NF diệt MVD non-trivial: X↠Y (Y⊄X và X∪Y≠R) đòi X là superkey. 5NF diệt join dependency tổng quát.**\n15. **NULL có 3 nghĩa: (a) không áp dụng, (b) chưa biết, (c) biết nhưng chưa nhập. Đây là lý do informal tránh NULL, không phải mục tiêu phân rã.**\n\n---\n\n","file":"materials/DB-Final.md","section":15},{"id":"final-16","group":"final","kind":"source","title":"§7. DATA STORAGE & INDEXING — Trọng số đề: 4 câu","markdown":"## §7. DATA STORAGE & INDEXING — Trọng số đề: 4 câu\n\n> **Tài liệu gốc:** `Lectures/08_DataStorageIndexingStructures.pdf` · `Final/VoTien/Storage.pdf` · `Tutorial/DB-Chapter8.md`\n>\n> **Tập trung:** bfr & b tính toán (4 trường hợp), 3 loại index & entry count, multilevel cost, B-tree vs B+-tree, \"1 Primary OR 1 Clustering\", disk geometry.\n\n---\n\n### 7.1. Physical Design — Vị trí trong kiến trúc\n\n```\nMiniworld → ERD/EERD (DBMS-independent)\n          → Logical schema (relational model)\n          → PHYSICAL DESIGN → Internal Schema\n```\n\nSong song: thiết kế chương trình ứng dụng + giao dịch → ứng dụng hoàn chỉnh.\n\n🔑 **Keywords (EN):** physical design, internal schema, storage structures, access paths, index.\n\n---\n\n### 7.2. Disk Geometry\n\n```\nDisk pack\n→ Disk surface  (n đĩa hai mặt → 2n surfaces)\n→ Track         (vòng đồng tâm trên 1 surface; capacity ≈ 4–50 KB)\n→ Sector/Block  (đơn vị đọc/ghi disk ↔ RAM; B cố định 512–4096 B)\n→ Cylinder      (tập track CÙNG bán kính trên TẤT CẢ surfaces)\n```\n\n| Thuật ngữ | Bẫy thường gặp |\n|---|---|\n| **Cylinder** | KHÔNG phải 1 track; KHÔNG phải 1 surface — là tập track cùng bán kính |\n| **Interblock gap G** | KHÔNG chứa data hữu ích — chỉ để phân tách block vật lý |\n| **Block size B** | Cố định cho hệ thống; địa chỉ = (Cylinder#, Surface/Track#, Block#) |\n\n🔑 **Keywords (EN):** disk pack, surface, track, sector, block, cylinder, interblock gap (G), physical block address.\n\n**Disk geometry formulas:**\n```\nRotation time       = 60 000 / p  (ms)          [p = vòng/phút, rpm]\nRotational delay rd = 60 000 / (2p)  (ms)       ← trung bình NỬA VÒNG\nTrack TOTAL cap     = n × (B + G)               [n = blocks/track]\nTrack USEFUL cap    = n × B\nTransfer rate    tr = track_total_cap / rotation_time\nBlock transfer time btt = B / tr\nBulk transfer rate btr  = (B / (B + G)) × tr    ← tỉ lệ data thực\nCylinder capacity   = track_cap × #surfaces\nDisk pack capacity  = cylinder_cap × #cylinders\n```\n\n**Access time (quan trọng nhất):**\n```\nAccess time = s + rd + btt\n  s   = seek time (đầu đọc di chuyển tới đúng cylinder)\n  rd  = rotational delay (chờ block quay tới đầu đọc)\n  btt = block transfer time (truyền 1 block vào RAM)\n```\n\nVí dụ: `p = 7 200 rpm`, `s = 5 ms`, `btt = 0.1 ms` → `rd = 60 000/(2×7200) = 4.17 ms` → `Access = 5 + 4.17 + 0.1 = 9.27 ms`.\n\n**Double buffering:** khi đọc nhiều block LIÊN TIẾP, dùng 2 buffer — CPU xử lý block n trong buffer 1 trong khi disk nạp block n+1 vào buffer 2 → tiết kiệm rotational delay + seek time giữa các block. \"20 random blocks\" không hưởng lợi; \"20 consecutive blocks + double buffering\" = nhanh hơn rõ rệt.\n\n🔑 **Keywords (EN):** seek time (s), rotational delay (rd), block transfer time (btt), bulk transfer rate, access time formula, double buffering.\n\n---\n\n### 7.3. File of Records & Block Allocation\n\n**File header (descriptor)** = field names/types, record format, block addresses, file organization — \"bìa hồ sơ\" của file.\n\n**Block allocation — 3 cách:**\n\n| Cách | Mô tả | Bfr formula |\n|---|---|---|\n| **Contiguous** | Block liên tiếp; đọc tuần tự nhanh | `⌊B / R⌋` |\n| **Linked** | Block rời rạc; mỗi block dành `p` bytes cho pointer | `⌊(B − p) / R⌋` |\n| **Indexed** | Index block lưu danh sách địa chỉ; truy cập block thứ k nhanh | như linked |\n\n🔑 **Keywords (EN):** file header, contiguous allocation, linked allocation, indexed allocation, block pointer (p).\n\n---\n\n### 7.4. Record Format & Blocking Factor\n\n| Loại | Mô tả |\n|---|---|\n| **Fixed-length** | Tất cả record cùng kích thước |\n| **Variable-length** | Trường độ dài thay đổi; thường dùng spanned |\n| **Unspanned** | Record KHÔNG được phép nằm trên 2 block; phần thừa block bỏ trống |\n| **Spanned** | Record có thể chia ra nhiều block liên tiếp |\n\n⚠️ **Deletion marker:** \"An additional byte is used as a deletion marker\" → cộng **+1 byte** vào `R` trước mọi tính toán.\n\n🔑 **Keywords (EN):** fixed-length record, variable-length record, spanned, unspanned, blocking factor (bfr), deletion marker.\n\n---\n\n### 7.5. FORMULA SHEET — Bắt buộc thuộc\n\n```\n══════════════════════ BLOCKING FACTOR ══════════════════════\nUnspanned + Contiguous:     bfr = ⌊B / R⌋\nUnspanned + Linked:         bfr = ⌊(B − p) / R⌋\n\n══════════════════════ SỐ BLOCK ══════════════════════════════\nUnspanned (cả 2 loại):      b = ⌈r / bfr⌉\nSpanned + Contiguous:       b = ⌈(r × R) / B⌉\nSpanned + Linked:           b = ⌈(r × R) / (B − p)⌉\n\n══════════════════════ SEARCH COST ══════════════════════════\nHeap / pile (avg):          b / 2\nHeap / pile (worst):        b\nOrdered, binary search:     ⌈log₂ b⌉\nHashed (no collision):      1\nInsert Heap:                2   (đọc last + ghi)\nInsert Ordered:             ⌈log₂ b⌉ + b   (search + shift)\n\n══════════════════════ INDEX ════════════════════════════════\nIndex entry (sparse — Primary / Clustering):   Rᵢ = V + P\nIndex entry (dense  — Secondary on key):       Rᵢ = V + PR\n  ↑ P  = block pointer (vd 6 B); PR = record pointer (vd 7 B)\nbfrᵢ   = ⌊B / Rᵢ⌋\nbᵢ     = ⌈#entries / bfrᵢ⌉\n\n#entries theo loại index:\n  Primary index   → #data blocks            (sparse)\n  Clustering index → #distinct values       (sparse)\n  Secondary (key) → #records                (dense)\n\nSingle-level index access: ⌈log₂ bᵢ⌉ + 1   ← +1 = data block\nMultilevel index access:   L + 1            ← L = số mức index\n```\n\n---\n\n### 7.6. 3 File Organizations\n\n| | **Heap (Pile)** | **Ordered (Sequential)** | **Hashed** |\n|---|---|---|---|\n| Sắp thứ tự? | Không | Theo ordering field | Theo hash function h(K) |\n| **Insert** | **Nhanh nhất** — append cuối | **Chậm nhất** — overflow + merge | Nhanh (nếu không collision) |\n| **Search (equality)** | b/2 (avg) | ⌈log₂ b⌉ | **1** (no collision) |\n| **Range search** | b (worst) | ⌈log₂ b⌉ + scan | **Vô dụng** |\n| **Read theo thứ tự** | Phải sort lại | Rất nhanh | Kém |\n\n**Ordered file — overflow (transaction) file:** để tránh insert chậm (phải dịch chuyển record), file ordered duy trì thêm 1 **overflow file** (transaction file) không sắp xếp cho các record mới. Tìm kiếm phải search cả 2 file; định kỳ **merge** overflow vào file chính và sort lại. Đây là lý do ISAM suy giảm khi insert nhiều (xem §7.10).\n\n**Collision resolution (Hashing):**\n- **Open addressing** (linear probing): tìm slot trống tiếp theo\n- **Chaining**: linked list overflow tại bucket\n- **Multiple hashing**: dùng hàm h₂ khi h₁ collision\n\nLoad factor tốt = **70–80%**; Dynamic hashing tránh tràn khi file tăng trưởng.\n\n🔑 **Keywords (EN):** heap file, pile, ordered file, sequential file, binary search, overflow file, transaction file, merge, hashed file, external hashing, bucket, hash function h(K), collision, open addressing, chaining, multiple hashing, dynamic hashing, extendible hashing.\n\n---\n\n### 7.7. 3 Loại Single-Level Index — Bảng vàng\n\n| Index | File ordered? | Field type | #entries | Dense/Sparse | Max/file |\n|---|---|---|---|---|---|\n| **Primary** | Yes — theo **key** | Key | **#data blocks** | **Sparse (Nondense)** | **1** |\n| **Clustering** | Yes — theo **non-key** | Non-key | **#distinct values** | **Sparse (Nondense)** | **1** |\n| **Secondary (key)** | No | Key | **#records** | **Dense** | Nhiều |\n| **Secondary (non-key)** | No | Non-key | Phụ thuộc option | Dense (option 1) | Nhiều |\n\n🔥 **Quy tắc vàng:** 1 file chỉ có **1 Primary HOẶC 1 Clustering** (do chỉ có 1 thứ tự vật lý), **KHÔNG đồng thời cả hai**. Secondary có thể có **nhiều**.\n\n🔥 **Primary = sparse** (1 entry/block); **Secondary on key = dense** (1 entry/record). Đừng lẫn.\n\n🔑 **Keywords (EN):** primary index (ordering key field, sparse, block anchor), clustering index (ordering non-key, sparse, distinct values), secondary index (non-ordering field, dense), dense index, sparse/nondense index.\n\n---\n\n### 7.8. Secondary Index on Non-key Field — 3 Options\n\nVấn đề: 1 non-key value ánh xạ tới **nhiều** record → phải xử lý:\n\n| Option | Cơ chế | Đặc điểm |\n|---|---|---|\n| **Opt 1** | 1 entry/record, key lặp lại nhiều lần | Dense; index file lớn |\n| **Opt 2** | 1 entry/distinct value → list pointers thẳng | **Nondense** (1 entry/value); list có độ dài thay đổi → khó fixed-size |\n| **Opt 3** | 1 entry/distinct value → block trung gian chứa list | **Phổ biến thực tế**; entry kích thước đều |\n\n🔑 **Keywords (EN):** secondary index on non-key, extra indirection block, option 3 (phổ biến).\n\n---\n\n### 7.9. Multilevel Index\n\nVì file index cũng là file **sorted** → xây primary index trên chính nó → nhiều mức:\n```\nLevel 1 (data index) → bᵢ₁ = ⌈#entries / bfrᵢ⌉\nLevel 2             → bᵢ₂ = ⌈bᵢ₁ / bfrᵢ⌉\nLevel 3             → bᵢ₃ = ⌈bᵢ₂ / bfrᵢ⌉\nDừng khi top level fits vừa 1 block → L mức\nAccess cost = L + 1\n```\n\n**Nhược điểm:** Insert/Delete tốn vì phải giữ sorted mọi mức → sinh ra **B-tree/B+-tree** là dynamic multilevel index khắc phục.\n\n🔑 **Keywords (EN):** multilevel index, L levels, top level fits 1 block, search cost = L + 1.\n\n---\n\n### 7.10. Search Tree & ISAM\n\n**Search tree order p:** mỗi node có tối đa `p` tree pointers và `p−1` search keys.\n- `P₁` trỏ subtree key `< K₁`; `P₂` trỏ subtree `K₁ < X < K₂`; ... `Pₚ` trỏ subtree `X > K_{p-1}`.\n- Node fitting constraint (B+-tree internal): `p × P_tree + (p−1) × V ≤ B`\n\n**ISAM (Indexed Sequential Access Method):**\n```\n= Multilevel index tĩnh + Ordered data file + Overflow area\n```\n- Insert ngẫu nhiên → record đi vào overflow chain → overflow dài → search chậm → cần **REORGANIZE**.\n- ISAM kém linh hoạt hơn B+-tree (static structure).\n\n🔑 **Keywords (EN):** search tree order p, ISAM, overflow area, reorganize.\n\n---\n\n### 7.11. B-tree vs B+-tree\n\n| Đặc tính | **B-tree** | **B+-tree** |\n|---|---|---|\n| Data pointer | Ở **mọi level** (internal + leaf) | **CHỈ ở leaf** |\n| Internal node | key + data ptr + tree ptr | Chỉ key + tree ptr (nhỏ hơn) |\n| Leaf node | key + data ptr | key + data ptr + **P_next** |\n| **Fanout** | Nhỏ hơn (internal entry to hơn) | **Lớn hơn** |\n| **Chiều cao** | Cao hơn | **Thấp hơn** → search nhanh hơn |\n| Range query | Khó (phải duyệt mọi level) | **Dễ** (theo P_next ở leaf) |\n| Equality query | Tốt | Tốt |\n| Ứng dụng | Ít dùng | **MySQL InnoDB, PostgreSQL — phổ biến nhất** |\n\n**Tự cân bằng:**\n- **Insert** vào node đầy → **Split** thành 2, lan tỏa lên cha.\n- **Delete** gây underflow (< ⌈p/2⌉) → **Merge** với sibling.\n- Min-occupancy: mọi node (trừ root) ≥ ⌈p/2⌉ tree pointers.\n- Mọi leaf ở **cùng level** (cây cân bằng hoàn toàn).\n\n🔥 **QUIZ 10 chính xác:** \"B+-tree: internal nodes có different structure — no data pointer in internal nodes; no tree pointer in leaf nodes\" (C). Insert vào B-tree không rebuild toàn bộ cây — chỉ split node (E đúng).\n\n🔑 **Keywords (EN):** B-tree, B+-tree, data pointer, tree pointer, leaf level, P_next, split, merge, balanced, min-occupancy ⌈p/2⌉, fanout.\n\n---\n\n### 7.12. Oracle Index Types (8 loại)\n\n| Loại | Dùng khi |\n|---|---|\n| **B-tree indexes** | Mặc định; equality + range |\n| **Index-organized tables** | Toàn bộ table nằm trong B+-tree |\n| **Reverse key indexes** | Đảo byte → phân tán insert tuần tự, tránh hot block |\n| **Descending indexes** | `ORDER BY col DESC` |\n| **B-tree cluster indexes** | Cụm bảng (cluster key) |\n| **Bitmap / Bitmap join** | Cột **low-cardinality** (Gender, Status) — tốt cho DW |\n| **Function-based** | Index trên expression hoặc `UPPER(col)` |\n| **Application domain** | User-defined |\n\n```sql\n-- Standard B-tree / Unique / Descending / Reverse\nCREATE [UNIQUE | BITMAP] INDEX idx_name\nON table_name (col [ASC | DESC], ...) [REVERSE];\n\n-- Bitmap join index (low-cardinality, Data Warehouse)\nCREATE BITMAP INDEX emp_bm_idx\nON EMPLOYEES(JOBS.job_title)\nFROM EMPLOYEES, JOBS\nWHERE EMPLOYEES.job_id = JOBS.job_id;\n```\n\n**Khi NÊN / KHÔNG NÊN index:**\n- NÊN: cột high-cardinality, tìm kiếm thường xuyên, range query, foreign key.\n- KHÔNG NÊN: bảng nhỏ, cột update rất nhiều (volatile), cột hiếm query.\n\n**Index selection với workload hỗn hợp (F2024-Q32):** Employee table — 80% transactions update `Salary` → KHÔNG index Salary dù bị query (quá volatile, overhead write > lợi read); 75% queries range-compare `Dno` → index `Dno`; equality search trên `SSN` → index `SSN`. Kết luận: index `{SSN, Dno}`, loại bỏ Salary. Bẫy: chọn phương án \"Salary + SSN + Dno\" vì Salary bị query.\n\n---\n\n### 7.13. RAID & SAN\n\n**RAID = Redundant Arrays of Inexpensive Disks.**\n\n| Level | Cơ chế | Redundancy | Chịu fail | Dùng khi |\n|---|---|---|---|---|\n| **0** | Block striping | **Không** | 0 disk | Tốc độ tối đa |\n| **1** | Mirror | 100% | 1 disk | Log, critical data |\n| **2** | Hamming code | Bit parity | 1 disk | Hiếm dùng |\n| **3** | Byte striping + 1 parity disk | Single parity | 1 disk | Transfer rate cao |\n| **4** | Block striping + 1 parity disk | Single parity | 1 disk | Ghi tắc (parity bottleneck) |\n| **5** | Block striping, **parity rải đều** | Distributed parity | 1 disk | **Phổ biến nhất server** |\n| **6** | Block striping + **P+Q (Reed-Solomon)** | 2 parity | **2 disk** | Backup quan trọng |\n\n**SAN (Storage Area Network):** mạng lưu trữ tốc độ cao; server ↔ storage many-to-many qua Fiber channel; khoảng cách ≤ 10 km cáp quang.\n\n🔑 **Keywords (EN):** RAID (Redundant Arrays of Inexpensive Disks) 0/1/3/5/6, striping, mirroring, parity, Reed-Solomon, SAN, Fiber channel.\n\n---\n\n### 7.14. Worked Numeric Examples (BKTBK, full step-by-step)\n\n---\n\n#### EX-1: Unspanned linked vs Spanned linked (QUIZ 10 Q2 & Q4 — BK-LMS verbatim)\n\n**Setup:** Employee, `r = 25 000`, `R = 75 B`, `B = 512 B`, `p = 6 B`.\n\n**Unspanned + Linked (Q2 → 4 167):**\n1. Usable = `B − p = 512 − 6 = 506 B`\n2. `bfr = ⌊506 / 75⌋ = ⌊6.75⌋ = 6`\n3. `b = ⌈25 000 / 6⌉ = ⌈4 166.67⌉ = 4 167` ✅\n\n**Spanned + Linked (Q4 → 3 706):**\n1. Total record bytes = `25 000 × 75 = 1 875 000 B`\n2. Usable = `506 B`\n3. `b = ⌈1 875 000 / 506⌉ = ⌈3 705.53⌉ = 3 706` ✅\n\n🔥 **Trap:** Spanned → ít block hơn (không lãng phí cuối block); Unspanned → nhiều block hơn.\n\n---\n\n#### EX-2: So sánh 4 phương pháp lưu trữ trên cùng một file (dạng VoTien)\n\n**Setup minh hoạ:** `r = 30 000` record, `R = 100 B`, `B = 1 024 B`, block pointer `p = 8 B`. Tính số block `b` theo cả 4 phương pháp.\n\n| Phương pháp | Công thức | Bước tính | Kết quả `b` |\n|---|---|---|---|\n| **Unspanned / Contiguous** | `bfr=⌊B/R⌋` → `b=⌈r/bfr⌉` | `bfr=⌊1024/100⌋=10`; `b=⌈30000/10⌉` | **3 000** |\n| **Unspanned / Linked** | `bfr=⌊(B−p)/R⌋` → `b=⌈r/bfr⌉` | `bfr=⌊1016/100⌋=10`; `b=⌈30000/10⌉` | **3 000** |\n| **Spanned / Contiguous** | `b=⌈(r×R)/B⌉` | `⌈3 000 000/1024⌉=⌈2929.69⌉` | **2 930** |\n| **Spanned / Linked** | `b=⌈(r×R)/(B−p)⌉` | `⌈3 000 000/1016⌉=⌈2952.76⌉` | **2 953** |\n\n**Nhận xét (đây là điểm hay hỏi):**\n1. **Unspanned lãng phí cuối block** (1024 − 10×100 = 24 B/block bỏ trống) → tốn block hơn spanned.\n2. **Spanned tận dụng hết block** → ít block hơn, nhưng record bị cắt qua 2 block → đọc 1 record có thể tốn 2 block access.\n3. **Linked** trừ `p` byte/block cho pointer → usable nhỏ hơn → cần nhiều block hơn contiguous (thấy rõ ở dòng spanned: 2953 > 2930).\n\n🔥 **Trap:** đề thường cho 4 đáp án rất gần nhau (lệch vài block) — phải xác định đúng **spanned/unspanned** và **contiguous/linked** rồi áp đúng công thức; tuyệt đối không nhầm `floor` (bfr) với `ceil` (b).\n\n---\n\n#### EX-3: Canonical ordered-file + Primary index (VoTien Q7–Q8, nguồn HK191/192)\n\n**Setup chuẩn:** `r = 300 000`, `R = 100 B`, `B = 4 096 B` (unspanned), `V = 9 B`, `P = 6 B`.\n\n**Bước 1 — File gốc:**\n1. `bfr = ⌊4096 / 100⌋ = 40`\n2. `b = ⌈300 000 / 40⌉ = 7 500`\n3. Binary search (không index): `⌈log₂ 7500⌉ = ⌈12.87⌉ = 13` lần truy cập\n\n**Bước 2 — Primary index:**\n4. `Rᵢ = V + P = 9 + 6 = 15 B` (sparse entry — block pointer)\n5. `bfrᵢ = ⌊4096 / 15⌋ = 273`\n6. #entries = b = `7 500` (sparse, 1 entry/block)\n7. `bᵢ = ⌈7500 / 273⌉ = ⌈27.47⌉ = 28`\n8. Cost = `⌈log₂ 28⌉ + 1 = 5 + 1 = 6` ← **nhanh hơn gấp đôi so với 13**\n\n🔥 **Trap:** +1 data block cuối cùng bắt buộc — quên = sai.\n\n---\n\n#### EX-4: Clustering index — VoTien Q9\n\n**Setup:** `r = 300 000`, `B = 4 096 B`. Sorted theo Zipcode (1 000 distinct values). `V_zip = 5 B`, `P = 6 B`.\n\n1. `Rᵢ = 5 + 6 = 11 B`\n2. `bfrᵢ = ⌊4096 / 11⌋ = 372`\n3. #entries = 1 000 (distinct values)\n4. `bᵢ = ⌈1000 / 372⌉ = ⌈2.69⌉ = 3`\n5. Cost = `⌈log₂ 3⌉ + 1 = 2 + 1 = 3` lần truy cập\n\n🔥 **Trap:** Clustering → #entries = #distinct values (KHÔNG phải #records, không phải #blocks).\n\n---\n\n#### EX-5: Multilevel index — VoTien Q10 / HK211 Q38 chuẩn\n\n**Setup:** `B = 1 024 B`, `p = 6 B`, `r = 50 000`, `R = 60 B`, `V = 9 B`. `bfr = 17`.\n\n1. `b = ⌈50 000 / 17⌉ = ⌈2 941.18⌉ = 2 942`\n2. `Rᵢ = 9 + 6 = 15 B`; `bfrᵢ = ⌊1024 / 15⌋ = 68`\n3. **Level 1:** `bᵢ₁ = ⌈2942 / 68⌉ = ⌈43.26⌉ = 44`\n4. **Level 2:** `bᵢ₂ = ⌈44 / 68⌉ = 1` → fits 1 block → **DỪNG**\n5. L = 2 mức → Cost = `L + 1 = 2 + 1 = 3` ✅\n\n🔥 **Trap:** MCQ Q38 đáp án A = \"12\" — đây là `⌈log₂ 2942⌉ = 12` (binary search trên **data file**), KHÔNG phải multilevel index cost. Multilevel index = **3**. Khi đề hỏi \"multilevel index\" → dùng **L + 1 = 3**, không phải 12.\n\n---\n\n#### EX-6: HK191 series — orderNo/orderDate/BillNo (VoTien Q18–Q22)\n\n**Setup:** `B = 512 B`, `r = 30 000`, `R = 45 B` (orderNo 13+qty 1+amount 4+status 1+orderDate 13+BillNo 13), file sorted theo **orderNo** (PK); BillNo = candidate key; `p = 6 B`, `V_{orderNo} = 13 B`.\n\n**Q18 — Phân loại index:**\n- orderNo = PK, file sorted theo orderNo → **Primary index**\n- BillNo = candidate key (unique), file KHÔNG sorted theo BillNo → **Secondary index** (dense, #entries=#records)\n- orderDate = non-key, non-ordering → **Secondary index** ✅ **Đáp án D**\n\n> ⚠️ **Tranh luận HK191-Q36 (BillNo):** Đáp án chính thức của đề gọi BillNo là \"clustering index\", nhưng phân tích đúng: BillNo là *candidate key* trên file KHÔNG sắp thứ tự theo BillNo → phải là **Secondary index (dense)**, không phải clustering (clustering = non-key ordering field). Ghi chú \"có thể là lỗi đề\" — khi thi, nếu xuất hiện lại hãy chọn Secondary dense và giải thích.\n\n**Q19 — bfr:**\n1. `bfr = ⌊512 / 45⌋ = ⌊11.38⌋ = 11` ✅ (Đáp án A)\n\n**Q20 — b:**\n2. `b = ⌈30 000 / 11⌉ = ⌈2727.27⌉ = 2 728` ✅ (Đáp án C)\n\n**Q21 — Primary index bfrᵢ:**\n3. `Rᵢ = V + P = 13 + 6 = 19 B`\n4. `bfrᵢ = ⌊512 / 19⌋ = ⌊26.95⌋ = 26` ✅ (Đáp án D)\n\n**Q22 — Primary index access cost:**\n5. #entries = b = `2 728`\n6. `bᵢ = ⌈2728 / 26⌉ = ⌈104.9⌉ = 105`\n7. Cost = `⌈log₂ 105⌉ + 1 = 7 + 1 = 8` ✅ (Đáp án B)\n\n---\n\n#### EX-7: Secondary index (dense) vs Primary (VoTien Q10 secondary variant)\n\n**Setup giống EX-3:** `r = 300 000`, `b = 7 500`, `B = 4 096`, `V_secondary = 9 B`, `P_R = 6 B`.\n\n1. `Rᵢ = 9 + 6 = 15 B` (dense: V + P_R — record pointer)\n2. `bfrᵢ = ⌊4096 / 15⌋ = 273`\n3. #entries = r = **300 000** (dense, 1 entry/record)\n4. `bᵢ = ⌈300 000 / 273⌉ = ⌈1 098.9⌉ = 1 099`\n5. Cost = `⌈log₂ 1099⌉ + 1 = 11 + 1 = 12`\n\nSo sánh: Primary → 6 lần; Secondary (dense) → 12 lần; Linear heap → b/2 = 3 750 lần.\n\n---\n\n#### EX-8: Multilevel index — tính số mức L từ tham số thô (HK241-Q17)\n\n**Setup:** `r = 30 000`, `B = 1 024 B`, `R = 100 B`, `V = 9 B`, `Pb = 6 B` (block pointer).\n\n1. `bfr = ⌊1024 / 100⌋ = 10`\n2. `b = ⌈30 000 / 10⌉ = 3 000` (data blocks = #entries level 1)\n3. Index entry: `Rᵢ = V + Pb = 9 + 6 = 15 B`; `bfrᵢ = ⌊1024 / 15⌋ = 68`\n4. **Level 1:** `bᵢ₁ = ⌈3 000 / 68⌉ = ⌈44.12⌉ = 45`\n5. **Level 2:** `bᵢ₂ = ⌈45 / 68⌉ = 1` → fits 1 block → **DỪNG**\n6. **L = 2 mức** → Access cost = `L + 1 = 3` ✅\n\n🔥 **Trap HK241-Q17:** đáp án nhiễu là \"45\" (level-1 blocks), \"3000\" (data blocks), \"10\" (bfr). Câu hỏi hỏi số lần truy cập → L + 1 = **3**.\n\n---\n\n### 7.15. File Operations\n\n| Operation | Mô tả | Ghi chú |\n|---|---|---|\n| **OPEN** | Mở file, set current record pointer | |\n| **FIND** | Tìm record đầu tiên thỏa điều kiện | |\n| **FINDNEXT** | Tìm record kế tiếp thỏa điều kiện | |\n| **READ** | Đọc current record vào biến | |\n| **INSERT** | Thêm record mới | |\n| **DELETE** | Xóa current record — thường **mark invalid** | Xóa vật lý qua REORGANIZE |\n| **MODIFY** | Sửa field của current record | |\n| **CLOSE** | Đóng file | |\n| **REORGANIZE** | Tổ chức lại file, xóa vật lý record đã mark | |\n| **READ_ORDERED** | Đọc theo thứ tự field | |\n\n🔑 **Keywords (EN):** OPEN, FIND, FINDNEXT, READ, INSERT, DELETE (mark), MODIFY, REORGANIZE, current record pointer.\n\n---\n\n### 7.16. So sánh tổng hợp — Primary vs Clustering vs Secondary\n\n| | Primary | Clustering | Secondary (key) |\n|---|---|---|---|\n| File ordered? | Yes | Yes | No |\n| Field type | Key | Non-key | Key hoặc Non-key |\n| #entries | #blocks | #distinct values | #records |\n| Dense/Sparse | Sparse | Sparse | Dense |\n| Max per file | 1 | 1 | Nhiều |\n| Coexistence | Không cùng Clustering | Không cùng Primary | OK với cả 2 |\n\n---\n\n### 🎯 MCQ Traps §7\n\n1. 🔥 `bfr = ⌊B/R⌋` **floor** — 11.37 → 11, KHÔNG round up. `b = ⌈r/bfr⌉` **ceil** — không bao giờ floor.\n2. 🔥 **Primary index**: #entries = **#data blocks** (sparse); bẫy: nhiều người nghĩ là #records.\n3. 🔥 **Clustering index**: #entries = **#distinct values** (KHÔNG phải #blocks, KHÔNG phải #records).\n4. 🔥 **Secondary on key**: #entries = **#records** (dense); entry = `V + PR` (record pointer PR, không phải block pointer P).\n5. 🔥 **+1 bắt buộc** sau `⌈log₂ bᵢ⌉` khi tính index cost (+1 = data block) — quên = sai.\n6. 🔥 Multilevel cost = **L + 1**. \"12\" trong Q38 là binary search trên data file, KHÔNG phải multilevel cost.\n7. 🔥 **1 file CHỈ 1 Primary HOẶC 1 Clustering** — không đồng thời cả hai. Many Secondary = OK. Nếu đề có 3 phương án đều vi phạm quy tắc này → chọn \"tất cả đều sai\" (HK241-Q18).\n8. 🔥 **B+-tree**: data pointer chỉ ở leaf; internal nodes chỉ có key + tree pointer. B-tree: data pointer ở mọi level.\n9. 🔥 **Hashing** = cực tốt equality (`=`), **vô dụng** cho range (`<`, `>`, `BETWEEN`).\n10. 🔥 **Insert heap = 2** (rẻ — chỉ đọc last block + ghi); insert ordered = đắt (binary search + dịch chuyển).\n11. 🔥 **RAID 5** = phổ biến nhất (parity rải đều, tolerate 1 fail); **RAID 6** = chịu **2** disk fail.\n12. 🔥 **Index trên unordered file = Secondary** — không phải Primary (Primary đòi file phải sorted theo field đó).\n13. 🔥 **Secondary index Option 2** (1 entry/distinct value → list pointers) = **nondense**, không phải dense — chỉ Option 1 (key lặp lại) mới là dense.\n14. 🔥 **Chọn index theo workload:** cột volatile (update nhiều) → KHÔNG index dù bị query; ưu tiên cột high-cardinality + truy vấn thường xuyên. Exclude Salary nếu 80% write.\n15. 🔥 **BillNo (HK191-Q36):** đáp án chính thức \"clustering\" có thể sai — BillNo là candidate key trên file không sắp theo BillNo → đúng là **Secondary dense**. Tranh luận: \"lỗi đề\".\n\n---\n\n### 🪄 Câu thần chú §7\n\n59. `bfr = ⌊B/R⌋` floor; `b = ⌈r/bfr⌉` ceil — không đổi.\n60. Heap b/2; Ordered ⌈log₂ b⌉; Hashed 1.\n61. Primary + Clustering = **nondense (sparse)**; Secondary on key = **dense**.\n62. 1 file CHỈ **1 Primary HOẶC 1 Clustering**; có thể nhiều Secondary.\n63. Single index search: `⌈log₂ bᵢ⌉ + 1` (+1 = data block, BẮT BUỘC).\n64. Multilevel: `L + 1`; dừng khi top level vừa 1 block.\n65. B+-tree: data pointer **CHỈ ở leaf**; leaf nối P_next → range query nhanh.\n66. B-tree internal có data ptr → entry to → fanout nhỏ → cây cao hơn B+-tree.\n67. Hashing: cực tốt equality, **vô dụng** range query.\n68. RAID = Redundant Arrays of Inexpensive Disks; RAID 5 phổ biến (parity rải); RAID 1 mirror; RAID 6 chịu 2 fail; RAID 0 không redundancy.\n69. Access time = **s + rd + btt**; rd = 60 000/(2p) — trung bình nửa vòng, không phải 1 vòng.\n70. Disk access unit = **Block** (KHÔNG phải record, KHÔNG phải file).\n71. `P` = block pointer (entry sparse); `PR` = record pointer (entry dense) — đừng nhầm.\n72. Double buffering tăng tốc đọc block **liên tiếp** — không giúp gì cho random I/O.\n73. Ordered file dùng overflow/transaction file cho insert nhanh; merge định kỳ để giữ thứ tự.\n\n---\n\n","file":"materials/DB-Final.md","section":16},{"id":"final-17","group":"final","kind":"source","title":"§8. DATABASE SECURITY — Trọng số đề: 3 câu","markdown":"## §8. DATABASE SECURITY — Trọng số đề: 3 câu\n\n> **Exam weight:** ~3 MCQ / 50. Open-book → skim keyword tables và micro-examples.  \n> **DBA** là người chịu trách nhiệm tổng thể về bảo mật CSDL.\n\n---\n\n### 8.1 Tổng quan — Các loại & mối đe dọa\n\n#### Phân loại vấn đề bảo mật (Types of Security)\n\n| Loại | Ví dụ |\n|---|---|\n| **Legal and ethical issues** | GDPR, HIPAA — quy định pháp lý bảo vệ dữ liệu cá nhân |\n| **Policy issues** | Quy tắc công ty: ai được xem dữ liệu lương |\n| **System-related issues** | Chọn bảo mật ở tầng phần cứng, OS, hay DBMS |\n| **Multiple security levels** | Phân loại dữ liệu: Public / Confidential / Top Secret |\n\n🔑 **Keywords (EN):** `legal`, `ethical`, `policy`, `system-related`, `multiple security levels`\n\n---\n\n#### Ba khái niệm nền tảng 🔥\n\n| Khái niệm | Định nghĩa |\n|---|---|\n| **Authentication** | Xác minh danh tính — \"người dùng có đúng là họ không?\" |\n| **Authorization** | Cấp quyền — cho phép chủ thể truy cập hợp lệ vào đối tượng |\n| **Access Control** | Cơ chế DBMS hạn chế truy cập vào CSDL |\n\n**Thứ tự khi đăng nhập:** `Identification → Authentication → Authorization`\n\n🔑 **Keywords (EN):** `authentication`, `authorization`, `access control`, `identification`\n\n---\n\n#### Ba mối đe dọa chính đối với CSDL 🔥\n\n| Mối đe dọa | Ý nghĩa |\n|---|---|\n| **Loss of integrity** | Dữ liệu bị sửa đổi trái phép → không còn chính xác, nhất quán |\n| **Loss of availability** | Dữ liệu/hệ thống không thể truy cập khi cần |\n| **Loss of confidentiality** | Dữ liệu bị lộ cho người không có quyền |\n\n> Integrity = dữ liệu **chính xác và nhất quán** (accurate and consistent) — không phải \"bảo mật\" hay \"không dư thừa\".\n\n**Phân biệt CIA nhanh:**\n\n| Thuộc tính | Ý nghĩa cốt lõi | Ví dụ |\n|---|---|---|\n| **Confidentiality** | Chặn truy cập **trái phép** | Người ngoài không đọc được dữ liệu |\n| **Integrity** | Chặn **sửa đổi trái phép** | Dữ liệu không bị alter không có thẩm quyền |\n| **Availability** | Đảm bảo **truy cập được khi cần** | Người dùng hợp lệ gửi request và nhận được dữ liệu |\n\n> **Bẫy thường gặp (F2024-Q33):** \"Hành khách xem được thông tin chuyến bay của mình khi request; chỉ manager được sửa\" — tính chất cấp cho hành khách là **Availability** (truy cập được khi cần), **KHÔNG phải Confidentiality**. SV dễ nhầm vì nghĩ \"chỉ xem dữ liệu của mình = confidential\" — sai. Confidentiality nói về ngăn truy cập trái phép, không nói về việc chủ thể hợp lệ truy cập được.\n\n🔑 **Keywords (EN):** `loss of integrity`, `loss of availability`, `loss of confidentiality`\n\n---\n\n#### Bốn biện pháp đối phó (Countermeasures)\n\n| Biện pháp | Mục đích |\n|---|---|\n| **Access control** | Kiểm soát ai được truy cập gì |\n| **Inference control** | Ngăn suy diễn thông tin cá nhân từ truy vấn thống kê |\n| **Flow control** | Ngăn thông tin chảy đến người không có quyền |\n| **Encryption** | Mã hóa dữ liệu nhạy cảm khi lưu/truyền |\n\n🔑 **Keywords (EN):** `access control`, `inference control`, `flow control`, `encryption`\n\n---\n\n#### Hai loại cơ chế bảo mật DBMS\n\n| Loại | Đặc điểm | Ví dụ |\n|---|---|---|\n| **Discretionary security mechanisms** | Chủ sở hữu tự quyết định ai được quyền gì | `GRANT SELECT ON Employee TO Alice;` |\n| **Mandatory security mechanisms** | Hệ thống quyết định dựa trên nhãn phân loại | User clearance Secret không đọc được Top Secret |\n\n---\n\n### 8.2 Discretionary Access Control (DAC) 🔥\n\n**Định nghĩa:** Người dùng kiểm soát dữ liệu họ sở hữu; có thể grant/revoke quyền cho người khác; tự định nghĩa kiểu truy cập (read/write/execute…).\n\n🔑 **Keywords (EN):** `discretionary access control`, `GRANT`, `REVOKE`, `privilege`, `owner`, `WITH GRANT OPTION`, `access matrix model`\n\n---\n\n#### Hai cấp độ đặc quyền DAC\n\n| Cấp | Đặc quyền |\n|---|---|\n| **Account level** | DBA cấp quyền cho account bất kể relation nào: `CREATE SCHEMA`, `CREATE TABLE`, `CREATE VIEW`, `ALTER`, `DROP`, `MODIFY` (INSERT/DELETE/UPDATE), `SELECT` |\n| **Relation/Table level** | Quyền trên từng relation R cụ thể: `SELECT`, `INSERT`, `UPDATE`, `DELETE`, `REFERENCES` |\n\n> `UPDATE` và `INSERT` ở relation-level có thể giới hạn chỉ trên **một số cột** nhất định.  \n> `SELECT` và `DELETE` **không** attribute-specific.\n\n---\n\n#### Cú pháp GRANT / REVOKE\n\n```sql\n-- Cấp quyền cơ bản\nGRANT SELECT, INSERT ON Employee, Department TO A2;\n\n-- Cấp với quyền truyền tiếp (WITH GRANT OPTION)\nGRANT SELECT ON Employee, Department TO A3 WITH GRANT OPTION;\n\n-- Cấp trên cột cụ thể\nGRANT UPDATE ON Employee (Salary) TO A4;\n\n-- Thu hồi (kèm cascade tự động)\nREVOKE SELECT ON Employee FROM A3;\n```\n\n---\n\n#### Micro-example: GRANT OPTION + Cascading REVOKE 🔥\n\n```\nA1 tạo bảng Employee (A1 là owner).\n\nBước 1: A1 → GRANT SELECT ON Employee TO A3 WITH GRANT OPTION;\nBước 2: A3 → GRANT SELECT ON Employee TO A4;          (không có GRANT OPTION)\nBước 3: A4 không thể tiếp tục propagate (vì không có GRANT OPTION).\n\nBước 4: A1 → REVOKE SELECT ON Employee FROM A3;\n         ↳ Hệ thống tự động REVOKE SELECT từ A4 luôn!\n         ↳ A4 mất quyền vì quyền của A4 phụ thuộc vào A3.\n```\n\n> **Quy tắc cascade REVOKE:** Khi A1 revoke từ A3, **tất cả quyền mà A3 đã propagate** cũng bị thu hồi tự động.\n\n**Kịch bản nhiều tầng (từ MCQ):**  \n`A1 →(GRANT OPTION)→ A2 →(GRANT OPTION)→ A3 → A4`  \nNếu A1 REVOKE từ A2 → A2, A3, A4 đều mất quyền. ✓\n\n---\n\n#### Views như cơ chế bảo mật 🔥\n\nDùng VIEW khi muốn giới hạn:\n- **Theo hàng (row filtering):** `CREATE VIEW v5 AS SELECT * FROM Employee WHERE Dno=5;`\n- **Theo cột (column filtering):** `CREATE VIEW v_safe AS SELECT Name, Bdate FROM Employee;`\n- **Kết hợp:** UNION để ẩn salary của nhóm cụ thể\n\n```sql\n-- MCQ pattern: Wong là manager dno=1, cần xem nhân viên dno=1\nCREATE VIEW wong_view AS\n  SELECT * FROM Employee WHERE dno = 1;\nGRANT SELECT ON wong_view TO Wong;\n-- ❌ GRANT SELECT ON Employee WHERE dno=1 TO Wong; -- KHÔNG HỢP LỆ TRONG SQL\n-- ❌ GRANT SELECT ON Employee, wong_view TO Wong;  -- Thừa và cấp quá nhiều\n```\n\n> Để tạo view, account phải có `SELECT` trên **tất cả** relations trong view definition.\n\n---\n\n#### Điểm yếu của DAC — Trojan Horse\n\nDAC dễ bị tấn công **Trojan Horse**: malicious program đọc dữ liệu từ object người dùng có quyền đọc, rồi ghi sang object khác mà kẻ tấn công có quyền đọc — không cần vi phạm access control trực tiếp.\n\n🔑 **Keywords (EN):** `Trojan horse`, `DAC weakness`, `unrestricted information flow`\n\n---\n\n### 8.3 Mandatory Access Control (MAC) 🔥\n\n**Định nghĩa:** Hệ thống **tự quyết định** quyền truy cập (read/write) dựa trên nhãn phân loại bảo mật của chủ thể (subject) và đối tượng (object) — không phụ thuộc vào ý muốn của chủ sở hữu dữ liệu.\n\n🔑 **Keywords (EN):** `mandatory access control`, `security classification`, `clearance level`, `security label`, `Bell-LaPadula`, `subject`, `object`\n\n---\n\n#### Cấp độ phân loại (Security Classes) 🔥\n\n```\nTop Secret (TS)  ≥  Secret (S)  ≥  Confidential (C)  ≥  Unclassified (U)\n```\n\n- **Subject** (người dùng) có **clearance level**\n- **Object** (dữ liệu) có **classification level**\n\n---\n\n#### Bell-LaPadula Model — Hai quy tắc cốt lõi 🔥\n\n| Quy tắc | Tên | Điều kiện đọc/ghi |\n|---|---|---|\n| **No read-up** (simple security property) | Không đọc lên | S đọc O khi: `class(S) ≥ class(O)` |\n| **No write-down** (star property / \\* property) | Không ghi xuống | S ghi O khi: `class(S) ≤ class(O)` |\n\n**Mục đích:** Bảo vệ **tính bí mật (confidentiality)** — không phải integrity hay availability.\n\n🔑 **Keywords (EN):** `no read-up`, `no write-down`, `simple security property`, `star property`, `*-property`, `confidentiality`\n\n---\n\n#### Micro-example: Quyết định đọc/ghi Bell-LaPadula\n\n```\nSubject S có clearance = Secret (S).\nObject O1 có classification = Confidential (C): S ≥ C → S ĐƯỢC ĐỌC O1. ✓\nObject O2 có classification = Top Secret (TS): S < TS → S KHÔNG ĐƯỢC ĐỌC O2. ✗\n\nVề ghi:\nS ghi O1 (C): S > C → vi phạm no write-down → KHÔNG ĐƯỢC GHI. ✗\nS ghi O3 (TS): S ≤ TS → ĐƯỢC GHI O3. ✓\n```\n\n---\n\n#### So sánh DAC vs MAC 🔥\n\n| Tiêu chí | DAC | MAC |\n|---|---|---|\n| **Ai quyết định** | Chủ sở hữu dữ liệu | Hệ thống (dựa trên nhãn) |\n| **Độ linh hoạt** | Cao — phù hợp nhiều lĩnh vực | Thấp — chỉ dùng trong môi trường hạn chế |\n| **Mức độ bảo mật** | Thấp hơn | **Cao hơn** |\n| **Nguy cơ** | Dễ bị Trojan Horse | Ngăn được Trojan Horse |\n| **Ứng dụng** | Thương mại phổ thông | Quân sự, chính phủ |\n| **Cài đặt** | Dễ hơn | Phức tạp hơn |\n\n> DAC **không ngăn được** Trojan Horse. MAC **có thể ngăn** vì flow information bị kiểm soát chặt.\n\n---\n\n### 8.4 Multilevel Relations & Polyinstantiation\n\n#### Cấu trúc Multilevel Relation\n\nTrong hệ thống MAC + relational model, mỗi relation có dạng:\n\n```\nR(A1, C1, A2, C2, ..., An, Cn, TC)\n```\n\n- `Ci`: classification attribute của attribute `Ai`\n- `TC` (Tuple Classification): nhãn bảo mật **cao nhất** trong tất cả `Ci` của tuple\n- **Apparent key**: primary key của relation bình thường (tất cả giá trị key phải cùng classification, không được NULL)\n\n🔑 **Keywords (EN):** `multilevel relation`, `apparent key`, `tuple classification (TC)`, `classification attribute`, `polyinstantiation`\n\n---\n\n#### Ví dụ hiển thị theo clearance level 🔥\n\nBảng gốc (chỉ admin TS thấy đầy đủ):\n\n| Name | Salary | JobPerformance | TC |\n|---|---|---|---|\n| Smith `U` | 40000 `C` | Fair `S` | S |\n| Brown `C` | 80000 `S` | Good `C` | S |\n\n| User clearance | Thấy gì |\n|---|---|\n| **S (Secret)** | Cả hai rows đầy đủ |\n| **C (Confidential)** | Smith: JobPerformance→NULL; Brown: Salary→NULL; TC hạ xuống C |\n| **U (Unclassified)** | Chỉ thấy Smith (TC=S > U → Brown ẩn); Salary=NULL, JobPerformance=NULL |\n\n> **Quy tắc:** User chỉ thấy **attribute** có `C_attr ≤ clearance(user)`, giá trị cao hơn → NULL.  \n> User chỉ thấy **row** nếu có thể thấy **apparent key** của row đó.\n\n---\n\n#### Polyinstantiation 🔥\n\n**Định nghĩa:** Nhiều tuples có cùng apparent key nhưng giá trị attribute **khác nhau** ở các classification level khác nhau.\n\n**Tại sao cần polyinstantiation?** Để **ngăn covert channel** (information leak): nếu DBMS từ chối INSERT của user U vì 'Brown' đã tồn tại ở level cao hơn → user U biết Brown tồn tại → thông tin bị lộ.\n\n```\nVí dụ: User C UPDATE Employee SET JobPerformance='Excellent' WHERE Name='Smith'\n\nKết quả (polyinstantiation):\nSmith U | 40000 C | Fair S      | TC=S   ← row cũ (S-level thấy)\nSmith U | 40000 C | Excellent C | TC=C   ← row mới (C-level thấy)\n```\n\n**Điều kiện toàn vẹn entity (entity integrity) trong multilevel:**\n- Tất cả attributes thuộc apparent key phải **NOT NULL** và có **cùng classification**\n- Mọi attribute khác trong tuple phải có classification ≥ classification của apparent key\n\n---\n\n### 8.5 Role-Based Access Control (RBAC)\n\n**Định nghĩa:** Quyền gắn với **roles** (vai trò); users được gán vào roles phù hợp.\n\n```sql\nCREATE ROLE manager;\nGRANT SELECT, UPDATE ON Employee TO manager;\nGRANT manager TO Alice;\nDESTROY ROLE manager;\n```\n\n**Đặc điểm:**\n- Nổi lên mạnh từ thập niên 1990\n- Hỗ trợ **role hierarchy** (phân cấp vai trò)\n- Hỗ trợ **temporal constraints** (giới hạn thời gian kích hoạt role)\n- Phù hợp với enterprise và web-based applications — nơi DAC/MAC không đủ mạnh\n- Vấn đề **Role Explosion** khi số roles quá lớn → ABAC giải quyết\n\n🔑 **Keywords (EN):** `role`, `role hierarchy`, `CREATE ROLE`, `DESTROY ROLE`, `role-based access control`, `role explosion`\n\n---\n\n### 8.6 Attribute-Based & Context-Based Access Control\n\n#### ABAC (Attribute-Based Access Control)\n\nĐánh giá **thuộc tính** thay vì roles:\n\n| Loại attribute | Ví dụ |\n|---|---|\n| Subject attributes | Job title, department, clearance level |\n| Object attributes | Document type, classification, creation date |\n| Environment conditions | Time of day, IP address, location |\n\nKiến trúc: `User → PEP (Enforcement) → PDP (Decision) → Policy → Allow/Deny`\n\n🔑 **Keywords (EN):** `ABAC`, `subject attributes`, `object attributes`, `environment conditions`, `PEP`, `PDP`, `fine-grained access control`\n\n#### CBAC (Context-Based Access Control)\n\nKiểm soát dựa trên **bối cảnh môi trường** tại thời điểm yêu cầu: thời gian, địa điểm, thiết bị, mạng. Nền tảng cho mô hình **Zero Trust**.\n\n---\n\n#### So sánh 4 mô hình Access Control\n\n| Model | Căn cứ đánh giá | Đặc điểm |\n|---|---|---|\n| **DAC** | Chủ sở hữu quyết định | Linh hoạt, dễ triển khai, dễ bị Trojan Horse |\n| **MAC** | Nhãn phân loại hệ thống | Bảo mật cao, cứng nhắc, phức tạp |\n| **RBAC** | Vai trò (roles) | Dễ quản lý, phù hợp enterprise, có thể bùng nổ roles |\n| **ABAC** | Thuộc tính đa chiều | Granular cao, linh hoạt, phức tạp cài đặt |\n| **CBAC** | Bối cảnh môi trường | Động, thêm tầng bảo mật real-time |\n\n---\n\n### 8.7 Mã hóa (Encryption)\n\n#### Các loại mã hóa\n\n| Loại | Cơ chế | Ví dụ thuật toán |\n|---|---|---|\n| **Symmetric encryption** | Cùng 1 key để mã hóa và giải mã | AES (128/192/256-bit), DES, 3DES |\n| **Asymmetric encryption** | Public key + Private key | RSA, ECC |\n| **Hashing** | Hàm một chiều (one-way) | SHA-256, bcrypt, Argon2 |\n\n#### Asymmetric Encryption — Quy tắc sử dụng key 🔥\n\n| Mục đích | Key dùng để mã hóa | Key dùng để giải mã |\n|---|---|---|\n| **Data confidentiality** (bảo mật nội dung) | **Public key** của người nhận | Private key của người nhận |\n| **Authentication / Digital signature** (xác thực / chữ ký) | **Private key** của người gửi | Public key của người gửi |\n\n> MCQ kinh điển: \"Alice muốn đảm bảo tính toàn vẹn (integrity / authentication) của message gửi Bob\" → Alice dùng **private key của Alice** để mã hóa.\n\n🔑 **Keywords (EN):** `public key`, `private key`, `asymmetric encryption`, `digital signature`, `data confidentiality`, `authentication`, `TDE` (Transparent Data Encryption), `TLS/SSL`\n\n---\n\n### 8.8 Statistical Database Security & Inference Control\n\n**Vấn đề:** CSDL thống kê chỉ cho phép truy vấn tổng hợp (AVG, COUNT, SUM) nhưng vẫn có thể bị suy diễn để lộ dữ liệu cá nhân.\n\n**Inference attack example:**\n```sql\nSELECT COUNT(*) FROM Emp WHERE Dept='CS' AND Gender='F'  → 1\nSELECT AVG(Salary) FROM Emp WHERE Dept='CS' AND Gender='F' → 85000\n-- ⇒ Lộ lương cá nhân của người duy nhất đó!\n```\n\n**Biện pháp Inference Control:**\n\n| Kỹ thuật | Mô tả |\n|---|---|\n| **Query Set Size Control** | Từ chối truy vấn nếu result set < ngưỡng (vd: < 5 records) |\n| **Query Restriction / Auditing** | Log và block chuỗi truy vấn đáng ngờ |\n| **Data Perturbation** | Thêm noise vào kết quả trước khi trả về |\n| **Data Swapping** | Hoán đổi giá trị giữa records, giữ nguyên thống kê |\n| **Differential Privacy** | Thêm noise có tính toán toán học (Apple, Google) |\n\n🔑 **Keywords (EN):** `statistical database`, `inference attack`, `inference control`, `tracker attack`, `query set size control`, `data perturbation`, `differential privacy`\n\n---\n\n### 8.9 Flow Control & Covert Channels\n\n**Flow control:** Ngăn thông tin chảy theo cách vi phạm chính sách bảo mật.\n\n**Covert channel:** Kênh truyền thông tin **ngầm, không trực tiếp** — vi phạm chính sách bảo mật mà không dùng access control thông thường.\n\n> Ví dụ covert channel: Process bí mật cao mã hóa dữ liệu bằng cách thay đổi pattern CPU usage hoặc lock/unlock file → process bí mật thấp quan sát pattern và giải mã — không cần đọc trực tiếp.\n\n🔑 **Keywords (EN):** `flow control`, `covert channel`, `implicit information flow`, `security policy`\n\n---\n\n### 8.10 Auditing & Audit Trail\n\n- DBMS ghi nhật ký (**system log / audit trail**) tất cả thao tác trên CSDL theo từng user session.\n- Khi nghi ngờ có xâm phạm → thực hiện **database audit**: review log tất cả accesses trong khoảng thời gian nhất định.\n- **Audit trail**: log dùng chủ yếu cho mục đích bảo mật.\n\n🔑 **Keywords (EN):** `audit trail`, `database audit`, `system log`, `login session`\n\n---\n\n### 8.11 SQL Injection\n\n**Định nghĩa:** Kẻ tấn công chèn SQL code độc hại vào input của ứng dụng để thao túng truy vấn cơ sở dữ liệu.\n\n#### Micro-example nhận diện SQL Injection\n\n```sql\n-- Input hợp lệ:\nSELECT * FROM users WHERE name='alice' AND pwd='secret';\n\n-- Tautology attack (luôn đúng):\n-- Input: ' OR '1'='1\nSELECT * FROM users WHERE name='' OR '1'='1' AND pwd='';\n-- → Luôn trả về rows → bypass authentication\n\n-- Piggy-backed query:\n-- Input: alice'; DROP TABLE users; --\nSELECT * FROM users WHERE name='alice'; DROP TABLE users;--\n\n-- UNION-based:\n-- Input: ' UNION SELECT username,password FROM admin--\n```\n\n#### Phân loại SQL Injection & Phòng chống\n\n| Loại tấn công | Đặc điểm |\n|---|---|\n| **Tautology** | Chèn điều kiện luôn đúng (`OR 1=1`) |\n| **Union-based** | Dùng `UNION` để lấy thêm dữ liệu từ bảng khác |\n| **Piggy-backed queries** | Chèn thêm câu SQL thứ hai sau dấu `;` |\n\n| Biện pháp phòng chống | Mô tả |\n|---|---|\n| **Bind variables / Parameterized queries** | `?` hoặc `:param` — input không bao giờ được parse thành SQL code |\n| **Input validation** | Kiểm tra, escape ký tự đặc biệt (quotes, semicolons…) |\n| **Stored procedures** | Gọi procedure thay vì xây dựng SQL động |\n| **Principle of least privilege** | Tài khoản DB chỉ có quyền tối thiểu cần thiết |\n\n🔑 **Keywords (EN):** `SQL injection`, `tautology`, `union attack`, `piggy-backed query`, `bind variables`, `parameterized queries`, `input validation`, `stored procedures`\n\n---\n\n### 8.12 Privacy & Data Protection\n\n- **Privacy:** quyền của cá nhân kiểm soát thông tin về bản thân.\n- **Data protection regulations:** GDPR (EU), HIPAA (US healthcare), CCPA.\n- Liên quan đến **data anonymization** và **differential privacy** khi công bố dữ liệu thống kê.\n\n🔑 **Keywords (EN):** `privacy`, `data protection`, `GDPR`, `anonymization`\n\n---\n\n### 8.13 MCQ Traps — Bẫy thường gặp\n\n1. **DAC vs MAC confusion 🔥**  \n   - DAC: **chủ sở hữu** quyết định → dễ triển khai, ít bảo mật.  \n   - MAC: **hệ thống** quyết định theo nhãn → bảo mật cao hơn DAC. MAC **không** phải dễ triển khai hơn DAC.\n\n2. **Bell-LaPadula direction trap 🔥**  \n   - \"No read-**up**\" → không đọc dữ liệu có classification **cao hơn** mình: `class(S) ≥ class(O)` để ĐỌC.  \n   - \"No write-**down**\" → không ghi dữ liệu có classification **thấp hơn** mình: `class(S) ≤ class(O)` để GHI.  \n   - Bell-LaPadula bảo vệ **confidentiality** (không phải integrity, không phải availability).  \n   - BiBa model (ngược lại: no read-down, no write-up) bảo vệ **integrity**.\n\n3. **GRANT OPTION propagation cascade 🔥**  \n   - Revoke từ B → **tất cả** quyền B đã grant (kể cả qua nhiều tầng) bị thu hồi.  \n   - A→B(GRANT OPTION)→C(GRANT OPTION)→D: A revoke B → B, C, D đều mất. ✓\n\n4. **WITH GRANT OPTION vs WITH ADMIN OPTION**  \n   - `WITH GRANT OPTION` dùng cho privileges (object-level).  \n   - `WITH ADMIN OPTION` dùng cho roles — khác nhau, không dùng lẫn.\n\n5. **VIEW + GRANT là cách đúng để filter rows/columns 🔥**  \n   - `GRANT SELECT ON Employee WHERE Dno=5 TO u1;` — **KHÔNG HỢP LỆ** trong SQL.  \n   - Đúng: tạo VIEW với WHERE, rồi GRANT SELECT trên VIEW.  \n   - GRANT trên view **không** kèm GRANT trên base table.\n\n6. **TC (Tuple Classification) = giá trị cao NHẤT 🔥**  \n   - TC = max của tất cả `Ci` trong tuple — **không phải** của apparent key.  \n   - Apparent key classification ≤ các attribute classification khác trong cùng tuple.\n\n7. **Asymmetric key: public vs private 🔥**  \n   - Mã hóa bằng **public key** → đảm bảo **confidentiality** (chỉ người nhận có private key mới giải được).  \n   - Mã hóa bằng **private key** → đảm bảo **authentication/signature** (ai cũng verify được bằng public key).\n\n8. **RBAC ≠ DAC**  \n   - RBAC **không phải** chỉ là tên khác của DAC. RBAC là mô hình độc lập — permissions gắn với roles, users gắn với roles.\n\n9. **DBA là người chịu trách nhiệm bảo mật**  \n   - Không phải CEO, CIO hay programmer.\n\n10. **Polyinstantiation: tại sao không reject INSERT/UPDATE?**  \n    - Reject → user cấp thấp biết có tuple cấp cao tồn tại → **covert channel** → lộ thông tin.  \n    - Giải pháp: tạo tuple mới (polyinstantiation) thay vì reject.\n\n11. **Availability vs Confidentiality trap 🔥 (F2024-Q33)**  \n    - \"User xem được dữ liệu của chính mình khi request\" = **Availability** — không phải Confidentiality.  \n    - Ví dụ: hành khách request xem thông tin chuyến bay của mình → tính chất được đảm bảo là **Availability** (truy cập được khi cần).  \n    - SV dễ nhầm: \"chỉ xem dữ liệu của mình = confidential\" → **SAI**. Confidentiality = ngăn truy cập **trái phép**; Availability = đảm bảo truy cập **hợp lệ** thành công.\n\n12. **Cross-DBMS comparison: cái gì universal, cái gì không 🔥 (HK211mock-Q35)**  \n    - Oracle, SQL Server, MySQL đều dùng: **relational data model** ✓ (universal)  \n    - \"Đều hỗ trợ MAC\" → **SAI** ✗ — MAC không phải tính năng chuẩn của cả 3.  \n    - \"Đều dùng cùng cấu trúc index\" → **SAI** ✗ — index structure là vendor-specific.  \n    - Quy tắc nhanh: relational model = universal ✓; MAC = không phổ quát ✗; index implementation = vendor-specific ✗.\n\n---\n\n### 8.14 Quick-ref: Công thức Bell-LaPadula (ôn nhanh)\n\n```\nREAD  hợp lệ khi: clearance(Subject) ≥ classification(Object)   [read DOWN = OK]\nWRITE hợp lệ khi: clearance(Subject) ≤ classification(Object)   [write UP  = OK]\n\nNhớ nhanh: \"Đọc thấp, Ghi cao\" — Subject chỉ đọc được xuống dưới, chỉ ghi được lên trên.\n```\n\n---\n\n","file":"materials/DB-Final.md","section":17},{"id":"final-18","group":"final","kind":"source","title":"§9. ADVANCED TOPICS — Trọng số đề: 4 câu","markdown":"## §9. ADVANCED TOPICS — Trọng số đề: 4 câu\n\n---\n\n### §9.1. Data Warehouse & OLAP\n\n#### 9.1.1. Khái niệm và Động lực\n\n**Data Warehouse** là kho lưu trữ dữ liệu trung tâm, tích hợp dữ liệu từ nhiều nguồn khác nhau (OLTP databases, flat files, APIs của bên thứ ba…), được làm sạch và chuẩn hóa, giữ lại lịch sử lâu dài, phục vụ phân tích và ra quyết định kinh doanh.\n\n🔑 **Keywords (EN):** **Data Warehouse**, **integrated**, **subject-oriented**, **non-volatile**, **time-variant**, **ETL**, **Business Intelligence (BI)**, **decision support**\n\nBốn đặc điểm cốt lõi của Data Warehouse (Bill Inmon):\n1. **Subject-Oriented** — tập trung vào chủ đề (Sales, Customers, Products), không phải quy trình giao dịch\n2. **Integrated** — dữ liệu từ nhiều nguồn được hợp nhất vào một định dạng chuẩn\n3. **Non-Volatile** — dữ liệu được tải vào và không bị xóa; chỉ thêm mới (append-only)\n4. **Time-Variant** — lưu lịch sử theo thời gian (snapshots), cho phép phân tích xu hướng\n\n---\n\n#### 9.1.2. OLTP vs OLAP 🔥\n\n| Tiêu chí | OLTP (On-line Transactional Processing) | OLAP (On-line Analytical Processing) |\n|---|---|---|\n| **Mục tiêu** | Xử lý giao dịch nghiệp vụ hàng ngày | Phân tích đa chiều, hỗ trợ ra quyết định |\n| **Loại thao tác** | Heavy Writes (INSERT, UPDATE, DELETE) | Heavy Reads (SELECT aggregations) |\n| **Dữ liệu** | Liên tục thay đổi | Mostly read-only sau khi tải |\n| **Thời gian đáp ứng** | Milliseconds (phải tức thời) | Seconds, minutes, hoặc hours |\n| **Khối lượng/Query** | Tiny (vài hàng) | Millions of rows at once |\n| **Thiết kế DB** | Highly Normalized (2D Tables) | Multidimensional (3D Cubes) |\n| **Ưu tiên** | Speed and exact accuracy | Deep analysis and complex calculations |\n| **Ví dụ** | Hệ thống đặt vé, thanh toán, đơn hàng | Báo cáo doanh thu, dự báo xu hướng |\n\n🔑 **Keywords (EN):** **OLTP**, **OLAP**, **normalized**, **multidimensional**, **aggregation**, **management reporting**, **analytical processing**\n\n---\n\n#### 9.1.3. Kiến trúc Data Warehouse & ETL 🔥\n\n```\nSOURCES → STAGE/ETL → DATA WAREHOUSE → MODELING → REPORT & BI\n```\n\n**ETL (Extract, Transform, Load):**\n- **Extract** — kéo dữ liệu thô từ các nguồn (CRMs, flat files, legacy databases, APIs)\n- **Transform** — làm sạch: loại bỏ duplicates, chuẩn hóa format, áp dụng business rules\n- **Load** — ghi dữ liệu đã chuẩn bị vào Data Warehouse (bảng cuối)\n\n**Data Lake** → lưu mọi dữ liệu thô (unstructured), kể cả chưa biết sẽ dùng; **Data Warehouse** → dữ liệu đã clean, structured, sẵn cho BI.\n\n🔑 **Keywords (EN):** **ETL**, **Extract**, **Transform**, **Load**, **Data Lake**, **staging**, **bronze/silver/gold layer**, **schema-on-read** (Data Lake) vs **schema-on-write** (DW)\n\n---\n\n#### 9.1.4. Schema: Star vs Snowflake 🔥\n\n**Fact Table** — bảng trung tâm, chứa các **measures** (số liệu đo lường: doanh thu, số lượng bán) và **foreign keys** trỏ đến dimension tables.\n\n**Dimension Table** — bảng mô tả các chiều phân tích (Time, Product, Customer, Store…).\n\n| Tiêu chí | Star Schema | Snowflake Schema |\n|---|---|---|\n| **Cấu trúc** | Fact table nối thẳng với dimension tables (1 cấp) | Dimension tables được chuẩn hóa thêm (nhiều cấp) |\n| **Normalization** | Denormalized dimensions | Normalized dimensions |\n| **Query performance** | Nhanh hơn (ít JOIN hơn) | Chậm hơn (nhiều JOIN hơn) |\n| **Dung lượng lưu trữ** | Lớn hơn (dữ liệu lặp lại) | Nhỏ hơn |\n| **Độ phức tạp** | Đơn giản | Phức tạp hơn |\n| **Khi nào dùng** | Khi cần hiệu suất query cao | Khi muốn tối ưu bộ nhớ |\n\n🔑 **Keywords (EN):** **Star schema**, **Snowflake schema**, **Fact table**, **Dimension table**, **measures**, **denormalized**, **foreign key**, **multidimensional cube**\n\n---\n\n#### 9.1.5. OLAP Operations & Data Mart\n\n**OLAP Operations** trên multidimensional cube:\n- **Roll-up (drill-up)** — tổng hợp lên mức cao hơn (ngày → tháng → năm; thành phố → tỉnh → quốc gia)\n- **Drill-down** — phân rã xuống mức chi tiết hơn (năm → quý → tháng → ngày)\n- **Slice** — cắt một chiều với giá trị cụ thể (chỉ xem dữ liệu quý 1)\n- **Dice** — cắt nhiều chiều cùng lúc (quý 1 + region = HCMC)\n- **Pivot (Rotate)** — xoay trục để thay đổi góc nhìn\n\n**Data Mart** — subset nhỏ hơn, chuyên biệt của Data Warehouse cho một team cụ thể (Marketing Mart, Sales Mart); dữ liệu đã được pre-aggregated.\n\n🔑 **Keywords (EN):** **Roll-up**, **Drill-down**, **Slice**, **Dice**, **Pivot**, **Data Mart**, **pre-aggregated**, **OLAP cube**, **multidimensional model**\n\n---\n\n### §9.2. Distributed Database\n\n#### 9.2.1. Định nghĩa & Phân loại\n\n**Distributed Database (DDBMS)** là một tập hợp dữ liệu có liên quan về mặt logic, được lưu trữ vật lý trên nhiều node mạng khác nhau nhưng hoạt động như một hệ thống thống nhất.\n\nCác loại Distributed Database:\n| Loại | Đặc điểm |\n|---|---|\n| **Homogeneous** | Tất cả sites dùng cùng DBMS và schema. Dễ đồng bộ, ít phức tạp. |\n| **Heterogeneous** | Các sites dùng DBMS/schema/model khác nhau. Cần translation mechanisms. |\n| **Client-Server** | Server quản lý dữ liệu, client yêu cầu. Centralized control. |\n| **Peer-to-Peer (P2P)** | Mọi node đều bình đẳng (no dedicated server). Decentralized, no single point of failure. |\n| **Cloud-Based** | Triển khai trên cloud, auto-scaling, high availability, pay-as-you-go. |\n\n🔑 **Keywords (EN):** **Distributed Database**, **DDBMS**, **homogeneous**, **heterogeneous**, **logically interrelated**, **multiple network nodes**, **unified system**\n\n---\n\n#### 9.2.2. Data Fragmentation 🔥\n\n**Fragmentation** là chia nhỏ quan hệ thành các mảnh (fragments) lưu ở các site khác nhau.\n\n**Ba loại fragmentation:**\n\n| Loại | Cách chia | Điều kiện tái tạo |\n|---|---|---|\n| **Horizontal Fragmentation** | Chia theo hàng (rows) dựa trên điều kiện (e.g., Region = 'HN') | UNION của tất cả fragments |\n| **Vertical Fragmentation** | Chia theo cột (columns); **bắt buộc giữ Primary Key** ở mỗi fragment | JOIN trên Primary Key |\n| **Hybrid (Mixed) Fragmentation** | Áp dụng cả horizontal và vertical | JOIN + UNION |\n\n**Correctness Rules (Tính đúng đắn của Fragmentation):**\n1. **Completeness** — Fragment1 ∪ Fragment2 = Relation gốc (không mất dữ liệu)\n2. **Reconstruction** — Có thể khôi phục quan hệ gốc từ fragments (bằng UNION hoặc JOIN)\n3. **Disjointness** — Trong horizontal fragmentation, một record chỉ xuất hiện ở đúng 1 fragment (không trùng lặp)\n\n> **Ví dụ:** Bảng Employee với cột (ID, Name, Department, Region, Salary):\n> - **Horizontal**: Fragment1 = Region='HN'; Fragment2 = Region='HCM'\n> - **Vertical**: Fragment_HR = (ID, Name, Department, Region); Fragment_Acc = (ID, Salary)\n> - **Hybrid**: Chỉ lấy (ID, Salary) của nhân viên Region='HN'\n\n🔑 **Keywords (EN):** **Horizontal fragmentation**, **vertical fragmentation**, **hybrid fragmentation**, **completeness**, **reconstruction**, **disjointness**, **primary key retention**\n\n---\n\n#### 9.2.3. Replication & Transparency\n\n**Replication** — lưu bản sao dữ liệu ở nhiều sites:\n- **Synchronous replication** — đảm bảo strong consistency; trade-off: higher latency (chờ tất cả replicas xác nhận)\n- **Asynchronous replication** — ưu tiên availability và low latency; trade-off: có thể đọc dữ liệu cũ trong thời gian ngắn\n\n**Các loại Transparency trong DDBMS:**\n- **Distribution/Location Transparency** — người dùng không cần biết dữ liệu nằm ở đâu\n- **Replication Transparency** — người dùng không biết có bao nhiêu bản sao\n- **Fragmentation Transparency** — người dùng không biết dữ liệu bị phân mảnh như thế nào\n\n🔑 **Keywords (EN):** **Replication**, **synchronous**, **asynchronous**, **distribution transparency**, **location transparency**, **replication transparency**, **fragmentation transparency**\n\n---\n\n#### 9.2.4. Two-Phase Commit (2PC) 🔥\n\n**Vấn đề:** Các sites không thể commit độc lập — nếu site A commit nhưng site B crash, hệ thống không nhất quán.\n\n**Giải pháp: 2PC Protocol** để đảm bảo Atomicity trong distributed transactions.\n\n**Phase 1 — Prepare/Voting Phase:**\n1. Coordinator gửi `VOTE_REQUEST` đến tất cả participants\n2. Mỗi participant đánh giá điều kiện cục bộ (data integrity, constraints)\n3. Nếu sẵn sàng: ghi `PREPARE LOG` vào stable storage, giữ locks, trả lời `YES`\n4. Nếu không sẵn sàng: trả lời `NO`\n\n**Phase 2 — Decision Phase:**\n- Nếu **tất cả YES** → Coordinator gửi global `COMMIT`\n- Nếu **bất kỳ NO hoặc timeout** → Coordinator gửi global `ABORT`\n- Participants thực thi quyết định, ghi log và release locks\n\n**Điểm yếu:** **Blocking problem** — nếu Coordinator crash sau Prepare phase, participants không thể tự commit hay abort, bị mắc kẹt cho đến khi Coordinator recover.\n\n🔑 **Keywords (EN):** **Two-Phase Commit (2PC)**, **coordinator**, **participants**, **VOTE_REQUEST**, **PREPARE LOG**, **global COMMIT**, **global ABORT**, **atomicity**, **blocking problem**, **distributed transaction**\n\n---\n\n### §9.3. NoSQL\n\n#### 9.3.1. Giới thiệu & Đặc điểm\n\n**NoSQL** (\"Not Only SQL\") được phát triển để xử lý Big Data với Volume, Velocity, Variety lớn mà SQL truyền thống không đáp ứng được.\n\nĐặc điểm chính của NoSQL:\n- **Horizontal Scaling (Scale-Out)** — thêm node thay vì nâng cấp máy (↔ vertical scaling của SQL)\n- **Schema-less / Schema-on-read** — không cần định nghĩa cấu trúc trước\n- **Eventual Consistency** — dữ liệu đồng bộ dần dần (thay vì strong consistency ngay lập tức)\n- **Sharding** — phân tán dữ liệu theo horizontal partitioning qua nhiều node\n- **Replication** — sao chép dữ liệu để high availability\n- **Simplified queries** — CRUD qua API thay vì complex SQL; No built-in JOINs\n\n🔑 **Keywords (EN):** **NoSQL**, **Not Only SQL**, **horizontal scaling**, **schema-less**, **eventual consistency**, **sharding**, **replication**, **Big Data**, **Volume/Velocity/Variety**\n\n---\n\n#### 9.3.2. CAP Theorem 🔥\n\n**CAP Theorem (Brewer, 2000):** Một hệ thống phân tán **không thể đồng thời đảm bảo cả 3** tính chất sau:\n\n- **C — Consistency**: Mọi node đều thấy cùng dữ liệu tại cùng thời điểm (most recent write hoặc error)\n- **A — Availability**: Mọi request đều nhận được response (có thể là dữ liệu cũ)\n- **P — Partition Tolerance**: Hệ thống tiếp tục hoạt động dù mạng bị chia đôi (network partition)\n\n> **Thực tế:** P là bắt buộc cho bất kỳ distributed system nào. Lựa chọn thực sự là **C vs A** khi xảy ra partition.\n\n| Hệ thống | CAP Choice | Ví dụ |\n|---|---|---|\n| CP | Consistency + Partition Tolerance | HBase, Neo4j (Causal Clustering) |\n| AP | Availability + Partition Tolerance | Cassandra, DynamoDB |\n| CA | Consistency + Availability | RDBMS (không distributed) |\n\n🔑 **Keywords (EN):** **CAP theorem**, **Consistency**, **Availability**, **Partition Tolerance**, **network partition**, **Brewer**, **CP**, **AP**, **CA**\n\n---\n\n#### 9.3.3. ACID vs BASE 🔥\n\n| Thuộc tính | ACID (SQL/RDBMS) | BASE (NoSQL) |\n|---|---|---|\n| **A** | Atomicity — all-or-nothing | Basically Available — luôn có response |\n| **C** | Consistency — valid state → valid state | Soft state — trạng thái có thể thay đổi theo thời gian |\n| **I** | Isolation — transactions không can thiệp nhau | Eventual consistency — các replicas hội tụ về cùng giá trị |\n| **D** | Durability — committed data tồn tại sau crash | — |\n| **Ưu tiên** | Strong consistency, correctness | High availability, scalability |\n\n🔑 **Keywords (EN):** **ACID**, **BASE**, **Atomicity**, **Consistency**, **Isolation**, **Durability**, **Basically Available**, **Soft state**, **Eventual consistency**\n\n---\n\n#### 9.3.4. 4 Loại NoSQL 🔥\n\n| Loại | Data Model | Điểm mạnh | Use Cases | Ví dụ |\n|---|---|---|---|---|\n| **Key-Value Store** | Massive dictionary: key → value (black box) | Lightning-fast read/write; đơn giản | Caching, session management, shopping carts | Redis, Amazon DynamoDB |\n| **Document Store** | JSON/BSON documents (self-describing, nested) | Flexible schema, rich query, maps to app objects | CMS, e-commerce catalogs, complex user profiles | MongoDB, Couchbase |\n| **Wide-Column Store** | Rows với dynamic columns; Partition key + Clustering columns | Write-optimized; massive scale; time-series | IoT sensor logs, event tracking, time-series data | Apache Cassandra, HBase |\n| **Graph Database** | Nodes (entities) + Edges (relationships) + Properties | Instant traversal; relationship-first; O(1) per hop | Social networks, recommendation engines, fraud detection | Neo4j, Amazon Neptune |\n\n🔑 **Keywords (EN):** **Key-Value**, **Document**, **Wide-Column**, **Graph**, **Redis**, **MongoDB**, **Cassandra**, **HBase**, **Neo4j**, **sharding**, **partition key**, **clustering column**\n\n---\n\n#### 9.3.5. SQL vs NoSQL — So sánh tổng quan\n\n| Tiêu chí | SQL | NoSQL |\n|---|---|---|\n| **Goal** | Absolute Consistency | Availability |\n| **Model** | ACID | BASE |\n| **Schema** | Schema-on-write, Strict (predefined) | Schema-on-read, Flexible (schema-less) |\n| **Architecture** | Centralized, Vertical Scaling | Distributed, Horizontal Scaling |\n| **Joins** | Native SQL JOINs | No joins (application-side logic) |\n| **Transactions** | Full ACID transactions | Limited; eventual consistency |\n| **Khi dùng** | Structured data, strong consistency | Semi/unstructured, high volume, speed |\n\n> **Lưu ý thi:** NoSQL = \"Not Only SQL\" — không phải thay thế hoàn toàn SQL, mà là **complementary tool** (polyglot persistence).\n\n---\n\n### §9.4. Neo4j — Graph Database\n\n#### 9.4.1. Property Graph Model 🔥\n\nNeo4j dựa trên **Property Graph Model** với 4 thành phần:\n\n1. **Nodes (Vertices)** — đại diện cho entities (danh từ). Mỗi node có:\n   - **Labels** — phân loại (`:Student`, `:Course`); 1 node có thể có nhiều labels\n   - **Properties** — key-value pairs tùy ý (e.g., `name: \"Alice\"`, `gpa: 3.8`)\n\n2. **Relationships (Edges)** — đại diện cho connections (động từ). Mỗi relationship:\n   - Có **hướng** (directed), nhưng có thể traverse cả 2 chiều\n   - Có đúng **1 Type** (e.g., `:ENROLLED_IN`, `:FRIEND_WITH`)\n   - Có thể có **Properties** riêng (e.g., `since: 2023`)\n\n3. **Labels** — cơ chế phân loại (categorization)\n\n4. **Properties** — key-value pairs lưu trực tiếp trên nodes/relationships (không cần bảng riêng)\n\n**Index-Free Adjacency:** Relationships được lưu vật lý như pointers trực tiếp đến nodes — không cần B-Tree index để traverse. Độ phức tạp traversal: **O(k × d)** (k = số hops, d = average degree), thay vì **O(k × log N)** của SQL JOIN.\n\n🔑 **Keywords (EN):** **Property Graph Model**, **Nodes**, **Relationships**, **Labels**, **Properties**, **Index-Free Adjacency**, **directed**, **typed relationship**, **pre-materialized**\n\n---\n\n#### 9.4.2. Cypher Query Language 🔥\n\nCypher dùng cú pháp **ASCII-Art** để biểu diễn graph patterns:\n\n```\n(n)                    — node variable n\n(n:Label)              — node với label\n(n {prop: val})        — node với property filter\n-[:TYPE]->             — directed relationship\n-[:TYPE*1..3]->        — variable-length path (1 đến 3 hops)\n(a)--(b)               — undirected relationship\n```\n\n**Các mệnh đề Cypher quan trọng:**\n\n| Mệnh đề | Chức năng |\n|---|---|\n| `MATCH` | Tìm kiếm pattern trong graph |\n| `OPTIONAL MATCH` | Left outer join (trả về NULL nếu không match) |\n| `WHERE` | Lọc theo điều kiện |\n| `RETURN` | Trả về kết quả |\n| `CREATE` | Tạo node/relationship mới |\n| `MERGE` | Upsert — tạo nếu chưa tồn tại (idempotent) |\n| `SET / REMOVE` | Cập nhật/xóa properties |\n| `DELETE / DETACH DELETE` | Xóa node (DETACH xóa cả relationships) |\n| `WITH` | Pipeline (chuyển kết quả sang bước tiếp theo) |\n\n**Ví dụ Cypher cơ bản:**\n\n```cypher\n// Tạo node và relationship\nCREATE (a:Student {name: \"Alice\", gpa: 3.8})\nCREATE (b:Course {code: \"CO2013\", name: \"Database Systems\"})\nCREATE (a)-[:ENROLLED_IN {semester: \"HK2\"}]->(b)\n\n// Tìm kiếm\nMATCH (s:Student)-[:ENROLLED_IN]->(c:Course)\nWHERE c.code = \"CO2013\"\nRETURN s.name, c.name\n\n// Variable-length path (bạn bè trong vòng 3 hops)\nMATCH (me:Student {name: \"Alice\"})-[:FRIEND*1..3]-(network:Student)\nWHERE network <> me\nRETURN network.name\n```\n\n🔑 **Keywords (EN):** **Cypher**, **MATCH**, **CREATE**, **MERGE**, **RETURN**, **WHERE**, **DETACH DELETE**, **pattern matching**, **variable-length path**, **ASCII-art syntax**, **openCypher**\n\n---\n\n#### 9.4.3. Neo4j vs Relational DB\n\n| Tiêu chí | Neo4j (Graph) | Relational DB |\n|---|---|---|\n| **Relationship representation** | First-class objects, pre-materialized on disk | Derived at query time via JOIN + index scan |\n| **Traversal cost** | O(k × d) — constant per hop | O(k × log N) — grows with data size |\n| **Schema** | Flexible (schema-optional) | Rigid (predefined) |\n| **Joins** | Native O(1) per hop (pointer following) | Expensive index-based hash/merge join |\n| **Relationship properties** | Stored directly on relationship | Cần alter JOIN table |\n| **Phù hợp** | Complex, connected, deep relationships | Flat, structured, tabular data |\n\n🔑 **Keywords (EN):** **Graph traversal**, **index-free adjacency**, **relationship as first-class citizen**, **pointer following**, **ACID** (Neo4j là ACID-compliant), **Causal Clustering**, **Raft consensus**\n\n---\n\n### §9.5. Data Anonymization\n\n#### 9.5.1. Khái niệm cơ bản\n\n**Data Anonymization** là quá trình biến đổi dữ liệu có hệ thống, cắt đứt khả năng nhận diện cá nhân trong khi vẫn giữ giá trị phân tích của dữ liệu.\n\n**Phân loại thuộc tính:**\n- **Direct Identifiers (PII — Personally Identifiable Information)** — xác định trực tiếp 1 người: Name, Phone number, Address, IP address\n- **Quasi-Identifiers (QIDs)** — không xác định trực tiếp nhưng khi kết hợp có thể tái nhận diện: Zip code, Birthdate, Gender\n\n> 🔥 **87% người dùng có thể bị tái nhận diện chỉ với 3 QIDs: Zip code + Birthdate + Gender** (Sweeney, 2000)\n\n**Các kiểu tấn công:**\n- **Linkage Attack** — re-identify bằng cách ghép QIDs với dữ liệu công khai khác\n- **Predicate Singling-Out Attack** — dùng logical query để cô lập 1 cá nhân trong dữ liệu đã tổng quát hóa\n- **Downcoding Attack** — khai thác cấu trúc phân cấp kết hợp với prior knowledge\n\n🔑 **Keywords (EN):** **Data Anonymization**, **Direct Identifiers**, **PII**, **Quasi-Identifiers (QIDs)**, **Linkage Attack**, **re-identification**, **Predicate Singling-Out**\n\n---\n\n#### 9.5.2. Transformation Mechanisms\n\n- **Generalization** — nhóm các giá trị cụ thể vào category rộng hơn, nhất quán về mặt ngữ nghĩa\n  - Ví dụ: `Date of Birth → Birth Year`; `Age 28 → Age Range 20-30`; `ZIP 700123 → Region HCM`\n- **Suppression** — xóa hoàn toàn hoặc che những giá trị ngoại lệ không thể tổng quát hóa\n  - Ví dụ: `ZIP 700123 → 700***`\n\n🔑 **Keywords (EN):** **Generalization**, **Suppression**, **equivalence class**, **masking**, **bucketing**, **data utility**\n\n---\n\n#### 9.5.3. k-Anonymity, l-Diversity, t-Closeness 🔥\n\n| Mô hình | Định nghĩa | Bảo vệ chống | Điểm yếu |\n|---|---|---|---|\n| **k-Anonymity** | Mỗi record không phân biệt được với ít nhất **k-1** records khác dựa trên QIDs. Nếu k=3: attacker thấy nhóm ≥3 hồ sơ giống nhau | Linkage Attack | Homogeneity Attack |\n| **l-Diversity** | Mỗi equivalence class phải có ít nhất **l giá trị sensitive phân biệt**. Chance đoán đúng sensitive attribute ≤ 1/l | Homogeneity Attack | Background knowledge attack; skewness attack |\n| **t-Closeness** | Phân phối sensitive attribute trong mỗi group phải **gần** với phân phối toàn bộ bảng (khoảng cách ≤ t) | Background knowledge attack | Giảm data utility nhiều hơn |\n\n**Homogeneity Attack:** k-anonymity thất bại khi tất cả records trong một group chia sẻ cùng sensitive attribute. Ví dụ: nhóm 3 người đều có \"Stomach Cancer\" — attacker không biết ai trong nhóm nhưng **biết chắc** target có Stomach Cancer.\n\n> **Ví dụ k=3:** Group với Age 20-30 gồm Alice, Bob, Charlie — nếu cả 3 đều có Stomach Cancer → vi phạm l-diversity (cần l≥2 tức ≥2 diseases khác nhau).\n\n🔑 **Keywords (EN):** **k-anonymity**, **l-diversity**, **t-closeness**, **equivalence class**, **Homogeneity Attack**, **sensitive attribute**, **generalization**, **suppression**, **quasi-identifiers**\n\n---\n\n#### 9.5.4. Differential Privacy (Modern Model) 🔥\n\n**Differential Privacy** — bảo vệ query outputs thay vì chỉ bảo vệ cấu trúc bảng. Kết quả query phải **gần như giống nhau** dù một người cụ thể có trong database hay không.\n\n**Privacy budget ε (epsilon):** Kiểm soát trade-off giữa privacy strength và result accuracy:\n- ε nhỏ → privacy mạnh hơn, noise nhiều hơn, kém chính xác\n- ε lớn → privacy yếu hơn, noise ít hơn, chính xác hơn\n\n**Laplace Mechanism** — kỹ thuật phổ biến:\n1. Tính aggregate thật: `AVG(salary) = $52,000`\n2. Thêm Laplace noise (phụ thuộc ε và query sensitivity): `Noise = -$660`\n3. Trả về output riêng tư: `$51,340`\n\n**Giới hạn thực tế:**\n- Repeated queries → privacy budget bị cạn kiệt theo thời gian\n- Quá nhiều noise → kết quả phân tích sai lệch\n- Cần query logging, access control, và governance nghiêm ngặt\n\n🔑 **Keywords (EN):** **Differential Privacy**, **privacy budget (ε)**, **Laplace mechanism**, **noise calibration**, **query sensitivity**, **membership inference**, **GDPR**\n\n---\n\n### §9.6. MCQ Traps — Advanced Topics\n\n> Những cặp từ dễ nhầm trong trắc nghiệm:\n\n| Trap | Sai (distractor) | Đúng |\n|---|---|---|\n| **NoSQL thay thế SQL?** | \"NoSQL replaces SQL\" | NoSQL = \"Not Only SQL\" — **complementary**, không thay thế |\n| **NoSQL scalability key?** | \"Eventual consistency\" hoặc \"schema-less\" | **Data distribution that allows horizontal scale** (đây là key contribution theo QUIZ) |\n| **Big Data = too many X?** | Too many users / too long transactions / too many apps | **Too much data to handle with traditional technologies** |\n| **Velocity trong Big Data?** | Monthly reports, batch processing | **Real-time / sensor-based monitoring** (phải xử lý ngay lập tức) |\n| **k-anonymity bảo vệ gì?** | Sensitive attribute leakage | Linkage Attack — **k-anonymity KHÔNG bảo vệ khỏi Homogeneity Attack** |\n| **l-diversity đảm bảo gì?** | Đảm bảo k groups | Đảm bảo ≥ l **distinct sensitive values** trong mỗi group |\n| **Schema trong SQL vs NoSQL** | \"SQL cần schema, NoSQL không cần\" | SQL = **predefined schema (schema-on-write)**; NoSQL = **schema-less / schema-on-read** |\n| **NoSQL distributed?** | \"NoSQL là distributed, SQL không phải\" | SQL systems **cũng có thể distributed** — không phải đặc điểm độc quyền của NoSQL |\n| **Document DB = Table?** | Document ≈ table/relation | Document ≈ **record/row** (1 JSON document = 1 record) |\n| **2PC blocking?** | Coordinator crashes trước Prepare | Blocking xảy ra khi Coordinator crash **sau** Prepare phase |\n| **Vertical fragmentation?** | Có thể bỏ Primary Key | **Bắt buộc giữ Primary Key** để reconstruction bằng JOIN |\n| **Star vs Snowflake faster?** | Snowflake nhanh hơn | **Star schema nhanh hơn** (ít JOINs hơn) |\n| **OLTP vs OLAP writes?** | OLAP heavy writes | OLAP = **heavy reads**; OLTP = heavy writes |\n| **Neo4j NoSQL model?** | Document, Key-Value | Neo4j = **Graph** model (Neo4j → graph, Redis → key-value, MongoDB → document, HBase/Cassandra → wide-column) |\n| **CAP: P là optional?** | Có thể bỏ P | P **bắt buộc** với distributed systems; lựa chọn thực là C vs A |\n\n---\n\n> **Bộ Neo4j mapping (thường ra MCQ):**\n> - **(a) Neo4j → (iii) graph** — **(b) Redis → (iv) key-value** — **(c) MongoDB → (ii) document** — **(d) HBase → (i) wide-column**\n\n---\n\n# §10. CÂU THẦN CHÚ TRƯỚC KHI VÀO PHÒNG THI\n\n> Bản tổng hợp các one-liner phải thuộc, đánh số liên tục, nhóm theo chương. 🔥 = câu critical. Ôn riêng mục này đêm trước thi (mỗi chương đã có \"🪄 Câu thần chú §N\" chi tiết hơn ở trên).\n\n**§1 — Overview**\n1. 🔥 Database System = DB + DBMS + Application + Users — KHÔNG phải chỉ DBMS.\n2. 🔥 Schema = bản vẽ (intension, hiếm đổi) · State/Instance/Snapshot = dữ liệu thực tế (extension, đổi liên tục).\n3. 🔥 3-schema: External (ai thấy gì) → Conceptual (có gì) → Internal (lưu thế nào). Mục tiêu = data independence.\n4. 🔥 Physical independence (đổi internal, conceptual giữ nguyên) DỄ hơn Logical independence (đổi conceptual, external giữ nguyên).\n5. 🔥 SQL = non-procedural/declarative; relational algebra = procedural. KHÔNG phải mọi DML đều non-procedural.\n6. Metadata lưu trong System Catalog (Data Dictionary). Conceptual design = DBMS-independent; Physical design mới phụ thuộc DBMS.\n\n**§2 — ERD & EERD** 🔥🔥\n7. 🔥 Danh từ → Entity · Tính chất → Attribute · Động từ → Relationship · Unique/SSN → Key.\n8. 🔑 Weak entity = `no key of its own` + `partial key` + `identifying relationship` (◇◇) + `total participation` + `existence-dependent`. PK = {owner_PK, partial_key}.\n9. 🔥 Cardinality ratio (\"bao nhiêu\": 1:1/1:N/M:N) và Participation (\"có bắt buộc\": total/partial) là HAI TRỤC ĐỘC LẬP.\n10. 🔥 Attribute M:N BẮT BUỘC nằm trên relationship (Hours trên WORKS_ON) — không migrate.\n11. Multivalued = oval đôi · Derived = oval đứt (không lưu) · Composite = oval cha-con (flatten khi map).\n12. 🔥 `|Sup| = |Sub1| + |Sub2|` ⟺ **Total AND Disjoint**.\n13. 🔥 Shared subclass = AND/∩ (thuộc TẤT CẢ cha) · Category/Union type = OR/∪ (thuộc CHỈ 1 cha, owner khác key → surrogate key).\n14. Specialization = top-down · Generalization = bottom-up · vẽ giống nhau. Subclass IS-A superclass; subclass/superclass luôn 1:1.\n15. Fan trap = pathway mơ hồ (≥2 nhánh 1:N) · Chasm trap = pathway đứt (partial participation).\n\n**§3 — Relational Mapping**\n16. 🔥 1:1 → FK phía total (UNIQUE) · 1:N → FK phía N · M:N → bảng riêng + 2 FK (PK = cả 2).\n17. Multivalued → bảng riêng · Composite → flatten · Derived → bỏ.\n18. 🔥 Ternary A:1, B:N, C:N → PK = (B,C); A là FK KHÔNG vào PK.\n19. 🔥 Total participation phía N/weak → `FK NOT NULL` đủ; phía \"1\"/M:N → cần CHECK/assertion/trigger.\n20. Specialization: 8B chỉ Total+Disjoint · 8C không xử lý Overlap · 8D tốt cho Overlap · 8A luôn an toàn.\n21. 🔥 4 ràng buộc của Relational Model = Domain · Key · Entity integrity (PK≠NULL) · Referential integrity. Participation KHÔNG thuộc nhóm này.\n22. DELETE vi phạm Referential integrity · INSERT vi phạm Entity integrity/Key/Referential. Relation = SET (không tuple trùng, atomic).\n\n**§4 — Relational Algebra**\n23. 🔥 σ cắt HÀNG · π cắt CỘT (tự loại trùng) · ρ đổi tên.\n24. 🔥 ∪/∩/− đòi union-compatible (− KHÔNG giao hoán) · × và ⋈ KHÔNG cần.\n25. 🔥 Natural join `*` nối cột CÙNG TÊN (bỏ 1 cột trùng); khác tên (SSN≠ESSN, Dnum≠Dnumber) → phải `⋈_{cond}`.\n26. 🔥 Division ÷ = \"for all/every\" = double `NOT EXISTS`. \"do not/without\" = set difference. \"for each/per\" = group 𝓕.\n27. `|RA π| ≤ |SQL SELECT|` (RA là set, SQL là multiset). `R ⟕ S = S ⟖ R`. RA = procedural, Calculus = non-procedural.\n\n**§5 — SQL** 🔥🔥\n28. 🔥 Thứ tự: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY. WHERE lọc tuple, HAVING lọc nhóm (aggregate → HAVING).\n29. 🔥 NULL: dùng `IS NULL`/`IS NOT NULL`, KHÔNG `= NULL`. `CHECK(X>1)` không chặn NULL (UNKNOWN).\n30. 🔥 `> ALL` = `> MAX` · `> ANY` = `> MIN` · `= ANY` = `IN`.\n31. 🔥 \"Làm TẤT CẢ\" = double `NOT EXISTS` (\"không có X nào mà chưa làm\"). `EXISTS` = \"ít nhất 1\" ≠ `COUNT(*)=1` = \"đúng 1\".\n32. 🔥 `LEFT JOIN … WHERE rightKey IS NULL` = anti-join (\"không có\"). `COUNT(*)` sau LEFT JOIN đếm cả NULL → dùng `COUNT(col)`.\n33. 🔥 Procedure: gọi `EXEC`, có thể nhiều result set, OUTPUT param phải `SET @out=(...)`. Function: `dbo.f()` trong SELECT/WHERE, TVF trong FROM.\n34. 🔥 Trigger: `INSERTED`=row mới, `DELETED`=row cũ (UPDATE có cả 2). Khác procedure ở activation (tự động theo event vs gọi tường minh).\n35. `ON DELETE CASCADE` khai ở bảng CON. `SECONDARY KEY` không có cú pháp → dùng `UNIQUE`. ACID: A = Atomicity (KHÔNG phải Accuracy).\n\n**§6 — FD & Normalization** 🔥\n36. 🔥 `F⁺` = closure TẬP FD (chứa luật) · `X⁺` = closure TẬP THUỘC TÍNH (chứa cột). Đừng nhầm.\n37. 🔥 `X⁺ = R` ⟺ superkey; tối giản ⟺ candidate key. Tính `X⁺`, đừng đoán key.\n38. U_left bắt buộc trong mọi CK · U_right không bao giờ trong CK · U_both thì thử.\n39. 🔥 1NF atomic · 2NF không partial · 3NF (X superkey HOẶC A prime) · BCNF (X superkey — không ngoại lệ).\n40. 🔥 Vi phạm 2NF → dạng chuẩn cao nhất = 1NF. Luôn báo dạng chuẩn THẤP nhất đạt được.\n41. 🔥 BCNF luôn lossless join nhưng có thể MẤT dependency preservation (TEACH: Instructor→Course là 3NF, không BCNF).\n42. NJB lossless: `(R1∩R2)→(R1−R2)` hoặc `(R1∩R2)→(R2−R1)` ∈ F⁺. Normalization = giảm dư thừa (KHÔNG giảm JOIN).\n\n**§7 — Storage & Indexing**\n43. 🔥 `bfr = ⌊B/R⌋` (linked: `⌊(B−p)/R⌋`) · `b = ⌈r/bfr⌉`.\n44. 🔥 Heap search avg `b/2`, worst `b` · Ordered (binary) `⌈log₂ b⌉` · Hashed = 1.\n45. 🔥 Primary index #entries = #block (sparse, field KEY + file ordered) · Clustering = #distinct values (non-key ordered) · Secondary on key = #record (dense).\n46. 🔥 1 file CHỈ 1 Primary HOẶC 1 Clustering (1 thứ tự vật lý), nhiều Secondary. Index search = ⌈log₂ bᵢ⌉ + 1; multilevel = L + 1.\n47. B+-tree: con trỏ dữ liệu CHỈ ở leaf; B-tree có thể ở internal. Heap = insert nhanh nhất.\n\n**§8 — Security**\n48. 🔥 DAC = chủ sở hữu cấp quyền (GRANT/REVOKE, WITH GRANT OPTION) · MAC = hệ thống quyết định theo nhãn (U<C<S<TS), bảo mật cao hơn DAC.\n49. 🔥 Bell-LaPadula: **no read-up** (đọc khi clearance ≥ class) + **no write-down** (ghi khi clearance ≤ class) → bảo vệ Confidentiality. Biba ngược lại → Integrity.\n50. 🔥 REVOKE cascade: thu hồi của 1 người → thu hồi luôn mọi quyền người đó đã cấp tiếp.\n51. 🔥 Lọc theo hàng/cột để cấp quyền → tạo VIEW rồi GRANT trên view (KHÔNG `GRANT … WHERE`).\n52. Asymmetric: confidentiality → mã hoá bằng **public key người nhận**; chữ ký/authentication → ký bằng **private key người gửi**.\n53. CIA: modify→Integrity · read/disclose→Confidentiality · accessible on request→Availability. DBA chịu trách nhiệm bảo mật.\n\n**§9 — Advanced Topics**\n54. 🔥 OLTP = heavy writes, normalized · OLAP = heavy reads, multidimensional. Star schema nhanh hơn (ít JOIN) Snowflake (chuẩn hoá dimension).\n55. 🔥 CAP: P bắt buộc với distributed → chọn C vs A. ACID (SQL) vs BASE (NoSQL: Basically Available, Soft state, Eventually consistent).\n56. 🔥 4 loại NoSQL: Key-Value (Redis) · Document (MongoDB) · Wide-Column (Cassandra/HBase) · Graph (Neo4j).\n57. 🔥 NoSQL key scalability = data distribution → horizontal scaling. NoSQL = \"Not Only SQL\" (bổ trợ, không thay thế).\n58. Fragmentation: Horizontal (rows, tái tạo bằng UNION) · Vertical (cols, GIỮ PK, tái tạo bằng JOIN). Đúng đắn = completeness + reconstruction + disjointness. 2PC: blocking nếu coordinator crash sau Prepare.\n59. Neo4j = property graph (Nodes + Relationships có hướng + Labels + Properties), index-free adjacency, Cypher `MATCH … RETURN`.\n60. 🔥 Data anonymization: k-anonymity (chống linkage, yếu trước homogeneity) → l-diversity (≥ l sensitive value/group) → t-closeness. Quasi-identifiers (Zip+Birthdate+Gender) tái nhận diện 87%.\n61. 🔥 \"NOT an ACID property\" = **Accuracy**. SQL query processing: Parse → Optimize → Generate → Execute.\n\n---\n\n# §11. \"IF YOU SEE X → THINK Y\" + ĐÁP ÁN GÂY TRANH CÃI\n\n> Bảng tra tốc độ trong phòng thi (open-book): thấy cụm từ bên trái → ánh xạ ngay sang khái niệm/đáp án bên phải.\n\n","file":"materials/DB-Final.md","section":18},{"id":"final-19","group":"final","kind":"source","title":"11.1. Speed-recap \"if you see X → think Y\"","markdown":"## 11.1. Speed-recap \"if you see X → think Y\"\n\n| Thấy trong đề | Nghĩ ngay tới |\n|---|---|\n| \"set of concepts describing data + relationships + constraints\" | **Data model** (không phải schema) |\n| figure: tên bảng + cột + data rows cụ thể | **Database state / snapshot** (không phải schema) |\n| đổi cách lưu/index, conceptual giữ nguyên | **Physical data independence** |\n| đổi conceptual, external giữ nguyên | **Logical data independence** (khó hơn) |\n| no key of its own / partial key / identifying | **Weak entity** |\n| \"must / at least one\" | **Total participation** |\n| \"may / optional / some have none\" | **Partial participation** |\n| `|Sup| = |Sub1| + |Sub2|` | **Total AND Disjoint** |\n| thuộc TẤT CẢ cha (AND/∩) | **Shared subclass** |\n| thuộc CHỈ 1 cha (OR/∪), owner khác key | **Category / Union type** → surrogate key |\n| pathway mơ hồ (≥2 nhánh 1:N) | **Fan trap** |\n| pathway đứt (partial participation giữa) | **Chasm trap** |\n| 1:N mapping | FK ở phía **N** |\n| M:N mapping / multivalued attribute | **bảng riêng** |\n| composite attribute | **flatten** thành components |\n| ternary A:1, B:N, C:N | PK = (B,C); A là FK không vào PK |\n| \"for each / per / mỗi\" | **GROUP BY / 𝓕** |\n| \"do not / without / no / không\" | **set difference** (RA) / `NOT EXISTS` (SQL) |\n| \"for all / every / tất cả / mọi\" | **division ÷** (RA) / **double `NOT EXISTS`** (SQL) |\n| `> ALL (subquery)` | strictly greater than **MAX** |\n| `> ANY` / `= ANY` | greater than **MIN** / **IN** |\n| aggregate dùng để lọc nhóm | **HAVING** (không bao giờ WHERE) |\n| so sánh với NULL | `IS NULL` / `IS NOT NULL` (không `=`/`<>`) |\n| `LEFT JOIN … WHERE rightKey IS NULL` | rows **không có** bản ghi liên quan (anti-join) |\n| natural join `*` với cột khác tên | SAI → dùng `⋈_{cond}` hoặc `ρ` |\n| gọi `EXEC` | **procedure** (function gọi `dbo.f()`, TVF trong `FROM`) |\n| `INSERTED` / `DELETED` trong code | **trigger** (mới / cũ; UPDATE có cả 2) |\n| `ON DELETE CASCADE` ở đâu | khai báo ở **bảng con** (chứa FK) |\n| vi phạm 2NF | dạng chuẩn cao nhất = **1NF** |\n| determinant luôn là superkey | **BCNF** |\n| `X→A`: X không superkey nhưng A prime | **3NF nhưng không BCNF** |\n| tính key | tính **`X⁺`** (đừng đoán) |\n| `bfr` | `⌊B/R⌋` (linked: `⌊(B−p)/R⌋`) |\n| `b` (số block) | `⌈r/bfr⌉` |\n| heap search | avg `b/2`, worst `b` |\n| ordered search trên ordering field | `⌈log₂ b⌉` |\n| primary index #entries | = **#data blocks** (sparse) |\n| clustering index #entries | = **#distinct values** |\n| secondary index on key #entries | = **#records** (dense) |\n| multilevel search cost | **#levels + 1** |\n| modify / change / unauthorized modification | **Integrity** |\n| read / view / disclose / secret | **Confidentiality** |\n| shown on request / accessible when needed | **Availability** |\n| username/password access | Identification → Authentication → Authorization |\n| owner cấp quyền (GRANT/REVOKE) | **DAC** |\n| U/C/S/TS, subject/object classification | **MAC** |\n| roles Admin/Lecturer/Student | **RBAC** |\n| no read-up / no write-down | **Bell-LaPadula** → Confidentiality |\n| no read-down / no write-up | **Biba** → Integrity |\n| \"only Bob can read\" | Bob's **public** key |\n| \"prove Alice sent / not tampered\" | Alice's **private** key |\n| GRANT chỉ một số dòng/cột | CREATE **VIEW** + GRANT on view |\n| sensor stream / real-time | **Velocity** |\n| too much data for traditional tech | **Volume / Big Data** |\n| NoSQL scalability | **horizontal scaling / data distribution** |\n| Neo4j / Redis / MongoDB / HBase·Cassandra | Graph / Key-value / Document / Wide-column |\n| OLTP vs OLAP | OLTP heavy-write normalized · OLAP heavy-read multidimensional |\n| Star vs Snowflake | Star = denormalized, ít JOIN, nhanh hơn |\n| vertical fragmentation | **giữ Primary Key** để JOIN tái tạo |\n| NOT an ACID property | **Accuracy** |\n| k-anonymity yếu trước | **Homogeneity attack** → cần l-diversity |\n| user xem dữ liệu của chính mình khi yêu cầu | **Availability** (không phải Confidentiality) |\n| \"minimize NULL values\" là mục đích normalization? | KHÔNG — đó là informal guideline; mục tiêu hình thức = attribute/dependency preservation + lossless join |\n| \"external level\" | = **view level** (2 thuật ngữ tương đương) |\n| Shared File Approach phát sinh vấn đề gì | **rigid data structure**, physical data dependency, no concurrency control |\n| INNER JOIN = RIGHT OUTER JOIN khi nào | khi **không có NULL** ở cột FK (mọi dòng đều match) |\n| \"phân tích nhu cầu lưu trữ\" là việc của ai | **Database Designer**, KHÔNG phải DBA |\n| chỉ mệnh đề nào bắt buộc trong SQL | **SELECT** (+FROM); WHERE/GROUP BY/HAVING/ORDER BY optional |\n| 1:1 mapping FK | phía total + phải **UNIQUE** (thiếu UNIQUE → thành N:1) |\n| ràng buộc theo thời gian trôi (sau N ngày…) | **scheduled job/cron**, trigger không làm được |\n| fan trap đúng nghĩa | **1:N + 1:N** từ cùng hub (M:N+1:N thì không phải fan trap thuần) |\n\n","file":"materials/DB-Final.md","section":19},{"id":"final-20","group":"final","kind":"source","title":"11.2. Đáp án gây tranh cãi (class key ≠ lý thuyết chuẩn)","markdown":"## 11.2. Đáp án gây tranh cãi (class key ≠ lý thuyết chuẩn)\n\n> Nếu đề lặp lại **nguyên văn** câu cũ → theo class key; nếu là phát biểu lý thuyết chuẩn → theo lý thuyết. Luôn đọc kỹ wording/quy ước thứ tự đề công bố.\n\n| Chủ đề | Class key | Lý thuyết chuẩn / Ghi chú |\n|---|---|---|\n| Asymmetric crypto — Alice đảm bảo **integrity/authentication** | A | Alice ký bằng **private key của Alice** → theory = D |\n| Bell-LaPadula no-write-down (U<C<S<TS) | B | Ghi hợp lệ khi `class(S) ≤ class(O)`; có thể đề dùng quy ước thứ tự đảo |\n| VIEW giấu lương nhân viên kinh nghiệm | C | Option C (`WHERE superssn IS NOT NULL`) làm **mất** nhân viên → cần **UNION/CASE** (mask) → D |\n| `DROP TABLE … CASCADE` | E | Chuẩn SQL: xóa bảng + ràng buộc/view phụ thuộc — KHÔNG xóa cả schema, KHÔNG phải DELETE |\n| \"set of concepts describing data…\" (Overview) | C (schema) | Định nghĩa chuẩn = **Data model** (D); schema là thiết kế cụ thể trong một model |\n| Multilevel index cost (Storage Q38) | A (12) | 12 = `⌈log₂ 2942⌉` = binary search trên **data file**; multilevel index cost chuẩn = **3** |\n| \"many clustering indexes on one file\" (Storage) | — | SAI — 1 thứ tự vật lý ⇒ tối đa 1 primary/clustering index |\n| FD holds on instance (FD Q6) | E (`C→D`) | `A→B` cũng đúng trên instance đó → câu hỏi lỏng lẻo; instance chỉ **bác bỏ** được FD |\n| BillNo index type (HK191 Q36) | A (clustering) | BillNo = candidate key trên file KHÔNG sắp theo BillNo → đúng phải là **Secondary index (dense)**; clustering = file sắp theo NON-key → đáp án chính thức có thể là lỗi đề |\n| \"Minimize NULL\" là mục đích normalization? (F2024 Q24) | — | \"Minimize NULL\" là **informal design guideline**, KHÔNG phải mục tiêu hình thức của phép phân rã → khi hỏi \"cái nào KHÔNG phải mục đích normalization\" thì CHỌN nó |\n\n> ⚠️ **Nguyên tắc khi mâu thuẫn:** với đáp án dạng \"(Đáp án chỉ mang tính tham khảo)\" → ưu tiên **giáo trình/định nghĩa chuẩn**. Open-book → mang theo bảng này để tra nhanh.\n\n---\n\n# §12. MẸO LÀM BÀI TRẮC NGHIỆM (OPEN-BOOK)\n\n> Đề **open-book** → lợi thế là tra cứu, nhưng **bẫy nằm ở câu chữ**, không phải ở việc nhớ. 50 câu / 90 phút ≈ **1.8 phút/câu** → phải nhanh.\n\n1. **Chuẩn bị \"trang tra nhanh\".** In sẵn **§0 Quick Reference** + **§0bis Golden Rules** + **§11 If-you-see-X**. Khi gặp câu lý thuyết → Ctrl+F keyword EN trong file này; gặp câu tính → mở §0 Formula sheet.\n\n2. **Dịch đề thành điều kiện kỹ thuật TRƯỚC khi đọc đáp án** (§0bis.1). Gạch chân keyword: \"all / at least one / controlled by / belongs to / must / may\". Đề trường **bắt keyword** — đọc kỹ cụm danh từ + lượng từ.\n\n3. **Loại đáp án theo Golden Rules:** câu quá tuyệt đối (always/never/all) thường sai; \"đúng khái niệm sai chủ thể\"; over-privileged (vi phạm least privilege); giữ sai số dòng/bỏ cột.\n\n4. **Câu tính (Storage/FD): luôn dùng công thức, đừng nhớ đáp án cũ.** Xác định đang hỏi **record / block / index entry / index block / block access** — khác nhau. FD: **tính `X⁺`**, đừng đoán key. Kiểm 2NF trước 3NF trước BCNF (báo dạng chuẩn THẤP nhất).\n\n5. **Câu SQL/RA: đọc CỘT mà code thực sự lọc.** `Employee.Dno` (belongs-to) ≠ `Project.Dnum` (controlled-by). Natural join `*` chỉ nối cột **cùng tên**. \"Tất cả\" = double `NOT EXISTS`.\n\n6. **Câu ER/EER: tách 2 trục.** Cardinality (1:1/1:N/M:N) độc lập với Participation (total/partial). Disjoint/Overlap độc lập với Total/Partial. Đếm subclass chỉ cộng được khi **Total AND Disjoint**.\n\n7. **Đánh dấu câu phân vân, làm câu chắc trước.** Trọng số: ưu tiên chắc điểm §2 (10) và §5 (9) — gần 40% đề. Đừng kẹt 1 câu khó §9.\n\n8. **Khi 2 đáp án \"đều có vẻ đúng\":** chọn cái khớp **keyword EN nguyên văn slide/sách** + khớp với đáp án QUIZ BK-LMS đã học. Tra §11.2 nếu là câu đáp án gây tranh cãi.\n\n---\n\n# §13. CHECKLIST TRƯỚC KHI LOCK MỖI ĐÁP ÁN\n\nHỏi nhanh trước khi chọn:\n\n- [ ] Đáp án có dùng natural join khi tên cột khác nhau không? (SSN≠ESSN, Dnum≠Dnumber)\n- [ ] Hai vế của set difference có union-compatible không?\n- [ ] Multivalued attribute có bị nhét vào 1 cột không? (vi phạm 1NF)\n- [ ] `Other` có bị thêm vào dưới specialization **Total** không? (sai — Total buộc thuộc ≥1 subclass)\n- [ ] Có thiếu phép `π` khi đề đòi \"tất cả thông tin nhân viên\" không?\n- [ ] Aggregate đặt đúng clause chưa? (`WHERE` lọc tuple vs `HAVING` lọc nhóm)\n- [ ] MAC: đang suy luận từ **clearance của user**, không phải từ raw data?\n- [ ] Đáp án có quá tuyệt đối không? (always/never/all/none)\n- [ ] Đáp án có over-privileged không? (vi phạm least privilege)\n- [ ] Đáp án có xoá dòng trong khi chỉ cần mask giá trị không?\n- [ ] Đã tính `X⁺` thay vì đoán key chưa?\n- [ ] Đã đọc kỹ code lọc `Dno` (belongs-to) hay `Dnum` (controlled-by)?\n- [ ] So sánh NULL có dùng `IS NULL`/`IS NOT NULL` không? (không `=`/`<>`)\n- [ ] Báo dạng chuẩn THẤP nhất đã thoả (vi phạm 2NF → 1NF)?\n- [ ] Index: câu hỏi đang hỏi #record / #block / #entry / #block access?\n- [ ] Cardinality ratio và Participation đã tách thành 2 trục độc lập chưa?\n- [ ] Shared subclass (AND/∩) hay Category (OR/∪)? Owner có cùng key không (→ surrogate key)?\n\n---\n\n# §14. KẾT LUẬN + CHIẾN LƯỢC 3 NGÀY\n\n","file":"materials/DB-Final.md","section":20},{"id":"final-21","group":"final","kind":"source","title":"14.1. Bảng đối chiếu chương ↔ nguồn ↔ số câu","markdown":"## 14.1. Bảng đối chiếu chương ↔ nguồn ↔ số câu\n\n| § | Chủ đề | Nguồn lecture/slide | Số câu | % đề |\n|---|---|---|---|---|\n| 1 | Database System Overview | `00_Introduction`, `01_Database System Concepts` | 5 | 10% |\n| 2 | ERD & EERD 🔥🔥 | `02_ER Model`, `03_EER Model` | 10 | 20% |\n| 3 | Relational Mapping | `04_Relational Data Model and Relational Mapping` | 5 | 10% |\n| 4 | Relational Algebra | `05_Relational Algebra` | 4 | 8% |\n| 5 | SQL 🔥🔥 | `06_SQL`, `2_SQL`, `3_Advanced SQL`, `6_Exercise_SQL` | 9 | 18% |\n| 6 | FD & Normalization 🔥 | `07_FD`, `4_Normalization`, VoTien/Normalization | 6 | 12% |\n| 7 | Data Storage & Indexing | `08_DataStorage`, `5_Indexing`, VoTien/Storage | 4 | 8% |\n| 8 | Database Security | `6_DatabaseSecurity` | 3 | 6% |\n| 9 | Advanced Topics | `7_DATA WAREHOUSE`, `8_DistributedDatabase`, `9_NoSQL`, `11_Neo4j`, `12_data_anonymization` | 4 | 8% |\n| | **TỔNG** | | **50** | **100%** |\n\n> Đối chiếu QUIZ BK-LMS (`Final/Important/`): QUIZ 1→§1 · QUIZ 2,3→§2 · QUIZ 4→§3 · QUIZ 5→§4 · QUIZ 6,7→§5 · QUIZ 8,9→§6 · QUIZ 10→§7+§8. Đây là nguồn dự đoán sát nhất — **làm lại hết QUIZ 1–10 trước khi thi**.\n\n","file":"materials/DB-Final.md","section":21},{"id":"final-22","group":"final","kind":"source","title":"14.2. Chiến lược ôn 3 ngày","markdown":"## 14.2. Chiến lược ôn 3 ngày\n\n**Ngày 1 — Khối nặng (35/50 câu):**\n- §2 ERD & EERD (10) → §5 SQL (9) → §6 FD & Normalization (6). Làm lại QUIZ 2,3,6,7,8,9.\n- Mục tiêu: thuộc keyword EN + làm trôi worked example (closure `X⁺`, normalization, double NOT EXISTS, procedure/trigger).\n\n**Ngày 2 — Khối vừa + tính toán (18/50 câu):**\n- §1 Overview (5) → §3 Mapping (5) → §4 Relational Algebra (4) → §7 Storage & Indexing (4). Làm lại QUIZ 1,4,5,10.\n- Mục tiêu: thuộc 7+2 steps mapping; thuộc công thức `bfr`/`b`/index + làm trôi 1 bài Storage end-to-end.\n\n**Ngày 3 — Khối lý thuyết cuối + tổng ôn (7/50 câu + chốt):**\n- §8 Security (3) → §9 Advanced Topics (4). Học bảng keyword + bảng so sánh.\n- Tổng ôn: đọc **§10 Câu thần chú** 2 lượt + **§11 If-you-see-X**. In **§0 + §0bis + §11** mang vào phòng thi (open-book).\n\n","file":"materials/DB-Final.md","section":22},{"id":"final-23","group":"final","kind":"source","title":"14.3. Lời cuối","markdown":"## 14.3. Lời cuối\n\n- Đề **bắt keyword** → với mỗi định nghĩa, nhớ **cụm tiếng Anh nguyên văn** (đã bôi đậm `🔑 Keywords (EN)` xuyên suốt file) — đó là phần khớp đáp án.\n- Đề **open-book** nhưng 1.8 phút/câu → không có thời gian đọc từ đầu; phải đã **hiểu + tra nhanh**. File này thiết kế để Ctrl+F.\n- Câu tính: **tin công thức, không tin trí nhớ đáp án cũ**. Câu lý thuyết: **khớp keyword + loại đáp án tuyệt đối**.\n\n> 🎯 **Mục tiêu: ĐIỂM 10.** Bao phủ 100% slide lecture của môn, không lọc theo đề. Chúc thi tốt! 💪\n","file":"materials/DB-Final.md","section":23},{"id":"guide-final","group":"final","kind":"guide","title":"Ôn cuối kỳ: học chủ động, có sản phẩm sau mỗi buổi","markdown":"# Ôn cuối kỳ: học chủ động, có sản phẩm sau mỗi buổi\n\n> Trọng số 50 câu và hình thức open-book xuất hiện trong DB-Final.md do người dùng cung cấp. Project không có thông báo gốc của học kỳ hiện tại để kiểm chứng chúng. Lịch dưới là đề xuất học, không dự đoán chắc đề thi.\n\n## Chọn một trong ba nhịp học\n\n| Nhịp | Cách thực hiện | Khi hoàn thành phải có |\n|---|---|---|\n| 14 ngày | 1–2 giờ/ngày; mỗi 2 ngày một cụm nội dung | Sổ lỗi sai và toàn bộ lab cơ bản |\n| 7 ngày | 3–4 giờ/ngày; chia đọc–làm–chữa | Một miniworld được mapping và bộ SQL tự viết |\n| 3 ngày | Đã học trước; ưu tiên lỗ hổng qua đề chẩn đoán | Một tờ công thức có điều kiện áp dụng |\n\n## Lộ trình 14 ngày\n\n| Ngày | Học | Làm và tự kiểm tra |\n|---|---|---|\n| 1 | DBMS, schema/state, 3 tầng | Giải thích hai loại data independence bằng ví dụ riêng |\n| 2 | Entity, attribute, key | Phân tích miniworld anime, chưa viết SQL |\n| 3 | Cardinality, participation, weak entity | Vẽ Chen có chú giải đường đôi, partial key |\n| 4 | EER, category, shared subclass | Tự tạo ví dụ cho đủ 4 tổ hợp specialization |\n| 5 | Mapping, PK/FK, semantic constraints | Lập bảng “DDL enforce được / cần kiểm thêm” |\n| 6 | RA, set/bag, difference, division | Tính từng bảng trung gian, dịch ba câu sang SQL |\n| 7 | DDL, SELECT, NULL | Q01–Q10 và lab schema |\n| 8 | JOIN, grouping, subquery | Q11–Q20, kiểm thử LEFT JOIN và tập rỗng |\n| 9 | Set operations, CTE, window, view | Q21–Q40; phân biệt phần mở rộng thực hành |\n| 10 | FD, closure, keys, cover | Tính tay 3 bài trước khi mở công cụ |\n| 11 | 2NF/3NF/BCNF, lossless, preservation | Giải TEACH và phản ví dụ decomposition sai |\n| 12 | Storage, index, B+ tree | Tính cùng bộ số bằng tay và công cụ |\n| 13 | Security, advanced topics | Lab binding/rollback; đọc nguyên mục ở Final |\n| 14 | Luyện 50 câu và tổng sửa lỗi | Ghi vì sao mỗi đáp án sai, không chỉ lưu chữ cái |\n\n## Một buổi học nên đi như thế nào?\n\n1. Đọc mục tiêu và nhìn sơ đồ trước (5 phút).\n2. Đọc hướng dẫn bổ sung rồi mở phần tương ứng trong tài liệu đầy đủ (25–45 phút).\n3. Đóng đáp án và tự viết code/vẽ/tính (20–40 phút).\n4. Chạy hoặc kiểm bằng dữ liệu nhỏ, tìm một phản ví dụ (10–20 phút).\n5. Ghi lỗi bằng câu hoàn chỉnh: “Mình đặt điều kiện ở WHERE làm mất phòng rỗng”, thay vì chỉ ghi “sai JOIN”.\n\n## Bộ đề tự luận mẫu có lời giải định hướng\n\n**Câu 1 — ER/EER (20 điểm).** Thiết kế anime–genre–studio–episode–account–watch list. Ghi rõ assumptions; total/partial; overlapping/total; belongs-to và Contains.\n\n**Chấm:** 4đ entity/attribute/key; 4đ maximum; 4đ minimum; 4đ weak entity + ISA; 4đ ngữ nghĩa thuộc tính quan hệ. Đáp án đối chiếu nằm ở hướng dẫn chương 2–4 và capstone. Các giả thiết khác vẫn có thể hợp lệ nếu nêu rõ và nhất quán.\n\n**Câu 2 — Mapping (15 điểm).** Viết schema, PK/FK, xác định 3 constraint chưa tự bảo đảm.\n\n**Chấm:** 6đ bảng liên kết/weak entity; 4đ PK/FK; 5đ ít nhất một genre, total specialization, điều kiện nghiệp vụ liên bảng. Đối chiếu `sql/anime-schema.sql` và `tools/capstone.py`.\n\n**Câu 3 — SQL (25 điểm).** Giải Q07, Q16, Q18, Q19 và Q25; mỗi câu 5đ gồm query, giải thích NULL/tập rỗng và output đúng.\n\n**Câu 4 — FD (25 điểm).** Cho R(A,B,C), F={AB→C,C→B}. Tìm keys, NF, phân rã BCNF và nhận xét bảo toàn.\n\n**Lời giải:** keys AB và AC; mọi attribute prime; C→B có C không superkey nên 3NF nhưng không BCNF. Tách CB và AC: giao C, C→CB nên lossless. AB→C không kiểm riêng được từ projected FDs; không bảo toàn. Xem thêm hướng dẫn chương 7.\n\n**Câu 5 — Storage (15 điểm).** Với r=30.000, R=100, B=4096, key=8, pointer=8, unspanned, không header: tính bfr, b, sparse index, số mức và chi phí.\n\n**Lời giải:** 40; 750; 750 entry/3 index block ở mức đầu; 1 block mức trên; 2 mức index; 3 accesses gồm data. Không nhầm 750 entry với 750 index block.\n\n## Checklist cần mang theo khi tự kiểm tra\n\n- SQL: query đã xử lý hàng không match, NULL, trùng và tập rỗng chưa?\n- ER: maximum và minimum đã xét độc lập từng phía chưa?\n- FD: key có đủ và tối thiểu không? Prime xét mọi candidate key chưa?\n- NF: đang xét FD nontrivial và đúng projected FDs ở từng quan hệ con chưa?\n- Storage: đơn vị byte/record/block/access có được ghi ở từng dòng chưa?\n- Đề thi thực tế: đã xác nhận quy định và phạm vi từ giảng viên chưa?\n","file":"lessons/10-exam-roadmap.md"},{"id":"guide-advanced","group":"final","kind":"guide","title":"09 · Security, giao dịch và các chủ đề mở rộng","markdown":"# 09 · Security, giao dịch và các chủ đề mở rộng\n\n> Nguồn học chính: phần Security và Advanced Topics trong **DB-Final.md**. Các phần dưới bổ sung cách nối lý thuyết với ứng dụng; chúng không thay thế toàn bộ phần gốc.\n\n![Lựa chọn khi hai bản sao mất liên lạc](../docs/assets/cap.svg)\n\n## Bảo mật: xác thực, phân quyền và truy vết\n\n**Authentication** xác định bạn là ai; **authorization** quyết định bạn được làm gì; **auditing** ghi lại hành vi để có thể điều tra. Không đồng nhất đăng nhập thành công với được phép đọc mọi bảng.\n\nDAC dựa trên quyền được cấp bởi chủ thể có thẩm quyền; RBAC gom quyền theo role; ABAC xét thuộc tính subject/resource/context. Bell–LaPadula tập trung vào **confidentiality** với “no read up, no write down” trong mô hình mức bảo mật đơn giản. Nó không tự giải quyết integrity hay mọi luồng rò rỉ trong ứng dụng.\n\nVí dụ user `viewer` chỉ cần xem catalog và sửa watch list của mình, không cần quyền DDL. Trong SQLite lab không có GRANT/REVOKE theo user như server DBMS; ví dụ phân quyền SQL Server/PostgreSQL trong nguồn thuộc phần đọc lý thuyết.\n\n## SQL injection: parameter binding và giới hạn\n\n```python\n# Giá trị đầu vào được truyền riêng, không nối vào SQL.\nrow = con.execute('SELECT account_id FROM account WHERE username=?', (username,)).fetchone()\n```\n\nInput `an' OR 1=1 --` được hiểu như một chuỗi username, không trở thành biểu thức SQL. Binding không chọn hộ tên bảng an toàn, không thay thế phân quyền và không sửa được mọi lỗi nghiệp vụ. Xem script chạy được ở lab 05.\n\n## ACID qua một hành vi cụ thể\n\nChuyển 100 đơn vị từ A sang B gồm hai UPDATE trong cùng transaction. **Atomicity**: cả hai cùng thành công hoặc cùng rollback. **Consistency**: transaction và constraints giữ các bất biến nghiệp vụ. **Isolation**: tương tác giữa các transaction tuân theo mức cô lập đã chọn. **Durability**: commit tồn tại qua sự cố theo các bảo đảm lưu trữ/cấu hình của hệ.\n\nSQLite serialize các thao tác ghi theo cơ chế của nó; bản demo một connection chỉ minh họa commit/rollback, không chứng minh mọi isolation anomaly của hệ phân tán. `tools/transaction_demo.py` cố tình gây lỗi giữa hai UPDATE và kiểm tra tổng tiền được giữ.\n\n## CAP: viết điều kiện partition trước khi chọn C hay A\n\nHai replica A/B mất liên lạc. A nhận ghi “đặt ghế cuối”. B có thể từ chối/chờ để giữ consistency, hoặc tiếp tục trả lời theo trạng thái cục bộ và có nguy cơ lệch. **Khi có network partition**, không thể bảo đảm đồng thời linearizable consistency và availability theo định nghĩa của CAP cho mọi request ở các node không lỗi. Câu “chọn 2 trong 3” chỉ là ghi nhớ sơ lược, không phải ba nút tùy ý tắt mở.\n\nConsistency trong CAP khác chữ C trong ACID. BASE không phải chứng minh rằng hệ không có transaction. SQL/NoSQL cũng không quyết định một hệ luôn AP hay CP; phải xét operation, topology và cấu hình.\n\n## OLTP, OLAP và data warehouse\n\nOLTP xử lý thao tác nghiệp vụ ngắn như thêm watch list, đánh giá phim. OLAP phân tích nhiều hàng như tổng giờ xem theo tháng và thể loại. Star schema có fact ở một grain đã định nghĩa và các dimension; grain sai tạo double-count khi join.\n\nVí dụ fact `DailyAnimeViews(date_id,anime_id,view_count)` có một hàng mỗi ngày–anime. Nếu join với nhiều genre rồi SUM(view_count), anime có hai genre xuất hiện hai lần. Phải quyết định phân bổ số lượt cho các thể loại hay báo cáo theo grain nào, không sửa bằng DISTINCT một cách máy móc.\n\n## Distributed DB và 2PC\n\nFragmentation chia dữ liệu; replication sao chép. 2PC có pha prepare và quyết định commit/abort để các participant thống nhất kết quả transaction trong mô hình tương ứng. Đây không phải Two-Phase Locking, và không tự chứng minh serializability. Coordinator/participant gặp lỗi có thể làm các bên chờ trong giao thức cơ bản.\n\n## NoSQL, graph và quyền riêng tư\n\nKey–value hợp tra bằng khóa; document hợp aggregate dữ liệu theo tài liệu; wide-column phục vụ các access pattern được thiết kế; graph hợp truy vấn đường đi/quan hệ. Đây là định hướng mô hình, không phải bảng xếp hạng tốc độ chung.\n\nk-anonymity gom quasi-identifiers để mỗi nhóm có ít nhất k bản ghi theo mô hình đang xét. Nó không bảo đảm bí mật sensitive attribute nếu cả nhóm cùng một giá trị; l-diversity và t-closeness giải quyết các khía cạnh khác. Differential privacy đặt bảo đảm lên cơ chế công bố ngẫu nhiên, không đơn giản là “xóa tên rồi thêm noise bất kỳ”.\n\n## Bài tập thảo luận có đáp án\n\n1. “Đã dùng prepared statements nên user được SELECT mọi bảng cũng không sao.” Đúng không?\n2. Đếm view sau khi join anime–genre có thể tăng vì sao?\n3. Một node không liên lạc được phần còn lại nhưng vẫn phục vụ một số user có đủ chứng minh availability trong định nghĩa CAP không?\n\n<details><summary>Lời giải</summary>\n\n1. Sai. Injection prevention và least privilege xử lý các loại rủi ro khác nhau.\n2. Join M:N nhân một fact thành nhiều hàng; cần xác định grain và cách tổng hợp.\n3. Không. CAP availability xét mọi request hợp lệ tới node không lỗi theo định nghĩa, không chỉ “đa số user vẫn dùng được”.\n\n</details>\n","file":"lessons/09-security-advanced.md"},{"id":"editorial","group":"info","kind":"guide","title":"Ghi chú biên tập và nguồn đối chiếu","markdown":"# Ghi chú biên tập và nguồn đối chiếu\n\n## Phạm vi thực sự đã có trong project\n\nProject nhập nguyên vẹn 9 file Markdown người dùng cung cấp. SHA-256 trong `materials/manifest.json` cho phép so sánh từng byte. Các dẫn chiếu đến slide PDF, quiz BK-LMS, đề thi hoặc file trong `Lectures/`, `Final/Important/` thuộc lời dẫn của nguồn; **những file đó không nằm trong bộ upload**, nên project không thể xác minh nội dung của chúng.\n\nHướng dẫn mới ở `lessons/`, lab, fixture và đề tự luyện là phần biên soạn bổ sung. Không gọi chúng là đáp án chính thức HCMUT. Bản gốc có các lời khẳng định “full điểm”, “đủ điểm 10”; đó không phải cam kết của project.\n\nTrình đọc còn xuống dòng các attribute trong Mermaid ER viết gộp bằng dấu chấm phẩy để tương thích renderer; không đổi file nguồn. Mermaid ER dùng Crow's Foot, không phải ký hiệu Chen. Khi học cardinality/participation, ưu tiên câu nghiệp vụ và chú giải của từng hệ ký hiệu.\n\n## Những điểm cần đọc cùng chú giải\n\n| Vị trí hoặc cách ghi trong nguồn | Cách hiểu chính xác hơn |\n|---|---|\n| Chương 1 mở đầu `D#` | Lỗi ký tự; trình đọc sửa tiêu đề hiển thị, file gốc giữ nguyên |\n| Chương 6 có chỗ xếp COMMIT/ROLLBACK vào DCL | Ở hướng dẫn mới dùng TCL; các giáo trình có cách chia nhóm khác nhau |\n| CAP “3 chọn 2” | Trong partition, không bảo đảm đồng thời C và A theo định nghĩa CAP; xem nguồn [4] |\n| Full/direct dependency dùng như đồng nghĩa | Full là không tồn tại proper subset LHS vẫn xác định RHS; “direct” không thay thế định nghĩa này |\n| BCNF không nhắc nontrivial ở một số câu tóm tắt | Chỉ xét FD không tầm thường; A→A không bắt A phải là superkey |\n| “BCNF luôn lossless” | Thuật toán phân rã BCNF chuẩn bảo đảm lossless; tùy ý tách các bảng BCNF không đủ |\n| Total M:N → CHECK/assertion/trigger | CHECK thường chỉ kiểm tra hàng; SQLite không hỗ trợ subquery trong CHECK; cần cơ chế liên bảng và transaction phù hợp |\n| Secondary key là candidate key không chọn | Dùng “alternate key” khi muốn tránh nhầm với search key/secondary index |\n| WITH LOCAL CHECK OPTION bỏ mọi kiểm tra view cha | Với PostgreSQL, view cha có CHECK OPTION riêng vẫn có thể được enforce; xem [3] |\n| Công thức lưu trữ | Chỉ áp dụng sau khi ghi giả thiết về header, pointer, spanned, cache và occupancy |\n\nĐây là **các chú giải trọng yếu**, không phải chứng nhận rằng từng khẳng định, từng bài giải và mọi dẫn nguồn trong 9 file đã được kiểm chứng độc lập. Khi có mâu thuẫn, dùng định nghĩa hình thức, phản ví dụ và tài liệu DBMS đúng phiên bản.\n\n## Dialect thực hành\n\n| Tính năng | SQLite lab | Đọc thêm |\n|---|---|---|\n| FK | Bật PRAGMA foreign_keys trên từng connection | [1] |\n| CHECK và NULL | CHECK không thay thế NOT NULL | [2] |\n| GROUP BY | SQLite cho bare columns trong một số dạng; bài giải project tránh dựa vào chúng | [2] |\n| GRANT/REVOKE theo database role | Không mô phỏng bằng SQLite | PostgreSQL/SQL Server trong nguồn |\n| ANY/ALL subquery, ASSERTION | Không dùng như code SQLite chạy được | Đọc như SQL chuẩn/dialect tương ứng |\n| Updatable view/CHECK OPTION | Không cùng hành vi với PostgreSQL | [3] |\n| Procedure/cursor/T-SQL INSERTED, DELETED | Không thuộc SQLite fixture | Đọc theo SQL Server |\n| Window functions trong Q33–Q34 | Phần mở rộng thực hành; cần SQLite có hỗ trợ window | [2] |\n\n## Tài liệu chính thức được đối chiếu\n\n1. [SQLite Foreign Key Support](https://www.sqlite.org/foreignkeys.html)\n2. [SQLite SELECT](https://www.sqlite.org/lang_select.html), [CREATE TABLE](https://www.sqlite.org/lang_createtable.html), [Python sqlite3](https://docs.python.org/3/library/sqlite3.html)\n3. [PostgreSQL 18 CREATE VIEW](https://www.postgresql.org/docs/18/sql-createview.html)\n4. [FoundationDB — CAP theorem](https://apple.github.io/foundationdb/cap-theorem.html), [Gilbert & Lynch — Perspectives on the CAP theorem](https://dspace.mit.edu/entities/publication/dfcb6512-af44-4fc9-8e8b-1a8f28f1b53a)\n5. [Mermaid documentation](https://mermaid.js.org/intro/), [KaTeX documentation](https://katex.org/docs/api), [Marked](https://github.com/markedjs/marked)\n6. [GitHub Pages: publish from a branch](https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site)\n\nCác nội dung giải thích là biên soạn và diễn giải, không sao chép dài từ các nguồn web. Tham chiếu kỹ thuật được kiểm tra ngày 26/10/2026.\n","file":"lessons/11-corrections-and-sources.md"},{"id":"lab-1","group":"labs","kind":"guide","title":"Lab 01 · Khởi động và kiểm tra ràng buộc","markdown":"# Lab 01 · Khởi động và kiểm tra ràng buộc\n\n## Yêu cầu và cách chạy\n\nCài Python 3.10 trở lên có module sqlite3 (bản Python thông thường trên Windows/macOS/Linux có sẵn). Không cần pip, Node, Docker hoặc database server để chạy các lab. Trình đọc `docs/index.html` mở được ngay bằng trình duyệt và dùng tài nguyên đóng gói trong repo.\n\n```bash\npython tools/check.py\npython tools/lab.py --exercise Q01\npython tools/lab.py --database anime --query \"SELECT * FROM anime\"\n```\n\nNếu máy dùng lệnh `python3`, thay `python` bằng `python3`; trên Windows cũng có thể dùng `py`. Chạy từ thư mục gốc project sau khi giải nén.\n\n## Tự quan sát constraint\n\n```python\nimport sys\nsys.path.insert(0, 'tools')\nfrom common import connect_fixture\nimport sqlite3\ncon = connect_fixture('anime')\nprint(con.execute('PRAGMA foreign_keys').fetchone())  # (1,)\ntry:\n    con.execute('INSERT INTO rating VALUES(1,1,11)')\nexcept sqlite3.IntegrityError as exc:\n    print(type(exc).__name__)\ncon.rollback()\n```\n\nThử điểm 11 trên cặp `(viewer_id=1, anime_id=1)` còn có thể đụng PK trùng; để cô lập CHECK, thử cặp chưa tồn tại `(3,2,11)`. Kiểm tra từng constraint bằng một input chỉ vi phạm constraint đó. Đây là kỹ năng thiết kế phép thử, không chỉ là chạy đến khi có lỗi.\n\nCác phép thử nên làm: thêm PK trùng; FK không tồn tại; NULL ở cột NOT NULL; CHECK score ngoài 1..10. Dùng connection mới cho mỗi phép thử nếu không muốn ảnh hưởng state trước đó.\n\n## Fixture COMPANY có gì khác mẫu quen thuộc?\n\nCó 9 employee và 4 department. Ngoài các tên COMPANY quen thuộc, Mai chưa có salary và assignment; Innovation không có employee và manager. Những hàng này chủ ý giúp thử NULL, LEFT JOIN, anti join và empty set. Không dùng output fixture như đáp án cho một database có seed khác.\n","file":"labs/01-setup.md"},{"id":"lab-2","group":"labs","kind":"guide","title":"Lab 02 · Tự viết SQL trong một phiên giữ state","markdown":"# Lab 02 · Tự viết SQL trong một phiên giữ state\n\n## Mở Python REPL\n\nTừ thư mục gốc chạy `python`, rồi:\n\n```python\nimport sys\nsys.path.insert(0, 'tools')\nfrom common import connect_fixture, table\ncon = connect_fixture('company')\nprint(table(con.execute('SELECT Fname, Salary FROM EMPLOYEE ORDER BY Fname')))\n```\n\nSửa query trong cùng phiên REPL để đọc lại state sau UPDATE. CLI `tools/lab.py` chủ ý tạo fixture mới mỗi lần chạy, nên UPDATE của lần trước không tồn tại ở lần sau.\n\n## Một chu trình làm bài hoàn chỉnh\n\n1. Đọc đề Q07 mà chưa mở lời giải.\n2. Viết tay bảng đầu ra: Administration 4; Headquarters 1; Innovation 0; Research 4.\n3. Thử INNER JOIN, ghi lại phòng bị mất.\n4. Đổi LEFT JOIN nhưng dùng COUNT(*), quan sát Innovation thành 1.\n5. Đổi COUNT(e.Ssn) và giải thích vì sao NULL do outer join tạo ra bị bỏ.\n\n## Thử transaction\n\n```python\nold = con.execute(\"SELECT Salary FROM EMPLOYEE WHERE Ssn=?\", ('123456789',)).fetchone()\ntry:\n    with con:\n        con.execute(\"UPDATE EMPLOYEE SET Salary=Salary+100 WHERE Ssn=?\", ('123456789',))\n        raise RuntimeError('Dừng giữa giao dịch')\nexcept RuntimeError:\n    pass\nnew = con.execute(\"SELECT Salary FROM EMPLOYEE WHERE Ssn=?\", ('123456789',)).fetchone()\nassert old == new\ncon.close()\n```\n\nĐừng chỉ so số hàng trả về; kiểm tra giá trị và tính chất nghiệp vụ. `sql/practice.sql` là đề để tự điền; `sql/solutions.sql` là đáp án chạy được; `exercises.json` giữ cả expected rows và lý do.\n","file":"labs/02-sql.md"},{"id":"lab-3","group":"labs","kind":"guide","title":"40 bài SQL: tự làm → dự đoán → chạy → chữa","markdown":"# 40 bài SQL: tự làm → dự đoán → chạy → chữa\n\nTất cả dùng COMPANY fixture của project. Kết quả đầy đủ được kiểm bằng expected rows trong exercises.json. Q21 là bẫy cố ý; Q22 sửa nó.\n\n## Q01 · Tên các nhân viên thuộc Research, tăng dần theo Fname\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q01`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname FROM EMPLOYEE WHERE Dno=5 ORDER BY Fname;\n```\n\n```json\n[[\"Franklin\"], [\"John\"], [\"Joyce\"], [\"Ramesh\"]]\n```\n\nWHERE lọc hàng theo mã phòng; ORDER BY giúp kết quả đối chiếu được.\n\n</details>\n\n## Q02 · Nhân viên có lương ít nhất 40000\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q02`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname,Salary FROM EMPLOYEE WHERE Salary>=40000 ORDER BY Fname;\n```\n\n```json\n[[\"Franklin\", 40000], [\"James\", 55000], [\"Jennifer\", 43000]]\n```\n\nSo sánh >= giữ cả giá trị biên. Lương NULL không làm predicate TRUE.\n\n</details>\n\n## Q03 · Nhân viên chưa biết lương\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q03`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname FROM EMPLOYEE WHERE Salary IS NULL ORDER BY Fname;\n```\n\n```json\n[[\"Mai\"]]\n```\n\nIS NULL kiểm tra thiếu giá trị; = NULL không cho TRUE.\n\n</details>\n\n## Q04 · Mã phòng thực sự có nhân viên, không trùng\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q04`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT DISTINCT Dno FROM EMPLOYEE ORDER BY Dno;\n```\n\n```json\n[[1], [4], [5]]\n```\n\nDISTINCT loại trùng sau projection; phòng 9 không có employee.\n\n</details>\n\n## Q05 · Hai người có lương cao nhất trong những người biết lương\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q05`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname,Salary FROM EMPLOYEE WHERE Salary IS NOT NULL ORDER BY Salary DESC,Ssn LIMIT 2;\n```\n\n```json\n[[\"James\", 55000], [\"Jennifer\", 43000]]\n```\n\nLọc NULL trước; thêm Ssn để ổn định thứ tự khi bằng lương. LIMIT là dialect SQLite.\n\n</details>\n\n## Q06 · Tên phòng của John Smith\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q06`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname,d.Dname FROM EMPLOYEE e JOIN DEPARTMENT d ON d.Dnumber=e.Dno WHERE e.Ssn='123456789';\n```\n\n```json\n[[\"John\", \"Research\"]]\n```\n\nNối bằng FK/PK, không dựa vào NATURAL JOIN khi tên cột khác nhau.\n\n</details>\n\n## Q07 · Đếm nhân viên mỗi phòng, kể cả phòng rỗng\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q07`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT d.Dname,COUNT(e.Ssn) AS n FROM DEPARTMENT d LEFT JOIN EMPLOYEE e ON e.Dno=d.Dnumber GROUP BY d.Dnumber,d.Dname ORDER BY d.Dname;\n```\n\n```json\n[[\"Administration\", 4], [\"Headquarters\", 1], [\"Innovation\", 0], [\"Research\", 4]]\n```\n\nLEFT JOIN giữ phòng rỗng; COUNT(e.Ssn) bỏ NULL do outer join tạo ra. COUNT(*) sẽ cho Innovation=1.\n\n</details>\n\n## Q08 · Phòng chưa có nhân viên\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q08`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT d.Dname FROM DEPARTMENT d WHERE NOT EXISTS(SELECT 1 FROM EMPLOYEE e WHERE e.Dno=d.Dnumber) ORDER BY d.Dname;\n```\n\n```json\n[[\"Innovation\"]]\n```\n\nNOT EXISTS kiểm tra không tồn tại nhân viên tương ứng.\n\n</details>\n\n## Q09 · Tên nhân viên và supervisor, giữ cả người không có supervisor\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q09`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname,s.Fname AS Supervisor FROM EMPLOYEE e LEFT JOIN EMPLOYEE s ON s.Ssn=e.Super_ssn ORDER BY e.Fname;\n```\n\n```json\n[[\"Ahmad\", \"Jennifer\"], [\"Alicia\", \"Jennifer\"], [\"Franklin\", \"James\"], [\"James\", null], [\"Jennifer\", \"James\"], [\"John\", \"Franklin\"], [\"Joyce\", \"Franklin\"], [\"Mai\", \"Jennifer\"], [\"Ramesh\", \"Franklin\"]]\n```\n\nSelf join dùng hai alias cho hai role của cùng entity. James được giữ nhờ LEFT JOIN.\n\n</details>\n\n## Q10 · Nhân viên không có dependent\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q10`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM DEPENDENT d WHERE d.Essn=e.Ssn) ORDER BY e.Fname;\n```\n\n```json\n[[\"Ahmad\"], [\"Alicia\"], [\"James\"], [\"Joyce\"], [\"Mai\"], [\"Ramesh\"]]\n```\n\nKhông có là không tồn tại một hàng match, không phải tồn tại một hàng không match.\n\n</details>\n\n## Q11 · Tổng giờ đã biết của từng dự án\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q11`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT p.Pnumber,SUM(w.Hours) AS Total FROM PROJECT p LEFT JOIN WORKS_ON w ON w.Pno=p.Pnumber GROUP BY p.Pnumber ORDER BY p.Pnumber;\n```\n\n```json\n[[1, 52.5], [2, 37.5], [3, 50], [10, 55], [20, 25], [30, 55]]\n```\n\nSUM bỏ qua Hours NULL của James. Đây là tổng giờ đã biết, không khẳng định tổng thực tế đã đầy đủ.\n\n</details>\n\n## Q12 · Nhân viên làm ít nhất 3 dự án\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q12`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname,COUNT(*) AS n FROM EMPLOYEE e JOIN WORKS_ON w ON w.Essn=e.Ssn GROUP BY e.Ssn,e.Fname HAVING COUNT(*)>=3 ORDER BY e.Fname;\n```\n\n```json\n[[\"Franklin\", 4]]\n```\n\nHAVING lọc nhóm sau COUNT; PK Works_on tránh lặp cùng cặp nhân viên–dự án.\n\n</details>\n\n## Q13 · Lương từ 25000 đến 30000, gồm hai đầu mút\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q13`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname FROM EMPLOYEE WHERE Salary BETWEEN 25000 AND 30000 ORDER BY Fname;\n```\n\n```json\n[[\"Ahmad\"], [\"Alicia\"], [\"John\"], [\"Joyce\"]]\n```\n\nBETWEEN gồm cả hai đầu mút.\n\n</details>\n\n## Q14 · Tên bắt đầu bằng J\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q14`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname FROM EMPLOYEE WHERE Fname LIKE 'J%' ORDER BY Fname;\n```\n\n```json\n[[\"James\"], [\"Jennifer\"], [\"John\"], [\"Joyce\"]]\n```\n\nPhần trăm match dãy ký tự; underscore match một ký tự. Collation/case behavior phụ thuộc DBMS.\n\n</details>\n\n## Q15 · So sánh COUNT(*) và COUNT(Salary)\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q15`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT COUNT(*),COUNT(Salary) FROM EMPLOYEE;\n```\n\n```json\n[[9, 8]]\n```\n\nCOUNT(*) đếm mọi hàng, COUNT(column) chỉ đếm hàng có giá trị non-NULL.\n\n</details>\n\n## Q16 · Nhân viên lương cao hơn trung bình phòng mình\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q16`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE e.Salary>(SELECT AVG(x.Salary) FROM EMPLOYEE x WHERE x.Dno=e.Dno) ORDER BY e.Fname;\n```\n\n```json\n[[\"Franklin\"], [\"Jennifer\"], [\"Ramesh\"]]\n```\n\nSubquery phải tương quan qua Dno; AVG bỏ NULL, không so với trung bình toàn công ty.\n\n</details>\n\n## Q17 · Nhân viên làm ít nhất một dự án ở Houston\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q17`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT DISTINCT e.Fname FROM EMPLOYEE e JOIN WORKS_ON w ON w.Essn=e.Ssn JOIN PROJECT p ON p.Pnumber=w.Pno WHERE p.Plocation='Houston' ORDER BY e.Fname;\n```\n\n```json\n[[\"Franklin\"], [\"James\"], [\"Jennifer\"], [\"Ramesh\"]]\n```\n\nDISTINCT tránh một người xuất hiện nhiều lần nếu làm nhiều dự án ở Houston.\n\n</details>\n\n## Q18 · Nhân viên làm cả dự án 1 và 2\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q18`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=1) AND EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=2) ORDER BY e.Fname;\n```\n\n```json\n[[\"John\"], [\"Joyce\"]]\n```\n\nHai EXISTS xét hai hàng có thể khác nhau. Pno=1 AND Pno=2 trên cùng hàng không thể đúng.\n\n</details>\n\n## Q19 · Nhân viên không làm bất kỳ dự án nào ở Houston\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q19`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM WORKS_ON w JOIN PROJECT p ON p.Pnumber=w.Pno WHERE w.Essn=e.Ssn AND p.Plocation='Houston') ORDER BY e.Fname;\n```\n\n```json\n[[\"Ahmad\"], [\"Alicia\"], [\"John\"], [\"Joyce\"], [\"Mai\"]]\n```\n\nMai chưa làm dự án vẫn thỏa không có dự án ở Houston. Không thay bằng một dự án ngoài Houston.\n\n</details>\n\n## Q20 · Nhân viên chưa được phân công dự án\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q20`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn) ORDER BY e.Fname;\n```\n\n```json\n[[\"Mai\"]]\n```\n\nAnti join qua NOT EXISTS cho kết quả ổn định trước NULL ở các cột không liên quan.\n\n</details>\n\n## Q21 · Tìm nhân viên không quản lý ai bằng NOT IN chưa xử lý NULL\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q21`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname FROM EMPLOYEE WHERE Ssn NOT IN (SELECT Super_ssn FROM EMPLOYEE) ORDER BY Fname;\n```\n\n```json\n[]\n```\n\nĐây là query cố ý minh họa bẫy: subquery chứa NULL của James nên NOT IN không giữ hàng nào. Không dùng làm lời giải đúng nghiệp vụ.\n\n</details>\n\n## Q22 · Sửa Q21 bằng NOT EXISTS\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q22`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM EMPLOYEE x WHERE x.Super_ssn=e.Ssn) ORDER BY e.Fname;\n```\n\n```json\n[[\"Ahmad\"], [\"Alicia\"], [\"John\"], [\"Joyce\"], [\"Mai\"], [\"Ramesh\"]]\n```\n\nLoại từng người có ít nhất một cấp dưới; không bị NULL trong Super_ssn làm nhiễu.\n\n</details>\n\n## Q23 · Tên người thuộc phòng 1 hoặc 5 bằng UNION\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q23`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname FROM EMPLOYEE WHERE Dno=1 UNION SELECT Fname FROM EMPLOYEE WHERE Dno=5 ORDER BY Fname;\n```\n\n```json\n[[\"Franklin\"], [\"James\"], [\"John\"], [\"Joyce\"], [\"Ramesh\"]]\n```\n\nUNION loại dòng trùng; UNION ALL giữ bội số.\n\n</details>\n\n## Q24 · Mã nhân viên làm cả dự án 1 và 2 bằng INTERSECT\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q24`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Essn FROM WORKS_ON WHERE Pno=1 INTERSECT SELECT Essn FROM WORKS_ON WHERE Pno=2 ORDER BY Essn;\n```\n\n```json\n[[\"123456789\"], [\"453453453\"]]\n```\n\nINTERSECT lấy giao hai tập có cùng cấu trúc.\n\n</details>\n\n## Q25 · Nhân viên làm mọi dự án trong tập {1,2}\n\nMức: Nâng cao. Chạy `python tools/lab.py --exercise Q25`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM PROJECT p WHERE p.Pnumber IN (1,2) AND NOT EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=p.Pnumber)) ORDER BY e.Fname;\n```\n\n```json\n[[\"John\"], [\"Joyce\"]]\n```\n\nKhông tồn tại dự án yêu cầu mà nhân viên chưa làm. Đây là mẫu for all.\n\n</details>\n\n## Q26 · Mẫu for all khi tập dự án yêu cầu rỗng\n\nMức: Nâng cao. Chạy `python tools/lab.py --exercise Q26`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM PROJECT p WHERE p.Dnum=9 AND NOT EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=p.Pnumber)) ORDER BY e.Fname;\n```\n\n```json\n[[\"Ahmad\"], [\"Alicia\"], [\"Franklin\"], [\"James\"], [\"Jennifer\"], [\"John\"], [\"Joyce\"], [\"Mai\"], [\"Ramesh\"]]\n```\n\nTập yêu cầu rỗng không có phản ví dụ; mọi ứng viên EMPLOYEE đều thỏa.\n\n</details>\n\n## Q27 · Mỗi phòng và nhân viên có lương >40000; giữ phòng không match\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q27`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT d.Dname,e.Fname FROM DEPARTMENT d LEFT JOIN EMPLOYEE e ON e.Dno=d.Dnumber AND e.Salary>40000 ORDER BY d.Dname,e.Fname;\n```\n\n```json\n[[\"Administration\", \"Jennifer\"], [\"Headquarters\", \"James\"], [\"Innovation\", null], [\"Research\", null]]\n```\n\nĐiều kiện trong ON quyết định cặp match nhưng vẫn giữ mọi phòng.\n\n</details>\n\n## Q28 · So sánh Q27 khi điều kiện lương chuyển xuống WHERE\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q28`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT d.Dname,e.Fname FROM DEPARTMENT d LEFT JOIN EMPLOYEE e ON e.Dno=d.Dnumber WHERE e.Salary>40000 ORDER BY d.Dname,e.Fname;\n```\n\n```json\n[[\"Administration\", \"Jennifer\"], [\"Headquarters\", \"James\"]]\n```\n\nWHERE lọc các hàng NULL-extended; query này chỉ phù hợp nếu muốn bỏ phòng không match.\n\n</details>\n\n## Q29 · Phòng có ít nhất 4 nhân viên, bằng HAVING\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q29`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Dno,COUNT(*) FROM EMPLOYEE GROUP BY Dno HAVING COUNT(*)>=4 ORDER BY Dno;\n```\n\n```json\n[[4, 4], [5, 4]]\n```\n\nWHERE không thể lọc trực tiếp COUNT của nhóm trước khi nhóm được tạo.\n\n</details>\n\n## Q30 · Dự án có ít nhất hai người tham gia\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q30`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Pno,COUNT(*) FROM WORKS_ON GROUP BY Pno HAVING COUNT(*)>=2 ORDER BY Pno;\n```\n\n```json\n[[1, 2], [2, 3], [3, 2], [10, 3], [20, 3], [30, 3]]\n```\n\nĐếm hàng phân công, kể cả hàng Hours NULL; đó là người tham gia chứ không phải số giờ.\n\n</details>\n\n## Q31 · Nhân viên có lương cao nhất trong từng phòng, giữ đồng hạng\n\nMức: Nâng cao. Chạy `python tools/lab.py --exercise Q31`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname FROM EMPLOYEE e WHERE e.Salary=(SELECT MAX(x.Salary) FROM EMPLOYEE x WHERE x.Dno=e.Dno) ORDER BY e.Fname;\n```\n\n```json\n[[\"Franklin\"], [\"James\"], [\"Jennifer\"]]\n```\n\nMAX bỏ NULL. So sánh bằng MAX giữ mọi hàng đồng hạng nếu dữ liệu có tie.\n\n</details>\n\n## Q32 · Phân loại lương: Unknown / High (>=40000) / Other\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q32`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT CASE WHEN Salary IS NULL THEN 'Unknown' WHEN Salary>=40000 THEN 'High' ELSE 'Other' END AS Band,COUNT(*) FROM EMPLOYEE GROUP BY CASE WHEN Salary IS NULL THEN 'Unknown' WHEN Salary>=40000 THEN 'High' ELSE 'Other' END ORDER BY Band;\n```\n\n```json\n[[\"High\", 3], [\"Other\", 5], [\"Unknown\", 1]]\n```\n\nCASE kiểm tra NULL riêng trước khi phân nhóm; không coi Unknown là Other.\n\n</details>\n\n## Q33 · Dense rank lương ở phòng 5, phần mở rộng window function\n\nMức: Nâng cao. Chạy `python tools/lab.py --exercise Q33`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname,DENSE_RANK() OVER(ORDER BY Salary DESC) AS SalaryRank FROM EMPLOYEE WHERE Dno=5 ORDER BY SalaryRank,Fname;\n```\n\n```json\n[[\"Franklin\", 1], [\"Ramesh\", 2], [\"John\", 3], [\"Joyce\", 4]]\n```\n\nWindow không gom mất từng hàng như GROUP BY; DENSE_RANK không để khoảng trống khi có tie.\n\n</details>\n\n## Q34 · Lương và trung bình phòng bằng window, không làm mất hàng\n\nMức: Nâng cao. Chạy `python tools/lab.py --exercise Q34`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Fname,AVG(Salary) OVER(PARTITION BY Dno) AS DeptAverage FROM EMPLOYEE WHERE Dno=5 ORDER BY Fname;\n```\n\n```json\n[[\"Franklin\", 33250], [\"John\", 33250], [\"Joyce\", 33250], [\"Ramesh\", 33250]]\n```\n\nPARTITION BY chia cửa sổ; WHERE Dno=5 vẫn giữ trọn phòng 5 trong ví dụ này.\n\n</details>\n\n## Q35 · CTE tính tổng giờ đã biết rồi lọc >=40\n\nMức: Nâng cao. Chạy `python tools/lab.py --exercise Q35`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nWITH T AS(SELECT Essn,SUM(Hours) AS h FROM WORKS_ON GROUP BY Essn) SELECT e.Fname,T.h FROM EMPLOYEE e JOIN T ON T.Essn=e.Ssn WHERE T.h>=40 ORDER BY e.Fname;\n```\n\n```json\n[[\"Ahmad\", 40], [\"Alicia\", 40], [\"Franklin\", 40], [\"John\", 40], [\"Joyce\", 40], [\"Ramesh\", 40]]\n```\n\nCTE đặt tên cho bước trung gian; không khẳng định nó luôn được materialize.\n\n</details>\n\n## Q36 · Nhân viên có trên 2 dependent\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q36`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT e.Fname,COUNT(*) FROM EMPLOYEE e JOIN DEPENDENT d ON d.Essn=e.Ssn GROUP BY e.Ssn,e.Fname HAVING COUNT(*)>2 ORDER BY e.Fname;\n```\n\n```json\n[[\"Franklin\", 3], [\"John\", 3]]\n```\n\nJoin trước và GROUP BY đúng khóa nhân viên; không gộp những người trùng tên.\n\n</details>\n\n## Q37 · Bộ tên/địa điểm dự án của phòng 5\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q37`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Pname,Plocation FROM PROJECT WHERE Dnum=5 ORDER BY Pnumber;\n```\n\n```json\n[[\"ProductX\", \"Bellaire\"], [\"ProductY\", \"Sugarland\"], [\"ProductZ\", \"Houston\"]]\n```\n\nProjection chọn hai cột, selection lọc phòng. SQL ORDER BY có thể dùng cột không nằm SELECT trong dạng này.\n\n</details>\n\n## Q38 · Bình quân lương đã biết toàn công ty\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q38`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT ROUND(AVG(Salary),2) FROM EMPLOYEE;\n```\n\n```json\n[[35125]]\n```\n\nTổng lương 281000 chia 8 giá trị đã biết, không chia 9.\n\n</details>\n\n## Q39 · Danh sách SSN không có WORKS_ON bằng EXCEPT\n\nMức: Trung bình. Chạy `python tools/lab.py --exercise Q39`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT Ssn FROM EMPLOYEE EXCEPT SELECT Essn FROM WORKS_ON ORDER BY Ssn;\n```\n\n```json\n[[\"111222333\"]]\n```\n\nEXCEPT biểu diễn hiệu hai tập cùng một cột SSN.\n\n</details>\n\n## Q40 · Tổng số phòng và số phòng có manager\n\nMức: Cơ bản. Chạy `python tools/lab.py --exercise Q40`.\n\n<details><summary>SQL, kết quả và giải thích</summary>\n\n```sql\nSELECT COUNT(*),COUNT(Mgr_ssn) FROM DEPARTMENT;\n```\n\n```json\n[[4, 3]]\n```\n\nCOUNT(column) bỏ NULL; Innovation có manager chưa được gán. Đây là giả thiết fixture, không phải yêu cầu COMPANY chính thức.\n\n</details>\n","file":"labs/03-exercises.md"},{"id":"lab-4","group":"labs","kind":"guide","title":"Lab 04 · Tính tay rồi đối chiếu thuật toán","markdown":"# Lab 04 · Tính tay rồi đối chiếu thuật toán\n\n## Bao đóng và candidate keys\n\n```bash\npython tools/fd.py --attrs A,B,C,D,E --fds \"A->B,C;B->D;C,D->E\" --start A\npython tools/fd.py --attrs A,B,C --fds \"A->B;B->A\" --start C\n```\n\nTên thuộc tính phân cách bằng dấu phẩy: `StudentID,CourseID`, không viết dính thành `StudentIDCourseID`. FD phân cách bằng dấu chấm phẩy; đặt toàn chuỗi trong dấu nháy để shell không hiểu `;` là tách lệnh. Bản CLI và công cụ trong trình đọc giới hạn 12 thuộc tính vì tìm mọi candidate key có chi phí tăng theo tổ hợp.\n\nThử thứ tự FD ngược: `B->C;A->B`. Với start A, thuật toán phải lặp thêm vòng để suy C; không dừng sau một lần quét.\n\n## Minimal cover\n\nThử F=`A->B,C;B->C;A,B->C`. Một kết quả tối giản tương đương là A→B, B→C. Tự kiểm: mọi FD gốc suy được từ cover và mọi FD cover suy được từ F. Hai cover tương đương không nhất thiết có cùng biểu diễn.\n\n## Storage\n\n```bash\npython tools/storage.py\npython tools/storage.py --records 10001 --record-bytes 120 --block-bytes 4096 --overhead 8\n```\n\nTrước khi chạy, viết riêng: hữu dụng mỗi block, bfr, data blocks, entry size, index capacity, từng mức index, tổng accesses. Công cụ chỉ mô hình hóa **unspanned + sparse primary multilevel index**; không tự giải mọi biến thể đề storage.\n\n## Tiêu chí hoàn thành\n\nGiải thích được từng dòng trace closure; chứng minh key là tối thiểu; kiểm một output có phép chia không nguyên; từ chối bộ số R lớn hơn block; nêu rõ giả thiết cache. Kết quả âm hoặc fan-out 1 phải báo input không hợp lệ, không được rơi vào vòng lặp vô hạn.\n","file":"labs/04-fd-storage.md"},{"id":"lab-5","group":"labs","kind":"guide","title":"Lab 05 · Giao dịch, index và parameter binding","markdown":"# Lab 05 · Giao dịch, index và parameter binding\n\n## Rollback và commit\n\n```bash\npython tools/transaction_demo.py\n```\n\nTrước: (1,1000), (2,500). Sau lỗi giữa giao dịch: giữ nguyên. Sau giao dịch thành công: (1,900), (2,600). Tổng tiền 1500 được giữ. Demo cố ý dùng số nguyên để không đưa sai số floating point vào bài toán tiền.\n\n## Query plan trước/sau index\n\n```bash\npython tools/index_demo.py\n```\n\nDữ liệu có 20.000 events, 1000 anime_id. Script tìm anime 137, kiểm chính xác 20 ID kỳ vọng và in plan trước/sau index. Thời gian chỉ là quan sát một lần chạy; plan được optimizer chọn tùy DBMS, dữ liệu và phiên bản. Không kết luận mọi CREATE INDEX đều làm mọi query nhanh hơn.\n\n## Thử chuỗi giống SQL injection như dữ liệu\n\n```python\nimport sys\nsys.path.insert(0, 'tools')\nfrom common import connect_fixture\ncon = connect_fixture('anime')\nfor username in ['an', \"an' OR 1=1 --\"]:\n    rows = con.execute('SELECT account_id FROM account WHERE username=?', (username,)).fetchall()\n    print(username, rows)\ncon.close()\n```\n\nKết quả: username `an` trả [(1,)]; chuỗi còn lại trả []. Không cần dựng query dễ bị tấn công để kiểm chứng cách binding giữ input như một giá trị. Đừng áp dụng placeholder cho tên cột; dùng whitelist nếu người dùng được chọn trường sắp xếp.\n","file":"labs/05-security.md"},{"id":"lab-6","group":"labs","kind":"guide","title":"Lab 06 · Capstone Anime Streaming","markdown":"# Lab 06 · Capstone Anime Streaming\n\n![Lược đồ thực hành](../docs/assets/schema.svg)\n\n## Phạm vi\n\nĐây là miniworld học tập độc lập lấy cảm hứng từ chủ đề BTL của bạn, **không phải bản thay thế EERD cuối cùng của nhóm**. Account có thể vừa viewer vừa content admin; anime có genre và studio qua M:N; episode yếu theo anime; watch list chứa nhiều anime và lưu AddedAt tại Contains.\n\n| Thực thể/quan hệ | Bảng | Điều cần chú ý |\n|---|---|---|\n| Account, Viewer, Admin | account, viewer, content_admin | Total + overlapping theo giả thiết lab |\n| Anime, Genre, Has_genre | anime, genre, anime_genre | Anime phải có ít nhất một genre |\n| Studio, Produced_by | studio, produced_by | Bảng liên kết cho M:N |\n| Episode | episode | PK (anime_id, episode_no) |\n| Watch list, Contains | watch_list, contains | AddedAt thuộc quan hệ Contains |\n| Rating | rating | Một viewer đánh giá một anime tối đa một hàng; score 1..10 |\n\n## Chạy luồng có validation\n\n```bash\npython tools/capstone.py\n```\n\nHàm add_anime mở transaction, thêm anime, thêm genre liên kết, kiểm invariants rồi commit. Nếu genre rỗng, hàm ném ValueError và transaction rollback. Đây là **validation ở tầng service**; người chạy raw SQL ngoài hàm vẫn có thể tạo state vi phạm. Xóa liên kết genre cuối cùng cũng phải đi qua một transaction có kiểm tra tương tự trong sản phẩm hoàn chỉnh.\n\n## Năm truy vấn tự luyện và output\n\n```sql\n-- 1. Anime có nhiều hơn một genre: Sky Academy, Orbit City.\nSELECT a.title,COUNT(*) AS genres FROM anime a\nJOIN anime_genre ag ON ag.anime_id=a.anime_id\nGROUP BY a.anime_id,a.title HAVING COUNT(*)>1 ORDER BY a.anime_id;\n\n-- 2. Anime chưa có rating: Paper Moon.\nSELECT title FROM anime a WHERE NOT EXISTS(\n SELECT 1 FROM rating r WHERE r.anime_id=a.anime_id\n) ORDER BY anime_id;\n\n-- 3. Score trung bình: Sky Academy=9, Quiet Garden=8, Orbit City=9.\nSELECT a.title,AVG(r.score) AS avg_score FROM anime a\nJOIN rating r ON r.anime_id=a.anime_id\nGROUP BY a.anime_id,a.title ORDER BY a.anime_id;\n\n-- 4. Account thuộc cả hai subclass: chi.\nSELECT a.username FROM account a\nJOIN viewer v ON v.account_id=a.account_id\nJOIN content_admin c ON c.account_id=a.account_id ORDER BY a.account_id;\n\n-- 5. List Weekend và thứ tự thêm: Sky Academy, Quiet Garden.\nSELECT a.title,c.added_at FROM watch_list w\nJOIN contains c ON c.list_id=w.list_id JOIN anime a ON a.anime_id=c.anime_id\nWHERE w.list_id=1 ORDER BY c.added_at,c.anime_id;\n```\n\n## Bài phát triển tiếp có tiêu chí chấm\n\n1. Thêm lịch sử xem theo viewer–episode, định nghĩa rõ một lần xem hay trạng thái xem hiện tại (2đ).\n2. Viết query progress theo anime và tránh nhân số dòng khi join genre (2đ).\n3. Chứng minh hai PK ghép phù hợp nghiệp vụ (2đ).\n4. Kiểm soát xóa genre cuối và account mất role cuối trong transaction (2đ).\n5. Tạo dữ liệu biên: anime chưa được rating, watch list rỗng, viewer kiêm admin (2đ).\n\nĐây là bài mở; một sản phẩm tốt phải nêu assumptions và kiểm invariants, không chỉ có đủ CREATE TABLE.\n","file":"labs/06-anime-capstone.md"},{"id":"lab-7","group":"labs","kind":"guide","title":"50 câu tự luyện có giải thích","markdown":"# 50 câu tự luyện có giải thích\n\nĐề biên soạn bổ sung theo các nhóm kiến thức của tài liệu. Không phải đề thi hoặc đáp án chính thức.\n\n## M01 · Schema khác state ở điểm nào?\n\n- **A.** Schema là bản backup; state là chương trình\n- **B.** Schema thay đổi sau mỗi SELECT\n- **C.** Hai khái niệm đồng nghĩa\n- **D.** Schema mô tả cấu trúc; state là dữ liệu tại một thời điểm\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** INSERT đổi state mà không bắt buộc đổi schema. CREATE/ALTER thường tác động schema.\n\n</details>\n\n## M02 · Thêm index nhưng ứng dụng vẫn dùng nguyên SQL minh họa điều gì?\n\n- **A.** Logical independence\n- **B.** Physical independence\n- **C.** Total participation\n- **D.** Entity integrity\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Index là đường truy cập ở mức vật lý; interface logic có thể giữ nguyên.\n\n</details>\n\n## M03 · Metadata là ví dụ nào?\n\n- **A.** Ảnh đại diện người dùng\n- **B.** Lương của John\n- **C.** Danh sách tên cột và kiểu dữ liệu\n- **D.** Một dòng đặt vé\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** Metadata mô tả cấu trúc và quy tắc của dữ liệu, thường trong catalog.\n\n</details>\n\n## M04 · Hai ứng dụng cùng ghi đè số chỗ trống gây vấn đề chính nào?\n\n- **A.** Specialization\n- **B.** Minimal cover\n- **C.** Projection\n- **D.** Concurrency\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Các thao tác đồng thời cần cơ chế transaction/isolation để tránh mất cập nhật hoặc vi phạm bất biến.\n\n</details>\n\n## M05 · Ba-schema architecture là gì?\n\n- **A.** External, conceptual, internal\n- **B.** RAM, CPU, SSD\n- **C.** DDL, DML, DCL\n- **D.** Frontend, API, database server\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Đây là ba mức mô tả dữ liệu, không phải ba tầng triển khai ứng dụng.\n\n</details>\n\n## M06 · Cardinality và participation lần lượt nói về điều gì?\n\n- **A.** Minimum và kiểu dữ liệu\n- **B.** Maximum và yêu cầu tham gia tối thiểu\n- **C.** Số cột và số hàng hiện tại\n- **D.** Tên khóa và index\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** 1:N/M:N không cho biết phía nào bắt buộc phải có ít nhất một liên kết.\n\n</details>\n\n## M07 · Trong Chen, đường đôi từ ANIME tới Has_genre biểu diễn gì?\n\n- **A.** Quan hệ 1:1\n- **B.** Anime có đúng hai genre\n- **C.** ANIME total participation\n- **D.** GENRE là weak entity\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** Mọi anime phải tham gia ít nhất một instance quan hệ; không suy ra tối đa là bao nhiêu.\n\n</details>\n\n## M08 · AddedAt khi thêm anime vào watch list nên gắn với gì?\n\n- **A.** Contains giữa list và anime\n- **B.** Tên studio\n- **C.** ANIME\n- **D.** GENRE\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Giá trị phụ thuộc vào cặp list–anime, không chỉ một entity riêng lẻ.\n\n</details>\n\n## M09 · Điều gì đặc trưng cho thực thể yếu?\n\n- **A.** Cần khóa owner cộng partial key để định danh\n- **B.** Bất cứ entity nào có FK\n- **C.** Không có thuộc tính\n- **D.** Luôn có ít hơn 10 hàng\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Sự phụ thuộc định danh là cốt lõi; nhiều entity mạnh cũng có FK sau mapping.\n\n</details>\n\n## M10 · EpisodeNo chỉ duy nhất trong cùng anime. Khóa tự nhiên phù hợp là gì?\n\n- **A.** EpisodeNo\n- **B.** Title\n- **C.** AnimeID + EpisodeNo\n- **D.** Duration\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** Hai anime có thể cùng tập số 1 nên EpisodeNo riêng không đủ định danh.\n\n</details>\n\n## M11 · Biết nhân viên và dự án cùng thuộc một phòng có đủ xác định ai làm dự án nào?\n\n- **A.** Đủ nếu cả hai FK NOT NULL\n- **B.** Luôn đủ\n- **C.** Chỉ khi phòng có tên\n- **D.** Không; cần quan hệ phân công hoặc constraint tương ứng\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Cùng phòng không đồng nghĩa phân công; suy diễn qua đường nối có thể tạo fan trap.\n\n</details>\n\n## M12 · Overlapping specialization cho phép điều gì?\n\n- **A.** Không entity nào có subclass\n- **B.** Subclass không kế thừa khóa\n- **C.** Một entity thuộc nhiều subclass trong specialization\n- **D.** Mọi entity phải thuộc mọi subclass\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** Cho phép giao giữa các subclass; không bắt buộc giao luôn khác rỗng trong mọi state.\n\n</details>\n\n## M13 · Total specialization tương ứng với điều kiện nào?\n\n- **A.** Hợp các subclass bằng superclass\n- **B.** Mọi subclass đều có ít nhất một hàng\n- **C.** Superclass không có khóa\n- **D.** Giao subclass rỗng\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Total yêu cầu bao phủ mọi entity của superclass, không yêu cầu mỗi subclass không rỗng.\n\n</details>\n\n## M14 · Shared subclass và category khác nhau ở phép tập hợp nào?\n\n- **A.** Cả hai luôn là hợp\n- **B.** Shared subclass là subset của giao; category là subset của hợp\n- **C.** Shared subclass là hiệu\n- **D.** Category là tích Descartes\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Teaching assistant thuộc student và employee; owner có thể là person hoặc company.\n\n</details>\n\n## M15 · Superclass + hai bảng subclass PK/FK mặc định có enforce total không?\n\n- **A.** Chỉ cần UNIQUE trên tên\n- **B.** Có, vì có FK\n- **C.** Có, vì subclass có PK\n- **D.** Không; superclass có thể chưa có hàng con\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** FK đảm bảo con có cha, không đảm bảo mọi cha có ít nhất một loại con.\n\n</details>\n\n## M16 · Mapping quan hệ 1:N thường đặt FK ở đâu?\n\n- **A.** Cả hai phía bắt buộc\n- **B.** Không cần FK\n- **C.** Phía N\n- **D.** Luôn phía 1\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** Mỗi hàng phía N có thể giữ khóa của một owner phía 1; tránh cột lặp ở phía 1.\n\n</details>\n\n## M17 · Mapping 1:1 bằng FK còn cần gì để chặn nhiều hàng trỏ cùng cha?\n\n- **A.** UNIQUE trên FK\n- **B.** ORDER BY\n- **C.** DEFAULT 0\n- **D.** SUM\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** FK chỉ kiểm tra tồn tại cha; UNIQUE giới hạn tối đa một hàng tham chiếu cùng khóa cha.\n\n</details>\n\n## M18 · M:N Produced_by nên được ánh xạ thế nào?\n\n- **A.** Một StudioID duy nhất trong ANIME\n- **B.** Một bảng liên kết chứa cả hai khóa\n- **C.** Một chuỗi chứa mọi studio trong một ô\n- **D.** Không thể mapping\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Bảng liên kết cho phép nhiều studio trên anime và nhiều anime trên studio.\n\n</details>\n\n## M19 · Superkey khác candidate key thế nào?\n\n- **A.** Hai khái niệm hoàn toàn khác\n- **B.** Candidate key là superkey tối thiểu theo bao hàm\n- **C.** Superkey luôn chỉ có một thuộc tính\n- **D.** Candidate key được phép trùng\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Thêm thuộc tính vào candidate key vẫn tạo superkey nhưng thường không còn tối thiểu.\n\n</details>\n\n## M20 · FK NOT NULL từ anime_genre tới anime đã đảm bảo mọi anime có genre chưa?\n\n- **A.** Chỉ cần thêm PK anime\n- **B.** Thêm CHECK anime_id>0 là đủ\n- **C.** Đã đủ\n- **D.** Chưa; anime có thể chưa được tham chiếu\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Constraint chỉ buộc mỗi hàng liên kết có cha; cần điều kiện tồn tại theo chiều ngược lại.\n\n</details>\n\n## M21 · Projection trong RA cổ điển xử lý dòng trùng thế nào?\n\n- **A.** Loại tuple trùng\n- **B.** Nhân đôi tuple\n- **C.** Chỉ giữ dòng đầu theo thứ tự\n- **D.** Giữ mọi dòng như SQL mặc định\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** RA dùng set semantics; SQL thường cần DISTINCT để có hành vi tương ứng.\n\n</details>\n\n## M22 · Natural join chọn cột nối dựa trên gì?\n\n- **A.** FK metadata\n- **B.** Tên cột trùng\n- **C.** Cột đầu tiên mỗi bảng\n- **D.** Mọi cột kiểu số\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Dno và Dnumber không tự match chỉ vì chúng có quan hệ FK.\n\n</details>\n\n## M23 · Từ “mọi / tất cả” thường gợi ý mẫu nào?\n\n- **A.** LEFT JOIN luôn đủ\n- **B.** Một điều kiện = duy nhất\n- **C.** Division hoặc không tồn tại phản ví dụ\n- **D.** ORDER BY\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** For all x, P(x) tương đương không tồn tại x sao cho không P(x).\n\n</details>\n\n## M24 · Union hai quan hệ đòi hỏi gì?\n\n- **A.** Cùng primary key tên giống nhau\n- **B.** Cùng số index\n- **C.** Cùng số tuple\n- **D.** Union-compatible về số cột và miền tương ứng\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Hai tập phải có cấu trúc tương thích; không cần có cùng số hàng.\n\n</details>\n\n## M25 · WHERE giữ các hàng có predicate nào?\n\n- **A.** FALSE\n- **B.** UNKNOWN\n- **C.** TRUE và UNKNOWN\n- **D.** TRUE\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Trong SQL ba-valued logic, WHERE chỉ giữ TRUE.\n\n</details>\n\n## M26 · Cách kiểm tra Salary thiếu giá trị là gì?\n\n- **A.** Salary = NULL\n- **B.** Salary IS NULL\n- **C.** Salary = 0\n- **D.** Salary = empty\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** = NULL cho UNKNOWN; IS NULL là phép kiểm tra thiếu giá trị.\n\n</details>\n\n## M27 · COUNT(*) khác COUNT(Salary) khi có NULL thế nào?\n\n- **A.** COUNT(Salary) cộng lương\n- **B.** COUNT(*) bỏ NULL\n- **C.** COUNT(Salary) bỏ hàng có Salary NULL\n- **D.** Cả hai luôn bằng nhau\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** COUNT(*) đếm hàng; COUNT(expression) đếm biểu thức non-NULL.\n\n</details>\n\n## M28 · Sau LEFT JOIN, WHERE trên cột bên phải có thể gây gì?\n\n- **A.** Tự biến thành FULL JOIN\n- **B.** Tự enforce FK\n- **C.** Luôn giữ mọi hàng trái\n- **D.** Loại các hàng NULL-extended\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Predicate thông thường như e.Salary>40000 cho UNKNOWN ở hàng không match và hàng đó bị loại.\n\n</details>\n\n## M29 · Lọc nhóm có COUNT>=4 nên đặt ở đâu?\n\n- **A.** HAVING COUNT(*)>=4\n- **B.** ORDER BY COUNT(*)>=4\n- **C.** PRIMARY KEY\n- **D.** WHERE COUNT(*)>=4\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** HAVING lọc nhóm sau aggregation trong thứ tự xử lý logic.\n\n</details>\n\n## M30 · NOT IN có NULL trong tập con có thể làm gì?\n\n- **A.** Luôn coi NULL là 0\n- **B.** Không cho TRUE đối với các giá trị không match còn lại\n- **C.** Luôn trả tất cả hàng\n- **D.** Tự bỏ NULL\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Với x không bằng giá trị đã biết nào, so với NULL vẫn UNKNOWN; dùng NOT EXISTS cho anti join phù hợp.\n\n</details>\n\n## M31 · Double NOT EXISTS với tập yêu cầu rỗng trả gì trong mẫu lấy ứng viên từ EMPLOYEE?\n\n- **A.** Lỗi SQL\n- **B.** Không ai\n- **C.** Mọi ứng viên EMPLOYEE\n- **D.** Chỉ nhân viên có dự án\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** Không tồn tại phản ví dụ trong tập rỗng: vacuous truth.\n\n</details>\n\n## M32 · Prepared statement placeholder dùng trực tiếp để thay gì?\n\n- **A.** Giá trị tham số\n- **B.** Từ khóa SELECT\n- **C.** Tên bảng tùy ý\n- **D.** Tên cột tùy ý\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Parameter binding tách giá trị khỏi cú pháp. Identifier động cần whitelist/cơ chế quoting phù hợp.\n\n</details>\n\n## M33 · View thông thường có nhất thiết lưu một bản sao vật lý kết quả không?\n\n- **A.** Không; khác materialized view\n- **B.** Chỉ khi có WHERE\n- **C.** Chỉ khi có JOIN\n- **D.** Có\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** View thường đặt tên cho query; materialized view là khái niệm khác, tùy DBMS.\n\n</details>\n\n## M34 · FD A→B có nghĩa gì?\n\n- **A.** A nhỏ hơn B\n- **B.** Hai tuple cùng A phải cùng B trong mọi state hợp lệ\n- **C.** B luôn là primary key\n- **D.** A và B cùng kiểu\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** FD là ràng buộc của schema/miniworld, không chỉ một mẫu tình cờ trong dữ liệu hiện có.\n\n</details>\n\n## M35 · R(A,B,C), F={A→B,B→C}; A+ là gì?\n\n- **A.** BC\n- **B.** A\n- **C.** AB\n- **D.** ABC\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Khởi tạo A; A→B thêm B; B→C thêm C; dừng khi không đổi.\n\n</details>\n\n## M36 · R(A,B,C), F={A→B,B→A}; candidate keys là gì?\n\n- **A.** Chỉ ABC\n- **B.** C\n- **C.** A và B\n- **D.** AC và BC\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** C không xuất hiện RHS nên bắt buộc thuộc key. AC và BC xác định toàn R, bỏ bất cứ thành phần nào đều không đủ.\n\n</details>\n\n## M37 · Prime attribute là gì?\n\n- **A.** Nằm trong ít nhất một candidate key\n- **B.** Có giá trị là số nguyên tố\n- **C.** Nằm trong mọi candidate key\n- **D.** Chỉ nằm trong primary key được chọn\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Phải tìm đủ candidate keys trước khi đánh dấu prime để kiểm 3NF.\n\n</details>\n\n## M38 · FD nontrivial X→a thỏa 3NF khi nào?\n\n- **A.** X superkey hoặc a prime\n- **B.** X phải candidate key đúng bằng PK\n- **C.** a phải nonprime\n- **D.** X luôn một thuộc tính\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** BCNF chỉ giữ nhánh X là superkey; 3NF cho phép RHS prime.\n\n</details>\n\n## M39 · R tách thành R1 và R2. Điều kiện lossless binary theo FD là gì?\n\n- **A.** Mỗi bảng con tự đạt BCNF\n- **B.** Mọi bảng con đều có PK\n- **C.** Giao xác định R1 hoặc R2 theo F+\n- **D.** Hai bảng có cùng số hàng\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** (R1∩R2)→R1 hoặc →R2 là điều kiện cần và đủ trong mô hình phân rã nhị phân dựa trên FD.\n\n</details>\n\n## M40 · Unspanned, B=4096, R=100, không overhead: bfr bằng bao nhiêu?\n\n- **A.** 409600\n- **B.** 100\n- **C.** 40\n- **D.** 41\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** floor(B/R)=40 record/block. Làm tròn xuống vì record không được tách.\n\n</details>\n\n## M41 · r=30000, bfr=40: số data block là bao nhiêu?\n\n- **A.** 750\n- **B.** 751\n- **C.** 1200000\n- **D.** 749\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** ceil(r/bfr)=750 block; phép chia đã nguyên.\n\n</details>\n\n## M42 · Sparse primary index điển hình có bao nhiêu entry?\n\n- **A.** Một mỗi data block\n- **B.** Một mỗi byte\n- **C.** Luôn một mỗi record\n- **D.** Một mỗi bảng\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Theo mô hình file sorted trên ordering key, một anchor đại diện mỗi data block.\n\n</details>\n\n## M43 · Hai mức index chưa cache và một data block: tổng accesses?\n\n- **A.** 4\n- **B.** 1\n- **C.** 2\n- **D.** 3\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** Số mức index là 2; cộng một lần đọc data block, tổng 3.\n\n</details>\n\n## M44 · Authentication và authorization khác gì?\n\n- **A.** Tên bảng và khóa\n- **B.** Không khác nhau\n- **C.** Danh tính và quyền truy cập\n- **D.** Mã hóa và backup\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** Đăng nhập thành công không có nghĩa được phép mọi thao tác.\n\n</details>\n\n## M45 · Bell–LaPadula tập trung bảo vệ gì?\n\n- **A.** Tốc độ query\n- **B.** Uniqueness\n- **C.** Backup duration\n- **D.** Confidentiality\n\n<details><summary>Đáp án và giải thích</summary>\n\n**D.** No read up/no write down là các quy tắc bảo mật thông tin trong mô hình này, không phải mô hình integrity tổng quát.\n\n</details>\n\n## M46 · Nguyên tắc least privilege yêu cầu gì?\n\n- **A.** Mọi user là DBA\n- **B.** Chỉ cấp quyền cần để hoàn thành công việc\n- **C.** Tắt audit\n- **D.** Chỉ dùng mật khẩu dài\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Giảm quyền hạn chế phạm vi tác động nếu tài khoản hoặc ứng dụng gặp sự cố.\n\n</details>\n\n## M47 · CAP nêu giới hạn quan trọng trong tình huống nào?\n\n- **A.** Khi có một SELECT\n- **B.** Khi network partition và vẫn đòi C cùng A theo định nghĩa\n- **C.** Chỉ khi hết RAM\n- **D.** Chỉ khi dùng SQL\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Không diễn đạt thành ba thuộc tính tùy ý chọn hai mà bỏ điều kiện partition.\n\n</details>\n\n## M48 · OLAP thường phục vụ loại công việc nào?\n\n- **A.** Chỉ thêm từng dòng đăng ký\n- **B.** Chỉ kiểm FK\n- **C.** Phân tích tổng hợp theo nhiều chiều\n- **D.** Chỉ đổi mật khẩu\n\n<details><summary>Đáp án và giải thích</summary>\n\n**C.** OLTP phục vụ giao dịch nghiệp vụ, OLAP phục vụ truy vấn phân tích; có hệ hỗn hợp.\n\n</details>\n\n## M49 · 2PC có tự đồng nghĩa với 2PL không?\n\n- **A.** Không; atomic commit khác giao thức locking\n- **B.** Chỉ khác tên\n- **C.** Cả hai là kiểu index\n- **D.** Có\n\n<details><summary>Đáp án và giải thích</summary>\n\n**A.** Two-Phase Commit phối hợp quyết định commit; Two-Phase Locking là cơ chế điều khiển đồng thời.\n\n</details>\n\n## M50 · Xóa tên và email đã đủ bảo đảm k-anonymity chưa?\n\n- **A.** Luôn đủ\n- **B.** Không; còn phải xét quasi-identifiers và nhóm tương đương\n- **C.** Có nếu đủ 10 hàng\n- **D.** Có nếu dùng NoSQL\n\n<details><summary>Đáp án và giải thích</summary>\n\n**B.** Tuổi, khu vực, nghề nghiệp kết hợp vẫn có thể nhận diện; k-anonymity có điều kiện hình thức riêng.\n\n</details>\n","file":"labs/07-mock-exam.md"}],"groups":[{"id":"c1","title":"Nền tảng & kiến trúc","file":"DB-Chapter1.md","guide":"guide-1","sourcePages":18},{"id":"c2","title":"ER · Thực thể và quan hệ","file":"DB-Chapter2.md","guide":"guide-2","sourcePages":18},{"id":"c3","title":"EER · Kế thừa và phân loại","file":"DB-Chapter3.md","guide":"guide-3","sourcePages":18},{"id":"c4","title":"Relational mapping","file":"DB-Chapter4.md","guide":"guide-4","sourcePages":17},{"id":"c5","title":"Đại số quan hệ","file":"DB-Chapter5.md","guide":"guide-5","sourcePages":18},{"id":"c6","title":"SQL từ cơ bản đến nâng cao","file":"DB-Chapter6.md","guide":"guide-6","sourcePages":20},{"id":"c7","title":"FD & Chuẩn hóa","file":"DB-Chapter7.md","guide":"guide-7","sourcePages":18},{"id":"c8","title":"Storage & Indexing","file":"DB-Chapter8.md","guide":"guide-8","sourcePages":13},{"id":"final","title":"Tổng ôn · DB-Final","file":"DB-Final.md","guide":"guide-final","sourcePages":24}],"manifest":[{"file":"DB-Chapter1.md","sha256":"9d66dcdd4e7f19b131b77c01dcdff3f196c1bdad24f034a34847ede1968ab968","lines":1504,"characters":80433},{"file":"DB-Chapter2.md","sha256":"89adefdd5f6bff6378221b644eb2df0fbdd83ca4c78788eb7463fd6f8fed3e62","lines":1535,"characters":79223},{"file":"DB-Chapter3.md","sha256":"5b595e6f9e689a46bcbb3d2be7265e3de18e64437803688ce727b059ccad9c00","lines":1487,"characters":73261},{"file":"DB-Chapter4.md","sha256":"a9c0f4c4efaa5acfe56e47033c310207f212d97c4fc354d86bcb9b9919d9ab67","lines":1604,"characters":70252},{"file":"DB-Chapter5.md","sha256":"c5d4fae0153b5a5510d379c1c4afef91406a396385f623bb83e8a082e57d451b","lines":1733,"characters":64470},{"file":"DB-Chapter6.md","sha256":"9dfb3848a0d57563ec7de8c7622fb48d29e62221d644d901c469b71ccbbfc636","lines":2477,"characters":94894},{"file":"DB-Chapter7.md","sha256":"fa020ec3b976445636d7d0f915b76b8d684908f49ce643c21128da5ef0558885","lines":1617,"characters":66479},{"file":"DB-Chapter8.md","sha256":"9a7803d67c38370fc23906e555ff6cab49d5b3b5e804fe94e8896573438f6a05","lines":1213,"characters":64501},{"file":"DB-Final.md","sha256":"b090e53edbea2cb0eb84c18b8d482e9e2eb9cdf38cdd75b7d31ed1b9a38d1543","lines":4978,"characters":240298}],"quiz":[{"id":"M01","topic":"c1","prompt":"Schema khác state ở điểm nào?","choices":["Schema là bản backup; state là chương trình","Schema thay đổi sau mỗi SELECT","Hai khái niệm đồng nghĩa","Schema mô tả cấu trúc; state là dữ liệu tại một thời điểm"],"answer":3,"explanation":"INSERT đổi state mà không bắt buộc đổi schema. CREATE/ALTER thường tác động schema."},{"id":"M02","topic":"c1","prompt":"Thêm index nhưng ứng dụng vẫn dùng nguyên SQL minh họa điều gì?","choices":["Logical independence","Physical independence","Total participation","Entity integrity"],"answer":1,"explanation":"Index là đường truy cập ở mức vật lý; interface logic có thể giữ nguyên."},{"id":"M03","topic":"c1","prompt":"Metadata là ví dụ nào?","choices":["Ảnh đại diện người dùng","Lương của John","Danh sách tên cột và kiểu dữ liệu","Một dòng đặt vé"],"answer":2,"explanation":"Metadata mô tả cấu trúc và quy tắc của dữ liệu, thường trong catalog."},{"id":"M04","topic":"c1","prompt":"Hai ứng dụng cùng ghi đè số chỗ trống gây vấn đề chính nào?","choices":["Specialization","Minimal cover","Projection","Concurrency"],"answer":3,"explanation":"Các thao tác đồng thời cần cơ chế transaction/isolation để tránh mất cập nhật hoặc vi phạm bất biến."},{"id":"M05","topic":"c1","prompt":"Ba-schema architecture là gì?","choices":["External, conceptual, internal","RAM, CPU, SSD","DDL, DML, DCL","Frontend, API, database server"],"answer":0,"explanation":"Đây là ba mức mô tả dữ liệu, không phải ba tầng triển khai ứng dụng."},{"id":"M06","topic":"c2","prompt":"Cardinality và participation lần lượt nói về điều gì?","choices":["Minimum và kiểu dữ liệu","Maximum và yêu cầu tham gia tối thiểu","Số cột và số hàng hiện tại","Tên khóa và index"],"answer":1,"explanation":"1:N/M:N không cho biết phía nào bắt buộc phải có ít nhất một liên kết."},{"id":"M07","topic":"c2","prompt":"Trong Chen, đường đôi từ ANIME tới Has_genre biểu diễn gì?","choices":["Quan hệ 1:1","Anime có đúng hai genre","ANIME total participation","GENRE là weak entity"],"answer":2,"explanation":"Mọi anime phải tham gia ít nhất một instance quan hệ; không suy ra tối đa là bao nhiêu."},{"id":"M08","topic":"c2","prompt":"AddedAt khi thêm anime vào watch list nên gắn với gì?","choices":["Contains giữa list và anime","Tên studio","ANIME","GENRE"],"answer":0,"explanation":"Giá trị phụ thuộc vào cặp list–anime, không chỉ một entity riêng lẻ."},{"id":"M09","topic":"c2","prompt":"Điều gì đặc trưng cho thực thể yếu?","choices":["Cần khóa owner cộng partial key để định danh","Bất cứ entity nào có FK","Không có thuộc tính","Luôn có ít hơn 10 hàng"],"answer":0,"explanation":"Sự phụ thuộc định danh là cốt lõi; nhiều entity mạnh cũng có FK sau mapping."},{"id":"M10","topic":"c2","prompt":"EpisodeNo chỉ duy nhất trong cùng anime. Khóa tự nhiên phù hợp là gì?","choices":["EpisodeNo","Title","AnimeID + EpisodeNo","Duration"],"answer":2,"explanation":"Hai anime có thể cùng tập số 1 nên EpisodeNo riêng không đủ định danh."},{"id":"M11","topic":"c2","prompt":"Biết nhân viên và dự án cùng thuộc một phòng có đủ xác định ai làm dự án nào?","choices":["Đủ nếu cả hai FK NOT NULL","Luôn đủ","Chỉ khi phòng có tên","Không; cần quan hệ phân công hoặc constraint tương ứng"],"answer":3,"explanation":"Cùng phòng không đồng nghĩa phân công; suy diễn qua đường nối có thể tạo fan trap."},{"id":"M12","topic":"c3","prompt":"Overlapping specialization cho phép điều gì?","choices":["Không entity nào có subclass","Subclass không kế thừa khóa","Một entity thuộc nhiều subclass trong specialization","Mọi entity phải thuộc mọi subclass"],"answer":2,"explanation":"Cho phép giao giữa các subclass; không bắt buộc giao luôn khác rỗng trong mọi state."},{"id":"M13","topic":"c3","prompt":"Total specialization tương ứng với điều kiện nào?","choices":["Hợp các subclass bằng superclass","Mọi subclass đều có ít nhất một hàng","Superclass không có khóa","Giao subclass rỗng"],"answer":0,"explanation":"Total yêu cầu bao phủ mọi entity của superclass, không yêu cầu mỗi subclass không rỗng."},{"id":"M14","topic":"c3","prompt":"Shared subclass và category khác nhau ở phép tập hợp nào?","choices":["Cả hai luôn là hợp","Shared subclass là subset của giao; category là subset của hợp","Shared subclass là hiệu","Category là tích Descartes"],"answer":1,"explanation":"Teaching assistant thuộc student và employee; owner có thể là person hoặc company."},{"id":"M15","topic":"c3","prompt":"Superclass + hai bảng subclass PK/FK mặc định có enforce total không?","choices":["Chỉ cần UNIQUE trên tên","Có, vì có FK","Có, vì subclass có PK","Không; superclass có thể chưa có hàng con"],"answer":3,"explanation":"FK đảm bảo con có cha, không đảm bảo mọi cha có ít nhất một loại con."},{"id":"M16","topic":"c4","prompt":"Mapping quan hệ 1:N thường đặt FK ở đâu?","choices":["Cả hai phía bắt buộc","Không cần FK","Phía N","Luôn phía 1"],"answer":2,"explanation":"Mỗi hàng phía N có thể giữ khóa của một owner phía 1; tránh cột lặp ở phía 1."},{"id":"M17","topic":"c4","prompt":"Mapping 1:1 bằng FK còn cần gì để chặn nhiều hàng trỏ cùng cha?","choices":["UNIQUE trên FK","ORDER BY","DEFAULT 0","SUM"],"answer":0,"explanation":"FK chỉ kiểm tra tồn tại cha; UNIQUE giới hạn tối đa một hàng tham chiếu cùng khóa cha."},{"id":"M18","topic":"c4","prompt":"M:N Produced_by nên được ánh xạ thế nào?","choices":["Một StudioID duy nhất trong ANIME","Một bảng liên kết chứa cả hai khóa","Một chuỗi chứa mọi studio trong một ô","Không thể mapping"],"answer":1,"explanation":"Bảng liên kết cho phép nhiều studio trên anime và nhiều anime trên studio."},{"id":"M19","topic":"c4","prompt":"Superkey khác candidate key thế nào?","choices":["Hai khái niệm hoàn toàn khác","Candidate key là superkey tối thiểu theo bao hàm","Superkey luôn chỉ có một thuộc tính","Candidate key được phép trùng"],"answer":1,"explanation":"Thêm thuộc tính vào candidate key vẫn tạo superkey nhưng thường không còn tối thiểu."},{"id":"M20","topic":"c4","prompt":"FK NOT NULL từ anime_genre tới anime đã đảm bảo mọi anime có genre chưa?","choices":["Chỉ cần thêm PK anime","Thêm CHECK anime_id>0 là đủ","Đã đủ","Chưa; anime có thể chưa được tham chiếu"],"answer":3,"explanation":"Constraint chỉ buộc mỗi hàng liên kết có cha; cần điều kiện tồn tại theo chiều ngược lại."},{"id":"M21","topic":"c5","prompt":"Projection trong RA cổ điển xử lý dòng trùng thế nào?","choices":["Loại tuple trùng","Nhân đôi tuple","Chỉ giữ dòng đầu theo thứ tự","Giữ mọi dòng như SQL mặc định"],"answer":0,"explanation":"RA dùng set semantics; SQL thường cần DISTINCT để có hành vi tương ứng."},{"id":"M22","topic":"c5","prompt":"Natural join chọn cột nối dựa trên gì?","choices":["FK metadata","Tên cột trùng","Cột đầu tiên mỗi bảng","Mọi cột kiểu số"],"answer":1,"explanation":"Dno và Dnumber không tự match chỉ vì chúng có quan hệ FK."},{"id":"M23","topic":"c5","prompt":"Từ “mọi / tất cả” thường gợi ý mẫu nào?","choices":["LEFT JOIN luôn đủ","Một điều kiện = duy nhất","Division hoặc không tồn tại phản ví dụ","ORDER BY"],"answer":2,"explanation":"For all x, P(x) tương đương không tồn tại x sao cho không P(x)."},{"id":"M24","topic":"c5","prompt":"Union hai quan hệ đòi hỏi gì?","choices":["Cùng primary key tên giống nhau","Cùng số index","Cùng số tuple","Union-compatible về số cột và miền tương ứng"],"answer":3,"explanation":"Hai tập phải có cấu trúc tương thích; không cần có cùng số hàng."},{"id":"M25","topic":"c6","prompt":"WHERE giữ các hàng có predicate nào?","choices":["FALSE","UNKNOWN","TRUE và UNKNOWN","TRUE"],"answer":3,"explanation":"Trong SQL ba-valued logic, WHERE chỉ giữ TRUE."},{"id":"M26","topic":"c6","prompt":"Cách kiểm tra Salary thiếu giá trị là gì?","choices":["Salary = NULL","Salary IS NULL","Salary = 0","Salary = empty"],"answer":1,"explanation":"= NULL cho UNKNOWN; IS NULL là phép kiểm tra thiếu giá trị."},{"id":"M27","topic":"c6","prompt":"COUNT(*) khác COUNT(Salary) khi có NULL thế nào?","choices":["COUNT(Salary) cộng lương","COUNT(*) bỏ NULL","COUNT(Salary) bỏ hàng có Salary NULL","Cả hai luôn bằng nhau"],"answer":2,"explanation":"COUNT(*) đếm hàng; COUNT(expression) đếm biểu thức non-NULL."},{"id":"M28","topic":"c6","prompt":"Sau LEFT JOIN, WHERE trên cột bên phải có thể gây gì?","choices":["Tự biến thành FULL JOIN","Tự enforce FK","Luôn giữ mọi hàng trái","Loại các hàng NULL-extended"],"answer":3,"explanation":"Predicate thông thường như e.Salary>40000 cho UNKNOWN ở hàng không match và hàng đó bị loại."},{"id":"M29","topic":"c6","prompt":"Lọc nhóm có COUNT>=4 nên đặt ở đâu?","choices":["HAVING COUNT(*)>=4","ORDER BY COUNT(*)>=4","PRIMARY KEY","WHERE COUNT(*)>=4"],"answer":0,"explanation":"HAVING lọc nhóm sau aggregation trong thứ tự xử lý logic."},{"id":"M30","topic":"c6","prompt":"NOT IN có NULL trong tập con có thể làm gì?","choices":["Luôn coi NULL là 0","Không cho TRUE đối với các giá trị không match còn lại","Luôn trả tất cả hàng","Tự bỏ NULL"],"answer":1,"explanation":"Với x không bằng giá trị đã biết nào, so với NULL vẫn UNKNOWN; dùng NOT EXISTS cho anti join phù hợp."},{"id":"M31","topic":"c6","prompt":"Double NOT EXISTS với tập yêu cầu rỗng trả gì trong mẫu lấy ứng viên từ EMPLOYEE?","choices":["Lỗi SQL","Không ai","Mọi ứng viên EMPLOYEE","Chỉ nhân viên có dự án"],"answer":2,"explanation":"Không tồn tại phản ví dụ trong tập rỗng: vacuous truth."},{"id":"M32","topic":"c6","prompt":"Prepared statement placeholder dùng trực tiếp để thay gì?","choices":["Giá trị tham số","Từ khóa SELECT","Tên bảng tùy ý","Tên cột tùy ý"],"answer":0,"explanation":"Parameter binding tách giá trị khỏi cú pháp. Identifier động cần whitelist/cơ chế quoting phù hợp."},{"id":"M33","topic":"c6","prompt":"View thông thường có nhất thiết lưu một bản sao vật lý kết quả không?","choices":["Không; khác materialized view","Chỉ khi có WHERE","Chỉ khi có JOIN","Có"],"answer":0,"explanation":"View thường đặt tên cho query; materialized view là khái niệm khác, tùy DBMS."},{"id":"M34","topic":"c7","prompt":"FD A→B có nghĩa gì?","choices":["A nhỏ hơn B","Hai tuple cùng A phải cùng B trong mọi state hợp lệ","B luôn là primary key","A và B cùng kiểu"],"answer":1,"explanation":"FD là ràng buộc của schema/miniworld, không chỉ một mẫu tình cờ trong dữ liệu hiện có."},{"id":"M35","topic":"c7","prompt":"R(A,B,C), F={A→B,B→C}; A+ là gì?","choices":["BC","A","AB","ABC"],"answer":3,"explanation":"Khởi tạo A; A→B thêm B; B→C thêm C; dừng khi không đổi."},{"id":"M36","topic":"c7","prompt":"R(A,B,C), F={A→B,B→A}; candidate keys là gì?","choices":["Chỉ ABC","C","A và B","AC và BC"],"answer":3,"explanation":"C không xuất hiện RHS nên bắt buộc thuộc key. AC và BC xác định toàn R, bỏ bất cứ thành phần nào đều không đủ."},{"id":"M37","topic":"c7","prompt":"Prime attribute là gì?","choices":["Nằm trong ít nhất một candidate key","Có giá trị là số nguyên tố","Nằm trong mọi candidate key","Chỉ nằm trong primary key được chọn"],"answer":0,"explanation":"Phải tìm đủ candidate keys trước khi đánh dấu prime để kiểm 3NF."},{"id":"M38","topic":"c7","prompt":"FD nontrivial X→a thỏa 3NF khi nào?","choices":["X superkey hoặc a prime","X phải candidate key đúng bằng PK","a phải nonprime","X luôn một thuộc tính"],"answer":0,"explanation":"BCNF chỉ giữ nhánh X là superkey; 3NF cho phép RHS prime."},{"id":"M39","topic":"c7","prompt":"R tách thành R1 và R2. Điều kiện lossless binary theo FD là gì?","choices":["Mỗi bảng con tự đạt BCNF","Mọi bảng con đều có PK","Giao xác định R1 hoặc R2 theo F+","Hai bảng có cùng số hàng"],"answer":2,"explanation":"(R1∩R2)→R1 hoặc →R2 là điều kiện cần và đủ trong mô hình phân rã nhị phân dựa trên FD."},{"id":"M40","topic":"c8","prompt":"Unspanned, B=4096, R=100, không overhead: bfr bằng bao nhiêu?","choices":["409600","100","40","41"],"answer":2,"explanation":"floor(B/R)=40 record/block. Làm tròn xuống vì record không được tách."},{"id":"M41","topic":"c8","prompt":"r=30000, bfr=40: số data block là bao nhiêu?","choices":["750","751","1200000","749"],"answer":0,"explanation":"ceil(r/bfr)=750 block; phép chia đã nguyên."},{"id":"M42","topic":"c8","prompt":"Sparse primary index điển hình có bao nhiêu entry?","choices":["Một mỗi data block","Một mỗi byte","Luôn một mỗi record","Một mỗi bảng"],"answer":0,"explanation":"Theo mô hình file sorted trên ordering key, một anchor đại diện mỗi data block."},{"id":"M43","topic":"c8","prompt":"Hai mức index chưa cache và một data block: tổng accesses?","choices":["4","1","2","3"],"answer":3,"explanation":"Số mức index là 2; cộng một lần đọc data block, tổng 3."},{"id":"M44","topic":"security","prompt":"Authentication và authorization khác gì?","choices":["Tên bảng và khóa","Không khác nhau","Danh tính và quyền truy cập","Mã hóa và backup"],"answer":2,"explanation":"Đăng nhập thành công không có nghĩa được phép mọi thao tác."},{"id":"M45","topic":"security","prompt":"Bell–LaPadula tập trung bảo vệ gì?","choices":["Tốc độ query","Uniqueness","Backup duration","Confidentiality"],"answer":3,"explanation":"No read up/no write down là các quy tắc bảo mật thông tin trong mô hình này, không phải mô hình integrity tổng quát."},{"id":"M46","topic":"security","prompt":"Nguyên tắc least privilege yêu cầu gì?","choices":["Mọi user là DBA","Chỉ cấp quyền cần để hoàn thành công việc","Tắt audit","Chỉ dùng mật khẩu dài"],"answer":1,"explanation":"Giảm quyền hạn chế phạm vi tác động nếu tài khoản hoặc ứng dụng gặp sự cố."},{"id":"M47","topic":"advanced","prompt":"CAP nêu giới hạn quan trọng trong tình huống nào?","choices":["Khi có một SELECT","Khi network partition và vẫn đòi C cùng A theo định nghĩa","Chỉ khi hết RAM","Chỉ khi dùng SQL"],"answer":1,"explanation":"Không diễn đạt thành ba thuộc tính tùy ý chọn hai mà bỏ điều kiện partition."},{"id":"M48","topic":"advanced","prompt":"OLAP thường phục vụ loại công việc nào?","choices":["Chỉ thêm từng dòng đăng ký","Chỉ kiểm FK","Phân tích tổng hợp theo nhiều chiều","Chỉ đổi mật khẩu"],"answer":2,"explanation":"OLTP phục vụ giao dịch nghiệp vụ, OLAP phục vụ truy vấn phân tích; có hệ hỗn hợp."},{"id":"M49","topic":"advanced","prompt":"2PC có tự đồng nghĩa với 2PL không?","choices":["Không; atomic commit khác giao thức locking","Chỉ khác tên","Cả hai là kiểu index","Có"],"answer":0,"explanation":"Two-Phase Commit phối hợp quyết định commit; Two-Phase Locking là cơ chế điều khiển đồng thời."},{"id":"M50","topic":"advanced","prompt":"Xóa tên và email đã đủ bảo đảm k-anonymity chưa?","choices":["Luôn đủ","Không; còn phải xét quasi-identifiers và nhóm tương đương","Có nếu đủ 10 hàng","Có nếu dùng NoSQL"],"answer":1,"explanation":"Tuổi, khu vực, nghề nghiệp kết hợp vẫn có thể nhận diện; k-anonymity có điều kiện hình thức riêng."}],"sql":[{"id":"Q01","title":"Tên các nhân viên thuộc Research, tăng dần theo Fname","sql":"SELECT Fname FROM EMPLOYEE WHERE Dno=5 ORDER BY Fname","expected":[["Franklin"],["John"],["Joyce"],["Ramesh"]],"explanation":"WHERE lọc hàng theo mã phòng; ORDER BY giúp kết quả đối chiếu được.","level":"Cơ bản","database":"company"},{"id":"Q02","title":"Nhân viên có lương ít nhất 40000","sql":"SELECT Fname,Salary FROM EMPLOYEE WHERE Salary>=40000 ORDER BY Fname","expected":[["Franklin",40000],["James",55000],["Jennifer",43000]],"explanation":"So sánh >= giữ cả giá trị biên. Lương NULL không làm predicate TRUE.","level":"Cơ bản","database":"company"},{"id":"Q03","title":"Nhân viên chưa biết lương","sql":"SELECT Fname FROM EMPLOYEE WHERE Salary IS NULL ORDER BY Fname","expected":[["Mai"]],"explanation":"IS NULL kiểm tra thiếu giá trị; = NULL không cho TRUE.","level":"Cơ bản","database":"company"},{"id":"Q04","title":"Mã phòng thực sự có nhân viên, không trùng","sql":"SELECT DISTINCT Dno FROM EMPLOYEE ORDER BY Dno","expected":[[1],[4],[5]],"explanation":"DISTINCT loại trùng sau projection; phòng 9 không có employee.","level":"Cơ bản","database":"company"},{"id":"Q05","title":"Hai người có lương cao nhất trong những người biết lương","sql":"SELECT Fname,Salary FROM EMPLOYEE WHERE Salary IS NOT NULL ORDER BY Salary DESC,Ssn LIMIT 2","expected":[["James",55000],["Jennifer",43000]],"explanation":"Lọc NULL trước; thêm Ssn để ổn định thứ tự khi bằng lương. LIMIT là dialect SQLite.","level":"Cơ bản","database":"company"},{"id":"Q06","title":"Tên phòng của John Smith","sql":"SELECT e.Fname,d.Dname FROM EMPLOYEE e JOIN DEPARTMENT d ON d.Dnumber=e.Dno WHERE e.Ssn='123456789'","expected":[["John","Research"]],"explanation":"Nối bằng FK/PK, không dựa vào NATURAL JOIN khi tên cột khác nhau.","level":"Cơ bản","database":"company"},{"id":"Q07","title":"Đếm nhân viên mỗi phòng, kể cả phòng rỗng","sql":"SELECT d.Dname,COUNT(e.Ssn) AS n FROM DEPARTMENT d LEFT JOIN EMPLOYEE e ON e.Dno=d.Dnumber GROUP BY d.Dnumber,d.Dname ORDER BY d.Dname","expected":[["Administration",4],["Headquarters",1],["Innovation",0],["Research",4]],"explanation":"LEFT JOIN giữ phòng rỗng; COUNT(e.Ssn) bỏ NULL do outer join tạo ra. COUNT(*) sẽ cho Innovation=1.","level":"Cơ bản","database":"company"},{"id":"Q08","title":"Phòng chưa có nhân viên","sql":"SELECT d.Dname FROM DEPARTMENT d WHERE NOT EXISTS(SELECT 1 FROM EMPLOYEE e WHERE e.Dno=d.Dnumber) ORDER BY d.Dname","expected":[["Innovation"]],"explanation":"NOT EXISTS kiểm tra không tồn tại nhân viên tương ứng.","level":"Cơ bản","database":"company"},{"id":"Q09","title":"Tên nhân viên và supervisor, giữ cả người không có supervisor","sql":"SELECT e.Fname,s.Fname AS Supervisor FROM EMPLOYEE e LEFT JOIN EMPLOYEE s ON s.Ssn=e.Super_ssn ORDER BY e.Fname","expected":[["Ahmad","Jennifer"],["Alicia","Jennifer"],["Franklin","James"],["James",null],["Jennifer","James"],["John","Franklin"],["Joyce","Franklin"],["Mai","Jennifer"],["Ramesh","Franklin"]],"explanation":"Self join dùng hai alias cho hai role của cùng entity. James được giữ nhờ LEFT JOIN.","level":"Cơ bản","database":"company"},{"id":"Q10","title":"Nhân viên không có dependent","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM DEPENDENT d WHERE d.Essn=e.Ssn) ORDER BY e.Fname","expected":[["Ahmad"],["Alicia"],["James"],["Joyce"],["Mai"],["Ramesh"]],"explanation":"Không có là không tồn tại một hàng match, không phải tồn tại một hàng không match.","level":"Cơ bản","database":"company"},{"id":"Q11","title":"Tổng giờ đã biết của từng dự án","sql":"SELECT p.Pnumber,SUM(w.Hours) AS Total FROM PROJECT p LEFT JOIN WORKS_ON w ON w.Pno=p.Pnumber GROUP BY p.Pnumber ORDER BY p.Pnumber","expected":[[1,52.5],[2,37.5],[3,50],[10,55],[20,25],[30,55]],"explanation":"SUM bỏ qua Hours NULL của James. Đây là tổng giờ đã biết, không khẳng định tổng thực tế đã đầy đủ.","level":"Cơ bản","database":"company"},{"id":"Q12","title":"Nhân viên làm ít nhất 3 dự án","sql":"SELECT e.Fname,COUNT(*) AS n FROM EMPLOYEE e JOIN WORKS_ON w ON w.Essn=e.Ssn GROUP BY e.Ssn,e.Fname HAVING COUNT(*)>=3 ORDER BY e.Fname","expected":[["Franklin",4]],"explanation":"HAVING lọc nhóm sau COUNT; PK Works_on tránh lặp cùng cặp nhân viên–dự án.","level":"Cơ bản","database":"company"},{"id":"Q13","title":"Lương từ 25000 đến 30000, gồm hai đầu mút","sql":"SELECT Fname FROM EMPLOYEE WHERE Salary BETWEEN 25000 AND 30000 ORDER BY Fname","expected":[["Ahmad"],["Alicia"],["John"],["Joyce"]],"explanation":"BETWEEN gồm cả hai đầu mút.","level":"Cơ bản","database":"company"},{"id":"Q14","title":"Tên bắt đầu bằng J","sql":"SELECT Fname FROM EMPLOYEE WHERE Fname LIKE 'J%' ORDER BY Fname","expected":[["James"],["Jennifer"],["John"],["Joyce"]],"explanation":"Phần trăm match dãy ký tự; underscore match một ký tự. Collation/case behavior phụ thuộc DBMS.","level":"Cơ bản","database":"company"},{"id":"Q15","title":"So sánh COUNT(*) và COUNT(Salary)","sql":"SELECT COUNT(*),COUNT(Salary) FROM EMPLOYEE","expected":[[9,8]],"explanation":"COUNT(*) đếm mọi hàng, COUNT(column) chỉ đếm hàng có giá trị non-NULL.","level":"Cơ bản","database":"company"},{"id":"Q16","title":"Nhân viên lương cao hơn trung bình phòng mình","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE e.Salary>(SELECT AVG(x.Salary) FROM EMPLOYEE x WHERE x.Dno=e.Dno) ORDER BY e.Fname","expected":[["Franklin"],["Jennifer"],["Ramesh"]],"explanation":"Subquery phải tương quan qua Dno; AVG bỏ NULL, không so với trung bình toàn công ty.","level":"Trung bình","database":"company"},{"id":"Q17","title":"Nhân viên làm ít nhất một dự án ở Houston","sql":"SELECT DISTINCT e.Fname FROM EMPLOYEE e JOIN WORKS_ON w ON w.Essn=e.Ssn JOIN PROJECT p ON p.Pnumber=w.Pno WHERE p.Plocation='Houston' ORDER BY e.Fname","expected":[["Franklin"],["James"],["Jennifer"],["Ramesh"]],"explanation":"DISTINCT tránh một người xuất hiện nhiều lần nếu làm nhiều dự án ở Houston.","level":"Trung bình","database":"company"},{"id":"Q18","title":"Nhân viên làm cả dự án 1 và 2","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=1) AND EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=2) ORDER BY e.Fname","expected":[["John"],["Joyce"]],"explanation":"Hai EXISTS xét hai hàng có thể khác nhau. Pno=1 AND Pno=2 trên cùng hàng không thể đúng.","level":"Trung bình","database":"company"},{"id":"Q19","title":"Nhân viên không làm bất kỳ dự án nào ở Houston","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM WORKS_ON w JOIN PROJECT p ON p.Pnumber=w.Pno WHERE w.Essn=e.Ssn AND p.Plocation='Houston') ORDER BY e.Fname","expected":[["Ahmad"],["Alicia"],["John"],["Joyce"],["Mai"]],"explanation":"Mai chưa làm dự án vẫn thỏa không có dự án ở Houston. Không thay bằng một dự án ngoài Houston.","level":"Trung bình","database":"company"},{"id":"Q20","title":"Nhân viên chưa được phân công dự án","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn) ORDER BY e.Fname","expected":[["Mai"]],"explanation":"Anti join qua NOT EXISTS cho kết quả ổn định trước NULL ở các cột không liên quan.","level":"Trung bình","database":"company"},{"id":"Q21","title":"Tìm nhân viên không quản lý ai bằng NOT IN chưa xử lý NULL","sql":"SELECT Fname FROM EMPLOYEE WHERE Ssn NOT IN (SELECT Super_ssn FROM EMPLOYEE) ORDER BY Fname","expected":[],"explanation":"Đây là query cố ý minh họa bẫy: subquery chứa NULL của James nên NOT IN không giữ hàng nào. Không dùng làm lời giải đúng nghiệp vụ.","level":"Trung bình","database":"company"},{"id":"Q22","title":"Sửa Q21 bằng NOT EXISTS","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM EMPLOYEE x WHERE x.Super_ssn=e.Ssn) ORDER BY e.Fname","expected":[["Ahmad"],["Alicia"],["John"],["Joyce"],["Mai"],["Ramesh"]],"explanation":"Loại từng người có ít nhất một cấp dưới; không bị NULL trong Super_ssn làm nhiễu.","level":"Trung bình","database":"company"},{"id":"Q23","title":"Tên người thuộc phòng 1 hoặc 5 bằng UNION","sql":"SELECT Fname FROM EMPLOYEE WHERE Dno=1 UNION SELECT Fname FROM EMPLOYEE WHERE Dno=5 ORDER BY Fname","expected":[["Franklin"],["James"],["John"],["Joyce"],["Ramesh"]],"explanation":"UNION loại dòng trùng; UNION ALL giữ bội số.","level":"Trung bình","database":"company"},{"id":"Q24","title":"Mã nhân viên làm cả dự án 1 và 2 bằng INTERSECT","sql":"SELECT Essn FROM WORKS_ON WHERE Pno=1 INTERSECT SELECT Essn FROM WORKS_ON WHERE Pno=2 ORDER BY Essn","expected":[["123456789"],["453453453"]],"explanation":"INTERSECT lấy giao hai tập có cùng cấu trúc.","level":"Trung bình","database":"company"},{"id":"Q25","title":"Nhân viên làm mọi dự án trong tập {1,2}","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM PROJECT p WHERE p.Pnumber IN (1,2) AND NOT EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=p.Pnumber)) ORDER BY e.Fname","expected":[["John"],["Joyce"]],"explanation":"Không tồn tại dự án yêu cầu mà nhân viên chưa làm. Đây là mẫu for all.","level":"Nâng cao","database":"company"},{"id":"Q26","title":"Mẫu for all khi tập dự án yêu cầu rỗng","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE NOT EXISTS(SELECT 1 FROM PROJECT p WHERE p.Dnum=9 AND NOT EXISTS(SELECT 1 FROM WORKS_ON w WHERE w.Essn=e.Ssn AND w.Pno=p.Pnumber)) ORDER BY e.Fname","expected":[["Ahmad"],["Alicia"],["Franklin"],["James"],["Jennifer"],["John"],["Joyce"],["Mai"],["Ramesh"]],"explanation":"Tập yêu cầu rỗng không có phản ví dụ; mọi ứng viên EMPLOYEE đều thỏa.","level":"Nâng cao","database":"company"},{"id":"Q27","title":"Mỗi phòng và nhân viên có lương >40000; giữ phòng không match","sql":"SELECT d.Dname,e.Fname FROM DEPARTMENT d LEFT JOIN EMPLOYEE e ON e.Dno=d.Dnumber AND e.Salary>40000 ORDER BY d.Dname,e.Fname","expected":[["Administration","Jennifer"],["Headquarters","James"],["Innovation",null],["Research",null]],"explanation":"Điều kiện trong ON quyết định cặp match nhưng vẫn giữ mọi phòng.","level":"Trung bình","database":"company"},{"id":"Q28","title":"So sánh Q27 khi điều kiện lương chuyển xuống WHERE","sql":"SELECT d.Dname,e.Fname FROM DEPARTMENT d LEFT JOIN EMPLOYEE e ON e.Dno=d.Dnumber WHERE e.Salary>40000 ORDER BY d.Dname,e.Fname","expected":[["Administration","Jennifer"],["Headquarters","James"]],"explanation":"WHERE lọc các hàng NULL-extended; query này chỉ phù hợp nếu muốn bỏ phòng không match.","level":"Trung bình","database":"company"},{"id":"Q29","title":"Phòng có ít nhất 4 nhân viên, bằng HAVING","sql":"SELECT Dno,COUNT(*) FROM EMPLOYEE GROUP BY Dno HAVING COUNT(*)>=4 ORDER BY Dno","expected":[[4,4],[5,4]],"explanation":"WHERE không thể lọc trực tiếp COUNT của nhóm trước khi nhóm được tạo.","level":"Trung bình","database":"company"},{"id":"Q30","title":"Dự án có ít nhất hai người tham gia","sql":"SELECT Pno,COUNT(*) FROM WORKS_ON GROUP BY Pno HAVING COUNT(*)>=2 ORDER BY Pno","expected":[[1,2],[2,3],[3,2],[10,3],[20,3],[30,3]],"explanation":"Đếm hàng phân công, kể cả hàng Hours NULL; đó là người tham gia chứ không phải số giờ.","level":"Trung bình","database":"company"},{"id":"Q31","title":"Nhân viên có lương cao nhất trong từng phòng, giữ đồng hạng","sql":"SELECT e.Fname FROM EMPLOYEE e WHERE e.Salary=(SELECT MAX(x.Salary) FROM EMPLOYEE x WHERE x.Dno=e.Dno) ORDER BY e.Fname","expected":[["Franklin"],["James"],["Jennifer"]],"explanation":"MAX bỏ NULL. So sánh bằng MAX giữ mọi hàng đồng hạng nếu dữ liệu có tie.","level":"Nâng cao","database":"company"},{"id":"Q32","title":"Phân loại lương: Unknown / High (>=40000) / Other","sql":"SELECT CASE WHEN Salary IS NULL THEN 'Unknown' WHEN Salary>=40000 THEN 'High' ELSE 'Other' END AS Band,COUNT(*) FROM EMPLOYEE GROUP BY CASE WHEN Salary IS NULL THEN 'Unknown' WHEN Salary>=40000 THEN 'High' ELSE 'Other' END ORDER BY Band","expected":[["High",3],["Other",5],["Unknown",1]],"explanation":"CASE kiểm tra NULL riêng trước khi phân nhóm; không coi Unknown là Other.","level":"Trung bình","database":"company"},{"id":"Q33","title":"Dense rank lương ở phòng 5, phần mở rộng window function","sql":"SELECT Fname,DENSE_RANK() OVER(ORDER BY Salary DESC) AS SalaryRank FROM EMPLOYEE WHERE Dno=5 ORDER BY SalaryRank,Fname","expected":[["Franklin",1],["Ramesh",2],["John",3],["Joyce",4]],"explanation":"Window không gom mất từng hàng như GROUP BY; DENSE_RANK không để khoảng trống khi có tie.","level":"Nâng cao","database":"company"},{"id":"Q34","title":"Lương và trung bình phòng bằng window, không làm mất hàng","sql":"SELECT Fname,AVG(Salary) OVER(PARTITION BY Dno) AS DeptAverage FROM EMPLOYEE WHERE Dno=5 ORDER BY Fname","expected":[["Franklin",33250],["John",33250],["Joyce",33250],["Ramesh",33250]],"explanation":"PARTITION BY chia cửa sổ; WHERE Dno=5 vẫn giữ trọn phòng 5 trong ví dụ này.","level":"Nâng cao","database":"company"},{"id":"Q35","title":"CTE tính tổng giờ đã biết rồi lọc >=40","sql":"WITH T AS(SELECT Essn,SUM(Hours) AS h FROM WORKS_ON GROUP BY Essn) SELECT e.Fname,T.h FROM EMPLOYEE e JOIN T ON T.Essn=e.Ssn WHERE T.h>=40 ORDER BY e.Fname","expected":[["Ahmad",40],["Alicia",40],["Franklin",40],["John",40],["Joyce",40],["Ramesh",40]],"explanation":"CTE đặt tên cho bước trung gian; không khẳng định nó luôn được materialize.","level":"Nâng cao","database":"company"},{"id":"Q36","title":"Nhân viên có trên 2 dependent","sql":"SELECT e.Fname,COUNT(*) FROM EMPLOYEE e JOIN DEPENDENT d ON d.Essn=e.Ssn GROUP BY e.Ssn,e.Fname HAVING COUNT(*)>2 ORDER BY e.Fname","expected":[["Franklin",3],["John",3]],"explanation":"Join trước và GROUP BY đúng khóa nhân viên; không gộp những người trùng tên.","level":"Trung bình","database":"company"},{"id":"Q37","title":"Bộ tên/địa điểm dự án của phòng 5","sql":"SELECT Pname,Plocation FROM PROJECT WHERE Dnum=5 ORDER BY Pnumber","expected":[["ProductX","Bellaire"],["ProductY","Sugarland"],["ProductZ","Houston"]],"explanation":"Projection chọn hai cột, selection lọc phòng. SQL ORDER BY có thể dùng cột không nằm SELECT trong dạng này.","level":"Cơ bản","database":"company"},{"id":"Q38","title":"Bình quân lương đã biết toàn công ty","sql":"SELECT ROUND(AVG(Salary),2) FROM EMPLOYEE","expected":[[35125]],"explanation":"Tổng lương 281000 chia 8 giá trị đã biết, không chia 9.","level":"Cơ bản","database":"company"},{"id":"Q39","title":"Danh sách SSN không có WORKS_ON bằng EXCEPT","sql":"SELECT Ssn FROM EMPLOYEE EXCEPT SELECT Essn FROM WORKS_ON ORDER BY Ssn","expected":[["111222333"]],"explanation":"EXCEPT biểu diễn hiệu hai tập cùng một cột SSN.","level":"Trung bình","database":"company"},{"id":"Q40","title":"Tổng số phòng và số phòng có manager","sql":"SELECT COUNT(*),COUNT(Mgr_ssn) FROM DEPARTMENT","expected":[[4,3]],"explanation":"COUNT(column) bỏ NULL; Innovation có manager chưa được gán. Đây là giả thiết fixture, không phải yêu cầu COMPANY chính thức.","level":"Cơ bản","database":"company"}]};
